INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f06bc99b-95e6-52c2-8db1-65f26dade4ef', 'free-exercise-db', '3_4_Sit-Up', '3/4 Mekik', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Yere uzanın ve ayaklarınızı sabitleyin. Dizleriniz bükülü olmalıdır.", "Ellerinizi başınızın arkasına veya yanlarına koyun. Sırtınız yerde başlayacaksınız. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi dizlerinize doğru kaldırmak için kalça ve omurganızı bükün.", "Kasılmanın en üst noktasında gövdeniz yere dik olmalıdır. Hareketi tersine çevirin ve yalnızca ¾ oranında aşağı inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["3_4_Sit-Up/0.jpg", "3_4_Sit-Up/1.jpg"]', 360.0, '3/4 Sit-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8743987b-b678-5f47-a262-cf4298901599', 'free-exercise-db', '90_90_Hamstring', '90/90 Arka Bacak Esnetme', 'push', 'beginner', NULL, '["body only"]', '["hamstrings"]', '["calves"]', '["Sırtüstü uzanın ve bir bacağınızı düz bir şekilde uzatın.", "Diğer bacağınızın kalça ve dizini 90 dereceye bükün. Gerekirse bacağınızı elleriniz ile destekleyebilirsiniz. Bu sizin başlangıç pozisyonunuz olacaktır.", "Bacağınızı düz bir şekilde havaya doğru uzatın ve üst noktada kısa bir süre bekleyin. Bacağı başlangıç pozisyonuna geri indirin.", "10-20 tekrar yapın, ardından diğer bacağa geçin."]', 'stretching', '["90_90_Hamstring/0.jpg", "90_90_Hamstring/1.jpg"]', 150.0, '90/90 Hamstring', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('314d21cb-aaa9-585f-a0a7-7d75f7fc8a55', 'free-exercise-db', 'Ab_Crunch_Machine', 'Karın Crunch (Makine)', 'pull', 'intermediate', 'isolation', '["machine"]', '["abdominals"]', '[]', '["Hafif bir direnç seçin ve karın makinesine oturun; ayaklarınızı sağlanan pedlerin altına yerleştirin ve üstteki tutamaklara tutunun. Pedlere triceps''inizi dayarken kollarınız 90 derecelik açıyla bükülü olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Aynı anda üst gövdenizi crunch yaparken bacaklarınızı da yukarı kaldırmaya başlayın. Bu hareketi yaparken nefes verin. İpucu: Yavaş ve kontrollü bir hareket kullandığınızdan emin olun. Bacaklarınızı ve ayaklarınızı gevşek tutarken ağırlığı hareket ettirmek için karın kaslarınıza odaklanın.", "Bir saniye bekledikten sonra nefes alarak yavaşça başlangıç pozisyonuna dönün.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Ab_Crunch_Machine/0.jpg", "Ab_Crunch_Machine/1.jpg"]', 360.0, 'Ab Crunch Machine', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c6cb1665-b948-5cce-99ac-4b23ddbeef66', 'free-exercise-db', 'Ab_Roller', 'Ab Roller', 'pull', 'intermediate', 'compound', '["other"]', '["abdominals"]', '["shoulders"]', '["Ab Roller''ı iki elinizle tutun ve yerde diz çökün.", "Şimdi ab roller''ı önünüzde yere koyun; böylece dört ayak (diz çökmüş şınav pozisyonu gibi) pozisyonunda olun. Bu sizin başlangıç pozisyonunuz olacak.", "Ab roller''ı yavaşça düz bir şekilde öne doğru yuvarlayın ve vücudunuzu düz bir pozisyona gelecek şekilde uzatın. İpucu: Vücudunuzla yere değmeden gidebildiğiniz kadar aşağı inin. Hareketin bu kısmında nefes alın.", "Gerilmiş pozisyonda kısa bir duraklamanın ardından, nefes verirken kendinizi başlangıç pozisyonuna geri çekin. İpucu: Yavaş hareket edin ve karın kaslarınızı her zaman sıkı tutun."]', 'strength', '["Ab_Roller/0.jpg", "Ab_Roller/1.jpg"]', 360.0, 'Ab Roller', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('10f35a17-060c-5d45-8eb5-a21e097ea861', 'free-exercise-db', 'Adductor', 'İç Bacak Foam Roll', 'static', 'intermediate', 'isolation', '["foam roll"]', '["adductors"]', '[]', '["Yüzüstü uzanın ve bir bacağınızı foam roller''ın üzerine yerleştirin.", "Bacağınızı, foam roller iç bacağınıza temas edecek şekilde çevirin. Vücut ağırlığınızı tolere edebildiğiniz kadar foam roller''a aktarın.", "İç bacak kaslarınızı gevşetmeye çalışırken kalçanız ile diziniz arasında foam roller''ın üzerinde ilerleyin ve gerginlik hissettiğiniz noktalarda 10-30 saniye bekleyin. Diğer bacakla tekrarlayın."]', 'stretching', '["Adductor/0.jpg", "Adductor/1.jpg"]', 150.0, 'Adductor', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0e7eab35-e35b-51a3-8036-8324ce1d48ca', 'free-exercise-db', 'Adductor_Groin', 'İç Bacak Esnetme (Partnerli)', 'static', 'intermediate', NULL, '[]', '["adductors"]', '[]', '["Sırtüstü uzanın ve ayaklarınızı tavana doğru kaldırın.", "Partnerinizden ayaklarınızı veya bileklerinizi tutmasını isteyin. Bacaklarınızı yapabildiğiniz kadar açın. Bu sizin başlangıç pozisyonunuzdur.", "Partneriniz buna engel olurken bacaklarınızı 10 saniye veya daha uzun süre birbirine doğru sıkmaya çalışın.", "Şimdi partneriniz ayaklarınızı birbirinden iterken bacaklarınızdaki kasları gevşetin ve rahat edebildiğiniz kadar esneyin. Aşırı esnemeyi ve sakatlanmayı önlemek için esneme yeterli olduğunda partnerinize haber verdiğinizden emin olun."]', 'stretching', '["Adductor_Groin/0.jpg", "Adductor_Groin/1.jpg"]', 150.0, 'Adductor/Groin', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b7901b34-fe6a-5bf2-851a-d6633c46bfbe', 'free-exercise-db', 'Advanced_Kettlebell_Windmill', 'Windmill (Kettlebell, İleri Seviye)', 'push', 'intermediate', 'isolation', '["kettlebells"]', '["abdominals"]', '["glutes", "hamstrings", "shoulders"]', '["Bir kettlebell''i tek kolla omuz hizasına çekin (clean) ve başınızın üzerine itin.", "Kettlebell''i her zaman kilitli tutarak kalçanızı kettlebell''in olduğu yöne doğru dışarı itin. Çalışmayan kolunuzu sırtınızın arkasında tutun ve ayaklarınızı kettlebell''li koldan kırk beş derecelik açıyla dışarı çevirin.", "Kendinizi mümkün olduğunca aşağı indirin.", "Bir saniye bekleyin ve hareketi tersine çevirerek başlangıç pozisyonuna dönün."]', 'strength', '["Advanced_Kettlebell_Windmill/0.jpg", "Advanced_Kettlebell_Windmill/1.jpg"]', 360.0, 'Advanced Kettlebell Windmill', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a6a44251-d19b-55f6-89a3-6b31aeeeac48', 'free-exercise-db', 'Air_Bike', 'Air Bike (Bisiklet Mekiği)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Yere sırtüstü uzanın ve belinizi yere bastırın. Bu egzersiz için ellerinizi başınızın yanına koymanız gerekir. Boynunuzu zorlamamaya dikkat edin. Şimdi omuzlarınızı mekik pozisyonuna kaldırın.", "Dizlerinizi, alt bacaklarınız yere paralel olacak şekilde, zemine dik olacakları noktaya kadar yukarı çekin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi aynı anda ve yavaşça pedal çevirme hareketi yapın: sağ bacağınızı öne doğru uzatırken sol dizinizi içeri çekin. Nefes verirken yana doğru mekik çekerek sağ dirseğinizi sol dizinize yaklaştırın.", "Nefes alırken başlangıç pozisyonuna dönün.", "Bacaklarınızla pedal çevirmeye devam ederek karşı tarafa mekik çekin, sol dirseğinizi sağ dizinize yaklaştırın ve nefes verin.", "Her iki taraf için önerilen tüm tekrarları tamamlayana kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Air_Bike/0.jpg", "Air_Bike/1.jpg"]', 360.0, 'Air Bike', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c7b2b3c6-8711-5dea-8934-889d1bf18dce', 'free-exercise-db', 'All_Fours_Quad_Stretch', 'Dört Ayak Üzerinde Ön Bacak Esnetme', 'static', 'intermediate', NULL, '["body only"]', '["quadriceps"]', '["quadriceps"]', '["Eller ve dizler üzerinde başlayın, ardından bir bacağınızı yerden kaldırın ve ayağınızı elinizle tutun.", "Ayağınızı veya bileğinizi elinizle tutun, dizinizi tamamen bükülü tutarak ön bacak (quadriceps) ve kalça bükücü kaslarını esnetin.", "Kalçanızı yere doğru iterek kalçanızı öne açmaya odaklanın. 10-20 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["All_Fours_Quad_Stretch/0.jpg", "All_Fours_Quad_Stretch/1.jpg"]', 150.0, 'All Fours Quad Stretch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bff1330d-6868-5de0-a9b0-86816927de83', 'free-exercise-db', 'Alternate_Hammer_Curl', 'Hammer Curl (Dambıl, Dönüşümlü)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Gövdeniz dik şekilde ayakta durun ve her elinizde kollarınız aşağı sarkacak şekilde birer dambıl tutun. Dirsekleriniz gövdenize yakın olmalıdır.", "Avuç içleriniz gövdenize bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolunuzu sabit tutarken nefes verip biceps''i kasarak sağ dambılı öne doğru kaldırın. Biceps tamamen kasılana ve dambıl omuz hizasına gelene kadar hareketi sürdürün. Biceps''i sıkarak kasılmış pozisyonda bir saniye bekleyin. İpucu: Yalnızca ön kollar hareket etmelidir.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna geri getirin.", "Hareketi sol elinizle tekrarlayın. Bu bir tekrar sayılır.", "Önerilen tekrar sayısı boyunca bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Alternate_Hammer_Curl/0.jpg", "Alternate_Hammer_Curl/1.jpg"]', 360.0, 'Alternate Hammer Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d196f1a0-37eb-59d1-bb06-47b8f937efd6', 'free-exercise-db', 'Alternate_Heel_Touchers', 'Sırayla Topuğa Dokunma', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Dizleriniz bükülü ve ayaklarınız yerde yaklaşık 45-60 cm aralıkta olacak şekilde yere uzanın. Kollarınız yanlarınızda uzanmış olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Gövdenizi yaklaşık 7-10 cm kadar ileri ve yukarı, sağ tarafa doğru kıvırın ve sağ topuğunuza dokunarak kasılmayı bir saniye tutun. Bu hareketi yaparken nefes verin.", "Şimdi nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Şimdi gövdenizi yaklaşık 7-10 cm kadar ileri ve yukarı, sol tarafa doğru kıvırın ve sol topuğunuza dokunarak kasılmayı bir saniye tutun. Bu hareketi yaparken nefes verin, ardından nefes alarak başlangıç pozisyonuna dönün. Her iki topuğa da dokunmak 1 tekrar sayılır.", "Belirlenen tüm tekrarlar tamamlanana kadar tarafları değiştirerek devam edin."]', 'strength', '["Alternate_Heel_Touchers/0.jpg", "Alternate_Heel_Touchers/1.jpg"]', 360.0, 'Alternate Heel Touchers', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a484c78e-395d-5129-8407-2cb3b61a8c39', 'free-exercise-db', 'Alternate_Incline_Dumbbell_Curl', 'Dönüşümlü Incline Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Her elinizde kollarınız uzanmış şekilde birer dambıl tutarak eğimli bir sehpaya oturun. İpucu: Dirsekleri gövdenize yakın tutun. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolunuzu sabit tutarken nefes verip biceps''inizi kasarak sağ dambılı öne doğru kaldırın. Bunu yaparken avuç içi yukarı bakacak şekilde elinizi döndürün. Biceps''iniz tamamen kasılana ve dambıllar omuz seviyesine gelene kadar hareketi sürdürün. Biceps''inizi sıkarak kasılmış pozisyonda bir saniye bekleyin. İpucu: Yalnızca ön kollar hareket etmelidir.", "Nefes alarak dambılı yavaşça başlangıç pozisyonuna indirin.", "Hareketi sol elinizle tekrarlayın. Bu bir tekrar sayılır.", "Önerilen tekrar sayısı kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Alternate_Incline_Dumbbell_Curl/0.jpg", "Alternate_Incline_Dumbbell_Curl/1.jpg"]', 360.0, 'Alternate Incline Dumbbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('baaa2c22-d513-52e7-af11-c2e40f668bb9', 'free-exercise-db', 'Alternate_Leg_Diagonal_Bound', 'Çapraz Sıçrama (Alternatif Bacak)', 'push', 'beginner', 'compound', '[]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Bir ayağınız diğerinin biraz önünde olacak şekilde rahat bir duruş alın.", "Ön bacağınızla yerden iterek başlayın, karşı dizinizi inmeden önce mümkün olduğunca ileri ve yukarı sürün. Her sıçramada iki yana doğru mümkün olduğunca fazla mesafe kat etmeye çalışın.", "Yandan yana mesafeyi ölçmek için yerde bir çizgi kullanmak işinize yarayabilir.", "Aynı hareketi diğer bacakla tekrarlayın."]', 'plyometrics', '["Alternate_Leg_Diagonal_Bound/0.jpg", "Alternate_Leg_Diagonal_Bound/1.jpg"]', 480.0, 'Alternate Leg Diagonal Bound', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2a87bb92-ec59-50f6-a0da-0c170dcb28ba', 'free-exercise-db', 'Alternating_Cable_Shoulder_Press', 'Dönüşümlü Omuz Press (Kablo)', 'push', 'beginner', 'compound', '["cable"]', '["shoulders"]', '["triceps"]', '["Kabloları kulenin en altına alın ve uygun bir ağırlık seçin.", "Kabloları kavrayın ve avuç içleriniz öne bakacak şekilde omuz hizasında tutun. Bu sizin başlangıç pozisyonunuzdur.", "Başınızı ve göğsünüzü dik tutarak dirseğinizi açın ve bir tarafı doğrudan başınızın üzerine itin.", "Üstte kısa bir süre bekledikten sonra başlangıç pozisyonuna dönün ve karşı tarafla tekrarlayın."]', 'strength', '["Alternating_Cable_Shoulder_Press/0.jpg", "Alternating_Cable_Shoulder_Press/1.jpg"]', 360.0, 'Alternating Cable Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1f3abdc7-c036-5c49-9436-ec8e27d97da0', 'free-exercise-db', 'Alternating_Deltoid_Raise', 'Alternatif Omuz Raise (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Ayakta dururken yanlarınızda birer dambıl tutun.", "Dirseklerinizi hafifçe bükülü tutarak ağırlıkları sallanma veya hile yapmadan doğrudan önünüzde omuz hizasına kadar kaldırın.", "Ağırlıkları yanlarınıza indirin.", "Bir sonraki tekrarda ağırlıkları yanlara doğru, yaklaşık omuz hizasına kadar kaldırın.", "Ağırlıkları başlangıç pozisyonuna indirin ve öne ve yana doğru dönüşümlü olarak devam edin."]', 'strength', '["Alternating_Deltoid_Raise/0.jpg", "Alternating_Deltoid_Raise/1.jpg"]', 360.0, 'Alternating Deltoid Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b0d78972-16c0-5ea1-8365-9237463890f3', 'free-exercise-db', 'Alternating_Floor_Press', 'Dönüşümlü Floor Press (Kettlebell)', 'push', 'beginner', 'compound', '["kettlebells"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Yere uzanın ve iki kettlebell''i omuzlarınızın yanına koyun.", "Önce birini, sonra diğerini göğsünüzün üzerine yerleştirin; kettlebell''leri sapından, avuç içleriniz öne bakacak şekilde kavrayın.", "Her iki kolunuzu uzatın, böylece kettlebell''ler göğsünüzün üzerinde tutulsun. Bir kettlebell''i göğsünüze indirin ve bileğinizi kilitli olan kettlebell yönüne çevirin.", "Kettlebell''i kaldırın ve karşı tarafla tekrarlayın."]', 'strength', '["Alternating_Floor_Press/0.jpg", "Alternating_Floor_Press/1.jpg"]', 360.0, 'Alternating Floor Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('56d51a81-bf8b-53de-99c8-c31c04dc2fb9', 'free-exercise-db', 'Alternating_Hang_Clean', 'Alternating Hang Clean (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["biceps", "calves", "forearms", "glutes", "lower back", "traps"]', '["İki kettlebell''i ayaklarınızın arasına yerleştirin. Başlangıç pozisyonunu almak için kalçanızı geriye doğru itin ve düz ileriye bakın.", "Bir kettlebell''i omzunuza clean yapın ve diğer kettlebell''i sarkık pozisyonda tutmaya devam edin. Kettlebell''i omzunuza doğru çekerken bacaklarınızı ve kalçanızı açarak clean hareketini yapın. Bunu yaparken bileğinizi döndürün.", "Omuzdaki kettlebell''i sarkık pozisyona indirin ve diğer kettlebell''i clean yapın. Tekrarlayın."]', 'strength', '["Alternating_Hang_Clean/0.jpg", "Alternating_Hang_Clean/1.jpg"]', 360.0, 'Alternating Hang Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('137b8bc7-a5ab-591c-a2ab-62bcd8d491a2', 'free-exercise-db', 'Alternating_Kettlebell_Press', 'Kettlebell Press (Dönüşümlü)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["triceps"]', '["İki kettlebell''i omuzlarınıza çekin (clean). Bacaklarınızı ve kalçanızı açarak kettlebell''leri omuzlarınıza doğru çekin. Bunu yaparken bileklerinizi döndürün.", "Diğer kettlebell''i sabit tutarken birini dirseğinizi açarak tam tepenize doğru itin ve avuç içi öne bakacak şekilde çevirin.", "İtilen kettlebell''i başlangıç pozisyonuna indirin ve hemen diğer kolunuzla itin."]', 'strength', '["Alternating_Kettlebell_Press/0.jpg", "Alternating_Kettlebell_Press/1.jpg"]', 360.0, 'Alternating Kettlebell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e5b52ac6-82d1-59a7-89e1-39a865118806', 'free-exercise-db', 'Alternating_Kettlebell_Row', 'Sırayla Row (Kettlebell)', 'pull', 'intermediate', 'isolation', '["kettlebells"]', '["middle back"]', '["biceps", "lats"]', '["İki kettlebell''i ayaklarınızın önüne koyun. Dizlerinizi hafifçe bükün ve kalçanızı mümkün olduğunca geriye itin. Başlangıç pozisyonuna eğilirken iki kettlebell''i de saplarından kavrayın.", "Diğer kettlebell''i tutmaya devam ederken bir kettlebell''i yerden kaldırın. Dirseğinizi bükerken çalışan taraftaki kürek kemiğinizi geriye çekin ve kettlebell''i karnınıza veya kaburgalarınıza doğru çekin.", "Çalışan koldaki kettlebell''i indirin ve diğer kolunuzla tekrarlayın."]', 'strength', '["Alternating_Kettlebell_Row/0.jpg", "Alternating_Kettlebell_Row/1.jpg"]', 360.0, 'Alternating Kettlebell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e0fc06d2-6746-5fb8-8a68-7f706615374b', 'free-exercise-db', 'Alternating_Renegade_Row', 'Dönüşümlü Renegade Row (Kettlebell)', 'pull', 'expert', 'compound', '["kettlebells"]', '["middle back"]', '["abdominals", "biceps", "chest", "lats", "triceps"]', '["Yerde omuz genişliği kadar aralıkla iki kettlebell yerleştirin. Şınav pozisyonundaymış gibi ayak parmaklarınızın ve ellerinizin üzerine konumlanın; vücudunuz düz ve uzamış olsun. Üst vücudunuzu desteklemek için kettlebell''lerin saplarını kullanın. Destek için ayaklarınızı geniş açmanız gerekebilir.", "Bir kettlebell''i yere doğru bastırın, diğerini ise çalışan taraftaki kürek kemiğini geriye çekerek ve dirseğinizi bükerek yan tarafınıza doğru çekin.", "Ardından kettlebell''i yere indirin ve karşı eldeki kettlebell ile aynı hareketi yapın. Birkaç tekrar boyunca devam edin."]', 'strength', '["Alternating_Renegade_Row/0.jpg", "Alternating_Renegade_Row/1.jpg"]', 360.0, 'Alternating Renegade Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('893707aa-3804-541c-9fbf-5c0a3082da4a', 'free-exercise-db', 'Ankle_Circles', 'Ayak Bileği Daireleri', 'pull', 'beginner', 'isolation', '[]', '["calves"]', '[]', '["Kendinizi dengede tutmak için squat rafı gibi sağlam bir nesneden tutunun.", "Sağ bacağınızı havaya kaldırın (yerden yaklaşık 5 cm) ve başparmağınızla dairesel bir hareket yapın. Büyük bir daire çiziyormuşsunuz gibi hayal edin. İpucu: Bir daire 1 tekrar sayılır. Hareketi yaparken normal nefes alın.", "Sağ ayakla işiniz bittiğinde sol bacakla tekrarlayın."]', 'stretching', '["Ankle_Circles/0.jpg", "Ankle_Circles/1.jpg"]', 150.0, 'Ankle Circles', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('44a926ca-352f-5ac3-b634-a5350574671d', 'free-exercise-db', 'Ankle_On_The_Knee', 'Ayak Bileği Dizde Esnetme', 'static', 'beginner', NULL, '[]', '["glutes"]', '[]', '["Sırtüstü yatar pozisyondan dizlerinizi bükün ve ayaklarınızı yerde tutun.", "Bir ayağınızın bileğini karşı dizinizin üzerine koyun.", "Alttaki bacağın uyluğunu veya dizini kavrayın ve her iki bacağınızı göğsünüze doğru çekin. Boyun ve omuzlarınızı gevşetin. 10-20 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["Ankle_On_The_Knee/0.jpg", "Ankle_On_The_Knee/1.jpg"]', 150.0, 'Ankle On The Knee', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ae706704-539b-5671-a4a1-c8c10185d76d', 'free-exercise-db', 'Anterior_Tibialis-SMR', 'Ön Kaval Kası Foam Roller (SMR)', 'static', 'intermediate', NULL, '["other"]', '["calves"]', '[]', '["Dizleriniz bükülü ve ayaklarınız yerde olacak şekilde yerde oturarak başlayın.", "Bir kas rulosu veya oklava kullanarak kaval kemiğinizin dış tarafındaki kaslara baskı uygulayın. Dizin hemen altından ayak bileğinin üstüne kadar ilerleyin ve gerginlik hissettiğiniz noktalarda 10-30 saniye bekleyin. Diğer bacakta tekrarlayın."]', 'stretching', '["Anterior_Tibialis-SMR/0.jpg", "Anterior_Tibialis-SMR/1.jpg"]', 150.0, 'Anterior Tibialis-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5ca13ac1-8220-5e5c-b61f-bfe05dee0048', 'free-exercise-db', 'Anti-Gravity_Press', 'Anti-Gravity Press (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["shoulders"]', '["middle back", "traps", "triceps"]', '["Bir barı incline bench''in baş tarafının arkasında yere yerleştirin.", "Bench''e yüzüstü uzanın. Pronasyon tutuşla (avuç içleri aşağı bakacak şekilde) halteri yerden alın. Dirseklerinizi bükerek ters curl yapın ve barı göğsünüze yaklaştırın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başlamak için dirseklerinizi açarak halteri başınızın önüne doğru itin. Hareket boyunca kollarınızı yere paralel tutun.", "Başlangıç pozisyonuna dönün ve seti tamamlamak için tekrarlayın."]', 'strength', '["Anti-Gravity_Press/0.jpg", "Anti-Gravity_Press/1.jpg"]', 360.0, 'Anti-Gravity Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d7aeb226-ef9e-5e5e-bed1-817097066ee4', 'free-exercise-db', 'Arm_Circles', 'Kol Çevirme', 'push', 'beginner', 'isolation', '[]', '["shoulders"]', '["traps"]', '["Ayağa kalkın ve kollarınızı yanlara doğru düz bir şekilde uzatın. Kollarınız yere paralel ve gövdenize dik (90 derece açıda) olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Uzattığınız her kolla yaklaşık 30 cm çapında daireler çizmeye yavaşça başlayın. Hareketi yaparken normal nefes alın.", "Uzanmış kollarla dairesel hareketi yaklaşık on saniye boyunca sürdürün. Ardından hareketi ters yöne çevirin."]', 'stretching', '["Arm_Circles/0.jpg", "Arm_Circles/1.jpg"]', 150.0, 'Arm Circles', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a1c7441f-8685-5513-97e7-c1dc178c0d1d', 'free-exercise-db', 'Arnold_Dumbbell_Press', 'Arnold Press (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Sırt desteği olan bir bankta oturun ve iki dambılı avuç içleriniz vücudunuza bakacak ve dirsekleriniz bükülü şekilde üst göğüs hizasında önünüzde tutun. İpucu: Kollarınız gövdenizin yanında olmalıdır. Başlangıç pozisyonu, dambıl curl hareketinin kasılmış kısmına benzemelidir.", "Harekete başlamak için dambılları kaldırırken avuç içlerinizi öne bakana kadar döndürün.", "Kollarınız başınızın üzerinde düz şekilde uzanana kadar dambılları kaldırmaya devam edin. Hareketin bu kısmında nefes verin.", "Üstte bir saniye bekledikten sonra avuç içlerinizi size doğru döndürerek dambılları başlangıç pozisyonuna indirmeye başlayın. İpucu: Sol kol saat yönünün tersine, sağ kol ise saat yönünde dönecektir. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Arnold_Dumbbell_Press/0.jpg", "Arnold_Dumbbell_Press/1.jpg"]', 360.0, 'Arnold Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f1abeaea-f0bb-5997-8e6f-5d53702a99ec', 'free-exercise-db', 'Around_The_Worlds', 'Around the World (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["chest"]', '["shoulders"]', '["Düz bir bench üzerine sırtüstü uzanın ve avuç içleriniz tavana bakacak şekilde her elinizde bir dambıl tutun. İpucu: Kollarınız yere paralel ve uyluklarınızın yanında olmalıdır. Sakatlanmamak için dirseklerinizi hafifçe bükülü tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi dambılları başlangıç pozisyonundan başınızın üzerine doğru yarım daire çizerek hareket ettirin. Hareket boyunca kollarınız her zaman yere paralel kalmalıdır. Hareketin bu kısmında nefes alın.", "Nefes verirken hareketi tersine çevirerek ağırlığı başlangıç pozisyonuna getirin."]', 'strength', '["Around_The_Worlds/0.jpg", "Around_The_Worlds/1.jpg"]', 360.0, 'Around The Worlds', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('01765e7a-25ce-57ef-99f7-af818a2c9b0a', 'free-exercise-db', 'Atlas_Stone_Trainer', 'Atlas Taşı Antrenörü (Halter)', 'pull', 'intermediate', 'compound', '["other"]', '["lower back"]', '["biceps", "forearms", "glutes", "hamstrings", "quadriceps"]', '["Bu antrenman aleti, taşa erişimi olmayanlar için Atlas Taşı gücünü geliştirmede etkilidir ve genellikle bar uçlarından veya kalın borudan yapılır.", "İstediğiniz ağırlığı bara yükleyerek başlayın. Ağırlığın üzerinde ayaklarınızı iki yana açarak durun, kollarınızı aletin etrafına dolayın ve kalçanızdan öne eğilin.", "Kalçanızı açarak ağırlığı dizlerinizin üzerine çekmeye başlayın. Ağırlık dizlerinizi geçtiğinde, uyluklarınızın üzerine yatırıp geriye oturarak ve göğsünüze sıkıca sarılarak kucağınıza alabilirsiniz.", "Hareketi, ağırlığı olabildiğince yükseğe kaldırmak için kalçalarınızı ve dizlerinizi açarak bitirin. Ağırlık, ardışık tekrarlar için kucağınıza ya da yere bırakılabilir."]', 'strongman', '["Atlas_Stone_Trainer/0.jpg", "Atlas_Stone_Trainer/1.jpg"]', 480.0, 'Atlas Stone Trainer', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9eaf141e-7c21-5a34-a344-906c5e96d600', 'free-exercise-db', 'Atlas_Stones', 'Atlas Stone', 'pull', 'expert', 'compound', '["other"]', '["lower back"]', '["abdominals", "adductors", "biceps", "calves", "forearms", "glutes", "hamstrings", "middle back", "quadriceps", "traps"]', '["Atlas taşı ayaklarınızın arasında olacak şekilde başlayın. Kollarınızı taşın etrafına dikey olarak sarmak için kalçanızdan öne eğilin ve parmaklarınızı taşın altına sokmaya çalışın. Birçok taşın altında küçük bir düz kısım vardır; bu, taşı tutmayı kolaylaştırır.", "Taşı gövdenize doğru çekerek ayaklarınızın arka yarısıyla yere basıp taşı yerden kaldırın.", "Taş dizlerinizi geçtiğinde, geriye doğru oturarak taşı uyluklarınızın üzerine çekin (lap).", "Alçakta oturup taşı göğsünüzün üstüne doğru yükseltirken tutuşunuzu taşın üzerinden uzanacak şekilde değiştirin. Kalçanızla iterek ayağa kalkın. Yükleme platformuna yaklaşın, geriye doğru yaslanın ve kalçanızı açarak taşı olabildiğince yükseğe çıkarın."]', 'strongman', '["Atlas_Stones/0.jpg", "Atlas_Stones/1.jpg"]', 480.0, 'Atlas Stones', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('59213103-472b-56aa-9c93-70498584c5b4', 'free-exercise-db', 'Axle_Deadlift', 'Axle Deadlift', 'pull', 'intermediate', 'compound', '["other"]', '["lower back"]', '["forearms", "glutes", "hamstrings", "middle back", "quadriceps", "traps"]', '["Bara, ayaklarınızın üzerinde ortalanacak şekilde yaklaşın. Ayaklarınız yaklaşık kalça genişliğinde olmalıdır. Kalçanızdan eğilerek barı omuz genişliğinde kavrayın ve kürek kemiklerinizin öne doğru açılmasına izin verin. Genellikle karışık (bir el üstten, bir el alttan) tutuş kullanılır.", "Ayaklarınız ve tutuşunuz yerleştikten sonra derin bir nefes alın, ardından kaval kemikleriniz bara değene kadar kalçanızı alçaltın ve dizlerinizi bükün. Başınızla ileriye bakın, göğsünüzü yukarıda ve belinizi kavisli tutun ve topuklarınızdan iterek ağırlığı yukarı kaldırmaya başlayın.", "Bar dizlerinizi geçtikten sonra barı güçlü bir şekilde geriye doğru çekin, kürek kemiklerinizi birbirine yaklaştırın ve kalçanızı bara doğru ileri itin.", "Kalçanızdan eğilerek ve barı yere doğru yönlendirerek indirin."]', 'strongman', '["Axle_Deadlift/0.jpg", "Axle_Deadlift/1.jpg"]', 480.0, 'Axle Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('badf0486-62c3-5082-a02f-c9cc62c88bfe', 'free-exercise-db', 'Back_Flyes_-_With_Bands', 'Back Fly (Direnç Bandı)', 'pull', 'beginner', 'compound', '["bands"]', '["shoulders"]', '["middle back", "triceps"]', '["Bandı squat rack gibi sabit bir direğin etrafından geçirin.", "Bandı saplarından tutun ve banttaki gerginlik artacak şekilde geriye doğru uzaklaşın.", "Kollarınızı önünüzde düz bir şekilde uzatıp kaldırın. İpucu: Kollarınız düz ve yere paralel, gövdenize dik olmalı. Ayaklarınız omuz genişliğinde açık ve yere sağlam basmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken kollarınızı yanlara ve geriye doğru hareket ettirin. Kollarınızı uzanmış ve yere paralel tutun. Kollarınız yanlarınızda uzanana kadar hareketi sürdürün.", "Kısa bir duraklamadan sonra nefes alırken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Back_Flyes_-_With_Bands/0.jpg", "Back_Flyes_-_With_Bands/1.jpg"]', 360.0, 'Back Flyes - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eb0a15d3-5127-5294-b8e4-b2be02b16049', 'free-exercise-db', 'Backward_Drag', 'Geriye Doğru Kızak Çekme', 'pull', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["calves", "forearms", "glutes", "hamstrings", "lower back"]', '["Kızağa istediğiniz ağırlığı yükleyin ve tutunabileceğiniz bir halat veya kayış bağlayın.", "Egzersize belirli bir mesafe boyunca geriye doğru hareket ederek başlayın. Geriye yaslanın ve olabildiğince hızlı ilerlemek için bacaklarınızı kısa adımlarla iterek açın."]', 'strongman', '["Backward_Drag/0.jpg", "Backward_Drag/1.jpg"]', 480.0, 'Backward Drag', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c67080d1-e969-557a-9802-2e9153ad0c47', 'free-exercise-db', 'Backward_Medicine_Ball_Throw', 'Geriye Sağlık Topu Atışı', 'push', 'beginner', 'compound', '["medicine ball"]', '["shoulders"]', '[]', '["Bu egzersiz en iyi bir partnerle yapılır. Partneriniz yoksa top atılıp geri alınabilir veya duvara atılabilir.", "Partnerinizin birkaç metre önünde, ikiniz de aynı yöne bakacak şekilde ayakta durun. Topu bacaklarınızın arasında tutun.", "Çömelin ve ardından yönünüzü kuvvetle tersine çevirerek tamamen doğrulun ve topu başınızın üzerinden partnerinize fırlatın.", "Partneriniz topu size geri yuvarlayabilir. İstenen tekrar sayısı kadar tekrarlayın."]', 'plyometrics', '["Backward_Medicine_Ball_Throw/0.jpg", "Backward_Medicine_Ball_Throw/1.jpg"]', 480.0, 'Backward Medicine Ball Throw', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c440c359-d5d6-5def-9a58-7b17c1a271da', 'free-exercise-db', 'Balance_Board', 'Denge Tahtası', NULL, 'beginner', 'compound', '["other"]', '["calves"]', '["hamstrings", "quadriceps"]', '["Denge tahtasını önünüze yerleştirin.", "Üzerine çıkın ve dengenizi korumaya çalışın.", "Dengeyi istediğiniz süre boyunca koruyun."]', 'strength', '["Balance_Board/0.jpg", "Balance_Board/1.jpg"]', 360.0, 'Balance Board', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('df158df8-9246-52e7-8437-6893193c5d40', 'free-exercise-db', 'Ball_Leg_Curl', 'Leg Curl (Pilates Topu)', 'pull', 'beginner', 'isolation', '["exercise ball"]', '["hamstrings"]', '["calves", "glutes"]', '["Yerde sırtüstü uzanın ve ayaklarınızı topun üzerine koyun.", "Topu, bacaklarınız uzatıldığında bilekleriniz topun üzerinde olacak şekilde konumlandırın. Bu sizin başlangıç pozisyonunuzdur.", "Ağırlığınızı kürek kemiklerinizde ve ayaklarınızda tutarak kalçanızı yerden kaldırın.", "Dizlerinizi bükerek topu mümkün olduğunca yakınınıza çekin ve arka bacak kaslarınızı kasın.", "Kısa bir duraklamadan sonra başlangıç pozisyonuna dönün."]', 'strength', '["Ball_Leg_Curl/0.jpg", "Ball_Leg_Curl/1.jpg"]', 360.0, 'Ball Leg Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9298ea93-5567-5763-b10b-0fa31c448f62', 'free-exercise-db', 'Band_Assisted_Pull-Up', 'Barfiks (Direnç Bandı Destekli)', NULL, 'beginner', 'compound', '["other"]', '["lats"]', '["abdominals", "forearms", "middle back"]', '["Bandı barfiks barının ortasına dolayın. Farklı seviyelerde destek sağlamak için farklı bantlar kullanabilirsiniz.", "Bandın ucunu aşağı çekin ve bir dizinizi bükerek halkanın içine yerleştirin; kaymayacağından emin olun. Barı orta ile geniş arası bir tutuşla kavrayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi bükerken sırt (lat) kaslarınızı kasarak kendinizi yukarı çekin. Dirsek vücudunuzun yanına doğru sürülmelidir. Çenenizi barın üzerine geçirmeye çalışarak öne doğru çekin. Sallanma veya sert hareketlerden kaçının.", "Kısa bir duraklamanın ardından başlangıç pozisyonuna dönün."]', 'strength', '["Band_Assisted_Pull-Up/0.jpg", "Band_Assisted_Pull-Up/1.jpg"]', 360.0, 'Band Assisted Pull-Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('14bb832a-3364-52f8-a676-17d1d95d2fc4', 'free-exercise-db', 'Band_Good_Morning', 'Good Morning (Direnç Bandı)', 'pull', 'beginner', 'compound', '["bands"]', '["hamstrings"]', '["glutes", "lower back"]', '["41 inçlik bir bant kullanarak bandın bir ucuna basın ve ayaklarınızı hafifçe açın. Bandın diğer ucunu ensenizin arkasından geçirmek için kalçanızdan öne eğilin. Bu sizin başlangıç pozisyonunuzdur.", "Bacaklarınızı düz tutarak kalçanızı açın ve neredeyse dik bir pozisyona gelin.", "Başlangıç pozisyonuna geri inerken sırtınızı yuvarlamadığınızdan emin olun."]', 'powerlifting', '["Band_Good_Morning/0.jpg", "Band_Good_Morning/1.jpg"]', 360.0, 'Band Good Morning', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e386a48b-7914-55d2-9529-a24b8485bde1', 'free-exercise-db', 'Band_Good_Morning_Pull_Through', 'Good Morning Pull Through (Direnç Bandı)', 'pull', 'beginner', 'compound', '["bands"]', '["hamstrings"]', '["glutes", "lower back"]', '["Bandı bir direğe geçirin. Biraz uzağında durun ve bandın karşı ucunu boynunuza dolayın. Ellerinizle bandı yerinde tutmaya yardımcı olabilirsiniz.", "Kalçanızdan eğilerek başlayın ve kalçanızı mümkün olduğunca geriye itin. Sırtınızı düz tutun ve yaklaşık 90 dereceye kadar öne eğilin. Dizleriniz sadece hafifçe bükülü olmalıdır.", "Kalçanızı iterek ayakta duruş pozisyonuna geri dönün ve başlangıç pozisyonuna gelin."]', 'powerlifting', '["Band_Good_Morning_Pull_Through/0.jpg", "Band_Good_Morning_Pull_Through/1.jpg"]', 360.0, 'Band Good Morning (Pull Through)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('20e130eb-51d7-53a6-a7f8-a365d9b003e3', 'free-exercise-db', 'Band_Hip_Adductions', 'Kalça Adduksiyonu (Direnç Bandı)', 'pull', 'beginner', 'isolation', '["bands"]', '["adductors"]', '[]', '["Bir bandı sağlam bir direğe veya başka bir nesneye sabitleyin.", "Sol tarafınız direğe dönük şekilde durun ve sağ ayağınızı banttan geçirerek ayak bileğinize dolayın.", "Dik durun ve gerekirse direğe tutunun. Bu sizin başlangıç pozisyonunuz olacak.", "Dizinizi düz tutarak sağ bacağınızı yana doğru kaldırabildiğiniz kadar açın.", "Başlangıç pozisyonuna dönün ve istenen tekrar sayısı kadar tekrarlayın.", "Tarafları değiştirin."]', 'strength', '["Band_Hip_Adductions/0.jpg", "Band_Hip_Adductions/1.jpg"]', 360.0, 'Band Hip Adductions', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('dba9e6bb-3d79-51cd-9683-0ab04d0b8591', 'free-exercise-db', 'Band_Pull_Apart', 'Band Pull Apart (Direnç Bandı)', 'pull', 'beginner', 'isolation', '["bands"]', '["shoulders"]', '["middle back", "traps"]', '["Kollarınız önünüzde dümdüz uzanmış şekilde bandı iki elinizle tutarak başlayın.", "Ters fly hareketi yaparak ellerinizi yanlara doğru açıp hareketi başlatın.", "Hareketi yaparken dirseklerinizi gergin tutun ve bandı göğsünüze doğru getirin. Egzersiz boyunca omuzlarınızı geride tuttuğunuzdan emin olun.", "Hareketin sonunda bir an bekleyin ve kontrollü bir şekilde başlangıç pozisyonuna dönün."]', 'strength', '["Band_Pull_Apart/0.jpg", "Band_Pull_Apart/1.jpg"]', 360.0, 'Band Pull Apart', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('55c89913-921c-57dd-9e81-c7165b634dfb', 'free-exercise-db', 'Band_Skull_Crusher', 'Skull Crusher (Direnç Bandı)', 'push', 'beginner', 'isolation', '["bands"]', '["triceps"]', '[]', '["Bandı bir rafın veya sehpanın tabanına sabitleyin. Bant başınızla aynı hizada olacak şekilde sehpaya uzanın.", "Bandı tutun ve üst kolunuz yere dik olacak şekilde dirseklerinizi kaldırın. Dirsekler bükülüyken bant başınızın üzerinde olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolunuzu yerinde tutarak dirseğinizi açıp kolunuzu düzleştirin. Hareketin üst noktasında kısa bir süre durun ve başlangıç pozisyonuna dönün."]', 'strength', '["Band_Skull_Crusher/0.jpg", "Band_Skull_Crusher/1.jpg"]', 360.0, 'Band Skull Crusher', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e237ca9c-b4ee-5de3-8f9f-0fc19af43d00', 'free-exercise-db', 'Barbell_Ab_Rollout', 'Ab Rollout (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["abdominals"]', '["lower back", "shoulders"]', '["Bu egzersiz için şınav pozisyonuna geçmeniz gerekir; ancak ellerinizi yere koymak yerine her iki tarafında 5-10 lb (yaklaşık 2,5-5 kg) ağırlık bulunan bir olimpik halteri tutacaksınız. Bu sizin başlangıç pozisyonunuzdur.", "Sırtınızda hafif bir kavis koruyarak kalçanızı kaldırın ve nefes verirken halteri ayaklarınıza doğru yuvarlayın. İpucu: Hareket sırasında kalçanız yukarı doğru gelmeli, karın kaslarınızı sıkı tutmalı ve sırt duruşunuzu her zaman korumalısınız. Ayrıca kollarınız hareket boyunca yere dik kalmalıdır. Aksi takdirde karın kaslarından çok omuz ve sırt kaslarınızı çalıştırırsınız.", "Üstte bir saniyelik kasılmadan sonra, nefes alırken halteri yavaşça başlangıç pozisyonuna doğru geri yuvarlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Ab_Rollout/0.jpg", "Barbell_Ab_Rollout/1.jpg"]', 360.0, 'Barbell Ab Rollout', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7ebcdb6a-5fdc-5e0c-be4b-62fef64f8b39', 'free-exercise-db', 'Barbell_Ab_Rollout_-_On_Knees', 'Ab Rollout (Halter, Dizüstü)', 'pull', 'expert', 'compound', '["barbell"]', '["abdominals"]', '["lower back", "shoulders"]', '["Her iki tarafına 2,5-5 kg ağırlık yüklenmiş bir olimpik halteri tutun ve yere diz çökün.", "Şimdi halteri önünüzde yere koyun, böylece dizlerinizin ve ellerinizin üzerinde olun (diz üstü şınav pozisyonunda gibi). Bu sizin başlangıç pozisyonunuz olacaktır.", "Halteri yavaşça düz bir şekilde öne doğru yuvarlayın ve vücudunuzu düz bir çizgi halinde uzatın. İpucu: Vücudunuzla yere değmeden gidebildiğiniz kadar aşağı inin. Hareketin bu kısmında nefes alın.", "Uzatılmış pozisyonda bir saniye bekledikten sonra, nefes vererek kendinizi başlangıç pozisyonuna geri çekmeye başlayın. İpucu: Yavaş hareket edin ve karın kaslarınızı her zaman sıkı tutun."]', 'strength', '["Barbell_Ab_Rollout_-_On_Knees/0.jpg", "Barbell_Ab_Rollout_-_On_Knees/1.jpg"]', 360.0, 'Barbell Ab Rollout - On Knees', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('603fdb86-288e-52ec-83ab-e3a245cd0141', 'free-exercise-db', 'Barbell_Bench_Press_-_Medium_Grip', 'Bench Press (Halter, Orta Tutuş)', 'push', 'beginner', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Düz bir bench üzerine sırtüstü uzanın. Orta genişlikte bir tutuşla (hareketin ortasında ön kol ile üst kol arasında 90 derecelik açı oluşturan tutuş) barı raftan kaldırın ve kollarınız kilitli şekilde tam üzerinizde tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başlangıç pozisyonundan nefes alın ve bar göğsünüzün ortasına değene kadar yavaşça inin.", "Kısa bir duraklamanın ardından nefes verirken barı başlangıç pozisyonuna doğru itin. Barı göğüs kaslarınızı kullanarak itmeye odaklanın. Hareketin üst noktasında kollarınızı kilitleyin, göğsünüzü sıkın, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İdeal olarak ağırlığı indirmek, kaldırmaktan yaklaşık iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde barı rafa geri yerleştirin."]', 'strength', '["Barbell_Bench_Press_-_Medium_Grip/0.jpg", "Barbell_Bench_Press_-_Medium_Grip/1.jpg"]', 360.0, 'Barbell Bench Press - Medium Grip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0bd331d5-f435-52bc-9343-84cdd6ff42f3', 'free-exercise-db', 'Barbell_Curl', 'Biceps Curl (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["biceps"]', '["forearms"]', '["Gövdeniz dik şekilde ayakta durun ve omuz genişliğinde bir tutuşla halteri tutun. Avuç içleriniz ileri bakmalı ve dirsekleriniz gövdenize yakın olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Üst kollarınızı sabit tutarak, nefes verirken biceps''i kasıp ağırlığı öne doğru kaldırın. İpucu: Sadece ön kollarınız hareket etmeli.", "Biceps''iniz tamamen kasılana ve halter omuz seviyesine gelene kadar hareketi sürdürün. Kasılmış pozisyonu bir saniye tutun ve biceps''i güçlü bir şekilde sıkın.", "Nefes alırken halteri yavaşça başlangıç pozisyonuna geri indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Curl/0.jpg", "Barbell_Curl/1.jpg"]', 360.0, 'Barbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4ffc471a-c167-58cc-b82d-e508adb01c5e', 'free-exercise-db', 'Barbell_Curls_Lying_Against_An_Incline', 'Incline Sehpaya Yaslanarak Biceps Curl (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["biceps"]', '[]', '["Eğimli bir sehpaya yaslanarak uzanın; kollarınız halteri tutarak yatay bir hatta sarkıyor olsun. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolunuzu sabit tutarken biceps''inizi sıkarak ağırlığı mümkün olduğunca yukarı kıvırın. Hareketin bu kısmında nefes verin. İpucu: Yalnızca ön kollar hareket etmelidir. Kolları sallamayın.", "Bir saniyelik kasılmadan sonra nefes alarak yavaşça başlangıç pozisyonuna dönün. İpucu: Sonuna kadar indiğinizden emin olun.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Curls_Lying_Against_An_Incline/0.jpg", "Barbell_Curls_Lying_Against_An_Incline/1.jpg"]', 360.0, 'Barbell Curls Lying Against An Incline', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a9a2607c-cb76-509a-8c5e-dc264dbdc889', 'free-exercise-db', 'Barbell_Deadlift', 'Deadlift (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["lower back"]', '["calves", "forearms", "glutes", "hamstrings", "lats", "middle back", "quadriceps", "traps"]', '["Yüklü bir halterin önünde durun.", "Sırtınızı olabildiğince düz tutarak dizlerinizi bükün, öne eğilin ve halteri orta (omuz genişliğinde) üstten tutuşla kavrayın. Bu egzersizin başlangıç pozisyonudur. İpucu: Bu tutuşla halteri tutmak zorsa tutuşunuzu karma yapın veya bilek kayışı kullanın.", "Halteri tutarken nefes verip bacaklarınızla iterek ve aynı anda gövdenizi dik pozisyona getirerek kaldırışı başlatın. Dik pozisyonda göğsünüzü öne çıkarın ve kürek kemiklerinizi geriye getirerek sırtı kasın. Askerlerin nöbette dikkat duruşunda nasıl durduğunu düşünün.", "Dizlerinizi bükerek ve aynı anda sırtınızı düz tutup belden öne eğilerek başlangıç pozisyonuna dönün. Halterdeki plakalar yere değdiğinde başlangıç pozisyonuna dönmüş ve bir sonraki tekrara hazır olursunuz.", "Programda belirtilen tekrar sayısını yapın."]', 'strength', '["Barbell_Deadlift/0.jpg", "Barbell_Deadlift/1.jpg"]', 360.0, 'Barbell Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1b5c6937-63fe-587d-b28a-2d55b809ea8a', 'free-exercise-db', 'Barbell_Full_Squat', 'Full Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Bu egzersizi güvenlik için en iyi şekilde squat rack içinde yapabilirsiniz. Başlamak için önce barı rack üzerinde omuz seviyesinin hemen üzerine yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve barı omuzlarınızın arkasına (boynun biraz altına) yerleştirin.", "Barı her iki kolunuzla iki yandan kavrayın ve önce bacaklarınızla iterek, aynı anda gövdenizi dikleştirerek rack''ten kaldırın.", "Rack''ten uzaklaşın ve ayaklarınızı omuz genişliğinde, parmak uçları hafifçe dışa dönük orta bir duruşla konumlandırın. Başınızı her zaman yukarıda tutun ve sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başınız yukarıda ve duruşunuz dik kalacak şekilde dizlerinizi bükerek ve kalçanızı geriye oturtarak barı yavaşça indirmeye başlayın. Arka bacak kaslarınız baldırlarınıza değene kadar inmeye devam edin. Hareketin bu kısmında nefes alın.", "Nefes vererek, ayağınızın topuğu veya orta kısmı ile yere basarak, bacaklarınızı düzeltip kalçanızı açarak barı kaldırmaya ve başlangıç pozisyonuna dönmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Full_Squat/0.jpg", "Barbell_Full_Squat/1.jpg"]', 360.0, 'Barbell Full Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2a693bd7-5ad0-5c88-a9fc-f890d901c7f2', 'free-exercise-db', 'Barbell_Glute_Bridge', 'Glute Bridge (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["glutes"]', '["calves", "hamstrings"]', '["Bacaklarınızın üzerinde yüklü bir halter olacak şekilde yerde oturarak başlayın. Kalın saplı bir bar kullanmak veya bara pet takmak bu egzersizin verdiği rahatsızlığı büyük ölçüde azaltabilir. Barı tam kalçalarınızın üzerine gelecek şekilde yuvarlayın ve yere düz bir şekilde uzanın.", "Topuklarınızla iterek harekete başlayın ve kalçanızı barla birlikte dikey olarak yukarı uzatın. Ağırlığınızı üst sırtınız ve topuklarınız taşımalıdır.", "Olabildiğince yukarı uzanın, ardından hareketi tersine çevirerek başlangıç pozisyonuna dönün."]', 'powerlifting', '["Barbell_Glute_Bridge/0.jpg", "Barbell_Glute_Bridge/1.jpg"]', 360.0, 'Barbell Glute Bridge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ae43f24d-4ddf-5551-8f09-1e1e31930154', 'free-exercise-db', 'Barbell_Guillotine_Bench_Press', 'Guillotine Bench Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Orta genişlikte bir tutuşla (hareketin ortasında ön kollar ile üst kollar arasında 90 derecelik bir açı oluşturan tutuş) halteri raftan alın ve kollarınız kilitli şekilde boynunuzun tam üzerinde tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes alırken halteri boynunuza yaklaşık 2,5 cm kalana kadar yavaşça indirin.", "Bir saniyelik duraklamanın ardından, nefes verirken göğüs kaslarınızı kullanarak halteri başlangıç pozisyonuna geri itin. Kollarınızı kilitleyin ve kasılmış pozisyonda göğsünüzü sıkın, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İniş, çıkıştan en az iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde halteri rafa geri yerleştirin."]', 'strength', '["Barbell_Guillotine_Bench_Press/0.jpg", "Barbell_Guillotine_Bench_Press/1.jpg"]', 360.0, 'Barbell Guillotine Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2a12b5e7-6683-555c-b17c-d63f1ddd417a', 'free-exercise-db', 'Barbell_Hack_Squat', 'Hack Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "forearms", "hamstrings"]', '["Halteri arkanızda kollarınız uzanmış şekilde tutarak dik durun, ayaklarınız omuz genişliğinde olsun. İpucu: Avuç içleriniz arkaya bakacak şekilde omuz genişliğinde bir tutuş en iyisidir. Daha iyi bir kavrama için bu egzersizde bilek bandı kullanabilirsiniz. Bu sizin başlangıç pozisyonunuzdur.", "Başınızı ve gözlerinizi yukarıda, sırtınızı düz tutarak uyluklarınızın üst kısmı yere paralel olana kadar çömelin. Yavaşça inerken nefes alın.", "Ağırlıklı olarak topuğunuzla iterek ve uyluklarınızı sıkarak nefes verirken ayağa kalkın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Hack_Squat/0.jpg", "Barbell_Hack_Squat/1.jpg"]', 360.0, 'Barbell Hack Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4fd89638-fd3e-52f4-9013-e570f2f1ff58', 'free-exercise-db', 'Barbell_Hip_Thrust', 'Hip Thrust (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["glutes"]', '["calves", "hamstrings"]', '["Arkanızda bir bench olacak şekilde yerde oturarak başlayın. Bacaklarınızın üzerinde yüklü bir halter bulundurun. Kalın bir bar kullanmak veya bara pedli bir koruma takmak bu egzersizin yarattığı rahatsızlığı büyük ölçüde azaltabilir.", "Barı tam kalçalarınızın üzerine gelecek şekilde yuvarlayın ve kürek kemikleriniz bench''in üst kısmına yakın olacak şekilde bench''e yaslanın.", "Ayaklarınızdan iterek ve kalçanızı barın altında dikey olarak açarak harekete başlayın. Ağırlığınız kürek kemiklerinize ve ayaklarınıza oturmalıdır. Mümkün olduğunca yukarı uzanın, ardından hareketi tersine çevirerek başlangıç pozisyonuna dönün."]', 'powerlifting', '["Barbell_Hip_Thrust/0.jpg", "Barbell_Hip_Thrust/1.jpg"]', 360.0, 'Barbell Hip Thrust', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('01ab5411-f716-5844-9a76-4f196faaf5ec', 'free-exercise-db', 'Barbell_Incline_Bench_Press_-_Medium_Grip', 'Incline Bench Press (Halter, Orta Tutuş)', 'push', 'beginner', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Eğimli bir bankta sırtüstü uzanın. Orta genişlikte bir tutuşla (hareketin ortasında ön kollar ile üst kollar arasında 90 derecelik açı oluşturan tutuş) barı raftan alın ve kollarınız kilitli şekilde tam üzerinizde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken barı üst göğsünüze temas edene kadar yavaşça indirin.", "Bir saniye bekledikten sonra, nefes verirken göğüs kaslarınızı kullanarak barı itip başlangıç pozisyonuna getirin. Kollarınızı kasılmış pozisyonda kilitleyin, göğsünüzü sıkın, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İnişin yukarı çıkıştan en az iki kat uzun sürmesi gerekir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde barı rafa geri yerleştirin."]', 'strength', '["Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg", "Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"]', 360.0, 'Barbell Incline Bench Press - Medium Grip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9e40a750-a8eb-5c51-86c8-5dade4d8c009', 'free-exercise-db', 'Barbell_Incline_Shoulder_Raise', 'Incline Shoulder Raise (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["shoulders"]', '["chest"]', '["Incline sehpaya sırtüstü uzanın. Orta genişlikte (omuz genişliğinden biraz daha geniş) bir tutuşla halteri raftan alın ve kollarınız düz şekilde tepenizde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı düz tutarak nefes verirken kürek kemiklerinizi öne doğru iterek (protraksiyon) omuzlarınızı sehpadan kaldırıp halteri yukarı itin.", "Nefes alırken halteri başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Incline_Shoulder_Raise/0.jpg", "Barbell_Incline_Shoulder_Raise/1.jpg"]', 360.0, 'Barbell Incline Shoulder Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('550a3904-d4c7-5042-b8da-c5c2937a422d', 'free-exercise-db', 'Barbell_Lunge', 'Lunge (Hamle) (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bu egzersizi güvenlik amacıyla squat rafının içinde yapmak en iyisidir. Başlamak için önce barı rafa omuz seviyesinin hemen altına yerleştirin. Doğru yüksekliği seçip barı yükledikten sonra barın altına girin ve omuzlarınızın arka kısmını (boynun biraz altında) barın üzerine yerleştirin.", "Her iki kolunuzla barı yanlardan tutun ve önce bacaklarınızla iterek, aynı anda gövdenizi doğrultarak barı raftan kaldırın.", "Raftan uzaklaşın, sağ bacağınızla öne adım atın ve gövdenizi dik tutup dengenizi koruyarak kalçanızdan aşağı çömelin. İnerken nefes alın. Not: İnerken dizinizin ayak parmaklarınızın ilerisine geçmesine izin vermeyin; bu, diz eklemine gereksiz yük bindirir.", "Ağırlıklı olarak topuğunuzla iterek yukarı çıkın ve nefes verirken başlangıç pozisyonuna dönün.", "Hareketi önerilen tekrar sayısı kadar yapın, ardından sol bacakla gerçekleştirin."]', 'strength', '["Barbell_Lunge/0.jpg", "Barbell_Lunge/1.jpg"]', 360.0, 'Barbell Lunge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('554c2479-8990-50a6-90b8-e4e87863d714', 'free-exercise-db', 'Barbell_Rear_Delt_Row', 'Arka Omuz Row (Halter)', 'pull', 'beginner', 'compound', '["barbell"]', '["shoulders"]', '["biceps", "lats", "middle back"]', '["Dik durun ve bir halteri geniş (omuz genişliğinden daha geniş) ve üsten (avuç içleri vücudunuza bakacak şekilde) bir tutuşla tutun.", "Dizlerinizi hafifçe bükün ve belinizin doğal kavsini koruyarak öne eğilin. Kollarınız barı tutarken önünüzde aşağı sarkmalıdır. Gövdeniz yere paralel olduğunda dirseklerinizi vücudunuzdan uzağa doğru açın. İpucu: Gövdeniz ve kollarınız \"T\" harfine benzemelidir. Şimdi egzersize başlamaya hazırsınız.", "Üst kollarınızı gövdenize dik tutarak, nefes verirken ve arka omuzlarınızı sıkarak halteri üst göğsünüze doğru çekin. İpucu: Doğru yapıldığında bu egzersiz ters yönde yapılan bir bench press''e benzemelidir. Ayrıca işi yapmak için biceps kaslarınızı kullanmaktan kaçının. Arka omuzları çalıştırmaya odaklanın; kollar yalnızca kanca görevi görmelidir.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Rear_Delt_Row/0.jpg", "Barbell_Rear_Delt_Row/1.jpg"]', 360.0, 'Barbell Rear Delt Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('14e6c450-7a89-5bb8-b8f4-b22f01001164', 'free-exercise-db', 'Barbell_Rollout_from_Bench', 'Bench Üzerinden Rollout (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["abdominals"]', '["glutes", "hamstrings", "lats", "shoulders"]', '["Yüklü bir halteri yere, bir bench''in ucuna yakın bir yere koyun. Her iki bacağınızla bench üzerinde diz çökün ve halteri orta ile dar arası bir tutuşla kavrayın. Bu sizin başlangıç pozisyonunuz olacak.", "Başlamak için kalçalarınızı açarak halteri yavaşça öne doğru yuvarlayın. Yuvarlarken omzunuzu bükerek halteri başınızın üzerine doğru götürün. Hareket boyunca kollarınızın uzanmış kalmasına dikkat edin.", "Halter mümkün olduğunca ileriye gittiğinde başlangıç pozisyonuna dönün."]', 'strength', '["Barbell_Rollout_from_Bench/0.jpg", "Barbell_Rollout_from_Bench/1.jpg"]', 360.0, 'Barbell Rollout from Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b35136a7-626b-5cb9-9571-30207301452a', 'free-exercise-db', 'Barbell_Seated_Calf_Raise', 'Oturarak Calf Raise (Halter)', 'push', 'beginner', 'isolation', '["barbell"]', '["calves"]', '[]', '["Düz bir bench''in yaklaşık 30 cm önüne bir blok yerleştirin.", "Bench''e oturun ve ayak parmak diplerinizi (ayak tabanınızın ön kısmını) bloğun üzerine koyun.", "Birinden, bir halteri dizlerinizin yaklaşık 7-8 cm üzerinde uyluklarınızın üstüne yerleştirmesini ve orada tutmasını isteyin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Baldırlarınızı sıkarak ve nefes vererek parmak uçlarınızda mümkün olduğunca yükselin.", "Bir saniyelik kasılmadan sonra yavaşça başlangıç pozisyonuna dönün. İpucu: Maksimum fayda için baldırlarınızı gidebildiğiniz kadar esnetin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Seated_Calf_Raise/0.jpg", "Barbell_Seated_Calf_Raise/1.jpg"]', 360.0, 'Barbell Seated Calf Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e7c84d37-e70f-5e97-a261-8e05f7cf802f', 'free-exercise-db', 'Barbell_Shoulder_Press', 'Shoulder Press (Halter, Oturarak)', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["chest", "triceps"]', '["Squat rafında sırt destekli bir sehpaya oturun. Halteri başınızın hemen üzerinde olacak bir yüksekliğe ayarlayın. Halteri üstten tutuşla (avuç içleri öne bakacak şekilde) kavrayın.", "Halteri doğru tutuş genişliğiyle aldıktan sonra kollarınızı kilitleyerek başınızın üzerine kaldırın. Omuz hizasında ve başınızın biraz önünde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken halteri yavaşça omuzlarınıza indirin.", "Nefes verirken halteri başlangıç pozisyonuna geri kaldırın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Shoulder_Press/0.jpg", "Barbell_Shoulder_Press/1.jpg"]', 360.0, 'Barbell Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2b61edea-b38e-5409-b46e-0c1b09bd441f', 'free-exercise-db', 'Barbell_Shrug', 'Omuz Şrag (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["traps"]', '[]', '["Ayaklarınız omuz genişliğinde olacak şekilde dik durun ve halteri önünüzde iki elinizle pronasyon tutuşuyla (avuç içleri uyluklara bakacak şekilde) tutun. İpucu: Elleriniz omuz genişliğinden biraz daha geniş olmalı. Daha iyi bir kavrama için bu egzersizde bilek bandı kullanabilirsiniz. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken omuzlarınızı gidebildiğiniz kadar yukarı kaldırın ve kasılmayı bir saniye tutun. İpucu: Halteri biceps''inizi kullanarak kaldırmaya çalışmaktan kaçının.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Shrug/0.jpg", "Barbell_Shrug/1.jpg"]', 360.0, 'Barbell Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('72121f8a-9a83-50dc-944b-5aee3bf5c066', 'free-exercise-db', 'Barbell_Shrug_Behind_The_Back', 'Arkadan Shrug (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["traps"]', '["forearms", "middle back"]', '["Ayaklarınız omuz genişliğinde açık şekilde dik durun ve halteri arkanızda, avuç içleriniz arkaya bakacak şekilde (pronated tutuş) iki elinizle tutun. İpucu: Elleriniz omuz genişliğinden biraz daha geniş olmalıdır. Daha iyi bir kavrama için bu egzersizde bilek bandı kullanabilirsiniz. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken omuzlarınızı olabildiğince yukarı kaldırın ve kasılmayı bir saniye tutun. İpucu: Halteri biceps ile kaldırmaya çalışmaktan kaçının. Kollar her zaman uzatılmış halde kalmalıdır.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Shrug_Behind_The_Back/0.jpg", "Barbell_Shrug_Behind_The_Back/1.jpg"]', 360.0, 'Barbell Shrug Behind The Back', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('445c0fa9-ee7d-5df9-90f9-5d7faa9f92a1', 'free-exercise-db', 'Barbell_Side_Bend', 'Side Bend (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["abdominals"]', '["lower back"]', '["Halteri omuzlarınızın arkasına (boynun biraz altına) yerleştirerek dik durun. Ayaklarınız omuz genişliğinde açık olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sırtınızı düz ve başınızı yukarıda tutarak, sadece belinizden sağa doğru gidebildiğiniz kadar eğilin. Yana eğilirken nefes alın. Ardından bir saniye bekleyin ve nefes vererek başlangıç pozisyonuna dönün. İpucu: Vücudun geri kalanını sabit tutun.", "Şimdi hareketi sola eğilerek tekrarlayın. Bir saniye bekleyin ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Side_Bend/0.jpg", "Barbell_Side_Bend/1.jpg"]', 360.0, 'Barbell Side Bend', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fb2c5303-17d7-5aec-810d-2b16d85d7496', 'free-exercise-db', 'Barbell_Side_Split_Squat', 'Yan Split Squat (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "hamstrings", "lower back"]', '["Halteri omuzlarınızın arkasına (boynun biraz altına) yerleştirip dik durun. Ayaklarınız geniş açık olmalı ve öndeki bacağın ayağı yana doğru açılı olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Karşı bacağınızı yalnızca hafifçe bükülü tutarken, öndeki bacağınızın dizini ve kalçasını bükerek vücudunuzu açılı ayağınızın yan tarafına doğru indirin. Vücudunuzu indirirken nefes alın.", "Öndeki bacağınızın kalçasını ve dizini açarak başlangıç pozisyonuna dönün. Bu hareketi yaparken nefes verin.", "Önerilen tekrar sayısını tamamladıktan sonra hareketi karşı bacakla tekrarlayın."]', 'strength', '["Barbell_Side_Split_Squat/0.jpg", "Barbell_Side_Split_Squat/1.jpg"]', 360.0, 'Barbell Side Split Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b3a290ef-02f9-5fca-bba4-677587a8fc30', 'free-exercise-db', 'Barbell_Squat', 'Squat (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Bu egzersizi güvenlik açısından bir squat rafı içinde yapmak en iyisidir. Başlamak için önce halteri rafta omuz seviyenizin hemen altına ayarlayın. Doğru yükseklik seçilip halter yüklendikten sonra halterin altına girin ve omuzlarınızın arkasını (boynun biraz altından) halterin üzerine yerleştirin.", "Halteri her iki kolunuzla yanlardan tutun ve önce bacaklarınızla iterek, aynı anda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşla, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Başınızı her zaman yukarıda tutun ve sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuzdur. (Not: Bu anlatımda genel gelişimi hedefleyen yukarıdaki orta duruş kullanılmıştır; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz düz kalacak şekilde dizlerinizi ve kalçanızı bükerek halteri yavaşça indirmeye başlayın. Üst bacak ile baldır arasındaki açı 90 dereceden biraz daha az olana kadar inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız dizlerinizin önü, ayak uçlarınızla öne doğru dik bir hayali düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizgiyi geçerse (ayak uçlarınızı aşarsa) dizinize gereksiz yük bindirirsiniz ve egzersizi yanlış yapmış olursunuz.", "Nefes verirken topuğunuzla yere basıp bacaklarınızı tekrar düzleştirerek halteri kaldırmaya başlayın ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Squat/0.jpg", "Barbell_Squat/1.jpg"]', 360.0, 'Barbell Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('59192791-2266-5d74-8d03-55168144cb4a', 'free-exercise-db', 'Barbell_Squat_To_A_Bench', 'Bench''e Squat (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Bu egzersiz güvenlik açısından en iyi squat rafının içinde yapılır. Başlamak için önce arkanıza düz bir bench veya box yerleştirin. Düz bench, kalçanızı geriye oturtmayı ve derinliğe inmeyi öğrenmenize yardımcı olur.", "Ardından barı boyunuza en uygun yükseklikteki rafa yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve omuzlarınızın arkasını (boynun biraz altında) barın üzerine yerleştirin.", "Barı her iki kolunuzla yanlardan tutun ve önce bacaklarınızla iterek, aynı zamanda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşta, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Aşağı bakmak dengenizi bozacağından başınızı her zaman yukarıda tutun ve sırtınızı dik tutun. Bu sizin başlangıç pozisyonunuz olacaktır. (Not: Bu anlatım için genel gelişimi hedefleyen yukarıdaki orta duruş kullanılmaktadır; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik kalacak şekilde dizlerinizi bükerek ve kalçanızı geriye oturtarak barı yavaşça indirmeye başlayın. Arkanızdaki bench''e hafifçe dokunana kadar inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız dizlerinizin önü, ayak uçlarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizginin ötesine (ayak uçlarınızı geçerek) giderse dizlere gereksiz yük bindirirsiniz ve egzersizi yanlış yapmış olursunuz.", "Nefes verirken topuğunuzla yeri iterek, bacaklarınızı düzeltip kalçanızı açarak barı başlangıç pozisyonuna doğru kaldırmaya başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Barbell_Squat_To_A_Bench/0.jpg", "Barbell_Squat_To_A_Bench/1.jpg"]', 360.0, 'Barbell Squat To A Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7aff17d1-b7c4-5e24-af0d-22a84011bf8e', 'free-exercise-db', 'Barbell_Step_Ups', 'Step Up (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "quadriceps"]', '["Halteri omuzlarınızın arkasına (boynun biraz altına) yerleştirerek dik durun ve yükseltilmiş bir platformun (düz bench''in arkasında spot için kullanılan platform gibi) arkasında ayakta durun. Bu sizin başlangıç pozisyonunuzdur.", "Sağ ayağınızı yükseltilmiş platforma koyun. Sağ bacağınızın kalçasını ve dizini açarak platforma çıkın. Vücudunuzun geri kalanını yukarı kaldırmak için çoğunlukla topuğunuzu kullanın ve sol ayağınızı da platforma koyun. Yukarı çıkmak için gereken kuvveti uygularken nefes verin.", "Nefes alırken sağ bacağınızın kalçasını ve dizini bükerek sol bacağınızla aşağı inin. Sağ ayağınızı sol ayağınızın yanına, ilk konumuna yerleştirerek başlangıçtaki ayakta duruş pozisyonuna dönün.", "Önerilen tekrar sayısı kadar sağ bacakla tekrarlayın, ardından sol bacakla yapın."]', 'strength', '["Barbell_Step_Ups/0.jpg", "Barbell_Step_Ups/1.jpg"]', 360.0, 'Barbell Step Ups', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8bdc04a0-4793-57d7-ad75-090ac7fd23df', 'free-exercise-db', 'Barbell_Walking_Lunge', 'Yürüyüşlü Lunge (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Ayaklarınız omuz genişliğinde açık ve bir halter üst sırtınızda olacak şekilde dik durarak başlayın.", "Bir bacağınızla öne adım atın ve kalçanızı indirmek için dizlerinizi bükün. Arka diziniz neredeyse yere değene kadar inin. Duruşunuz dik kalmalı ve ön diziniz ön ayağınızın üzerinde kalmalıdır.", "Ön ayağınızın topuğundan iterek her iki dizinizi açın ve ayağa kalkın.", "Arka ayağınızla öne adım atarak lunge hareketini diğer bacakla tekrarlayın."]', 'strength', '["Barbell_Walking_Lunge/0.jpg", "Barbell_Walking_Lunge/1.jpg"]', 360.0, 'Barbell Walking Lunge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f6dfb8ce-5230-56ab-a6a9-90c2778671ca', 'free-exercise-db', 'Battling_Ropes', 'Battling Ropes', 'push', 'beginner', 'compound', '["other"]', '["shoulders"]', '["chest", "forearms"]', '["Bu egzersiz için ortasından 4,5-6 metre uzağa sabitlenmiş ağır bir halata ihtiyacınız olacak. Halatın önünde durun ve kollarınız yanlarınızda uzanmış halde her elinizle bir ucunu tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Bir kolunuzu olabildiğince hızlı bir şekilde omuz seviyesine kaldırarak harekete başlayın.", "O kolu başlangıç pozisyonuna bırakırken karşı kolu kaldırın.", "Sol ve sağ kollarınızı dönüşümlü olarak kullanmaya devam edin ve halatları olabildiğince hızlı bir şekilde aşağı yukarı savurun."]', 'strength', '["Battling_Ropes/0.jpg", "Battling_Ropes/1.jpg"]', 360.0, 'Battling Ropes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f35aafd8-2b17-55ad-a2b5-49d00817ff16', 'free-exercise-db', 'Bear_Crawl_Sled_Drags', 'Ayı Yürüyüşü Kızak Sürükleme', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bir koşum takımı ya da gevşek bir ağırlık kemeri takın ve zinciri arkaya bağlayın; böylece kızağa sırtınız dönük olsun. Ellerinizi yere koyacak şekilde eğilin. Sırtınız düz, dizleriniz bükülü olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Sağ ve sol bacağınızı dönüşümlü olarak iterek ilerlemeye başlayın. Dengenizi korumak ve çekmeye yardımcı olmak için ellerinizi kullanın. Belirlenen mesafe boyunca sırtınızı düz tutmaya çalışın."]', 'strongman', '["Bear_Crawl_Sled_Drags/0.jpg", "Bear_Crawl_Sled_Drags/1.jpg"]', 480.0, 'Bear Crawl Sled Drags', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d8aa6bd6-9ceb-5b14-9195-b0dad36c0862', 'free-exercise-db', 'Behind_Head_Chest_Stretch', 'Baş Arkası Göğüs Esnetme (Partnerli)', 'static', 'expert', 'isolation', '["other"]', '["chest"]', '["shoulders"]', '["Partneriniz arkanızda olacak şekilde yerde dik oturun.", "Ellerinizi başınızın arkasına koyun ve dirseklerinizi olabildiğince geriye itin. Partneriniz dirseklerinizi tutmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Ellerinizi başınızın arkasında tutarak dirseklerinizi 10 saniye veya daha uzun süre nazikçe öne çekmeye çalışın. Partneriniz dirseklerinizin hareket etmesini engellemelidir.", "Şimdi kaslarınızı gevşetin ve partnerinizin dirseklerinizi sizin için rahat olduğu kadar nazikçe geriye çekmesini sağlayın. Aşırı esneme veya sakatlanmayı önlemek için esnemenin yeterli olduğu noktada partnerinize haber verdiğinizden emin olun."]', 'stretching', '["Behind_Head_Chest_Stretch/0.jpg", "Behind_Head_Chest_Stretch/1.jpg"]', 150.0, 'Behind Head Chest Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('277ab3ee-3a4f-5301-9690-98062e072f26', 'free-exercise-db', 'Bench_Dips', 'Bench Dips', 'push', 'beginner', 'compound', '["body only"]', '["triceps"]', '["chest", "shoulders"]', '["Bu egzersiz için sırtınızın arkasına bir sehpa yerleştirmeniz gerekir. Sehpa vücudunuza dik olacak şekilde ve ona arkanız dönükken, kollarınız tamamen uzamış ve omuz genişliğinde açık halde sehpanın kenarından tutunun. Bacaklarınız öne doğru uzanmış, belden bükülü ve gövdenize dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alarak dirseklerinizden bükülüp vücudunuzu yavaşça indirin; üst kol ile ön kol arasındaki açı 90 dereceden biraz küçük olana kadar inin. İpucu: Hareket boyunca dirsekleri mümkün olduğunca yakın tutun. Ön kollar her zaman aşağıya bakmalıdır.", "Triceps''inizi kullanarak gövdenizi tekrar yukarı itin ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bench_Dips/0.jpg", "Bench_Dips/1.jpg"]', 360.0, 'Bench Dips', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('54449bd4-18c7-5c6c-b0b2-05528e649e9a', 'free-exercise-db', 'Bench_Jump', 'Bench Jump', 'push', 'intermediate', 'compound', '["body only"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Önünüzde 30-60 cm mesafede bir kutu veya bench ile başlayın. Ayaklarınız omuz genişliğinde açık dikilin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sıçrayışa hazırlanmak için kısa bir squat yapın ve kollarınızı geriye doğru savurun.", "Bu pozisyondan sekerek kalçanızı, dizlerinizi ve ayak bileklerinizi açın ve olabildiğince yükseğe sıçrayın. Kollarınızı öne ve yukarı doğru savurun.", "Bench''in üzerinden atlayın ve dizleriniz bükülü şekilde inin, darbeyi bacaklarınızla sönümleyin.", "Arkanıza dönüp ters yöne bakın, ardından bench''in üzerinden geri atlayın."]', 'plyometrics', '["Bench_Jump/0.jpg", "Bench_Jump/1.jpg"]', 480.0, 'Bench Jump', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bdfa1c28-24d9-56ad-a71d-b1d56bf8a91d', 'free-exercise-db', 'Bench_Press_-_Powerlifting', 'Bench Press (Powerlifting)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "forearms", "lats", "shoulders"]', '["Bench''e uzanarak başlayın; mümkünse başınızı halterin ötesine getirin. Ayaklarınızı altınıza çekin ve sırtınızı kavisli tutun. Ağırlığınızı desteklemek için halteri kullanarak omuzlarınızı bench''ten kaldırın ve geriye çekin, kürek kemiklerinizi birbirine sıkıştırın. Ayaklarınızı kullanarak trapez kaslarınızı bench''e doğru bastırın. Hareket boyunca bu sıkı vücut pozisyonunu koruyun.", "Tutuşunuz ne kadar geniş olursa olsun, halterdeki halkayı kapsamalıdır. Omuzlarınızı öne çekmeden halteri raftan çıkarın. Halteri sıkmaya ve ikiye ayırmaya çalışmaya odaklanın.", "Halteri alt göğsünüze veya üst karnınıza indirin. Halter, bilek ve dirsek her zaman aynı hizada kalmalıdır.", "Halter gövdenize değdiğinde duraklayın ve ardından halteri mümkün olan en büyük kuvvetle yukarı itin. Dirsekler kilitlenmeye kadar içeride kalmalıdır."]', 'powerlifting', '["Bench_Press_-_Powerlifting/0.jpg", "Bench_Press_-_Powerlifting/1.jpg"]', 360.0, 'Bench Press - Powerlifting', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4fedb2cd-84a5-5859-9e51-17312e97d91b', 'free-exercise-db', 'Bench_Press_-_With_Bands', 'Bench Press (Direnç Bandı)', 'push', 'beginner', 'compound', '["bands"]', '["chest"]', '["shoulders", "triceps"]', '["Düz bir bank kullanarak bir bandı, başınıza en yakın bank ayağının altına sabitleyin.", "Bant sabitlendikten sonra iki sapından tutun ve bankta uzanın.", "Kollarınızı uzatarak bant saplarını omuz genişliğinde önünüzde tutun.", "Omuz genişliğine geldikten sonra bileklerinizi, avuç içleriniz sizden uzağa bakacak şekilde öne doğru çevirin. Bu sizin başlangıç pozisyonunuzdur.", "Dirseğiniz 90 derecelik açı oluşturana kadar sapları yavaşça indirin. Her zaman tam kontrolü koruyun.", "Nefes verirken göğüs kaslarınızı kullanarak sapları yukarı kaldırın. Kollarınızı kasılmış pozisyonda kilitleyin, göğsünüzü sıkın, bir saniye bekleyin ve ardından yavaşça inmeye başlayın. İpucu: İnişin yukarı çıkıştan en az iki kat uzun sürmesi gerekir.", "Hareketi antrenman programınızdaki belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bench_Press_-_With_Bands/0.jpg", "Bench_Press_-_With_Bands/1.jpg"]', 360.0, 'Bench Press - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f25e1bba-1892-5d25-9d0d-df656c32ded5', 'free-exercise-db', 'Bench_Press_with_Chains', 'Bench Press (Zincirli)', 'push', 'expert', 'compound', '["barbell"]', '["triceps"]', '["chest", "lats", "shoulders"]', '["Ana zinciri istediğiniz uzunluğa kısaltarak ayarlayın. Zincirleri barın uç kısımlarına (sleeve) yerleştirin.", "Bench''e uzanın ve mümkünse başınızı barın ötesine geçirin. Ayaklarınızı altınıza çekin ve sırtınızı kavisleyin. Barı ağırlığınızı desteklemek için kullanarak omuzlarınızı bench''ten kaldırın ve geriye çekin, kürek kemiklerinizi birbirine sıkıştırın. Trapez kaslarınızı bench''e doğru bastırmak için ayaklarınızı kullanın. Hareket boyunca bu sıkı vücut pozisyonunu koruyun. Tutuşunuz ne kadar geniş olursa olsun, barın üzerindeki halkayı kapsamalıdır.", "Omuzlarınızı öne açmadan barı rack''ten çıkarın. Barı sıkmaya ve ikiye ayırmaya çalışmaya odaklanın. Barı alt göğsünüze veya üst karnınıza doğru indirin. Bar, bilek ve dirsek her zaman aynı hizada kalmalıdır.", "Halter gövdenize değdiğinde kısa bir süre bekleyin, ardından barı olabildiğince fazla güçle yukarı itin. Dirsekler kollar tam düzelene kadar içeride tutulmalıdır."]', 'powerlifting', '["Bench_Press_with_Chains/0.jpg", "Bench_Press_with_Chains/1.jpg"]', 360.0, 'Bench Press with Chains', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ca817c55-3555-527d-9b7c-bda4ce147246', 'free-exercise-db', 'Bench_Sprint', 'Bench Sprint (Sehpada Sprint)', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bir ayağınız sehpa veya kutu üzerinde, topuğunuz kenara yakın olacak şekilde yerde durun.", "Sehpanın üzerindeki ayağınızla iterek kalça ve dizinizi açın.", "Karşı ayağınızla kutunun üzerine inin ve diğer ayağınızı başlangıç pozisyonuna geri getirin.", "Seti tamamlamak için bir ayaktan diğerine geçerek devam edin."]', 'plyometrics', '["Bench_Sprint/0.jpg", "Bench_Sprint/1.jpg"]', 480.0, 'Bench Sprint', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7d498813-6ebf-527d-8f3c-23dd92f9b7df', 'free-exercise-db', 'Bent-Arm_Barbell_Pullover', 'Bükülü Kol Pullover (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["lats"]', '["chest", "lats", "shoulders", "triceps"]', '["Düz bir sehpada omuz genişliğinde bir tutuşla halteri alarak uzanın.", "Kollarınız hafif bükülü şekilde halteri göğsünüzün tam üzerinde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı bükülü pozisyonda tutarak, göğsünüzde bir gerilme hissedene kadar nefes alırken ağırlığı başınızın arkasında bir yay çizerek yavaşça indirin.", "Bu noktada, ağırlığı indirirken çizdiğiniz yayı izleyerek halteri başlangıç pozisyonuna geri getirin ve bu hareketi yaparken nefes verin.", "Ağırlığı başlangıç pozisyonunda bir saniye bekletin ve hareketi belirlenen tekrar sayısı kadar yineleyin."]', 'strength', '["Bent-Arm_Barbell_Pullover/0.jpg", "Bent-Arm_Barbell_Pullover/1.jpg"]', 360.0, 'Bent-Arm Barbell Pullover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('80933262-483d-583d-ba7f-400ee4b138d6', 'free-exercise-db', 'Bent-Arm_Dumbbell_Pullover', 'Pullover (Dambıl, Bükülü Kol)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["chest"]', '["lats", "shoulders", "triceps"]', '["Düz bir bench üzerine bir dambılı dik şekilde yerleştirin.", "Dambılın bench''in üst kısmında sağlam durduğundan emin olun ve bench''e dik şekilde (gövdeniz bench''in üzerinden çapraz, haç oluşturacak şekilde) yalnızca omuzlarınız bench''e temas edecek biçimde uzanın. Kalçanız bench''in altında, bacaklarınız bükülü ve ayaklarınız yere sağlam basmalıdır. Başınız da bench''in dışında kalacaktır.", "Dambılı iki elinizle kavrayın ve kollarınız bükülü halde göğsünüzün tam üzerinde tutun. İki avuç içiniz de dambılın bir ucunun alt tarafına dayanmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır. Dikkat: Bu egzersiz için kullanılan dambılın sağlam olduğundan her zaman emin olun. Plakaları gevşek bir dambıl kullanmak, dambılın parçalanıp yüzünüze düşmesine neden olabilir.", "Kollarınızı bükülü pozisyonda kilitli tutarak, göğsünüzde bir gerilme hissedene kadar nefes alırken ağırlığı başınızın arkasına doğru bir yay çizerek yavaşça indirin.", "Bu noktada, ağırlığın indiği yayı takip ederek dambılı başlangıç pozisyonuna geri getirin ve bu hareketi yaparken nefes verin.", "Ağırlığı başlangıç pozisyonunda bir saniye tutun ve hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent-Arm_Dumbbell_Pullover/0.jpg", "Bent-Arm_Dumbbell_Pullover/1.jpg"]', 360.0, 'Bent-Arm Dumbbell Pullover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0f8fac7e-0c1c-512e-b149-3d9c57c86ae4', 'free-exercise-db', 'Bent-Knee_Hip_Raise', 'Dizler Bükülü Kalça Kaldırma', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Kollarınız yanlarınızda olacak şekilde sırtüstü düz bir şekilde yere uzanın.", "Şimdi dizlerinizi yaklaşık 75 derecelik bir açıyla bükün ve ayaklarınızı yerden yaklaşık 5 cm kaldırın.", "Alt karın kaslarınızı kullanarak, bacaklarınızdaki 75 derecelik bükülmeyi koruyarak dizlerinizi kendinize doğru çekin. Pelvisinizi geriye doğru yuvarlayarak kalçanızı yerden kaldırana kadar bu harekete devam edin. Hareketin bu kısmında nefes verin. İpucu: Hareketin sonunda dizleriniz göğsünüzün üzerinde olacaktır.", "Hareketin üst noktasında karın kaslarınızı bir saniye sıkın ve ardından nefes alırken yavaşça başlangıç pozisyonuna dönün. İpucu: Her zaman kontrollü bir hareket sürdürün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent-Knee_Hip_Raise/0.jpg", "Bent-Knee_Hip_Raise/1.jpg"]', 360.0, 'Bent-Knee Hip Raise', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0730b9c1-4e72-5923-8351-d1522ac647cf', 'free-exercise-db', 'Bent_Over_Barbell_Row', 'Bent Over Row (Halter)', 'pull', 'beginner', 'compound', '["barbell"]', '["middle back"]', '["biceps", "lats", "shoulders"]', '["Halteri üstten tutuşla (avuç içleri aşağı bakacak şekilde) tutun, dizlerinizi hafifçe bükün ve sırtınızı düz tutarak belden öne eğilip gövdenizi neredeyse yere paralel hale getirin. İpucu: Başınızı yukarıda tuttuğunuzdan emin olun. Halter tam önünüzde sarkmalı, kollarınız yere ve gövdenize dik şekilde aşağı sarkmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi gövdenizi sabit tutarken nefes verin ve halteri kendinize doğru çekin. Dirseklerinizi vücudunuza yakın tutun ve ağırlığı taşımak için yalnızca ön kollarınızı kullanın. Üst kasılma noktasında sırt kaslarınızı sıkın ve kısa bir süre bekleyin.", "Ardından nefes alın ve halteri yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent_Over_Barbell_Row/0.jpg", "Bent_Over_Barbell_Row/1.jpg"]', 360.0, 'Bent Over Barbell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d10079ae-2984-5dbc-9722-22ec853950bb', 'free-exercise-db', 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'Rear Delt Raise (Dambıl, Baş Bankta)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Her elinizde bir dambıl olacak ve önünüzde eğimli bir bank bulunacak şekilde dik durun.", "Sırtınızı düz tutarak ve doğal bel kavsinizi koruyarak, alnınız önünüzdeki banka değene kadar öne eğilin. Kollarınızın yere dik olacak şekilde önünüzde sarkmasına izin verin. Avuç içleriniz birbirine bakmalı ve gövdeniz yere paralel olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi öne eğik ve sabit tutarak, kollarınız düz ve dirsekler hafif bükülü halde dambılları düz yanlara doğru, kollarınız yere paralel olana kadar kaldırın. Ağırlıkları kaldırırken nefes verin. Dikkat: Gövdeyi sallamaktan veya kolları yanlar yerine geriye getirmekten kaçının.", "Üstte bir saniyelik kasılmadan sonra dambılları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg", "Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg"]', 360.0, 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5b615780-d848-58a8-8988-8ed896d23dee', 'free-exercise-db', 'Bent_Over_Low-Pulley_Side_Lateral', 'Öne Eğilerek Yan Raise (Alt Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["shoulders"]', '["lower back", "middle back", "traps"]', '["Bir ağırlık seçin ve alt makaranın tutamağını sağ elinizle tutun.", "Gövdeniz yere neredeyse paralel olana kadar belinizden öne eğilin. Bacaklarınız hafif bükülü olmalı, sol elinizi sol uyluğunuzun alt kısmına koyun. Sağ kolunuz omzunuzdan önünüze sarkmalı ve dirsekte hafif bükülü olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Sağ kolunuzu, dirsek hafif bükülü şekilde, kol yere paralel olana ve sağ kulağınızla aynı hizaya gelene kadar yana doğru kaldırın. Bu adımı yaparken nefes verin.", "Nefes alarak ağırlığı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın ve hareketi diğer kolla da yapın."]', 'strength', '["Bent_Over_Low-Pulley_Side_Lateral/0.jpg", "Bent_Over_Low-Pulley_Side_Lateral/1.jpg"]', 360.0, 'Bent Over Low-Pulley Side Lateral', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c0a38724-e9ff-550b-a4b1-cde5cd541bb5', 'free-exercise-db', 'Bent_Over_One-Arm_Long_Bar_Row', 'Tek Kol Long Bar Row (Öne Eğilerek)', 'pull', 'beginner', 'compound', '["barbell"]', '["middle back"]', '["biceps", "lats", "lower back", "traps"]', '["Olimpik halterin uçlarından birine ağırlık yerleştirin. Halterin diğer ucunu iki duvarın köşesine yerleştirdiğinizden veya halterin geriye kayamaması için yere ağır bir nesne koyduğunuzdan emin olun.", "Gövdeniz mümkün olduğunca yere paralel olana kadar öne eğilin ve dizlerinizi hafifçe bükülü tutun.", "Şimdi barı, ağırlığın yerleştirildiği taraftaki plakaların hemen arkasından bir elinizle kavrayın ve diğer elinizi dizinizin üzerine koyun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sırt kaslarını maksimum çalıştırmak için dirseğinizi içeride tutarak barı plakalar alt göğsünüze değene kadar düz bir şekilde yukarı çekin. Ağırlığı kaldırırken sırt kaslarınızı sıkın ve hareketin üst noktasında bir saniye bekleyin. Ağırlığı kaldırırken nefes verin. İpucu: Gövdenizin sallanmasına izin vermeyin. Sadece kol hareket etmelidir.", "Barı yavaşça başlangıç pozisyonuna indirin ve latissimus kaslarınızda güzel bir esneme hissedin. İpucu: Plakaların yere değmesine izin vermeyin. En iyi hareket açıklığını sağlamak için büyük plakalar (16-20 kg) yerine küçük plakalar (11 kg''lık) kullanmanızı öneririm.", "Önerilen tekrar sayısı kadar tekrarlayın ve kolunuzu değiştirin."]', 'strength', '["Bent_Over_One-Arm_Long_Bar_Row/0.jpg", "Bent_Over_One-Arm_Long_Bar_Row/1.jpg"]', 360.0, 'Bent Over One-Arm Long Bar Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('48118813-4f53-57d1-a8e4-7d34e7f2a222', 'free-exercise-db', 'Bent_Over_Two-Arm_Long_Bar_Row', 'Uzun Bar Row (İki Kol, Öne Eğilmiş)', 'pull', 'intermediate', 'compound', '["barbell"]', '["middle back"]', '["biceps", "lats"]', '["Olimpik halterin uç taraflarından birine ağırlık takın. Halterin diğer ucunu iki duvarın köşesine yerleştirdiğinizden veya halterin geriye kayamaması için yere ağır bir nesne koyduğunuzdan emin olun.", "Gövdeniz yere mümkün olduğunca paralel olana kadar öne eğilin ve dizlerinizi hafifçe bükülü tutun.", "Şimdi iki elinizle halteri, ağırlığın takıldığı taraftaki plakaların hemen arkasından tutun ve diğer elinizi dizinize koyun. Bu sizin başlangıç pozisyonunuz olacak.", "Sırt kaslarının maksimum uyarılması için dirseklerinizi içeride tutarak halteri plakalar alt göğsünüze değene kadar düz bir şekilde yukarı çekin. Ağırlığı kaldırırken sırt kaslarınızı sıkın ve hareketin üst noktasında bir saniye bekleyin. Ağırlığı kaldırırken nefes verin. İpucu: Halterin ucuna takarak bir üzengi veya çift saplı kablo aparatı kullanabilirsiniz.", "Latissimus kaslarınızda güzel bir gerilme hissederek halteri yavaşça başlangıç pozisyonuna indirin. İpucu: Plakaların yere değmesine izin vermeyin. En iyi hareket açıklığını sağlamak için büyük plakalar (15-20 kg''lık) yerine küçük plakalar (11 kg''lık) kullanmanızı öneririm.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent_Over_Two-Arm_Long_Bar_Row/0.jpg", "Bent_Over_Two-Arm_Long_Bar_Row/1.jpg"]', 360.0, 'Bent Over Two-Arm Long Bar Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0aab12b0-3861-5fb8-abc6-b3b3a71574db', 'free-exercise-db', 'Bent_Over_Two-Dumbbell_Row', 'Bent Over Row (Çift Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["middle back"]', '["biceps", "lats", "shoulders"]', '["Her elinizde bir dambıl olacak şekilde (avuç içleri gövdenize bakacak biçimde) dizlerinizi hafifçe bükün ve belden öne eğilerek gövdenizi öne getirin; eğilirken sırtınızı neredeyse yere paralel olana kadar düz tuttuğunuzdan emin olun. İpucu: Başınızı yukarıda tuttuğunuzdan emin olun. Ağırlıklar tam önünüzde sarkmalı, kollarınız yere ve gövdenize dik şekilde aşağı sarkmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarken (nefes verirken) dambılları yanlarınıza doğru kaldırın ve dirseklerinizi vücudunuza yakın tutun (ağırlıkları tutmak dışında ön kollarınızla kuvvet uygulamayın). Üst kasılma noktasında sırt kaslarınızı sıkın ve bir saniye bekleyin.", "Nefes alırken ağırlığı yavaşça tekrar başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent_Over_Two-Dumbbell_Row/0.jpg", "Bent_Over_Two-Dumbbell_Row/1.jpg"]', 360.0, 'Bent Over Two-Dumbbell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1c6eec4c-2539-5b72-9854-8bb32af62970', 'free-exercise-db', 'Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'Öne Eğilerek Row (Dambıl, Nötr Tutuş)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["middle back"]', '["biceps", "lats"]', '["Her elinizde bir dambıl olacak şekilde (avuç içleri birbirine bakacak biçimde) dizlerinizi hafifçe bükün ve sırtınızı dik tutarak belden öne eğilin; gövdeniz yere neredeyse paralel olsun. İpucu: Başınızı yukarıda tuttuğunuzdan emin olun. Ağırlıklar tam önünüzde sarkmalı, kollarınız yere ve gövdenize dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarak, nefes verirken dambılları yanınıza doğru kaldırın ve kürek kemiklerinizi birbirine doğru sıkın. Üst kasılma noktasında sırt kaslarınızı sıkın ve bir saniye bekleyin.", "Nefes alırken ağırlığı yavaşça tekrar başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg", "Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg"]', 360.0, 'Bent Over Two-Dumbbell Row With Palms In', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('54aa1dd6-3687-564a-af29-9bc07618ffc1', 'free-exercise-db', 'Bent_Press', 'Bent Press (Kettlebell)', 'pull', 'expert', 'compound', '["kettlebells"]', '["abdominals"]', '["glutes", "hamstrings", "lower back", "quadriceps", "shoulders", "triceps"]', '["Bir kettlebell''i omzunuza clean yapın. Kettlebell''i omzunuza doğru kaldırırken bacaklarınızı ve kalçanızı açarak omuza alın. Bunu yaparken bilek dönmelidir. Bu sizin başlangıç pozisyonunuzdur.", "Kettlebell''in karşı tarafına doğru eğilerek başlayın; gözlerinizi kettlebell''de tutarak boş elinizle yere dokunabilene kadar devam edin. Bunu yaparken, kolunuzu yere dik tutarak dirseğinizi açıp ağırlığı dikey olarak yukarı bastırın.", "Kettlebell başınızın üzerindeyken dik pozisyona dönün. Kettlebell''i omzunuza geri getirin ve istenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Bent_Press/0.jpg", "Bent_Press/1.jpg"]', 360.0, 'Bent Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1b0851cc-dc78-54c9-9229-ef55dd25cbe5', 'free-exercise-db', 'Bicycling', 'Bisiklet Sürme', NULL, 'beginner', NULL, '["other"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için bisiklete oturun ve selenizi boyunuza göre ayarlayın."]', 'cardio', '["Bicycling/0.jpg", "Bicycling/1.jpg"]', 600.0, 'Bicycling', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('04c00a08-6731-59a6-9972-235bd6060416', 'free-exercise-db', 'Bicycling_Stationary', 'Sabit Bisiklet', NULL, 'beginner', NULL, '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için bisiklete oturun ve selenizi boyunuza göre ayarlayın.", "Menüden istediğiniz seçeneği seçin. Açmak için pedal çevirmeye başlamanız gerekebilir. Manuel ayarı kullanabilir veya bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kaloriyi tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz. Direnç seviyesi antrenman boyunca değiştirilebilir. Tutamaklar, uygun bir yoğunlukta kalmanıza yardımcı olmak için kalp atış hızınızı izlemekte kullanılabilir."]', 'cardio', '["Bicycling_Stationary/0.jpg", "Bicycling_Stationary/1.jpg"]', 600.0, 'Bicycling, Stationary', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f38cac06-06d8-54ac-9e79-d16fb7603b6f', 'free-exercise-db', 'Board_Press', 'Board Press', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "forearms", "lats", "shoulders"]', '["Bench''e uzanarak başlayın ve mümkünse başınızı barın ötesine geçirin. 2x6''lık kalaslardan yapılmış bir ila beş tahta birbirine vidalanabilir ve antrenman partneri, bantlar tarafından yerinde tutulabilir ya da sadece tişörtünüzün altına sıkıştırılabilir.", "Ayaklarınızı altınıza çekin ve sırtınızı kavisleyin. Barı ağırlığınızı desteklemek için kullanarak omuzlarınızı bench''ten kaldırın ve geriye çekin, kürek kemiklerinizi birbirine sıkıştırın. Trapez kaslarınızı bench''e doğru bastırmak için ayaklarınızı kullanın. Hareket boyunca bu sıkı vücut pozisyonunu koruyun.", "Standart bench press tutuşunu veya triceps''e odaklanmak için omuz genişliğinde bir tutuşu kullanabilirsiniz. Omuzlarınızı öne açmadan barı rack''ten çıkarın. Bar, bilek ve dirsek her zaman aynı hizada kalmalıdır. Barı sıkmaya ve ikiye ayırmaya çalışmaya odaklanın.", "Barı tahtalara doğru indirin, ardından olabildiğince fazla güçle yukarı itin. Dirsekler kollar tam düzelene kadar içeride tutulmalıdır."]', 'powerlifting', '["Board_Press/0.jpg", "Board_Press/1.jpg"]', 360.0, 'Board Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('005b07f1-fe21-5200-a145-730d6e82b2ec', 'free-exercise-db', 'Body-Up', 'Body-Up', 'push', 'intermediate', 'isolation', '["body only"]', '["triceps"]', '["abdominals", "forearms"]', '["Yerde plank pozisyonu alın. Vücut ağırlığınızı ayak parmaklarınız ve ön kollarınız üzerinde taşımalı, gövdenizi düz tutmalısınız. Ön kollarınız omuz genişliğinde açık olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Avuç içlerinizi yere sıkıca bastırarak dirseklerinizi açın ve vücudunuzu yerden kaldırın. Hareketi yaparken gövdenizi sert tutun.", "Dirseklerinizin bükülmesine izin vererek ön kollarınızı yavaşça yere doğru indirin.", "Tekrarlayın."]', 'strength', '["Body-Up/0.jpg", "Body-Up/1.jpg"]', 360.0, 'Body-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('551bc958-0fab-5b13-819c-fb57faa0f86c', 'free-exercise-db', 'Body_Tricep_Press', 'Triceps Press (Vücut Ağırlığı)', 'push', 'beginner', 'isolation', '["body only"]', '["triceps"]', '[]', '["Bir barı rafa göğüs yüksekliğinde yerleştirin.", "Ayakta, barı omuz genişliğinde bir tutuşla kavrayın ve ayaklarınız bitişik, kollarınız uzanmış şekilde bara yaslanacak biçimde bir iki adım geriye gidin. Bu sizin başlangıç pozisyonunuz olacak.", "Dirseklerinizi bükerek ve kendinizi bara doğru indirerek başlayın.", "Duraklayın, ardından dirseklerinizi açarak hareketi tersine çevirin.", "Vücut ağırlığının ötesine geçmek için omuzlarınızın üzerine zincir ekleyin."]', 'strength', '["Body_Tricep_Press/0.jpg", "Body_Tricep_Press/1.jpg"]', 360.0, 'Body Tricep Press', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('127b1500-dd3f-58af-8c47-b147a9b25a1e', 'free-exercise-db', 'Bodyweight_Flyes', 'Vücut Ağırlığı Fly (EZ Bar)', 'push', 'intermediate', 'isolation', '["e-z curl bar"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["İki eşit yüklü EZ barı yere yan yana yerleştirin. Barların yuvarlanabildiğinden emin olun.", "Barların üzerinde şınav pozisyonuna geçin; ağırlığınızı ayak parmaklarınız ve elleriniz üzerinde taşıyın, kollarınız uzatılmış ve vücudunuz düz olsun.", "Ellerinizi barların üzerine koyun. Bu sizin başlangıç pozisyonunuzdur.", "Yavaş ve kontrollü bir hareketle ellerinizi vücudunuzun orta hattından uzaklaştırın ve barları birbirinden ayırarak yuvarlayın. Hareketin bu kısmında nefes alın.", "Barları olabildiğince açtıktan sonra, onları tekrar birbirine çekerek başlangıç pozisyonuna dönün. Bu hareketi yaparken nefes verin."]', 'strength', '["Bodyweight_Flyes/0.jpg", "Bodyweight_Flyes/1.jpg"]', 360.0, 'Bodyweight Flyes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7dcf4659-446a-5cee-9beb-e2b3610d1923', 'free-exercise-db', 'Bodyweight_Mid_Row', 'Vücut Ağırlığıyla Orta Row', 'pull', 'intermediate', 'compound', '["other"]', '["middle back"]', '["biceps", "lats"]', '["Bir barfiks aparatında avuç içleriniz sizden uzağa bakacak şekilde orta ile geniş arası bir tutuşla tutunarak başlayın. Asılı pozisyondan dizlerinizi göğsünüze çekin, geriye yaslanın ve bacaklarınızı barfiks aparatının kendi tarafınıza doğru geçirin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kollarınız düz haldeyken dirseklerinizi bükün ve kürek kemiklerinizi geriye çekerek bacaklarınız barfiks aparatına temas edene kadar vücudunuzu yukarı kaldırın.", "Kısa bir duraklamanın ardından başlangıç pozisyonuna dönün."]', 'strength', '["Bodyweight_Mid_Row/0.jpg", "Bodyweight_Mid_Row/1.jpg"]', 360.0, 'Bodyweight Mid Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6adff14f-647e-5e52-96b5-82e0ca037c07', 'free-exercise-db', 'Bodyweight_Squat', 'Squat (Vücut Ağırlığı)', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Ayaklarınızı omuz genişliğinde açarak ayakta durun. Ellerinizi başınızın arkasına koyabilirsiniz. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi ve kalçanızı bükerek, kalçanızı geriye doğru oturtarak harekete başlayın.", "Yapabiliyorsanız tam derinliğe kadar inin ve hareketi hızla tersine çevirerek başlangıç pozisyonuna dönün. Çömelirken başınızı ve göğsünüzü yukarıda tutun ve dizlerinizi dışarı doğru itin."]', 'strength', '["Bodyweight_Squat/0.jpg", "Bodyweight_Squat/1.jpg"]', 360.0, 'Bodyweight Squat', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ebdd62b4-a8bf-5dba-b851-8d8633f302b7', 'free-exercise-db', 'Bodyweight_Walking_Lunge', 'Yürüyüşlü Lunge (Vücut Ağırlığı)', 'push', 'beginner', 'compound', '[]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Ayaklarınız omuz genişliğinde açık ve elleriniz kalçanızda olacak şekilde ayakta durarak başlayın.", "Bir bacağınızla öne adım atın ve kalçanızı indirmek için dizlerinizi bükün. Arka dizinizin neredeyse yere değdiği noktaya kadar inin. Duruşunuz dik kalmalı ve ön dizinizin ön ayağınızın üzerinde kalmalıdır.", "Ön ayağınızın topuğuyla iterek ve iki dizinizi açarak kendinizi yukarı kaldırın.", "Arka ayağınızla öne adım atarak lunge hareketini diğer bacakta tekrarlayın."]', 'strength', '["Bodyweight_Walking_Lunge/0.jpg", "Bodyweight_Walking_Lunge/1.jpg"]', 360.0, 'Bodyweight Walking Lunge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0e3163ed-89b6-57a1-adf7-7ee1bfcb2753', 'free-exercise-db', 'Bosu_Ball_Cable_Crunch_With_Side_Bends', 'Bosu Üzerinde Kablo Mekik (Yan Eğilmeli)', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["Kablo makinesinin her koluna standart bir sap bağlayın ve bunları en aşağı konuma getirin.", "Bir Bosu topu alın ve kablo makinesinin önüne, ortasına yerleştirin.", "Belinizin kavisli kısmı topun etrafını saracak şekilde Bosu topunun üzerine uzanın. Kalçanız yere değmeden yere yakın olmalı.", "İki elinizle geriye uzanın ve her kablonun sapını kavrayın.", "Ayaklarınız geniş duruşta olacak şekilde, kollarınızı önünüze ve dizlerinizin arasına düz bir şekilde uzatın. Elleriniz diz seviyesinde olmalı.", "Kollarınızı düz ve kablonun yukarı doğru açısıyla aynı hizada tutun. Kollarınızı düşürmeden veya bükmeden gövdenizi mekik hareketiyle yükseltin.", "Kollarınızla sert pozisyonu koruyun. Sırtınız Bosu topunun etrafında kavisli ve karın kaslarınız uzamış şekilde yavaşça başlangıç pozisyonuna inin.", "Aynı hareket dizisini tükenene kadar tekrarlayın.", "Tükenmeye ulaştığınızda karın kaslarınızı sıkı tutun ve sırtınız Bosu topundan kalkacak şekilde gövdenizi plank pozisyonuna kaldırın.", "Kollarınızı yanlarınıza indirin; düz tutun. Dönüşümlü yan eğilmeler yapmaya başlayın; topuklarınıza uzanın! Bu bitirme hareketi yan karın kaslarınıza odaklanır."]', 'strength', '["Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg", "Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg"]', 360.0, 'Bosu Ball Cable Crunch With Side Bends', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e8d26695-7720-5b4c-8dcd-6ac8af31f5cd', 'free-exercise-db', 'Bottoms-Up_Clean_From_The_Hang_Position', 'Ters Tutuşlu Hang Clean (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["forearms"]', '["biceps", "shoulders"]', '["Bir elinizde kettlebell ile dik durarak egzersize başlayın.", "Kettlebell''i kuvvetle geriye doğru sallayın, ardından hareketi kuvvetle tersine çevirin. Kettlebell sapını olabildiğince sert sıkın ve kettlebell''i omzunuza kaldırın."]', 'strength', '["Bottoms-Up_Clean_From_The_Hang_Position/0.jpg", "Bottoms-Up_Clean_From_The_Hang_Position/1.jpg"]', 360.0, 'Bottoms-Up Clean From The Hang Position', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f945cc90-11e6-5a34-891c-a28ead1cffb1', 'free-exercise-db', 'Bottoms_Up', 'Bottoms Up (Alt Karın)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Yerde sırtüstü uzanarak başlayın. Bacaklarınız düz, kollarınız yanınızda olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Hareketi yapmak için kalça ve dizlerinizi bükerek dizlerinizi göğsünüze doğru çekin. Ardından bacaklarınızı tam üzerinize, yere dik olacak şekilde uzatın. Leğen kemiğinizi döndürüp yukarı kaldırarak kalçanızı yerden kaldırın.", "Kısa bir duraklamanın ardından başlangıç pozisyonuna dönün."]', 'strength', '["Bottoms_Up/0.jpg", "Bottoms_Up/1.jpg"]', 360.0, 'Bottoms Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c2d4efb9-ac33-54d6-ab12-9a0e777f6896', 'free-exercise-db', 'Box_Jump_Multiple_Response', 'Box Jump (Seri Tekrar)', 'push', 'beginner', 'compound', '["other"]', '["hamstrings"]', '["abductors", "adductors", "calves", "glutes", "quadriceps"]', '["Kutuya veya platforma yaklaşık bir kol boyu mesafede dönük, rahat bir duruş alın. Kollarınız yanlarda aşağıda ve bacaklarınız hafif bükülü olmalıdır.", "İlk ivme için kollarınızı kullanarak yukarı ve öne zıplayın ve her iki ayağınızla aynı anda kutunun veya platformun üzerine inin.", "Hemen aşağı inin veya zıplayarak orijinal başlangıç yerine dönün; ardından diziyi tekrarlayın."]', 'plyometrics', '["Box_Jump_Multiple_Response/0.jpg", "Box_Jump_Multiple_Response/1.jpg"]', 480.0, 'Box Jump (Multiple Response)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('12e5c581-3390-5644-bc31-8815070e1dea', 'free-exercise-db', 'Box_Skip', 'Box Skip', 'push', 'beginner', 'compound', '["other"]', '["hamstrings"]', '["abductors", "adductors", "calves", "glutes", "quadriceps"]', '["Yaklaşık 2,5 metre arayla sıralanmış birkaç kutuya ihtiyacınız olacak.", "İlk kutuya dönük olarak, bir bacağınız diğerinin biraz gerisinde olacak şekilde başlayın.", "Kalçanızla mümkün olduğunca fazla yükseklik kazanmaya çalışarak arka bacağınızdan güç alıp itin.", "Kutuya iner inmez, yükseklik ve mesafe kazanmak için diğer bacağınızı öne ve yukarı doğru sürerek kutudan fırlayın. İlk kutuya inen aynı bacakla ilk iki kutu arasına inin.", "Ardından bir sonraki kutuya adım atın ve tekrarlayın."]', 'plyometrics', '["Box_Skip/0.jpg", "Box_Skip/1.jpg"]', 480.0, 'Box Skip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('11ca9904-7fa9-59ed-8b70-9f362eb4c39f', 'free-exercise-db', 'Box_Squat', 'Box Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["adductors", "calves", "glutes", "hamstrings", "lower back"]', '["Box squat, istediğiniz derinliğe çömelmenizi ve squat hareketinde patlayıcı güç geliştirmenizi sağlar. Arkanızda uygun yükseklikte bir kutu olacak şekilde bir power rack içinde başlayın. Genellikle paralel squat''a ulaşmanızı sağlayan bir kutu yüksekliği hedeflenir, ancak isterseniz daha yüksek ya da daha alçakta çalışabilirsiniz.", "Barın altına girip barı omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine doğru sıkın ve dirseklerinizi öne doğru döndürerek barı omuzlarınızın üzerinde bükmeye çalışın. Barı raftan çıkarın, belinizde sıkı bir kavis oluşturun ve geriye adım atarak pozisyon alın. Sırt, kalça, addüktör ve arka bacak kaslarına daha fazla vurgu için ayaklarınızı daha geniş, ön bacak (quad) gelişimi için daha yakın yerleştirin. Başınızı karşıya dönük tutun.", "Sırtınız, omuzlarınız ve karın bölgeniz sıkı iken dizlerinizi ve kalçanızı dışarı doğru iterek inişe başlayın. Kutunun üzerine oturana kadar kalçanızla geriye oturun. İdeal olarak baldırlarınız yere dik olmalıdır. Kutuya ulaştığınızda bekleyin ve kalça fleksörlerini gevşetin. Kutudan asla sekmeyin.", "Ağırlığı topuklarınızda tutup ayaklarınızı ve dizlerinizi dışarı iterek, hareketi başınızla yönlendirirken kutudan yukarı doğru itin. Baştan ayağa sıkılığı koruyarak yukarı çıkmaya devam edin."]', 'powerlifting', '["Box_Squat/0.jpg", "Box_Squat/1.jpg"]', 360.0, 'Box Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('07b614be-6048-5ae0-9c42-3b07d51c8fa7', 'free-exercise-db', 'Box_Squat_with_Bands', 'Box Squat (Halter, Direnç Bandı)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings", "lower back"]', '["Arkanızda uygun yükseklikte bir kutu olacak şekilde power rack içinde başlayın. Bantları halterin kollarına takın ve uygun gerginlik sağlanacak şekilde bant çivilerine, rafa veya dambıllara sabitleyin. Dambıl kullanılıyorsa hareket etmeyecek şekilde sabitleyin. Ayrıca kullandığınız dambılların bantlar için yeterince ağır olduğundan emin olun. Dambılları yerinde tutmak için ek plakalar kullanılabilir. Daha fazla gerginlik gerekiyorsa zemindeki tabanı genişletebilir veya bantları kısaltabilirsiniz. Genellikle paralel squat''a getirecek bir kutu yüksekliği hedeflenir, ancak isterseniz daha yüksek veya daha alçak çalışabilirsiniz.", "Halterin altına girip halteri omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine doğru sıkın ve halteri omuzlarınızın üzerinde bükmeye çalışır gibi dirseklerinizi öne doğru döndürün. Halteri raftan çıkarırken belinizde sıkı bir kavis oluşturun ve geriye adım atarak pozisyon alın. Sırt, kalça, iç bacak ve arka bacağa daha fazla vurgu için ayaklarınızı daha geniş, ön bacak gelişimi için daha dar yerleştirin. Başınızı ileri bakacak şekilde tutun.", "Sırtınız, omuzlarınız ve karın bölgeniz sıkıyken dizlerinizi ve kalçanızı dışarı doğru iterek inişe başlayın. Kutunun üzerine oturana kadar kalçanızla geriye oturun. İdeal olarak kaval kemiklerinizin yere dik olması gerekir. Kutuya ulaştığınızda durun ve kalça fleksörlerini gevşetin. Kutudan asla sıçramayın.", "Ağırlığı topuklarınızda tutup ayaklarınızı ve dizlerinizi dışarı iterek hareketi başınızla yönlendirerek kutudan yukarı doğru çıkın. Baştan ayağa sıkılığı koruyarak yükselmeye devam edin. Halteri rafa geri yerleştirirken dikkatli olun."]', 'powerlifting', '["Box_Squat_with_Bands/0.jpg", "Box_Squat_with_Bands/1.jpg"]', 360.0, 'Box Squat with Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('11492d08-2225-5435-8ee7-434c9ae57579', 'free-exercise-db', 'Box_Squat_with_Chains', 'Box Squat (Halter, Zincirli)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings", "lower back"]', '["Arkanızda uygun yükseklikte bir box bulunan bir power rack içinde başlayın. Genellikle sizi paralel squat seviyesine getiren bir box yüksekliği hedeflenir, ancak isterseniz daha yüksek veya alçak da çalışabilirsiniz.", "Zincirleri kurmak için önce ana zinciri barın kollarının (sleeve) üzerinden geçirin. Ağır zincir, bir kanca (snap hook) ile bağlanmalıdır. Ana zincirin uzunluğunu, hareketin en üst noktasında birkaç halkası hâlâ yerde kalacak şekilde ayarlayın.", "Barın altına girerek ve omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine doğru sıkın ve barı omuzlarınızın üzerinde bükmeye çalışır gibi dirseklerinizi öne doğru döndürün. Barı raftan alırken belinizde sıkı bir kavis oluşturun ve geriye doğru adım atarak yerinizi alın. Sırt, kalça, iç bacak kasları (adductor) ve arka bacak üzerindeki vurguyu artırmak için ayaklarınızı daha geniş, ön bacak (quad) gelişimi için daha dar açın. Başınızı ileri bakacak şekilde tutun.", "Sırtınız, omuzlarınız ve karın bölgeniz sıkı haldeyken dizlerinizi ve kalçanızı dışarı doğru iterek inişe başlayın. Box''ın üzerine oturana kadar kalçanızı geriye atın. İdeal olarak kaval kemikleriniz yere dik olmalıdır. Box''a ulaştığınızda duraklayın ve kalça fleksörlerini gevşetin. Box''tan asla sekmeyin.", "Ağırlığı topuklarınıza vererek ve ayaklarınızı ve dizlerinizi dışarı iterek, hareketi başınızla yönlendirerek box''tan yukarı doğru güç alın. Baştan ayağa sıkı kalmaya devam ederek yukarı çıkın."]', 'strength', '["Box_Squat_with_Chains/0.jpg", "Box_Squat_with_Chains/1.jpg"]', 360.0, 'Box Squat with Chains', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6ff4f725-4f15-5104-ab85-4f8eaee41131', 'free-exercise-db', 'Brachialis-SMR', 'Brachialis Foam Roller (SMR)', 'static', 'intermediate', NULL, '["foam roll"]', '["biceps"]', '[]', '["Yan yatın ve üst kolunuz foam roller''a temas etsin. Üst kol, vücudunuzla az çok aynı hizada olmalı ve biceps''in dış kısmı foam roller''a bastırılmalıdır.", "Ağırlığınızı kolunuz ve ayaklarınız üzerinde taşıyarak kalçanızı yerden kaldırın. 10-30 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["Brachialis-SMR/0.jpg", "Brachialis-SMR/1.jpg"]', 150.0, 'Brachialis-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2aec6b4d-dae7-54e4-b585-7e8c86db2a31', 'free-exercise-db', 'Bradford_Rocky_Presses', 'Bradford/Rocky Press (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["shoulders"]', '["triceps"]', '["Askeri press bench''ine oturun ve barı omuz seviyesinde, pronasyon tutuşla (avuç içleri öne bakacak şekilde) tutun. İpucu: Tutuşunuz omuz genişliğinden geniş olmalı ve halter aşağı inerken ön kol ile üst kol arasında 90 derecelik bir açı oluşturmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Halteri doğru tutuşla aldıktan sonra kollarınızı kilitleyerek barı başınızın üzerine kaldırın.", "Şimdi nefes alırken barı yavaşça başınızın arkasına doğru indirin.", "Nefes vererek barı başlangıç pozisyonuna geri kaldırın.", "Nefes alırken barı yavaşça başlangıç pozisyonuna indirin. Bu bir tekrardır.", "Önerilen tekrar sayısını tamamlayana kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Bradford_Rocky_Presses/0.jpg", "Bradford_Rocky_Presses/1.jpg"]', 360.0, 'Bradford/Rocky Presses', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('26e4f251-b8de-5e6f-a226-98e5d6043e3f', 'free-exercise-db', 'Butt-Ups', 'Butt-Up (Dirsek Üzerinde)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Şınav pozisyonuna benzer şekilde başlayın, ancak dirsekleriniz yerde ve ön kollarınızın üzerinde dinleniyor olsun. Kollarınız 90 derecelik açıyla bükülü olmalıdır.", "Sırtınızı tamamen düz tutmak yerine hafifçe kamburlaştırın.", "Kaburga kafesiniz ile kalçanız arasındaki mesafeyi kapatmak için karın kaslarınızı sıkıca kasarak kalçanızı tavana doğru kaldırın. Sonuçta yüksek bir köprü pozisyonuna geleceksiniz. Hareketin bu kısmında nefes verin.", "Nefes alırken yavaşça başlangıç pozisyonuna inin. İpucu: Sırtınızın aşağı doğru çökmesine izin vermeyin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Butt-Ups/0.jpg", "Butt-Ups/1.jpg"]', 360.0, 'Butt-Ups', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c73a416a-f7cf-5529-852d-443e3f5a67cd', 'free-exercise-db', 'Butt_Lift_Bridge', 'Köprü (Kalça Kaldırma)', 'push', 'beginner', 'isolation', '["body only"]', '["glutes"]', '["hamstrings"]', '["Ellerinizi yanlarınıza koyup dizlerinizi bükerek sırtüstü düz bir şekilde yere uzanın. Ayaklarınız yaklaşık omuz genişliğinde olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Esas olarak topuklarınızla iterek, sırtınızı düz tutarak kalçanızı yerden kaldırın. Hareketin bu kısmında nefes verin ve üstte bir saniye bekleyin.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün."]', 'strength', '["Butt_Lift_Bridge/0.jpg", "Butt_Lift_Bridge/1.jpg"]', 360.0, 'Butt Lift (Bridge)', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('856d2911-733d-5422-b3ba-9ae0cc57f8e2', 'free-exercise-db', 'Butterfly', 'Butterfly (Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["chest"]', '[]', '["Sırtınız pede düz bir şekilde yaslanacak şekilde makineye oturun.", "Tutamakları kavrayın. İpucu: Üst kollarınız yere paralel olmalıdır; makineyi buna göre ayarlayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Göğüs kaslarınızı ortada sıkarak tutamakları yavaşça birbirine doğru itin. Hareketin bu kısmında nefes verin ve kasılmayı bir saniye tutun.", "Nefes alırken göğüs kaslarınız tamamen esneyene kadar yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Butterfly/0.jpg", "Butterfly/1.jpg"]', 360.0, 'Butterfly', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b89b2990-7cc9-54b2-92eb-95881f01843c', 'free-exercise-db', 'Cable_Chest_Press', 'Chest Press (Kablo)', 'push', 'beginner', 'compound', '["cable"]', '["chest"]', '["shoulders", "triceps"]', '["Ağırlığı uygun bir miktara ayarlayın, oturun ve sapları kavrayın. Üst kollarınız vücudunuzla yaklaşık 45 derece açı yapmalı, başınız ve göğsünüz dik olmalıdır. Dirsekler yaklaşık 90 derece bükülü olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi açarak, sapları önünüzde birbirine doğru itmeye başlayın. Hareketi yaparken kürek kemiklerinizi geride sabit tutun.", "Tam açılma noktasında kısa bir süre bekledikten sonra, kablolarda gerginliği koruyarak başlangıç pozisyonuna dönün.", "Bu hareketi sırtınız pedden ayrık, eğimli veya ters eğimli şekilde ya da kolları dönüşümlü kullanarak da yapabilirsiniz."]', 'strength', '["Cable_Chest_Press/0.jpg", "Cable_Chest_Press/1.jpg"]', 360.0, 'Cable Chest Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('cc4f116b-a15e-5cfc-9545-5d2541e9092e', 'free-exercise-db', 'Cable_Crossover', 'Cable Crossover', 'push', 'beginner', 'isolation', '["cable"]', '["chest"]', '["shoulders"]', '["Başlangıç pozisyonuna geçmek için makaraları yüksek bir konuma (başınızın üzerine) getirin, kullanılacak direnci seçin ve her elinize bir makara tutamağı alın.", "Kollarınızı önünüzde birleştirirken iki makara arasındaki hayali düz çizginin önüne adım atın. Gövdeniz belden hafifçe öne eğik olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Biceps tendonundaki stresi önlemek için dirseklerinizi hafif bükülü tutarak, göğsünüzde bir gerilme hissedene kadar kollarınızı geniş bir yay çizerek yanlara (iki yana düz) açın. Hareketin bu kısmında nefes alın. İpucu: Hareket boyunca kolların ve gövdenin sabit kalması, hareketin yalnızca omuz ekleminde gerçekleşmesi gerektiğini unutmayın.", "Nefes verirken kollarınızı başlangıç pozisyonuna geri getirin. Ağırlıkları indirirken kullandığınız aynı hareket yayını kullandığınızdan emin olun.", "Başlangıç pozisyonunda bir saniye bekleyin ve hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Crossover/0.jpg", "Cable_Crossover/1.jpg"]', 360.0, 'Cable Crossover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a0682c7a-8b30-51e5-b93b-985241ec20ae', 'free-exercise-db', 'Cable_Crunch', 'Kablo Mekik', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["İp aparatı bulunan yüksek bir makaranın altında diz çökün.", "Kablo ip aparatını kavrayın ve ellerinizi yüzünüzün yanına gelecek şekilde ipi aşağı indirin.", "Kalçanızı hafifçe bükün ve ağırlığın alt sırtınızı geriye doğru germesine izin verin. Bu sizin başlangıç pozisyonunuz olacak.", "Kalçanız sabitken, karın kaslarınızı kasarak belinizden bükülün; böylece dirsekleriniz uyluklarınızın ortasına doğru ilerlesin. Hareketin bu kısmında nefes verin ve kasılmayı bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün. İpucu: Hareket boyunca karın kaslarınızda sürekli gerginlik olduğundan emin olun. Ayrıca işin büyük kısmını alt sırtın üstlenmesine neden olacak kadar ağır bir ağırlık seçmeyin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Crunch/0.jpg", "Cable_Crunch/1.jpg"]', 360.0, 'Cable Crunch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6e80ff71-8f2e-579c-9775-973d4b64e71a', 'free-exercise-db', 'Cable_Deadlifts', 'Deadlift (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["quadriceps"]', '["forearms", "glutes", "hamstrings", "lower back"]', '["Kabloları kulelerin en altına indirin ve uygun bir ağırlık seçin. Direklerin tam ortasında durun.", "Başlamak için kalça ve dizlerinizi bükerek tutacaklara uzanabilecek kadar çömelin.", "Tutacakları kavradıktan sonra yukarı çıkmaya başlayın. Topuklarınızdan iterek kalça ve dizlerinizi açın, ellerinizi yanlarınızda sarkık tutun. Hareket boyunca başınızı ve göğsünüzü yukarıda tutun.", "Tam ayakta duruş pozisyonuna ulaştıktan sonra başlangıç pozisyonuna dönün ve tekrarlayın."]', 'strength', '["Cable_Deadlifts/0.jpg", "Cable_Deadlifts/1.jpg"]', 360.0, 'Cable Deadlifts', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bd9b00ad-39e2-545b-8aeb-17db08d58d91', 'free-exercise-db', 'Cable_Hammer_Curls_-_Rope_Attachment', 'Hammer Curl (Kablo, Halat)', 'pull', 'beginner', 'isolation', '["cable"]', '["biceps"]', '[]', '["Halat aparatını alt makaraya takın ve makineye yaklaşık 30 cm uzaklıkta, makineye dönük şekilde durun.", "Halatı nötr (avuç içleri içe bakacak) tutuşla kavrayın ve sırtınızın doğal kavisini koruyup gövdenizi sabit tutarak dik durun.", "Dirseklerinizi yanlarınıza yaklaştırın ve tüm hareket boyunca sabit tutun. İpucu: Yalnızca ön kollar hareket etmelidir; üst kollarınız değil. Bu sizin başlangıç pozisyonunuzdur.", "Biceps''inizi kullanarak nefes verirken kollarınızı biceps ön kollarınıza değene kadar yukarı çekin. İpucu: Dirseklerinizi içeride ve üst kollarınızı sabit tuttuğunuzu unutmayın.", "Biceps''inizi sıkarak 1 saniyelik bir kasılmanın ardından ağırlığı yavaşça başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Hammer_Curls_-_Rope_Attachment/0.jpg", "Cable_Hammer_Curls_-_Rope_Attachment/1.jpg"]', 360.0, 'Cable Hammer Curls - Rope Attachment', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d1fbcb54-16b5-597c-ad8e-2335be690fa1', 'free-exercise-db', 'Cable_Hip_Adduction', 'Hip Adduction (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["quadriceps"]', '[]', '["Alt makaranın önünde, bir bacağınız makaranın yanında ve diğeri uzakta olacak şekilde ileriye dönük durun.", "Ayak bileği kayışını kabloya ve makaraya yakın olan bacağınızın ayak bileğine bağlayın.", "Şimdi ağırlık yığınından uzağa doğru geniş bir duruşla adım atın ve makara sisteminin barını kavrayın.", "Kayışsız ayağınızın (uzaktaki ayak) üzerinde durun ve kayışlı bacağın alt makaraya doğru çekilmesine izin verin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi iç bacak kaslarınızı kullanarak kalçayı adduksiyonla kapatıp kayışlı bacağı uzaktaki bacağın önünden geçirerek hareketi gerçekleştirin. Hareketin bu kısmında nefes verin.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın, ardından aynı hareketi karşı bacakla tekrarlayın."]', 'strength', '["Cable_Hip_Adduction/0.jpg", "Cable_Hip_Adduction/1.jpg"]', 360.0, 'Cable Hip Adduction', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f16372c9-bccb-5c22-a997-66a39d42930f', 'free-exercise-db', 'Cable_Incline_Pushdown', 'Incline Pushdown (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["lats"]', '[]', '["Düz bar aparatı takılı yüksek makaralı bir makineye sırtınız dönük şekilde eğimli bir bankta uzanın.", "Düz bar aparatını baş üstünde, avuç içleri aşağı bakacak (pronated) omuz genişliğinde bir tutuşla kavrayın ve kollarınızı önünüze uzatın. Bar üst uyluklarınızdan yaklaşık 2 inç (5 cm) uzakta olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı sabit tutarak, bar tam başınızın üzerine gelene kadar kollarınızı yarım daire çizerek geriye kaldırın. Hareketin bu kısmında nefes alın.", "Kanat (lat) kaslarınızı kullanarak yavaşça başlangıç pozisyonuna dönün ve başlangıç pozisyonuna ulaştığınızda kasılmayı tutun. Hareketin bu kısmında nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Incline_Pushdown/0.jpg", "Cable_Incline_Pushdown/1.jpg"]', 360.0, 'Cable Incline Pushdown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f121fb9b-1c18-52fd-a1a8-9d65b5bbe8bf', 'free-exercise-db', 'Cable_Incline_Triceps_Extension', 'Incline Triceps Extension (Kablo)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Düz bar aparatı takılı yüksek makara makinesine sırtınız dönük olacak şekilde incline bench üzerine uzanın.", "Düz bar aparatını başınızın üzerinde pronasyon (üstten; avuç içleri aşağı) dar bir tutuşla (omuz genişliğinden daha dar) kavrayın ve dirseklerinizi yanlarınıza yakın tutun. Üst kollarınız yerden ölçüldüğünde yaklaşık 25 derecelik bir açı oluşturmalı.", "Üst kollarınızı sabit tutarak, triceps''i kasarken kollarınızı açın. Hareketin bu kısmında nefes verin ve kasılmayı bir saniye tutun.", "Yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Incline_Triceps_Extension/0.jpg", "Cable_Incline_Triceps_Extension/1.jpg"]', 360.0, 'Cable Incline Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a9bd260f-46c4-509b-b8c0-2505bf98672b', 'free-exercise-db', 'Cable_Internal_Rotation', 'İç Rotasyon (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["shoulders"]', '[]', '["Alçak makaranın yanında yan dönük oturun (bacaklarınız önünüzde uzatılmış veya çapraz olabilir) ve tek el kablo aparatını makaraya en yakın kolunuzla tutun. İpucu: Makara yüksekliğini ayarlayabiliyorsanız oturmak için düz bir bench kullanabilirsiniz.", "Dirseğinizi vücudunuzun yanına yerleştirin; dirsek 90° bükülü ve kol makaraya doğru bakıyor olsun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Ön kolunuz karın kaslarınızın önünden geçene kadar omzunuzu içe doğru döndürerek tek el kablo aparatını vücudunuza doğru çekin. Hayali bir yarım daire çizmiş olacaksınız. İpucu: Ön kol her zaman gövdenize dik kalmalıdır.", "Yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın ve ardından hareketi diğer kolla yapın."]', 'strength', '["Cable_Internal_Rotation/0.jpg", "Cable_Internal_Rotation/1.jpg"]', 360.0, 'Cable Internal Rotation', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6fe34a0b-30e1-545b-b78e-869a29369538', 'free-exercise-db', 'Cable_Iron_Cross', 'Iron Cross (Kablo)', 'push', 'beginner', 'isolation', '["cable"]', '["chest"]', '[]', '["Makaraları yüksek konuma getirerek başlayın, kullanılacak direnci seçin ve her elinize bir tutamak alın.", "İki makaranın tam ortasında durun ve kollarınızı iki yana açın. Başınız ve göğsünüz yukarıda olmalı, kollarınız \"T\" harfi oluşturmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi gergin tutarak kollarınızı düz bir şekilde yanlarınıza doğru çekin.", "Maksimum kasılma noktasında bekledikten sonra kollarınızı başlangıç pozisyonuna geri getirin.", "Hareketi belirlenen tekrar sayısı kadar sürdürün."]', 'strength', '["Cable_Iron_Cross/0.jpg", "Cable_Iron_Cross/1.jpg"]', 360.0, 'Cable Iron Cross', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('72a6d879-eb92-5602-81e0-c459eb32d83c', 'free-exercise-db', 'Cable_Judo_Flip', 'Judo Flip (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["abdominals"]', '[]', '["Halat aparatını kuleye bağlayın ve kabloyu en alt makara konumuna getirin. Kabloya yan dönük, ayaklarınız geniş açık şekilde durun ve halatı iki elinizle tutun.", "Halatı judo atışı yapar gibi omzunuzun üzerinden getirirken gövdenizi makaradan uzağa doğru döndürün.", "Döndüğünüz ve öne doğru kasıldığınız sırada ağırlığınızı ayaklarınız arasında kaydırarak kabloyu aşağı çekin.", "Başlangıç pozisyonuna dönün ve tükenene kadar tekrarlayın.", "Ardından pozisyonunuzu değiştirin ve aynı hareket serisini diğer tarafta tekrarlayın."]', 'strength', '["Cable_Judo_Flip/0.jpg", "Cable_Judo_Flip/1.jpg"]', 360.0, 'Cable Judo Flip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f7fe9fa1-80f5-56eb-8400-7e239d79907e', 'free-exercise-db', 'Cable_Lying_Triceps_Extension', 'Yatarak Triceps Extension (Kablo)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Düz bir bench''e uzanın ve alt makaranın düz bar aparatını dar bir üstten tutuşla kavrayın. İpucu: Bunu yapmanın en kolay yolu, uzanırken birinin barı size vermesidir.", "Kollarınız uzatılmış halde barı gövdenizin üzerinde konumlandırın. Kollarınız ve gövdeniz 90 derecelik bir açı oluşturmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kollarınızı sabit ve dirseklerinizi içeride tutarak dirseğinizden bükülerek barı indirin. Bar alnınıza hafifçe değene kadar inin. Hareketin bu kısmında nefes alın.", "Barı başlangıç pozisyonuna geri kaldırırken triceps''inizi kasın. Hareketin bu kısmında nefes verin.", "Kasılmış pozisyonda bir saniye bekleyin ve önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Lying_Triceps_Extension/0.jpg", "Cable_Lying_Triceps_Extension/1.jpg"]', 360.0, 'Cable Lying Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('631b0bef-f8c7-55f6-8062-a55d94259c50', 'free-exercise-db', 'Cable_One_Arm_Tricep_Extension', 'Tek Kol Triceps Extension (Kablo)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Sağ elinizle, yüksek makaraya bağlı tek bir sapı avuç içi yukarı bakacak (supinated) şekilde kavrayın. Ağırlık bloğunun tam önünde durmalısınız.", "Şimdi sapı, üst kolunuz ve dirseğiniz vücudunuzun yanına kilitlenecek şekilde aşağı çekin. Üst kolunuz ile ön kolunuz dar bir açı (90 dereceden az) oluşturmalıdır. Diğer kolunuzu belinizin yanında tutabilir, daha iyi denge için bir bacağınızı önde diğerini arkada konumlandırabilirsiniz. Bu sizin başlangıç pozisyonunuzdur.", "Triceps''i kasarak tek saplı aparatı kolunuz düzleşene kadar yanınıza doğru aşağı hareket ettirin. Bu hareketi yaparken nefes verin. İpucu: Yalnızca ön kollar hareket etmelidir. Üst kollarınız her zaman sabit kalmalıdır.", "Triceps''i sıkın ve bu kasılmış pozisyonda bir saniye bekleyin.", "Sapı yavaşça başlangıç pozisyonuna döndürün.", "Önerilen tekrar sayısı kadar tekrarlayın, ardından aynı hareketi diğer kolla yapın."]', 'strength', '["Cable_One_Arm_Tricep_Extension/0.jpg", "Cable_One_Arm_Tricep_Extension/1.jpg"]', 360.0, 'Cable One Arm Tricep Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('aa5e6f8a-3d2d-582d-8bb5-cc8d34c959bd', 'free-exercise-db', 'Cable_Preacher_Curl', 'Preacher Curl (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["biceps"]', '["forearms"]', '["Bir preacher bench''i makara makinesinin yaklaşık 60 cm önüne yerleştirin.", "Düz bir barı alt makaraya takın.", "Dirseğiniz ve üst kollarınız preacher bench''in minderinin üzerinde sağlam şekilde duracak biçimde oturun ve birinin barı alt makaradan size vermesini sağlayın.", "Barı kavrayın ve kollarınızı preacher bench minderinin üzerinde tamamen uzatın. Bu sizin başlangıç pozisyonunuz olacak.", "Şimdi ağırlığı omuzlarınıza doğru çekmeye başlayın ve hareketin üst noktasında biceps''i güçlü bir şekilde sıkın. Bu hareketi yaparken nefes verin. Ayrıca üstte bir saniye bekleyin.", "Şimdi ağırlığı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Preacher_Curl/0.jpg", "Cable_Preacher_Curl/1.jpg"]', 360.0, 'Cable Preacher Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f54d6cdb-3c5a-5294-b2b2-64852995c18e', 'free-exercise-db', 'Cable_Rear_Delt_Fly', 'Arka Omuz Fly (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["shoulders"]', '[]', '["Makaraları uygun yüksekliğe ayarlayın ve ağırlığı seçin. Makaralar başınızın üzerinde olmalıdır.", "Sol makarayı sağ elinizle, sağ makarayı sol elinizle tutarak önünüzde çaprazlayın. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı geriye ve dışa doğru hareket ettirerek hareketi başlatın; hareketi yaparken kollarınızı düz tutun.", "Hareketin sonunda bekleyin, ardından tutamakları başlangıç pozisyonuna geri getirin."]', 'strength', '["Cable_Rear_Delt_Fly/0.jpg", "Cable_Rear_Delt_Fly/1.jpg"]', 360.0, 'Cable Rear Delt Fly', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3c615219-4ab1-50fe-9001-a5517a0fa4c0', 'free-exercise-db', 'Cable_Reverse_Crunch', 'Reverse Crunch (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["Bir ayak bileği kayışı aparatını alçak makara kablosuna bağlayın ve önüne yere bir mat yerleştirin.", "Ayaklarınız makaraya bakacak şekilde oturun ve kabloyu ayak bileklerinize bağlayın.", "Uzanın, bacaklarınızı kaldırın ve dizlerinizi 90 derecelik açıyla bükün. Bacaklarınız ve kablo aynı hizada olmalıdır. Değilse, hizalanana kadar makarayı yukarı veya aşağı ayarlayın.", "Ellerinizi başınızın arkasında tutarak dizlerinizi gövdenize doğru çekin ve kalçanızı yerden kaldırın.", "Bir an duraklayın ve yavaş ve kontrollü bir şekilde kalçanızı indirip bacaklarınızı başlangıçtaki 90 derecelik açıya geri getirin. Dinlenme pozisyonunda bile karın kaslarınızda hâlâ gerginlik olmalıdır.", "Aynı hareketi tükenene kadar tekrarlayın."]', 'strength', '["Cable_Reverse_Crunch/0.jpg", "Cable_Reverse_Crunch/1.jpg"]', 360.0, 'Cable Reverse Crunch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('19a9df2a-18fa-5703-b3d1-1c3da56d35eb', 'free-exercise-db', 'Cable_Rope_Overhead_Triceps_Extension', 'Overhead Triceps Extension (Kablo, Halat)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Halatı makara makinesinin alt makarasına takın.", "Halatı iki elinizle kavrayın ve kollarınızı nötr tutuşla (avuç içleri birbirine bakacak şekilde) elleriniz tam başınızın üzerinde olacak biçimde uzatın. Dirsekleriniz başınıza yakın olmalı, kollarınız yere dik olmalı ve parmak boğumlarınız tavana bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı sabit tutarken halatı yavaşça başınızın arkasına indirin. Bu hareketi yaparken nefes alın ve triceps''iniz tam gerildiğinde durun.", "Nefes verirken triceps''inizi kasarak başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Rope_Overhead_Triceps_Extension/0.jpg", "Cable_Rope_Overhead_Triceps_Extension/1.jpg"]', 360.0, 'Cable Rope Overhead Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6239afa2-e0b2-52df-aba1-6508faf20993', 'free-exercise-db', 'Cable_Rope_Rear-Delt_Rows', 'Arka Omuz Row (Kablo, İp)', 'pull', 'beginner', 'compound', '["cable"]', '["shoulders"]', '["biceps", "middle back"]', '["Sırt için oturarak kablo row yapacakmış gibi, alt makara row istasyonunda aynı pozisyonda oturun.", "Makaraya bir ip aparatı takın ve üsten bir tutuşla kavrayın. Kollarınız uzanmış ve yere paralel, dirsekleriniz yanlara açık olmalıdır.", "Belinizi dik tutun ve kalçanızı geriye kaydırın; dizleriniz hafif bükülü olsun. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi yukarıda ve yanlara açık tutarak kablo aparatını üst göğsünüze, boynunuzun hemen altına doğru çekin. Nefes vererek dirsekler sırtınızın biraz gerisine geçene kadar bu hareketi sürdürün. İpucu: Hareket boyunca üst kollarınızı yatay, gövdeye dik ve yere paralel tutun.", "Kolların uzandığı ve omuzların öne gerildiği ilk pozisyona geri dönün. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Rope_Rear-Delt_Rows/0.jpg", "Cable_Rope_Rear-Delt_Rows/1.jpg"]', 360.0, 'Cable Rope Rear-Delt Rows', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9e2745a1-9cd3-5eee-8ba7-40d6c64ac189', 'free-exercise-db', 'Cable_Russian_Twists', 'Russian Twist (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["abdominals"]', '[]', '["Standart bir tutamak aparatı bağlayın ve kabloyu orta makara pozisyonuna ayarlayın.", "Kabloya dik olacak şekilde bir stabilite topunun üzerine uzanın ve tutamağı bir elinizle kavrayın. Makaradan yaklaşık kol boyu uzaklıkta olmalısınız ve kablodaki ağırlığın gerginliği hissedilmelidir.", "Tutamağı iki elinizle kavrayın ve kollarınızı göğsünüzün üzerinde tamamen uzatın. Elleriniz makara ile tam hizada olmalıdır. Değilse, hizalanana kadar makarayı yukarı veya aşağı ayarlayın.", "Kalçanızı yukarıda ve karın kaslarınızı sıkı tutun. Gövdenizi makaradan uzağa doğru tam bir çeyrek tur döndürün. Vücudunuz baştan dizlere kadar düz olmalıdır.", "Bir an bekleyin ve yavaş ve kontrollü bir şekilde başlangıç pozisyonuna dönün. Dinlenme pozisyonunda da kabloda yan taraftan bir gerginlik olmalıdır.", "Aynı hareketi tükenene kadar tekrarlayın.", "Ardından yerinizi değiştirin ve aynı hareket serisini karşı tarafta tekrarlayın."]', 'strength', '["Cable_Russian_Twists/0.jpg", "Cable_Russian_Twists/1.jpg"]', 360.0, 'Cable Russian Twists', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('01d5460d-3d4b-5d60-958e-63b415ab780a', 'free-exercise-db', 'Cable_Seated_Crunch', 'Oturarak Kablo Mekik', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["Sırtınız yüksek bir makaraya dönük olacak şekilde düz bir bench üzerine oturun.", "Kablo ip aparatını avuç içleriniz birbirine bakacak şekilde iki elinizle kavrayın ve ellerinizi iki omzunuzun üzerine sağlam bir şekilde yerleştirin. İpucu: Ağırlığın alt sırtınızı hafifçe geriye doğru germesine izin verin. Bu sizin başlangıç pozisyonunuz olacak.", "Kalçanız sabitken, dirsekleriniz kalçalarınıza doğru ilerleyecek şekilde belinizden bükülün. Bu adımı yaparken nefes verin.", "Nefes alırken yavaşça ilk pozisyona dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Seated_Crunch/0.jpg", "Cable_Seated_Crunch/1.jpg"]', 360.0, 'Cable Seated Crunch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('789302dd-3b93-5476-ad37-2d6296822684', 'free-exercise-db', 'Cable_Seated_Lateral_Raise', 'Oturarak Lateral Raise (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["shoulders"]', '["middle back", "traps"]', '["Birbirine zıt yönde duran iki alçak makaranın ortasında durun ve hemen arkanıza düz bir bank yerleştirin (size dik olacak şekilde; bankın dar kenarı arkanızda olmalıdır). Her makara için kullanılacak ağırlığı seçin.", "Şimdi arkanızdaki düz bankın kenarına oturun ve ayaklarınızı dizlerinizin önüne yerleştirin.", "Sırtınızı düz tutarak öne eğilin ve gövdenizi uyluklarınıza yaslayın.", "Birinden makaralara bağlı tek sapları size vermesini isteyin. Ağırlığı seçtikten sonra sol makarayı sağ elinizle, sağ makarayı sol elinizle kavrayın. Makaralar dizlerinizin altından geçmeli, kollarınız avuç içleri birbirine bakacak ve dirsekler hafif bükülü şekilde uzatılmış olmalıdır. Bu başlangıç pozisyonudur.", "Kollarınızı sabit tutarak, üst kolları yanlara doğru yere paralel ve omuz hizasına gelene kadar kaldırın. Bu hareketi yaparken nefes verin ve kasılmayı bir saniye tutun.", "Nefes alırken kollarınızı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın. İpucu: Egzersiz boyunca üst kolları gövdeye dik ve dirsek pozisyonunu sabit (10 ila 30 derecelik açı) tutun."]', 'strength', '["Cable_Seated_Lateral_Raise/0.jpg", "Cable_Seated_Lateral_Raise/1.jpg"]', 360.0, 'Cable Seated Lateral Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3f6bc8bc-ea05-5c67-82e6-8d8a4436c4b7', 'free-exercise-db', 'Cable_Shoulder_Press', 'Omuz Press (Kablo)', 'push', 'beginner', 'compound', '["cable"]', '["shoulders"]', '["triceps"]', '["Kabloları kulelerin en altına indirin ve uygun bir ağırlık seçin.", "Direklerin tam ortasında durun. Kabloları kavrayın ve avuç içleriniz öne bakacak şekilde omuz hizasında tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başınızı ve göğsünüzü yukarıda tutarak, dirseklerinizi açıp tutacakları doğrudan başınızın üzerine doğru itin.", "Üstte bir an duraklayın, ardından başlangıç pozisyonuna dönün ve tekrarlayın."]', 'strength', '["Cable_Shoulder_Press/0.jpg", "Cable_Shoulder_Press/1.jpg"]', 360.0, 'Cable Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ee962d1a-9861-5918-9230-bec27c8eae78', 'free-exercise-db', 'Cable_Shrugs', 'Shrug (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["traps"]', '[]', '["Alt makaraya bağlı kablo barını omuz genişliğinde veya biraz daha geniş üstten tutuşla (avuç içleri aşağı bakacak şekilde) kavrayın.", "Kollarınız önünüzde uzanmış ve barı tutar halde makaraya yakın şekilde dik durun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken omuzlarınızı olabildiğince yukarı kaldırarak barı yükseltin. Üst noktadaki kasılmayı bir saniye tutun. İpucu: Kollar her zaman uzamış kalmalıdır. Barı kaldırmaya yardımcı olması için biceps''i kullanmaktan kaçının. Yalnızca omuzlar aşağı yukarı hareket etmelidir.", "Barı başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Shrugs/0.jpg", "Cable_Shrugs/1.jpg"]', 360.0, 'Cable Shrugs', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1ba30faf-8749-57cc-b2bd-ac4debe38d8b', 'free-exercise-db', 'Cable_Wrist_Curl', 'Bilek Curl (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["forearms"]', '[]', '["Düz bar aparatı takılı alçak bir kablo makarasının önüne düz bir bench yerleştirerek başlayın.", "Kablo barını dar ile omuz genişliği arası bir supinasyon tutuşuyla (avuç içleri yukarı) kavrayın ve ön kollarınız uyluklarınızın üstüne yaslanacak şekilde kaldırın. Bilekleriniz dizlerinizin hemen ötesinde sarkmalı.", "Bileklerinizi yukarı doğru kıvırarak ve nefes vererek başlayın. Kasılmayı bir saniye tutun.", "Nefes alırken bileklerinizi yavaşça başlangıç pozisyonuna indirin.", "Ön kollarınız sabit olmalı; bu egzersizi yapmak için gereken tek hareket bilektir.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cable_Wrist_Curl/0.jpg", "Cable_Wrist_Curl/1.jpg"]', 360.0, 'Cable Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d672afba-3e8e-57c1-9b10-d9fae1703ce4', 'free-exercise-db', 'Calf-Machine_Shoulder_Shrug', 'Omuz Shrug (Calf Makinesi)', 'pull', 'beginner', 'isolation', '["machine"]', '["traps"]', '[]', '["Calf makinesinde, omuz pedleri omuzlarınızın üzerinde olacak şekilde yerleşin. Gövdeniz dik, kollarınız yanlarınızda doğal biçimde uzanmış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken omuzlarınızı kulaklarınıza doğru kaldırın ve kasılmayı tam bir saniye boyunca tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Calf-Machine_Shoulder_Shrug/0.jpg", "Calf-Machine_Shoulder_Shrug/1.jpg"]', 360.0, 'Calf-Machine Shoulder Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d33d174a-1093-559d-a76e-0ad702de094a', 'free-exercise-db', 'Calf_Press', 'Calf Press (Makine)', 'push', 'beginner', 'isolation', '["machine"]', '["calves"]', '[]', '["Koltuğu, başlangıç pozisyonunda bacaklarınız sadece hafifçe bükülü olacak şekilde ayarlayın. Ayak parmak diplerinizin (ayak tabanınızın ön kısmı) platformda sağlam bir şekilde durması gerekir.", "Uygun bir ağırlık seçin ve tutamakları kavrayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dizlerinizi açarak bacaklarınızı düzeltin ve ağırlığı ağırlık yığınından yeni yeni kaldırın. Ayak bileğiniz tamamen bükülü, parmaklarınız yukarıya bakıyor olmalıdır. Ayak parmak diplerinizle gidebildiğiniz kadar aşağı doğru iterek hareketi gerçekleştirin.", "Kısa bir beklemeden sonra hareketi tersine çevirin ve tekrarlayın."]', 'strength', '["Calf_Press/0.jpg", "Calf_Press/1.jpg"]', 360.0, 'Calf Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8aa4f80e-9492-561d-bab2-54c1f9036d24', 'free-exercise-db', 'Calf_Press_On_The_Leg_Press_Machine', 'Calf Press (Leg Press Makinesi)', 'push', 'beginner', 'isolation', '["machine"]', '["calves"]', '[]', '["Leg press makinesini kullanarak makineye oturun ve bacaklarınızı önünüzdeki platforma orta (omuz genişliğinde) bir ayak aralığıyla yerleştirin.", "Ağırlıklı platformu yerinde tutan güvenlik çubuklarını indirin ve bacaklarınız dizlerinizi kilitlemeden tamamen uzanana kadar platformu sonuna kadar yukarı itin. (Not: Bazı leg press makinelerinde güvenlik çubuklarını daha fazla güvenlik için takılı bırakabilirsiniz. Makineniz buna izin veriyorsa tercih edilen yöntem budur.) Gövdeniz ve bacaklarınız mükemmel bir 90 derecelik açı yapmalıdır. Şimdi ayak parmaklarınızı ve ayak ön tabanlarınızı dikkatlice platformun alt kısmına yerleştirin; topuklar boşlukta kalsın. Ayak parmakları, bölümün başında anlatıldığı gibi öne, dışa ya da içe bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken ayak bileklerinizi olabildiğince uzatarak ve baldırınızı kasarak topuklarınızı kaldırıp platforma itin. Diz her zaman sabit kalmalıdır; hiçbir zaman bükülme olmamalıdır. Aşağı inmeye başlamadan önce kasılmış pozisyonu bir saniye boyunca tutun.", "Nefes alırken ayak bileklerinizi bükerek topuklarınızı indirin ve baldırlarınız gerilene kadar yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Calf_Press_On_The_Leg_Press_Machine/0.jpg", "Calf_Press_On_The_Leg_Press_Machine/1.jpg"]', 360.0, 'Calf Press On The Leg Press Machine', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('035238dc-b01a-50ad-b830-78c92c59da85', 'free-exercise-db', 'Calf_Raise_On_A_Dumbbell', 'Calf Raise (Dambıl Üzerinde)', 'push', 'intermediate', 'isolation', '["dumbbell"]', '["calves"]', '[]', '["Denge için sağlam bir nesneye tutunun ve bir dambıl sapının üzerine çıkın; tercihen yuvarlak plakalı bir dambıl olsun, çünkü dambıl yuvarlanır ve dengelenmek için daha çok çalışmanız gerekir; bu da egzersizin etkisini artırır.", "Şimdi baldırınızda güzel bir esneme elde etmek için ayağınızı hafifçe öne doğru yuvarlayın. Bu sizin başlangıç pozisyonunuzdur.", "Tam bir açılma elde etmek için ayağınızı sapın üzerinden yuvarlarken baldırınızı yukarı kaldırın. Hareketi yaparken nefes verin. Üst noktada baldırı sert şekilde kasın ve bir saniye bekleyin. İpucu: Yukarı çıkarken dambılı hafifçe geriye doğru yuvarlayın.", "Şimdi daha iyi bir esneme için aşağı inerken dambılı hafifçe öne doğru yuvarlayarak nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Calf_Raise_On_A_Dumbbell/0.jpg", "Calf_Raise_On_A_Dumbbell/1.jpg"]', 360.0, 'Calf Raise On A Dumbbell', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6b19e8c8-295b-5a31-a935-96bb4cb09327', 'free-exercise-db', 'Calf_Raises_-_With_Bands', 'Calf Raise (Direnç Bandı)', 'push', 'beginner', 'isolation', '["bands"]', '["calves"]', '[]', '["Bir egzersiz bandını alın ve ayak parmaklarınızla üzerine basın; bandın ayak ile eller arasındaki uzunluğunun iki tarafta da aynı olduğundan emin olun.", "Bandın tutacaklarını tutarken, omuz press''e hazırlanır gibi kollarınızı başınızın yanına kaldırın. Avuç içleri öne bakmalı, dirsekler bükülü ve yanlarda olmalıdır. Bu hareket bantta gerginlik yaratacaktır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Ellerinizi omuzlarınızın yanında tutarak nefes verirken parmak uçlarınızın üzerinde yükselin ve hareketin en üst noktasında baldırlarınızı sertçe sıkın.", "Bir saniyelik kasılmanın ardından yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Calf_Raises_-_With_Bands/0.jpg", "Calf_Raises_-_With_Bands/1.jpg"]', 360.0, 'Calf Raises - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('49bbdef0-7056-549e-b807-0f9b5266ff7c', 'free-exercise-db', 'Calf_Stretch_Elbows_Against_Wall', 'Baldır Esnetme (Dirsekler Duvarda)', 'static', 'beginner', 'isolation', '[]', '["calves"]', '[]', '["Bir duvara yüzünüz dönük, birkaç adım uzaklıkta durun.", "Ağırlığınızı ön kollarınıza vererek duvara yaslanın.", "Topuklarınızı yerde tutmaya çalışın. 10-20 saniye bekleyin. Duvara daha yakın veya daha uzak durarak egzersizi sırasıyla daha kolay veya daha zor hale getirebilirsiniz."]', 'stretching', '["Calf_Stretch_Elbows_Against_Wall/0.jpg", "Calf_Stretch_Elbows_Against_Wall/1.jpg"]', 150.0, 'Calf Stretch Elbows Against Wall', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d66187b8-6e82-5cd6-8026-5e02ebf5895e', 'free-exercise-db', 'Calf_Stretch_Hands_Against_Wall', 'Duvara Dayanarak Baldır Esnetme', 'static', 'beginner', 'isolation', '[]', '["calves"]', '[]', '["Bir duvara dönük olarak, duvardan birkaç adım uzakta durun. Bir ayağınız önde olacak şekilde ayaklarınızı kademeli konumlandırın.", "Öne doğru eğilin ve ellerinizi duvara dayayın; topuğunuzu, kalçanızı ve başınızı düz bir çizgide tutun.", "Topuğunuzu yerde tutmaya çalışın. 10-20 saniye bekleyin ve ardından taraf değiştirin."]', 'stretching', '["Calf_Stretch_Hands_Against_Wall/0.jpg", "Calf_Stretch_Hands_Against_Wall/1.jpg"]', 150.0, 'Calf Stretch Hands Against Wall', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('856f7769-7f35-5cd3-b382-c85b14c1d3f9', 'free-exercise-db', 'Calves-SMR', 'Baldır Foam Roller (SMR)', 'static', 'intermediate', NULL, '["foam roll"]', '["calves"]', '[]', '["Yerde oturarak başlayın. Alt bacağınızın altına bir foam roller yerleştirin. Diğer bacağınızı karşı bacağın üzerinden çaprazlayabilir veya ağırlığınızın bir kısmını taşıyacak şekilde yere koyabilirsiniz. Bu sizin başlangıç pozisyonunuzdur.", "Ellerinizi yanınıza veya hemen arkanıza koyun ve kalçanızı yerden kaldırmak için bastırın; ağırlığınızın büyük bölümünü baldır kasınıza verin. Dizin altından bileğin üstüne kadar yuvarlanın ve gerginlik hissettiğiniz noktalarda 10-30 saniye bekleyin. Diğer bacak için tekrarlayın."]', 'stretching', '["Calves-SMR/0.jpg", "Calves-SMR/1.jpg"]', 150.0, 'Calves-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d17da84d-4cd9-57ee-b923-1b5d34173dd2', 'free-exercise-db', 'Car_Deadlift', 'Araba Deadlift', 'pull', 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["forearms", "glutes", "hamstrings", "lower back", "traps"]', '["Bu yarışma ekipmanı genellikle nötr tutuşlu saplara sahiptir, ancak bazılarında normal bir deadlift gibi yaklaşabileceğiniz düz bir bar bulunur. Ekipman bir araç veya traktör lastiği ya da fıçı gibi başka ağır nesnelerle yüklenebilir.", "Güçlü bir squat yapıyorsanız saplar arasında ortalanın, güçlü bir deadlift yapıyorsanız birkaç santim geride durun. Ayaklarınız yaklaşık kalça genişliğinde açık olmalı. Sapları kavramak için kalçanızdan eğilin. Ayaklarınız ve kavrayışınız sabitlendikten sonra derin bir nefes alın, ardından kalçanızı alçaltın ve dizlerinizi bükün.", "Başınızla ileri bakın, göğsünüzü dik ve sırtınızı kavisli tutun ve ağırlığı yukarı hareket ettirmek için topuklarınızdan itmeye başlayın. Ağırlık yukarı gelirken, kalçanızı öne iterek kürek kemiklerinizi birbirine yaklaştırın.", "Kalçalarınızdan bükülerek ve ağırlığı yere yönlendirerek ağırlığı indirin."]', 'strongman', '["Car_Deadlift/0.jpg", "Car_Deadlift/1.jpg"]', 480.0, 'Car Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c44f6133-d704-5455-9ff9-95172095146e', 'free-exercise-db', 'Car_Drivers', 'Car Drivers (Plaka)', 'push', 'beginner', 'isolation', '["barbell"]', '["shoulders"]', '["forearms"]', '["Dik dururken bir halter plakasını iki elinizle 3 ve 9 saat konumlarından tutun. Avuç içleriniz birbirine bakmalı ve kollarınız önünüzde düz bir şekilde uzatılmış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Plakayı mümkün olduğunca bir tarafa doğru döndürerek harekete başlayın. Direksiyonu bir yana çevirirken kullanacağınız hareketin aynısını kullanın.", "Hareketi tersine çevirin ve plakayı tamamen karşı tarafa çevirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Car_Drivers/0.jpg", "Car_Drivers/1.jpg"]', 360.0, 'Car Drivers', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('efcd9409-8f2c-5338-8cb4-acf8d1ca252f', 'free-exercise-db', 'Carioca_Quick_Step', 'Carioca Hızlı Adım', NULL, 'beginner', NULL, '[]', '["adductors"]', '["abdominals", "abductors", "calves", "glutes", "hamstrings", "quadriceps"]', '["Ayaklarınız birkaç santim aralıklı ve sol kolunuz rahat, atletik bir pozisyonda yukarıda olacak şekilde başlayın.", "Sağ ayağınızla hızlıca arkaya adım atın ve dizinizi yukarı çekin.", "Sağ dizinizi çektiğinizde kollarınızı hızla yukarı kaldırın ve dizinizin dümdüz yukarı aşağı gittiğinden emin olun. Hareket ederken ayaklarınızı döndürmekten kaçının ve yana giderken ileri bakmaya devam edin."]', 'plyometrics', '["Carioca_Quick_Step/0.jpg", "Carioca_Quick_Step/1.jpg"]', 480.0, 'Carioca Quick Step', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('84a4e3fa-3ce5-5c97-a1d8-1c76888aa729', 'free-exercise-db', 'Cat_Stretch', 'Kedi Esnetmesi', 'static', 'beginner', NULL, '[]', '["lower back"]', '["middle back", "traps"]', '["Yerde eller ve dizler üzerinde pozisyon alın.", "Karnınızı içeri çekin ve omurganızı, belinizi, omuzlarınızı ve boynunuzu yuvarlayarak başınızı sarkıtın.", "15 saniye bekleyin."]', 'stretching', '["Cat_Stretch/0.jpg", "Cat_Stretch/1.jpg"]', 150.0, 'Cat Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f95129da-bf65-5ac6-9e90-8f0f778c2d54', 'free-exercise-db', 'Catch_and_Overhead_Throw', 'Yakala ve Baş Üstü Fırlat (Medicine Ball)', 'push', 'beginner', 'compound', '["medicine ball"]', '["lats"]', '["abdominals", "chest", "shoulders"]', '["Bir duvara veya partnere dönük şekilde ayakta durarak başlayın.", "İki elinizi kullanarak topu başınızın arkasına, olabildiğince gererek getirin ve topu güçlü bir şekilde öne fırlatın.", "Fırlatmanızı sonuna kadar takip ettiğinizden ve topun geri dönüşünü karşılamaya hazır olduğunuzdan emin olun. Topu duvara fırlatıyorsanız, geri dönen topu karşılayabilecek kadar duvara yakın durun ve partnerle yaptığınızdan biraz daha yukarıya nişan alın."]', 'plyometrics', '["Catch_and_Overhead_Throw/0.jpg", "Catch_and_Overhead_Throw/1.jpg"]', 480.0, 'Catch and Overhead Throw', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eaebf674-5623-5fbe-910b-eb1da47036b6', 'free-exercise-db', 'Chain_Handle_Extension', 'Triceps Extension (Zincirli Tutaç)', 'push', 'intermediate', 'isolation', '["other"]', '["triceps"]', '[]', '["Bu egzersiz için iki kablo tutacağına, düz bir bench''e ve zincirlere ihtiyacınız olacak. Zincirlerin ortasını tutaçlara bağlayın ve düz bench üzerine yerleşin. Dirsekleriniz tam yukarıyı göstermelidir.", "Üst kolunuzu sabit tutarak ve bilekleriniz pronasyonda (avuç içleri öne/aşağı bakacak şekilde) dirseğinizi açarak başlayın.", "Kilitlenme noktasında duraklayın ve hareketi tersine çevirerek başlangıç pozisyonuna dönün."]', 'powerlifting', '["Chain_Handle_Extension/0.jpg", "Chain_Handle_Extension/1.jpg"]', 360.0, 'Chain Handle Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3bb5a213-d078-56ca-b791-275604de6103', 'free-exercise-db', 'Chain_Press', 'Chain Press (Zincir)', 'push', 'intermediate', 'compound', '["other"]', '["chest"]', '["shoulders", "triceps"]', '["Zincirleri kablo tutamaklarına bağlayarak başlayın. Düz sehpada dambıl press''teki pozisyonda yerleşin. Bilekleriniz pronasyonda ve kollarınız yere dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi bükerek zincirleri indirin; zincirin bir kısmı yere yığılarak yük azalacaktır.", "Dirseğiniz 90 derecelik açı yapana kadar devam edin, ardından dirseği açarak hareketi tersine çevirin ve kilitlenmeye kadar itin."]', 'powerlifting', '["Chain_Press/0.jpg", "Chain_Press/1.jpg"]', 360.0, 'Chain Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4ad1fe6a-bcc5-55f5-8cc6-e5892b4db417', 'free-exercise-db', 'Chair_Leg_Extended_Stretch', 'Sandalyede Bacak Uzatma Esnetmesi', 'static', 'beginner', 'isolation', '["other"]', '["hamstrings"]', '["adductors"]', '["Bir sandalyede dik oturun ve oturağın yanlarından tutunun.", "Bir bacağınızı kaldırın, dizinizi açın ve bunu yaparken ayak bileğinizi bükün.", "O bacağı yavaşça gidebildiğiniz kadar dışa doğru açın, ardından tekrar ortaya getirin ve aşağı indirin.", "Diğer bacağınız için tekrarlayın."]', 'stretching', '["Chair_Leg_Extended_Stretch/0.jpg", "Chair_Leg_Extended_Stretch/1.jpg"]', 150.0, 'Chair Leg Extended Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a04e708d-8f21-5e66-a115-345166fad8ae', 'free-exercise-db', 'Chair_Lower_Back_Stretch', 'Sandalyede Bel Esnetme', 'static', 'beginner', 'isolation', '[]', '["lats"]', '["lower back"]', '["Bir sandalyeye dik oturun.", "Kolunuz başınızın üzerinden geçecek şekilde bir yana doğru eğilin. Boştaki elinizle sandalyeye tutunabilirsiniz.", "10 saniye bekleyin ve diğer tarafa da tekrarlayın."]', 'stretching', '["Chair_Lower_Back_Stretch/0.jpg", "Chair_Lower_Back_Stretch/1.jpg"]', 150.0, 'Chair Lower Back Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('83a28285-860e-56e6-954e-652af50b7d1f', 'free-exercise-db', 'Chair_Squat', 'Sandalye Squat (Halter)', 'push', 'beginner', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için önce barı boyunuza en uygun konuma ayarlayın. Bar yüklendikten sonra altına girin ve omuzlarınızın arkasına yerleştirin.", "Barı avuç içleriniz ileri bakacak şekilde tutun, kilidini açın ve bacaklarınızı açarak raftan kaldırın.", "Ayaklarınızı barın yaklaşık 45 cm önüne doğru hareket ettirin. Bacaklarınızı omuz genişliğinde bir duruşla, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Her zaman ileri bakın ve omurganızı nötr veya hafifçe kavisli tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Başınız yukarıda ve duruşunuz dik şekilde dizlerinizi bükerek barı yavaşça indirin. Üst bacak ile alt bacak arasındaki açı 90 dereceyi geçene kadar inmeye devam edin.", "Nefes verirken ayaklarınızın topuklarıyla yeri iterek, dizlerinizi açarak ve başlangıç pozisyonuna dönerek barı kaldırmaya başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Chair_Squat/0.jpg", "Chair_Squat/1.jpg"]', 360.0, 'Chair Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1590d046-ade6-5561-a459-8e414cd76b09', 'free-exercise-db', 'Chair_Upper_Body_Stretch', 'Sandalyede Üst Vücut Esnetme', 'static', 'beginner', NULL, '["other"]', '["shoulders"]', '["biceps", "chest"]', '["Sandalyenin kenarına oturun ve sandalyenin arkasını kavrayın.", "Sırtınızı düz tutarak kollarınızı uzatın ve bir gerilme hissedecek şekilde üst vücudunuzu öne doğru çekin. 20-30 saniye bekleyin."]', 'stretching', '["Chair_Upper_Body_Stretch/0.jpg", "Chair_Upper_Body_Stretch/1.jpg"]', 150.0, 'Chair Upper Body Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ebb79469-2b16-5ac4-b00e-95ff191f1a44', 'free-exercise-db', 'Chest_And_Front_Of_Shoulder_Stretch', 'Göğüs ve Ön Omuz Esnetme', 'static', 'beginner', 'isolation', '["other"]', '["chest"]', '["shoulders"]', '["Bacaklarınız bitişik şekilde ayakta durarak ve bir vücut çubuğu (bodybar) ya da süpürge sapı tutarak başlayın.", "Çubuğu omuz genişliğinden biraz daha geniş bir tutuşla, avuç içleriniz aşağı bakacak şekilde önünüzde tutun.", "Çubuğu dikkatlice yukarı kaldırın ve başınızın arkasına doğru götürün."]', 'stretching', '["Chest_And_Front_Of_Shoulder_Stretch/0.jpg", "Chest_And_Front_Of_Shoulder_Stretch/1.jpg"]', 150.0, 'Chest And Front Of Shoulder Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0a36f7a5-5874-5d44-ac29-ed356f570822', 'free-exercise-db', 'Chest_Push_from_3_point_stance', 'Medicine Ball Chest Push (3 Nokta Duruşu)', 'push', 'beginner', 'compound', '["medicine ball"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Sırtınız düz ve bir eliniz yerde olacak şekilde çömelerek üç nokta duruşunda başlayın. Medicine ball''u hemen önünüze yerleştirin.", "Başlamak için ilk adımınızı atın ve topu göğsünüze çekin; fırlatmaya hazırlanmak için iki elinizi de konumlandırın.", "İkinci adımı atarken topu patlayıcı bir şekilde, olabildiğince sert biçimde öne doğru fırlatın."]', 'plyometrics', '["Chest_Push_from_3_point_stance/0.jpg", "Chest_Push_from_3_point_stance/1.jpg"]', 480.0, 'Chest Push from 3 point stance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('51cf228b-0214-56e8-99ca-0a183c275442', 'free-exercise-db', 'Chest_Push_multiple_response', 'Göğüs İtişi (Seri Tekrar, Medicine Ball)', 'push', 'beginner', 'compound', '["medicine ball"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Bir duvara dönük şekilde diz çökerek başlayın veya bir partnerden yararlanın. Topu iki elinizle göğsünüze sıkıca bastırarak tutun.", "Kalçanızla öne ve dışa doğru patlayıcı bir hareket yaparak topu olabildiğince sert itin.", "Hareketi öne doğru düşerek ve kendinizi ellerinizle karşılayarak tamamlayın.", "Hemen dik pozisyona geri dönün. İstenen tekrar sayısı kadar tekrarlayın."]', 'plyometrics', '["Chest_Push_multiple_response/0.jpg", "Chest_Push_multiple_response/1.jpg"]', 480.0, 'Chest Push (multiple response)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9f6f63cf-9a58-549c-97d3-b4eefaef2473', 'free-exercise-db', 'Chest_Push_single_response', 'Chest Push (Tek Tekrar)', 'push', 'beginner', 'compound', '["medicine ball"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Medisin topunu iki elinizle göğsünüze sıkıca bastırarak diz üstü pozisyonda başlayın.", "Kalçanızla öne ve dışa doğru patlayıcı şekilde hareket ederek ve topu olabildiğince uzağa iterek pası gerçekleştirin.", "Hareketi tamamlamak için öne doğru düşün ve kendinizi ellerinizle yakalayın."]', 'plyometrics', '["Chest_Push_single_response/0.jpg", "Chest_Push_single_response/1.jpg"]', 480.0, 'Chest Push (single response)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2293f70a-905a-5dd5-a9ef-10cbff55cdc3', 'free-exercise-db', 'Chest_Push_with_Run_Release', 'Koşu ile Göğüs İtişi (Sağlık Topu)', 'push', 'beginner', 'compound', '["medicine ball"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Dizler bükülü, kalça geride ve sırt düz olacak şekilde atletik bir duruşla başlayın. Sağlık topunu bacaklarınızın yanında tutun. Bu sizin başlangıç pozisyonunuzdur.", "İlk adımınızı atarken sağlık topunu göğsünüze çekin.", "İkinci adımda topu patlayıcı bir şekilde ileri itin ve bıraktıktan hemen sonra 10 yarda (yaklaşık 9 metre) sprint atın. Çok hızlıysanız kendi pasınızı yakalayabilirsiniz!"]', 'plyometrics', '["Chest_Push_with_Run_Release/0.jpg", "Chest_Push_with_Run_Release/1.jpg"]', 480.0, 'Chest Push with Run Release', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8b8d56ae-97bf-5368-957b-90fa16c850a0', 'free-exercise-db', 'Chest_Stretch_on_Stability_Ball', 'Göğüs Esnetme (Pilates Topu)', 'static', 'beginner', 'isolation', '["exercise ball"]', '["chest"]', '[]', '["Bir egzersiz topunun yanında eller ve dizler üzerinde pozisyon alın.", "Kolunuzu yana doğru açık tutarak dirseklerinizi topun üzerine yerleştirin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi topun üzerinde tutarak gövdenizi yere doğru indirin. Esnetmeyi 20-30 saniye boyunca tutun ve diğer kolla tekrarlayın."]', 'stretching', '["Chest_Stretch_on_Stability_Ball/0.jpg", "Chest_Stretch_on_Stability_Ball/1.jpg"]', 150.0, 'Chest Stretch on Stability Ball', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9f27e1c0-8cae-5be4-aa01-869d9a0d2989', 'free-exercise-db', 'Childs_Pose', 'Child''s Pose (Çocuk Pozu)', 'static', 'beginner', NULL, '[]', '["lower back"]', '["glutes", "middle back"]', '["Dizlerinizin ve ellerinizin üzerine gelin, ellerinizi önünüze doğru yürütün.", "Kalçanızı topuklarınızın üzerine oturacak şekilde indirin. Tüm omurganızı esnetmek için geriye otururken kollarınızın yerde sürünmesine izin verin.", "Topuklarınızın üzerine yerleştikten sonra ellerinizi ayaklarınızın yanına getirin ve gevşeyin. Sırtınıza doğru \"nefes alın\". Alnınızı yere dayayın. Diz probleminiz varsa bu pozisyondan kaçının."]', 'stretching', '["Childs_Pose/0.jpg", "Childs_Pose/1.jpg"]', 150.0, 'Child''s Pose', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8fbc53b2-9a50-5b48-a147-9c46c430090a', 'free-exercise-db', 'Chin-Up', 'Chin-Up (Ters Tutuş Barfiks)', 'pull', 'beginner', 'compound', '["body only"]', '["lats"]', '["biceps", "forearms", "middle back"]', '["Barfiks barını avuç içleriniz gövdenize bakacak ve omuz genişliğinden daha dar bir tutuşla kavrayın.", "Her iki kolunuz önünüzde uzatılmış ve bar seçtiğiniz tutuş genişliğinde elinizdeyken, gövdenizi olabildiğince düz tutun, bel bölgenizde hafif bir kavis oluşturun ve göğsünüzü öne çıkarın. Bu sizin başlangıç pozisyonunuzdur. İpucu: Gövdeyi olabildiğince düz tutmak biceps uyarımını en üst düzeye çıkarırken sırt katılımını en aza indirir.", "Nefes verirken, başınız barın hizasına gelene kadar gövdenizi yukarı çekin. Hareketi gerçekleştirmek için biceps kaslarını kullanmaya odaklanın. Dirseklerinizi vücudunuza yakın tutun. İpucu: Üst gövde hareket ederken sabit kalmalı, yalnızca kollar hareket etmelidir. Ön kollar barı tutmaktan başka bir iş yapmamalıdır.", "Kasılmış pozisyonda biceps''i bir saniye sıktıktan sonra, kolunuz tamamen uzayana kadar gövdenizi yavaşça başlangıç pozisyonuna indirin. Hareketin bu kısmında nefes alın.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Chin-Up/0.jpg", "Chin-Up/1.jpg"]', 360.0, 'Chin-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4e90e2d3-a1ff-50dd-b951-87fca721f452', 'free-exercise-db', 'Chin_To_Chest_Stretch', 'Çene Göğse Boyun Esnetme', 'static', 'beginner', NULL, '[]', '["neck"]', '["traps"]', '["Yerde oturma pozisyonu alın.", "İki elinizi başınızın arkasına, parmaklarınız kenetli, başparmaklarınız aşağı ve dirsekleriniz tam ileri bakacak şekilde yerleştirin. Başınızı yavaşça göğsünüze doğru çekin. 20-30 saniye bekleyin."]', 'stretching', '["Chin_To_Chest_Stretch/0.jpg", "Chin_To_Chest_Stretch/1.jpg"]', 150.0, 'Chin To Chest Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('946932af-a1bc-5d42-88ab-ef40f08f20b1', 'free-exercise-db', 'Circus_Bell', 'Circus Bell (Dev Dambıl)', 'push', 'expert', 'compound', '["other"]', '["shoulders"]', '["forearms", "glutes", "hamstrings", "lower back", "traps", "triceps"]', '["Circus bell, kalın saplı büyük boy bir dambıldır. Dambılı ayaklarınızın arasında tutarak başlayın ve sapı iki elinizle kavrayın.", "Kalçanızı ve dizlerinizi açarak dambılı istenen omzunuza taşıyın (clean) ve diğer elinizi bırakın.", "Dengenizi kaybetmemek için dambıl başlarından birini omzunuzun arkasına almaya dikkat edin. Başınızın üzerine kaldırmak için dizlerinizi bükerek çökün, ardından dambılı başınızın üzerine uzatırken yukarı doğru itin ve bunu yaparken hafifçe ondan uzağa doğru eğilin.", "Zili dikkatlice yere geri yönlendirin ve olabildiğince kontrol altında tutun. Zemine zarar vermemek için bu hareketi kalın bir kauçuk mat üzerinde yapmak en iyisidir."]', 'strongman', '["Circus_Bell/0.jpg", "Circus_Bell/1.jpg"]', 480.0, 'Circus Bell', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4fc065e3-d24a-5853-afd3-68e34144302a', 'free-exercise-db', 'Clean', 'Clean (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["calves", "forearms", "glutes", "lower back", "quadriceps", "shoulders", "traps"]', '["Yerdeki halter kaval kemiklerinize yakın olacak şekilde, bacaklarınızın hemen dışından üsten (veya kancalı/hook) bir tutuşla barı kavrayın. Ağırlığı topuklarınıza vererek kalçanızı alçaltın; sırtınız düz, başınız ileri bakıyor, göğsünüz yukarıda ve omuzlarınız barın hemen önünde olsun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Topuklarınızdan iterek ve dizlerinizi açarak ilk çekişe (first pull) başlayın. Sırt açınız aynı kalmalı ve kollarınız düz durmalıdır. Ağırlığı kontrollü bir şekilde dizlerin üstüne kadar hareket ettirin.", "Sırada, clean hareketi için asıl hızlanma kaynağı olan ikinci çekiş (second pull) gelir. Bar uyluğun ortasına yaklaştığında kalçanızı açmaya başlayın. Zıplama hareketiyle kalça, diz ve ayak bileklerinizi açarak hızlanın ve barı yukarı hareket ettirmek için hızdan yararlanın. Ağırlığı hızlandırmak için kollarla aktif olarak çekmeye gerek yoktur; ikinci çekişin sonunda vücut tamamen açılmış, hafifçe geriye eğik ve kollar hâlâ uzamış olmalıdır.", "Tam açılmaya ulaşıldığında, omuzlarınızı sertçe silkerek (shrug) ve dirsekleriniz yukarı ve dışarı bakacak şekilde kollarınızı bükerek üçüncü çekişe (third pull) geçin. En yüksek açılma noktasında kendinizi sertçe aşağı çekin ve bunu yaparken dirseklerinizi barın altına doğru döndürün. Barı ön squat pozisyonunda karşılayın; bu pozisyonun derinliği, üçüncü çekişin sonunda barın yüksekliğine bağlıdır. Bar öne doğru yuvarlanmış omuzlarınızın üzerine oturmalı, ellerinizi gevşek tutarak boğazınıza hafifçe değmelidir. Toparlanmaya yardımcı olacak şekilde en alt squat pozisyonuna kadar inmeye devam edin.", "Topuklarınızdan iterek, gövdenizi dik ve dirseklerinizi yukarıda tutarak hemen toparlanın. Ayakta duruş pozisyonuna yükselene kadar devam edin."]', 'olympic weightlifting', '["Clean/0.jpg", "Clean/1.jpg"]', 420.0, 'Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f0238a52-973a-5d00-b8b2-8da1ff41a8f1', 'free-exercise-db', 'Clean_Deadlift', 'Clean Deadlift', 'pull', 'beginner', 'compound', '["barbell"]', '["hamstrings"]', '["forearms", "glutes", "lower back", "middle back", "quadriceps", "traps"]', '["Halter kaval kemiklerinize yakın olacak şekilde ayakta durarak başlayın. Ayaklarınız tam kalçanızın altında ve hafifçe dışa dönük olmalıdır. Halteri omuz genişliğinde, çift üstten tutuşla veya hook tutuşla kavrayın. Halterin yanına çömelin. Omurganız tam açılmış olmalı; sırt açınız omuzlarınızı halterin önüne yerleştirecek ve sırtınızı olabildiğince dik tutacak şekilde olmalıdır.", "Topuklarınızın ön kısmıyla zemini iterek başlayın. Halter yukarı çıkarken sırt açınızı sabit tutun. Dizlerinizi halterin yolundan uzak tutmaya yardımcı olması için yanlara doğru açın.", "Halter dizlerinizi geçtikten sonra kalçanız ve dizleriniz tamamen açılana kadar kalçanızı halteri doğru itip kaldırışı tamamlayın."]', 'olympic weightlifting', '["Clean_Deadlift/0.jpg", "Clean_Deadlift/1.jpg"]', 420.0, 'Clean Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5d8a5c45-714a-58eb-b145-055e018db086', 'free-exercise-db', 'Clean_Pull', 'Clean Pull (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["forearms", "glutes", "hamstrings", "lower back", "traps"]', '["Halter, kaval kemiklerinize yakın şekilde yerdeyken, bacaklarınızın hemen dışından üstten veya hook tutuşla kavrayın. Ağırlığı topuklarınıza vererek, sırtınız düz, başınız ileriye bakacak, göğsünüz yukarıda ve omuzlarınız barın hemen önünde olacak şekilde kalçanızı alçaltın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dizlerinizi açarak ve topuklarınızdan iterek ilk çekişe başlayın. Sırt açınız aynı kalmalı, kollarınız düz ve dirsekleriniz dışarıda kalmalıdır. Ağırlığı kontrollü bir şekilde dizlerin üzerine kadar hareket ettirmeye devam edin.", "Ardından, clean hareketi için ana hızlanma kaynağı olan ikinci çekiş gelir. Bar uyluğun orta noktasına yaklaştığında kalçanızı açmaya başlayın. Sıçrama benzeri bir hareketle kalçanızı, dizlerinizi ve ayak bileklerinizi açarak hızı kullanıp barı yukarı doğru hızlandırın. Ağırlığı hızlandırmak için kollarla aktif olarak çekmenize gerek yoktur; ikinci çekişin sonunda vücut tamamen açılmış, hafifçe geriye eğilmiş ve kollar hâlâ uzatılmış olmalıdır. Tam açılma sert ve ani olmalı, gerekenden uzun sürmemelidir."]', 'olympic weightlifting', '["Clean_Pull/0.jpg", "Clean_Pull/1.jpg"]', 420.0, 'Clean Pull', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d5128ef7-15c5-5a32-b1ac-bf89bac171d5', 'free-exercise-db', 'Clean_Shrug', 'Clean Şrag (Halter)', 'pull', 'beginner', 'compound', '["barbell"]', '["traps"]', '["forearms", "shoulders"]', '["Omuz genişliğinde, çift üsten (double overhand) veya hook tutuşla, bar uyluğun ortasında asılı olacak şekilde başlayın. Sırtınız düz ve hafifçe öne eğimli olmalı.", "Omuzlarınızı kulaklarınıza doğru silkin. Bu egzersiz genellikle clean''den daha ağır bir ağırlıkla yapılabilse de, hareketin yavaşlayacağı noktaya kadar aşırı yük bindirmekten kaçının."]', 'olympic weightlifting', '["Clean_Shrug/0.jpg", "Clean_Shrug/1.jpg"]', 420.0, 'Clean Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('83707bad-300c-5de9-8a9c-4fc787cea883', 'free-exercise-db', 'Clean_and_Jerk', 'Clean and Jerk', 'push', 'expert', 'compound', '["barbell"]', '["shoulders"]', '["abdominals", "glutes", "hamstrings", "lower back", "quadriceps", "traps", "triceps"]', '["Yerdeki halter kaval kemiklerinize yakın olacak şekilde, bacakların hemen dışından üstten veya hook tutuşla kavrayın. Ağırlık topuklarınızda, sırtınız düz, başınız ileri bakar, göğsünüz dik ve omuzlarınız halterin hemen önünde olacak şekilde kalçanızı alçaltın. Bu sizin başlangıç pozisyonunuz olacak.", "Topuklarınızdan iterek ve dizlerinizi açarak ilk çekişe başlayın. Sırt açınız aynı kalmalı ve kollarınız düz kalmalıdır. Dizlerin üzerine çıkana kadar ağırlığı kontrollü bir şekilde hareket ettirin.", "Sonra clean için ivmenin ana kaynağı olan ikinci çekiş gelir. Halter uyluğun ortasına yaklaşırken kalçanızı açmaya başlayın. Zıplama hareketiyle kalça, diz ve ayak bileklerinizi açarak hızı kullanıp halteri yukarı hareket ettirin. Ağırlığı hızlandırmak için kollarla aktif olarak çekmeye gerek olmamalıdır; ikinci çekişin sonunda vücut tamamen açılmış, hafifçe geriye yaslanmış ve kollar hâlâ uzanmış olmalıdır.", "Tam açılmaya ulaşıldığında, dirsekler yukarı ve dışa bakacak şekilde omuzlarınızı sertçe silkerek ve kollarınızı bükerek üçüncü çekişe geçin. En yüksek açılma noktasında, dirseklerinizi halterin altına döndürerek kendinizi sertçe aşağı çekin. Halteri bir front squat pozisyonunda karşılayın; bunun derinliği üçüncü çekişin sonunda halterin yüksekliğine bağlıdır. Halter, öne çıkmış omuzların üzerine, elleriniz gevşek şekilde boğazınıza hafifçe değecek biçimde yerleştirilmelidir. Toparlanmaya yardımcı olacak en alt squat pozisyonuna kadar inmeye devam edin.", "Topuklarınızdan iterek, gövdenizi dik ve dirseklerinizi yukarıda tutarak hemen toparlanın. Ayakta duruş pozisyonuna yükselene kadar devam edin.", "İkinci aşama, ağırlığı baş üstüne kaldıran jerk''tir. Ağırlık omuzların önünde yerleşikken dip hareketiyle başlayın. Ayaklarınız kalçanızın tam altındayken, kalçanızı geriye hareket ettirmeden dizlerinizi bükün. Sadece hafifçe aşağı inin ve yönü olabildiğince güçlü bir şekilde tersine çevirin.", "Mümkün olduğunca fazla hız ve kuvvet yaratmak için topuklarınızdan itin ve bar omuzlardan ayrılırken başınızı yoldan çektiğinizden emin olun.", "Ayaklar yerden ayrıldığı anda, ayaklar mümkün olduğunca hızlı bir şekilde karşılama pozisyonuna yerleştirilmelidir. Ayakların platforma karşı aktif olarak itmediği kısa anda, sporcunun halteri yukarı itme çabası onları aşağı sürecektir. Ayaklar bir ayak önde, bir ayak arkada olacak şekilde ayrılmalıdır. Halteri kollar baş üstünde kilitli olarak karşılayın. Ayakta duruş pozisyonuna dönün."]', 'olympic weightlifting', '["Clean_and_Jerk/0.jpg", "Clean_and_Jerk/1.jpg"]', 420.0, 'Clean and Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('684d5f5c-6a51-5da4-b1b4-6be066a2402c', 'free-exercise-db', 'Clean_and_Press', 'Clean and Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["abdominals", "calves", "glutes", "hamstrings", "lower back", "middle back", "quadriceps", "shoulders", "traps", "triceps"]', '["Omuz genişliğinde bir duruş alın; dizleriniz kolların içinde olsun. Sırtınızı düz tutarak dizlerinizden ve kalçanızdan bükülün; böylece halteri kollarınız tamamen uzamış ve omuz genişliğinden biraz daha geniş bir pronasyon (üstten) tutuşla kavrayabilirsiniz. Dirsekleri yanlara doğru çevirin. Bar kaval kemiklerinize yakın olmalıdır. Omuzlarınızı barın hizasında ya da biraz önünde konumlandırın. Düz bir sırt duruşu oluşturun. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi açarak barı çekmeye başlayın. Sırt açısını sabit tutarken kalçanızı öne ve omuzlarınızı aynı hızda yukarı hareket ettirin; barı vücudunuza yakın tutarak düz yukarı kaldırmaya devam edin.", "Bar dizin hizasını geçerken ayak bileklerinizi, dizlerinizi ve kalçanızı zıplama hareketine benzer şekilde güçlü bir şekilde açın. Bunu yaparken elinizle barı yönlendirmeye devam edin, omuzlarınızı silkin ve hareketin momentumunu kullanarak barı olabildiğince yükseğe çekin. Bar vücudunuza yakın hareket etmeli ve dirsekleriniz dışarıda kalmalıdır.", "Maksimum yükseklikte ayaklarınız yerden kesilmeli ve kendinizi barın altına çekmeye başlamalısınız. Bunun mekaniği kullanılan ağırlığa göre biraz değişebilir. Kendinizi barın altına çekerken çömelme pozisyonuna inmelisiniz.", "Bar en yüksek noktaya ulaştığında dirseklerinizi barın etrafında ve altına doğru döndürün. Gövdenizi dik tutup barın ağırlığını karşılamak için kalçanızı ve dizlerinizi bükerek barı omuzlarınızın ön kısmına yerleştirin (rack).", "Barı clean pozisyonunda tutarak tam boya kadar ayağa kalkın.", "Ayaklarınızı hareket ettirmeden nefes verirken barı başınızın üzerine bastırın. Barı kontrollü bir şekilde indirin."]', 'strength', '["Clean_and_Press/0.jpg", "Clean_and_Press/1.jpg"]', 360.0, 'Clean and Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c90ce64e-d052-5087-b0d2-d3e6fed4da0d', 'free-exercise-db', 'Clean_from_Blocks', 'Clean (Halter, Bloklardan)', 'pull', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "shoulders", "traps"]', '["Halter istenen yükseklikteki kutular veya standlar üzerindeyken bacaklarınızın hemen dışından üstten veya hook tutuşla kavrayın. Ağırlığı topuklarınıza vererek, sırtınız düz, başınız ileri bakacak, göğsünüz yukarıda ve omuzlarınız halterin hemen önünde olacak şekilde kalçanızı indirin. Bu sizin başlangıç pozisyonunuzdur.", "Topuklarınızla iterek ve dizlerinizi açarak ilk çekişe başlayın. Sırt açınız aynı kalmalı, kollarınız düz ve dirsekleriniz dışa dönük kalmalıdır.", "Tam açılma sağlandığında, omuzlarınızı sertçe silkip dirseklerinizi yukarı ve dışa doğru tutarak kollarınızı bükerek karşılama pozisyonuna geçin. Dirseklerinizi halterin altına döndürürken kendinizi agresif şekilde aşağı çekin. Halteri front squat pozisyonunda karşılayın; derinlik, üçüncü çekişin sonunda halterin yüksekliğine bağlıdır. Halter öne itilmiş omuzlara oturmalı, ellerinizi gevşek tutarak boğazınıza hafifçe değmelidir. Toparlanmanıza yardımcı olacak alt squat pozisyonuna kadar inmeye devam edin.", "Gövdenizi dik ve dirseklerinizi yukarıda tutarak topuklarınızla iterek hemen toparlanın. Ayakta durma pozisyonuna gelene kadar devam edin. Bir sonraki tekrar için ağırlığı kutulara geri bırakın."]', 'olympic weightlifting', '["Clean_from_Blocks/0.jpg", "Clean_from_Blocks/1.jpg"]', 420.0, 'Clean from Blocks', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fdf04e2d-c735-54d5-bd79-71f5c81d2fe8', 'free-exercise-db', 'Clock_Push-Up', 'Saat Şınavı', 'push', 'intermediate', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Yerde yüzüstü pozisyona geçin; ağırlığınızı ellerinizin ve ayak parmaklarınızın üzerinde taşıyın.", "Kollarınız tamamen uzamış ve elleriniz yaklaşık omuz genişliğinde olmalıdır. Hareket boyunca vücudunuzu düz tutun. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi bükerek göğsünüzü yere doğru indirin.", "En altta, dirseklerinizi açarak kendinizi havalanana kadar olabildiğince hızlı yukarı itin. Bir yana doğru 12-18 inç (30-45 cm) \"zıplamayı\" hedefleyin.", "Yukarı doğru hızlanırken dış ayağınızı hareket yönünüzden uzağa doğru hareket ettirin. Yerden ayrıldığınızda bir sonraki tekrar için vücudunuzu yaklaşık 30 derece kaydırın.", "Başlangıç pozisyonuna dönün ve başladığınız yere gelene kadar tüm daire boyunca egzersizi tekrarlayın."]', 'strength', '["Clock_Push-Up/0.jpg", "Clock_Push-Up/1.jpg"]', 360.0, 'Clock Push-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9aff56f2-4c65-5346-85b9-f30c7f38040b', 'free-exercise-db', 'Close-Grip_Barbell_Bench_Press', 'Dar Tutuşlu Bench Press (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["triceps"]', '["chest", "shoulders"]', '["Düz bir bench''e sırtüstü uzanın. Dar bir tutuşla (yaklaşık omuz genişliğinde) barı rack''ten kaldırın ve kollarınız kilitli halde üzerinizde düz tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken barı orta göğsünüzde hissedene kadar yavaşça indirin. İpucu: Normal bench press''ten farklı olarak, triceps''in devreye girmesini maksimuma çıkarmak için dirseklerinizi her zaman gövdenize yakın tuttuğunuzdan emin olun.", "Bir saniye bekledikten sonra, nefes vererek ve barı triceps kaslarınızla iterek başlangıç pozisyonuna getirin. Kasılmış pozisyonda kollarınızı kilitleyin, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: Aşağı inmek en az yukarı çıkmanın iki katı kadar sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde barı tekrar rack''e yerleştirin."]', 'strength', '["Close-Grip_Barbell_Bench_Press/0.jpg", "Close-Grip_Barbell_Bench_Press/1.jpg"]', 360.0, 'Close-Grip Barbell Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('aca37b90-eff7-5222-9cb0-f5880a6ea626', 'free-exercise-db', 'Close-Grip_Dumbbell_Press', 'Dar Tutuş Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["triceps"]', '["chest", "shoulders"]', '["Düz bir bankın üzerine bir dambılı dikey olarak yerleştirin.", "Dambılın bankın üst kısmında sağlam şekilde durduğundan emin olarak, bankın üzerine dik şekilde uzanın; yüzeyle yalnızca omuzlarınız temas etsin. Kalçanız bankın altında olmalı, bacaklarınız bükülü ve ayaklarınız sıkıca yerde olmalıdır.", "Dambılı iki elinizle kavrayın ve kolunuz boyunca göğsünüzün tam üzerinde tutun. Her iki avuç içi dambılın yanlarındaki alt yüzeye bastırmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dambılı göğsünüze indirerek harekete başlayın.", "Dirseklerinizi açarak başlangıç pozisyonuna dönün."]', 'strength', '["Close-Grip_Dumbbell_Press/0.jpg", "Close-Grip_Dumbbell_Press/1.jpg"]', 360.0, 'Close-Grip Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('47fdb1c1-079f-5eac-90b1-71bbf2996a00', 'free-exercise-db', 'Close-Grip_EZ-Bar_Curl_with_Band', 'Dar Tutuş Curl (EZ Bar, Direnç Bandı)', 'pull', 'beginner', 'isolation', '["e-z curl bar"]', '["biceps"]', '["forearms"]', '["Barın her iki ucuna bir bant bağlayın. Barı alın ve bir ayağınızı bandın ortasına yerleştirin. EZ bar''ı dar ve supine (avuç içleri yukarı bakan) bir tutuşla tutarak dik durun. Dirsekler gövdenize yakın olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kollarınızı yerinde tutarak curl hareketini yapmak için dirseklerinizi bükün. Ağırlık kaldırılırken nefes verin.", "Biceps''iniz tamamen kasılana ve bar omuz hizasına gelene kadar harekete devam edin. Kasılmış pozisyonda bir saniye bekleyin ve biceps''i sertçe sıkın.", "Nefes alırken barı yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Close-Grip_EZ-Bar_Curl_with_Band/0.jpg", "Close-Grip_EZ-Bar_Curl_with_Band/1.jpg"]', 360.0, 'Close-Grip EZ-Bar Curl with Band', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('89054b58-49a0-56ea-a6d1-da91cb25a80d', 'free-exercise-db', 'Close-Grip_EZ-Bar_Press', 'Close-Grip Press (EZ Bar)', 'push', 'beginner', 'compound', '["e-z curl bar"]', '["triceps"]', '["chest", "shoulders"]', '["Uygun ağırlıkta yüklenmiş bir EZ bar ile düz sehpaya uzanın.", "Dar bir tutuşla barı kaldırın ve dirsekleriniz içeride olacak şekilde gövdenizin tam üzerinde tutun. Kollar yere dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes alırken barı alt göğsünüze doğru indirin. Bu hareketi yaparken dirseklerinizi içeride tutun.", "Barı tekrar yukarı itmek için triceps''i kullanarak nefes verirken dirseklerinizi açıp başlangıç pozisyonuna itin.", "Tekrarlayın."]', 'strength', '["Close-Grip_EZ-Bar_Press/0.jpg", "Close-Grip_EZ-Bar_Press/1.jpg"]', 360.0, 'Close-Grip EZ-Bar Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8facf270-03bd-5a58-aa34-45223d19099e', 'free-exercise-db', 'Close-Grip_EZ_Bar_Curl', 'Dar Tutuşlu Biceps Curl (EZ Bar)', 'pull', 'beginner', 'isolation', '["barbell"]', '["biceps"]', '["forearms"]', '["Gövdeniz dik şekilde ayakta durun ve EZ curl barı iç taraftaki dar tutamaktan tutun. Avuç içleriniz öne bakmalı ve barın şeklinden dolayı hafifçe içe doğru eğimli olmalıdır. Dirsekleriniz gövdenize yakın olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kollarınızı sabit tutarak, nefes verirken biceps''inizi kasıp ağırlıkları öne doğru curl yapın. İpucu: Sadece ön kollar hareket etmelidir.", "Biceps''iniz tamamen kasılana ve bar omuz seviyesine gelene kadar hareketi sürdürün. Kasılmış pozisyonda bir saniye bekleyin ve biceps''inizi sertçe sıkın.", "Nefes alırken barı yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Close-Grip_EZ_Bar_Curl/0.jpg", "Close-Grip_EZ_Bar_Curl/1.jpg"]', 360.0, 'Close-Grip EZ Bar Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a8df011b-af9d-5475-ad9e-7292c5c58122', 'free-exercise-db', 'Close-Grip_Front_Lat_Pulldown', 'Dar Tutuş Lat Pulldown', 'pull', 'beginner', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Üst makaraya geniş bir bar bağlı olan lat pulldown makinesinde oturun. Makinenin diz pedini boyunuza göre ayarladığınızdan emin olun. Bu padler, vücudunuzun bara bağlı dirençle yukarı kalkmasını önler.", "Barı, belirtilen tutuşla avuç içleriniz öne bakacak şekilde kavrayın. Tutuşlar hakkında not: Geniş tutuşta elleriniz omuz genişliğinden daha geniş aralıklı olmalıdır. Orta tutuşta eller omuz genişliğinde, dar tutuşta ise omuz genişliğinden daha dar aralıklı olmalıdır.", "Her iki kolunuz önünüzde uzatılmış ve bar seçtiğiniz tutuş genişliğinde elinizdeyken, gövdenizi yaklaşık 30 derece geriye yatırın, bel bölgenizde hafif bir kavis oluşturun ve göğsünüzü öne çıkarın. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken, omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek barı üst göğsünüze temas edene kadar indirin. İpucu: Tam kasılma pozisyonuna ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde sabit kalmalıdır (yalnızca kollar hareket etmelidir). Ön kollar barı tutmaktan başka bir iş yapmamalıdır; bu nedenle barı ön kollarınızı kullanarak aşağı çekmeye çalışmayın.", "Kasılmış pozisyonda bir saniye bekledikten sonra, kürek kemiklerinizi birbirine doğru sıkarak barı kollarınız tamamen uzanana ve lat kaslarınız tamamen gerilene kadar yavaşça başlangıç pozisyonuna kaldırın. Hareketin bu kısmında nefes alın.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Close-Grip_Front_Lat_Pulldown/0.jpg", "Close-Grip_Front_Lat_Pulldown/1.jpg"]', 360.0, 'Close-Grip Front Lat Pulldown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('39355ae3-cfca-5f08-a723-60662f2814f8', 'free-exercise-db', 'Close-Grip_Push-Up_off_of_a_Dumbbell', 'Dar Şınav (Dambıl Üzerinde)', 'push', 'intermediate', 'compound', '["body only"]', '["triceps"]', '["abdominals", "chest", "shoulders"]', '["Yere uzanın ve ellerinizi dik duran bir dambılın üzerine yerleştirin. Ağırlığınızı ayak parmaklarınız ve ellerinizle taşıyın, gövdenizi sert, dirseklerinizi içeride ve kollarınızı düz tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken dirseklerinizin bükülmesine izin vererek vücudunuzu aşağı indirin. Vücudunuzu düz tutun; kalçanızın yükselmesine veya çökmesine izin vermeyin.", "Dirseklerinizi açarak kendinizi başlangıç pozisyonuna geri itin. Bu adımı yaparken nefes verin.", "Kasılmış pozisyonda bir duraklamanın ardından hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg", "Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg"]', 360.0, 'Close-Grip Push-Up off of a Dumbbell', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7fc357ad-d515-576d-8fa0-b0c317911a77', 'free-exercise-db', 'Close-Grip_Standing_Barbell_Curl', 'Dar Tutuş Ayakta Biceps Curl (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["biceps"]', '["forearms"]', '["Halteri avuç içleriniz yukarı bakacak şekilde, birkaç santim aralıkla iki elinizle tutun.", "Gövdeniz düz ve başınız yukarıda ayakta durun. Ayaklarınız yaklaşık omuz genişliğinde, dirsekleriniz gövdenize yakın olmalıdır. Bu sizin başlangıç pozisyonunuzdur. İpucu: Hareket boyunca üst kollarınızı ve dirseklerinizi sabit tutacaksınız.", "Ön kollar biceps''inize değene kadar barı yarım daire şeklinde yukarı kıvırın. Hareketin bu kısmında nefes verin ve en üstte biceps''inizi bir saniye sertçe kasın. İpucu: Ağırlığı kaldırırken sırtınızı bükmekten veya sallanma hareketleri kullanmaktan kaçının. Yalnızca ön kollar hareket etmelidir.", "Nefes alarak yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Close-Grip_Standing_Barbell_Curl/0.jpg", "Close-Grip_Standing_Barbell_Curl/1.jpg"]', 360.0, 'Close-Grip Standing Barbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6604d17c-192b-535f-897c-5890e98f504c', 'free-exercise-db', 'Cocoons', 'Cocoons (Kozalak Mekik)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Yerde sırtüstü uzanarak başlayın. Bacaklarınız düz, kollarınız başınızın arkasına doğru uzanmış olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Hareketi gerçekleştirmek için dizlerinizi göğsünüze doğru çekin ve kalçanızı yerden kaldırmak için pelvisinizi döndürün. Bunu yaparken omurganızı bükün ve aynı anda mekik hareketi yapmak için kollarınızı başınızın üzerinden geri getirin.", "Kısa bir duraklamanın ardından başlangıç pozisyonuna dönün."]', 'strength', '["Cocoons/0.jpg", "Cocoons/1.jpg"]', 360.0, 'Cocoons', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('aa435481-b31f-524d-b308-35bb558d52f1', 'free-exercise-db', 'Conans_Wheel', 'Conan''s Wheel', NULL, 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["abdominals", "biceps", "calves", "forearms", "lower back", "shoulders", "traps"]', '["Ağırlık yüklendikten sonra aletin ucundan zurcher hold tutuşunu alın. Barı dirseğinizin kıvrımına yerleştirin ve bileğinizi tutun. Ağırlığı ön kollarınızdan uzak tutmaya çalışın.", "Ağırlığı yerden kaldırarak başlayın. Sıkı ve dik bir duruş koruyarak kısa ve hızlı adımlarla yürümeye başlayın. Bir daire çizerek dönerken yukarıya ve uzağa bakın. Hareket sırasında nefesinizi tutmayın. Bir veya daha fazla tam tur tamamlayana kadar yürümeye devam edin."]', 'strongman', '["Conans_Wheel/0.jpg", "Conans_Wheel/1.jpg"]', 480.0, 'Conan''s Wheel', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1aea19db-7980-547f-86b5-7dddeac01b8d', 'free-exercise-db', 'Concentration_Curls', 'Concentration Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Düz bir bench''e oturun ve bacaklarınızın arasında önünüzde bir dambıl bulundurun. Bacaklarınız açık, dizleriniz bükülü ve ayaklarınız yerde olmalıdır.", "Sağ kolunuzla dambılı alın. Sağ üst kolunuzun arka kısmını sağ iç uyluğunuzun üst kısmına yerleştirin. Avuç içinizi uyluğunuzdan uzağa, öne bakacak şekilde çevirin. İpucu: Kolunuz uzamış olmalı ve dambıl yerden havada durmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kolunuzu sabit tutarak, nefes verirken biceps''inizi kasarak ağırlığı öne doğru curl yapın. Yalnızca ön kollar hareket etmelidir. Biceps''iniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar harekete devam edin. İpucu: Hareketin üst noktasında kolunuzun serçe parmağının başparmağınızdan daha yukarıda olduğundan emin olun. Bu, iyi bir kasılma sağlar. Biceps''i sıkarken kasılmış pozisyonda bir saniye bekleyin.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna getirmeye başlayın. Dikkat: Hiçbir zaman sallanma hareketlerinden kaçının.", "Önerilen tekrar sayısı kadar tekrarlayın. Ardından hareketi sol kolla yapın."]', 'strength', '["Concentration_Curls/0.jpg", "Concentration_Curls/1.jpg"]', 360.0, 'Concentration Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c88da192-f430-55e7-9b84-1b8b558f72ed', 'free-exercise-db', 'Cross-Body_Crunch', 'Çapraz Mekik', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Sırtüstü düz uzanın ve dizlerinizi yaklaşık 60 derece bükün.", "Ayaklarınızı yere düz basın ve ellerinizi gevşekçe başınızın arkasına koyun. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi yukarı kıvrılın ve sağ dirseğinizi ve omzunuzu vücudunuzun karşısına getirirken aynı anda sol dizinizi sol omzunuza doğru çekin. Dirseğinizle uzanın ve dizinize dokunmaya çalışın. Hareketi yaparken nefes verin. İpucu: Yalnızca dirseği değil omzunuzu da dizinize doğru getirmeye çalışın ve önemli olanın sadece dirseği hareket ettirmek değil, hareketi yaparken karın kaslarını kasmak olduğunu unutmayın.", "Nefes alırken başlangıç pozisyonuna geri inin ve sol dirsek ile sağ dizle tekrarlayın.", "Belirtilen tüm tekrarlar tamamlanana kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Cross-Body_Crunch/0.jpg", "Cross-Body_Crunch/1.jpg"]', 360.0, 'Cross-Body Crunch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9ca5e3a5-5fe6-5fac-a7ac-329ed529107e', 'free-exercise-db', 'Cross_Body_Hammer_Curl', 'Cross Body Hammer Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Her elinizde birer dambıl ile dik durun. Eller yanlarınızda aşağıda ve avuç içleri içe bakıyor olmalıdır.", "Avuç içlerinizi içe bakar tutarak ve kolunuzu bükmeden, nefes verirken sağ koldaki dambılı sol omzunuza doğru kaldırın. Dambılın üst kısmını omzunuza değdirin ve kasılmayı bir saniye tutun.", "Nefes alırken dambılı aynı yol üzerinden yavaşça indirin, ardından aynı hareketi sol kol için tekrarlayın.", "Her kol için önerilen tekrar sayısı tamamlanana kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Cross_Body_Hammer_Curl/0.jpg", "Cross_Body_Hammer_Curl/1.jpg"]', 360.0, 'Cross Body Hammer Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('18b7dc1f-6c02-5c0f-9043-680c85680405', 'free-exercise-db', 'Cross_Over_-_With_Bands', 'Cross Over (Direnç Bandı)', 'push', 'beginner', 'compound', '["bands"]', '["chest"]', '["biceps", "shoulders"]', '["Bir egzersiz bandını sabit bir direğin etrafına sabitleyin.", "Direğe sırtınız dönükken bandın iki ucundaki saplardan tutun ve banda gerginlik vermek için yeterince ileri adım atın.", "Kollarınızı yanlara, yere paralel ve gövdenize dik olacak şekilde (gövdeniz ve kollarınız \"T\" harfine benzemeli) ve avuç içleriniz ileri bakacak şekilde kaldırın. Dirsekleriniz hafifçe bükülü şekilde kollar uzanmış olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Kollarınızı düz tutarak, nefes verirken ve göğüs kaslarınızı kasarak yarım daire hareketiyle göğsünüzün önünde birleştirin. Kasılmayı bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar yapın."]', 'strength', '["Cross_Over_-_With_Bands/0.jpg", "Cross_Over_-_With_Bands/1.jpg"]', 360.0, 'Cross Over - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1bf05fb7-dffb-5c06-8f44-523dcbbb2934', 'free-exercise-db', 'Crossover_Reverse_Lunge', 'Çapraz Geri Lunge (Hamle)', 'pull', 'intermediate', NULL, '[]', '["lower back"]', '["abdominals", "abductors", "glutes", "hamstrings", "quadriceps"]', '["Ayaklarınız omuz genişliğinde açık dikilin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Bir ayağınızla geriye adım atarak ve kalçanızı ve ön dizinizi bükerek geri lunge yapın. Bunu yaparken gövdenizi ön bacağın üzerinden çapraz olarak döndürün.", "Kısa bir beklemeden sonra başlangıç pozisyonuna dönün ve diğer tarafta tekrarlayın; dönüşümlü olarak devam edin."]', 'stretching', '["Crossover_Reverse_Lunge/0.jpg", "Crossover_Reverse_Lunge/1.jpg"]', 150.0, 'Crossover Reverse Lunge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6df3bf4c-dfb1-544e-a36d-ea0b1edb8dc7', 'free-exercise-db', 'Crucifix', 'Crucifix (Yana Açık Statik Tutuş)', 'static', 'beginner', 'isolation', '["other"]', '["shoulders"]', '["forearms"]', '["Crucifix hareketinde ağırlıkları süre boyunca yana açık şekilde statik olarak tutarsınız. Bu hareket dambıllarla çalışılabilse de, farklı hissettirdiği için baltalar ve çekiçler gibi kullanılan çeşitli aletlerle çalışmak en iyisidir.", "Ayakta durarak başlayın ve aletleri tutarak kollarınızı yanlara kaldırın. Kollarınız yere paralel olmalıdır. Müsabakada, paralelliği bozduğunuzda sizi uyarmak için hakemler veya sensörler kullanılır. Ne kadar dayanabilirseniz tutun. Genellikle ağırlıklar, 30-60 saniyede pes edeceğiniz kadar ağır olmalıdır."]', 'strongman', '["Crucifix/0.jpg", "Crucifix/1.jpg"]', 480.0, 'Crucifix', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b4d9cb1e-afa8-5ecb-b985-6138ba385c89', 'free-exercise-db', 'Crunch_-_Hands_Overhead', 'Mekik (Eller Başın Üzerinde)', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Sırtınız düz ve dizleriniz, arka bacaklarınız ile baldırlarınız arasında yaklaşık 60 derecelik bir açı olacak şekilde bükülü halde yere uzanın.", "Ayaklarınızı yere düz basın ve kollarınızı avuç içleriniz çapraz olacak şekilde başınızın üzerine doğru uzatın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst vücudunuzu öne doğru kıvırın ve kürek kemiklerinizi yerden hafifçe kaldırın. Her zaman kollarınızı başınız, boynunuz ve omuzlarınızla aynı hizada tutun. Onları bu konumdan öne doğru hareket ettirmeyin. Hareketin bu kısmında nefes verin ve kasılmayı bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Crunch_-_Hands_Overhead/0.jpg", "Crunch_-_Hands_Overhead/1.jpg"]', 360.0, 'Crunch - Hands Overhead', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('daa0815e-bf2e-57ad-b90f-1f6880ba606b', 'free-exercise-db', 'Crunch_-_Legs_On_Exercise_Ball', 'Mekik (Bacaklar Pilates Topunda)', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Ayaklarınız bir egzersiz topunun üzerinde ve dizleriniz 90 derece bükülü şekilde sırtüstü düz uzanın.", "Ayaklarınızı üç dört inç (yaklaşık 8-10 cm) aralıklı yerleştirin ve ayak parmaklarınızı birbirine değecek şekilde içe doğru çevirin.", "Ellerinizi dirsekleriniz içeride olacak şekilde başınızın iki yanına hafifçe yerleştirin. İpucu: Parmaklarınızı başınızın arkasında kilitlemeyin.", "Karın kaslarınızı daha iyi izole etmek için belinizin boşluğunu yere doğru bastırın. Bu sizin başlangıç pozisyonunuzdur.", "Omuzlarınızı yerden kaldırmaya başlayın ve alt belinizle yere olabildiğince sert bastırmaya devam edin. Omuzlarınız yerden yalnızca yaklaşık dört inç (10 cm) kalkmalı ve alt belinizin yerde kalması gerekir. Hareketin bu kısmında nefes verin. Kasılmanın üst noktasında karın kaslarınızı sert şekilde sıkın ve bir saniye bekleyin. İpucu: Yavaş ve kontrollü bir harekete odaklanın. Hiçbir zaman ivme kullanmaktan kaçının.", "Nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Crunch_-_Legs_On_Exercise_Ball/0.jpg", "Crunch_-_Legs_On_Exercise_Ball/1.jpg"]', 360.0, 'Crunch - Legs On Exercise Ball', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c679f483-a3cc-5a8c-bc9f-e5f66df36c09', 'free-exercise-db', 'Crunches', 'Mekik (Crunch)', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Ayaklarınız yerde düz olacak şekilde sırtüstü düz bir şekilde uzanın veya dizleriniz 90 derece bükülü şekilde ayaklarınızı bir bench üzerine koyun. Ayaklarınızı bench üzerine koyuyorsanız, aralarında üç dört parmak (yaklaşık 8-10 cm) mesafe bırakın ve ayak parmaklarınızı birbirine değecek şekilde içe doğru çevirin.", "Şimdi dirsekleriniz içeride kalacak şekilde ellerinizi başınızın iki yanına hafifçe koyun. İpucu: Parmaklarınızı başınızın arkasında kilitlemeyin.", "Karın kaslarınızı daha iyi izole etmek için belinizin kavisli kısmını yere bastırarak omuzlarınızı yerden kaldırmaya başlayın.", "Karın kaslarınızı kasarken ve nefes verirken alt sırtınızla olabildiğince güçlü bir şekilde yere bastırmaya devam edin. Omuzlarınız yerden sadece yaklaşık 10 cm kalkmalı ve alt sırtınız yerde kalmalıdır. Hareketin üst noktasında karın kaslarınızı sertçe kasın ve kasılmayı bir saniye tutun. İpucu: Yavaş ve kontrollü harekete odaklanın; ivme kullanarak kendinizi kandırmayın.", "Bir saniyelik kasılmadan sonra nefes alırken yavaşça tekrar başlangıç pozisyonuna inmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Crunches/0.jpg", "Crunches/1.jpg"]', 360.0, 'Crunches', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2902624a-3f4a-59d4-b63b-7a816dc88c4b', 'free-exercise-db', 'Cuban_Press', 'Cuban Press (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["traps"]', '["Ayakta dururken her elinize bir dambıl alın ve avuç içleriniz aşağı bakacak (pronated) şekilde tutun. Üst kollarınızı yere paralel olacak şekilde kaldırın ve ön kollarınızın \"korkuluk\" (scarecrow) pozisyonunda sarkmasına izin verin. Bu sizin başlangıç pozisyonunuzdur.", "Harekete başlamak için omuzlarınızı dışa doğru döndürerek üst kolu 180 derece hareket ettirin. Üst kolları yerinde tutarak bilekleriniz doğrudan dirseklerinizin üzerine gelene ve ön kollarınız yere dik olana kadar döndürün.", "Şimdi dirseklerinizi açarak dambılları başınızın üzerine doğru kollarınızı düzleştirecek şekilde itin.", "Nefes alırken adımları tersine çevirerek başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Cuban_Press/0.jpg", "Cuban_Press/1.jpg"]', 360.0, 'Cuban Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('edbebcc0-ecc6-5724-a6c1-db143a8122b3', 'free-exercise-db', 'Dancers_Stretch', 'Dansçı Esnetmesi', 'static', 'beginner', NULL, '[]', '["lower back"]', '["abductors", "glutes"]', '["Yerde dik oturun.", "Sağ bacağınızı dizi bükülü halde sol bacağınızın üzerinden geçirin. Sol bacağınız düz ve yerde olmalıdır.", "Sol kolunuzu sağ bacağınızın üzerine, sağ elinizi ise yere yerleştirin.", "Üst vücudunuzu sağa doğru döndürün ve 10-20 saniye bekleyin. Taraf değiştirin."]', 'stretching', '["Dancers_Stretch/0.jpg", "Dancers_Stretch/1.jpg"]', 150.0, 'Dancer''s Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('506a4b24-e862-5ead-8513-c8e2343e16cd', 'free-exercise-db', 'Dead_Bug', 'Dead Bug', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Sırtüstü yatarak ellerinizi tavana doğru başınızın üzerinde uzatın.", "Ayaklarınızı, dizlerinizi ve kalçanızı 90 dereceye kadar yukarı getirin.", "Kaburga kafesinizi aşağı indirmek ve sırtınızı yere yapıştırmak için kuvvetlice nefes verin; pelvisinizi yukarı doğru çevirin ve kalçanızı sıkın. Bu pozisyonu hareket boyunca koruyun. Bu sizin başlangıç pozisyonunuzdur.", "Bir bacağınızı uzatarak, diz ve kalçayı düzleştirip bacağı yerin hemen üzerine getirerek egzersize başlayın.", "Hareketi yaparken bel ve pelvis pozisyonunuzu koruyun, çünkü sırtınız kavis yapmak isteyecektir.", "Sıkı kalın ve çalışan bacağı başlangıç pozisyonuna geri getirin.", "Karşı tarafta tekrarlayın ve set tamamlanana kadar dönüşümlü olarak devam edin."]', 'strength', '["Dead_Bug/0.jpg", "Dead_Bug/1.jpg"]', 360.0, 'Dead Bug', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eaed120c-b0f9-540d-945c-2ba9fbfb51e8', 'free-exercise-db', 'Deadlift_with_Bands', 'Deadlift (Direnç Bandı)', 'pull', 'expert', 'compound', '["barbell"]', '["lower back"]', '["forearms", "glutes", "hamstrings", "middle back", "quadriceps", "traps"]', '["Kısa bantlarla deadlift yapmak için başlamadan önce bantları barın üzerine geçirin ve hazırlanmak için içlerine basın. Uzun bantlar için ise, ağır dambıllar veya bir rack gibi sağlam bir tabana sabitlenmeleri gerekir.", "Ayaklarınız ve tutuşunuz yerleştikten sonra derin bir nefes alın, ardından kaval kemikleriniz bara değene kadar kalçanızı alçaltın ve dizlerinizi bükün. Başınızla ileriye bakın, göğsünüzü yukarıda ve belinizi kavisli tutun ve topuklarınızdan iterek ağırlığı yukarı kaldırmaya başlayın. Bar dizlerinizi geçtikten sonra barı güçlü bir şekilde geriye doğru çekin, kürek kemiklerinizi birbirine yaklaştırın ve kalçanızı bara doğru ileri itin.", "Kalçanızdan eğilerek ve barı yere doğru yönlendirerek indirin."]', 'powerlifting', '["Deadlift_with_Bands/0.jpg", "Deadlift_with_Bands/1.jpg"]', 360.0, 'Deadlift with Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5f7d52cd-284d-5ee3-b47e-dbf1834b8413', 'free-exercise-db', 'Deadlift_with_Chains', 'Deadlift (Halter, Zincirli)', 'pull', 'expert', 'compound', '["barbell"]', '["lower back"]', '["forearms", "glutes", "hamstrings", "middle back", "quadriceps", "traps"]', '["Zincirleri barın kollarına (sleeve) bağlayabilir veya ortasını barın üzerine asabilirsiniz; böylece kaldırdıkça ağırlık daha fazla artar.", "Bar ayaklarınızın üzerinde ortalanacak şekilde yaklaşın. Ayaklarınız yaklaşık kalça genişliğinde açık olmalıdır. Kürek kemiklerinizin öne doğru açılmasına izin vererek kalçadan bükülüp barı omuz genişliğinde kavrayın. Genellikle üsten tutuş ya da ağır setlerde karışık (biri üstten, biri alttan) tutuş kullanılır. Ayaklarınız ve tutuşunuz hazır olduğunda derin bir nefes alın, ardından kaval kemikleriniz bara değene kadar kalçanızı alçaltın ve dizlerinizi bükün.", "Başınızla ileri bakın, göğsünüzü yukarıda ve sırtınızı kavisli tutun ve ağırlığı yukarı hareket ettirmek için topuklarınızdan itmeye başlayın. Bar dizlerin üstüne çıktıktan sonra barı sertçe geriye doğru çekin, kalçanızı bara doğru ileri sürerken kürek kemiklerinizi birbirine doğru sıkın.", "Kalçanızdan bükülerek ve barı yere doğru yönlendirerek barı indirin."]', 'powerlifting', '["Deadlift_with_Chains/0.jpg", "Deadlift_with_Chains/1.jpg"]', 360.0, 'Deadlift with Chains', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f2168baa-b7c7-5bb0-9809-b99f44b57faa', 'free-exercise-db', 'Decline_Barbell_Bench_Press', 'Decline Bench Press (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Bacaklarınızı decline bankın ucunda sabitleyin ve yavaşça bankta uzanın.", "Orta genişlikte bir tutuşla (hareketin ortasında ön kollar ile üst kollar arasında 90 derecelik açı oluşturan tutuş) barı raftan alın ve kollarınız kilitli şekilde tam üzerinizde tutun. Kollar yere dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur. İpucu: Rotator cuff''ınızı korumak için barı raftan almanızda size yardımcı olacak bir spotter bulundurmanız en iyisidir.", "Nefes alırken barı alt göğsünüzde hissedene kadar yavaşça indirin.", "Bir saniye bekledikten sonra, nefes verirken göğüs kaslarınızı kullanarak barı itip başlangıç pozisyonuna getirin. Kollarınızı kilitleyin ve kasılmış pozisyonda göğsünüzü sıkın, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İnişin yukarı çıkıştan en az iki kat uzun sürmesi gerekir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde barı rafa geri yerleştirin."]', 'strength', '["Decline_Barbell_Bench_Press/0.jpg", "Decline_Barbell_Bench_Press/1.jpg"]', 360.0, 'Decline Barbell Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bd345310-290b-525b-b7ea-af1ad588149d', 'free-exercise-db', 'Decline_Close-Grip_Bench_To_Skull_Crusher', 'Decline Close-Grip Bench - Skull Crusher (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "shoulders"]', '["Bacaklarınızı decline sehpanın ucuna sabitleyin ve sehpaya yavaşça uzanın.", "Dar bir tutuşla (omuz genişliğinden biraz daha dar) halteri raftan kaldırın ve kollarınız kilitli, dirsekleriniz içeride olacak şekilde tepenizde tutun. Kollar yere dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur. İpucu: Rotator manşetinizi korumak için halteri raftan almanız için bir yardımcı (spotter) olması en iyisidir.", "Şimdi nefes alırken halteri alt göğsünüze doğru indirin. Bu hareketi yaparken dirseklerinizi içeride tutun.", "Halteri tekrar yukarı itmek için triceps''i kullanarak nefes verirken başlangıç pozisyonuna itin.", "Nefes alırken ve üst kollarınızı sabit tutarken, halterin alnınıza hafifçe değdiğini hissedene kadar ön kollarınızı kendinize doğru yarım daire hareketiyle hareket ettirerek halteri yavaşça indirin. Hareketin bu kısmında nefes alın.", "Triceps''i kasarak ve nefes vererek halteri başlangıç pozisyonuna geri kaldırın.", "Önerilen tekrar sayısı tamamlanana kadar 3-6. adımları tekrarlayın."]', 'strength', '["Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg", "Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg"]', 360.0, 'Decline Close-Grip Bench To Skull Crusher', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6b9bdf50-e9f1-54f0-a228-a0e07687b124', 'free-exercise-db', 'Decline_Crunch', 'Decline Mekik', 'pull', 'intermediate', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Bacaklarınızı decline bench''in ucunda sabitleyin ve uzanın.", "Şimdi dirsekleriniz içeride kalacak şekilde ellerinizi başınızın iki yanına hafifçe koyun. İpucu: Parmaklarınızı başınızın arkasında kilitlemeyin.", "Karın kaslarınızı daha iyi izole etmek için belinizin kavisli kısmını bench''e bastırarak omuzlarınızı bench''ten kaldırmaya başlayın.", "Karın kaslarınızı kasarken ve nefes verirken alt sırtınızla olabildiğince güçlü bir şekilde bastırmaya devam edin. Omuzlarınız bench''ten sadece yaklaşık 10 cm kalkmalı ve alt sırtınız bench üzerinde kalmalıdır. Hareketin üst noktasında karın kaslarınızı sertçe kasın ve kasılmayı bir saniye tutun. İpucu: Yavaş ve kontrollü harekete odaklanın; ivme kullanarak kendinizi kandırmayın.", "Bir saniyelik kasılmadan sonra nefes alırken yavaşça tekrar başlangıç pozisyonuna inmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Decline_Crunch/0.jpg", "Decline_Crunch/1.jpg"]', 360.0, 'Decline Crunch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0d566239-918c-5575-a390-04b0ff2e2c1f', 'free-exercise-db', 'Decline_Dumbbell_Bench_Press', 'Decline Bench Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders", "triceps"]', '["Bacaklarınızı decline sehpanın ucuna sabitleyin ve her elinizde uyluklarınızın üzerinde bir dambıl olacak şekilde uzanın. Avuç içleriniz birbirine bakıyor olmalıdır.", "Uzandıktan sonra dambılları omuz genişliğinde önünüze getirin.", "Omuz genişliğine geldiğinde, avuç içleriniz sizden uzağa bakacak şekilde bileklerinizi öne doğru döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken ağırlıkları yavaşça yanlarınıza indirin. Dambılların kontrolünü her zaman koruyun. İpucu: Hareket boyunca ön kollar her zaman yere dik olmalıdır.", "Nefes verirken göğüs kaslarınızı kullanarak dambılları yukarı itin. Kollarınızı kasılmış pozisyonda kilitleyin, göğsünüzü sıkın, bir saniye bekleyin ve ardından yavaşça inmeye başlayın. İpucu: İnmek, yukarı çıkmaktan en az iki kat daha uzun sürmelidir.", "Hareketi antrenman programınızdaki belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Decline_Dumbbell_Bench_Press/0.jpg", "Decline_Dumbbell_Bench_Press/1.jpg"]', 360.0, 'Decline Dumbbell Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2f70a4c0-d364-56ca-859a-0b10a81df3f8', 'free-exercise-db', 'Decline_Dumbbell_Flyes', 'Decline Fly (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '[]', '["Bacaklarınızı decline bench''in ucunda sabitleyin ve her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde uzanın. Avuç içleriniz birbirine bakmalıdır.", "Uzandıktan sonra dambılları önünüzde omuz genişliğinde konumlandırın. Avuç içleri birbirine bakmalı ve kollar yere dik ve tamamen uzatılmış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Biceps tendonunda stresi önlemek için dirseklerinizi hafifçe bükülü tutarak, göğsünüzde bir esneme hissedene kadar kollarınızı iki yana geniş bir yay çizerek indirin. Hareketin bu kısmında nefes alın. İpucu: Hareket boyunca kolların sabit kalması gerektiğini unutmayın; hareket sadece omuz ekleminde gerçekleşmelidir.", "Göğüs kaslarınızı sıkarak ve nefes vererek kollarınızı başlangıç pozisyonuna geri getirin. İpucu: Ağırlıkları indirirken kullandığınız hareket yayının aynısını kullandığınızdan emin olun.", "Kasılmış pozisyonda bir saniye bekleyin ve hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Decline_Dumbbell_Flyes/0.jpg", "Decline_Dumbbell_Flyes/1.jpg"]', 360.0, 'Decline Dumbbell Flyes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b976703f-7971-5638-88eb-07b838317b28', 'free-exercise-db', 'Decline_Dumbbell_Triceps_Extension', 'Decline Triceps Extension (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Bacaklarınızı decline bench''in ucuna sabitleyin ve her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde uzanın. Avuç içleriniz birbirine bakacaktır.", "Uzandıktan sonra dambılları omuz genişliğinde önünüze doğru hareket ettirin. Avuç içleri birbirine bakmalı, kollar yere dik ve tamamen uzamış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken ve üst kollarınızı sabit (dirsekler içeride) tutarak, başparmaklarınız kulaklarınızın yanına gelene kadar ön kollarınızı yarım daire şeklinde kendinize doğru hareket ettirerek dambılları yavaşça indirin. Hareketin bu kısmında nefes alın.", "Triceps''inizi kasarak ve nefes vererek dambılları başlangıç pozisyonuna kaldırın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Decline_Dumbbell_Triceps_Extension/0.jpg", "Decline_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'Decline Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5e0abc29-5d0d-54b6-b81f-b9e47cc789ba', 'free-exercise-db', 'Decline_EZ_Bar_Triceps_Extension', 'Decline Triceps Extension (EZ Bar)', 'push', 'beginner', 'isolation', '["barbell"]', '["triceps"]', '[]', '["Bacaklarınızı decline bankın ucunda sabitleyin ve yavaşça bankta uzanın.", "Dar bir tutuşla (omuz genişliğinden biraz daha dar) EZ barı raftan alın ve kollarınız kilitli ve dirsekleriniz içeride olacak şekilde tam üzerinizde tutun. Kollar yere dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur. İpucu: Rotator cuff''ınızı korumak için barı raftan almanızda size yardımcı olacak bir spotter bulundurmanız en iyisidir.", "Üst kollarınızı sabit tutarak, ön kollarınızı yarım daire çizerek size doğru hareket ettirip barı alnınıza hafifçe değene kadar yavaşça indirin. Hareketin bu kısmında nefes alın.", "Triceps''i kasarak ve nefes vererek barı başlangıç pozisyonuna kaldırın.", "Önerilen tekrar sayısı tamamlanana kadar tekrarlayın."]', 'strength', '["Decline_EZ_Bar_Triceps_Extension/0.jpg", "Decline_EZ_Bar_Triceps_Extension/1.jpg"]', 360.0, 'Decline EZ Bar Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c514069f-516e-5793-9b94-ab9b76d25d0b', 'free-exercise-db', 'Decline_Oblique_Crunch', 'Decline Yan Karın Mekik', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Bacaklarınızı decline bench''in ucunda sabitleyin ve yavaşça bench''e uzanın.", "Gövdeniz yerden ölçüldüğünde yaklaşık 35-45 derece olana kadar üst vücudunuzu bench''ten kaldırın.", "Bir elinizi başınızın yanına, diğerini uyluğunuza koyun. Bu sizin başlangıç pozisyonunuz olacak.", "Gövdenizi sola çevirirken üst vücudunuzu başlangıç pozisyonundan yavaşça kaldırın. Nefes vererek sağ dirseğiniz sol dizinize değene kadar mekik hareketine devam edin. Bu kasılmış pozisyonu bir saniye tutun. İpucu: Karın kaslarınızı sıkı tutmaya ve hareketi yavaş ve kontrollü yapmaya odaklanın.", "Nefes alırken vücudunuzu yavaşça başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar bir seti sağ tarafta tamamladıktan sonra sol tarafa geçin. İpucu: Gövdenizi gerçekten çevirmeye ve yukarı pozisyondayken kasılmayı hissetmeye odaklanın."]', 'strength', '["Decline_Oblique_Crunch/0.jpg", "Decline_Oblique_Crunch/1.jpg"]', 360.0, 'Decline Oblique Crunch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2075dbf1-a15a-5fad-a16d-c0c2b2ab45d8', 'free-exercise-db', 'Decline_Push-Up', 'Decline Şınav', 'push', 'beginner', 'compound', '[]', '["chest"]', '["shoulders", "triceps"]', '["Yüzüstü yere uzanın, ellerinizi yaklaşık 36 inç (90 cm) aralıklı yerleştirin ve gövdenizi kollarınızın uzunluğu kadar yukarıda tutun. Ayaklarınızı bir kutuya veya sehpaya çıkarın. Bu sizin başlangıç pozisyonunuzdur.", "Sonra nefes alırken göğsünüz neredeyse yere değene kadar kendinizi aşağı indirin.", "Şimdi nefes verin ve göğsünüzü sıkarak üst vücudunuzu başlangıç pozisyonuna geri itin.", "Üst kasılma noktasında kısa bir duraklamanın ardından, gerektiği kadar tekrar için tekrar aşağı inmeye başlayabilirsiniz."]', 'strength', '["Decline_Push-Up/0.jpg", "Decline_Push-Up/1.jpg"]', 360.0, 'Decline Push-Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e7f01647-7665-53b2-84c9-be80d42a0317', 'free-exercise-db', 'Decline_Reverse_Crunch', 'Decline Reverse Crunch', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Decline sehpada sırtüstü uzanın ve sehpanın üst kısmını iki elinizle kavrayın. Bu pozisyonda vücudunuzun kaymasına izin vermeyin.", "Dizlerinizi ve ayaklarınızı bitişik tutarak karın kaslarınızla bacaklarınızı yere paralel tutun. İpucu: Bacaklarınız dizde hafif bükülü olacak şekilde tamamen uzamış olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken pelvisinizi geriye yuvarlayıp kalçanızı sehpadan kaldırarak bacaklarınızı gövdenize doğru getirin. Hareketin sonunda dizleriniz göğsünüze değiyor olacaktır.", "Kasılmayı bir saniye tutun ve nefes alırken bacaklarınızı başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Decline_Reverse_Crunch/0.jpg", "Decline_Reverse_Crunch/1.jpg"]', 360.0, 'Decline Reverse Crunch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('012a0f5f-110c-58d6-b9f7-0ee84c5ae35e', 'free-exercise-db', 'Decline_Smith_Press', 'Decline Press (Smith Makinesi)', 'push', 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Smith makinesinin altına bir decline bench yerleştirin. Şimdi barı, uzandığınızda kollarınız neredeyse tamamen açıkken ulaşabileceğiniz bir yüksekliğe ayarlayın. Omuz genişliğinden geniş, pronasyon (avuç içleri öne/aşağı) tutuşla barı kilitten çıkarın ve kollarınız uzamış halde tam üzerinizde tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken dirseklerinizin bükülmesine izin vererek barı kontrollü bir şekilde indirin ve gövdenize hafifçe değdirin.", "Kısa bir duraklamanın ardından nefes vererek dirseklerinizi açıp barı başlangıç pozisyonuna getirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Set tamamlandığında barı rafa geri kilitleyin."]', 'strength', '["Decline_Smith_Press/0.jpg", "Decline_Smith_Press/1.jpg"]', 360.0, 'Decline Smith Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('54249510-205d-5c5e-b422-49c4312f2115', 'free-exercise-db', 'Deficit_Deadlift', 'Deficit Deadlift', 'pull', 'intermediate', 'compound', '["barbell"]', '["lower back"]', '["forearms", "glutes", "hamstrings", "middle back", "quadriceps", "traps"]', '["Üzerine çıkabileceğiniz, genellikle 2,5-7,5 cm yüksekliğinde bir platform veya ağırlık plakaları hazırlayarak başlayın. Bara, ayaklarınızın üzerinde ortalanacak şekilde yaklaşın. Ayaklarınız yaklaşık kalça genişliğinde olmalıdır. Kalçanızdan eğilerek barı omuz genişliğinde kavrayın ve kürek kemiklerinizin öne doğru açılmasına izin verin. Genellikle üstten tutuş veya ağır setlerde karışık tutuş kullanılır.", "Ayaklarınız ve tutuşunuz yerleştikten sonra derin bir nefes alın, ardından kaval kemikleriniz bara değene kadar kalçanızı alçaltın ve dizlerinizi bükün. Başınızla ileriye bakın, göğsünüzü yukarıda ve belinizi kavisli tutun ve topuklarınızdan iterek ağırlığı yukarı kaldırmaya başlayın. Bar dizlerinizi geçtikten sonra barı güçlü bir şekilde geriye doğru çekin, kürek kemiklerinizi birbirine yaklaştırın ve kalçanızı bara doğru ileri itin.", "Kalçanızdan eğilerek ve barı yere doğru yönlendirerek indirin."]', 'powerlifting', '["Deficit_Deadlift/0.jpg", "Deficit_Deadlift/1.jpg"]', 360.0, 'Deficit Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('614ceca5-e8ee-58d3-a878-d4b7a17b7545', 'free-exercise-db', 'Depth_Jump_Leap', 'Depth Jump Leap (Kutudan Kutuya Sıçrama)', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Bu çalışma için biri 12-16 inç (30-40 cm), diğeri 22-26 inç (55-65 cm) yüksekliğinde iki kutuya veya sehpaya ihtiyacınız olacak.", "İki kutudan birinin üzerinde kollarınız yanlarda dururken ayaklarınız bitişik ve depth jump''taki gibi kenardan hafifçe dışarıda olacak şekilde durun. Diğer kutuyu, sporcunun yaklaşık iki üç fit (60-90 cm) önüne ve ona dönük olacak şekilde yerleştirin.", "İlk kutudan kendinizi bırakarak, iki ayakla inip aynı anda sıçrayarak başlayın.", "Kollarınızı ve vücudun tam açılmasını kullanarak yukarı ve öne doğru olabildiğince yoğun şekilde itip yüksek kutuya sıçrayın. Yine bacakların darbeyi sönümlemesine izin verin."]', 'plyometrics', '["Depth_Jump_Leap/0.jpg", "Depth_Jump_Leap/1.jpg"]', 480.0, 'Depth Jump Leap', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('25c12190-8948-54c5-9c89-404ef627004b', 'free-exercise-db', 'Dip_Machine', 'Dips (Makine)', 'push', 'beginner', 'compound', '["machine"]', '["triceps"]', '["chest", "shoulders"]', '["Dips makinesine sağlam şekilde oturun, ağırlığı seçin ve sapları sıkıca kavrayın.", "Şimdi triceps''e vurgu yapmak için dirseklerinizi yanlarınızda tutun. Dirsekler 90 derecelik açıyla bükülü olmalıdır.", "Triceps''i kasarak, nefes verirken kollarınızı aşağı doğru uzatın. İpucu: Hareketin en altında, triceps kasında gerginliği korumak için kollarınızı hafif bükülü tutmaya odaklanın.", "Şimdi nefes alırken kollarınızın yavaşça başlangıç pozisyonuna geri gelmesine izin verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dip_Machine/0.jpg", "Dip_Machine/1.jpg"]', 360.0, 'Dip Machine', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c5a3cdda-7e09-54e2-817f-28b78c661daf', 'free-exercise-db', 'Dips_-_Chest_Version', 'Dips (Göğüs Odaklı)', 'push', 'intermediate', 'compound', '["other"]', '["chest"]', '["shoulders", "triceps"]', '["Bu egzersiz için paralel barlara ihtiyacınız var. Başlangıç pozisyonuna geçmek için vücudunuzu barların üzerinde kolları tam uzatmış (kilitli) şekilde tutun.", "Nefes alırken gövdenizi yaklaşık 30 derece öne eğerek ve dirseklerinizi hafifçe dışa açarak göğsünüzde hafif bir gerilme hissedene kadar yavaşça inin.", "Gerilmeyi hissettiğinizde, nefes verirken göğsünüzü kullanarak vücudunuzu başlangıç pozisyonuna geri getirin. İpucu: Hareketin en üstünde göğsünüzü bir saniye sıkmayı unutmayın.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dips_-_Chest_Version/0.jpg", "Dips_-_Chest_Version/1.jpg"]', 360.0, 'Dips - Chest Version', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fbe7388b-5201-57c4-8f18-37e14e0bd41c', 'free-exercise-db', 'Dips_-_Triceps_Version', 'Dips (Triceps Odaklı)', 'push', 'beginner', 'compound', '["body only"]', '["triceps"]', '["chest", "shoulders"]', '["Başlangıç pozisyonuna geçmek için vücudunuzu paralel barların üzerinde kollarınız neredeyse kilitli şekilde kol boyu mesafede tutun.", "Şimdi nefes alın ve kendinizi yavaşça aşağı doğru indirin. Gövdeniz dik kalmalı ve dirsekleriniz vücudunuza yakın durmalıdır. Bu, triceps''in daha iyi devreye girmesine yardımcı olur. Üst kol ile ön kol arasında 90 derecelik bir açı oluşana kadar kendinizi indirin.", "Ardından nefes verin ve vücudunuzu başlangıç pozisyonuna getirmek için triceps''inizi kullanarak gövdenizi yukarı itin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dips_-_Triceps_Version/0.jpg", "Dips_-_Triceps_Version/1.jpg"]', 360.0, 'Dips - Triceps Version', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8c30445f-f7ab-5303-8a2a-098d582daef4', 'free-exercise-db', 'Donkey_Calf_Raises', 'Donkey Calf Raise (Makine)', 'push', 'intermediate', 'isolation', '["other"]', '["calves"]', '[]', '["Bu egzersiz için bir donkey calf raise makinesine ihtiyacınız olacak. Alt sırtınızı ve kalçanızı sağlanan pedli kolun altına yerleştirerek başlayın. Pede temas eden bölge kuyruk sokumu bölgesi olmalıdır.", "Her iki kolunuzu yan tutacaklara yerleştirin ve ayaklarınızın ön kısmını topuklar sarkacak şekilde calf bloğuna koyun. Hedeflemek istediğiniz bölgeye göre ayak parmaklarını öne, içe veya dışa hizalayın ve dizlerinizi kilitlemeden düzeltin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken ayak bileklerinizi mümkün olduğunca yukarı doğru açarak topuklarınızı kaldırın ve baldırınızı kasın. Dizin her zaman sabit kalmasını sağlayın; hiçbir zaman bükülme olmamalıdır. Aşağı inmeye başlamadan önce kasılmış pozisyonu bir saniye boyunca tutun.", "Nefes alırken topuklarınızı indirerek ve ayak bileklerinizi bükerek, baldırlarınız gerilene kadar yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Donkey_Calf_Raises/0.jpg", "Donkey_Calf_Raises/1.jpg"]', 360.0, 'Donkey Calf Raises', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6ee426c9-021b-56d0-befc-97408eb1c727', 'free-exercise-db', 'Double_Kettlebell_Alternating_Hang_Clean', 'Alternating Hang Clean (Çift Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["biceps", "calves", "forearms", "glutes", "lower back", "quadriceps", "traps"]', '["İki kettlebell''i ayaklarınızın arasına yerleştirin. Başlangıç pozisyonunu almak için kalçanızı geriye doğru itin ve düz ileriye bakın.", "Bir kettlebell''i omzunuza clean yapın ve diğer kettlebell''i tutmaya devam edin.", "Akıcı bir hareketle, üstteki kettlebell''i indirirken alttaki kettlebell''i yukarı doğru sürün."]', 'strength', '["Double_Kettlebell_Alternating_Hang_Clean/0.jpg", "Double_Kettlebell_Alternating_Hang_Clean/1.jpg"]', 360.0, 'Double Kettlebell Alternating Hang Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2686c37a-67e0-5008-b1d4-067875d512d9', 'free-exercise-db', 'Double_Kettlebell_Jerk', 'Kettlebell Jerk (Çift)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["calves", "quadriceps", "triceps"]', '["Her elinizde bir kettlebell''i sapından tutun.", "Bacaklarınızı ve kalçanızı açarak kettlebell''leri omuzlarınıza doğru çekerek omuzlarınıza alın (clean). Bunu yaparken bileklerinizi avuç içleri öne bakacak şekilde döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi dik tutarak dizlerinizi bükerek vücudunuzu aşağı indirin (dip).", "Hemen yön değiştirin ve topuklarınızla iterek ivme yaratmak için adeta zıplayın.", "Bunu yaparken kollarınızı açarak ve ağırlıkları hareket ettirmek için vücudunuzun ivmesini kullanarak kettlebell''leri kilitlenene kadar tepenize itin.", "Ayaklarınızı bir ayak önde, bir ayak arkada olacak şekilde split pozisyonda yere indirin.", "Ağırlıklar tepenizdeyken ayaklarınızı birleştirerek ayakta durma pozisyonuna dönün. Bir sonraki tekrar için ağırlıkları indirin."]', 'strength', '["Double_Kettlebell_Jerk/0.jpg", "Double_Kettlebell_Jerk/1.jpg"]', 360.0, 'Double Kettlebell Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2971dbe2-fd9b-5d51-9a61-f836ce2aded5', 'free-exercise-db', 'Double_Kettlebell_Push_Press', 'Çift Kettlebell Push Press', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["calves", "quadriceps", "triceps"]', '["İki kettlebell''i omuzlarınıza kaldırın (clean).", "Birkaç inç çömelin ve hareketi hızla tersine çevirin. Bacaklarınızdan gelen ivmeyi kettlebell''leri baş üstüne itmek için kullanın.", "Kettlebell''ler tamamen yukarıda kilitlendikten sonra, onları omuzlarınıza indirin ve tekrarlayın."]', 'strength', '["Double_Kettlebell_Push_Press/0.jpg", "Double_Kettlebell_Push_Press/1.jpg"]', 360.0, 'Double Kettlebell Push Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0391e801-b27f-52eb-b71d-8959a4e009aa', 'free-exercise-db', 'Double_Kettlebell_Snatch', 'Çift Kettlebell Snatch', 'pull', 'expert', 'compound', '["kettlebells"]', '["shoulders"]', '["glutes", "hamstrings", "quadriceps"]', '["İki kettlebell''i ayaklarınızın arkasına yerleştirin. Kettlebell''leri almak için dizlerinizi bükün ve geriye oturun.", "Kettlebell''leri bacaklarınızın arasından kuvvetle savurun ve yönü tersine çevirin.", "Kalçanızla itin ve kettlebell''leri kesintisiz tek bir hareketle başınızın üzerinde kilitleyin."]', 'strength', '["Double_Kettlebell_Snatch/0.jpg", "Double_Kettlebell_Snatch/1.jpg"]', 360.0, 'Double Kettlebell Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bdd64458-d6e2-59d9-9cef-7b9e3b5afe98', 'free-exercise-db', 'Double_Kettlebell_Windmill', 'Çift Kettlebell Windmill', 'pull', 'intermediate', NULL, '["kettlebells"]', '["abdominals"]', '["glutes", "hamstrings", "shoulders", "triceps"]', '["Bir kettlebell''i ön ayağınızın önüne koyun ve karşı kolunuzla bir kettlebell''i clean and press ile baş üstüne kaldırın. Bacaklarınızı ve kalçanızı açarak kettlebell''i omuzlarınıza doğru çekerek omzunuza getirin. Bunu yaparken bileğinizi döndürün, böylece avuç içi ileri baksın.", "Kettlebell her zaman kilitli şekilde, kalçanızı kilitli kettlebell yönüne doğru dışarı itin. Ayaklarınızı kilitli kettlebell''in olduğu koldan kırk beş derecelik bir açıyla dışa doğru çevirin.", "Kalçadan bir yana doğru eğilerek, kalçanızı dışarı iterek, kettlebell''i yerden alabilene kadar yavaşça eğilin. Baş üstünde tuttuğunuz kettlebell''e her zaman gözlerinizi sabitleyin.", "Kettlebell''i yerden aldıktan sonra bir saniye duraklayın ve hareketi tersine çevirerek başlangıç pozisyonuna dönün."]', 'strength', '["Double_Kettlebell_Windmill/0.jpg", "Double_Kettlebell_Windmill/1.jpg"]', 360.0, 'Double Kettlebell Windmill', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('330015ae-34c3-5e6f-9d89-d12517664133', 'free-exercise-db', 'Double_Leg_Butt_Kick', 'Çift Bacak Butt Kick', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Dizleriniz hafifçe bükülü şekilde ayakta durarak başlayın.", "Kalçanızı ve dizlerinizi bükerek hızlıca kısa bir mesafe çömelin ve hemen ardından maksimum dikey yükseklik için sıçrayın.", "Yukarı çıkarken dizlerinizi bükerek topuklarınızı kalçanıza değdirmeye çalışarak çekin.", "Hareketi dizleriniz sadece kısmen bükülü şekilde inerek bitirin ve darbeyi bacaklarınızla sönümleyin."]', 'plyometrics', '["Double_Leg_Butt_Kick/0.jpg", "Double_Leg_Butt_Kick/1.jpg"]', 480.0, 'Double Leg Butt Kick', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3f26ab08-b2bf-58f2-942c-3b8b2090c9c0', 'free-exercise-db', 'Downward_Facing_Balance', 'Yüzüstü Top Üzerinde Denge', 'static', 'intermediate', 'isolation', '["exercise ball"]', '["glutes"]', '["abdominals", "hamstrings"]', '["Bir egzersiz topunun üzerine yüzüstü uzanın.", "Karnınız top üzerinde dururken ellerinizle yerde ileri doğru yürüyün ve bacaklarınızı kaldırın; dirseklerinizi ve dizlerinizi uzatın."]', 'strength', '["Downward_Facing_Balance/0.jpg", "Downward_Facing_Balance/1.jpg"]', 360.0, 'Downward Facing Balance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('317d1247-1bfc-59b2-9846-0131e475862c', 'free-exercise-db', 'Drag_Curl', 'Drag Curl (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["biceps"]', '["forearms"]', '["Halteri supinasyon tutuşuyla (avuç içleri öne bakacak şekilde) kavrayın ve dirseklerinizi gövdenize yakın ve geride tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken, barı gövdenizle temas halinde tutarak yukarı \"sürükleyip\" dirseklerinizi geride tutarak kıvırın. İpucu: Gördüğünüz gibi dirsekleri yanlarınıza sabitlemeyeceksiniz, bunun yerine geriye getireceksiniz. Ayrıca omuzlarınızı kaldırmayın.", "Barı her zaman gövdenizle temas halinde tutarak yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Drag_Curl/0.jpg", "Drag_Curl/1.jpg"]', 360.0, 'Drag Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ad264063-0b9d-5bc8-a431-031ee10606f3', 'free-exercise-db', 'Drop_Push', 'Drop Push (Kutudan Şınav)', 'push', 'intermediate', 'compound', '["other"]', '["chest"]', '["shoulders", "triceps"]', '["Alçak kutuları veya başka platformları 2-3 feet (yaklaşık 60-90 cm) arayla yerleştirin.", "Ellerinizi kutuların üzerine koyarak kendinizi destekleyip aralarında şınav pozisyonuna geçin.", "İyi bir duruşla, yukarı bastırarak ve ellerinizi omuz genişliğine getirerek platformlardan aşağı düşün; iniş darbesini kollarınızla emerek yumuşatın."]', 'plyometrics', '["Drop_Push/0.jpg", "Drop_Push/1.jpg"]', 480.0, 'Drop Push', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9fa94923-13bc-5020-a2bb-13964230f36b', 'free-exercise-db', 'Dumbbell_Alternate_Bicep_Curl', 'Dönüşümlü Biceps Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Gövdeniz dik şekilde, her elinizde kol boyu kadar sarkan birer dambılla ayakta durun. Dirsekleriniz gövdenize yakın olmalı ve avuç içleriniz uyluklarınıza bakmalıdır.", "Üst kolunuzu sabit tutarak sağ dambılı curl yapın ve bu sırada avuç içlerini öne bakana kadar döndürün. Bu noktada nefes verirken biceps''inizi kasmaya devam edin; biceps tamamen kasılana ve dambıllar omuz seviyesine gelene kadar sürdürün. Biceps''inizi sıkarak kasılmış pozisyonda bir saniye bekleyin. İpucu: Sadece ön kollar hareket etmelidir.", "Nefes alırken dambılı yavaşça başlangıç pozisyonuna getirmeye başlayın. İpucu: İnerken avuç içlerinizi başlangıç pozisyonuna (uyluklarınıza bakacak şekilde) geri çevirmeyi unutmayın.", "Hareketi sol elle tekrarlayın. Bu bir tekrara eşittir.", "Önerilen tekrar sayısı kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Dumbbell_Alternate_Bicep_Curl/0.jpg", "Dumbbell_Alternate_Bicep_Curl/1.jpg"]', 360.0, 'Dumbbell Alternate Bicep Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('19e5dd98-dbb8-5d54-a01a-43e1c4fbc721', 'free-exercise-db', 'Dumbbell_Bench_Press', 'Bench Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders", "triceps"]', '["Her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde düz bir bench''e uzanın. Avuç içleriniz birbirine bakacaktır.", "Ardından dambılları yukarı kaldırmak için uyluklarınızdan destek alarak, dambılları tek tek kaldırın ve omuz genişliğinde önünüzde tutun.", "Omuz genişliğine geldiğinizde, avuç içleriniz sizden uzağa bakacak şekilde bileklerinizi öne doğru çevirin. Dambıllar göğsünüzün hemen yanlarında olmalı, üst kolunuz ve ön kolunuz 90 derecelik açı oluşturmalıdır. Dambıllar üzerinde her zaman tam kontrolü koruduğunuzdan emin olun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Ardından nefes verirken göğsünüzü kullanarak dambılları yukarı itin. Hareketin üst noktasında kollarınızı kilitleyin ve göğsünüzü sıkın, bir saniye bekleyin ve ardından yavaşça inmeye başlayın. İpucu: İdeal olarak ağırlığı indirmek, kaldırmaktan yaklaşık iki kat daha uzun sürmelidir.", "Hareketi antrenman programınızdaki belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Bench_Press/0.jpg", "Dumbbell_Bench_Press/1.jpg"]', 360.0, 'Dumbbell Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7ca9d82b-819d-5446-9b1a-4534ba5f84a8', 'free-exercise-db', 'Dumbbell_Bench_Press_with_Neutral_Grip', 'Bench Press (Dambıl, Nötr Tutuş)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders", "triceps"]', '["Her elinize bir dambıl alın ve düz sehpaya sırtüstü uzanın. Ayaklarınız yerde düz olmalı ve kürek kemikleriniz geriye çekilmiş olmalıdır.", "Nötr tutuşu koruyarak, avuç içleri birbirine bakacak şekilde, kollarınız yere dik olarak tam tepenizde uzatılmış halde başlayın. Bu sizin başlangıç pozisyonunuzdur.", "Dirseği bükerek ve üst kolları yanlara doğru indirerek harekete başlayın. Dambıllar gövdenize gelene kadar inin.", "Durun, ardından dirseği açın ve başlangıç pozisyonuna dönün."]', 'strength', '["Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg", "Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg"]', 360.0, 'Dumbbell Bench Press with Neutral Grip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6a14bc1d-36c5-5df8-9bb9-5bc55947654f', 'free-exercise-db', 'Dumbbell_Bicep_Curl', 'Biceps Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Her elinizde bir dambıl olacak şekilde kollarınız aşağı uzanmış halde dik durun. Dirseklerinizi gövdenize yakın tutun ve avuç içleriniz öne bakana kadar döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi üst kollarınızı sabit tutarak nefes verin ve biceps''inizi kasarak ağırlıkları kaldırın. Biceps''iniz tamamen kasılana ve dambıllar omuz seviyesine gelene kadar kaldırmaya devam edin. Biceps''inizi sıkarken kasılmış pozisyonda kısa bir süre bekleyin.", "Ardından nefes alın ve dambılları yavaşça başlangıç pozisyonuna indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Bicep_Curl/0.jpg", "Dumbbell_Bicep_Curl/1.jpg"]', 360.0, 'Dumbbell Bicep Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2a64aa5f-e35c-523a-a357-0a85d73a2270', 'free-exercise-db', 'Dumbbell_Clean', 'Clean (Dambıl)', 'pull', 'intermediate', 'compound', '["dumbbell"]', '["hamstrings"]', '["calves", "forearms", "glutes", "lower back", "quadriceps", "shoulders", "traps"]', '["Her elinizde birer dambıl, ayaklarınız omuz genişliğinde olacak şekilde ayakta durarak başlayın.", "Kalçanızdan ve dizlerinizden bükülerek, dambıllar yere değene kadar kalçanızı geriye iterek ağırlıkları yere indirin. Bu sizin başlangıç pozisyonunuzdur.", "Hareketi başlatmak için kalçanızı, dizlerinizi ve ayak bileklerinizi açarak ağırlıkları yukarı hızlandırmak amacıyla sert bir şekilde yukarı sıçrayın. Dambıllarda nötr bir tutuşu koruyarak tam açılma sağlanana kadar kollarınızı düz tutun.", "Tam açılmadan sonra, ağırlığı çömelme pozisyonunda karşılamak için kalçanızı ve dizlerinizi tekrar bükün. Kollarınızın bükülmesine izin vererek dambılları omuzlarınıza yönlendirin.", "Ağırlığı çömelme pozisyonunda karşıladıktan sonra, ağırlıklar omuzlarınızda olacak şekilde ayakta durma pozisyonunda bitirmek için kalçanızı ve dizlerinizi açın."]', 'strength', '["Dumbbell_Clean/0.jpg", "Dumbbell_Clean/1.jpg"]', 360.0, 'Dumbbell Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('36e2cd46-b83f-5094-8e51-a3ddbc9a38ec', 'free-exercise-db', 'Dumbbell_Floor_Press', 'Floor Press (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["triceps"]', '["chest", "shoulders"]', '["Ellerinizde dambıllarla yere uzanın. Dizleriniz bükülü olabilir. Ağırlıklar üstünüzde tamamen uzanmış şekilde başlayın.", "Üst kolunuz yere temas edene kadar ağırlıkları indirin. Triceps''in büyüklüğünü ve gücünü vurgulamak için dirseklerinizi içeride tutabilir veya göğüse odaklanmak için kollarınızı yana doğru açabilirsiniz.", "Altta duraklayın, ardından dirseklerinizi açarak ağırlıkları üstte birleştirin."]', 'powerlifting', '["Dumbbell_Floor_Press/0.jpg", "Dumbbell_Floor_Press/1.jpg"]', 360.0, 'Dumbbell Floor Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9ba927e6-fa4d-547c-b2e7-a5ac54edc582', 'free-exercise-db', 'Dumbbell_Flyes', 'Fly (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["chest"]', '[]', '["Her elinizde bir dambıl uyluklarınızın üzerinde dururken düz sehpaya uzanın. Avuç içleriniz birbirine bakacaktır.", "Ardından dambılları kaldırmak için uyluklarınızdan destek alarak dambılları tek tek kaldırın ve avuç içleriniz birbirine bakacak şekilde omuz genişliğinde önünüzde tutun. Dambılları press yapar gibi yukarı kaldırın, ancak kilitlenmeden hemen önce durun ve tutun. Bu sizin başlangıç pozisyonunuzdur.", "Biceps tendonundaki yüklenmeyi önlemek için dirseklerinizi hafifçe bükülü tutarak, göğsünüzde bir esneme hissedene kadar kollarınızı iki yana geniş bir yay çizerek indirin. Hareketin bu kısmında nefes alın. İpucu: Hareket boyunca kolların sabit kalması gerektiğini, hareketin yalnızca omuz ekleminde gerçekleşmesi gerektiğini unutmayın.", "Göğüs kaslarınızı sıkarak ve nefes vererek kollarınızı başlangıç pozisyonuna geri getirin. İpucu: Ağırlıkları indirirken kullandığınız hareket yayının aynısını kullandığınızdan emin olun.", "Kasılmış pozisyonda bir saniye bekleyin ve hareketi belirtilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Flyes/0.jpg", "Dumbbell_Flyes/1.jpg"]', 360.0, 'Dumbbell Flyes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('14f6d7c0-69c4-550c-885c-1a559cebc1de', 'free-exercise-db', 'Dumbbell_Incline_Row', 'Incline Row (Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["middle back"]', '["biceps", "forearms", "lats", "shoulders"]', '["Nötr tutuşla, eğimli bir bankın üzerine yaslanın.", "Her elinize nötr tutuşla bir dambıl alın ve kollarınız düz şekilde başlayın. Bu sizin başlangıç pozisyonunuzdur.", "Kürek kemiklerinizi geriye çekin ve dirseklerinizi bükerek dambılları yanınıza doğru çekin.", "Hareketin en üst noktasında bekleyin, ardından başlangıç pozisyonuna dönün."]', 'strength', '["Dumbbell_Incline_Row/0.jpg", "Dumbbell_Incline_Row/1.jpg"]', 360.0, 'Dumbbell Incline Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3ae05017-be25-56ee-a4de-d0e8a830f27c', 'free-exercise-db', 'Dumbbell_Incline_Shoulder_Raise', 'Incline Omuz Kaldırma (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde bir incline bench üzerine oturun.", "Ağırlıkları omuzlarınıza fırlatmak için bacaklarınızı yukarı kaldırın ve geriye yaslanın. Dambılları kollarınız uzanmış şekilde omuzlarınızın üzerine konumlandırın. Kollar yere dik, avuç içleri ileri bakacak ve parmak eklemleri tavana dönük olmalıdır. Bu sizin başlangıç pozisyonunuz olacak.", "Kollarınızı düz ve kilitli tutarak, nefes verirken omuzlarınızı bench''ten kaldırarak dambılları yukarı kaldırın.", "Nefes alırken dambılları başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Incline_Shoulder_Raise/0.jpg", "Dumbbell_Incline_Shoulder_Raise/1.jpg"]', 360.0, 'Dumbbell Incline Shoulder Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a217c998-42f7-5434-8a38-396a23177569', 'free-exercise-db', 'Dumbbell_Lunges', 'Lunge (Hamle, Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Gövdeniz dik şekilde, iki dambılı elleriniz yanlarda olacak şekilde tutarak ayakta durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sağ bacağınızla, geride sabit kalan ayaktan yaklaşık 60 cm kadar öne adım atın ve gövdenizi dik tutarak ve dengenizi koruyarak üst vücudunuzu aşağı indirin. İnerken nefes alın. Not: Diğer egzersizlerde olduğu gibi, inerken dizinizin ayak parmaklarınızın ilerisine geçmesine izin vermeyin; bu diz eklemine gereksiz stres bindirir. Ön kaval kemiğinizi yere dik tutmaya özen gösterin.", "Esas olarak ayağınızın topuğunu kullanarak yukarı itin ve nefes verirken başlangıç pozisyonuna dönün.", "Hareketi önerilen tekrar sayısı kadar tekrarlayın, ardından sol bacakla yapın."]', 'strength', '["Dumbbell_Lunges/0.jpg", "Dumbbell_Lunges/1.jpg"]', 360.0, 'Dumbbell Lunges', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8bde966f-d675-522f-a8cf-f3a3e96e68e7', 'free-exercise-db', 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', 'Yüzüstü Tek Kol Arka Omuz Raise (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["shoulders"]', '["middle back"]', '["Bir elinizde dambıl tutarken, hafifçe eğimli (yerden ölçüldüğünde yaklaşık 15 derece) ayarlanabilir bir bench''in üzerine göğsünüz aşağı bakacak şekilde uzanın. Diğer elinizi denge için bench''in ayağından tutmak için kullanabilirsiniz.", "Dambılı tutan elinizin avuç içini nötr pozisyonda (avuç içi gövdenize bakacak şekilde) konumlandırın ve kolunuzu dirseği hafifçe bükülü şekilde uzatılmış halde tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes verirken, dirseğiniz omuz hizasına gelene ve kolunuz yere yaklaşık paralel olana kadar dambıllı kolu yana doğru kaldırın. İpucu: Hareket boyunca kolunuzu gövdenize dik ve uzamış halde tutun. Ayrıca üst noktadaki kasılmayı bir saniye koruyun.", "Nefes alırken dambılı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg", "Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg"]', 360.0, 'Dumbbell Lying One-Arm Rear Lateral Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0a3ae735-a283-53fa-a318-1e97516722be', 'free-exercise-db', 'Dumbbell_Lying_Pronation', 'Yüzüstü Pronation (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["Düz bir bankta yüzüstü uzanın; bir kolunuzla dambılı tutun, diğer elinizi bankın üzerinde başınızı yaslayabilecek şekilde katlayın.", "Dambılı tutan kolun dirseğini, üst kol ile ön kol arasında 90 derecelik bir açı oluşacak şekilde bükün.", "Şimdi üst kolu, ön kol yere dik ve üst kol gövdenize dik olacak şekilde kaldırın. İpucu: Üst kol yere paralel olmalı ve gövdenizle de 90 derecelik açı oluşturmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken, üst kol ile ön kol arasındaki 90 derecelik bükülmeyi koruyarak ön kolunuzu dışa doğru döndürün ve dambılı öne kaldırın. Bu dışa dönme hareketine ön kol yere paralel olana kadar devam edin. Bu noktada kasılmayı bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Lying_Pronation/0.jpg", "Dumbbell_Lying_Pronation/1.jpg"]', 360.0, 'Dumbbell Lying Pronation', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e778ed86-5f6b-5a3d-a1c9-5b3386157123', 'free-exercise-db', 'Dumbbell_Lying_Rear_Lateral_Raise', 'Yüzüstü Arka Omuz Raise (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Her elinizde bir dambıl tutarken, hafif eğimli (yerden ölçüldüğünde yaklaşık 15 derece) ayarlanabilir bir sehpaya göğsünüz aşağıda olacak şekilde uzanın.", "Kollarınız uzanmış ve dirsekler hafif bükülü haldeyken avuç içlerinizi nötr konumda (avuç içleri gövdenize bakacak şekilde) tutun. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes verirken dirsekleriniz omuz hizasına gelene ve kollarınız yere kabaca paralel olana kadar kollarınızı yanlara kaldırın. İpucu: Hareket boyunca kollarınızı gövdeye dik ve uzanmış halde tutun. Ayrıca en üstteki kasılmayı bir saniye koruyun.", "Nefes alarak dambılları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin."]', 'strength', '["Dumbbell_Lying_Rear_Lateral_Raise/0.jpg", "Dumbbell_Lying_Rear_Lateral_Raise/1.jpg"]', 360.0, 'Dumbbell Lying Rear Lateral Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9e3c633e-7c9e-584d-a708-e7b33b59d87b', 'free-exercise-db', 'Dumbbell_Lying_Supination', 'Yatarak Supinasyon (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["Bir kolunuzda dambıl tutarak düz bir bench üzerinde yan yatın; diğer elinizi bench üzerinde başınızı yaslayabileceğiniz şekilde katlayın.", "Dambılı tutan kolunuzun dirseğini, üst kol ile ön kol arasında 90 derecelik bir açı oluşacak şekilde bükün.", "Şimdi üst kolunuzu, ön kol yere paralel ve gövdenize dik olacak şekilde kaldırın (İpucu: Böylece ön kol doğrudan önünüzde olacaktır). Üst kol gövdenizin yanında sabit olmalı ve yere paralel (her zaman gövdenizle aynı hizada) olmalıdır. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken, üst kol ile ön kol arasındaki 90 derecelik bükülmeyi koruyarak dambılın yarım daire hareketiyle yukarı kalkması için ön kolunuzu dışa doğru döndürün. Ön kol yere dik ve gövdenin tavana baktığı noktaya kadar bu dış rotasyona devam edeceksiniz. Bu noktada kasılmayı bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın ve ardından diğer kola geçin."]', 'strength', '["Dumbbell_Lying_Supination/0.jpg", "Dumbbell_Lying_Supination/1.jpg"]', 360.0, 'Dumbbell Lying Supination', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1d1349c6-00ea-5990-a8b0-2aedb8269497', 'free-exercise-db', 'Dumbbell_One-Arm_Shoulder_Press', 'Tek Kol Shoulder Press (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Bir dambıl alın ve dambılları uyluklarınızın üzerinde dik olarak yerleştirirken ya askeri press bench''ine ya da sırt desteği olan bir utility bench''e oturun ya da dik ayakta durun.", "Dambılı omuz yüksekliğine getirmek için clean yapın. Diğer el, yanda tamamen uzatılmış, belin yanında tutulabilir veya sabit bir yüzeyi kavrayabilir.", "Avuç içiniz öne bakacak şekilde bileğinizi döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken dambılı kolunuz tamamen uzayana kadar yukarı itin.", "Bir saniye bekledikten sonra nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın, ardından kolunuzu değiştirin."]', 'strength', '["Dumbbell_One-Arm_Shoulder_Press/0.jpg", "Dumbbell_One-Arm_Shoulder_Press/1.jpg"]', 360.0, 'Dumbbell One-Arm Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('751a67e8-63ca-599a-8463-2649d92cf7a9', 'free-exercise-db', 'Dumbbell_One-Arm_Triceps_Extension', 'Triceps Extension (Dambıl, Tek Kol)', 'push', 'intermediate', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Bir dambıl alın ve ya askeri press sehpasına ya da sırt desteği olan bir utility sehpaya oturup dambılı dik şekilde uyluklarınızın üzerine koyun ya da dik ayakta durun.", "Dambılı omuz hizasına getirmek için yukarı çekin (clean), ardından kolu başınızın üzerine uzatın; böylece tüm kol yere dik ve başınızın yanında olur. Dambıl tepenizde olmalıdır. Diğer el, dambıllı üst kolu desteklemek için bel hizasında yana tam uzatılmış halde tutulabilir veya sabit bir yüzeye tutunabilir.", "Bileği, avuç içiniz öne ve serçe parmağınız tavana bakacak şekilde döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolu sabit tutarken dambılı yavaşça başınızın arkasına indirin. Bu hareketi yaparken nefes alın ve triceps''iniz tam gerildiğinde durun.", "Nefes verirken triceps''inizi kasarak başlangıç pozisyonuna dönün. İpucu: Yalnızca ön kolun hareket etmesi zorunludur. Üst kol her zaman başınızın yanında sabit kalmalıdır.", "Önerilen tekrar sayısı kadar tekrarlayın ve kolları değiştirin."]', 'strength', '["Dumbbell_One-Arm_Triceps_Extension/0.jpg", "Dumbbell_One-Arm_Triceps_Extension/1.jpg"]', 360.0, 'Dumbbell One-Arm Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bae324bb-ee7d-5b69-93b5-6832b5339796', 'free-exercise-db', 'Dumbbell_One-Arm_Upright_Row', 'Tek Kol Upright Row (Dambıl)', 'pull', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["biceps", "traps"]', '["Bir dambıl alın ve kolunuz hafifçe bükülü dirsekle önünüzde uzanmış, sırtınız düz halde dik durun. Bu sizin başlangıç pozisyonunuz olacaktır. İpucu: Dambıl uyluğunuzun üzerinde durmalı ve avuç içiniz uyluklarınıza bakmalıdır.", "Diğer elinizi tamamen yanda uzatılmış halde belinizin yanında tutabilir veya sabit bir yüzeyden tutabilirsiniz. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken yan omuz kaslarınızı kullanarak dambılı kaldırın. Dambıl yukarı hareket ederken vücuda yakın olmalıdır. Dambıl çenenizle neredeyse aynı hizaya gelene kadar kaldırmaya devam edin. İpucu: Hareketi dirsekleriniz yönlendirmelidir. Dambılı kaldırırken dirseğiniz her zaman ön kolunuzdan daha yüksekte olmalıdır. Ayrıca gövdenizi sabit tutun ve hareketin üst noktasında bir saniye duraklayın.", "Dambılı yavaşça başlangıç pozisyonuna indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın ve kolları değiştirin."]', 'strength', '["Dumbbell_One-Arm_Upright_Row/0.jpg", "Dumbbell_One-Arm_Upright_Row/1.jpg"]', 360.0, 'Dumbbell One-Arm Upright Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('142ca0e9-2475-59c9-8b0e-4f9ce29474ee', 'free-exercise-db', 'Dumbbell_Prone_Incline_Curl', 'Yüzüstü Incline Curl (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her elinize bir dambıl alın ve omuzlarınız eğimin üst kısmına yakın olacak şekilde eğimli bir sehpaya yüzüstü uzanın. Dizleriniz oturağın üzerinde durabilir ya da bacaklarınızı yanlara açabilirsiniz (benim tercih ettiğim yöntem).", "Kollarınızı uzatın ve yere dik olacak şekilde doğal bir şekilde önünüzde sarkmasına izin verin.", "Şimdi dirseklerinizi yanınızda tutun ve avuç içlerini öne çevirin. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınız tamamen bükülene kadar biceps''inizi kasarak dambılları kaldırın. Hareketin bu kısmında nefes verin ve yalnızca ön kolların hareket ettiğinden emin olun. Üst kollar her zaman sabit kalmalıdır.", "Kollarınız tamamen uzayana kadar dambılları indirin.", "Önerilen sayıda tekrarlayın."]', 'strength', '["Dumbbell_Prone_Incline_Curl/0.jpg", "Dumbbell_Prone_Incline_Curl/1.jpg"]', 360.0, 'Dumbbell Prone Incline Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('058e2de1-88f6-5445-8352-6a4e21b4bdea', 'free-exercise-db', 'Dumbbell_Raise', 'Lateral Raise (Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["shoulders"]', '["biceps"]', '["Her elinize bir dambıl alın ve kollarınız yanlarınızda uzanmış, dirsekler hafif bükülü ve sırtınız dik şekilde ayakta durun. Bu sizin başlangıç pozisyonunuzdur. İpucu: Dambıllar uyluklarınızın yanında, avuç içleriniz arkaya bakacak şekilde olmalıdır.", "Nefes verirken dambılları kaldırmak için yan omuz kaslarınızı kullanın. Dambıllar yukarı kalkarken vücudun yanında olmalıdır. Dambıllar neredeyse çenenizle aynı hizaya gelene kadar kaldırmaya devam edin. İpucu: Hareketi dirsekleriniz yönlendirmelidir. Dambılı kaldırırken dirseğiniz her zaman ön kolunuzdan daha yukarıda olmalıdır. Ayrıca gövdenizi sabit tutun ve hareketin en üstünde bir saniye bekleyin.", "Dambılları yavaşça başlangıç pozisyonuna indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Raise/0.jpg", "Dumbbell_Raise/1.jpg"]', 360.0, 'Dumbbell Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0eae578e-5918-5deb-8c2e-86e9e69d4c18', 'free-exercise-db', 'Dumbbell_Rear_Lunge', 'Geri Lunge (Hamle, Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Gövdeniz dik şekilde, iki dambılı elleriniz yanlarda olacak şekilde tutarak ayakta durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sağ bacağınızla, sol ayaktan yaklaşık 60 cm kadar geriye adım atın ve gövdenizi dik tutarak ve dengenizi koruyarak üst vücudunuzu aşağı indirin. İnerken nefes alın. İpucu: Diğer egzersizlerde olduğu gibi, inerken dizinizin ayak parmaklarınızın ilerisine geçmesine izin vermeyin; bu diz eklemine gereksiz stres bindirir. Ön kaval kemiğinizi yere dik tutmaya özen gösterin. Lunge sırasında gövdeyi dik tutun; esnek kalça fleksörleri önemlidir. Uzun bir lunge gluteus maximus''u, kısa bir lunge ise quadriceps''i daha çok çalıştırır.", "Yukarı itin ve nefes verirken başlangıç pozisyonuna dönün. İpucu: Quadriceps''i vurgulamak için ayağınızın ön kısmıyla itin. Kalça kaslarına odaklanmak için topuklarınızla bastırın.", "Şimdi aynı hareketi karşı bacakla tekrarlayın."]', 'strength', '["Dumbbell_Rear_Lunge/0.jpg", "Dumbbell_Rear_Lunge/1.jpg"]', 360.0, 'Dumbbell Rear Lunge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('dd1f3cee-80bc-5ac1-abec-b954331c668b', 'free-exercise-db', 'Dumbbell_Scaption', 'Scaption (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '["traps"]', '["Bu düzeltici egzersiz, kürek kemiğinizi stabilize eden kasları güçlendirir. Her elinizde hafif bir ağırlık tutun ve yanlarınızda sarkıtın. Başparmaklarınız yukarı bakmalı.", "Kollarınızı önünüze, merkezden yaklaşık 30 derece açıyla kaldırarak harekete başlayın. Hareketi yaparken kollarınız tamamen uzanmış olmalı.", "Kollarınız yere paralel olana kadar devam edin ve ardından başlangıç pozisyonuna dönün."]', 'strength', '["Dumbbell_Scaption/0.jpg", "Dumbbell_Scaption/1.jpg"]', 360.0, 'Dumbbell Scaption', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a073e2cb-eb99-59d4-8338-7c652868b654', 'free-exercise-db', 'Dumbbell_Seated_Box_Jump', 'Oturarak Box Jump (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bir kutuyu sehpanın yanına yaklaşık birkaç ayak mesafeye yerleştirin. Dambılı iki elinizle göğsünüze tutun ve kutuya bakacak şekilde sehpaya oturun. Bu sizin başlangıç pozisyonunuzdur.", "Öne eğilirken ayaklarınızı sıkıca yere basın, kalçanızı ve dizlerinizi açarak yukarı ve öne doğru zıplayın.", "Kutuya iki ayağınızla inin; kalçanızın ve dizlerinizin bükülmesine izin vererek darbeyi sönümleyin.", "Aşağı adım atın ve başlangıç pozisyonuna dönün."]', 'plyometrics', '["Dumbbell_Seated_Box_Jump/0.jpg", "Dumbbell_Seated_Box_Jump/1.jpg"]', 480.0, 'Dumbbell Seated Box Jump', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fefc7f03-243e-555f-a415-12c4a7a07b70', 'free-exercise-db', 'Dumbbell_Seated_One-Leg_Calf_Raise', 'Calf Raise (Dambıl, Oturarak Tek Bacak)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["calves"]', '[]', '["Yere, düz bir sehpadan yaklaşık 12 inç (30 cm) uzağa bir blok yerleştirin.", "Düz sehpaya oturun ve sol üst uyluğunuza, dizinizin yaklaşık 3 inç (7-8 cm) üstüne bir dambıl koyun.", "Şimdi sol ayağınızın ön tabanını bloğa yerleştirin. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken ve baldır kasınızı kasarken parmak uçlarınızı olabildiğince yukarı kaldırın. Kasılmayı bir saniye tutun.", "Yavaşça başlangıç pozisyonuna dönün ve olabildiğince aşağı esneyin.", "Belirtilen tekrar sayısı kadar tekrarlayın, ardından sağ bacakla tekrarlayın."]', 'strength', '["Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg", "Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg"]', 360.0, 'Dumbbell Seated One-Leg Calf Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8d4dbc0c-51a0-5664-9cf6-f5f5a0e571f7', 'free-exercise-db', 'Dumbbell_Shoulder_Press', 'Omuz Press (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Her elinizde bir dambıl tutarken, sırt desteği olan bir military press bench''ine veya çok amaçlı bir bench''e oturun. Dambılları dik şekilde uyluklarınızın üzerine yerleştirin.", "Şimdi dambılları, yukarı doğru itmek için uyluklarınızdan destek alarak tek tek omuz hizasına kaldırın.", "Avuç içleriniz öne bakacak şekilde bileklerinizi çevirdiğinizden emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes verin ve dambılları üstte birbirine değene kadar yukarı itin.", "Ardından üstteki kasılmış pozisyonda kısa bir duraklamanın ardından nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Shoulder_Press/0.jpg", "Dumbbell_Shoulder_Press/1.jpg"]', 360.0, 'Dumbbell Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('44dfffc0-31f7-5e77-8f57-92dbb9b7fe5a', 'free-exercise-db', 'Dumbbell_Shrug', 'Shrug (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["traps"]', '[]', '["Her elinizde bir dambıl (avuç içleri gövdenize bakacak şekilde) ve kollarınız yanlarda uzanmış halde dik durun.", "Nefes verirken omuzlarınızı olabildiğince yukarı kaldırarak dambılları yükseltin. Üstte kasılmayı bir saniye tutun. İpucu: Kollar her zaman uzatılmış halde kalmalıdır. Dambılları kaldırmaya yardımcı olması için biceps''i kullanmaktan kaçının. Yalnızca omuzlar yukarı ve aşağı hareket etmelidir.", "Dambılları başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Shrug/0.jpg", "Dumbbell_Shrug/1.jpg"]', 360.0, 'Dumbbell Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8c5df98e-9468-596e-af4a-7b85f5db2e76', 'free-exercise-db', 'Dumbbell_Side_Bend', 'Yan Eğilme (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["abdominals"]', '[]', '["Sol elinizde bir dambıl (avuç içi gövdeye dönük) tutarak ve sağ elinizi belinize koyarak dik durun. Ayaklarınız omuz genişliğinde olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Sırtınızı düz ve başınızı yukarıda tutarak, sadece belinizden olabildiğince sağa doğru eğilin. Yana eğilirken nefes alın. Ardından bir saniye bekleyin ve nefes vererek başlangıç pozisyonuna dönün. İpucu: Vücudun geri kalanını sabit tutun.", "Şimdi hareketi bu sefer sola doğru eğilerek tekrarlayın. Bir saniye bekleyin ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın ve ardından el değiştirin."]', 'strength', '["Dumbbell_Side_Bend/0.jpg", "Dumbbell_Side_Bend/1.jpg"]', 360.0, 'Dumbbell Side Bend', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('388e498f-1a26-5e0d-bd94-ed0cb25d5c56', 'free-exercise-db', 'Dumbbell_Squat', 'Squat (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Her elinizde birer dambıl tutarak dik durun (avuç içleri bacaklarınızın yanına bakacak şekilde).", "Bacaklarınızı omuz genişliğinde orta bir duruşla konumlandırın, ayak parmakları hafifçe dışa baksın. Aşağı bakmak dengenizi bozacağı için başınızı her zaman yukarıda tutun ve sırtınızı da düz tutun. Bu sizin başlangıç pozisyonunuzdur. Not: Bu anlatım için genel gelişimi hedefleyen yukarıda tarif edilen orta duruşu kullanacağız; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.", "Başınız yukarıda ve duruşunuz dik iken dizlerinizi bükerek gövdenizi yavaşça indirmeye başlayın. Uyluklarınız yere paralel olana kadar inmeye devam edin. İpucu: Egzersizi doğru yaptıysanız dizlerinizin ön kısmı, ayak parmaklarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizgiyi geçerse (ayak parmaklarınızı geçerse) dize gereksiz yük bindiriyorsunuz ve egzersizi yanlış yapıyorsunuz demektir.", "Ağırlıklı olarak topuğunuzla yeri iterek bacaklarınızı tekrar düzleştirirken nefes verip gövdenizi yukarı kaldırmaya başlayın ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Squat/0.jpg", "Dumbbell_Squat/1.jpg"]', 360.0, 'Dumbbell Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('beba23e7-1d52-5f3a-9814-ad76bed3a8b4', 'free-exercise-db', 'Dumbbell_Squat_To_A_Bench', 'Bench Squat (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Arkanızda düz bir bench varken, her elinizde bir dambıl tutarak (avuç içleri bacaklarınızın yanına bakacak şekilde) dik durun.", "Bacaklarınızı omuz genişliğinde, parmak uçları hafifçe dışa dönük orta bir duruşla konumlandırın. Aşağı bakmak dengenizi bozacağından başınızı her zaman yukarıda tutun ve ayrıca sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuz olacaktır. Not: Bu anlatım için genel gelişimi hedefleyen yukarıda tarif edilen orta duruşu kullanacağız; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.", "Başınız yukarıda ve duruşunuz dik kalacak şekilde dizlerinizi bükerek gövdenizi yavaşça indirmeye başlayın. Arkanızdaki bench''e hafifçe değene kadar inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız, dizlerinizin ön kısmı ayak parmaklarınızla öne doğru dik bir hayali düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizgiyi geçerse (ayak parmaklarınızı geçerse), dizinize gereksiz stres bindirirsiniz ve egzersiz yanlış yapılmış demektir.", "Esas olarak ayağınızın topuğu ile yere basarak bacaklarınızı tekrar düzeltirken ve başlangıç pozisyonuna dönerken nefes vererek kalkmaya başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Dumbbell_Squat_To_A_Bench/0.jpg", "Dumbbell_Squat_To_A_Bench/1.jpg"]', 360.0, 'Dumbbell Squat To A Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1b91bb68-2a86-52a3-8e34-792527772283', 'free-exercise-db', 'Dumbbell_Step_Ups', 'Step-Up (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Her elinizde bir dambıl (avuç içleri bacaklarınızın yanına bakacak şekilde) olacak şekilde dik durun.", "Sağ ayağınızı yükseltilmiş platforma koyun. Sağ bacağınızın kalça ve dizini açarak platforma çıkın. Vücudunuzun geri kalanını yukarı kaldırmak için ağırlıklı olarak topuğunuzu kullanın ve sol ayağınızı da platforma koyun. Yukarı çıkmak için gereken kuvveti uygularken nefes verin.", "Nefes alırken sağ bacağınızın kalça ve dizini bükerek sol bacakla aşağı inin. Sağ ayağınızı ilk pozisyondaki sol ayağınızın yanına koyarak başlangıçtaki ayakta duruş pozisyonuna dönün.", "Önerilen tekrar sayısı kadar sağ bacakla tekrarlayın, ardından sol bacakla yapın."]', 'strength', '["Dumbbell_Step_Ups/0.jpg", "Dumbbell_Step_Ups/1.jpg"]', 360.0, 'Dumbbell Step Ups', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7c319a25-2242-5104-bd62-57fc2b9315ac', 'free-exercise-db', 'Dumbbell_Tricep_Extension_-Pronated_Grip', 'Triceps Extension (Dambıl, Pronasyon Tutuş)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Düz sehpaya uzanın ve iki dambılı tam omuzlarınızın üzerinde tutun. Kollarınız tamamen uzamış olmalı ve gövdeniz ile yer arasında 90 derecelik açı oluşturmalıdır.", "Avuç içleriniz öne bakmalı ve dirsekleriniz içeride olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes alın ve dambılları kulaklarınıza yaklaşana kadar yavaşça indirin. Üst kollarınızı sabit ve dirseklerinizi içeride tuttuğunuzdan emin olun.", "Ardından nefes verin ve ağırlığı başlangıç pozisyonuna döndürmek için triceps''inizi kullanın."]', 'strength', '["Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg", "Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg"]', 360.0, 'Dumbbell Tricep Extension -Pronated Grip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e1932225-64d9-5e55-9bf8-5b895295c878', 'free-exercise-db', 'Dynamic_Back_Stretch', 'Dinamik Sırt Esnetme', 'pull', 'beginner', NULL, '[]', '["lats"]', '[]', '["Ayaklarınız omuz genişliğinde açık şekilde durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kollarınızı düz tutarak, kollarınız başınızın üzerine gelene kadar her seferinde hareket açıklığını artırarak 5-10 kez önünüzde yukarı doğru sallayın."]', 'stretching', '["Dynamic_Back_Stretch/0.jpg", "Dynamic_Back_Stretch/1.jpg"]', 150.0, 'Dynamic Back Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6f576d19-0a6f-5a9c-b560-cbdce8a55168', 'free-exercise-db', 'Dynamic_Chest_Stretch', 'Dinamik Göğüs Esnetme', 'pull', 'beginner', NULL, '[]', '["chest"]', '["middle back"]', '["Elleriniz birleşik ve kollarınız doğrudan önünüze uzanmış şekilde durun. Bu sizin başlangıç pozisyonunuz olacak.", "Kollarınızı düz tutarak, abartılı bir alkış hareketine benzer şekilde kollarınızı hızla olabildiğince geriye ve tekrar öne getirin. Hızınızı artırarak 5-10 kez tekrarlayın."]', 'stretching', '["Dynamic_Chest_Stretch/0.jpg", "Dynamic_Chest_Stretch/1.jpg"]', 150.0, 'Dynamic Chest Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2809b452-0933-5a05-a05c-9e652361c611', 'free-exercise-db', 'EZ-Bar_Curl', 'Biceps Curl (EZ Bar)', 'pull', 'beginner', 'isolation', '["e-z curl bar"]', '["biceps"]', '[]', '["EZ curl barı geniş dış tutacaklardan tutarak dik durun. Barın şekli nedeniyle avuç içleriniz öne bakmalı ve hafifçe içe doğru eğimli olmalıdır. Dirseklerinizi gövdenize yakın tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi üst kollarınızı sabit tutarak nefes verin ve biceps''inizi kasarak ağırlığı öne doğru curl yapın. Yalnızca ön kollarınızı hareket ettirmeye odaklanın.", "Biceps''iniz tamamen kasılana ve bar omuz hizasına gelene kadar ağırlığı kaldırmaya devam edin. Üstteki kasılmış pozisyonu bir an tutun ve biceps''i sıkın.", "Ardından nefes alın ve barı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["EZ-Bar_Curl/0.jpg", "EZ-Bar_Curl/1.jpg"]', 360.0, 'EZ-Bar Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('37982930-ce10-5a65-8d7c-e7a0991d64fb', 'free-exercise-db', 'EZ-Bar_Skullcrusher', 'Skull Crusher (EZ Bar)', 'push', 'beginner', 'isolation', '["e-z curl bar"]', '["triceps"]', '["forearms"]', '["Dar bir tutuşla EZ barı kaldırın ve sehpaya uzanırken dirsekleriniz içeride olacak şekilde tutun. Kollarınız yere dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı sabit tutarak dirseklerinizin bükülmesine izin vererek barı indirin. Hareketin bu kısmında nefes alın. Bar tam alnınızın üzerine geldiğinde durun.", "Dirseği açarak ve nefes vererek barı başlangıç pozisyonuna geri kaldırın.", "Tekrarlayın."]', 'strength', '["EZ-Bar_Skullcrusher/0.jpg", "EZ-Bar_Skullcrusher/1.jpg"]', 360.0, 'EZ-Bar Skullcrusher', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('51d6305b-1ca6-543b-9f52-57cbdb55eafd', 'free-exercise-db', 'Elbow_Circles', 'Dirsek Çevirme', 'pull', 'beginner', 'isolation', '[]', '["shoulders"]', '["traps"]', '["Ayaklarınız hafifçe açık şekilde oturun veya ayakta durun.", "Ellerinizi omuzlarınıza koyun; dirsekleriniz omuz seviyesinde ve dışa bakıyor olmalı.", "Dirseklerinizle yavaşça bir daire çizin. Daireye başlarken nefes verin ve daireyi tamamlarken nefes alın."]', 'stretching', '["Elbow_Circles/0.jpg", "Elbow_Circles/1.jpg"]', 150.0, 'Elbow Circles', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('952bc535-9622-53b6-bd94-6f62fbe85aa9', 'free-exercise-db', 'Elbow_to_Knee', 'Dirsek-Diz Mekik', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Yere uzanın ve sağ bacağınızı bükülü sol dizinizin üzerinden çaprazlayın. Ellerinizi başınızın arkasında kenetleyin ve kürek kemikleriniz yerde olacak şekilde başlayın. Bu sizin başlangıç pozisyonunuzdur.", "Omurganızı bükerek ve gövdenizi döndürerek sol dirseğinizi sağ dizinize getirin.", "Başlangıç pozisyonuna dönün ve taraf değiştirmeden önce hareketi istenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Elbow_to_Knee/0.jpg", "Elbow_to_Knee/1.jpg"]', 360.0, 'Elbow to Knee', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7a06ae4a-004c-5370-a17f-7c0739d916a9', 'free-exercise-db', 'Elbows_Back', 'Dirsekleri Geriye Çekme', 'static', 'beginner', 'isolation', '[]', '["chest"]', '["shoulders"]', '["Dik durun.", "Her iki elinizi parmaklar aşağı bakacak ve dirsekler dışa dönük şekilde alt sırtınıza koyun.", "Ardından dirseklerinizi nazikçe geriye çekin ve birbirine değdirmeyi hedefleyin."]', 'stretching', '["Elbows_Back/0.jpg", "Elbows_Back/1.jpg"]', 150.0, 'Elbows Back', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0ce6b7fa-3e0e-51a1-ae5f-8aa239c5c422', 'free-exercise-db', 'Elevated_Back_Lunge', 'Yükseltilmiş Geri Lunge (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Bir barı uygun ağırlıkla yükleyip omuz yüksekliğinde bir rafa yerleştirin. Arkanıza kısa, yükseltilmiş bir platform koyun.", "Barı sırtınızın üst kısmına alın; sırtınızı kavisli ve sıkı tutun. İki ayağınızla yükseltilmiş platforma çıkın. Bu sizin başlangıç pozisyonunuzdur.", "Bir bacağınızla geriye adım atarak başlayın. Diziniz yere değene kadar kalçanızı ve dizlerinizi bükerek inin.", "Bekleyin ve kalçanızı ve dizlerinizi açarak yukarı kalkın; dönüşümlü yapmadan önce tamamen başlangıç pozisyonuna dönün."]', 'strength', '["Elevated_Back_Lunge/0.jpg", "Elevated_Back_Lunge/1.jpg"]', 360.0, 'Elevated Back Lunge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('24495ce8-89ee-530e-aff2-24ee87ac84fd', 'free-exercise-db', 'Elevated_Cable_Rows', 'Yükseltilmiş Platformda Kablo Row', 'pull', 'intermediate', 'compound', '["cable"]', '["lats"]', '["middle back", "traps"]', '["Yüksekliği yaklaşık 10-15 cm olan bir tür platform (aerobik veya calf raise platformu olabilir) edinin.", "Bunu kablo row makinesinin oturağına yerleştirin.", "Makineye oturun ve dizleriniz hafifçe bükülü, kilitli olmayacak şekilde ayaklarınızı ön platforma veya sağlanan çapraz bara koyun.", "Sırtınızın doğal hizasını koruyarak öne eğilin ve V-bar saplarını kavrayın.", "Kollarınız uzanmış şekilde, gövdeniz bacaklarınızla 90 derecelik bir açı yapana kadar geriye çekin. Sırtınız hafifçe kavisli ve göğsünüz dışarı çıkık olmalı. Barı önünüzde tutarken latissimus kaslarınızda güzel bir gerilme hissediyor olmalısınız. Bu egzersizin başlangıç pozisyonudur.", "Gövdenizi sabit tutarak, kollarınızı gövdenize yakın tutup karın kaslarınıza dokunana kadar sapları gövdenize doğru çekin. Bu hareketi yaparken nefes verin. Bu noktada sırt kaslarınızı sertçe sıkıyor olmalısınız. Bu kasılmayı bir saniye tutun ve nefes alırken yavaşça ilk pozisyona dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Elevated_Cable_Rows/0.jpg", "Elevated_Cable_Rows/1.jpg"]', 360.0, 'Elevated Cable Rows', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d6aa9c21-3a33-51f2-a193-15d6621df15c', 'free-exercise-db', 'Elliptical_Trainer', 'Eliptik Bisiklet', NULL, 'intermediate', NULL, '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için eliptik cihaza çıkın ve menüden istediğiniz seçeneği seçin. Çoğu eliptik cihazda manuel bir ayar vardır veya çalıştırmak için bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kalori miktarını tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz. Antrenmanın yoğunluğunu değiştirmek için eğim ayarlanabilir.", "Uygun yoğunlukta kalmanıza yardımcı olmak için kalp atış hızınızı takip etmek amacıyla tutamaçlar kullanılabilir."]', 'cardio', '["Elliptical_Trainer/0.jpg", "Elliptical_Trainer/1.jpg"]', 600.0, 'Elliptical Trainer', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8c3184ed-a6cc-56ba-9c42-eb3606ea6af3', 'free-exercise-db', 'Exercise_Ball_Crunch', 'Mekik (Pilates Topu)', 'pull', 'beginner', 'isolation', '["exercise ball"]', '["abdominals"]', '[]', '["Alt sırtınızın kavisi topun küresel yüzeyine bastırılmış şekilde egzersiz topunun üzerine uzanın. Dizleriniz bükülü ve ayaklarınız yere sıkıca basmalıdır. Üst gövde topun üst kısmından aşağı sarkmalıdır. Kollar ya vücudun yanında tutulmalı ya da göğsün üzerinde çapraz yapılmalıdır; çünkü bu pozisyonlar (ellerin başın arkasında olduğu pozisyonun aksine) boyun zorlanmalarını önler.", "Boynunuzu her zaman sabit tutarak gövdenizi bir esneme pozisyonuna indirin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kalçanız sabitken, karın kaslarınızı kasarak belinizi bükün ve karın kaslarınızda güzel bir kasılma hissedene kadar omuzlarınızı ve gövdenizi yukarı doğru kıvırın. Kollarınız yanlarda ise bacaklarınızın yanı boyunca kayarak yukarı çıkmalı, çapraz iseler göğsünüzün üzerinde kalmalıdır. Alt sırt her zaman topla temas halinde kalmalıdır. Bu hareketi yaparken nefes verin ve kasılmayı bir saniye tutun.", "Nefes alırken başlangıç pozisyonuna geri dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Exercise_Ball_Crunch/0.jpg", "Exercise_Ball_Crunch/1.jpg"]', 360.0, 'Exercise Ball Crunch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('08416ab2-f50b-5877-abd5-13c2a775fa7c', 'free-exercise-db', 'Exercise_Ball_Pull-In', 'Pull-In (Egzersiz Topu)', 'pull', 'beginner', 'compound', '["exercise ball"]', '["abdominals"]', '[]', '["Yakınınıza bir egzersiz topu yerleştirin ve ellerinizi omuz genişliğinde yere koyarak şınav pozisyonunda topun önünde yere uzanın.", "Şimdi alt kaval kemiklerinizi egzersiz topunun üzerine yerleştirin. İpucu: Bu noktada bacaklarınız tamamen uzatılmış ve kaval kemikleri topun üzerinde olmalı; üst vücut ise önünüzde uzatılmış iki kolunuzla desteklenen şınav benzeri bir pozisyonda olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sırtınızı tamamen düz ve üst vücudunuzu sabit tutarak, nefes verirken dizlerinizi göğsünüze doğru çekin ve topun ayak bileklerinizin altında öne doğru yuvarlanmasına izin verin. Karın kaslarınızı sıkın ve bu pozisyonda bir saniye bekleyin.", "Şimdi nefes alırken bacaklarınızı yavaşça düzeltin ve topu başlangıç pozisyonuna geri yuvarlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Exercise_Ball_Pull-In/0.jpg", "Exercise_Ball_Pull-In/1.jpg"]', 360.0, 'Exercise Ball Pull-In', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7d7c82cd-ee2b-55a6-b441-a84c7fcbf683', 'free-exercise-db', 'Extended_Range_One-Arm_Kettlebell_Floor_Press', 'Geniş Hareket Aralıklı Tek Kol Floor Press (Kettlebell)', 'push', 'beginner', 'compound', '["kettlebells"]', '["chest"]', '["shoulders", "triceps"]', '["Yere uzanın ve bir kolla bastırmak için bir kettlebell konumlandırın. Kettlebell sapından tutulmalıdır. İtme yaptığınız taraftaki bacak bükülü olmalı ve diz vücudun orta hattını geçmelidir.", "Dirseğinizi açarak ve kolunuzu içe doğru çekerek kettlebell''i vücudunuzun üzerine itin. Başlangıç pozisyonuna dönün."]', 'strength', '["Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg", "Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg"]', 360.0, 'Extended Range One-Arm Kettlebell Floor Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fe5bf8fa-cd0c-5235-92dc-6bcd6167e919', 'free-exercise-db', 'External_Rotation', 'External Rotation (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Bir kolunuzda dambıl, diğer eliniz başınızı üzerine yaslayabileceğiniz şekilde katlanmış halde sehpanın üstünde olacak şekilde düz sehpaya yan yatın.", "Dambılı tutan kolun dirseğini, üst kol ile ön kol arasında 90 derecelik açı oluşturacak şekilde bükün. İpucu: Kolu gövdenize paralel tutun.", "Şimdi üst kolu sabit tutarken dirseği bükün. Bu şekilde ön kol yere paralel ve gövdenize dik olacaktır (İpucu: Yani ön kol tam önünüzde olacaktır). Üst kol gövdenizin yanında sabit olmalı ve yere paralel olmalıdır (her zaman gövdenizle aynı hizada). Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken ön kolunuzu dışa doğru döndürün (external rotation); böylece üst kol ile ön kol arasındaki 90 derecelik bükülmeyi koruyarak dambıl yarım daire hareketiyle yukarı kalkar. Ön kol yere dik ve gövde tavana bakar hale gelene kadar bu dış rotasyona devam edin. Bu noktada kasılmayı bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin."]', 'strength', '["External_Rotation/0.jpg", "External_Rotation/1.jpg"]', 360.0, 'External Rotation', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('81b03ea9-525c-5f6b-882d-e369812f18ea', 'free-exercise-db', 'External_Rotation_with_Band', 'Dış Rotasyon (Direnç Bandı)', 'pull', 'beginner', 'compound', '["bands"]', '["shoulders"]', '[]', '["Bandı bir direğe dolayarak sıkıştırın. Bant dirseğinizle aynı yükseklikte olmalıdır. Sol tarafınız banda dönük şekilde birkaç ayak uzaklıkta durun.", "Bandın ucunu sağ elinizle kavrayın ve dirseğinizi yan tarafınıza sıkıca bastırın. Dirseğinizle yerinde sabitlemek için bir ped ya da foam roll tutmanızı öneririz.", "Üst kolunuz yerindeyken dirseğiniz 90 dereceye bükülü, eliniz gövdenizin önünden karşıya uzanıyor olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseğinizi yerinde tutarak kolunuzu backhand (tersten vuruş) hareketiyle döndürerek hareketi gerçekleştirin.", "Yapabildiğiniz kadar devam edin, bekleyin ve başlangıç pozisyonuna dönün."]', 'strength', '["External_Rotation_with_Band/0.jpg", "External_Rotation_with_Band/1.jpg"]', 360.0, 'External Rotation with Band', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('edfa8b80-b7ce-59a3-b9bb-5eda92a374ea', 'free-exercise-db', 'External_Rotation_with_Cable', 'Dışa Rotasyon (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["shoulders"]', '[]', '["Kabloyu dirseğinizle aynı yüksekliğe ayarlayın. Sol tarafınız bantla (kabloyla) karşı karşıya olacak şekilde birkaç adım uzakta durun.", "Sapı sağ elinizle kavrayın ve dirseğinizi sıkıca yan tarafınıza bastırın. Dirseğinizi sabit tutmak için dirseğinizle bir ped veya foam roll tutmanızı öneririz.", "Üst kolunuz yerindeyken, dirseğiniz 90 derece bükülü ve eliniz gövdenizin önünden karşı tarafa uzanmış olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseğinizi yerinde tutarak kolunuzu tenis backhand hareketi gibi dışa doğru döndürerek hareketi gerçekleştirin."]', 'strength', '["External_Rotation_with_Cable/0.jpg", "External_Rotation_with_Cable/1.jpg"]', 360.0, 'External Rotation with Cable', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('963f9aee-bcc6-5166-9587-20399a7dcabe', 'free-exercise-db', 'Face_Pull', 'Face Pull', 'pull', 'intermediate', 'compound', '["cable"]', '["shoulders"]', '["middle back"]', '["Halat veya çift tutamak takılı yüksek makaraya dönük durun ve ellerinizi birbirinden ayırarak ağırlığı doğrudan yüzünüze doğru çekin. Üst kollarınızı yere paralel tutun."]', 'strength', '["Face_Pull/0.jpg", "Face_Pull/1.jpg"]', 360.0, 'Face Pull', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2f901cff-6411-5014-ac71-514cb8a60d17', 'free-exercise-db', 'Farmers_Walk', 'Farmer''s Walk', NULL, 'intermediate', 'compound', '["other"]', '["forearms"]', '["abdominals", "glutes", "hamstrings", "lower back", "quadriceps", "traps"]', '["Farmer''s walk için kullanılabilecek çeşitli ekipmanlar vardır. Bu ekipmanlar mevcut değilse egzersiz ağır dambıllar veya kısa barlarla da yapılabilir. Ekipmanların arasında durarak başlayın.", "Sapları kavradıktan sonra, sırtınızı düz ve başınızı yukarıda tutarak topuklarınızdan iterek bunları kaldırın.", "Kısa ve hızlı adımlarla yürüyün ve nefes almayı unutmayın. Belirli bir mesafe boyunca, genellikle 15-30 metre, olabildiğince hızlı ilerleyin."]', 'strongman', '["Farmers_Walk/0.jpg", "Farmers_Walk/1.jpg"]', 480.0, 'Farmer''s Walk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5f539c67-29f2-5d6d-bd5d-b8d355cd8a9b', 'free-exercise-db', 'Fast_Skipping', 'Hızlı Skipping', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Bir bacağınız hafifçe önde olacak şekilde rahat bir pozisyonda başlayın. Bu sizin başlangıç pozisyonunuzdur.", "Sağ-sağ-adım, ardından sol-sol-adım şeklinde adım-sıçrama düzeniyle dönüşümlü olarak skipping yapın.", "Yerle temasınızı yakın tutarak ve havada kalma süresini azaltarak, olabildiğince hızlı hareket edip hızlı skipping yapın."]', 'plyometrics', '["Fast_Skipping/0.jpg", "Fast_Skipping/1.jpg"]', 480.0, 'Fast Skipping', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9c311b68-b594-53b1-8d64-cb21eda09f46', 'free-exercise-db', 'Finger_Curls', 'Finger Curl (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["forearms"]', '[]', '["Bir halteri iki elinizle avuç içleriniz yukarı bakacak şekilde tutun; elleriniz yaklaşık omuz genişliğinde açık olsun.", "Ayaklarınızı yere düz basın ve omuz genişliğinden biraz daha geniş açın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Parmaklarınızı açarak barı mümkün olduğunca aşağı indirin. Barın ellerinizden aşağı yuvarlanmasına izin vererek, barı parmaklarınızın son eklemiyle yakalayın.", "Şimdi nefes verirken ellerinizi kapatarak barı olabildiğince yukarı curl yapın. Üst noktada kasılmayı tutun."]', 'strength', '["Finger_Curls/0.jpg", "Finger_Curls/1.jpg"]', 360.0, 'Finger Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('37110777-b159-5bfb-aadd-09dca6555b4c', 'free-exercise-db', 'Flat_Bench_Cable_Flyes', 'Düz Sehpada Fly (Kablo)', 'push', 'intermediate', 'isolation', '["cable"]', '["chest"]', '[]', '["Düz bir sehpayı iki alt makaranın arasına, üzerine uzandığınızda göğsünüz kablo makaralarıyla hizalanacak şekilde yerleştirin.", "Sehpaya düz uzanın ve ayaklarınızı yerde tutun.", "Birinden her elinize tutamakları vermesini isteyin. Her bir tek tutamak aparatını avuç içleri yukarı bakacak şekilde kavrayacaksınız.", "Kollarınızı dirsekleriniz hafif bükülü olacak şekilde yanlara uzatın. İpucu: Bu bükülmeyi tüm hareket boyunca sabit tutacaksınız. Kolların yere paralel olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi kablo kollarını birbirine doğru çekerek kolları doğrudan önünüzde yarım daire hareketiyle, iki el hareketin tepesinde buluşana kadar kaldırmaya başlayın. Bu hareketi yaparken göğsünüzü sıkın ve nefes verin. Ayrıca en üstte kasılmayı bir saniye tutun. İpucu: Doğru yapıldığında, hareketin üst pozisyonunda kollarınız gövdenize dik olmalı ve eller göğsünüzün üzerinde birbirine değmelidir.", "Yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Flat_Bench_Cable_Flyes/0.jpg", "Flat_Bench_Cable_Flyes/1.jpg"]', 360.0, 'Flat Bench Cable Flyes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e07fec6c-3b60-55cb-89c4-2986b9257cc4', 'free-exercise-db', 'Flat_Bench_Leg_Pull-In', 'Leg Pull-In (Düz Bench)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Bir egzersiz matına veya bacaklarınız ucundan sarkacak şekilde düz bir bench''e uzanın.", "Ellerinizi avuç içleri aşağı bakacak şekilde kalçanızın altına veya yanlarda bench''i tutacak şekilde yerleştirin (egzersiz matı üzerindeyse avuç içleri aşağı bakacak şekilde yanlarda). Ayrıca bacaklarınızı düz uzatın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken dizlerinizi bükün ve üst uyluklarınızı gövdenize doğru çekin. Dizleriniz göğsünüze yaklaşana kadar bu hareketi sürdürün. Kasılmış pozisyonu bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Flat_Bench_Leg_Pull-In/0.jpg", "Flat_Bench_Leg_Pull-In/1.jpg"]', 360.0, 'Flat Bench Leg Pull-In', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9839c11c-0761-57c4-8801-89aa8f4bbd27', 'free-exercise-db', 'Flat_Bench_Lying_Leg_Raise', 'Düz Bankta Leg Raise', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Sırtınız düz bankta olacak ve bacaklarınız bankın ucundan dışarıda önünüzde uzanmış şekilde uzanın.", "Ellerinizi avuç içleri aşağı bakacak şekilde kalçanızın altına koyun veya yanlarda bankı tutacak şekilde yerleştirin. Bu sizin başlangıç pozisyonunuzdur.", "Bacaklarınızı mümkün olduğunca düz tutarak, dizler hafif bükülü ama kilitli halde, bacaklarınızı yerle 90 derecelik açı yapana kadar kaldırın. Hareketin bu kısmında nefes verin ve kasılmayı üstte bir saniye tutun.", "Şimdi nefes alırken bacaklarınızı yavaşça başlangıç pozisyonuna indirin."]', 'strength', '["Flat_Bench_Lying_Leg_Raise/0.jpg", "Flat_Bench_Lying_Leg_Raise/1.jpg"]', 360.0, 'Flat Bench Lying Leg Raise', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1a273df3-16b3-5400-8c30-d6c53828add7', 'free-exercise-db', 'Flexor_Incline_Dumbbell_Curls', 'Flexor Incline Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Dambılı sizden uzak olan taraftan tutun, böylece size yakın tarafta daha fazla ağırlık olsun. (Bu, tüm biceps dambıl egzersizlerinde iyi bir etki için uygulanabilir.) Şimdi normal bir incline dambıl curl yapın, ancak bilekleriniz üzerindeki herhangi bir stresi nötralize etmek için bileklerinizi olabildiğince geride tutun.", "Her elinizde bir dambıl tutarak 45 derece açılı bir incline bench üzerine oturun.", "Kollarınızı dirsekler içeride olacak şekilde yanlarınızda sarkıtın ve avuç içlerinizi başparmaklar vücuttan uzağa bakacak şekilde ileri çevirin. İpucu: Eller yukarı gelirken hiçbir dönme olmaması gerektiğinden bu el pozisyonunu hareket boyunca koruyacaksınız. Bu sizin başlangıç pozisyonunuz olacak.", "Biceps''iniz tamamen kasılana kadar iki dambılı aynı anda yukarı kıvırın ve nefes verin. İpucu: Kollarınızı sallamayın veya ivme kullanmayın. Her zaman kontrollü bir hareket sürdürün. Kasılmış pozisyonu üstte bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Flexor_Incline_Dumbbell_Curls/0.jpg", "Flexor_Incline_Dumbbell_Curls/1.jpg"]', 360.0, 'Flexor Incline Dumbbell Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8fa6c65d-2085-5c85-8d2c-ee595a6f7354', 'free-exercise-db', 'Floor_Glute-Ham_Raise', 'Yerde Glute-Ham Raise', 'pull', 'intermediate', 'isolation', '[]', '["hamstrings"]', '["calves", "glutes"]', '["Bu egzersiz için bir partner kullanabilir veya ayaklarınızı sabit bir şeyin altına sıkıştırabilirsiniz.", "Üst bacaklarınız ve gövdeniz dik şekilde dizlerinizin üzerinde başlayın. Partner kullanıyorsanız, sizi pozisyonda tutmak için ayaklarınızı sıkıca tutacaktır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Öne giderken kalçanızı BÜKMEMEYE dikkat ederek dizlerinizden açılarak kendinizi aşağı indirin.", "Yere ulaştığınızda ellerinizi önünüze koyun. Bu hareket çok zordur ve yardımsız yapamayabilirsiniz. Başlangıç pozisyonuna dönmenize yardımcı olmak için kollarınızla yerden hafifçe itin."]', 'strength', '["Floor_Glute-Ham_Raise/0.jpg", "Floor_Glute-Ham_Raise/1.jpg"]', 360.0, 'Floor Glute-Ham Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f67dc7c5-0672-5e45-9c33-e70b7ff2ec6b', 'free-exercise-db', 'Floor_Press', 'Floor Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "shoulders"]', '["J-kancaları, halteri rafa yerleştirmek için uygun yüksekliğe gelecek şekilde ayarlayın. Başınız power rack''in ucuna yakın olacak şekilde yerde sırtüstü uzanarak başlayın. Kürek kemiklerinizi birbirine yaklaştırarak halteri kancalardan çıkarın.", "Halteri göğsünüzün alt kısmına veya üst karnınıza doğru indirin; bunu yaparken halteri sıkın ve ikiye ayırmaya çalışır gibi çekin. Hareket boyunca dirseklerinizi içeride tuttuğunuzdan emin olun. Üst kolunuz yere değene kadar halteri indirin ve durun; ağırlığı çarptırmaktan veya sektirmekten kaçının.", "Halter, bilekleriniz ve dirsekleriniz aynı hizada kalacak şekilde halteri olabildiğince hızlı yukarı itin."]', 'powerlifting', '["Floor_Press/0.jpg", "Floor_Press/1.jpg"]', 360.0, 'Floor Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f4b2901e-47a4-5cf1-9077-5442bce0e02b', 'free-exercise-db', 'Floor_Press_with_Chains', 'Floor Press (Halter, Zincirli)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "shoulders"]', '["J-kancalarını barı rafa koymak için uygun yüksekliğe ayarlayın. Bu egzersiz için zincirleri doğrudan barın ucundan asın ve uçlarını plakalardan uzak tutmaya çalışın.", "Başınız bir power rack''in ucuna yakın olacak şekilde yerde uzanarak başlayın. Kürek kemiklerinizi birbirine doğru çekili tutarak barı kancalardan alın.", "Barı sıkıp ayırmaya çalışır gibi tutarak göğsünüzün alt kısmına veya üst karnınıza doğru indirin. Hareket boyunca dirseklerinizi içeride tuttuğunuzdan emin olun. Üst kolunuz yere değene kadar barı indirin ve duraklayın; ağırlığı çarptırmayın veya zıplatmayın.", "Barı bar, bilekleriniz ve dirseklerinizin aynı hizada kalmasını sağlayarak mümkün olduğunca hızlı bir şekilde yukarı itin."]', 'powerlifting', '["Floor_Press_with_Chains/0.jpg", "Floor_Press_with_Chains/1.jpg"]', 360.0, 'Floor Press with Chains', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('21716a8c-43e4-5738-bfbc-43672b9e4a04', 'free-exercise-db', 'Flutter_Kicks', 'Flutter Kick (Bankta Yüzüstü)', 'pull', 'beginner', 'compound', '["body only"]', '["glutes"]', '["hamstrings"]', '["Düz bir bankta kalçanız bankın kenarında olacak şekilde yüzüstü uzanın; bacaklar düz ve ayak parmakları yerden yüksekte, kollar bankın üzerinde ve ön kenarı tutuyor olsun.", "Kalça ve arka bacak kaslarınızı sıkın ve bacaklarınızı kalçanızla aynı hizaya gelene kadar düzleştirin. Bu sizin başlangıç pozisyonunuzdur.", "Hareketi sol bacağı sağ bacaktan daha yukarı kaldırarak başlatın.", "Ardından sağ bacağı kaldırırken sol bacağı indirin.", "Her bacak için önerilen tekrar sayısını tamamlayana kadar bu şekilde dönüşümlü olarak devam edin (suda çırpınma tekmesi yapar gibi). Hareketi her zaman kontrollü tuttuğunuzdan emin olun. İpucu: Bu hareketi yaparken normal nefes alıp verin."]', 'strength', '["Flutter_Kicks/0.jpg", "Flutter_Kicks/1.jpg"]', 360.0, 'Flutter Kicks', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('57a741dd-3d03-580b-a3c2-a3e84d170ec0', 'free-exercise-db', 'Foot-SMR', 'Ayak Masajı (Foam Roller)', 'static', 'intermediate', NULL, '["other"]', '["calves"]', '[]', '["Bu egzersiz ayaklardaki kasların fasyasını esnetir. Ayakkabılarınız çıkarılmış halde oturarak başlayın. Bir ayak rulosu veya küçük bir PVC boru parçası gibi benzer bir nesne kullanarak ayağınızı, ayak kemerinizin üzerinden ruloya dayayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sıkıca bastırın ve ayak kemerinizin üzerinde yuvarlayın. 10-30 saniye bekleyin, ardından ayak değiştirin."]', 'stretching', '["Foot-SMR/0.jpg", "Foot-SMR/1.jpg"]', 150.0, 'Foot-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('62826ef5-6bc7-58e6-ac0f-d2b822a9ad56', 'free-exercise-db', 'Forward_Drag_with_Press', 'İleri Sürükleme ve İtiş (Kızak)', 'push', 'intermediate', 'compound', '["other"]', '["chest"]', '["calves", "glutes", "hamstrings", "quadriceps", "shoulders", "triceps"]', '["Kızağa çift tutamaklı bir zincir ya da ip aparatı bağlayın. Kızağa sırtınız dönük olmalı ve her elinizde bir tutamak tutmalısınız.", "Hareketi bir adım ileri giderek başlatın. Öne eğilerek hareket etmek için bacaklarınızı ve kalçanızı açın; her adımda dirseklerinizi açarak ellerinizi öne doğru itmek için durun. Press yapmaya hazır başlangıç pozisyonuna dönene kadar ileri adım atın."]', 'strongman', '["Forward_Drag_with_Press/0.jpg", "Forward_Drag_with_Press/1.jpg"]', 480.0, 'Forward Drag with Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('885af78d-4f43-52ea-b332-571081a8b58c', 'free-exercise-db', 'Frankenstein_Squat', 'Frankenstein Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["abdominals", "calves", "glutes", "hamstrings"]', '["Bu çalışma, clean ve front squat sırasında hem halterin hem de vücudunuzun doğru konumlandırılmasını öğretir.", "Halteri omuzlarınızın ön kısmına yerleştirin, tutuşunuzu bırakın ve kollarınızı önünüze doğru uzatın. Omuzlar bir raf oluşturacak şekilde öne itilmelidir ve halter boğazınıza temas etmelidir. Yalnızca kürek kemiklerinizi öne hareket ettirdiğinizden emin olun; torasik omurgayı yuvarlamayın.", "Dizlerinizi ve kalçanızı bükerek, bacaklarınızın arasına oturarak squat yapın. Gövdenizi dik, kollarınızı yukarıda ve omuzlarınızı önde tutun; halter yerinde kalmalıdır. Arka bacaklarınız baldırlarınıza değene kadar squat''ın en alt noktasına inin.", "Topuğunuzun ön kısmıyla iterek ve dizlerinizi ve kalçanızı açarak dik pozisyona dönün."]', 'olympic weightlifting', '["Frankenstein_Squat/0.jpg", "Frankenstein_Squat/1.jpg"]', 420.0, 'Frankenstein Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('31084b7d-700f-5d5b-b26f-dbbeccd76055', 'free-exercise-db', 'Freehand_Jump_Squat', 'Sıçrama Squat (Vücut Ağırlığı)', 'push', 'intermediate', 'compound', '["body only"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Kollarınızı göğsünüzün üzerinde çapraz yapın.", "Başınız yukarıda ve sırtınız düz halde ayaklarınızı omuz genişliğinde konumlandırın.", "Sırtınızı düz ve göğsünüzü yukarıda tutarak, nefes alırken üst uyluklarınız yere paralel veya daha alçak olana kadar çömelin.", "Şimdi esas olarak ayaklarınızın ön kısmıyla iterek, uyluklarınızı yay gibi kullanarak olabildiğince yükseğe zıplayın. Hareketin bu kısmında nefes verin.", "Yere tekrar değdiğinizde hemen çömelin ve yeniden zıplayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Freehand_Jump_Squat/0.jpg", "Freehand_Jump_Squat/1.jpg"]', 360.0, 'Freehand Jump Squat', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6f004138-d58c-50c5-8dc7-4414abbf645a', 'free-exercise-db', 'Frog_Hops', 'Frog Hop (Kurbağa Sıçrayışı)', 'push', 'intermediate', 'compound', '[]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Ellerinizi başınızın arkasına koyarak durun ve gövdenizi dik, başınızı yukarıda tutarak çömelin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Gereksiz yere yüksek zıplamaktan kaçınarak birkaç adım öne doğru sıçrayın. Ayaklarınız yere değdiğinde darbeyi bacaklarınızla emin ve tekrar sıçrayın. Bu hareketi 5-10 kez tekrarlayın."]', 'stretching', '["Frog_Hops/0.jpg", "Frog_Hops/1.jpg"]', 150.0, 'Frog Hops', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b252bd57-98a7-5533-a7d7-651b329193fd', 'free-exercise-db', 'Frog_Sit-Ups', 'Kurbağa Mekik', 'pull', 'intermediate', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Sırtınız yerde (veya egzersiz matında) düz ve bacaklarınız önünüzde uzanmış şekilde uzanın.", "Şimdi dizlerinizden bükün ve ayak tabanlarınızı birbirine değdirirken dış uyluklarınızı yere (veya mata) yaklaştırın.", "Şimdi dış uyluklarınızı yerde (veya en azından neredeyse değecek şekilde) tutarken her iki ayak tabanını iterek mümkün olduğunca yakınınıza getirmeye çalışın. İpucu: Bu pozisyonda bacaklarınız bir elmas şekli oluşturmalıdır.", "Şimdi karşı omuzlarınıza dokunarak kollarınızı önünüzde çaprazlayın. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken gövdenizi yukarı kıvırırken alt sırtınızı yere yassılaştırın. İpucu: Bu, bir mekiğin ilk 1/4''lük hareketini yapmak gibi olacaktır. Üst pozisyonda bir saniye bekleyin.", "Nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Frog_Sit-Ups/0.jpg", "Frog_Sit-Ups/1.jpg"]', 360.0, 'Frog Sit-Ups', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('21f734ac-f37d-580e-8239-ac5683e42c7b', 'free-exercise-db', 'Front_Barbell_Squat', 'Front Squat (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bu egzersizi güvenlik amacıyla squat rafının içinde yapmak en iyisidir. Başlamak için önce barı boyunuza en uygun rafa yerleştirin. Doğru yüksekliği seçip barı yükledikten sonra dirseklerinizi yüksekte ve üst kolunuzu yere paralelin hafif üzerinde tutarak kollarınızı barın altına getirin. Barı deltoidlerinizin üzerine yerleştirin ve tam kontrol için barı kavrarken kollarınızı çaprazlayın.", "Önce bacaklarınızla iterek ve aynı anda gövdenizi doğrultarak barı raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşla, ayak parmakları hafifçe dışa bakacak şekilde konumlandırın. Aşağı bakmak dengenizi bozacağı için başınızı her zaman yukarıda tutun ve sırtınızı da düz tutun. Bu sizin başlangıç pozisyonunuzdur. (Not: Bu anlatım için genel gelişimi hedefleyen yukarıda tarif edilen orta duruşu kullanacağız; ancak ayak konumlandırma bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik iken dizlerinizi bükerek barı yavaşça indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz küçük oluncaya kadar (üst bacakların yere paralelin altında olduğu nokta) inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız dizlerinizin ön kısmı, ayak parmaklarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizgiyi geçerse (ayak parmaklarınızı geçerse) dize gereksiz yük bindiriyorsunuz ve egzersizi yanlış yapıyorsunuz demektir.", "Ağırlıklı olarak ayağınızın ortasıyla yeri iterek bacaklarınızı tekrar düzleştirirken nefes verip barı kaldırmaya başlayın ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Front_Barbell_Squat/0.jpg", "Front_Barbell_Squat/1.jpg"]', 360.0, 'Front Barbell Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d0c4082c-f0df-51c3-aff7-4e5b94043879', 'free-exercise-db', 'Front_Barbell_Squat_To_A_Bench', 'Front Squat (Halter, Bankta)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bu egzersizi güvenlik amacıyla bir squat rack içinde yapmak en iyisidir. Başlamak için önce arkanıza düz bir bank yerleştirin ve barı boyunuza en uygun yükseklikteki rafa koyun. Doğru yükseklik seçilip bar yüklendikten sonra, dirsekleriniz yukarıda ve üst kollarınız yere paralelin biraz üzerinde kalacak şekilde kollarınızı barın altından getirin. Barı deltoidlerin üzerine yaslayın ve tam kontrol için barı kavrarken kollarınızı çaprazlayın.", "Barı önce bacaklarınızla iterek ve aynı anda gövdenizi doğrultarak raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta duruşa getirin, ayak parmakları hafifçe dışa dönük olsun. Aşağıya bakmak dengenizi bozacağından başınızı her zaman yukarıda tutun ve sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuzdur. (Not: Bu anlatım için yukarıda tarif edilen, genel gelişimi hedefleyen orta duruş kullanılmıştır; ancak ayak pozisyonu bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik kalacak şekilde dizlerinizi bükerek barı yavaşça indirmeye başlayın. Kalçanız bankla temas edene kadar inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız, dizlerinizin ön kısmı ayak parmaklarınızla öne doğru dik, hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizgiyi geçerse (ayak parmaklarınızın ilerisine giderse) dize gereksiz yük bindirmiş olursunuz ve egzersiz yanlış yapılmıştır.", "Nefes verirken ağırlıklı olarak ayağınızın topuğuyla yere basarak bacaklarınızı tekrar düzleştirin ve barı kaldırarak başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Front_Barbell_Squat_To_A_Bench/0.jpg", "Front_Barbell_Squat_To_A_Bench/1.jpg"]', 360.0, 'Front Barbell Squat To A Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('25de6298-ece1-52fe-b5bc-e39dc8db3212', 'free-exercise-db', 'Front_Box_Jump', 'Front Box Jump', 'push', 'beginner', 'compound', '["other"]', '["hamstrings"]', '["abductors", "adductors", "calves", "glutes", "quadriceps"]', '["Önünüzde 30-60 cm mesafede uygun yükseklikte bir kutu ile başlayın. Ayaklarınız omuz genişliğinde açık dikilin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sıçrayışa hazırlanmak için kısa bir squat yapın ve kollarınızı geriye doğru savurun.", "Bu pozisyondan sekerek kalçanızı, dizlerinizi ve ayak bileklerinizi açın ve olabildiğince yükseğe sıçrayın. Kollarınızı öne ve yukarı doğru savurun.", "Kutuya dizleriniz bükülü şekilde inin ve darbeyi bacaklarınızla sönümleyin. Kutudan yere geri atlayabilir ya da tercihen bir seferde tek bacakla adım atarak inebilirsiniz."]', 'plyometrics', '["Front_Box_Jump/0.jpg", "Front_Box_Jump/1.jpg"]', 480.0, 'Front Box Jump', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('344c79a6-65a6-5bf4-bf05-a6d80f65e9d8', 'free-exercise-db', 'Front_Cable_Raise', 'Front Raise (Kablo)', 'push', 'beginner', 'isolation', '["cable"]', '["shoulders"]', '[]', '["Alt makaralı makinede ağırlığı seçin ve alt makaraya bağlı tek el kablo aparatını sol elinizle kavrayın.", "Makaraya sırtınızı dönün ve kolunuzu düz aşağı indirin; tek el kablo aparatı uyluklarınızın önünde, kol boyu uzaklıkta ve avuç içi uyluklarınıza bakacak şekilde olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarak (sallanmadan), avuç içi her zaman aşağı bakacak şekilde, dirsek hafif bükülü olarak sol kolunuzu öne doğru kaldırın. Kolunuz yere paralelin biraz üstüne gelene kadar yukarı çıkmaya devam edin. Hareketin bu kısmında nefes verin ve üstte bir saniye bekleyin.", "Şimdi nefes alırken kolunuzu yavaşça başlangıç pozisyonuna indirin.", "Bu kol için önerilen tüm tekrarlar yapıldıktan sonra kolları değiştirin ve egzersizi sağ kolla yapın."]', 'strength', '["Front_Cable_Raise/0.jpg", "Front_Cable_Raise/1.jpg"]', 360.0, 'Front Cable Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c32c2177-df6c-5dfe-bd9d-9b583f1a7297', 'free-exercise-db', 'Front_Cone_Hops_or_hurdle_hops', 'Öne Koni Sıçraması (Engel Sıçraması)', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Bir sıra koni veya başka küçük engeller dizin ve aralarına birkaç adım mesafe bırakın.", "İlk koninin önünde ayaklarınız omuz genişliğinde açık şekilde durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Zıplarken her iki kolunuzu da sallayarak iki ayağınızla ilk koninin üzerinden zıplayarak başlayın.", "İnişin etkisini dizlerinizi bükerek karşılayın ve ilk sıçramadan geri tepmeyle bir sonraki koninin üzerinden zıplayın.", "Tüm konilerin üzerinden zıplayana kadar devam edin."]', 'plyometrics', '["Front_Cone_Hops_or_hurdle_hops/0.jpg", "Front_Cone_Hops_or_hurdle_hops/1.jpg"]', 480.0, 'Front Cone Hops (or hurdle hops)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('42d61561-257a-50c8-a75c-407ea0f72222', 'free-exercise-db', 'Front_Dumbbell_Raise', 'Front Raise (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["İki dambıl alın ve gövdeniz dik, dambıllar kol boyu kadar uyluklarınızın önünde, avuç içleriniz uyluklarınıza bakacak şekilde ayakta durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Gövdenizi sabit tutarak (sallanmadan), dirseğinizi hafifçe bükerek ve avuç içleriniz her zaman aşağı bakacak şekilde sol dambılı öne doğru kaldırın. Kolunuz yere paralelin biraz üzerine gelene kadar yukarı çıkmaya devam edin. Hareketin bu kısmında nefes verin ve üst noktada bir saniye bekleyin. Bir saniyelik beklemeden sonra nefes alın.", "Şimdi dambılı yavaşça başlangıç pozisyonuna indirirken aynı anda sağ dambılı kaldırın.", "Her kol için önerilen tüm tekrar sayısı tamamlanana kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Front_Dumbbell_Raise/0.jpg", "Front_Dumbbell_Raise/1.jpg"]', 360.0, 'Front Dumbbell Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('26153f55-53de-5af9-9fb6-f383814e3dcc', 'free-exercise-db', 'Front_Incline_Dumbbell_Raise', 'Incline Front Raise (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Her elinizde bir dambıl tutarak eğimi 30 ile 60 derece arasında ayarlanmış bir incline bench''e oturun. İpucu: Kası her seferinde biraz farklı çalıştırmak için açıyı değiştirebilirsiniz.", "Kollarınızı önünüze düz bir şekilde uzatın, avuç içleriniz aşağı baksın ve dambıllar uyluklarınızın yaklaşık 2,5 cm üzerinde olsun. Bu sizin başlangıç pozisyonunuz olacak.", "Dirseklerinizi kilitli tutarak dambılları omuzlarınızın biraz üzerine gelene kadar yavaşça düz bir şekilde yukarı kaldırın. Üstte bir saniye sıkın ve hareketin bu kısmında nefes verdiğinizden emin olun. İpucu: Başınızı her zaman bench''e yaslı ve bacaklarınızı yerde tutun.", "Nefes alırken kolları başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Front_Incline_Dumbbell_Raise/0.jpg", "Front_Incline_Dumbbell_Raise/1.jpg"]', 360.0, 'Front Incline Dumbbell Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('20a0b577-7271-5c59-aa66-552ed8765191', 'free-exercise-db', 'Front_Leg_Raises', 'Öne Bacak Sallama', 'pull', 'beginner', NULL, '["body only"]', '["hamstrings"]', '[]', '["Bir sandalyenin veya başka bir desteğin yanında durun ve bir elinizle tutunun.", "Bacağınızı düz tutarak öne doğru sallayın. Ardından aşağı doğru sallayarak bacağınızı esnekliğinizin izin verdiği kadar geriye getirin. 5-10 kez tekrarlayın ve ardından bacak değiştirin."]', 'stretching', '["Front_Leg_Raises/0.jpg", "Front_Leg_Raises/1.jpg"]', 150.0, 'Front Leg Raises', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5d41c559-be33-5d27-86a3-e7438e7ab2ee', 'free-exercise-db', 'Front_Plate_Raise', 'Front Raise (Plaka)', 'push', 'intermediate', 'isolation', '["other"]', '["shoulders"]', '[]', '["Dik dururken bir halter plakasını 3 ve 9 pozisyonlarından iki elinizle tutun. Avuç içleriniz birbirine bakmalı, kollarınız hafifçe bükülü dirseklerle uzamış ve kilitli olmalı ve plaka önünüzde belinizin yakınında, gidebildiğiniz kadar aşağıda olmalıdır. İpucu: Kollar egzersiz boyunca bu pozisyonda kalacaktır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken plakayı omuz seviyesinin biraz üstüne gelene kadar yavaşça kaldırın. Kasılmayı bir saniye tutun. İpucu: Ağırlığı sallamadığınızdan veya dirseklerinizi bükmediğinizden emin olun. Gövdeniz de hareket boyunca sabit kalmalıdır.", "Nefes alırken plakayı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Front_Plate_Raise/0.jpg", "Front_Plate_Raise/1.jpg"]', 360.0, 'Front Plate Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('88a2de8e-eb16-5efb-a245-f6736217e8bf', 'free-exercise-db', 'Front_Raise_And_Pullover', 'Front Raise ve Pullover (Halter)', 'pull', 'beginner', 'compound', '["barbell"]', '["chest"]', '["lats", "shoulders", "triceps"]', '["Avuç içleri aşağı bakacak ve eller yaklaşık 15 inç (38 cm) aralıklı olacak şekilde bir halteri tutarak düz sehpaya uzanın.", "Halteri üst uyluklarınıza yerleştirin, kollarınızı uzatıp dirseklerinizi hafif bükülü tutarak kilitleyin. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes alırken kollarınızı düz tutarak ağırlığı yarım daire hareketiyle kaldırın. Halter başınızın üzerinden diğer tarafa geçene kadar aynı harekete devam edin (İpucu: halter yaklaşık 180 derece yol alacaktır). Bu noktada kollarınız yere paralel ve avuç içleriniz tavana bakıyor olmalıdır.", "Şimdi nefes verirken hareketi tersine çevirerek halteri başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Front_Raise_And_Pullover/0.jpg", "Front_Raise_And_Pullover/1.jpg"]', 360.0, 'Front Raise And Pullover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4f9851ec-8f5a-5a18-b0d4-07a75d582979', 'free-exercise-db', 'Front_Squat_Clean_Grip', 'Front Squat (Clean Tutuş)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["abdominals", "glutes", "hamstrings"]', '["Başlamak için önce barı rack üzerinde omuz seviyesinin biraz altına yerleştirin. Barı deltoidlerin üzerine, köprücük kemiklerine bastırarak ve boğazınıza hafifçe değecek şekilde dayayın. Ellerinizle clean tutuşu alın ve barı yerinde tutmaya yardımcı olması için ona yalnızca parmaklarınızla dokunun.", "Barı önce bacaklarınızla iterek, aynı anda gövdenizi dikleştirerek rack''ten kaldırın. Rack''ten uzaklaşın ve bacaklarınızı omuz genişliğinde, parmak uçları hafifçe dışa dönük orta bir duruşla konumlandırın. Başınızı ve dirseklerinizi her zaman yukarıda tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dizlerinizi bükerek bacaklarınızın arasına oturun. Arka bacak kaslarınız baldırlarınıza değene kadar inmeye devam edin. Çömelirken dizlerinizi dışa doğru itmek için abduktörlerinizi bilinçli olarak kullanarak dizlerinizi ayaklarınızla aynı hizada tutun.", "Nefes vererek, esas olarak ayağınızın topuğu veya orta kısmı ile yere basarak, bacaklarınızı tekrar düzeltip başlangıç pozisyonuna dönerek barı kaldırmaya başlayın."]', 'strength', '["Front_Squat_Clean_Grip/0.jpg", "Front_Squat_Clean_Grip/1.jpg"]', 360.0, 'Front Squat (Clean Grip)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9cd8de63-e38c-53f4-90b2-a22370bf41b2', 'free-exercise-db', 'Front_Squats_With_Two_Kettlebells', 'Front Squat (Çift Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["quadriceps"]', '["calves", "glutes"]', '["İki kettlebell''i omuzlarınıza clean ile alın. Bacaklarınızı ve kalçanızı açarak kettlebell''leri omuzlarınıza doğru çekerek omuzlarınıza getirin. Bunu yaparken bileklerinizi döndürün.", "Her zaman düz ileri bakarak, olabildiğince aşağı çömelin ve altta duraklayın. Çömelirken dizlerinizi dışa doğru itin. Gövdenizi dik, başınızı ve göğsünüzü yukarıda tutarak bacaklarınızın arasına doğru çömelmelisiniz.", "Topuklarınızdan iterek yukarı kalkın ve tekrarlayın."]', 'strength', '["Front_Squats_With_Two_Kettlebells/0.jpg", "Front_Squats_With_Two_Kettlebells/1.jpg"]', 360.0, 'Front Squats With Two Kettlebells', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f97550f6-5a4f-5591-abe8-e81264114ecb', 'free-exercise-db', 'Front_Two-Dumbbell_Raise', 'Front Raise (İki Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["İki dambıl alın ve gövdeniz dik, dambıllar uyluklarınızın önünde kollarınız uzanmış ve avuç içleriniz uyluklarınıza bakacak şekilde durun. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarak (sallanmadan), dirsekleriniz hafif bükülü ve avuç içleriniz her zaman aşağı bakacak şekilde dambılları öne doğru kaldırın. Kollarınız yere paralelin biraz üzerine gelene kadar yukarı çıkmaya devam edin. Hareketin bu kısmında nefes verin ve üstte bir saniye bekleyin.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Front_Two-Dumbbell_Raise/0.jpg", "Front_Two-Dumbbell_Raise/1.jpg"]', 360.0, 'Front Two-Dumbbell Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d87a4022-6aac-58be-8c62-e388e40d9b91', 'free-exercise-db', 'Full_Range-Of-Motion_Lat_Pulldown', 'Tam Hareket Açıklığı Lat Pulldown (Kablo)', 'pull', 'intermediate', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Ayakta ya da yüksek bir sehpada oturarak, yüksek makaralara bağlı iki üzengi kablosunu kavrayın. Kolların çevrenizde çaprazlanacağı ve avuç içlerinin öne bakacağı şekilde karşı elle tutun.", "Göğsünüzü yukarıda ve belinizde hafif bir kavisi koruyarak, normal bir pulldown yapıyormuş gibi tutamakları aşağı çekin. Hareket açıklığı daha çok bir yay şeklinde olacaktır. Hareket sırasında, alt pozisyonda avuç içleriniz öne değil birbirine bakacak şekilde ellerinizi döndürün. Yavaşça başlangıç pozisyonuna dönün ve tekrarlayın."]', 'strength', '["Full_Range-Of-Motion_Lat_Pulldown/0.jpg", "Full_Range-Of-Motion_Lat_Pulldown/1.jpg"]', 360.0, 'Full Range-Of-Motion Lat Pulldown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0265a03a-6337-5661-bac7-30ade947cbbb', 'free-exercise-db', 'Gironda_Sternum_Chins', 'Gironda Sternum Chin-Up', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["biceps", "middle back"]', '["Barfiks barını omuz genişliğinde alttan (avuç içleri size bakacak şekilde) bir tutuşla kavrayın.", "Şimdi kollarınız tamamen uzamış halde asılın, göğsünüzü dışarı çıkarın ve geriye yaslanın. İpucu: Hareketin tamamı boyunca geriye yaslanmış olacaksınız. Bu sizin başlangıç pozisyonunuz olacaktır.", "Hareket boyunca omurganız kavisli ve başınız bardan olabildiğince uzağa yaslanmış halde kendinizi bara doğru çekmeye başlayın. Hareketin bu kısmında nefes verin. İpucu: Hareketin üst noktasında kalçanız ve bacaklarınız yere göre yaklaşık 45 derecelik bir açıda olacaktır.", "Köprücük kemiğiniz barı geçene ve alt göğsünüz veya sternum bölgeniz bara değene kadar çekmeye devam edin. Bu kasılmayı bir saniye tutun. İpucu: Hareketin bu kısmını tamamladığınızda başınız yere paralel olacaktır.", "Nefes alırken yavaşça başlangıç pozisyonuna dönmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Gironda_Sternum_Chins/0.jpg", "Gironda_Sternum_Chins/1.jpg"]', 360.0, 'Gironda Sternum Chins', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4eaedec3-e8e4-5732-8d25-1adeda30713c', 'free-exercise-db', 'Glute_Ham_Raise', 'Glute Ham Raise', 'pull', 'intermediate', 'compound', '["machine"]', '["hamstrings"]', '["calves", "glutes"]', '["Ekipmanı vücudunuza göre ayarlayarak başlayın. Yüzüstü uzanırken ayaklarınızı silindirlerin arasındaki ayak plakasına dayayın. Dizleriniz pedin hemen arkasında olmalıdır.", "Hareketin alt noktasından başlayın. Dizlerinizi bükerek harekete başlarken sırtınızı kavisli tutun. Bunu yaparken ayak parmaklarınızı ayak plakasına bastırın. Üst vücudunuzu düz tutun ve vücudunuz dik konuma gelene kadar devam edin.", "İnişi kontrollü tutarak başlangıç pozisyonuna dönün."]', 'powerlifting', '["Glute_Ham_Raise/0.jpg", "Glute_Ham_Raise/1.jpg"]', 360.0, 'Glute Ham Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ccecd116-70bb-5527-b83f-930e381393b0', 'free-exercise-db', 'Glute_Kickback', 'Glute Kickback', 'push', 'beginner', 'compound', '["body only"]', '["glutes"]', '["hamstrings"]', '["Yerde veya egzersiz matında diz çökün ve kollarınız önünüze (gövdeye dik) uzanmış şekilde belinizden bükülün; böylece kolları omuz genişliğinde açık, diz çökmüş şınav pozisyonuna geçin. Başınız ileri bakmalı ve dizlerin bükülmesi arka bacak ile baldır arasında 90 derecelik bir açı oluşturmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken 90 derecelik bükülmeyi koruyarak sağ bacağınızı arka bacak kasları sırtınızla aynı hizaya gelene kadar kaldırın. Hareket boyunca kalça kaslarınızı kasın ve üst noktada kasılmayı bir saniye tutun. İpucu: Hareketin sonunda üst bacak yere paralel, baldır ise yere dik olmalıdır.", "Nefes alırken ilk pozisyona dönün ve şimdi sol bacakla tekrarlayın.", "Önerilen tüm tekrarlar yapılana kadar bacakları değiştirmeye devam edin."]', 'strength', '["Glute_Kickback/0.jpg", "Glute_Kickback/1.jpg"]', 360.0, 'Glute Kickback', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f334b8b8-c838-5541-a662-b010e30ef638', 'free-exercise-db', 'Goblet_Squat', 'Goblet Squat (Kettlebell)', 'push', 'beginner', 'compound', '["kettlebells"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "shoulders"]', '["Hafif bir kettlebell''i boynuzlarından tutarak göğsünüze yakın şekilde ayakta durun. Bu sizin başlangıç pozisyonunuzdur.", "Arka bacaklarınız baldırlarınıza değene kadar bacaklarınızın arasına doğru çömelin. Göğsünüzü ve başınızı yukarıda, sırtınızı düz tutun.", "En alt pozisyonda bekleyin ve dizlerinizi dışarı itmek için dirseklerinizi kullanın. Başlangıç pozisyonuna dönün ve 10-20 tekrar yapın."]', 'strength', '["Goblet_Squat/0.jpg", "Goblet_Squat/1.jpg"]', 360.0, 'Goblet Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('80e7c6af-d0e4-58eb-bf86-a3f05bbe5bc7', 'free-exercise-db', 'Good_Morning', 'Good Morning (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["abdominals", "glutes", "lower back"]', '["Halteri omuz yüksekliğinde bir rafta tutarak başlayın. Halteri omuzlarınızın üstüne değil, power squat''taki gibi omuzlarınızın arkasına yerleştirin. Sırtınızı sıkı, kürek kemiklerinizi birbirine yakın ve dizlerinizi hafif bükülü tutun. Raftan geriye adım atın.", "Kalçanızdan eğilerek, öne eğilirken kalçanızı geriye doğru hareket ettirerek neredeyse paralel pozisyona gelin. Sırtınızı kavisli ve boyun omurganızı doğru hizada tutun.", "Kalça ve arka bacak kaslarınızla kalçanızı açarak hareketi tersine çevirin. Başlangıç pozisyonuna dönene kadar devam edin."]', 'powerlifting', '["Good_Morning/0.jpg", "Good_Morning/1.jpg"]', 360.0, 'Good Morning', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5fb9ed4a-91cf-5342-ae48-6bbac9262a02', 'free-exercise-db', 'Good_Morning_off_Pins', 'Good Morning (Pin Pozisyonundan, Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["abdominals", "glutes", "lower back"]', '["Bir rafta yaklaşık mide hizanızda bir barla başlayın. Barın altına doğru eğilin ve barı omuzlarınızın üstüne değil, power squat''ta olduğu gibi omuzlarınızın arkasına yerleştirin. Doğru yükseklikte, öne eğildiğinizde yere neredeyse paralel olmalısınız. Sırtınızı sıkı, kürek kemiklerinizi birbirine yakın ve dizlerinizi hafif bükülü tutun. Sırtınızı kavisli ve boyun omurganızı doğru hizada tutun.", "Kalçalarınızı kalça ve arka bacak kaslarınızla açarak harekete başlayın ve ağırlıkla ayağa kalkın. Ağırlığı yavaşça pinlerin üzerine indirerek başlangıç pozisyonuna dönün."]', 'powerlifting', '["Good_Morning_off_Pins/0.jpg", "Good_Morning_off_Pins/1.jpg"]', 360.0, 'Good Morning off Pins', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7213ccce-5ec6-5f40-ac03-9f05ee4cb030', 'free-exercise-db', 'Gorilla_Chin_Crunch', 'Gorilla Chin/Crunch', 'pull', 'intermediate', 'compound', '["body only"]', '["abdominals"]', '["biceps", "lats"]', '["Bir barfiks barından, omuz genişliğinden biraz daha geniş bir ters (avuç içleri size dönük) tutuşla asılın.", "Şimdi baldırlarınız yere paralel, uyluklarınız ise yere dik kalacak şekilde dizlerinizi 90 derecelik açıyla bükün. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken, dizlerinizi aynı anda göğüs seviyesine kadar çekerek mekik yaparak kendinizi yukarı çekin. Burnunuz barla aynı seviyeye gelir gelmez yukarı çıkmayı bırakın. İpucu: Bu noktaya geldiğinizde mekik hareketini de aynı anda bitirmelisiniz.", "Başlangıç pozisyonuna dönerken yavaşça nefes almaya başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Gorilla_Chin_Crunch/0.jpg", "Gorilla_Chin_Crunch/1.jpg"]', 360.0, 'Gorilla Chin/Crunch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('19b01ac2-9be8-5583-974b-5442d02e2ca9', 'free-exercise-db', 'Groin_and_Back_Stretch', 'Kasık ve Sırt Esnetme', 'static', 'intermediate', 'compound', '[]', '["adductors"]', '[]', '["Dizleriniz bükülü ve ayaklarınız bitişik şekilde yere oturun.", "Parmaklarınızı başınızın arkasında kenetleyin. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi uyluklarınızın iç tarafına getirerek öne doğru kıvrılın. Kısa bir beklemeden sonra başınız yukarıda ve sırtınız düz olacak şekilde başlangıç pozisyonuna dönün. 10-20 tekrar yapın."]', 'stretching', '["Groin_and_Back_Stretch/0.jpg", "Groin_and_Back_Stretch/1.jpg"]', 150.0, 'Groin and Back Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('71bcd440-b2a5-5268-aa7e-668cf9dbfed2', 'free-exercise-db', 'Groiners', 'Groiner', 'pull', 'intermediate', 'compound', '["body only"]', '["adductors"]', '[]', '["Yerde şınav pozisyonunda başlayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Her iki bacağınızı kullanarak ileri zıplayın ve ayaklarınız ellerinizin yanına gelecek şekilde inin. Bunu yaparken başınızı yukarıda tutun.", "Başlangıç pozisyonuna dönün ve hemen hareketi tekrarlayın; 10-20 tekrar boyunca devam edin."]', 'stretching', '["Groiners/0.jpg", "Groiners/1.jpg"]', 150.0, 'Groiners', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('99ba394e-44c6-558c-8f8b-731b91ea3be5', 'free-exercise-db', 'Hack_Squat', 'Hack Squat (Makine)', 'push', 'beginner', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Gövdenizin arkasını makinenin sırt desteğine yaslayın ve omuzlarınızı sağlanan omuz minderlerinin altına yerleştirin.", "Bacaklarınızı platform üzerinde omuz genişliğinde orta bir duruşla, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. İpucu: Başınızı her zaman yukarıda ve sırtınızı her zaman minderde tutun.", "Kollarınızı makinenin yan saplarına yerleştirin ve güvenlik barlarını devre dışı bırakın (çoğu tasarımda bu, yan sapların öne bakan konumdan çapraz konuma getirilmesiyle yapılır).", "Şimdi dizlerinizi kilitlemeden bacaklarınızı düzeltin. Bu sizin başlangıç pozisyonunuz olacak. (Not: Bu anlatımda genel gelişimi hedefleyen yukarıda tarif edilen orta duruş kullanılacaktır; ancak ayak konumlandırma bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik şekilde (sırtınız her zaman minderde) dizlerinizi bükerek platformu yavaşça indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz az olana kadar inmeye devam edin (üst bacakların yere paralelin altında olduğu nokta). Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız, dizlerinizin ön kısmı ayak parmaklarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizginin ötesine geçiyorsa (ayak parmaklarınızı aşıyorsa) dizlere gereksiz yük bindiriyorsunuz demektir ve egzersiz yanlış yapılmıştır.", "Nefes verirken, esas olarak ayağınızın topuğuyla yeri iterek ve bacaklarınızı tekrar düzelterek platformu kaldırmaya ve başlangıç pozisyonuna dönmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Hack_Squat/0.jpg", "Hack_Squat/1.jpg"]', 360.0, 'Hack Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('cfcef273-0b2a-57de-be41-10a1a706759a', 'free-exercise-db', 'Hammer_Curls', 'Hammer Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Gövdeniz dik şekilde ayakta durun ve her elinizde kollarınız aşağı sarkacak şekilde birer dambıl tutun. Dirsekleriniz gövdenize yakın olmalıdır.", "Avuç içleri gövdenize bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi üst kolunuzu sabit tutarken nefes verin ve biceps''i kasarak ağırlığı öne doğru kaldırın. Biceps tamamen kasılana ve dambıl omuz hizasına gelene kadar ağırlığı kaldırmaya devam edin. Biceps''i sıkarak kasılmış pozisyonda kısa bir süre bekleyin. İpucu: Dirseği sabit tutmaya ve yalnızca ön kolu hareket ettirmeye odaklanın.", "Kısa duraklamanın ardından nefes alın ve dambılları yavaşça başlangıç pozisyonuna indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Hammer_Curls/0.jpg", "Hammer_Curls/1.jpg"]', 360.0, 'Hammer Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d6913622-cd0e-5e4c-bbbc-da3b324af414', 'free-exercise-db', 'Hammer_Grip_Incline_DB_Bench_Press', 'Incline Press (Dambıl, Çekiç Tutuş)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders", "triceps"]', '["Her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde bir incline bench''e uzanın. Avuç içleriniz birbirine bakacaktır.", "Dambılları yukarı kaldırmak için uyluklarınızdan destek alarak, dambılları omuz genişliğinde tutabilmeniz için bir seferde bir kolla kaldırın (clean).", "Omuz genişliğine geldiğinizde avuç içlerinizi nötr tutuşta (avuç içleri birbirine bakacak şekilde) tutun. Dirseklerinizi dışarı açık, üst kollarınızı omuzlarla aynı hizada (gövdeye dik) ve dirseklerinizi üst kol ile ön kol arasında 90 derecelik açı oluşturacak şekilde bükülü tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes alırken ağırlıkları yavaşça yanınıza doğru indirin. Dambıllar üzerinde her zaman tam kontrolü koruyun.", "Nefes verirken göğüs kaslarınızı kullanarak dambılları yukarı itin. Kasılmış pozisyonda kollarınızı kilitleyin, bir saniye bekleyin ve ardından yavaşça inmeye başlayın. İpucu: Aşağı inmek, yukarı çıkmaktan en az iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde dambılları uyluklarınıza geri koyun ve ardından yere bırakın. Bu, dambılları bırakmanın en güvenli yoludur."]', 'strength', '["Hammer_Grip_Incline_DB_Bench_Press/0.jpg", "Hammer_Grip_Incline_DB_Bench_Press/1.jpg"]', 360.0, 'Hammer Grip Incline DB Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('66d40702-4757-554f-95f5-521552720a7a', 'free-exercise-db', 'Hamstring-SMR', 'Arka Bacak Foam Roller (SMR)', 'static', 'beginner', 'isolation', '["foam roll"]', '["hamstrings"]', '[]', '["Oturur pozisyonda bacaklarınızı, foam roll üst bacaklarınızın arkasında kalacak şekilde üzerine uzatın. Ağırlığınızı desteklemek için ellerinizi yanınıza veya arkanıza koyun. Bu sizin başlangıç pozisyonunuzdur.", "Ellerinizi kullanarak kalçanızı yerden kaldırın ve ağırlığınızı foam roll üzerinde tek bacağa kaydırın. Esnettiğiniz bacağın arka bacak kaslarını gevşetin.", "Foam roll üzerinde kalçanın altından dizin arkasının üstüne kadar yuvarlanın ve gerginlik hissettiğiniz noktalarda 10-30 saniye bekleyin. Diğer bacak için tekrarlayın."]', 'stretching', '["Hamstring-SMR/0.jpg", "Hamstring-SMR/1.jpg"]', 150.0, 'Hamstring-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d4afac20-ceb4-5de2-9dac-34c5aab080f4', 'free-exercise-db', 'Hamstring_Stretch', 'Arka Bacak Esnetme', 'static', 'beginner', 'isolation', '[]', '["hamstrings"]', '[]', '["Sırtüstü yatın ve bir bacağınızı kalça doksan derece olacak şekilde üstünüzde uzatın. Diğer bacağınızı yerde düz tutun.", "Bir kemer, bant ya da ipi ayağınızın ön tabanına geçirin. Bu sizin başlangıç pozisyonunuzdur.", "Baldır ve arka bacaklarda gerilim oluşturmak için kemeri çekin. Bu esnetmeyi 10-30 saniye tutun ve diğer bacakla tekrarlayın."]', 'stretching', '["Hamstring_Stretch/0.jpg", "Hamstring_Stretch/1.jpg"]', 150.0, 'Hamstring Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('06d85846-1179-5dc3-abaa-b670729914a4', 'free-exercise-db', 'Handstand_Push-Ups', 'Handstand Şınav', 'push', 'expert', 'compound', '["body only"]', '["shoulders"]', '["triceps"]', '["Sırtınız duvara dönük olarak belinizden eğilin ve ellerinizi omuz genişliğinde yere koyun.", "Kollarınız düz halde kendinizi duvara doğru yukarı fırlatın. Vücudunuz baş aşağı, kollar ve bacaklar tamamen uzatılmış olmalıdır. Tüm vücudunuzu mümkün olduğunca düz tutun. İpucu: Bunu ilk kez yapıyorsanız, bir spotter''ın size yardım etmesini sağlayın. Ayrıca aşağıya bakmak yerine başınızla duvara dönük kalmaya dikkat edin.", "Nefes alırken başınız neredeyse yere değene kadar kendinizi yavaşça yere doğru indirin. İpucu: Baş yaralanmasını önlemek için yavaş inmeniz son derece önemlidir.", "Nefes verirken dirsekleriniz neredeyse kilitlenene kadar kendinizi yavaşça yukarı itin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Handstand_Push-Ups/0.jpg", "Handstand_Push-Ups/1.jpg"]', 360.0, 'Handstand Push-Ups', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d3ff3e61-8243-5124-b79f-c237b371263f', 'free-exercise-db', 'Hang_Clean', 'Hang Clean (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "forearms", "glutes", "hamstrings", "lower back", "shoulders", "traps"]', '["Omuz genişliğinde, çift üsten (double overhand) ya da hook tutuşla başlayın; bar uyluğun ortasında asılı dursun. Sırtınız düz ve hafifçe öne eğik olmalıdır.", "Kalçanızı, dizlerinizi ve ayak bileklerinizi agresif bir şekilde açarak ağırlığı yukarı doğru sürerek başlayın. Bunu yaparken omuzlarınızı kulaklarınıza doğru silkin.", "Gövdenizi dik ve dirseklerinizi yukarıda tutarak topuklarınızdan iterek hemen toparlanın. Ayakta durma pozisyonuna yükselene kadar devam edin."]', 'olympic weightlifting', '["Hang_Clean/0.jpg", "Hang_Clean/1.jpg"]', 420.0, 'Hang Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('87a6b34e-1be4-5180-9fcc-28a20e7d2df1', 'free-exercise-db', 'Hang_Clean_-_Below_the_Knees', 'Hang Clean (Halter, Diz Altından)', 'pull', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "forearms", "glutes", "hamstrings", "lower back", "shoulders", "traps"]', '["Omuz genişliğinde, çift üstten (double overhand) veya hook tutuşla, bar dizlerin hemen altında asılı olacak şekilde başlayın. Sırtınız düz ve hafifçe öne eğimli olmalıdır.", "Kalça, diz ve bileklerinizi güçlü şekilde açarak ağırlığı yukarı doğru itin. Bunu yaparken omuzlarınızı kulaklarınıza doğru silkin (shrug). Tam açılma sağlandığında, dirsekler yukarı ve dışa doğru olacak şekilde güçlü bir shrug ve kol bükme ile üçüncü çekişe geçin.", "Maksimum açılma noktasında kendinizi güçlü şekilde aşağı çekin ve bunu yaparken dirseklerinizi barın altına doğru döndürün. Barı front squat pozisyonunda karşılayın; squat derinliği, üçüncü çekişin sonunda barın bulunduğu yüksekliğe bağlıdır. Bar, öne uzatılmış omuzların üzerine yerleşmeli, eller gevşek şekilde boğaza hafifçe değmelidir. Toparlanmaya yardımcı olacak alt squat pozisyonuna kadar inmeye devam edin.", "Gövdenizi dik ve dirseklerinizi yukarıda tutarak topuklarınızla iterek hemen toparlanın. Ayakta duruş pozisyonuna yükselene kadar devam edin."]', 'olympic weightlifting', '["Hang_Clean_-_Below_the_Knees/0.jpg", "Hang_Clean_-_Below_the_Knees/1.jpg"]', 420.0, 'Hang Clean - Below the Knees', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f3f8e735-46a4-5691-b589-5b7c5b0b25b8', 'free-exercise-db', 'Hang_Snatch', 'Hang Snatch (Halter)', 'pull', 'expert', 'compound', '["barbell"]', '["hamstrings"]', '["abdominals", "calves", "forearms", "glutes", "lower back", "quadriceps", "shoulders", "traps"]', '["Halteri geniş, üstten veya hook tutuşla kavrayarak başlayın. Ayaklarınız tam kalçanızın altında ve dışa dönük olmalıdır. Dizleriniz hafif bükülü ve gövdeniz öne eğik olmalıdır. Omurga tamamen açık ve baş ileri bakıyor olmalıdır. Halter kalça hizasında olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Bacaklarınızı ve kalçanızı agresif şekilde açın. Tam açılma noktasında omuzlarınızı silkin ve dirseklerinizin yanlara doğru bükülmesine izin verin.", "Ayaklarınızı karşılama pozisyonuna getirirken halteri tepenize doğru yükseltirken kendinizi halterin altına güçlü şekilde çekin. Halteri vücudunuz olabildiğince alçakta ve kollarınız tepenizde tamamen açık şekilde karşılayın.", "Ağırlık tepenizdeyken ayakta durma pozisyonuna dönün. Ardından ağırlığı kontrollü bir şekilde yere geri bırakın."]', 'olympic weightlifting', '["Hang_Snatch/0.jpg", "Hang_Snatch/1.jpg"]', 420.0, 'Hang Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7587d930-1157-5c28-aa0f-80b08ca20747', 'free-exercise-db', 'Hang_Snatch_-_Below_Knees', 'Hang Snatch (Diz Altı)', 'pull', 'expert', 'compound', '["barbell"]', '["hamstrings"]', '["abdominals", "calves", "forearms", "glutes", "lower back", "quadriceps", "shoulders", "traps"]', '["Barı üstten veya hook tutuşla geniş bir şekilde kavrayarak başlayın. Ayaklarınız kalçanızın tam altında ve dışa dönük olmalıdır. Dizleriniz hafifçe bükülü ve gövdeniz öne eğik olmalıdır. Omurga tamamen uzatılmış ve baş ileriye bakıyor olmalıdır. Bar dizlerin hemen altında olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Bacaklarınızı ve kalçanızı güçlü bir şekilde açın. Tam açılmanın zirvesinde omuzlarınızı silkin ve dirseklerinizin yana doğru bükülmesine izin verin.", "Ayaklarınızı karşılama pozisyonuna getirirken barı başınızın üzerine kaldırırken kendinizi kuvvetle barın altına çekin. Barı vücudunuz olabildiğince alçakta ve kollarınız başınızın üzerinde tamamen uzatılmış halde karşılayın.", "Ağırlık başınızın üzerindeyken ayakta duruş pozisyonuna dönün, ardından ağırlığı kontrollü bir şekilde yere geri indirin."]', 'olympic weightlifting', '["Hang_Snatch_-_Below_Knees/0.jpg", "Hang_Snatch_-_Below_Knees/1.jpg"]', 420.0, 'Hang Snatch - Below Knees', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0278f267-43e8-5da2-83e6-908a4cb0e423', 'free-exercise-db', 'Hanging_Bar_Good_Morning', 'Asılı Bar Good Morning (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["abdominals", "glutes", "lower back"]', '["Bir barı, karın hizanızda yaklaşık aynı yükseklikte bir rafa yerleştirerek başlayın. Barı zincirler ya da süspansiyon kayışları ile asın.", "Barın altında öne eğilin ve barı trapezlerinizin üzerine değil, power squat''ta olduğu gibi omuzlarınızın arkasına yerleştirin. Doğru yükseklikte, öne eğildiğinizde yere neredeyse paralel olmalısınız. Sırtınızı sıkı, kürek kemiklerinizi birbirine sıkıştırılmış ve dizlerinizi hafif bükülü tutun. Sırtınızı kavisli tutun ve boyun omurganızı doğru hizada tutun.", "Kalçanızı, kalça ve arka bacak kaslarınızla açarak harekete başlayın ve ağırlıkla ayağa kalkın.", "Ağırlığı yavaşça, zincirler tarafından desteklendiği başlangıç pozisyonuna indirin."]', 'powerlifting', '["Hanging_Bar_Good_Morning/0.jpg", "Hanging_Bar_Good_Morning/1.jpg"]', 360.0, 'Hanging Bar Good Morning', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fba152db-c9f8-5f2b-96ef-25ce7b0678be', 'free-exercise-db', 'Hanging_Leg_Raise', 'Asılı Bacak Kaldırma', 'pull', 'expert', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Kollarınız başınızın üzerinde tam uzamış halde, geniş veya orta bir tutuşla bir barfiks barından asılın. Bacaklar düz aşağıda olmalı ve leğen kemiği hafifçe geriye yuvarlanmış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Gövde ile bacaklar arasında 90 derecelik açı oluşana kadar bacaklarınızı kaldırın. Bu hareketi yaparken nefes verin ve kasılmayı yaklaşık bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Hanging_Leg_Raise/0.jpg", "Hanging_Leg_Raise/1.jpg"]', 360.0, 'Hanging Leg Raise', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3a3544ac-8535-5266-ac3f-0d62335134cd', 'free-exercise-db', 'Hanging_Pike', 'Hanging Pike (Barfikste Bacak Kaldırma)', 'pull', 'expert', 'compound', '["body only"]', '["abdominals"]', '[]', '["Bacaklarınız ve ayaklarınız bitişik olacak şekilde, omuz genişliğinden biraz daha geniş üstten tutuşla (avuç içleri sizden uzağa bakacak şekilde) bir barfiks barından asılın. İpucu: Bara tutunmayı kolaylaştırmak için bilek bandajı kullanabilirsiniz.", "Şimdi dizlerinizi 90 derece bükün ve üst bacaklarınızı öne getirin; böylece baldırlarınız yere dik, uyluklar yere paralel kalır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken bacaklarınızı kaval kemiklerinizle tepenizdeki bara neredeyse dokunana kadar yukarı çekin. İpucu: Üst noktada bacaklarınızı olabildiğince düzleştirmeye çalışın.", "Bacaklarınızı başlangıç pozisyonuna gelene kadar olabildiğince yavaş indirin. İpucu: Her zaman sallanmaktan ve ivme kullanmaktan kaçının.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Hanging_Pike/0.jpg", "Hanging_Pike/1.jpg"]', 360.0, 'Hanging Pike', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0f52263a-9453-50df-bc50-8bc7ac7c629e', 'free-exercise-db', 'Heaving_Snatch_Balance', 'Heaving Snatch Balance (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["abdominals", "forearms", "glutes", "hamstrings", "shoulders", "triceps"]', '["Bu çalışma snatch''i öğrenmenize yardımcı olur. Omuzlarınızın arkasında hafif bir ağırlık tutarak başlayın. Ayaklarınız kalça genişliğinden biraz daha geniş ve dışa dönük olmalıdır; squat yaparkenki aynı pozisyon.", "Dizlerinizi hafifçe bükerek çökün ve barın yükünü kısa süreliğine boşaltmak için tekrar yukarı sıçrayın. Kendinizi barın altına sürün; tam squat''a inerken barı başınızın üzerine yükseltin.", "Ayakta durma pozisyonuna dönün."]', 'olympic weightlifting', '["Heaving_Snatch_Balance/0.jpg", "Heaving_Snatch_Balance/1.jpg"]', 420.0, 'Heaving Snatch Balance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b6cea886-b5f3-559e-81d7-78248d5402c1', 'free-exercise-db', 'Heavy_Bag_Thrust', 'Ağır Torbaya İtiş', 'push', 'beginner', 'compound', '["other"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Bu egzersiz için bir ağır boks torbası kullanın. Torbanın yanında ayaklarınız aralıklı ve oldukça geniş açık şekilde dik bir duruş alın. Elinizi torbanın üzerine yaklaşık göğüs hizasına koyun. Bu sizin başlangıç pozisyonunuzdur.", "Belinizden dönerek torbayı olabildiğince sert itmeye başlayın. Bu hareketi hızlı yapın ve torbayı vücudunuzdan uzağa itin.", "Torba geri sallandığında bu adımları tersine çevirerek torbayı karşılayın."]', 'plyometrics', '["Heavy_Bag_Thrust/0.jpg", "Heavy_Bag_Thrust/1.jpg"]', 480.0, 'Heavy Bag Thrust', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('88b92daf-33db-5e7a-9cf9-471c776396e5', 'free-exercise-db', 'High_Cable_Curls', 'Yüksek Kablo Biceps Curl', 'pull', 'intermediate', 'compound', '["cable"]', '["biceps"]', '[]', '["İki yüksek makaranın arasında durun ve her kolunuzla bir sap tutun. Üst kollarınız yere paralel ve avuç içleriniz size bakacak şekilde konumlandırın. Bu sizin başlangıç pozisyonunuz olacak.", "Sapları kulaklarınızın yanına gelene kadar size doğru kıvırın. Bunu yaparken biceps''inizi kastığınızdan ve nefes verdiğinizden emin olun. Üst kollar sabit kalmalı ve sadece ön kollar hareket etmeli. Biceps''i sıkarken kasılmış pozisyonda bir saniye bekleyin.", "Kolları yavaşça başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["High_Cable_Curls/0.jpg", "High_Cable_Curls/1.jpg"]', 360.0, 'High Cable Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3b9c5839-b75f-5a2e-b54b-f8397cd525a5', 'free-exercise-db', 'Hip_Circles_prone', 'Hip Circle (Dört Ayak Pozisyonu)', 'pull', 'beginner', 'isolation', '["body only"]', '["abductors"]', '["adductors"]', '["Yerde ellerinizin ve dizlerinizin üzerinde konumlanın. İyi bir duruş koruyarak bükülü bir dizinizi yerden kaldırın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dizinizi bükülü tutarak femuru bir yay çizerek döndürün ve dizinizle büyük bir daire çizmeye çalışın.", "Bunu belirli sayıda tekrar boyunca yavaşça yapın, ardından diğer tarafta tekrarlayın."]', 'stretching', '["Hip_Circles_prone/0.jpg", "Hip_Circles_prone/1.jpg"]', 150.0, 'Hip Circles (prone)', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('23a631c7-828b-531a-b835-6583843189e8', 'free-exercise-db', 'Hip_Extension_with_Bands', 'Kalça Extension (Direnç Bandı)', 'push', 'beginner', 'compound', '["bands"]', '["glutes"]', '["hamstrings"]', '["Bandın bir ucunu bir direğin alt kısmına sabitleyin ve diğer ucunu bir ayak bileğine bağlayın.", "Bandın bağlantı noktasına dönük durun ve dengenizi sağlamak için direkten tutunun.", "Başınızı ve göğsünüzü yukarıda tutarak, diziniz düz kalacak şekilde dirençli bacağınızı olabildiğince geriye hareket ettirin.", "Bacağınızı başlangıç pozisyonuna geri getirin."]', 'strength', '["Hip_Extension_with_Bands/0.jpg", "Hip_Extension_with_Bands/1.jpg"]', 360.0, 'Hip Extension with Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('414e3bf0-868c-5e6a-a60b-6cdaa0d3786c', 'free-exercise-db', 'Hip_Flexion_with_Band', 'Kalça Fleksiyonu (Direnç Bandı)', 'pull', 'beginner', 'compound', '["bands"]', '["quadriceps"]', '[]', '["Bandın bir ucunu bir direğin alt kısmına sabitleyin ve diğer ucunu bir bileğinize bağlayın.", "Bandın bağlandığı noktaya sırtınız dönük şekilde durun.", "Başınızı ve göğsünüzü dik tutarak dizinizi 90 dereceye kadar yukarı kaldırın ve bekleyin.", "Bacağınızı başlangıç pozisyonuna döndürün."]', 'strength', '["Hip_Flexion_with_Band/0.jpg", "Hip_Flexion_with_Band/1.jpg"]', 360.0, 'Hip Flexion with Band', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f455ff93-e0c4-592d-8033-7b89d18b1837', 'free-exercise-db', 'Hip_Lift_with_Band', 'Hip Lift (Direnç Bandı)', 'push', 'beginner', 'compound', '["bands"]', '["glutes"]', '["calves", "hamstrings"]', '["Uygun bir bant seçtikten sonra, bandı iki yanınızdan sabitleyerek rack''in ortasına uzanın. Rack''inizde pim yoksa, bant ağır dambıllar veya benzeri nesnelerle sabitlenebilir; sadece hareket etmeyeceklerinden emin olun.", "Pozisyonunuzu bant doğrudan kalçanızın üzerinde olacak şekilde ayarlayın. Dizlerinizi bükün ve ayaklarınızı yere düz basın. Ellerinizi yere koyabilir veya bandı yerinde tutmak için kullanabilirsiniz.", "Omuzlarınızı yerde tutarak, topuklarınızdan iterek kalçanızı kaldırın ve bandı gidebildiğiniz kadar yukarı doğru itin.", "Hareketin üst noktasında bekleyin ve başlangıç pozisyonuna dönün."]', 'powerlifting', '["Hip_Lift_with_Band/0.jpg", "Hip_Lift_with_Band/1.jpg"]', 360.0, 'Hip Lift with Band', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c6c3cfd0-07c7-560e-8a40-d9222dfbdec4', 'free-exercise-db', 'Hug_A_Ball', 'Topa Sarılma Esnetmesi', 'static', 'beginner', 'isolation', '["exercise ball"]', '["lower back"]', '["calves", "glutes"]', '["Yere oturun.", "Bir egzersiz topunu iki bacağınızın arasına alın (ata biner gibi) ve kalçanızı yere doğru alçaltın.", "Vücudunuzu desteklemek için kollarınızı topun etrafına sarın. Bacaklarınızı, ayaklarınız yerde düz ve dizleriniz ayak bileklerinizin üzerinde hizalı olacak şekilde ayarlayın. Topun sizden uzağa yuvarlanıp sizi kalçanızın üzerine düşürmemesi için topu iyi kavrayın."]', 'stretching', '["Hug_A_Ball/0.jpg", "Hug_A_Ball/1.jpg"]', 150.0, 'Hug A Ball', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a887afb4-a709-579a-9270-af3dda9672c9', 'free-exercise-db', 'Hug_Knees_To_Chest', 'Dizleri Göğse Çekme Esnetmesi', 'static', 'beginner', NULL, '[]', '["lower back"]', '["glutes"]', '["Sırtüstü uzanın ve her iki dizinizi göğsünüze çekin.", "Kollarınızı dizlerin üzerinden değil, altından geçirin (bu diz eklemlerinize çok fazla baskı yapar).", "Dizleri yavaşça omuzlarınıza doğru çekin. Bu aynı zamanda kalça kaslarınızı da esnetir."]', 'stretching', '["Hug_Knees_To_Chest/0.jpg", "Hug_Knees_To_Chest/1.jpg"]', 150.0, 'Hug Knees To Chest', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ade147f8-1c36-5a02-b109-1339e2ad8bbb', 'free-exercise-db', 'Hurdle_Hops', 'Engel Sıçrama', 'push', 'beginner', 'compound', '["other"]', '["hamstrings"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Birkaç adım arayla bir sıra engel veya başka küçük bariyerler kurun.", "Ayaklarınız omuz genişliğinde açık şekilde ilk engelin önünde durun. Bu sizin başlangıç pozisyonunuz olacak.", "İki ayakla birlikte ilk engelin üzerinden zıplayarak başlayın ve zıplarken iki kolunuzu sallayın.", "Dizlerinizi bükerek iniş darbesini emerek, ilk sıçramadan sekerek bir sonraki engelin üzerinden zıplayın. Tüm engellerin üzerinden atlayana kadar devam edin."]', 'plyometrics', '["Hurdle_Hops/0.jpg", "Hurdle_Hops/1.jpg"]', 480.0, 'Hurdle Hops', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f5c4febc-04a9-5da0-91f0-f9338edf0ead', 'free-exercise-db', 'Hyperextensions_Back_Extensions', 'Hyperextension (Sırt Ekstansiyonu)', 'pull', 'beginner', 'isolation', '["other"]', '["lower back"]', '["glutes", "hamstrings"]', '["Ayak bileklerinizi ayak pedlerinin altına sağlam şekilde yerleştirerek hyperextension sehpasına yüzüstü uzanın.", "Mümkünse üst pedi, üst uyluklarınız geniş pedin üzerinde düz duracak ve belinizden herhangi bir kısıtlama olmadan eğilmeniz için yeterli alan kalacak şekilde ayarlayın.", "Vücudunuz düzken kollarınızı önünüzde (benim tercihim) veya başınızın arkasında çaprazlayın. Bu sizin başlangıç pozisyonunuzdur. İpucu: Ek direnç için çapraz kollarınızın altında önünüzde bir ağırlık plakası da tutabilirsiniz.", "Sırtınızı düz tutarak belden olabildiğince yavaşça öne eğilmeye başlayın. Bu hareketi yaparken nefes alın. Arka bacaklarınızda güzel bir esneme hissedene ve sırtınızı yuvarlamadan daha fazla devam edemeyene kadar öne doğru hareket etmeye devam edin. İpucu: Bu egzersizi yaparken asla sırtınızı yuvarlamayın. Ayrıca bazı kişiler diğerlerinden daha ileri gidebilir. Önemli olan, sırtınızı yuvarlamadan vücudunuzun izin verdiği kadar ileri gitmenizdir.", "Nefes alırken gövdenizi yavaşça ilk pozisyonuna kaldırın. İpucu: Sırtınızı düz çizgiyi geçecek kadar kavislendirme isteğine karşı koyun. Ayrıca sırtınızı sakatlanmaya karşı korumak için gövdenizi hiçbir zaman sallamayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Hyperextensions_Back_Extensions/0.jpg", "Hyperextensions_Back_Extensions/1.jpg"]', 360.0, 'Hyperextensions (Back Extensions)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('998b9f35-c29e-5c8a-987f-b12871a43fc0', 'free-exercise-db', 'Hyperextensions_With_No_Hyperextension_Bench', 'Hiperekstansiyon (Düz Bankta)', 'pull', 'intermediate', 'compound', '["body only"]', '["lower back"]', '["glutes", "hamstrings"]', '["Biri bacaklarınızı tutarken, kalçanız bankın ucundan sarkacak şekilde düz bankın kenarına doğru kayın. İpucu: Tüm üst vücudunuz yere doğru sarkıyor olmalıdır. Ayrıca hiperekstansiyon bankındaki ile aynı pozisyonda olacaksınız, ancak düz bankın yüksekliği hiperekstansiyon bankına göre farklı olduğundan hareket açıklığı daha kısa olacaktır.", "Vücudunuz düz haldeyken kollarınızı önünüzde (benim tercihim) veya başınızın arkasında çaprazlayın. Bu sizin başlangıç pozisyonunuzdur. İpucu: Ekstra direnç için çaprazladığınız kolların altında önünüzde bir plaka da tutabilirsiniz.", "Sırtınızı düz tutarak belinizden olabildiğince yavaşça öne eğilmeye başlayın. Bu hareketi yaparken nefes alın. Yere neredeyse değene veya arka bacaklarınızda güzel bir esneme hissedene kadar (hangisi önce gelirse) öne doğru hareket etmeye devam edin. İpucu: Bu egzersizi yaparken sırtınızı asla yuvarlamayın.", "Nefes verirken gövdenizi yavaşça ilk pozisyona kaldırın. İpucu: Sırtınızı düz çizginin ötesine kavislendirme isteğinden kaçının. Ayrıca sırtınızı sakatlanmaktan korumak için gövdenizi hiçbir zaman sallamayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Hyperextensions_With_No_Hyperextension_Bench/0.jpg", "Hyperextensions_With_No_Hyperextension_Bench/1.jpg"]', 360.0, 'Hyperextensions With No Hyperextension Bench', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('63e6ab67-2093-50c4-8e6a-a45c41c60a91', 'free-exercise-db', 'IT_Band_and_Glute_Stretch', 'IT Band ve Kalça Esnetme', 'static', 'intermediate', NULL, '["other"]', '["abductors"]', '[]', '["Bir kemer, ip ya da bandı ayaklarınızdan birine dolayın ve yerde uzanırken bacağı uzatılmış halde gövdenizin üzerinden karşı tarafa doğru savurun. Bu sizin başlangıç pozisyonunuzdur.", "Ayağınızı yerden uzak tutarak kemeri çekin ve gerilimi kullanarak ayak parmaklarını yukarı çekin. 10-20 saniye bekleyin ve diğer tarafta tekrarlayın."]', 'stretching', '["IT_Band_and_Glute_Stretch/0.jpg", "IT_Band_and_Glute_Stretch/1.jpg"]', 150.0, 'IT Band and Glute Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ec7476c7-2d6f-5eaf-84e9-af3e61b9e2f3', 'free-exercise-db', 'Iliotibial_Tract-SMR', 'IT Band Foam Roll', 'static', 'intermediate', 'isolation', '["foam roll"]', '["abductors"]', '[]', '["Yan yatın; alttaki bacağınız kalça ile diz arasında foam roller üzerinde olsun. Diğer bacağınız önünüzde çapraz olabilir.", "Ağırlığınızın tolere edebildiğiniz kadarını alttaki bacağınıza verin; alttaki bacağınızı yerle temas halinde tutmanıza gerek yoktur. Esnettiğiniz bacağın kaslarını gevşettiğinizden emin olun.", "Bacağınızı kalçanızdan dizinize kadar foam roller üzerinde yuvarlayın ve gerginlik hissettiğiniz noktalarda 10-30 saniye duraklayın. Karşı bacakla tekrarlayın."]', 'stretching', '["Iliotibial_Tract-SMR/0.jpg", "Iliotibial_Tract-SMR/1.jpg"]', 150.0, 'Iliotibial Tract-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('516ec5f3-0e86-5d5d-815d-a837f7f97862', 'free-exercise-db', 'Inchworm', 'Inchworm', NULL, 'beginner', 'compound', '["body only"]', '["hamstrings"]', '[]', '["Ayaklarınız birbirine yakın şekilde ayakta durun. Bacaklarınızı düz tutarak aşağı doğru uzanın ve ellerinizi hemen önünüzde yere koyun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Ellerinizi sol ve sağ dönüşümlü olarak yavaşça öne doğru yürüterek başlayın. Bunu yaparken bacaklarınızı düz tutarak sadece kalçanızdan eğilin.", "Vücudunuz şınav pozisyonunda yere paralel olana kadar devam edin.", "Şimdi ellerinizi yerinde tutarak, ayaklarınızla her seferinde sadece birkaç santimetre ilerleyerek yavaşça kısa adımlar atın.", "Bacaklarınızı düz tutarak ayaklarınız ellerinizin yanına gelene kadar yürümeye devam edin."]', 'stretching', '["Inchworm/0.jpg", "Inchworm/1.jpg"]', 150.0, 'Inchworm', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('351fc5bb-c4a9-556b-95e6-1a100b729bfd', 'free-exercise-db', 'Incline_Barbell_Triceps_Extension', 'Incline Triceps Extension (Halter)', 'push', 'intermediate', 'isolation', '["barbell"]', '["triceps"]', '["forearms"]', '["Halteri omuz genişliğinden biraz daha dar bir üsten tutuşla (avuç içleri aşağı) tutun.", "45-75 derece arasında herhangi bir açıya ayarlanmış eğimli bir sehpaya uzanın.", "Kollarınız uzanmış ve dirsekleriniz içeride olacak şekilde barı başınızın üzerine getirin. Kollar başın üzerinde gövdeyle aynı hizada olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi önkollarınız biceps''inize değene kadar barı başınızın arkasına yarım daire hareketiyle indirin. Bu hareketi yaparken nefes alın. İpucu: Üst kollarınızı her zaman sabit ve başınıza yakın tutun. Yalnızca ön kollar hareket etmelidir.", "Nefes verip triceps''inizi kasarak başlangıç pozisyonuna dönün. Kasılmayı bir saniye tutun.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Incline_Barbell_Triceps_Extension/0.jpg", "Incline_Barbell_Triceps_Extension/1.jpg"]', 360.0, 'Incline Barbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('178962f2-bd20-5b5c-a0eb-0173bd7334ce', 'free-exercise-db', 'Incline_Bench_Pull', 'Incline Bench Pull', 'pull', 'beginner', 'isolation', '["barbell"]', '["middle back"]', '["lats", "shoulders"]', '["Her elinize bir dambıl alın ve eğimi yaklaşık 30 derece olarak ayarlanmış bir incline bench üzerine yüzüstü uzanın.", "Kolların yere doğru bakacak şekilde, tamamen uzanmış olarak yanlarınızda sarkmasına izin verin.", "Elleriniz pronasyon (avuç içleri aşağı) tutuşta olana kadar bileklerinizi çevirin.", "Şimdi dirseklerinizi dışa doğru açın. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken dambılları sanki ters bench press yapıyormuşsunuz gibi yukarı çekmeye başlayın. Bunu, ön kollarınızı sarkık bırakırken dirseklerinizi bükerek ve üst kollarınızı yukarı kaldırarak yapacaksınız. Üst kollar sırtınızla aynı seviyeye gelene kadar bu harekete devam edin. İpucu: Dirsekler yana doğru açılacak ve hareketin üst noktasında üst kollarınız ve gövdeniz \"T\" harfini oluşturmalıdır. Kasılmayı üstte bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Incline_Bench_Pull/0.jpg", "Incline_Bench_Pull/1.jpg"]', 360.0, 'Incline Bench Pull', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('659a38d9-ed27-58eb-b76c-2ec4cda21e3e', 'free-exercise-db', 'Incline_Cable_Chest_Press', 'Incline Göğüs Press (Kablo)', 'push', 'beginner', 'compound', '["cable"]', '["chest"]', '["shoulders", "triceps"]', '["Ağırlığı uygun bir miktara ayarlayın ve oturarak tutacakları kavrayın. Üst kollarınız vücudunuzla yaklaşık 45 derece açı yapmalı, başınız ve göğsünüz yukarıda olmalıdır. Dirsekler yaklaşık 90 derece bükülü olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseklerinizi açarak ve tutacakları tam önünüzde birbirine doğru iterek harekete başlayın. Hareketi yaparken kürek kemiklerinizi geriye çekili tutun.", "Tam açılma noktasında duraklayın ve kablolardaki gerginliği koruyarak başlangıç pozisyonuna dönün."]', 'strength', '["Incline_Cable_Chest_Press/0.jpg", "Incline_Cable_Chest_Press/1.jpg"]', 360.0, 'Incline Cable Chest Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ba43ee92-7ac4-50a5-87aa-d52a4cfa0124', 'free-exercise-db', 'Incline_Cable_Flye', 'Incline Fly (Kablo)', 'push', 'intermediate', 'isolation', '["cable"]', '["chest"]', '["shoulders"]', '["Başlangıç pozisyonuna geçmek için makaraları zemin seviyesine (makinede gövdenizin altında kalan mümkün olan en alçak seviye) ayarlayın.", "45 derece ayarlanmış bir incline bench''i makaraların arasına yerleştirin, her birinde bir ağırlık seçin ve her elinizle bir makarayı kavrayın.", "Her elinizde bir tutamak varken incline bench''e uzanın ve ellerinizi kollarınız uzatılmış halde yüzünüzün önünde birleştirin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Biceps tendonunda stresi önlemek için dirseklerinizi hafifçe bükerek, göğsünüzde bir esneme hissedene kadar kollarınızı iki yana geniş bir yay çizerek indirin. Hareketin bu kısmında nefes alın. İpucu: Hareket boyunca kolların sabit kalması gerektiğini unutmayın. Hareket sadece omuz ekleminde gerçekleşmelidir.", "Göğüs kaslarınızı sıkarak ve nefes vererek kollarınızı başlangıç pozisyonuna geri getirin. Kasılmış pozisyonda bir saniye bekleyin. İpucu: Ağırlıkları indirirken kullandığınız hareket yayının aynısını kullandığınızdan emin olun.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Incline_Cable_Flye/0.jpg", "Incline_Cable_Flye/1.jpg"]', 360.0, 'Incline Cable Flye', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5e92c85b-fd8a-5114-adad-045405179c2f', 'free-exercise-db', 'Incline_Dumbbell_Bench_With_Palms_Facing_In', 'Incline Press (Dambıl, Nötr Tutuş)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders", "triceps"]', '["Her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde bir incline bench''e uzanın. Avuç içleriniz birbirine bakacaktır.", "Dambılları yukarı kaldırmak için uyluklarınızdan destek alarak, dambılları omuz genişliğinde tutabilmeniz için bir seferde bir kolla kaldırın (clean).", "Omuz genişliğine geldiğinizde avuç içlerinizi nötr tutuşta (avuç içleri birbirine bakacak şekilde) tutun. Dirseklerinizi dışarı açık, üst kollarınızı omuzlarla aynı hizada (gövdeye dik) ve dirseklerinizi üst kol ile ön kol arasında 90 derecelik açı oluşturacak şekilde bükülü tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes alırken ağırlıkları yavaşça yanınıza doğru indirin. Dambıllar üzerinde her zaman tam kontrolü koruyun.", "Nefes verirken göğüs kaslarınızı kullanarak dambılları yukarı itin. Kasılmış pozisyonda kollarınızı kilitleyin, bir saniye bekleyin ve ardından yavaşça inmeye başlayın. İpucu: Aşağı inmek, yukarı çıkmaktan en az iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde dambılları uyluklarınıza geri koyun ve ardından yere bırakın. Bu, dambılları bırakmanın en güvenli yoludur."]', 'strength', '["Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg", "Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg"]', 360.0, 'Incline Dumbbell Bench With Palms Facing In', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a294f59c-5b33-5450-9b7a-8ca35e795d22', 'free-exercise-db', 'Incline_Dumbbell_Curl', 'Incline Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her elinizde kollarınız uzanmış şekilde birer dambıl tutarak eğimli bir sehpaya yaslanarak oturun. Dirseklerinizi gövdenize yakın tutun ve avuç içlerinizi öne bakana kadar döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolunuzu sabit tutarken nefes verip biceps''inizi kasarak ağırlıkları öne doğru kıvırın. Yalnızca ön kollar hareket etmelidir. Biceps''leriniz tamamen kasılana ve dambıllar omuz seviyesine gelene kadar hareketi sürdürün. Kasılmış pozisyonu bir saniye tutun.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Incline_Dumbbell_Curl/0.jpg", "Incline_Dumbbell_Curl/1.jpg"]', 360.0, 'Incline Dumbbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7c19e79c-1e66-531a-8379-cd845b2df597', 'free-exercise-db', 'Incline_Dumbbell_Flyes', 'Incline Fly (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders"]', '["Her elinizde bir dambıl tutun ve eğimi 30 dereceyi geçmeyecek şekilde ayarlanmış bir incline sehpaya uzanın.", "Kollarınızı dirsekleriniz hafif bükülü şekilde tepenize doğru uzatın.", "Şimdi bileklerinizi avuç içleriniz size bakacak şekilde döndürün. İpucu: Serçe parmaklarınız birbirinin yanında olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken kollarınızı uzamış halde tutup bileklerinizi avuç içleri birbirine bakana kadar döndürerek kollarınızı yavaşça yanlara doğru indirmeye başlayın. İpucu: Hareketin sonunda kollarınız yanınızda ve avuç içleriniz tavana bakıyor olacaktır.", "Nefes verirken hareketi tersine çevirerek ve ellerinizi serçe parmaklarınız tekrar birbirinin yanında olacak şekilde döndürerek dambılları başlangıç pozisyonuna geri getirmeye başlayın. İpucu: Hareketin yalnızca omuz ekleminde ve bilekte gerçekleşeceğini unutmayın. Dirsek ekleminde hareket olmaz.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Incline_Dumbbell_Flyes/0.jpg", "Incline_Dumbbell_Flyes/1.jpg"]', 360.0, 'Incline Dumbbell Flyes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('41edc940-d555-51b8-b6a8-657622cc6310', 'free-exercise-db', 'Incline_Dumbbell_Flyes_-_With_A_Twist', 'Incline Fly (Dambıl, Rotasyonlu)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders"]', '["Her elinizde bir dambıl tutun ve eğimi 30 dereceyi geçmeyecek şekilde ayarlanmış eğimli bir bankta uzanın.", "Kollarınızı dirsekleriniz hafif bükülü şekilde üzerinizde uzatın.", "Şimdi bileklerinizi avuç içleriniz size bakacak şekilde çevirin. İpucu: Serçe parmaklar yan yana olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken, kollarınızı uzatılmış halde tutarak ve avuç içleri birbirine bakana kadar bileklerinizi döndürerek kolları yavaşça yanlara indirmeye başlayın. İpucu: Hareketin sonunda kollar yanlarınızda, avuç içleri tavana bakar durumda olacaktır.", "Nefes verirken hareketi tersine çevirerek ve ellerinizi serçe parmaklar tekrar yan yana gelecek şekilde döndürerek dambılları başlangıç pozisyonuna getirmeye başlayın. İpucu: Hareketin yalnızca omuz eklemi ve bilekte gerçekleştiğini unutmayın. Dirsek ekleminde hareket olmaz.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg", "Incline_Dumbbell_Flyes_-_With_A_Twist/1.jpg"]', 360.0, 'Incline Dumbbell Flyes - With A Twist', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('645adb1c-4434-53ef-9f06-3e69abacf38b', 'free-exercise-db', 'Incline_Dumbbell_Press', 'Incline Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders", "triceps"]', '["Her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde incline bench üzerine yaslanın. Avuç içleriniz birbirine bakacak.", "Ardından, dambılları yukarı itmeye yardımcı olması için uyluklarınızı kullanarak dambılları omuz genişliğinde tutabilmeniz için birer birer kaldırın.", "Dambılları omuz genişliğinde kaldırdıktan sonra, avuç içleriniz sizden uzağa bakacak şekilde bileklerinizi öne doğru döndürün. Bu sizin başlangıç pozisyonunuz olacak.", "Dambıllar üzerinde her zaman tam kontrolü sürdürdüğünüzden emin olun. Ardından nefes verin ve dambılları göğsünüzle yukarı itin.", "Üstte kollarınızı kilitleyin, bir saniye bekleyin ve ardından ağırlığı yavaşça indirmeye başlayın. İpucu: İdeal olarak ağırlıkları indirmek, kaldırmaktan yaklaşık iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde dambılları önce uyluklarınızın üzerine, ardından yere koyun. Bu, dambılları bırakmanın en güvenli yoludur."]', 'strength', '["Incline_Dumbbell_Press/0.jpg", "Incline_Dumbbell_Press/1.jpg"]', 360.0, 'Incline Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9498c4b9-03c5-565b-aa94-2f77118e45fe', 'free-exercise-db', 'Incline_Hammer_Curls', 'Incline Hammer Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her elinizde birer dambıl ile eğimli bir sehpaya oturun. Ayaklarınız bitişik halde sırtınızı sehpaya sıkıca yaslayın. Dambılların nötr tutuşla yanınızda düz aşağı sarkmasına izin verin. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolu sabit tutmaya çalışarak dirsekten bükülerek hareketi başlatın.", "Hareketin tepesine kadar devam edin ve bekleyin, ardından yavaşça başlangıç pozisyonuna dönün."]', 'strength', '["Incline_Hammer_Curls/0.jpg", "Incline_Hammer_Curls/1.jpg"]', 360.0, 'Incline Hammer Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d68776de-92e6-5581-9ad2-5f1f5c320158', 'free-exercise-db', 'Incline_Inner_Biceps_Curl', 'Incline Inner Biceps Curl (Dambıl)', NULL, 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her elinizde bir dambıl tutun ve incline bench''e yaslanın.", "Dambıllar kol boyu kadar yanlarınızda sarkıyor ve avuç içleriniz dışa bakıyor olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes verirken ön kollarınızı yan deltoidlerinizle aynı hizada tutarak ağırlığı dışa ve yukarı doğru curl yapın. Dambıllar omuz yüksekliğine gelene ve deltoidlerinizin yanında olana kadar curl hareketine devam edin. İpucu: Hareketin sonu çift biceps pozuna benzemelidir.", "Hareketin üst noktasında bir saniyelik kasılmadan sonra nefes almaya başlayın ve ağırlıkları kaldırırken izlediğiniz yolun aynısıyla yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Incline_Inner_Biceps_Curl/0.jpg", "Incline_Inner_Biceps_Curl/1.jpg"]', 360.0, 'Incline Inner Biceps Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4519294a-b026-544e-9b3f-229d886136e1', 'free-exercise-db', 'Incline_Push-Up', 'Incline Şınav', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Bir sehpaya veya sağlam yükseltilmiş bir platforma dönük şekilde durun. Ellerinizi sehpanın veya platformun kenarına, omuz genişliğinden biraz daha geniş yerleştirin.", "Ön ayaklarınızı sehpadan veya platformdan geriye konumlandırın; kollarınız ve vücudunuz düz olmalıdır. Kollar vücuda dik olmalıdır. Vücudunuzu düz tutarak kollarınızı bükerek göğsünüzü kutunun veya platformun kenarına indirin.", "Kollarınız açılana kadar vücudunuzu yukarı itin. Tekrarlayın."]', 'strength', '["Incline_Push-Up/0.jpg", "Incline_Push-Up/1.jpg"]', 360.0, 'Incline Push-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a57b9a08-6e10-52b0-8dc4-f0c074e96367', 'free-exercise-db', 'Incline_Push-Up_Close-Grip', 'Incline Şınav (Dar Tutuş)', 'push', 'beginner', 'compound', '["body only"]', '["triceps"]', '["chest", "shoulders"]', '["Uygun bir yükseklikte bir Smith makinesi barına veya sağlam bir yükseltilmiş platforma dönük şekilde durun.", "Ellerinizi bar üzerinde yan yana yerleştirin.", "Ayaklarınızı bardan geriye doğru konumlandırın; kollarınız ve vücudunuz düz olsun. Bu sizin başlangıç pozisyonunuz olacak.", "Vücudunuzu düz tutarak, kollarınızı bükerek göğsünüzü bara doğru indirin.", "Dirseklerinizi açarak, kendinizi geri iterek başlangıç pozisyonuna dönün."]', 'strength', '["Incline_Push-Up_Close-Grip/0.jpg", "Incline_Push-Up_Close-Grip/1.jpg"]', 360.0, 'Incline Push-Up Close-Grip', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4b04305b-1877-5493-9987-32861266805a', 'free-exercise-db', 'Incline_Push-Up_Depth_Jump', 'Incline Şınav Depth Jump', 'push', 'beginner', 'compound', '["other"]', '["chest"]', '["shoulders", "triceps"]', '["Bu çalışma için yaklaşık 12 inç (30 cm) yüksekliğinde bir kutuya ve iki kalın minderi veya aerobik stepine ihtiyacınız olacak.", "Stepleri omuzlarınızın hemen dışına yerleştirin ve ayaklarınızı kutunun üzerine koyarak incline şınav pozisyonuna geçin; elleriniz stepin hemen içinde olsun. Bu sizin başlangıç pozisyonunuzdur.", "Vücudunuzu indirmek için dirseklerinizi bükerek başlayın, ardından pozisyonu hızla tersine çevirerek vücudunuzu yerden itin. Yerden ayrılırken ellerinizi stepin üzerine alın ve darbeyi emmek için dirseklerinizi bükün.", "Başlangıç pozisyonuna dönmek için hareketi tekrarlayın."]', 'plyometrics', '["Incline_Push-Up_Depth_Jump/0.jpg", "Incline_Push-Up_Depth_Jump/1.jpg"]', 480.0, 'Incline Push-Up Depth Jump', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('90201cf4-de7e-565b-9637-c4eebad906e1', 'free-exercise-db', 'Incline_Push-Up_Medium', 'Incline Şınav (Orta Tutuş)', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Bir Smith makinesi barına ya da uygun yükseklikteki sağlam bir yükseltilmiş platforma dönük şekilde ayakta durun.", "Ellerinizi barın üzerine, yaklaşık omuz genişliğinde açık olacak şekilde yerleştirin.", "Ayaklarınızı bardan geriye konumlandırın; kollarınız ve vücudunuz düz olsun. Bu sizin başlangıç pozisyonunuzdur.", "Vücudunuzu düz tutarak kollarınızı bükerek göğsünüzü bara doğru indirin.", "Dirseklerinizi açarak kendinizi yukarı iterek başlangıç pozisyonuna dönün."]', 'strength', '["Incline_Push-Up_Medium/0.jpg", "Incline_Push-Up_Medium/1.jpg"]', 360.0, 'Incline Push-Up Medium', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('709cfbb3-5f8c-5515-8bde-b7b17de343e6', 'free-exercise-db', 'Incline_Push-Up_Reverse_Grip', 'Incline Şınav (Ters Tutuş)', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Bir Smith makinesi barına veya uygun yükseklikteki sağlam yükseltilmiş bir platforma dönük durun.", "Ellerinizi avuç içleri yukarı bakacak şekilde, yaklaşık omuz genişliğinde açık olarak bara yerleştirin.", "Ayaklarınızı bardan geriye doğru, kollarınız ve vücudunuz düz olacak şekilde konumlandırın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Vücudunuzu düz tutarak kollarınızı bükerek göğsünüzü bara doğru indirin.", "Dirseklerinizi açarak, kendinizi yukarı iterek başlangıç pozisyonuna dönün."]', 'strength', '["Incline_Push-Up_Reverse_Grip/0.jpg", "Incline_Push-Up_Reverse_Grip/1.jpg"]', 360.0, 'Incline Push-Up Reverse Grip', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1b3d400a-7fca-596d-8593-24e9e08561ba', 'free-exercise-db', 'Incline_Push-Up_Wide', 'Incline Şınav (Geniş Tutuş)', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Smith makinesi barına veya uygun yükseklikte sağlam yükseltilmiş bir platforma dönük şekilde durun.", "Ellerinizi omuz genişliğinden daha geniş şekilde bara yerleştirin.", "Ayaklarınızı bardan geriye konumlandırın; kollarınız ve vücudunuz düz olmalıdır. Kollarınız vücuda dik olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Vücudunuzu düz tutarak kollarınızı bükerek göğsünüzü bara doğru indirin.", "Dirseklerinizi açıp kendinizi yukarı iterek başlangıç pozisyonuna dönün."]', 'strength', '["Incline_Push-Up_Wide/0.jpg", "Incline_Push-Up_Wide/1.jpg"]', 360.0, 'Incline Push-Up Wide', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e1a1ebaa-cf01-5675-a8ab-e644028d5144', 'free-exercise-db', 'Intermediate_Groin_Stretch', 'Kasık Esnetme (Orta Seviye)', 'static', 'intermediate', 'isolation', '["other"]', '["hamstrings"]', '[]', '["Bacaklarınız uzanmış şekilde sırtüstü uzanın. Bir kemer, ip veya bandı ayaklarınızdan birinin etrafına geçirin ve o bacağı yana doğru olabildiğince açın. Bu sizin başlangıç pozisyonunuz olacak.", "Kasık ve arka bacak kaslarınızda gerginlik oluşturmak için kemeri nazikçe çekin. 10-20 saniye bekleyin ve diğer tarafta tekrarlayın."]', 'stretching', '["Intermediate_Groin_Stretch/0.jpg", "Intermediate_Groin_Stretch/1.jpg"]', 150.0, 'Intermediate Groin Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d98c3277-38b3-5145-88e2-3e5cffa79937', 'free-exercise-db', 'Intermediate_Hip_Flexor_and_Quad_Stretch', 'Orta Seviye Kalça Fleksörü ve Ön Bacak Esnetme', 'static', 'intermediate', 'compound', '["other"]', '["quadriceps"]', '[]', '["Bir ip, kemer ya da bant ayaklarınızdan birine dolanmış şekilde yüzüstü yere uzanın.", "Esnetilecek bacağın dizini bükün ve kalçasını açın; iki elinizle kemeri çekin. Dizinizin ve kalçanızın yerden kalkması, kalça fleksörlerinde ve ön bacak kaslarında gerilim yaratmalıdır. Esnetmeyi 10-20 saniye tutun ve diğer bacakla tekrarlayın."]', 'stretching', '["Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg", "Intermediate_Hip_Flexor_and_Quad_Stretch/1.jpg"]', 150.0, 'Intermediate Hip Flexor and Quad Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8efb2ab5-88a1-5b4e-a5db-07dbd4156224', 'free-exercise-db', 'Internal_Rotation_with_Band', 'İç Rotasyon (Direnç Bandı)', NULL, 'beginner', 'isolation', '["bands"]', '["shoulders"]', '[]', '["Bandı bir direğe dolayın. Bant dirseğinizle aynı yükseklikte olmalıdır. Sağ yanınız banda dönük olacak şekilde, birkaç adım uzakta durun.", "Bandın ucunu sağ elinizle kavrayın ve dirseğinizi gövdenize sıkıca bastırın. Dirseğinizi sıkıca yerinde tutmak için dirseğinizle bir ped veya foam roller sıkıştırmanızı öneririz.", "Üst kolunuz yerindeyken, dirseğiniz 90 derece bükülü ve eliniz gövdenizden uzağa uzanmış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi yerinde tutarak kolunuzu forehand hareketiyle döndürerek hareketi gerçekleştirin.", "Yapabildiğiniz kadar devam edin, bekleyin ve ardından başlangıç pozisyonuna dönün."]', 'strength', '["Internal_Rotation_with_Band/0.jpg", "Internal_Rotation_with_Band/1.jpg"]', 360.0, 'Internal Rotation with Band', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c9d42521-9c27-5650-84be-bfd79327c9eb', 'free-exercise-db', 'Inverted_Row', 'Inverted Row (Ters Row)', 'pull', 'beginner', 'compound', '[]', '["middle back"]', '["lats"]', '["Bir barı rafta yaklaşık bel yüksekliğine ayarlayın. Smith makinesini de kullanabilirsiniz.", "Barı omuz genişliğinden geniş bir tutuşla kavrayın ve barın altında asılı kalacak şekilde konumlanın. Vücudunuz düz, topuklarınız yerde ve kollarınız tamamen uzamış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi bükerek ve göğsünüzü bara doğru çekerek başlayın. Hareketi yaparken kürek kemiklerinizi geriye çekin.", "Hareketin üst noktasında duraklayın ve başlangıç pozisyonuna dönün.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Inverted_Row/0.jpg", "Inverted_Row/1.jpg"]', 360.0, 'Inverted Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('239f7182-ef92-5105-90c5-9d50400bd1c6', 'free-exercise-db', 'Inverted_Row_with_Straps', 'Inverted Row (Askı ile)', 'pull', 'beginner', 'compound', '["other"]', '["middle back"]', '["biceps", "lats"]', '["Bir rafa veya başka sabit bir nesneye bir halat ya da süspansiyon askıları asın. Uçlarını kavrayın ve halatlardan asılı şekilde sırtüstü konumlanın. Vücudunuz düz, topuklarınız yerde ve kollarınız tamamen uzanmış olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi bükerek göğsünüzü ellerinize doğru çekmeye başlayın. Hareketi yaparken kürek kemiklerinizi geriye çekin.", "Hareketin en üst noktasında bekleyin ve kendinizi başlangıç pozisyonuna geri indirin.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Inverted_Row_with_Straps/0.jpg", "Inverted_Row_with_Straps/1.jpg"]', 360.0, 'Inverted Row with Straps', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('84eb992e-fd7f-58dd-96a8-595defa34847', 'free-exercise-db', 'Iron_Cross', 'Iron Cross', 'push', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["chest", "glutes", "hamstrings", "lower back", "quadriceps", "traps"]', '[]', 'strength', '["Iron_Cross/0.jpg", "Iron_Cross/1.jpg"]', 360.0, 'Iron Cross', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2590b3a0-e186-50b3-b265-d964b7dda7a4', 'free-exercise-db', 'Iron_Crosses_stretch', 'Iron Cross Esnetme', 'pull', 'intermediate', 'compound', '[]', '["quadriceps"]', '[]', '["Kollarınız yanlara uzanmış ve avuç içleriniz yere bastırılmış şekilde yüzüstü yere uzanın. Bu sizin başlangıç pozisyonunuz olacak.", "Başlamak için bir dizinizi bükün ve o bacağı vücudunuzun arkasından karşıya doğru getirerek karşı elin yakınında yere değdirmeye çalışın.", "Bacağı hemen başlangıç pozisyonuna döndürün ve diğer bacakla hızlıca tekrarlayın. 10-20 tekrar boyunca dönüşümlü devam edin."]', 'stretching', '["Iron_Crosses_stretch/0.jpg", "Iron_Crosses_stretch/1.jpg"]', 150.0, 'Iron Crosses (stretch)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('11182f11-5706-504d-8e16-57b4cced66ae', 'free-exercise-db', 'Isometric_Chest_Squeezes', 'İzometrik Göğüs Sıkma', 'static', 'beginner', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Oturarak veya ayakta, kollarınızı 90 derece bükün ve avuç içlerinizi göğsünüzün önünde birleştirin. İpucu: Elleriniz açık, avuç içleri birbirine bakacak ve parmaklar öne dönük (gövdenize dik) olmalıdır.", "Göğsünüzü kasarken iki elinizi birbirine doğru bastırın. Yavaş bir gerginlikle başlayın ve yavaşça artırın. Bu kasılmayı yaparken normal nefes almaya devam edin.", "Önerilen saniye sayısı kadar tutun.", "Şimdi gerginliği yavaşça bırakın.", "Önerilen süre kadar dinlenin ve tekrarlayın."]', 'plyometrics', '["Isometric_Chest_Squeezes/0.jpg", "Isometric_Chest_Squeezes/1.jpg"]', 480.0, 'Isometric Chest Squeezes', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fdbc20a6-265b-5a0b-b73b-e909d27d7d8d', 'free-exercise-db', 'Isometric_Neck_Exercise_-_Front_And_Back', 'İzometrik Boyun Egzersizi (Ön ve Arka)', 'static', 'beginner', 'isolation', '["body only"]', '["neck"]', '[]', '["Başınız ve boynunuz nötr pozisyondayken (başınız dik ve karşıya bakacak şekilde normal pozisyon) iki elinizi başınızın ön tarafına yerleştirin.", "Şimdi boyun kaslarınızı kasarken nazikçe öne doğru itin, ancak başınızın hareket etmesine direnin. Yavaş bir gerilimle başlayın ve yavaşça artırın. Bu kasılmayı yaparken normal şekilde nefes almaya devam edin.", "Önerilen saniye boyunca tutun.", "Şimdi gerilimi yavaşça bırakın.", "Önerilen süre kadar dinlenin ve ellerinizi başınızın arka tarafına yerleştirerek tekrarlayın."]', 'strength', '["Isometric_Neck_Exercise_-_Front_And_Back/0.jpg", "Isometric_Neck_Exercise_-_Front_And_Back/1.jpg"]', 360.0, 'Isometric Neck Exercise - Front And Back', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0791d7d0-3dab-5f01-b68a-e05fe8873371', 'free-exercise-db', 'Isometric_Neck_Exercise_-_Sides', 'İzometrik Boyun Egzersizi (Yan)', 'static', 'beginner', 'isolation', '["body only"]', '["neck"]', '[]', '["Başınız ve boynunuz nötr pozisyondayken (başınız dik ve ileri bakarken normal pozisyon) sol elinizi başınızın sol tarafına yerleştirin.", "Şimdi sol boyun kaslarınızı kasarken sola doğru hafifçe itin, ancak başınızın herhangi bir hareket etmesine direnin. Yavaş bir gerilimle başlayın ve yavaşça artırın. Bu kasılmayı yaparken normal nefes almaya devam edin.", "Önerilen saniye sayısı kadar bekleyin.", "Şimdi gerilimi yavaşça bırakın.", "Önerilen süre kadar dinlenin ve sağ elinizi başınızın sağ tarafına yerleştirerek tekrarlayın."]', 'strength', '["Isometric_Neck_Exercise_-_Sides/0.jpg", "Isometric_Neck_Exercise_-_Sides/1.jpg"]', 360.0, 'Isometric Neck Exercise - Sides', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('790603a2-7357-5498-bd2a-395c603d5782', 'free-exercise-db', 'Isometric_Wipers', 'İzometrik Wiper (Şınav Pozisyonunda)', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Şınav pozisyonuna geçin; ağırlığınızı ellerinizin ve ayak parmaklarınızın üzerinde taşıyın ve vücudunuzu düz tutun. Elleriniz omuz genişliğinin hemen dışında olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Vücut ağırlığınızı olabildiğince bir tarafa kaydırarak başlayın ve vücudunuzu indirirken o taraftaki dirseğin bükülmesine izin verin.", "Bükülü kolu açarak hareketi tersine çevirin, kendinizi yukarı itin ve ardından diğer tarafa doğru inin.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Isometric_Wipers/0.jpg", "Isometric_Wipers/1.jpg"]', 360.0, 'Isometric Wipers', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('609e88af-49f8-5299-8532-42906012712e', 'free-exercise-db', 'JM_Press', 'JM Press', 'push', 'beginner', 'compound', '["barbell"]', '["triceps"]', '["chest", "shoulders"]', '["Egzersize dar tutuşlu bench press''te yaptığınız gibi başlayın. Düz bir bench üzerine uzanıp halteri kollarınız uzanmış (tamamen açık) ve dirsekleriniz içeride olacak şekilde kol boyu mesafede tutacaksınız. Ancak kolları gövdeye dik tutmak yerine, halterin doğrudan üst göğsünüzün üzerinde olduğundan emin olun. Bu sizin başlangıç pozisyonunuz olacak.", "Tamamen uzanmış pozisyondan başlayarak halteri sanki yatarak triceps extension yapıyormuşsunuz gibi indirin. Bu hareketi yaparken nefes alın. Yarı noktaya ulaştığınızda, üst kollarınızı gövdeye dik olana kadar bacaklarınıza doğru hareket ettirerek halterin yaklaşık 2,5 cm geriye yuvarlanmasına izin verin. İpucu: Üst kolları öne getirirken dirseklerdeki bükülmeyi sabit tutun.", "Nefes verirken, triceps''i kullanarak dar tutuşlu bench press yapar gibi halteri tekrar yukarı itin.", "Şimdi başlangıç pozisyonuna dönün ve baştan başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["JM_Press/0.jpg", "JM_Press/1.jpg"]', 360.0, 'JM Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('13f09ec4-10e9-5fea-b19c-7673bdf09efa', 'free-exercise-db', 'Jackknife_Sit-Up', 'Jackknife Mekik', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Yere (veya egzersiz matına) sırtüstü düz uzanın; kollarınız başınızın arkasında düz bir şekilde uzatılmış ve bacaklarınız da uzatılmış olsun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken belinizden bükülün ve aynı anda bacaklarınızı ve kollarınızı kaldırarak bir çakı (jackknife) pozisyonunda buluşturun. İpucu: Bacaklar uzatılmış ve yerden yaklaşık 35-45 derecelik bir açıyla kaldırılmış olmalı, kollar ise uzatılmış ve bacaklarınıza paralel olmalıdır. Üst gövde yerden kalkmış olmalıdır.", "Nefes alırken kollarınızı ve bacaklarınızı başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Jackknife_Sit-Up/0.jpg", "Jackknife_Sit-Up/1.jpg"]', 360.0, 'Jackknife Sit-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c433e181-47d8-5b11-a494-3459252219dd', 'free-exercise-db', 'Janda_Sit-Up', 'Janda Mekik', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Vücudunuzu yerde temel mekik pozisyonuna yerleştirin; dizler doksan derece bükülü, ayaklar yere düz ve kollar göğsünüzün üzerinde çapraz veya yanlarda olsun. Bu sizin başlangıç pozisyonunuzdur.", "Kalçanızı ve arka bacaklarınızı güçlü şekilde sıkarken ciğerlerinizi havayla doldurun ve yavaş bir yükselişle (üç ila altı saniyelik sayımla) yavaşça nefes verin. İpucu: Kalça ve arka bacak kaslarının sıkılması önemlidir, çünkü bu, kalça fleksörlerinin reciprocal inhibition (karşılıklı inhibisyon) adı verilen bir süreçle devre dışı kalmasına neden olur; bu da temelde kasılan kasların karşıtı olan kasların gevşemesi anlamına gelir.", "Nefes alırken kontrollü bir şekilde yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Janda_Sit-Up/0.jpg", "Janda_Sit-Up/1.jpg"]', 360.0, 'Janda Sit-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('08d98d02-b024-58b4-9ae9-bf2cc82e8308', 'free-exercise-db', 'Jefferson_Squats', 'Jefferson Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back", "traps"]', '["Bir halteri yere koyun.", "Barın uzunlamasına ortasında durun.", "Dizlerinizden bükülerek ve sırtınızı düz tutarak eğilin ve barın ön kısmını sağ elinizle kavrayın. Avuç içiniz içe (nötr tutuş) ve sol tarafa bakmalıdır.", "Barın arka kısmını sol elinizle kavrayın. Elinizin avuç içi nötr tutuş hizasında olmalıdır (avuç içleri sağ tarafa bakacak şekilde). İpucu: Tutuşunuzun bar üzerinde eşit olduğundan emin olun. Gövdeniz tam olarak barın ortasında konumlanmalı ve gövdeniz ile sağ eliniz (önde olmalı) arasındaki mesafe, gövdeniz ile sol eliniz (arkada olmalı) arasındaki mesafeyle aynı olmalıdır.", "Şimdi ağırlıkla birlikte dik ayağa kalkın. İpucu: Ayaklarınız omuz genişliğinde ve ayak parmaklarınız hafifçe dışa bakıyor olmalıdır.", "Sırtınızı düz tutarak dizlerinizi bükerek üst uyluklarınız yere paralel olana kadar çömelin. İpucu: Sırtınızı yere olabildiğince dik ve başınızı yukarıda tutun. Ayrıca dizlerinizin ayak parmaklarınızı geçmesine izin vermemeyi unutmayın. Hareketin bu kısmında nefes alın.", "Şimdi ayaklarınızla iterek kendinizi başlangıç pozisyonuna geri sürün. İpucu: Barı kollarınızın uzunluğunda sarkık ve dirseklerinizi hafif bükülü olarak kilitli tutun. Kollar yalnızca kanca görevi görür. Onlarla kaldırma yapmaktan kaçının. Kaldırmayı kollarınızla değil, uyluklarınızla yapın."]', 'strength', '["Jefferson_Squats/0.jpg", "Jefferson_Squats/1.jpg"]', 360.0, 'Jefferson Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9c27b97b-79c2-5465-8f24-550a4cc5e541', 'free-exercise-db', 'Jerk_Balance', 'Jerk Balance (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["glutes", "hamstrings", "quadriceps", "triceps"]', '["Bu çalışma, jerk sırasında kendinizi yeterince alçağa itmeyi öğrenmenize yardımcı olur ve hareket sırasında geriye doğru hareket edenleri düzeltir. Bar jerk pozisyonunda rafta, omuzlar öne dönük, gövde dik ve ayaklar hafifçe ayrık şekilde başlayın.", "Hareketi normal bir jerk gibi başlatın: gövdenizi dik tutarak dizlerinizden çökün ve ağırlığı kollarınızla değil ivmeyle kaldırarak güçlü bir şekilde yukarı itin.", "Arka ayağınızı yerinde tutun ve ağırlığı jerk yaparken vücudunuzu tam split pozisyonuna ileri itmek için onu kullanın. Ağırlık baş üstündeyken ayağa kalkarak toparlanın."]', 'olympic weightlifting', '["Jerk_Balance/0.jpg", "Jerk_Balance/1.jpg"]', 420.0, 'Jerk Balance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('49ce34c3-0fa5-5d55-9a70-837accabe758', 'free-exercise-db', 'Jerk_Dip_Squat', 'Jerk Dip Squat', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["abdominals", "calves"]', '["Bu hareket jerk''in dip (çömelme) kısmını güçlendirir. Bar jerk pozisyonunda rafta, omuzlar önde bir raf oluşturacak şekilde ve bar boğaza hafifçe değerek başlayın. Ayaklar tam kalçaların altında, rahat edeceğiniz kadar dışa dönük olmalıdır.", "Gövdenizi dik tutarak, dizlerinizi bükerek ve kalçanızı geriye hareket ettirmeden dizlerin öne doğru gitmesine izin vererek çömelin (dip). Çömelme aşırı olmamalıdır. Ayaklarınızdan güçlü bir şekilde iterek ağırlığı başlangıç pozisyonuna getirin."]', 'olympic weightlifting', '["Jerk_Dip_Squat/0.jpg", "Jerk_Dip_Squat/1.jpg"]', 420.0, 'Jerk Dip Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c0caac4f-fa49-5379-8890-bdf9a6235e23', 'free-exercise-db', 'Jogging_Treadmill', 'Koşu Bandında Jogging', NULL, 'beginner', NULL, '["machine"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Başlamak için koşu bandına çıkın ve menüden istediğiniz seçeneği belirleyin. Çoğu koşu bandında manuel bir ayar bulunur veya koşmak için bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kalori miktarını tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz. Antrenmanın yoğunluğunu değiştirmek için eğim ayarlanabilir.", "Koşu bantları kolaylık ve kardiyovasküler faydalar sunar ve genellikle dışarıda jogging yapmaktan daha az darbe etkisi yaratır. 68 kg''lık bir kişi 30 dakika jogging yaparak yaklaşık 250 kalori yakarken, koşarak 450 kaloriden fazla yakar. Jogging yaparken doğru duruşu koruyun ve tutamaklardan yalnızca gerektiğinde, örneğin banttan inerken veya kalp atış hızınızı kontrol ederken tutunun."]', 'cardio', '["Jogging_Treadmill/0.jpg", "Jogging_Treadmill/1.jpg"]', 600.0, 'Jogging, Treadmill', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7ecb62dc-c639-5779-a73f-3bd7ca755310', 'free-exercise-db', 'Keg_Load', 'Keg Load (Fıçı Yükleme)', 'pull', 'intermediate', 'compound', '["other"]', '["lower back"]', '["abdominals", "biceps", "calves", "forearms", "glutes", "hamstrings", "middle back", "quadriceps", "shoulders", "traps"]', '["Fıçıları yüklemek için istenen sayıdaki fıçıyı yükleme platformundan genellikle 30-50 fit (9-15 metre) uzağa yerleştirin.", "İlk fıçının yakın kulpunu tutarak başlayın, fıçıyı yan yatırarak fıçının tabanının karşı kenarını kavrayın. Fıçıyı göğsünüze kadar kaldırın.", "Fıçıyı ne kadar yükseğe koyabilirseniz platforma o kadar hızlı ilerleyebilirsiniz. Omuza almaya genellikle izin verilmez. Fıçıyı sıkıca tuttuğunuzdan emin olun. Platforma olabildiğince hızlı ilerleyin ve olabildiğince yükseğe çıkarmak için kalçanızı, dizlerinizi ve ayak bileklerinizi açarak fıçıyı yükleyin.", "Bir sonraki fıçıyı almak için başlangıç pozisyonuna dönün ve yarışma tamamlanana kadar tekrarlayın."]', 'strongman', '["Keg_Load/0.jpg", "Keg_Load/1.jpg"]', 480.0, 'Keg Load', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e40b5f41-7237-563c-a8ef-eba0207e33d7', 'free-exercise-db', 'Kettlebell_Arnold_Press', 'Arnold Press (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["triceps"]', '["Bir kettlebell''i omzunuza clean ile alın. Bacaklarınızı ve kalçanızı açarak kettlebell''i omzunuza doğru kaldırıp omzunuza getirin. Avuç içi içe bakmalı.", "Düz ileri bakarak kettlebell''i öne ve baş üstüne doğru itin; hareketin üst noktasında avuç içiniz ileri bakacak şekilde bileğinizi döndürün.", "Kettlebell''i avuç içi içe bakacak şekilde başlangıç pozisyonuna geri getirin."]', 'strength', '["Kettlebell_Arnold_Press/0.jpg", "Kettlebell_Arnold_Press/1.jpg"]', 360.0, 'Kettlebell Arnold Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('219ea2fa-47c9-54df-a031-c7884afac33c', 'free-exercise-db', 'Kettlebell_Dead_Clean', 'Dead Clean (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["calves", "glutes", "lower back", "quadriceps", "traps"]', '["Kettlebell''i ayaklarınızın arasına yerleştirin. Başlangıç pozisyonunu almak için kalçanızı geriye itin ve düz ileri bakın.", "Kettlebell''i omzunuza doğru çekin (clean). Kettlebell''i omzunuza doğru kaldırırken bacaklarınızı ve kalçanızı açın. Bunu yaparken bilek dönmelidir.", "Sırtınızı düz ve kalçanızı geride tutarak arka bacak kaslarınızı gergin tutup kettlebell''i indirin."]', 'strength', '["Kettlebell_Dead_Clean/0.jpg", "Kettlebell_Dead_Clean/1.jpg"]', 360.0, 'Kettlebell Dead Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eb193839-0737-547c-8b4a-04de3e1c53dc', 'free-exercise-db', 'Kettlebell_Figure_8', 'Kettlebell Sekiz Çizme (Figure 8)', 'pull', 'intermediate', NULL, '["kettlebells"]', '["abdominals"]', '["hamstrings", "shoulders"]', '["Bir kettlebell''i bacaklarınızın arasına koyun ve omuz genişliğinden daha geniş bir duruş alın. Kalçanızı geriye iterek ve sırtınızı düz tutarak öne eğilin.", "Kettlebell''i alın ve bacaklarınızın arasından diğer elinize geçirin. Karşılayan el, bacakların arkasından uzanmalıdır. Birkaç tekrar boyunca ileri geri devam edin."]', 'strength', '["Kettlebell_Figure_8/0.jpg", "Kettlebell_Figure_8/1.jpg"]', 360.0, 'Kettlebell Figure 8', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c4dc4255-58ed-53e5-a71d-cfe3299a3bdc', 'free-exercise-db', 'Kettlebell_Halo', 'Halo (Kettlebell)', NULL, 'beginner', 'compound', '["kettlebells"]', '["shoulders"]', '["traps", "middle back", "abdominals", "triceps"]', '["Ayaklarınız kalça genişliğinde dik durun. Bir kettlebell''i ters çevirerek, kettlebell''in gövdesi ellerinizin üzerinde ve göğsünüze yakın olacak şekilde kulplarından tutun. Karın kaslarınızı sıkın ve kaburga kafesinizin aşağıda kalması için kalça kaslarınızı sıkın. Bu sizin başlangıç pozisyonunuz olacak.", "Dirseklerinizi başınıza yakın tutarak kettlebell''i bir kulağınızın yanından yukarı ve başınızın arkasından dolaştırın.", "Daireyi karşı kulağınızın yanından devam ettirin ve göğsünüzün önündeki başlangıç pozisyonuna geri indirin; kettlebell''in hareket boyunca vücudunuza yakın geçmesine izin verin.", "Belirlenen sayıda daireyi bir yönde tamamlayın, ardından aynı sayıyı ters yönde tekrarlayın.", "Yavaş hareket edin ve başınızı, kalçanızı ve alt sırtınızı sabit tutun. Alt sırtınız kavis yapıyorsa veya kettlebell başınızdan uzaklaşıyorsa daha hafif bir ağırlık kullanın."]', 'strength', '[]', 360.0, 'Kettlebell Halo', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d2660913-6bf3-5df7-8c2a-a313fd89c795', 'free-exercise-db', 'Kettlebell_Halo_With_Overhead_Extension', 'Halo ve Overhead Extension (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders", "triceps"]', '["traps", "middle back", "abdominals"]', '["Ayaklarınız kalça genişliğinde açık dik durun. Bir kettlebell''i kulplarından ters tutun; gövde elleriniz üzerinde ve göğsünüze yakın olsun. Karın kaslarınızı sıkın ve kaburga kafesinizin aşağıda kalması için kalça kaslarınızı kasın. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi başınıza yakın tutarak kettlebell''i bir kulağınızın yanından yukarı ve çevresinden geçirerek başınızın arkasına kadar getirin. Burada bekleyin.", "Bu pozisyondan dirseklerinizi açarak kettlebell''i kollarınız düzelene kadar yukarı ve başınızın üzerine doğru itin; üst kollarınızı başınızın yanında tutun.", "Dirseklerinizi bükerek kettlebell''i kontrollü bir şekilde başınızın arkasındaki bekleme pozisyonuna geri indirin.", "Bir tekrarı tamamlamak için daireyi karşı kulağın yanından geçirerek devam ettirin ve göğsünüzün önündeki başlangıç pozisyonuna geri getirin.", "Her tekrarda dairenin yönünü değiştirin. Hareket boyunca başınızı, kalçanızı ve belinizi sabit tutun; belinizde bir kavis oluşuyorsa veya geriye yaslanmadan baş üstü pozisyona ulaşamıyorsanız daha hafif bir ağırlık kullanın ya da halo ve extension hareketlerini ayrı egzersizler olarak yapın."]', 'strength', '[]', 360.0, 'Kettlebell Halo with Overhead Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a360ded0-35d5-569f-9ec8-cf77c412c74d', 'free-exercise-db', 'Kettlebell_Hang_Clean', 'Hang Clean (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["calves", "glutes", "lower back", "shoulders", "traps"]', '["Kettlebell''i ayaklarınızın arasına koyun. Başlangıç pozisyonuna geçmek için kalçanızı geriye itin ve düz karşıya bakın.", "Kettlebell''i omzunuza kaldırın (clean). Kettlebell''i omzunuza doğru kaldırırken bacaklarınızı ve kalçanızı açın. Bunu yaparken bilek dönmelidir.", "Arka bacak kaslarınızı gergin tutarak kettlebell''i bacaklarınızın arasında asılı pozisyona indirin. Başınızı her zaman yukarıda tutun."]', 'strength', '["Kettlebell_Hang_Clean/0.jpg", "Kettlebell_Hang_Clean/1.jpg"]', 360.0, 'Kettlebell Hang Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ccc432e7-c434-5c25-bfb3-99f57896d75f', 'free-exercise-db', 'Kettlebell_One-Legged_Deadlift', 'Tek Bacak Deadlift (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["glutes", "lower back"]', '["Bir kettlebell''i sapından tek elinizle tutun. Kettlebell''i tuttuğunuz taraftaki bacak üzerinde durun.", "O dizi hafifçe bükülü tutarak, kalçadan eğilerek ve serbest bacağınızı denge için arkanıza uzatarak stiff-leg deadlift yapın.", "Yere paralel olana kadar kettlebell''i indirmeye devam edin ve ardından dik pozisyona dönün."]', 'strength', '["Kettlebell_One-Legged_Deadlift/0.jpg", "Kettlebell_One-Legged_Deadlift/1.jpg"]', 360.0, 'Kettlebell One-Legged Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('01feaafb-6a24-5d37-b1aa-bf05f9cff843', 'free-exercise-db', 'Kettlebell_Overhead_Triceps_Extension', 'Overhead Triceps Extension (Kettlebell)', 'push', 'beginner', 'isolation', '["kettlebells"]', '["triceps"]', '["shoulders", "abdominals"]', '["Ayaklarınız kalça genişliğinde açık dururken kettlebell''i iki elinizle kulplarından tutun. Kollarınız açılana kadar başınızın üzerine itin; kettlebell''in gövdesi ellerinizin arkasında sarkmalıdır.", "Karın kaslarınızı sıkın ve üst kollarınızı dik ve başınıza yakın tutun. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi bükerek kettlebell''i başınızın arkasına indirin; dirsekleriniz dışarı açılmadan omuz mobilitenizin izin verdiği kadar gidin.", "Dirseklerinizi açarak kettlebell''i başlangıç pozisyonuna geri itin ve bu sırada üst kollarınızı hareketsiz tutun.", "Kaburga kafesinizi aşağıda tutun ve kollarınızı açarken alt belinizi kavislendirmekten kaçının."]', 'strength', '[]', 360.0, 'Kettlebell Overhead Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4f4a45e0-e3a4-5c69-8f7b-17f882d7e23b', 'free-exercise-db', 'Kettlebell_Pass_Between_The_Legs', 'Bacak Arası Kettlebell Pas', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["abdominals"]', '["glutes", "hamstrings", "shoulders"]', '["Bir kettlebell''i bacaklarınızın arasına koyun ve rahat bir duruş alın. Kalçanızı geriye iterek ve sırtınızı düz tutarak öne eğilin.", "Bir kettlebell''i alın ve bacaklarınızın arasından \"W\" şeklinde diğer elinize aktarın. Birkaç tekrar boyunca ileri geri devam edin."]', 'strength', '["Kettlebell_Pass_Between_The_Legs/0.jpg", "Kettlebell_Pass_Between_The_Legs/1.jpg"]', 360.0, 'Kettlebell Pass Between The Legs', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('288bfec5-6fc2-5fa6-9cfb-4a458d11be33', 'free-exercise-db', 'Kettlebell_Pirate_Ships', 'Pirate Ship (Kettlebell)', 'push', 'beginner', 'compound', '["kettlebells"]', '["shoulders"]', '["abdominals"]', '["Geniş bir duruşla bir kettlebell''i iki elinizle tutun. Kollarınız uzamış halde bel hizasında sarkmasına izin verin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Bir yana dönerek ve kettlebell''i baş hizasına sallayarak harekete başlayın. Hareketin üst noktasında kısa bir süre duraklayın.", "Karşı yana dönerken kettlebell''in düşmesine izin verin ve tekrar kettlebell''i baş hizasına kaldırın.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Kettlebell_Pirate_Ships/0.jpg", "Kettlebell_Pirate_Ships/1.jpg"]', 360.0, 'Kettlebell Pirate Ships', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6d309d5e-5c4c-5880-ab5c-a4f7be2827e2', 'free-exercise-db', 'Kettlebell_Pistol_Squat', 'Pistol Squat (Kettlebell)', 'push', 'expert', 'compound', '["kettlebells"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "shoulders"]', '["Bir kettlebell''i iki elinizle boynuzlarından tutarak alın. Bir bacağınızı yerden kaldırın ve diğer bacağın üzerinde çömelin.", "Kettlebell''i önünüzde yukarıda tutarak dizinizi bükün ve kalçanızı geriye oturtarak çömelin.", "Alt pozisyonda bir saniye bekleyin, ardından başınızı ve göğsünüzü yukarıda tutarak topuğunuzdan iterek hareketi tersine çevirin.", "Kendinizi tekrar indirin ve tekrarlayın."]', 'strength', '["Kettlebell_Pistol_Squat/0.jpg", "Kettlebell_Pistol_Squat/1.jpg"]', 360.0, 'Kettlebell Pistol Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b9bab72a-2dea-5d82-8bc6-a46e0c348960', 'free-exercise-db', 'Kettlebell_Seated_Press', 'Oturarak Press (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["triceps"]', '["Yere oturun ve bacaklarınızı rahatça açın.", "Bir kettlebell''i omzunuza clean yapın.", "Kettlebell''i kilitlenene kadar yukarı ve dışa doğru başınızın üzerine itin. Başlangıç pozisyonuna dönün."]', 'strength', '["Kettlebell_Seated_Press/0.jpg", "Kettlebell_Seated_Press/1.jpg"]', 360.0, 'Kettlebell Seated Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('248251b5-3d93-52c7-9837-f264e77c4b30', 'free-exercise-db', 'Kettlebell_Seesaw_Press', 'Tahterevalli Press (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["triceps"]', '["İki kettlebell''i omuzlarınıza clean ile alın.", "Bir kettlebell''i yukarı itin.", "Kettlebell''i indirin ve hemen diğer kettlebell''i yukarı itin. Her iki tarafta da aynı sayıda tekrar yaptığınızdan emin olun."]', 'strength', '["Kettlebell_Seesaw_Press/0.jpg", "Kettlebell_Seesaw_Press/1.jpg"]', 360.0, 'Kettlebell Seesaw Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('72beb933-ea07-5f9e-9ee3-108594345ff4', 'free-exercise-db', 'Kettlebell_Sumo_High_Pull', 'Sumo High Pull (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["traps"]', '["adductors", "glutes", "hamstrings", "quadriceps", "shoulders"]', '["Bir kettlebell''i ayaklarınızın arasına yere koyun. Ayaklarınızı geniş bir duruşta konumlandırın ve kettlebell''i iki elinizle kavrayın. Dizleriniz bükülü olarak kalçanızı mümkün olduğunca geriye alın. Göğsünüzü ve başınızı yukarıda tutun. Bu sizin başlangıç pozisyonunuzdur.", "Kalçanızı ve dizlerinizi açarak, aynı anda dirseklerinizi yükselterek kettlebell''i omuzlarınıza doğru çekmeye başlayın. Başlangıç pozisyonuna dönmek için hareketi tersine çevirin."]', 'strength', '["Kettlebell_Sumo_High_Pull/0.jpg", "Kettlebell_Sumo_High_Pull/1.jpg"]', 360.0, 'Kettlebell Sumo High Pull', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1ee7488b-757b-5096-ad12-c1e215045b48', 'free-exercise-db', 'Kettlebell_Thruster', 'Thruster (Kettlebell, Çift)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["quadriceps", "triceps"]', '["İki kettlebell''i omuzlarınıza çekin (clean). Bacaklarınızı ve kalçanızı açarak kettlebell''leri omuzlarınıza doğru çekin. Bunu yaparken bileklerinizi döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Kalçanızı ve dizlerinizi bükerek, kalçanızı bacaklarınızın arasına indirerek squat yapmaya başlayın. Olabildiğince alçağa inerken sırtınızı dik ve düz tutun.", "En alt noktada yön değiştirin ve topuklarınızla iterek dizlerinizi ve kalçanızı açıp squat''tan kalkın. Bunu yaparken kollarınızı dümdüz yukarı uzatarak iki kettlebell''i de tepenize itin ve ağırlıkları yukarı sürmek için squat''tan gelen ivmeyi kullanın.", "Bir sonraki tekrara başlarken ağırlıkları omuzlara geri getirin."]', 'strength', '["Kettlebell_Thruster/0.jpg", "Kettlebell_Thruster/1.jpg"]', 360.0, 'Kettlebell Thruster', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('92a2afad-338c-5f5d-9c12-95d807f1426d', 'free-exercise-db', 'Kettlebell_Turkish_Get-Up_Lunge_style', 'Turkish Get-Up (Kettlebell, Lunge Tarzı)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["abdominals", "hamstrings", "quadriceps", "triceps"]', '["Yerde sırtüstü uzanın ve dirseğinizi açarak bir kettlebell''i üst pozisyona itin. Kettlebell ile aynı taraftaki dizinizi bükün.", "Kettlebell''i her zaman kilitli tutarak karşı tarafa doğru dönün ve çalışmayan kolunuzu lunge pozisyonuna doğru ilerlemenize yardımcı olması için kullanın. Boştaki elinizle kendinizi oturur pozisyona itin, ardından bir dize ilerleyin.", "Kettlebell''e bakarak yavaşça ayağa kalkın. Hareketi tersine çevirerek başlangıç pozisyonuna dönün ve tekrarlayın."]', 'strength', '["Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg", "Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg"]', 360.0, 'Kettlebell Turkish Get-Up (Lunge style)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('71e5df30-8f32-5553-a6db-a3d562e439de', 'free-exercise-db', 'Kettlebell_Turkish_Get-Up_Squat_style', 'Turkish Get-Up (Kettlebell, Squat Stili)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["abdominals", "calves", "hamstrings", "quadriceps", "triceps"]', '["Yerde sırtüstü uzanın ve dirseğinizi açarak bir kettlebell''i yukarı itin. Kettlebell ile aynı taraftaki dizinizi bükün.", "Kettlebell''i her zaman kilitli tutarak karşı tarafa doğru dönün ve çalışmayan kolunuzu lunge pozisyonuna doğru ileri atılmanıza yardımcı olması için kullanın.", "Serbest elinizle kendinizi oturma pozisyonuna itin, ardından ayağa kalkmaya geçin. Kettlebell''e bakarak yavaşça ayağa kalkın. Hareketi tersine çevirerek başlangıç pozisyonuna dönün ve tekrarlayın."]', 'strength', '["Kettlebell_Turkish_Get-Up_Squat_style/0.jpg", "Kettlebell_Turkish_Get-Up_Squat_style/1.jpg"]', 360.0, 'Kettlebell Turkish Get-Up (Squat style)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('90dbfd47-a68e-548f-b722-d28af2269daf', 'free-exercise-db', 'Kettlebell_Windmill', 'Windmill (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["abdominals"]', '["glutes", "hamstrings", "shoulders", "triceps"]', '["Bir kettlebell''i ön ayağınızın önüne koyun ve karşı kolunuzla clean and press ile baş üstüne kaldırın. Bacaklarınızı ve kalçanızı açarak kettlebell''i omuzlarınıza doğru çekerek omzunuza getirin. Bunu yaparken bileğinizi döndürün, böylece avuç içi ileri baksın. Dirseğinizi açarak baş üstüne itin.", "Kettlebell her zaman kilitli şekilde, kalçanızı kilitli kettlebell yönüne doğru dışarı itin. Ayaklarınızı kilitli kettlebell''in olduğu koldan kırk beş derecelik bir açıyla dışa doğru çevirin. Kalçadan bir yana doğru eğilerek, kalçanızı dışarı iterek, serbest elinizle yere dokunabilene kadar yavaşça eğilin. Baş üstünde tuttuğunuz kettlebell''e her zaman gözlerinizi sabitleyin.", "Yere ulaştıktan sonra bir saniye duraklayın ve hareketi tersine çevirerek başlangıç pozisyonuna dönün."]', 'strength', '["Kettlebell_Windmill/0.jpg", "Kettlebell_Windmill/1.jpg"]', 360.0, 'Kettlebell Windmill', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fff2a0ac-2031-5c5f-b1ed-b36f3690f90f', 'free-exercise-db', 'Kipping_Muscle_Up', 'Kipping Muscle-Up', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["abdominals", "biceps", "forearms", "middle back", "shoulders", "traps", "triceps"]', '["Halkaları false grip ile tutun; avuç içlerinizin alt kısmı halkaların üzerinde olsun.", "Bacaklarınızı hafifçe geriye doğru savurarak harekete başlayın.", "Bu hareketin tersine bacaklarınızı öne ve yukarı savurun, çenenizi ve göğsünüzü geriye doğru hızla çekin ve bunu yaparken kendinizi iki kolunuzla yukarı çekin. Barfiksin üst pozisyonuna ulaştığınızda, omuzlarınızı öne yuvarlarken halkaları koltuk altlarınıza çekin ve dirseklerinizin düz arkanıza doğru gitmesine izin verin. Bu, hareketin dips kısmına devam etmeniz için sizi doğru pozisyona getirir.", "Kontrolü ve dengeyi koruyarak hareketi tamamlamak için dirseklerinizden uzayın.", "Kendinizi yere indirirken dikkatli olun."]', 'strength', '["Kipping_Muscle_Up/0.jpg", "Kipping_Muscle_Up/1.jpg"]', 360.0, 'Kipping Muscle Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9eb7ec67-5100-5349-9c7d-ba54bc3a36f4', 'free-exercise-db', 'Knee_Across_The_Body', 'Diz Çaprazlama Esnetmesi', 'static', 'beginner', NULL, '[]', '["glutes"]', '["abductors", "lower back"]', '["Sağ bacağınız düz olacak şekilde yere uzanın. Sol bacağınızı bükün ve vücudunuzun karşısına doğru indirin; sağ elinizle dizi yere doğru bastırın. (Gergin iseniz dizin yere değmesi gerekmez.)", "Sol kolunuzu rahatça yanınıza koyun ve başınızı sola çevirin. Kuyruk sokumunuza bir ağırlık bağlı olduğunu hayal edin. Alt sırtınızı esnetmek için göğsünüz ters yönde uzanırken kuyruk sokumunuzun yere doğru geriye düşmesine izin verin. Taraf değiştirin."]', 'stretching', '["Knee_Across_The_Body/0.jpg", "Knee_Across_The_Body/1.jpg"]', 150.0, 'Knee Across The Body', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5b42538c-573b-5e86-9813-6a87c6dbc6cb', 'free-exercise-db', 'Knee_Circles', 'Diz Daireleri', 'pull', 'beginner', 'compound', '["body only"]', '["calves"]', '["hamstrings", "quadriceps"]', '["Bacaklarınız bitişik ve elleriniz belinizin yanında şekilde durun.", "Şimdi normal nefes alırken dizlerinizi dairesel bir hareketle hareket ettirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'stretching', '["Knee_Circles/0.jpg", "Knee_Circles/1.jpg"]', 150.0, 'Knee Circles', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('14191a42-f944-5e84-baa0-c37ee4f67a01', 'free-exercise-db', 'Knee_Hip_Raise_On_Parallel_Bars', 'Diz/Kalça Kaldırma (Paralel Bar)', 'pull', 'beginner', 'isolation', '["other"]', '["abdominals"]', '[]', '["Vücudunuzu dikey bacak kaldırma bench''ine, ön kollarınız gövdenin yanındaki pedlerin üzerinde dinlenecek ve tutacakları tutacak şekilde yerleştirin. Kollarınız 90 derecelik açıyla bükülü olacaktır.", "Gövde düz, alt sırt makinenin pedine bastırılmış ve bacaklar yere doğru uzamış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes verirken bacaklarınızı uzamış halde tutarak yukarı kaldırın. Bacaklarınız yere yaklaşık paralel olana kadar bu hareketi sürdürün ve ardından kasılmayı bir saniye tutun. İpucu: Bu egzersizi yaparken herhangi bir ivme veya sallanma kullanmayın.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Knee_Hip_Raise_On_Parallel_Bars/0.jpg", "Knee_Hip_Raise_On_Parallel_Bars/1.jpg"]', 360.0, 'Knee/Hip Raise On Parallel Bars', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fc53ddf7-339e-5d25-824a-11fb1c5030c6', 'free-exercise-db', 'Knee_Tuck_Jump', 'Diz Çekme Sıçraması', 'push', 'beginner', 'compound', '["body only"]', '["hamstrings"]', '["abductors", "adductors", "calves", "glutes", "quadriceps"]', '["Dizleriniz hafif bükülü, rahat bir ayakta durma pozisyonunda başlayın. Ellerinizi önünüzde, avuç içleri aşağı bakacak ve parmak uçları göğüs hizasında birleşecek şekilde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Hızla çeyrek squat pozisyonuna inin ve hemen yukarı doğru patlayıcı şekilde sıçrayın. Dizlerinizi göğsünüze doğru çekin ve avuç içlerinize değdirmeye çalışın.", "Dizlerinizi yukarı kaldırarak olabildiğince yükseğe sıçrayın, ardından bacaklarınızı yeniden açarak ve dizlerin tekrar bükülmesine izin vererek darbeyi sönümleyip iyi bir iniş yaptığınızdan emin olun."]', 'plyometrics', '["Knee_Tuck_Jump/0.jpg", "Knee_Tuck_Jump/1.jpg"]', 480.0, 'Knee Tuck Jump', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('71241211-7e8a-5578-a1d7-701c72e064d6', 'free-exercise-db', 'Kneeling_Arm_Drill', 'Diz Çökerek Kol Çalışması', 'pull', 'beginner', NULL, '[]', '["shoulders"]', '["abdominals"]', '["Bu çalışma koşu sırasında kol verimliliğini artırmaya yardımcı olur. Sol ayağınız önde, sağ dizinizi yerde olacak şekilde diz çökerek başlayın. Kalça ve arka bacak kaslarınızın aktif kalması için ön topuğunuzdan baskı uygulayın.", "Kolları uzun, sarkaç benzeri sallanışlarla kontrol ederek başlayın. Kol açısını daraltın ve kolları hafif tempolu koşuda olduğu gibi kullanın, ardından koşuya ve son olarak sprinte ilerleyin.", "Elleriniz kalçanızı geçtiği anda, sprint hareketinde olduğu gibi olabildiğince hızlı olmaları için onları öne doğru hızlandırın.", "Diz değiştirin ve tekrarlayın."]', 'plyometrics', '["Kneeling_Arm_Drill/0.jpg", "Kneeling_Arm_Drill/1.jpg"]', 480.0, 'Kneeling Arm Drill', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1912f5d3-6b27-5899-98b7-53cf4b347d02', 'free-exercise-db', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'Diz Üstü Kablo Crunch (Dönüşümlü Oblik Twist)', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["Yüksek bir makara kablosuna ip aparatı bağlayın ve önüne yere bir mat yerleştirin.", "İpi iki elinizle kavrayın ve kuleden yaklaşık iki ayak geride diz çökün.", "İpi başınızın arkasına, ellerinizi kulaklarınızın yanında olacak şekilde konumlandırın.", "Ellerinizi aynı yerde tutarak karın kaslarınızı kasın ve dirsekleriniz dizlerinize ulaşana kadar ipi crunch hareketiyle aşağı çekin.", "Altta kısa bir süre bekleyin ve yavaş ve kontrollü bir şekilde başlangıç pozisyonuna ulaşana kadar yukarı kalkın.", "Aynı aşağı hareketi yarıya gelene kadar tekrarlayın; bu noktada dirseklerinizden birini karşı dize doğru döndürmeye başlayacaksınız.", "Yine altta kısa bir süre bekleyin ve yavaş ve kontrollü bir şekilde başlangıç pozisyonuna ulaşana kadar yukarı kalkın.", "Aynı hareketi önceki gibi tekrarlayın, ancak bu sefer diğer dirseği karşı dize getirerek dönüşümlü yapın.", "Bu hareket serisine tükenene kadar devam edin."]', 'strength', '["Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg", "Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/1.jpg"]', 360.0, 'Kneeling Cable Crunch With Alternating Oblique Twists', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('479c963f-9f7b-5880-b539-f41a4048b073', 'free-exercise-db', 'Kneeling_Cable_Triceps_Extension', 'Diz Üstü Triceps Extension (Kablo)', 'push', 'intermediate', 'isolation', '["cable"]', '["triceps"]', '[]', '["Bir bench''i yüksek makara makinesinin önüne yan olarak yerleştirin.", "Düz bar aparatını elleriniz yaklaşık 15 cm aralıkta ve avuç içleriniz aşağı bakacak şekilde başınızın üzerinde tutun.", "Makineye sırtınız dönük olarak diz çökün.", "Başınızı ve üst kollarınızın arkasını bench''in üzerine koyun. Dirsekleriniz bükülü ve ön kollarınız yüksek makaraya doğru bakıyor olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kollarınızı her zaman başınıza yakın ve dirsekleriniz içeride tutarak, dirsekler kilitlenene ve kollarınız yere paralel olana kadar barı yarım daire hareketiyle öne itin. Triceps''inizi sertçe kasın ve bu pozisyonu bir saniye koruyun. Bu hareketi yaparken nefes verin.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Kneeling_Cable_Triceps_Extension/0.jpg", "Kneeling_Cable_Triceps_Extension/1.jpg"]', 360.0, 'Kneeling Cable Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6009ecb0-e013-563c-8588-df521a77a586', 'free-exercise-db', 'Kneeling_Forearm_Stretch', 'Diz Çökerek Ön Kol Esnetme', 'static', 'beginner', 'isolation', '[]', '["forearms"]', '[]', '["Avuç içleriniz düz ve parmaklarınız dizlerinize doğru geriye bakacak şekilde bir mat üzerinde diz çökerek başlayın.", "Avuç içlerinizi yerde düz tutarak, bileklerinizde ve ön kollarınızda bir gerilme hissedene kadar yavaşça geriye doğru yaslanın. 20-30 saniye bekleyin."]', 'stretching', '["Kneeling_Forearm_Stretch/0.jpg", "Kneeling_Forearm_Stretch/1.jpg"]', 150.0, 'Kneeling Forearm Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7a81f66c-61c3-5a4d-a3a3-7417111eff86', 'free-exercise-db', 'Kneeling_High_Pulley_Row', 'Diz Çökerek Yüksek Makara Row', 'pull', 'beginner', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back"]', '["Başınızın üzerinde bir makara kullanarak uygun ağırlığı seçin. Kabloya bir ip takın ve birkaç adım uzakta diz çökün; ipi iki kolunuz uzanmış şekilde önünüzde tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Dirseklerinizi bükerek ve omuzlarınızı tamamen geriye çekerek, dirsekleriniz dışarıda olacak şekilde ipi üst göğsünüze doğru çekerek harekete başlayın.", "Kısa bir duraklamadan sonra yavaşça başlangıç pozisyonuna dönün."]', 'strength', '["Kneeling_High_Pulley_Row/0.jpg", "Kneeling_High_Pulley_Row/1.jpg"]', 360.0, 'Kneeling High Pulley Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0cdc1944-d3c2-5219-a912-632fc92e47a2', 'free-exercise-db', 'Kneeling_Hip_Flexor', 'Diz Üstü Kalça Fleksörü Esnetme', 'static', 'beginner', 'isolation', '[]', '["quadriceps"]', '["quadriceps"]', '["Bir mat üzerinde diz çökün ve sağ dizinizi, ayak tabanınız yerde olacak şekilde yukarı getirin; sol bacağınızı, ayağınızın üstü yerde olacak şekilde arkanıza uzatın.", "Kalçanızda bir esneme hissedene kadar ağırlığınızı öne kaydırın. 15 saniye bekleyin, ardından diğer tarafta tekrarlayın."]', 'stretching', '["Kneeling_Hip_Flexor/0.jpg", "Kneeling_Hip_Flexor/1.jpg"]', 150.0, 'Kneeling Hip Flexor', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d070f757-bd01-5403-884d-133edbde4294', 'free-exercise-db', 'Kneeling_Jump_Squat', 'Diz Çökmüş Jump Squat', 'push', 'expert', 'compound', '["barbell"]', '["glutes"]', '["calves", "hamstrings", "quadriceps"]', '["Omuzlarınızın arkasına halter yerleştirilmiş şekilde yerde diz çökerek başlayın veya bu egzersiz için vücut ağırlığınızı kullanabilirsiniz. Barı raftan almayı kolaylaştırmak için bu, bir power rack içinde yapılabilir.", "Başınızı ve göğsünüzü yukarıda tutarak kalçanızı geriye oturtun, kalçanız ayaklarınıza değene kadar inin.", "Ayaklarınızın yere düz basarak inmesini sağlayacak kadar güç üretmek için kalçanızla patlayıcı şekilde yukarı fırlayın.", "Topuklarınızdan iterek ve dizlerinizi açarak ayakta duruş pozisyonuna gelip squat''ı sürdürün."]', 'olympic weightlifting', '["Kneeling_Jump_Squat/0.jpg", "Kneeling_Jump_Squat/1.jpg"]', 420.0, 'Kneeling Jump Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b400bdb2-297c-5fc1-81d1-a655e60f7397', 'free-exercise-db', 'Kneeling_Single-Arm_High_Pulley_Row', 'Diz Üstü Tek Kol Row (Üst Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back"]', '["Tek bir tutacağı üst makaraya bağlayın ve ağırlığınızı seçin.", "Kablo kulesinin önünde diz çökün ve kolunuz uzamış halde kabloyu tek elinizle alın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Avuç içiniz öne bakarken, dirseğinizi bükerek ve kürek kemiğinizi geriye çekerek ağırlığı gövdenize doğru aşağı çekin. Bunu yaparken bileğinizi, hareketin sonunda avuç içiniz size bakacak şekilde döndürün.", "Kısa bir duraklamanın ardından başlangıç pozisyonuna dönün."]', 'strength', '["Kneeling_Single-Arm_High_Pulley_Row/0.jpg", "Kneeling_Single-Arm_High_Pulley_Row/1.jpg"]', 360.0, 'Kneeling Single-Arm High Pulley Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1e63bfb4-a5ed-52a5-aa1b-4e6dbec6e004', 'free-exercise-db', 'Kneeling_Squat', 'Kneeling Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["glutes"]', '["abdominals", "hamstrings", "lower back"]', '["Halteri power rack''te uygun yüksekliğe ayarlayın. Halterin arkasında diz çökün; dizlerinizi yastıklamak için bir mat sermek faydalı olabilir. Halterin altına kayın ve omuzlarınızın arkasına yerleştirin. Kürek kemikleriniz geriye çekilmeli ve halter sırtınızda sıkı durmalıdır. Ağırlığı raftan çıkarın.", "Başınız ileri bakarken kalçanızla geriye oturarak baldırlarınıza değene kadar inin.", "Hareketi tersine çevirerek gövdenizi dik pozisyona geri getirin."]', 'powerlifting', '["Kneeling_Squat/0.jpg", "Kneeling_Squat/1.jpg"]', 360.0, 'Kneeling Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('42ee9901-d8b9-5eba-bae5-0de275ee7aba', 'free-exercise-db', 'Landmine_180s', 'Landmine 180', 'pull', 'beginner', 'compound', '["barbell"]', '["abdominals"]', '["glutes", "lower back", "shoulders"]', '["Bir barı landmine aparatına yerleştirin veya bir köşeye sağlam şekilde sabitleyin. Barı uygun bir ağırlıkla yükleyin.", "Barı yerden kaldırın ve kollarınız önünüze uzanmış şekilde iki elinizle omuz yüksekliğine getirin. Geniş bir duruş alın. Bu sizin başlangıç pozisyonunuz olacak.", "Gövdenizi ve kalçanızı döndürürken ağırlığı tamamen bir yana doğru savurarak hareketi gerçekleştirin. Egzersiz boyunca kollarınızı uzanmış tutun.", "Ağırlığı tamamen karşı tarafa savurmak için hareketi tersine çevirin.", "Set tamamlanana kadar hareketi dönüşümlü olarak sürdürün."]', 'strength', '["Landmine_180s/0.jpg", "Landmine_180s/1.jpg"]', 360.0, 'Landmine 180''s', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('89d584fd-7d9b-5c7c-8321-3bb81d166bba', 'free-exercise-db', 'Landmine_Linear_Jammer', 'Landmine Linear Jammer', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["abdominals", "calves", "chest", "hamstrings", "quadriceps", "triceps"]', '["Bir barı landmine aparatına yerleştirin veya aparat yoksa bir köşeye sağlam bir şekilde sabitleyin. Barı uygun bir ağırlıkla yükleyin ve tutamak aparatını bar üzerine yerleştirin.", "Barı yerden kaldırın ve tutamakları omuzlarınıza getirin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Atletik bir duruşta, kollarınız bükülü kalacak şekilde kalçanızı bükerek ve geriye iterek squat yapın.", "Hareketi, kalçanızı, dizlerinizi ve ayak bileklerinizi güçlü bir şekilde açarak ve aynı zamanda kollarınızı düzeltmek için dirseklerinizi açarak tersine çevirin. Bu hareket patlayıcı bir şekilde, squat''tan tam açılmaya olabildiğince güçlü biçimde çıkarak yapılmalıdır.", "Başlangıç pozisyonuna dönün."]', 'strength', '["Landmine_Linear_Jammer/0.jpg", "Landmine_Linear_Jammer/1.jpg"]', 360.0, 'Landmine Linear Jammer', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3b4e7cb3-ff21-5ea0-918b-90064c49be36', 'free-exercise-db', 'Lateral_Bound', 'Yana Sıçrama (Lateral Bound)', 'push', 'beginner', 'compound', '["body only"]', '["adductors"]', '["abductors", "calves", "glutes", "hamstrings", "quadriceps"]', '["Hareket yönünüze 90 derece dönük şekilde yarım squat pozisyonu alın. Bu sizin başlangıç pozisyonunuzdur.", "Ağırlığınızı dış bacağa kaydırırken önde olan bacağınızın içe doğru karşı hareket yapmasına izin verin.", "Hemen itin ve uzanın; yana doğru olabildiğince uzağa sıçramaya çalışın.", "İner inmez hemen ters yönde itin ve ilk başlangıç pozisyonunuza dönün.", "Birkaç tekrar boyunca ileri geri devam edin."]', 'plyometrics', '["Lateral_Bound/0.jpg", "Lateral_Bound/1.jpg"]', 480.0, 'Lateral Bound', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f4845ea6-afe1-5adf-901c-705a8443083e', 'free-exercise-db', 'Lateral_Box_Jump', 'Yana Box Jump', 'push', 'beginner', 'compound', '["other"]', '["adductors"]', '["abductors", "calves", "glutes", "hamstrings", "quadriceps"]', '["Rahat bir ayakta duruş alın ve yanınıza kısa bir kutu yerleştirin. Bu sizin başlangıç pozisyonunuzdur.", "Germe refleksini başlatmak için hızla çeyrek squat''a çökün ve hemen yönü tersine çevirerek yukarı ve yana doğru zıplayın.", "Ayaklarınızın kutunun üzerinden rahatça geçmesini sağlayacak kadar dizlerinizi yükseğe getirin.", "Darbeyi bacaklarınızla emerek kutunun ortasına inin.", "Kutunun diğer tarafına dikkatlice zıplayarak inin ve birkaç tekrar boyunca ileri geri devam edin."]', 'plyometrics', '["Lateral_Box_Jump/0.jpg", "Lateral_Box_Jump/1.jpg"]', 480.0, 'Lateral Box Jump', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('cb32f4fe-8892-5dc9-a003-e6fd6591c02a', 'free-exercise-db', 'Lateral_Cone_Hops', 'Yana Koni Sıçraması', 'push', 'beginner', 'compound', '["other"]', '["adductors"]', '["abductors", "calves", "glutes", "hamstrings", "quadriceps"]', '["Birkaç adım aralıkla bir sıra koni yerleştirin.", "Konilerin ucunun yanında, gidiş yönüne 90 derece dönük olarak durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Bir gerilme refleksi başlatmak için dizlerinizi bükerek çömelip sıçramaya başlayın ve hemen yön değiştirip yerden iterek koninin üzerinden yukarı ve yana doğru zıplayın.", "İnişte darbeyi bacaklarınızla karşılayın ve bir sonraki sıçramaya geri tepin; koni sırası boyunca devam edin."]', 'plyometrics', '["Lateral_Cone_Hops/0.jpg", "Lateral_Cone_Hops/1.jpg"]', 480.0, 'Lateral Cone Hops', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('14b1cb6c-7ade-5ba2-85dd-fa17cacf2349', 'free-exercise-db', 'Lateral_Raise_-_With_Bands', 'Lateral Raise (Direnç Bandı)', 'push', 'beginner', 'isolation', '["bands"]', '["shoulders"]', '[]', '["Başlamak için bir egzersiz bandının üzerine, gerginlik kol boyunda başlayacak şekilde basın. Tutamaçları omuz genişliğinden biraz daha dar, pronasyon tutuşla (avuç içleri uyluklarınıza bakacak şekilde) kavrayın. Tutamaçlar uyluklarınızın yanlarında durmalıdır. Kollarınız dirsekleri hafif bükülü şekilde uzamış ve sırtınız düz olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken yan omuz kaslarınızı kullanarak tutamaçları yanlara doğru kaldırın. Tutamaçları paralelin biraz üstüne gelene kadar kaldırmaya devam edin. İpucu: Tutamaçları kaldırırken elinizi su döker gibi hafifçe eğin ve kollarınızı uzamış halde tutun. Ayrıca gövdenizi sabit tutun ve hareketin üst noktasında bir saniye bekleyin.", "Tutamaçları yavaşça başlangıç pozisyonuna geri indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lateral_Raise_-_With_Bands/0.jpg", "Lateral_Raise_-_With_Bands/1.jpg"]', 360.0, 'Lateral Raise - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9062ca0c-dfbe-57d2-9e4d-1af187365e52', 'free-exercise-db', 'Latissimus_Dorsi-SMR', 'Latissimus Dorsi Foam Roller', 'static', 'beginner', 'isolation', '["foam roll"]', '["lats"]', '[]', '["Yerde yatarken, bir foam roller''ı sırtınızın altına ve bir yana, koltuk altınızın hemen arkasına yerleştirin. Bu sizin başlangıç pozisyonunuz olacak.", "Gerilen taraftaki kolunuzu arkanızda ve yanınızda tutarak, üst vücudunuz yerden havada kalacak şekilde ağırlığınızı latissimus kaslarınıza kaydırın. 10-30 saniye bekleyin ve taraf değiştirin."]', 'stretching', '["Latissimus_Dorsi-SMR/0.jpg", "Latissimus_Dorsi-SMR/1.jpg"]', 150.0, 'Latissimus Dorsi-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eb1829b7-23af-554f-bdab-93c33ebbb6a5', 'free-exercise-db', 'Leg-Over_Floor_Press', 'Leg-Over Floor Press (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["chest"]', '["shoulders", "triceps"]', '["Yere uzanın ve bir kettlebell''i sapından tutarak göğsünüzün üzerine yerleştirin. Çalışan taraftaki bacağınızı çalışmayan taraftaki bacağın üzerinden uzatın. Boştaki kolunuz destek için yanınıza uzatılabilir.", "Kettlebell''i kilitli pozisyona kadar itin.", "Kettlebell dirseğin üzerinde kalacak şekilde dirseğiniz yere değene kadar ağırlığı indirin. İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Leg-Over_Floor_Press/0.jpg", "Leg-Over_Floor_Press/1.jpg"]', 360.0, 'Leg-Over Floor Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('329b7507-b3c5-5ea5-8e8a-b9829a400f80', 'free-exercise-db', 'Leg-Up_Hamstring_Stretch', 'Bacak Yukarıda Arka Bacak Esnetme', 'push', 'beginner', 'isolation', '[]', '["hamstrings"]', '[]', '["Sırtüstü düz yatın, bir dizinizi bükün ve omurganızı dengelemek için o ayağınızı yere düz basın.", "Diğer bacağınızı havaya uzatın. Gergin iseniz tamamen düzleştiremeyebilirsiniz; sorun değil. Kaldırdığınız ayağın tabanı tavana bakacak şekilde (ya da olabildiğince yaklaşacak şekilde) dizi uzatın.", "Bacağı yavaşça olabildiğince düzleştirin ve ardından bacağı burnunuza doğru çekin. Taraf değiştirin."]', 'stretching', '["Leg-Up_Hamstring_Stretch/0.jpg", "Leg-Up_Hamstring_Stretch/1.jpg"]', 150.0, 'Leg-Up Hamstring Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('616c5137-d45d-537e-ac05-1d8e1c828422', 'free-exercise-db', 'Leg_Extensions', 'Leg Extension (Makine)', 'push', 'beginner', 'isolation', '["machine"]', '["quadriceps"]', '[]', '["Bu egzersiz için bir leg extension makinesi kullanmanız gerekecek. Önce ağırlığınızı seçin ve bacaklarınız pedin altında (ayaklar ileri bakacak şekilde) ve elleriniz yan çubukları tutacak şekilde makineye oturun. Bu sizin başlangıç pozisyonunuz olacaktır. İpucu: Pedi alt bacağınızın üzerine (ayaklarınızın hemen üstüne) gelecek şekilde ayarlamanız gerekecektir. Ayrıca bacaklarınızın alt ve üst bacak arasında 90 derecelik açı oluşturduğundan emin olun. Açı 90 dereceden azsa bu, dizin ayak parmaklarının üzerinde olduğu anlamına gelir ve bu da diz eklemine gereksiz yük bindirir. Makine bu şekilde tasarlanmışsa ya başka bir makine arayın ya da egzersize başladığınızda 90 derecelik açıya ulaştığınızda aşağı inmeyi bırakmaya dikkat edin.", "Quadriceps kaslarınızı kullanarak nefes verirken bacaklarınızı sonuna kadar uzatın. Vücudun geri kalanının koltukta sabit kaldığından emin olun. Kasılmış pozisyonda bir saniye duraklayın.", "Nefes alırken ağırlığı yavaşça orijinal pozisyona geri indirin; 90 derecelik açı sınırını geçmediğinizden emin olun.", "Önerilen sayıda tekrarlayın."]', 'strength', '["Leg_Extensions/0.jpg", "Leg_Extensions/1.jpg"]', 360.0, 'Leg Extensions', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2df242dc-edd2-5518-978c-c08e2468f073', 'free-exercise-db', 'Leg_Lift', 'Ayakta Geriye Bacak Kaldırma', 'push', 'beginner', 'isolation', '["body only"]', '["glutes"]', '["hamstrings"]', '["Ayaklarınız yan yana ve yaklaşık omuz genişliğinde, dik durun; kendinizi sabitlemek ve dengenizi korumak için squat rack''in yanları veya bir sandalyenin üst kısmı gibi sağlam bir yüzeyi kavrayın.", "Ayak bileği ağırlığı ile veya ağırlıksız olarak, diğer bacağınızı düz tutarak bir bacağınızı sanki ayakta leg curl yapıyormuşsunuz gibi arkanıza kaldırın. Bu hareketi yaparken nefes verin.", "Nefes alırken kaldırdığınız bacağı yavaşça yere getirin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Hareketi karşı bacakla tekrarlayın."]', 'strength', '["Leg_Lift/0.jpg", "Leg_Lift/1.jpg"]', 360.0, 'Leg Lift', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bf112065-a13c-5d61-aafc-21edc236d6e1', 'free-exercise-db', 'Leg_Press', 'Leg Press', 'push', 'beginner', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bir leg press makinesinde makineye oturun ve bacaklarınızı doğrudan önünüzdeki platforma orta (omuz genişliği) bir ayak duruşuyla yerleştirin. (Not: Bu anlatımda genel gelişimi hedefleyen yukarıda tarif edilen orta duruş kullanılacaktır; ancak ayak konumlandırma bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Ağırlıklı platformu yerinde tutan güvenlik barlarını indirin ve bacaklarınız önünüzde tamamen uzanana kadar platformu sonuna kadar itin. İpucu: Dizlerinizi kilitlemediğinizden emin olun. Gövdeniz ve bacaklarınız mükemmel bir 90 derecelik açı oluşturmalıdır. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes alırken üst ve alt bacaklarınız 90 derecelik bir açı yapana kadar platformu yavaşça indirin.", "Esas olarak ayaklarınızın topuklarıyla iterek ve kuadriseps kaslarını kullanarak nefes verirken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın ve işiniz bittiğinde güvenlik pimlerini düzgünce kilitlediğinizden emin olun. Tamamen yüklü platformun üzerinize düşmesini istemezsiniz."]', 'strength', '["Leg_Press/0.jpg", "Leg_Press/1.jpg"]', 360.0, 'Leg Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8852c4ac-910c-534c-87cd-0ec9d8f51616', 'free-exercise-db', 'Leg_Pull-In', 'Leg Pull-In', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Bir egzersiz matının üzerine bacaklarınız uzatılmış ve elleriniz avuç içleri aşağı bakacak şekilde yanınızda ya da kalçanızın altında olacak şekilde uzanın. İpucu: Benim tercihim ellerin yanda olmasıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken dizlerinizi bükün ve üst bacaklarınızı karın bölgenize doğru çekin. Dizleriniz yaklaşık göğüs seviyesine gelene kadar harekete devam edin. Bu hareketi yaparken karın kaslarınızı kasın ve üstte bir saniye bekleyin. İpucu: Hareket sırasında alt bacaklar (baldırlar) her zaman yere paralel kalmalıdır.", "Nefes alırken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Leg_Pull-In/0.jpg", "Leg_Pull-In/1.jpg"]', 360.0, 'Leg Pull-In', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d623d436-4be1-51db-aabb-96726df1b536', 'free-exercise-db', 'Leverage_Chest_Press', 'Chest Press (Leverage Makine)', 'push', 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Pimlere uygun ağırlığı yükleyin ve koltuğu boyunuza göre ayarlayın. Hareketin başında tutamaklar göğüs kaslarının alt veya orta kısmına yakın olmalıdır.", "Göğsünüz ve başınız yukarıda, kürek kemikleriniz geriye çekilmiş olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi açarak tutamakları öne doğru itin.", "Üstte kısa bir beklemeden sonra, set tamamlanana kadar ağırlığı duraklara indirmeyerek kaslardaki gerilimi koruyun ve ağırlığı başlangıç pozisyonunun hemen üzerine getirin."]', 'strength', '["Leverage_Chest_Press/0.jpg", "Leverage_Chest_Press/1.jpg"]', 360.0, 'Leverage Chest Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9b61a65b-96be-55cc-abb0-8ab217ce7bdb', 'free-exercise-db', 'Leverage_Deadlift', 'Deadlift (Leverage Makinesi)', 'pull', 'beginner', 'compound', '["machine"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Pimleri uygun ağırlığa yükleyin. Kendinizi tam olarak tutamaçların arasına konumlandırın. Alt tutamaçları rahat bir tutuşla kavrayın, ardından nefes alırken kalçanızı indirin. Başınızla ileri bakın ve göğsünüzü yukarıda tutun. Bu sizin başlangıç pozisyonunuzdur.", "Ağırlığı başlangıç pozisyonuna geri getirin."]', 'strength', '["Leverage_Deadlift/0.jpg", "Leverage_Deadlift/1.jpg"]', 360.0, 'Leverage Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('48a0c643-10a7-5851-85b5-54b44f6ab196', 'free-exercise-db', 'Leverage_Decline_Chest_Press', 'Decline Chest Press (Leverage Makine)', 'push', 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Pimlere uygun bir ağırlık yükleyin ve koltuğu boyunuza göre ayarlayın. Hareketin başlangıcında tutamaklar göğüs kaslarının alt kısmına yakın olmalıdır. Göğsünüz ve başınız yukarıda, kürek kemikleriniz geriye çekilmiş olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseklerinizi açarak tutamakları öne doğru itin.", "Üst noktada kısa bir beklemeden sonra, set bitene kadar ağırlığı stoklara indirmeyerek kaslardaki gerginliği koruyacak şekilde ağırlığı başlangıç pozisyonunun hemen üzerine geri getirin."]', 'strength', '["Leverage_Decline_Chest_Press/0.jpg", "Leverage_Decline_Chest_Press/1.jpg"]', 360.0, 'Leverage Decline Chest Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7a3c6dbb-0c38-5d95-b65a-73a18d88f6ab', 'free-exercise-db', 'Leverage_High_Row', 'High Row (Leverage Makinesi)', 'pull', 'beginner', 'compound', '["machine"]', '["middle back"]', '["lats"]', '["Pimlere uygun bir ağırlık yükleyin ve koltuk yüksekliğini tam olarak üstünüzdeki tutamaçlara uzanabileceğiniz şekilde ayarlayın. Sizi aşağıda tutmaya yardımcı olması için diz pedini ayarlayın. Tutamaçları pronasyon tutuşla kavrayın. Bu sizin başlangıç pozisyonunuzdur.", "Dirseğinizi bükerken kürek kemiklerinizi geriye çekerek tutamaçları gövdenize doğru çekin.", "Hareketin alt noktasında durun, ardından tutamaçları yavaşça başlangıç pozisyonuna geri getirin.", "Birden fazla tekrar için, çalışan kaslardaki gerginliği korumak amacıyla ağırlığı tamamen duruş noktalarına geri indirmekten kaçının."]', 'strength', '["Leverage_High_Row/0.jpg", "Leverage_High_Row/1.jpg"]', 360.0, 'Leverage High Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a97c54fa-775d-5212-a786-ae6ce1de6742', 'free-exercise-db', 'Leverage_Incline_Chest_Press', 'Incline Chest Press (Leverage Makine)', 'push', 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Pimlere uygun ağırlığı yükleyin ve koltuğu boyunuza göre ayarlayın. Hareketin başında tutamaklar göğüs kaslarının üst kısmına yakın olmalıdır. Göğsünüz ve başınız yukarıda, kürek kemikleriniz geriye çekilmiş olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi açarak tutamakları öne doğru itin.", "Üstte kısa bir beklemeden sonra, set tamamlanana kadar ağırlığı duraklara indirmeyerek kaslardaki gerilimi koruyun ve ağırlığı başlangıç pozisyonunun hemen üzerine getirin."]', 'strength', '["Leverage_Incline_Chest_Press/0.jpg", "Leverage_Incline_Chest_Press/1.jpg"]', 360.0, 'Leverage Incline Chest Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('95ca7443-0f66-51dd-9d70-8d3f89e97811', 'free-exercise-db', 'Leverage_Iso_Row', 'Leverage Iso Row (Makine)', 'pull', 'beginner', 'compound', '["machine"]', '["lats"]', '["biceps", "middle back"]', '["Pinlere uygun bir ağırlık yükleyin ve sapların göğüs seviyesinde olması için koltuk yüksekliğini ayarlayın. Sapları nötr veya pronated (avuç içi aşağı) tutuşla kavrayın. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi bükerken kürek kemiklerinizi geriye çekerek sapları gövdenize doğru çekin.", "Hareketin sonunda bekleyin, ardından sapları yavaşça başlangıç pozisyonuna döndürün. Birden fazla tekrarda, çalışan kaslardaki gerginliği korumak için ağırlığı tamamen duruş noktalarına geri bırakmaktan kaçının."]', 'strength', '["Leverage_Iso_Row/0.jpg", "Leverage_Iso_Row/1.jpg"]', 360.0, 'Leverage Iso Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bc9d359c-1af2-5702-859b-2b5b3b83a4eb', 'free-exercise-db', 'Leverage_Shoulder_Press', 'Omuz Press (Leverage Makine)', 'push', 'beginner', 'compound', '["machine"]', '["shoulders"]', '["triceps"]', '["Pimlere uygun bir ağırlık yükleyin ve koltuğu boyunuza göre ayarlayın. Hareketin başında tutacaklar omuzların üst kısmına yakın olmalıdır. Göğsünüz ve başınız yukarıda olmalı ve tutacaklar pronasyon (avuç içleri öne/aşağı bakan) tutuşla tutulmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseklerinizi açarak tutacakları yukarı doğru itin.", "Üstte kısa bir duraklamanın ardından, set tamamlanana kadar ağırlığı stoplara geri indirmeyerek kaslardaki gerginliği koruyacak şekilde, ağırlığı başlangıç pozisyonunun hemen üstüne getirin."]', 'strength', '["Leverage_Shoulder_Press/0.jpg", "Leverage_Shoulder_Press/1.jpg"]', 360.0, 'Leverage Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('144f32c7-c24a-516a-afc8-356ad7be7767', 'free-exercise-db', 'Leverage_Shrug', 'Shrug (Leverage Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["traps"]', '["forearms"]', '["Pimlere uygun bir ağırlık yükleyin. Tutamakların tam arasında konumlanın.", "Üst tutamakları rahat bir tutuşla kavrayın, ardından nefes alırken kalçanızı alçaltın. Başınızla ileriye bakın ve göğsünüzü yukarıda tutun.", "Topuklarınızla yere basarak, kalçanızı ve dizlerinizi açıp ayakta duruş pozisyonuna yükselin. Hareket boyunca kollarınızı düz tutun ve omuzlarınız geride olacak şekilde bitirin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Omuzlarınızı kulaklarınıza doğru silkerek ağırlığı kaldırın; düz yukarı ve aşağı hareket edin.", "Hareketin üst noktasında bekleyin, ardından ağırlığı başlangıç pozisyonuna geri indirin."]', 'strength', '["Leverage_Shrug/0.jpg", "Leverage_Shrug/1.jpg"]', 360.0, 'Leverage Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f2dcf170-fcd4-5844-9130-23cc833ffb4f', 'free-exercise-db', 'Linear_3-Part_Start_Technique', 'Doğrusal 3 Aşamalı Çıkış Tekniği', 'push', 'beginner', 'compound', '[]', '["hamstrings"]', '["calves", "quadriceps"]', '["Bu çalışma, tam duruştan bir sprinte olabildiğince hızlı ivmelenmenize yardımcı olur. Başlamak için bir çizgi kullanmak faydalıdır. İki ayağınız çizgi üzerinde olacak şekilde başlayın. Sol ayağınızı parmak ucu sağ ayak bileğinizin yanında olacak şekilde yerleştirin. Sağ ayağınızı sol ayağın 10-15 cm gerisine yerleştirin.", "Sağ elinizi çizgiye koyun ve ardından burnunuzu sol dizinize yaklaştırın.", "Öne eğilirken çömelin; başınız kalçanızdan daha aşağıda ve ağırlığınız sol bacağa yüklenmiş olsun. Bu sizin başlangıç pozisyonunuz olacak.", "Sol elinizi yere paralel olacak ve arkanızı gösterecek şekilde kaldırın ve hazır olduğunuzda patlayıcı bir şekilde fırlayın."]', 'plyometrics', '["Linear_3-Part_Start_Technique/0.jpg", "Linear_3-Part_Start_Technique/1.jpg"]', 480.0, 'Linear 3-Part Start Technique', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('30ff9e07-2b93-5255-ace9-11f541588aa9', 'free-exercise-db', 'Linear_Acceleration_Wall_Drill', 'Duvarda Doğrusal İvmelenme Çalışması', NULL, 'beginner', 'compound', '[]', '["hamstrings"]', '["calves", "glutes", "quadriceps"]', '["Bir duvara yaklaşık 45 derece açıyla yaslanın. Ayaklarınız bitişik, kalçanız kasılmış olmalıdır.", "Sağ dizinizi hızla kaldırarak, durup, ardından dümdüz yere doğru sürerek başlayın.", "Bacak değiştirin, karşı dizi kaldırın ve ardından dümdüz yere doğru vurun.", "Sağ bacağınızla bir kez daha tekrarlayın ve sağ ayağınız yere değer değmez, olabildiğince hızlı şekilde sağ ve sol arasında dönüşümlü olarak hızla vurmaya devam edin."]', 'plyometrics', '["Linear_Acceleration_Wall_Drill/0.jpg", "Linear_Acceleration_Wall_Drill/1.jpg"]', 480.0, 'Linear Acceleration Wall Drill', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d1ea860e-85b2-54b2-a9ee-3cc78f545d65', 'free-exercise-db', 'Linear_Depth_Jump', 'Düz Çizgide Depth Jump', 'push', 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Birbirinden birkaç ayak uzakta duran iki kutuya ya da sehpaya ihtiyacınız olacak. Diğer platforma dönük olarak bir kutunun üzerinde ayakta durarak başlayın.", "Hareketi başlatmak için dizlerinizin ve kalçanızın bükülmesine izin vererek platformlarınızın arasındaki yere nazikçe inin.", "Patlayıcı bir şekilde kalçanızı, dizlerinizi ve ayak bileklerinizi açarak diğer platforma zıplayıp hareketi tersine çevirin.", "Darbeyi bacaklarınızla emerek yumuşak bir şekilde inin."]', 'plyometrics', '["Linear_Depth_Jump/0.jpg", "Linear_Depth_Jump/1.jpg"]', 480.0, 'Linear Depth Jump', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5cc6235f-e5db-5f45-8444-783132252443', 'free-exercise-db', 'Log_Lift', 'Log Lift (Strongman)', 'push', 'intermediate', 'compound', '["other"]', '["shoulders"]', '["abdominals", "chest", "glutes", "hamstrings", "lower back", "middle back", "quadriceps", "traps", "triceps"]', '["Kütük önünüzde olacak şekilde ayakta durarak başlayın. Sapları kavrayın ve kütüğü kaldırmaya (clean) başlayın. Clean''e başlamak için eğilmişken kütüğü göğsünüze çekerek olabildiğince yükseğe çıkarmaya çalışın. Clean''i tamamlamak için kalça ve dizlerinizi açarak kütüğü yukarı getirin.", "Başınızı geriye itin ve yukarı bakın; böylece göğsünüzde kütüğü yaslayacağınız bir raf oluşturun. Press''e dizlerinizi hafifçe bükerek çökerek ve hareketi tersine çevirerek başlayın. Bu push press, kütüğü dikey olarak hareket ettirmeye başlayacak ivmeyi üretir. Kütüğü başınızın üzerine itmek için dirseklerinizi açarak devam edin. Form konusunda katı kurallar yoktur; en verimli olduğunuz tekniği kullanın. Kütük itilirken her tekrarda başınızı öne doğru ileri geçirip karşıya baktığınızdan emin olun.", "Olabildiğince çok tekrarlayın. Kütüğü yere indirirken inişi kontrol etmeye çalışın."]', 'strongman', '["Log_Lift/0.jpg", "Log_Lift/1.jpg"]', 480.0, 'Log Lift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ba75c97d-ed0f-57eb-8bb4-164c0536443a', 'free-exercise-db', 'London_Bridges', 'London Bridge (Halat)', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["biceps", "forearms", "middle back"]', '["Yüksek bir kirişe veya çapraz elemana bir tırmanma halatı bağlayın. Altında, Smith makinesi barının güvenlik kilitleriyle yerine kilitlendiğinden ve hareket edemeyeceğinden emin olun. Alternatif olarak sağlam bir box da kullanılabilir.", "Dengenizi sağlamak için halatı kullanarak barın üzerinde durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Vücudunuzu düz tutarak geriye yaslanın ve halatta el üstüne el koyarak yavaşça vücudunuzu aşağı indirin. Yere dik olana kadar devam edin.", "Vücudunuzu düz tutarak hareketi tersine çevirin ve el üstüne el koyarak başlangıç pozisyonuna dönün."]', 'strength', '["London_Bridges/0.jpg", "London_Bridges/1.jpg"]', 360.0, 'London Bridges', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b0a4cf6b-dd8a-5f5d-a14d-5432c1ec1469', 'free-exercise-db', 'Looking_At_Ceiling', 'Tavana Bakma Esnetmesi', 'static', 'beginner', 'isolation', '[]', '["quadriceps"]', '[]', '["Yere diz çökün ve topuklarınızı iki elinizle tutun.", "Sırtınızda bir kavis oluşturmak için kalçanızı yukarı ve ileri doğru kaldırırken başınızı geriye getirerek tavana bakın."]', 'stretching', '["Looking_At_Ceiling/0.jpg", "Looking_At_Ceiling/1.jpg"]', 150.0, 'Looking At Ceiling', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7ea9b833-03ad-5eda-8c78-903818223111', 'free-exercise-db', 'Low_Cable_Crossover', 'Low Cable Crossover', 'push', 'beginner', 'isolation', '["cable"]', '["chest"]', '["shoulders"]', '["Başlangıç pozisyonuna geçmek için makaraları alt konuma getirin, kullanılacak direnci seçin ve her elinizle bir tutamağı kavrayın.", "Makaralardaki gerginliği alacak şekilde öne adım atın. Avuç içleriniz öne bakmalı, eller belin altında ve kollar düz olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı hafif bükülü tutarak ellerinizi yukarı ve vücudunuzun orta çizgisine doğru çekin. Ellerinizin avuç içi yukarı bakacak şekilde göğsünüzün önünde buluşması gerekir.", "Kısa bir duraklamanın ardından kollarınızı başlangıç pozisyonuna geri getirin."]', 'strength', '["Low_Cable_Crossover/0.jpg", "Low_Cable_Crossover/1.jpg"]', 360.0, 'Low Cable Crossover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a097ae58-9ad1-5793-a50f-c74a74a11008', 'free-exercise-db', 'Low_Cable_Triceps_Extension', 'Sırtüstü Alt Kablo Triceps Extension', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["İstediğiniz ağırlığı seçin ve ip bağlı bir oturarak row makinesinin sehpasına yüzü yukarı bakacak şekilde uzanın. Başınız aparata doğru bakmalıdır.", "İpin uçlarının dış kısımlarını avuç içleriniz birbirine bakacak şekilde (nötr tutuş) kavrayın.", "Dirseklerinizi 90 derecelik açıyla bükülü ve üst kollarınızı gövdenize dik (90 derecelik açı) olacak şekilde konumlandırın. İpucu: Dirsekleri içeride tutun ve üst kolların tavana, ön kolların ise başınızın üzerindeki makaraya doğru baktığından emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken ön kollarınızı düz ve dikey olana kadar uzatın. Üst kollar ve dirsekler hareket boyunca sabit kalır. Yalnızca ön kollar hareket etmelidir. Triceps''inizi bir saniye sertçe kasın.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Low_Cable_Triceps_Extension/0.jpg", "Low_Cable_Triceps_Extension/1.jpg"]', 360.0, 'Low Cable Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fc124a06-f8ef-56cc-86f6-0324bde44a6c', 'free-exercise-db', 'Low_Pulley_Row_To_Neck', 'Alçak Makara Boyna Row', 'pull', 'beginner', 'compound', '["cable"]', '["shoulders"]', '["biceps", "middle back", "traps"]', '["İp aparatı olan bir alçak makara row makinesine oturun.", "İpin uçlarını avuç içleri aşağı bakacak şekilde kavrayın ve sırtınız düz, dizleriniz hafifçe bükülü şekilde oturun. İpucu: Sırtınızı neredeyse tamamen dik tutun ve kollarınız önünüzde tamamen uzanmış olsun. Bu sizin başlangıç pozisyonunuz olacak.", "Gövdenizi sabit tutarak, nefes verirken dirseklerinizi kaldırın ve bükmeye başlayın, ipi boynunuza doğru çekin. Hareket boyunca üst kollarınız yere paralel kalmalıdır. İpucu: Ellerinizin neredeyse kulaklarınızın yanında olduğu (ön kollar hareketin sonunda biraz yukarı açılı olacağı için yere paralel olmayacaktır) ve dirseklerinizin yanlarınızdan uzakta, dışarıda olduğu noktaya kadar bu harekete devam edin.", "Kasılmış pozisyonda yaklaşık bir saniye bekledikten sonra nefes alırken yavaşça başlangıç pozisyonuna dönün. İpucu: Yine, hareketin hiçbir bölümünde gövde hareket etmemelidir.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Low_Pulley_Row_To_Neck/0.jpg", "Low_Pulley_Row_To_Neck/1.jpg"]', 360.0, 'Low Pulley Row To Neck', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7a42bb6c-a128-5922-b96e-7989ad2a40ce', 'free-exercise-db', 'Lower_Back-SMR', 'Bel Masajı (Foam Roller)', 'static', 'beginner', NULL, '["foam roll"]', '["lower back"]', '[]', '["Oturma pozisyonunda, bir foam roller''ı belinizin altına yerleştirin. Kollarınızı önünüzde kavuşturun ve omuzlarınızı öne doğru açın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kalçanızı yerden kaldırın ve ağırlığınızı belinizde tutarak geriye yaslanın. Şimdi ağırlığınızı omurgadan uzak tutarak ve omurganın yanındaki kaslara vererek hafifçe bir yana kaydırın. Belinizin üzerinde yuvarlanın ve gerginlik noktalarında 10-30 saniye bekleyin. Diğer tarafta tekrarlayın."]', 'stretching', '["Lower_Back-SMR/0.jpg", "Lower_Back-SMR/1.jpg"]', 150.0, 'Lower Back-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eeae90ec-f81d-5609-b582-e3e255e44d77', 'free-exercise-db', 'Lower_Back_Curl', 'Alt Sırt Curl', 'static', 'beginner', NULL, '["body only"]', '["abdominals"]', '[]', '["Kollarınız yanlara açık şekilde karnınızın üzerine uzanın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Alt sırt kaslarınızı kullanarak omurganızı açın ve göğsünüzü yerden kaldırın. Kendinizi yukarı itmek için kollarınızı kullanmayın. Hareket boyunca başınızı yukarıda tutun. 10-20 tekrar yapın."]', 'stretching', '["Lower_Back_Curl/0.jpg", "Lower_Back_Curl/1.jpg"]', 150.0, 'Lower Back Curl', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('617bda93-348b-5841-9ff8-8314a6926a9c', 'free-exercise-db', 'Lunge_Pass_Through', 'Lunge Pass Through (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["calves", "glutes", "quadriceps"]', '["Sağ elinizde bir kettlebell tutarak gövdeniz dik şekilde durun. Bu sizin başlangıç pozisyonunuzdur.", "Sol ayağınızla öne adım atın ve gövdenizi dik tutarak kalça ve dizinizi bükerek üst vücudunuzu aşağı indirin. Arka dizinizi neredeyse yere değene kadar indirin.", "Lunge yaparken kettlebell''i ön bacağınızın altından karşı elinize geçirin.", "Ayağınızın topuğundan iterek başlangıç pozisyonuna dönün.", "Bacakları dönüşümlü kullanarak hareketi önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lunge_Pass_Through/0.jpg", "Lunge_Pass_Through/1.jpg"]', 360.0, 'Lunge Pass Through', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3bd78fbc-705f-5f2a-9613-417bfb006394', 'free-exercise-db', 'Lunge_Sprint', 'Lunge Sprint (Smith Makinesi)', 'push', 'intermediate', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Smith makinesindeki barı uygun bir yüksekliğe ayarlayın. Barın altına girin ve barı omuzlarınızın arkasına yerleştirin. Barı rack''ten çıkarın, ardından ayaklarınızı ayırarak bir ayağınızı öne, birini arkaya alın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dizlerinizi bükerek ve kalçanızı alçaltarak arka dizinizi neredeyse yere kadar indirin.", "İnişin en alt noktasında hemen yön değiştirin. Arka ayağınızdan hafif bir destekle ön ayağınızın topuğundan patlayıcı bir şekilde itin. Zıplayın ve bacaklarınızın pozisyonunu değiştirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lunge_Sprint/0.jpg", "Lunge_Sprint/1.jpg"]', 360.0, 'Lunge Sprint', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b9137aaf-c8cf-5efa-a2da-3bceb75a69a5', 'free-exercise-db', 'Lying_Bent_Leg_Groin', 'Yatarak İç Bacak Esnetme (Partnerli)', 'static', 'expert', NULL, '["other"]', '["adductors"]', '[]', '["Dizleriniz bükülü ve ayak tabanlarınız birbirine bastırılmış şekilde sırtüstü uzanın. Partnerinizden dizlerinizi tutmasını isteyin. Bu sizin başlangıç pozisyonunuzdur.", "Partneriniz herhangi bir hareketin gerçekleşmesini engellerken dizlerinizi birbirine doğru sıkmaya çalışın.", "10-20 saniye sonra, partneriniz dizlerinizi nazikçe yere doğru iterken kaslarınızı gevşetin. Sakatlanmayı veya aşırı esnemeyi önlemek için esneme yeterli olduğunda yardımcınıza haber verdiğinizden emin olun."]', 'stretching', '["Lying_Bent_Leg_Groin/0.jpg", "Lying_Bent_Leg_Groin/1.jpg"]', 150.0, 'Lying Bent Leg Groin', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bc253605-4f6e-555a-b660-1e64f81106ff', 'free-exercise-db', 'Lying_Cable_Curl', 'Yatarak Biceps Curl (Kablo)', 'pull', 'intermediate', 'isolation', '["cable"]', '["biceps"]', '[]', '["Alçak makaraya bağlı düz bir barı veya EZ bar aparatını her iki elinizle, omuz genişliğinde alttan (avuç içleri yukarı bakan) bir tutuşla kavrayın.", "Ağırlık bloğunun önünde bir egzersiz matı üzerine sırtüstü uzanın; ayaklarınız makaranın çerçevesine düz basmalı ve bacaklarınız düz olmalıdır.", "Kollarınız uzamış ve dirsekleriniz vücudunuza yakınken kollarınızı hafifçe bükün. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kollarınızı sabit ve dirseklerinizi vücudunuza yakın tutarak, nefes verirken ve biceps''inizi sıkarak barı yavaşça göğsünüze doğru curl yapın.", "Hareketin üst noktasında bir saniyelik sıkmanın ardından yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Cable_Curl/0.jpg", "Lying_Cable_Curl/1.jpg"]', 360.0, 'Lying Cable Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a529c36e-4d64-5b72-b68b-bdcf90c2a49c', 'free-exercise-db', 'Lying_Cambered_Barbell_Row', 'Yüzüstü Cambered Bar Row', 'pull', 'beginner', 'isolation', '["barbell"]', '["middle back"]', '["biceps", "lats", "traps"]', '["Bir cambered (eğimli) barı egzersiz sehpasının altına yerleştirin.", "Egzersiz sehpasına yüzüstü uzanın ve barı omuz genişliğinden geniş, avuç içleri aşağı (pronasyon) bir tutuşla kavrayın. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken dirseklerinizi vücudunuza yakın tutarak barı üst-orta sırtı hedeflemek için göğsünüze, ya da lat kaslarını hedeflemek istiyorsanız karnınıza doğru çekin.", "Üstte bir saniye bekledikten sonra nefes alırken yavaşça başlangıç pozisyonuna indirin."]', 'strength', '["Lying_Cambered_Barbell_Row/0.jpg", "Lying_Cambered_Barbell_Row/1.jpg"]', 360.0, 'Lying Cambered Barbell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5547dc29-f171-54d2-a4cc-ef8f4fbabfd6', 'free-exercise-db', 'Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'Yatarak Biceps Curl (Üst Makara, Dar Tutuş)', 'pull', 'beginner', 'isolation', '["cable"]', '["biceps"]', '[]', '["Yüksek bir makaranın veya lat pulldown makinesinin önüne düz bir sehpa yerleştirin.", "Düz bar aparatını alttan tutuşla (avuç içleri yukarı) yaklaşık omuz genişliğinde kavrayın.", "Başınız sehpanın ucundan sarkacak şekilde sırtüstü uzanın.", "Şimdi kollarınızı omuzlarınızın tam üzerinde düz şekilde uzatın. Gövdeniz ve kollarınız 90 derecelik açı oluşturmalı ve dirsekler içeride olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken barı yarım daire hareketiyle çenenize değene kadar kıvırın. Üst kasılma noktasında biceps''i bir saniye sıkın. İpucu: Bu hareketi yaparken yalnızca ön kollar hareket etmelidir. Üst kollar hiçbir zaman hareket etmemelidir. Hareket boyunca dik kalmalıdırlar.", "Yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg", "Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg"]', 360.0, 'Lying Close-Grip Bar Curl On High Pulley', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('936af7de-e65d-510c-b46d-7f80ac6c16b9', 'free-exercise-db', 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'Yatarak Triceps Extension (Halter, Dar Tutuş, Baş Arkası)', 'push', 'intermediate', 'isolation', '["barbell"]', '["triceps"]', '[]', '["Pronated tutuşla (avuç içleri öne bakacak şekilde) bir halter ya da EZ Curl bar tutarken, başınız bankın ucuna yakın olacak şekilde düz bir bankta sırtüstü uzanın. İpucu: Halter tutuyorsanız omuz genişliğinde bir tutuşla, EZ Bar kullanıyorsanız iç saplardan kavrayın.", "Kollarınızı önünüze uzatın ve (kolları uzatılmış tutarak) barı yarım daire çizerek yavaşça başınızın üzerindeki bir pozisyona geri getirin. Bu adımın sonunda kolunuz baş üstünde ve yere paralel olmalıdır. Bu sizin başlangıç pozisyonunuzdur. İpucu: Dirseklerinizi her zaman içeride tutun.", "Nefes alırken, üst kolu sabit tutarak dirseklerinizi bükerek barı indirin. Ön kollarınız yere dik olana kadar barı indirmeye devam edin.", "Nefes verirken barı yarım daire çizerek, alt kollar da yere paralel olana kadar yukarı iterek başlangıç pozisyonuna getirin. Hareketin en üstünde triceps''i bir saniye boyunca sert şekilde kasın. İpucu: Yine, yalnızca ön kollar hareket etmelidir. Üst kollar her zaman sabit kalmalıdır.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg", "Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg"]', 360.0, 'Lying Close-Grip Barbell Triceps Extension Behind The Head', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3b5349b6-10db-5c67-aef0-9211477d92da', 'free-exercise-db', 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'Yatarak Çeneye Triceps Press (Halter, Dar Tutuş)', 'push', 'intermediate', 'isolation', '["e-z curl bar"]', '["triceps"]', '[]', '["Bir halteri veya EZ Curl barını pronasyon tutuşla (avuç içleri ileri bakacak şekilde) tutarken, başınız bench''in ucundan dışarıda olacak şekilde düz bir bench üzerine sırtüstü uzanın. İpucu: Halter kullanıyorsanız omuz genişliğinde bir tutuşla, EZ Bar kullanıyorsanız iç saplardan tutun.", "Halteri göğsünüzün üzerinde tutarken kollarınızı önünüze doğru uzatın. Kollar gövdenize dik (90 derecelik açı) olmalıdır. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes alırken, üst kolu sabit ve dirsekleri içeride tutarak dirseklerden bükülerek halteri yarım daire hareketiyle indirin. Halter çenenize hafifçe değene kadar indirmeye devam edin.", "Nefes verirken halteri yarım daire hareketiyle yukarı iterek başlangıç pozisyonuna geri getirin. Hareketin üst noktasında triceps''i bir saniye boyunca sertçe kasın. İpucu: Yine, sadece ön kollar hareket etmelidir. Üst kollar her zaman sabit kalmalıdır.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg", "Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/1.jpg"]', 360.0, 'Lying Close-Grip Barbell Triceps Press To Chin', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8c75b75a-c50d-547c-a299-944455f65c6e', 'free-exercise-db', 'Lying_Crossover', 'Yatarak Çapraz Bacak Esnetme', 'static', 'expert', NULL, '["body only"]', '["abductors"]', '[]', '["Sırtüstü uzanın ve bacaklarınızı uzatın.", "Bir bacağınızı dizi bükülü halde vücudunuzun üzerinden çaprazlayın ve dizinizi yere değdirmeye çalışın. Partneriniz yanınızda diz çökmeli, bir eliyle omzunuzu aşağıda tutmalı ve diğer eliyle çaprazlanan bacağı kontrol etmelidir. Bu sizin başlangıç pozisyonunuz olacaktır.", "Partneriniz gerçek bir harekete izin vermezken bükülü dizinizi yerden kaldırmaya çalışın.", "10-20 saniye sonra, partneriniz dizi nazikçe yere doğru bastırırken bacağınızı gevşetin. Diğer tarafla tekrarlayın."]', 'stretching', '["Lying_Crossover/0.jpg", "Lying_Crossover/1.jpg"]', 150.0, 'Lying Crossover', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f6d78ad5-17ff-50c1-8e1c-5f7463cd70c6', 'free-exercise-db', 'Lying_Dumbbell_Tricep_Extension', 'Yatarak Triceps Extension (Dambıl)', 'push', 'intermediate', 'isolation', '["dumbbell"]', '["triceps"]', '["chest", "shoulders"]', '["Düz bir bench üzerine uzanın ve iki dambılı tam önünüzde tutun. Kollarınız gövdenizden ve yerden 90 derecelik açıyla tamamen uzamış olmalıdır. Avuç içleri birbirine bakmalı ve dirsekler içeride olmalıdır. Bu başlangıç pozisyonudur.", "Nefes alırken ve üst kollarınızı dirsekler içeride sabit tutarak, dambıllar kulaklarınızın yakınına gelene kadar ağırlığı yavaşça indirin.", "Bu noktada dirsekleri içeride ve üst kolları sabit tutarak, nefes verirken triceps''i kullanarak ağırlığı başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Dumbbell_Tricep_Extension/0.jpg", "Lying_Dumbbell_Tricep_Extension/1.jpg"]', 360.0, 'Lying Dumbbell Tricep Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d412a4d6-adfe-5a37-8648-f7f39ffefa8c', 'free-exercise-db', 'Lying_Face_Down_Plate_Neck_Resistance', 'Yüzüstü Plaka ile Boyun Direnci', 'pull', 'intermediate', 'isolation', '["other"]', '["neck"]', '[]', '["Düz bir sehpada tüm vücudunuz düz olacak şekilde yüzüstü uzanın ve başınızın arkasında bir ağırlık plakası tutun. İpucu: Üst göğsünüzün, boynunuzun ve yüzünüzün sehpanın dışında kalması için omuzlarınız düz sehpanın ucunun biraz üzerinde olacak şekilde konumlanmanız gerekir. Bu sizin başlangıç pozisyonunuzdur.", "Plakayı başınızın arkasında sabit tutarak nefes alırken başınızı (\"evet\" der gibi) yavaşça indirin.", "Nefes verirken başınızı yarım daire hareketiyle başlangıç pozisyonuna kaldırın. Kasılmayı bir saniye tutun.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Face_Down_Plate_Neck_Resistance/0.jpg", "Lying_Face_Down_Plate_Neck_Resistance/1.jpg"]', 360.0, 'Lying Face Down Plate Neck Resistance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('127da930-4ea8-5c5c-868a-3ce4484e4963', 'free-exercise-db', 'Lying_Face_Up_Plate_Neck_Resistance', 'Sırtüstü Boyun Direnci (Plaka)', 'pull', 'intermediate', 'isolation', '["other"]', '["neck"]', '[]', '["Düz bir bench üzerinde tüm vücudunuz düz şekilde sırtüstü uzanın ve bir ağırlık plakasını alnınızın üzerinde tutun. İpucu: Trapez kaslarınızın, boynunuzun ve başınızın bench''in dışında kalması için omuzlarınız düz bench''in ucunun biraz üzerinde olacak şekilde konumlanmanız gerekir. Bu sizin başlangıç pozisyonunuz olacaktır.", "Plakayı alnınızda sabit tutarak, nefes alırken başınızı yarım daire hareketiyle yavaşça geriye doğru indirin.", "Nefes verirken başınızı yarım daire hareketiyle başlangıç pozisyonuna geri kaldırın. Kasılmayı bir saniye tutun.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Face_Up_Plate_Neck_Resistance/0.jpg", "Lying_Face_Up_Plate_Neck_Resistance/1.jpg"]', 360.0, 'Lying Face Up Plate Neck Resistance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('373a4bf1-e665-552e-821d-164169181115', 'free-exercise-db', 'Lying_Glute', 'Yatarak Kalça Esnetme (Partnerli)', 'static', 'expert', NULL, '["body only"]', '["glutes"]', '["abductors"]', '["Partneriniz yanınızda diz çökmüşken sırtüstü uzanın.", "Bir bacağın kalçasını bükerek yerden kaldırın. Bacağı, ayak karşı kalçanın üzerinde ve alt bacak vücudunuza dik olacak şekilde döndürün. Partneriniz dizi ve ayak bileğini yerinde tutmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Partneriniz bacağın gerçekten hareket etmesini engellerken bacağınızı partnerinize doğru itmeye çalışın.", "10-20 saniye sonra tamamen gevşeyin; partneriniz ayak bileğini ve dizi nazikçe göğsünüze doğru itsin. Sakatlanmayı veya aşırı esnemeyi önlemek için esneme yeterli olduğunda yardımcınıza haber verdiğinizden emin olun."]', 'stretching', '["Lying_Glute/0.jpg", "Lying_Glute/1.jpg"]', 150.0, 'Lying Glute', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b2d8f8da-b329-5401-aae4-2a3eae475be2', 'free-exercise-db', 'Lying_Hamstring', 'Yatarak Arka Bacak Esnetme (Partnerli)', 'static', 'expert', NULL, '["other"]', '["hamstrings"]', '["calves"]', '["Bacaklarınız uzamış halde sırtüstü uzanın. Partneriniz yanınızda diz çökmüş olmalıdır. Bir bacağınızı tavana doğru kaldırın ve partnerinizin ayak bileğini tutmasını sağlayın. Gerekirse partneriniz bacağınızı desteklemek için omzunu kullanabilir. Bu sizin başlangıç pozisyonunuz olacaktır.", "Partneriniz bacağınızı yerinde tutarken, 10-20 saniye boyunca arka bacak kaslarınızı kasarak dizinizi bükmeye çalışın.", "Ardından bacağınızı gevşetin ve partnerinizin bacağınızı nazikçe başınıza doğru itmesine izin verin. Sakatlanmayı veya aşırı esnemeyi önlemek için esneme yeterli olduğunda yardımcınıza haber verdiğinizden emin olun. Tamamlandığında taraf değiştirin."]', 'stretching', '["Lying_Hamstring/0.jpg", "Lying_Hamstring/1.jpg"]', 150.0, 'Lying Hamstring', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('77a53f5e-c31b-55ca-8cac-67d3a96e73aa', 'free-exercise-db', 'Lying_High_Bench_Barbell_Curl', 'Yüksek Bench''te Yüzüstü Curl (Halter)', 'pull', 'intermediate', 'isolation', '["barbell"]', '["biceps"]', '[]', '["Supinasyon tutuşla (avuç içleri yukarı bakacak şekilde) bir halteri tutarken yüksek bir düz bench üzerine yüzüstü uzanın. İpucu: Halter kullanıyorsanız omuz genişliğinde bir tutuşla, EZ Bar kullanıyorsanız iç saplardan tutun. Üst vücudunuz, üst göğsünüz bench''in ucunun üzerinde olacak ve halter kollarınız uzanmış ve yere dik olacak şekilde önünüzde asılı duracak biçimde konumlanmalıdır. Bu sizin başlangıç pozisyonunuz olacak.", "Dirseklerinizi içeride ve üst kollarınızı sabit tutarak, biceps''i kasıp nefes verirken ağırlığı yarım daire hareketiyle yukarı kıvırın. Hareketin üst noktasında bir saniye bekleyin.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün. İpucu: Ağırlık üzerinde her zaman tam kontrolü sürdürün ve sallanmaktan kaçının. Unutmayın, hareket boyunca sadece ön kollar hareket etmelidir.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_High_Bench_Barbell_Curl/0.jpg", "Lying_High_Bench_Barbell_Curl/1.jpg"]', 360.0, 'Lying High Bench Barbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e77ceefe-c2fe-551a-80f1-9fc0694b2aeb', 'free-exercise-db', 'Lying_Leg_Curls', 'Yüzüstü Leg Curl (Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["hamstrings"]', '[]', '["Makine kolunu boyunuza göre ayarlayın ve kolun pedi bacaklarınızın arkasında (baldırların birkaç santim altında) olacak şekilde leg curl makinesine yüzüstü uzanın. İpucu: Açılı bir pozisyon arka bacak kaslarının devreye girmesi için daha uygun olduğundan, mümkünse düz yerine açılı bir leg curl makinesi kullanın.", "Gövdenizi sehpada düz tutarak bacaklarınızın tamamen uzandığından emin olun ve makinenin yan tutamaklarını kavrayın. Ayak parmaklarınızı düz konumlandırın (ya da ayak konumlandırma bölümünde anlatılan diğer iki duruştan herhangi birini de kullanabilirsiniz). Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken üst bacaklarınızı pedden kaldırmadan bacaklarınızı olabildiğince yukarı kıvırın. Tam kasılmış pozisyona ulaştığınızda bir saniye bekleyin.", "Nefes alırken bacaklarınızı başlangıç pozisyonuna geri getirin. Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Leg_Curls/0.jpg", "Lying_Leg_Curls/1.jpg"]', 360.0, 'Lying Leg Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ab762b90-8fc0-50fe-bcfc-01919c0425a7', 'free-exercise-db', 'Lying_Machine_Squat', 'Yatarak Squat (Makine)', 'push', 'intermediate', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bacak makinesini, dizleriniz bükülü ve uyluklarınız paralelin biraz altında olacak şekilde içine girmenize izin verecek bir yüksekliğe ayarlayın.", "Ağırlığı seçtikten sonra, makinenin içinde yüzünüz yukarı bakacak, dizleriniz bükülü ve uyluklarınız platforma paralelin biraz altında olacak şekilde konumlanın. Dizlerinizin ayak parmaklarınızı geçmediğinden emin olun. Arka bacaklar ile baldırlar arasında oluşan açı 90 dereceden biraz daha az olmalıdır (başlangıç pozisyonunuz paralelin biraz altında başlamayı gerektirdiği için). Sırtınız ve başınız makineye yaslanmalı, omuzlarınız omuz padlerinin altında bastırılmış olmalıdır.", "Ellerinizi saplara yerleştirin ve ayaklarınızı omuz genişliğinde, hafifçe dışa bakacak şekilde konumlandırın. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken ayakların ön kısmıyla iterek quadriceps''i sıkarak tüm vücudunuzu dikleştirin. Kasılmış pozisyonu bir saniye tutun. İpucu: Paralelin altından başladığınız için, yalnızca ilk tekrarda ellerinizi uyluklarınıza bastırarak kalkmanıza yardımcı olmak için kullanmayı tercih edebilirsiniz.", "Nefes alırken yavaşça çömelin, ancak başlangıç pozisyonuna kadar inmek yerine, uyluklarınız platforma paralel olduğunda durun. Arka bacaklar ile baldırlar arasındaki açı 90 derece olmalıdır.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Machine_Squat/0.jpg", "Lying_Machine_Squat/1.jpg"]', 360.0, 'Lying Machine Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('54b91745-d3de-5ea2-b5a9-00d5f591ae0c', 'free-exercise-db', 'Lying_One-Arm_Lateral_Raise', 'Yüzüstü Tek Kol Lateral Raise (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Bir elinizde dambıl tutarken göğsünüz aşağı bakacak şekilde düz bir bench''e uzanın. Diğer elinizle denge için bench''in ayağını tutabilirsiniz.", "Dambılı tutan elin avuç içini nötr pozisyonda (avuç içi gövdenize bakacak şekilde) konumlandırın ve kolunuzu dirseğiniz hafifçe bükülü olarak uzatılmış halde tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes verirken dambılı tutan kolunuzu dirseğiniz omuz yüksekliğine gelene ve kolunuz yaklaşık yere paralel olana kadar yana kaldırın. İpucu: Hareket boyunca kolunuzu uzatılmış halde tutarken gövdeye dik tutun. Ayrıca üst noktada kasılmayı bir saniye koruyun.", "Nefes alırken dambılı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_One-Arm_Lateral_Raise/0.jpg", "Lying_One-Arm_Lateral_Raise/1.jpg"]', 360.0, 'Lying One-Arm Lateral Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('33e7fab8-5541-55c5-a983-edbf7c4e308c', 'free-exercise-db', 'Lying_Prone_Quadriceps', 'Yüzüstü Ön Bacak Esnetme (Partnerli)', NULL, 'expert', NULL, '["body only"]', '["quadriceps"]', '[]', '["Partneriniz yanınızda diz çökmüşken yerde yüzüstü uzanın. Bir dizinizi bükün ve o bacağı yerden kaldırarak ayağınızla kalçanıza dokunmaya çalışın. Partneriniz dizi ve ayak bileğini tutmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Partneriniz gerçekten herhangi bir hareketi engellerken dizinizi açmaya çalışın.", "10-20 saniye sonra, partneriniz ayağı nazikçe kalçanıza doğru iterek ön bacak kaslarını ve kalça fleksörlerini daha da esnetirken kaslarınızı gevşetin.", "10-20 saniye sonra taraf değiştirin."]', 'stretching', '["Lying_Prone_Quadriceps/0.jpg", "Lying_Prone_Quadriceps/1.jpg"]', 150.0, 'Lying Prone Quadriceps', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4295cf5e-58e8-5afa-8206-4eb37789b3fa', 'free-exercise-db', 'Lying_Rear_Delt_Raise', 'Yüzüstü Arka Omuz Raise (Dambıl) – Lying Rear Delt Raise', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Her elinizde bir dambıl tutarken göğsünüz aşağı bakacak şekilde düz bir bench üzerine uzanın.", "Avuç içlerinizi nötr pozisyonda (avuç içleri gövdenize bakacak şekilde) konumlandırın ve kollarınızı dirsekler hafifçe bükülü şekilde uzatılmış halde tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes verirken, dirsekleriniz omuz hizasına gelene ve kollarınız yere yaklaşık paralel olana kadar kollarınızı yana doğru kaldırın. İpucu: Hareket boyunca kollarınızı gövdenize dik ve uzamış halde tutun. Ayrıca üst noktadaki kasılmayı bir saniye koruyun.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın ve ardından diğer kola geçin."]', 'strength', '["Lying_Rear_Delt_Raise/0.jpg", "Lying_Rear_Delt_Raise/1.jpg"]', 360.0, 'Lying Rear Delt Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1468f8d3-2a7d-583c-9c7c-3df29d8e6a79', 'free-exercise-db', 'Lying_Supine_Dumbbell_Curl', 'Sırtüstü Biceps Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Düz bir sehpada yüzü yukarı bakacak şekilde uzanın; her elinizde uyluklarınızın üzerinde birer dambıl tutun.", "Dambılları kollarınız uzanmış ve avuç içleriniz uyluklarınıza bakacak şekilde (nötr tutuş) yanlara getirin.", "Kollarınızı gövdenize yakın ve dirseklerinizi içeride tutarak, kollarınızı (dirseklerde hafif bükülü şekilde uzanmış halde tutarak) yavaşça yere doğru gidebildiğiniz kadar aşağı indirin. Daha fazla aşağı inemediğinizde üst kollarınızı o pozisyonda kilitleyin; bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken ağırlıkları yavaşça kıvırmaya başlayın ve aynı anda avuç içleri yukarı bakacak şekilde bileklerinizi döndürün. Biceps''leriniz tamamen kasılana kadar ağırlığı kıvırmaya devam edin ve üst pozisyonda bir saniye sertçe sıkın. İpucu: Yalnızca ön kollar hareket etmelidir. Üst kollar sabit kalmalı ve dirsekler hareket boyunca içeride kalmalıdır.", "Çok yavaş bir şekilde başlangıç pozisyonuna dönün."]', 'strength', '["Lying_Supine_Dumbbell_Curl/0.jpg", "Lying_Supine_Dumbbell_Curl/1.jpg"]', 360.0, 'Lying Supine Dumbbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4d994bb3-2c8f-5e64-996e-960a350e8bb9', 'free-exercise-db', 'Lying_T-Bar_Row', 'Yüzüstü T-Bar Row', 'pull', 'intermediate', 'compound', '["machine"]', '["middle back"]', '["biceps", "lats"]', '["T-bar Row makinesini istediğiniz ağırlıkla yükleyin ve üst göğsünüz minderin üst kısmında olacak şekilde bacak yüksekliğini ayarlayın. İpucu: Bazı makinelerde yapabileceğiniz tek şey, üst göğsünüzün minderin üstünde olmasını sağlayan yükseklikte uygun basamağın üzerinde durmaktır.", "Yüzüstü minderin üzerine uzanın ve sapları kavrayın. Sırtınızın hangi bölgesini vurgulamak istediğinize bağlı olarak avuç içleri aşağı, yukarı veya içe bakacak şekilde tutabilirsiniz.", "Barı raftan kaldırın ve kollarınızı önünüze uzatın. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken ağırlığı yavaşça yukarı çekin ve hareketin üst noktasında sırtınızı sıkın. İpucu: Sırt kaslarını daha iyi devreye sokmak için hareket boyunca üst kolları gövdeye mümkün olduğunca yakın tutun. Ayrıca vücudunuzu hiçbir zaman minderden kaldırmayın ve ağırlığı kaldırmak için biceps''i kullanmaktan kaçının.", "Hareketin üst noktasında bir saniyelik kasılmadan sonra, nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_T-Bar_Row/0.jpg", "Lying_T-Bar_Row/1.jpg"]', 360.0, 'Lying T-Bar Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ee8f38c2-d946-54fa-ad92-f770a1a7c829', 'free-exercise-db', 'Lying_Triceps_Press', 'Yatarak Triceps Press (EZ Bar)', 'push', 'intermediate', 'isolation', '["e-z curl bar"]', '["triceps"]', '[]', '["Başınızın arkasında yerde bir EZ bar (benim tercihim) veya düz bar bulunacak ve ayaklarınız yerde olacak şekilde düz sehpaya uzanın.", "Arkanızdaki barı orta genişlikte üstten (pronasyon) tutuşla kavrayın ve barı önünüzde kol boyu yukarı kaldırın. İpucu: Kollar gövdenize ve yere dik olmalıdır. Dirsekler içeride olmalıdır. Bu başlangıç pozisyonudur.", "Nefes alırken üst kollarınızı ve dirseklerinizi sabit tutarak bar alnınıza hafifçe değene kadar ağırlığı yavaşça indirin.", "Bu noktada nefes verirken triceps''i kullanarak ağırlığı başlangıç pozisyonuna geri kaldırın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Lying_Triceps_Press/0.jpg", "Lying_Triceps_Press/1.jpg"]', 360.0, 'Lying Triceps Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a89a2122-8580-536c-ba55-a210c0b6fbec', 'free-exercise-db', 'Machine_Bench_Press', 'Bench Press (Makine)', 'push', 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Chest press makinesine oturun ve ağırlığı seçin.", "Tutamakları öne getirmenize yardımcı olacağı için makinenin sağladığı pedala basın; böylece tutamakları kavrayıp kollarınızı tamamen uzatabilirsiniz.", "Tutamakları avuç içleri aşağı bakacak şekilde kavrayın ve üst kollarınız gövdenizin yanlarında yere paralel olacak şekilde dirseklerinizi kaldırın. İpucu: Tutamakları kavradığınız için ön kollarınız öne bakacaktır. Tutamakları öne getirip kollarınızı uzattığınızda başlangıç pozisyonunda olacaksınız.", "Şimdi nefes alırken tutamakları kendinize doğru geri getirin.", "Göğüs kaslarınızı kasarak ve nefes vererek tutamakları kendinizden uzağa itin. Başlangıç pozisyonuna dönmeden önce kasılmayı bir saniye tutun.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde pedala tekrar basın ve tutamakları yavaşça orijinal yerlerine geri getirin."]', 'strength', '["Machine_Bench_Press/0.jpg", "Machine_Bench_Press/1.jpg"]', 360.0, 'Machine Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('25a88463-cba7-5d75-a656-fbf7096a64fa', 'free-exercise-db', 'Machine_Bicep_Curl', 'Biceps Curl (Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["biceps"]', '[]', '["Koltuğu uygun yüksekliğe ayarlayın ve ağırlığınızı seçin. Üst kollarınızı pedlere yaslayın ve tutacakları kavrayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi bükerek ve alt kolunuzu üst koluna doğru çekerek hareketi gerçekleştirin.", "Hareketin üst noktasında duraklayın ve ardından ağırlığı yavaşça başlangıç pozisyonuna geri getirin.", "Çalışan kaslardaki gerginliği korumak için set tamamlanana kadar ağırlığı tamamen stoplara indirmekten kaçının."]', 'strength', '["Machine_Bicep_Curl/0.jpg", "Machine_Bicep_Curl/1.jpg"]', 360.0, 'Machine Bicep Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5477692d-1b32-5bb5-8884-dc5dbcb3910c', 'free-exercise-db', 'Machine_Preacher_Curls', 'Preacher Curl (Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["biceps"]', '[]', '["Preacher Curl makinesine oturun ve ağırlığı seçin.", "Üst kollarınızın arkasını (triceps) sağlanan preacher pedine yerleştirin ve sapları avuç içleri yukarı bakacak (underhand) tutuşla kavrayın. İpucu: Kolları pede yerleştirirken dirseklerinizi içeride tuttuğunuzdan emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes verirken biceps''i kasarak sapları kaldırın. Pozisyonun en üstünde kasılmayı bir saniye tuttuğunuzdan emin olun. İpucu: Yalnızca ön kollar hareket etmelidir. Üst kollar her zaman sabit kalmalı ve pedin üzerinde olmalıdır.", "Nefes alırken sapları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Machine_Preacher_Curls/0.jpg", "Machine_Preacher_Curls/1.jpg"]', 360.0, 'Machine Preacher Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8056d6a0-6e01-556f-a722-70f1f9e06e6e', 'free-exercise-db', 'Machine_Shoulder_Military_Press', 'Shoulder Press (Makine)', 'push', 'beginner', 'compound', '["machine"]', '["shoulders"]', '["triceps"]', '["Shoulder Press makinesine oturun ve ağırlığı seçin.", "Dirsekleriniz bükülü ve gövdenizle aynı hizada olacak şekilde tutamaçları yanlarınızdan kavrayın. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes verirken tutamaçları kaldırın ve kollarınızı tamamen açın. Üst noktada kasılmayı bir saniye tuttuğunuzdan emin olun.", "Nefes alırken tutamaçları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Machine_Shoulder_Military_Press/0.jpg", "Machine_Shoulder_Military_Press/1.jpg"]', 360.0, 'Machine Shoulder (Military) Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f9b12752-3d16-5569-bed5-8fd06ebd469d', 'free-exercise-db', 'Machine_Triceps_Extension', 'Triceps Extension (Makine)', 'push', 'beginner', 'isolation', '["machine"]', '["triceps"]', '[]', '["Koltuğu uygun yüksekliğe ayarlayın ve ağırlığınızı seçin. Üst kollarınızı pedlere yaslayın ve tutacakları kavrayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi açarak ve alt kolunuzu üst kolunuzdan uzağa iterek hareketi gerçekleştirin.", "Hareketin sonunda duraklayın ve ardından ağırlığı yavaşça başlangıç pozisyonuna geri getirin.", "Çalışan kaslardaki gerginliği korumak için set tamamlanana kadar ağırlığı tamamen stoplara indirmekten kaçının."]', 'strength', '["Machine_Triceps_Extension/0.jpg", "Machine_Triceps_Extension/1.jpg"]', 360.0, 'Machine Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ca38c4f6-b484-546f-93c3-e07ff2d39916', 'free-exercise-db', 'Medicine_Ball_Chest_Pass', 'Sağlık Topu Göğüs Pası', 'push', 'beginner', 'compound', '["medicine ball"]', '["chest"]', '["shoulders", "triceps"]', '["Bu egzersiz için bir partnere ihtiyacınız var. Partneriniz yoksa bu hareket duvara karşı yapılabilir.", "Partnerinize dönük olarak sağlık topunu iki elinizle gövdenizde tutarak başlayın.", "Topu göğsünüze çekin ve dirseklerinizi açarak hareketi tersine çevirin. Spor uygulamaları için atış yaparken bir adım atabilirsiniz.", "Partneriniz topu yakalamalı ve size geri atmalıdır.", "Atışı iki elinizle göğüs hizasında karşılayın."]', 'plyometrics', '["Medicine_Ball_Chest_Pass/0.jpg", "Medicine_Ball_Chest_Pass/1.jpg"]', 480.0, 'Medicine Ball Chest Pass', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('33f40bcd-f376-5cca-8228-e0f1d4b10ba6', 'free-exercise-db', 'Medicine_Ball_Full_Twist', 'Full Twist (Medicine Ball)', 'pull', 'beginner', 'compound', '["medicine ball"]', '["abdominals"]', '["shoulders"]', '["Bu egzersiz için bir medicine ball''a ve bir partnere ihtiyacınız olacak. Partnerinizle sırt sırta, aranızda 60-90 cm mesafe olacak şekilde durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Topu gövdenizin önünde tutun. Kalçanızı açın ve omuzlarınızı partnerinizle aynı anda çevirin.", "Tam dönüş için siz ve partneriniz aynı yöne, yani saat yönünün tersine dönmelisiniz.", "Topu partnerinize verin, ardından her ikiniz de işlemi tekrarlamak için ters yöne dönebilirsiniz."]', 'plyometrics', '["Medicine_Ball_Full_Twist/0.jpg", "Medicine_Ball_Full_Twist/1.jpg"]', 480.0, 'Medicine Ball Full Twist', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b0e95458-ed2f-5a07-a2a2-40dc51512395', 'free-exercise-db', 'Medicine_Ball_Scoop_Throw', 'Medicine Ball Scoop Throw', 'push', 'beginner', 'compound', '["medicine ball"]', '["shoulders"]', '["abdominals", "hamstrings", "quadriceps"]', '["Elinizde bir medicine ball ile yarım çömelme duruşu alın. Kollarınız top ayaklarınızın yakınında olacak şekilde sarkmalı.", "Bacaklarınızı açarak ve zıplayarak kalçanızı öne doğru iterek başlayın.", "Bunu yaparken kollarınızı uzanmış tutarak yukarı ve başınızın üzerinden sallayın ve hareketin zirvesinde topu bırakın. Amaç, topu arkanıza doğru olabildiğince uzağa atmaktır."]', 'plyometrics', '["Medicine_Ball_Scoop_Throw/0.jpg", "Medicine_Ball_Scoop_Throw/1.jpg"]', 480.0, 'Medicine Ball Scoop Throw', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0518aa2f-fee9-5bb8-b066-3770bc968fb6', 'free-exercise-db', 'Middle_Back_Shrug', 'Orta Sırt Shrug (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["middle back"]', '[]', '["Her elinizde bir dambıl tutarak incline sehpaya yüzüstü uzanın. Kollarınız tamamen uzamış, aşağı sarkmış ve yere bakıyor olmalıdır. Avuç içleriniz birbirine bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken kürek kemiklerinizi birbirine sıkın ve kasılmayı tam bir saniye tutun. İpucu: Bu hareket, bir sarılmanın tersi gibidir veya kollarınız yokmuş gibi rear lateral yapmaya benzer.", "Nefes alırken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Middle_Back_Shrug/0.jpg", "Middle_Back_Shrug/1.jpg"]', 360.0, 'Middle Back Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0855ca81-0101-5d67-83dd-bb491b9a97a2', 'free-exercise-db', 'Middle_Back_Stretch', 'Orta Sırt Esnetme', 'static', 'beginner', 'isolation', '[]', '["middle back"]', '["abdominals", "lats", "lower back"]', '["Ayaklarınız omuz genişliğinde açık ve elleriniz kalçanızda olacak şekilde durun.", "Bir esneme hissedene kadar belinizden dönün. 10 ila 15 saniye bekleyin, ardından diğer tarafa dönün."]', 'stretching', '["Middle_Back_Stretch/0.jpg", "Middle_Back_Stretch/1.jpg"]', 150.0, 'Middle Back Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2f0ee4c8-1f42-5e08-98ff-123e34c627e2', 'free-exercise-db', 'Mixed_Grip_Chin', 'Karışık Tutuş Chin-Up', 'pull', 'expert', 'compound', '["other"]', '["middle back"]', '["biceps", "lats"]', '["Omuz genişliğinden yaklaşık 2,5 cm daha geniş bir aralıkla, bir elinizin avuç içi öne, diğerinin avuç içi size bakacak şekilde bir barfiks barını kavrayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes verirken kendinizi yukarı çekmeye başlayın. İpucu: Avuç içi yukarı bakan kolda, hareketi yapmak için sırt kaslarını kullanmaya odaklanın. O kolun dirseği gövdeye yakın kalmalıdır. Avuç içi öne bakan diğer kolda ise dirsek uzakta ama gövdeyle aynı hizada olacaktır. Vücudunuzu yukarı çekmek için lat kaslarını kullanmaya odaklanacaksınız.", "Üstte bir saniyelik kasılmanın ardından nefes alırken yavaşça aşağı inmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bir sonraki sette tutuşları değiştirin; yani sağ elinizin avuç içi size, sol elinizinki öne bakıyorsa, bir sonraki sette sağ elinizin avuç içi öne, solunki size bakacak."]', 'strength', '["Mixed_Grip_Chin/0.jpg", "Mixed_Grip_Chin/1.jpg"]', 360.0, 'Mixed Grip Chin', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4c455ed8-c51e-5367-9193-a66df0dd8e2e', 'free-exercise-db', 'Monster_Walk', 'Monster Walk (Direnç Bandı)', 'pull', 'beginner', 'compound', '["bands"]', '["abductors"]', '[]', '["Her iki ayak bileğinize bir bant, her iki dizinize de bir bant daha geçirin. Ayaklarınız omuz genişliğinde olduğunda bantların gergin olacağı kadar gerilim olmalıdır.", "Başlamak için sol ve sağ ayağınızı dönüşümlü olarak kullanarak kısa adımlarla ileri yürüyün.", "Birkaç adımdan sonra tam tersini yapın ve başladığınız yere geri doğru yürüyün."]', 'strength', '["Monster_Walk/0.jpg", "Monster_Walk/1.jpg"]', 360.0, 'Monster Walk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('361f5215-49a2-5362-9e8f-7e7661c93800', 'free-exercise-db', 'Mountain_Climbers', 'Mountain Climber', 'pull', 'beginner', 'compound', '[]', '["quadriceps"]', '["chest", "hamstrings", "shoulders"]', '["Ağırlığınız ellerinizde ve ayak parmaklarınızda desteklenerek şınav pozisyonunda başlayın. Diz ve kalçayı bükerek bir bacağı dizi yaklaşık kalçanın altına gelene kadar getirin. Bu sizin başlangıç pozisyonunuz olacak.", "Bacaklarınızın pozisyonunu patlayıcı bir şekilde tersine çevirin; bükülü bacağı düzleşip ayak parmağıyla desteklenene kadar uzatın ve diğer ayağı kalça ve diz bükülü şekilde yukarı getirin. 20-30 saniye boyunca dönüşümlü olarak tekrarlayın."]', 'plyometrics', '["Mountain_Climbers/0.jpg", "Mountain_Climbers/1.jpg"]', 480.0, 'Mountain Climbers', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ef2baebf-88b0-56ca-bd16-32ccba12ae0f', 'free-exercise-db', 'Moving_Claw_Series', 'Moving Claw Serisi (Koşu Drili)', NULL, 'beginner', 'compound', '[]', '["hamstrings"]', '["calves", "quadriceps"]', '["Bu hareket, sprintte başarılı olmanıza yardımcı olmak için koşu formunuzu hazırlar. Koşarken dizinizi bükün ve kalça açılırken topuğunuzla kalçanıza vurmayı hedefleyin.", "Bacak tekrar öne doğru hareket ederken ön bacak kasını yeniden yükleyin ve bir sonraki adımda yere güçlü şekilde basın.", "Koşarken kollarınızı kullandığınızdan, hızlı bir 1-2 hareketiyle yumruk atar gibi ileri savurduğunuzdan emin olun."]', 'plyometrics', '["Moving_Claw_Series/0.jpg", "Moving_Claw_Series/1.jpg"]', 480.0, 'Moving Claw Series', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c5b3c485-461d-5daf-ba4f-e2f84c5aea72', 'free-exercise-db', 'Muscle_Snatch', 'Muscle Snatch', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["glutes", "lower back", "quadriceps", "shoulders", "triceps"]', '["Yüklü bir halteri uyluğun orta noktasında geniş bir tutuşla tutarak başlayın. Ayaklarınız kalçanızın tam altında olmalı ve gerekirse dışa dönük olmalıdır. Göğsünüz yukarıda ve başınız ileriye bakacak şekilde kalçanızı alçaltın. Omuzlarınız barın hemen önünde olmalıdır. Bu başlangıç pozisyonu olacaktır.", "Topuklarınızın ön kısmından iterek barı kaldırarak çekişe başlayın. Kalçanızı, dizlerinizi ve ayak bileklerinizi açarak ikinci çekişe geçin ve barı olabildiğince hızlı bir şekilde yukarı sürün. Bar vücuda yakın olmalıdır.", "Dizlerinizi yeniden bükmeden barı baş üstü pozisyona kadar kaldırmaya devam edin."]', 'olympic weightlifting', '["Muscle_Snatch/0.jpg", "Muscle_Snatch/1.jpg"]', 420.0, 'Muscle Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ce116f16-0be6-5cf5-aa42-b705670b465a', 'free-exercise-db', 'Muscle_Up', 'Muscle Up (Halka)', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["abdominals", "biceps", "forearms", "middle back", "shoulders", "traps", "triceps"]', '["Halkaları false grip (sahte tutuş) ile kavrayın; avuç içi tabanlarınız halkaların üzerinde olsun. Dirseklerinizi bükerek ve dirseklerinizi yanlarınıza çekerek barfiks hareketini başlatın.", "Barfiksin üst noktasına ulaştığınızda, omuzlarınızı öne yuvarlarken halkaları koltuk altlarınıza çekin ve dirseklerinizin arkanızda düz geriye gitmesine izin verin. Bu sizi hareketin dips bölümüne devam etmek için doğru pozisyona getirir.", "Kontrolü ve dengeyi koruyarak hareketi tamamlamak için dirseklerinizi açın.", "Kendinizi yere indirirken dikkatli olun."]', 'strength', '["Muscle_Up/0.jpg", "Muscle_Up/1.jpg"]', 360.0, 'Muscle Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7b27af90-dbb6-5e2a-aa77-afb547a6d518', 'free-exercise-db', 'Narrow_Stance_Hack_Squats', 'Hack Squat (Makine, Dar Duruş)', 'push', 'intermediate', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Gövdenizin arkasını makinenin sırt pedine yaslayın ve omuzlarınızı sağlanan omuz pedlerinin altına yerleştirin.", "Bacaklarınızı platform üzerinde omuz genişliğinden dar bir duruşla, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Ayaklarınız yaklaşık 3 inç (7-8 cm) veya daha az aralıklı olmalıdır. İpucu: Başınızı her zaman yukarıda tutun ve sırtınızı da her zaman pedde tutun.", "Kollarınızı makinenin yan tutamaçlarına koyun ve güvenlik barlarını devre dışı bırakın (çoğu tasarımda bu, yan tutamaçların öne bakan konumdan çapraz konuma getirilmesiyle yapılır).", "Şimdi dizlerinizi kilitlemeden bacaklarınızı düzleştirin. Bu sizin başlangıç pozisyonunuzdur.", "Başınız yukarıda düz bir duruşu koruyarak (sırt her zaman pedde) dizlerinizi bükerek ünitedeki ağırlığı yavaşça indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz daha az olana kadar (üst bacakların yere paralelin altında olduğu nokta) inmeye devam edin. Hareketin bu kısmında nefes alın.", "Nefes verirken ağırlıklı olarak ayaklarınızın topuklarıyla zemini iterek bacaklarınızı tekrar düzleştirin ve üniteyi kaldırmaya başlayıp başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Narrow_Stance_Hack_Squats/0.jpg", "Narrow_Stance_Hack_Squats/1.jpg"]', 360.0, 'Narrow Stance Hack Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('26bea2c0-fbae-5a02-8e94-faaf3110d4ea', 'free-exercise-db', 'Narrow_Stance_Leg_Press', 'Leg Press (Dar Duruş)', 'push', 'intermediate', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Leg press makinesinde makineye oturun ve bacaklarınızı hemen önünüzdeki platforma omuz genişliğinden dar bir duruşla, ayak parmakları hafifçe dışa bakacak şekilde yerleştirin. Ayaklarınız arasındaki mesafe yaklaşık 3 inç (7-8 cm) veya daha az olmalıdır. İpucu: Başınızı her zaman yukarıda tutun ve sırtınızı da her zaman pede yaslı tutun.", "Ağırlıklı platformu yerinde tutan güvenlik çubuklarını indirin ve bacaklarınız önünüzde tamamen uzanana kadar platformu sonuna kadar itin. İpucu: Dizlerinizi kilitlemediğinizden emin olun. Gövdeniz ve bacaklarınız tam 90 derecelik bir açı oluşturmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken, üst ve alt bacaklarınız 90 derecelik açı yapana kadar platformu yavaşça indirin.", "Ağırlıklı olarak ayaklarınızın topuklarıyla iterek ve quadriceps''i kullanarak nefes verirken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın ve işiniz bittiğinde güvenlik pinlerini düzgün şekilde kilitlediğinizden emin olun. Tamamen yüklü platformun üzerinize düşmesini istemezsiniz."]', 'strength', '["Narrow_Stance_Leg_Press/0.jpg", "Narrow_Stance_Leg_Press/1.jpg"]', 360.0, 'Narrow Stance Leg Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2b7fe9fc-8406-5c01-ae1f-ae12d842fab3', 'free-exercise-db', 'Narrow_Stance_Squats', 'Dar Duruşlu Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Bu egzersiz güvenlik amacıyla en iyi squat rack içinde yapılır. Başlamak için önce barı boyunuza en uygun rafa yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve omuzlarınızın arkasını (boynun biraz altında) barın üzerine yerleştirin.", "Barı iki kolunuzla iki yandan tutun ve önce bacaklarınızla iterek ve aynı anda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinden dar bir duruşla, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Ayaklar yaklaşık 8-15 cm arayla olmalı. Başınızı her zaman yukarıda tutun (aşağı bakmak dengenizi bozar) ve sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuz olacak. (Not: Bu anlatımda genel gelişimi hedefleyen yukarıda tarif edilen orta duruş kullanılacaktır; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik şekilde dizlerinizi bükerek barı yavaşça indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz az olana kadar inmeye devam edin (üst bacakların yere paralelin altında olduğu nokta). Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız, dizlerinizin ön kısmı ayak parmaklarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizginin ötesine geçiyorsa (ayak parmaklarınızı aşıyorsa) dizlere gereksiz yük bindiriyorsunuz demektir ve egzersiz yanlış yapılmıştır.", "Nefes verirken, esas olarak ayağınızın topuğuyla yeri iterek ve bacaklarınızı tekrar düzelterek barı kaldırmaya ve başlangıç pozisyonuna dönmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Narrow_Stance_Squats/0.jpg", "Narrow_Stance_Squats/1.jpg"]', 360.0, 'Narrow Stance Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a6ab14ee-25f1-5ccc-a22c-1f04130b4d36', 'free-exercise-db', 'Natural_Glute_Ham_Raise', 'Glute-Ham Raise (Doğal)', 'pull', 'intermediate', 'compound', '["body only"]', '["hamstrings"]', '["calves", "glutes", "lower back"]', '["Bir lat pulldown makinesinin bacak pedini veya bir preacher bench kullanarak, ayak bilekleriniz pedlerin altında, dizleriniz oturağın üzerinde ve makineye sırtınız dönük olacak şekilde konumlanın. Dik durmalı ve iyi bir duruşu korumalısınız.", "Bu sizin başlangıç pozisyonunuz olacaktır. Dizleriniz neredeyse tamamen düzelene kadar kendinizi kontrollü bir şekilde aşağı indirin.", "Kontrolü koruyarak kendinizi başlangıç pozisyonuna geri kaldırın.", "Bir tekrarı tamamlayamıyorsanız, tekrarı tamamlamaya yardımcı olması için bir bant, bir partner kullanın veya bir kutudan itin."]', 'strength', '["Natural_Glute_Ham_Raise/0.jpg", "Natural_Glute_Ham_Raise/1.jpg"]', 360.0, 'Natural Glute Ham Raise', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d81a75cd-9fe3-5f32-816d-81f3cdf452c8', 'free-exercise-db', 'Neck-SMR', 'Boyun Foam Roll (SMR)', 'static', 'intermediate', NULL, '["other"]', '["neck"]', '[]', '["Bir kas silindiri ya da oklava kullanarak silindiri başınızın arkasına, boynunuza dayayın. Silindiri doğrudan omurgaya değil, hafifçe çevirerek omurganın iki yanındaki kaslara bastırdığınızdan emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Boynunuzun üst kısmından başlayarak boyun kaslarınız üzerinde yavaşça aşağı doğru yuvarlanın; gerginlik noktalarında 10-30 saniye bekleyin."]', 'stretching', '["Neck-SMR/0.jpg", "Neck-SMR/1.jpg"]', 150.0, 'Neck-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b256c26e-31c6-5e6d-883f-93a6fcc26f1d', 'free-exercise-db', 'Neck_Press', 'Neck Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Düz bir bench''e sırtüstü uzanın. Orta genişlikte bir tutuşla (hareketin ortasında ön kollar ile üst kollar arasında 90 derecelik açı oluşturan tutuş) barı raftan kaldırın ve kollarınız kilitli şekilde boynunuzun tam üzerinde tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken barı boynunuzda hissedene kadar yavaşça inin.", "Bir saniyelik duraklamanın ardından nefes verirken ve barı göğüs kaslarınızı kullanarak iterek barı başlangıç pozisyonuna getirin. Kollarınızı kilitleyin ve kasılmış pozisyonda göğsünüzü sıkın, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: Aşağı inmek, yukarı çıkmaktan en az iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde barı rafa geri yerleştirin."]', 'strength', '["Neck_Press/0.jpg", "Neck_Press/1.jpg"]', 360.0, 'Neck Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8cdc1b87-1617-5e6e-ae89-b18fed10caff', 'free-exercise-db', 'Oblique_Crunches', 'Oblik Crunch', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Belinizi yere bastırarak yere düz uzanın. Bu egzersiz için bir elinizi başınızın yanına, diğerini yanda yere koymanız gerekir.", "Ayaklarınızın yükseltilmiş ve düz bir yüzeyde durduğundan emin olun.", "Şimdi eli başınıza değen taraftaki omzu kaldırın.", "Dizinize dokunana kadar omzunuzu ve vücudunuzu yukarı kaldırın. Örneğin sağ elinizi başınızın yanına koyduysanız, sağ dirseğiniz sol dizinize değene kadar vücudunuzu yukarı kaldırın. Aynı varyasyon tersi yapılarak, sol dirsek sağ dize değdirilerek de uygulanabilir.", "Diziniz dirseğinize değdikten sonra başlangıç pozisyonuna gelene kadar vücudunuzu indirin.", "Egzersizin eksantrik (alçaltma) kısmında nefes almayı, konsantrik (yukarı çıkış) kısmında nefes vermeyi unutmayın.", "Her taraf için önerilen tüm tekrarlar tamamlanana kadar bu şekilde dönüşümlü devam edin."]', 'strength', '["Oblique_Crunches/0.jpg", "Oblique_Crunches/1.jpg"]', 360.0, 'Oblique Crunches', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0235e970-3347-5603-8f55-efbca6fe5fa0', 'free-exercise-db', 'Oblique_Crunches_-_On_The_Floor', 'Yerde Oblique Mekik', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Sağ yanınızın üzerine, bacaklarınız birbirinin üzerinde olacak şekilde uzanarak başlayın. Dizlerinizin biraz bükülü olduğundan emin olun.", "Sol elinizi başınızın arkasına koyun.", "Bu hazır pozisyona geçtikten sonra, normal bir mekik yapar gibi sol dirseğinizi yukarı doğru hareket ettirerek başlayın; ancak bu sefer ana vurgu oblik kaslarınız üzerinde olmalıdır.", "Gidebildiğiniz kadar yukarı mekik çekin, kasılmayı bir saniye tutun ve ardından yavaşça başlangıç pozisyonuna geri inin.", "Egzersizin eksantrik (alçaltma) kısmında nefes almayı, konsantrik (yükselme) kısmında ise nefes vermeyi unutmayın."]', 'strength', '["Oblique_Crunches_-_On_The_Floor/0.jpg", "Oblique_Crunches_-_On_The_Floor/1.jpg"]', 360.0, 'Oblique Crunches - On The Floor', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b851d346-fda7-596e-8b45-aca34b391ab5', 'free-exercise-db', 'Olympic_Squat', 'Olimpik Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Halter trapez kaslarının üzerinde desteklenmiş şekilde başlayın. Göğüs yukarıda ve baş öne dönük olmalıdır. Gerektiği kadar dışa dönük ayaklarla kalça genişliğinde bir duruş alın.", "Kalçanızı mümkün olduğunca geriye hareket ettirmekten kaçınarak dizlerinizi bükerek inin. Bu, dizlerin öne doğru ilerlemesini gerektirir; ayaklarla aynı hizada kaldıklarından emin olun. Amaç, gövdeyi olabildiğince dik tutmaktır. Ağırlığı topuğun ön kısmında tutarak en aşağıya kadar inin.", "Üst bacaklar alt bacaklara temas ettiği anda hareketi tersine çevirin ve ağırlığı yukarı doğru itin."]', 'olympic weightlifting', '["Olympic_Squat/0.jpg", "Olympic_Squat/1.jpg"]', 420.0, 'Olympic Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('49dd611e-0672-5291-91b6-94fddde9d7e6', 'free-exercise-db', 'On-Your-Back_Quad_Stretch', 'Sırtüstü Ön Bacak Esnetme', 'static', 'beginner', 'isolation', '["other"]', '["quadriceps"]', '[]', '["Düz bir sehpaya veya step''e uzanın ve bir bacağınızı ve kolunuzu yandan sarkıtın.", "Dizinizi bükün ve ayağın üstünü tutun. Bunu yaparken alt belinizi kavislendirmemeye dikkat edin.", "Nötr pozisyonda kalmak için göbeğinizi omurgaya çekin. Ayağınızı aşağı ve elinize doğru bastırın. Kalça esnemesini artırmak için tuttuğunuz bacağın kalçasını tavana doğru kaldırın.", "Taraf değiştirin."]', 'stretching', '["On-Your-Back_Quad_Stretch/0.jpg", "On-Your-Back_Quad_Stretch/1.jpg"]', 150.0, 'On-Your-Back Quad Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1e890327-3473-5b66-88da-d6226a76baeb', 'free-exercise-db', 'On_Your_Side_Quad_Stretch', 'Yan Yatarak Ön Bacak Esnetme', 'static', 'beginner', 'isolation', '[]', '["quadriceps"]', '[]', '["Sağ yanınıza uzanarak başlayın; sağ dizinizi 90 derecelik açıyla bükülü şekilde önünüzde yerde tutun (bu, gövdeyi sabitler).", "Sol dizinizi arkanıza bükün ve sol ayağınızı sol elinizle tutun. Kalça fleksörünüzü esnetmek için sol kalçanızı öne doğru bastırırken sol ayağınızı elinize doğru geriye itin. Taraf değiştirin."]', 'stretching', '["On_Your_Side_Quad_Stretch/0.jpg", "On_Your_Side_Quad_Stretch/1.jpg"]', 150.0, 'On Your Side Quad Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2dbcb535-7fe5-5f79-bfb1-f9125b601f08', 'free-exercise-db', 'One-Arm_Dumbbell_Row', 'Tek Kol Row (Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["middle back"]', '["biceps", "lats", "shoulders"]', '["Düz bir bench seçin ve her iki yanına birer dambıl yerleştirin.", "Sağ bacağınızı bench''in ucuna koyun, üst vücudunuz yere paralel olana kadar gövdenizi belinizden öne eğin ve destek için sağ elinizi bench''in diğer ucuna yerleştirin.", "Sol elinizle yerdeki dambılı alın ve belinizi düz tutarak ağırlığı tutun. Elin avuç içi gövdenize bakmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kolunuzu yanınıza yakın ve gövdenizi sabit tutarak direnci göğsünüzün yanına doğru düz yukarı çekin. Bu adımı yaparken nefes verin. İpucu: Tam kasılmış pozisyona ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Ayrıca gücün kollardan değil sırt kaslarından geldiğinden emin olun. Son olarak, üst gövde sabit kalmalı ve sadece kollar hareket etmelidir. Ön kollar dambılı tutmak dışında başka bir iş yapmamalıdır; bu nedenle dambılı ön kollarınızla yukarı çekmeye çalışmayın.", "Direnci düz aşağı başlangıç pozisyonuna indirin. Bu adımı yaparken nefes alın.", "Hareketi belirtilen tekrar sayısı kadar tekrarlayın.", "Taraf değiştirin ve diğer kolla tekrar yapın."]', 'strength', '["One-Arm_Dumbbell_Row/0.jpg", "One-Arm_Dumbbell_Row/1.jpg"]', 360.0, 'One-Arm Dumbbell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('99492bcc-b687-5423-93d6-081db3095ae0', 'free-exercise-db', 'One-Arm_Flat_Bench_Dumbbell_Flye', 'Fly (Dambıl, Tek Kol, Düz Sehpa)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["chest"]', '[]', '["Bir elinizde uyluğunuzun üzerinde duran bir dambılla düz sehpaya uzanın. Dambılı tutan elin avuç içi nötr tutuşta olmalıdır.", "Dambılı kaldırmak için uyluklarınızdan destek alarak, dambılı kaldıran kolunuz tamamen uzamış halde önünüzde tutabilecek şekilde yukarı çekin (clean). Bu egzersizde nötr tutuşu korumayı unutmayın. Kaldırmayan elinizle daha iyi destek için düz sehpayı yan taraftan tutun. Bu sizin başlangıç pozisyonunuzdur.", "Biceps tendonundaki yüklenmeyi önlemek için ağırlığı taşıyan kolunuzun dirseği hafif bükülü olmalıdır. Göğsünüzde bir esneme hissedene kadar ağırlıklı kolunuzu geniş bir yay çizerek indirmeye başlayın. Hareketin bu kısmında nefes alın. İpucu: Hareket boyunca kaldıran kolunuzun sabit kalması gerektiğini, hareketin yalnızca omuz ekleminde gerçekleşmesi gerektiğini unutmayın.", "Göğüs kaslarınızı sıkarak ve nefes vererek kaldıran kolunuzu başlangıç pozisyonuna geri getirin. İpucu: Ağırlıkları indirirken kullandığınız hareket yayının aynısını kullandığınızdan emin olun.", "Kasılmış pozisyonda bir saniye bekleyin ve hareketi belirtilen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve egzersizi tekrarlayın."]', 'strength', '["One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg", "One-Arm_Flat_Bench_Dumbbell_Flye/1.jpg"]', 360.0, 'One-Arm Flat Bench Dumbbell Flye', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b1c6e44c-827a-5046-8839-73c8c94e9e51', 'free-exercise-db', 'One-Arm_High-Pulley_Cable_Side_Bends', 'Tek Kol Yana Eğilme (Üst Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["Standart bir sapı bir kuleye bağlayın. Kabloyu en yüksek makara pozisyonuna getirin.", "Yan tarafınız kabloya dönük şekilde durun. Bir elinizle yukarı uzanın ve sapı underhand tutuşla kavrayın.", "Kabloyu, dirseğiniz yanınıza değene ve sap omzunuzun yanında olana kadar aşağı çekin.", "Ayaklarınızı kalça genişliğinde açın. Dönme noktasını anlamanıza yardımcı olmak için boştaki elinizi kalçanıza koyun.", "Kolu sabit pozisyonda tutun. Ağırlığı yan mekik hareketiyle aşağı getirmek için oblik kasınızı kasın.", "Maksimum kasılmaya ulaştığınızda ağırlığı yavaşça başlangıç pozisyonuna bırakın. Ağırlık bloğu asla dinlenme pozisyonunda tamamen boşaltılmamalıdır. Amaç, set boyunca sürekli gerginliği korumaktır.", "Tükenene kadar tekrarlayın.", "Ardından pozisyonunuzu değiştirin ve aynı hareket dizisini karşı tarafta tekrarlayın."]', 'strength', '["One-Arm_High-Pulley_Cable_Side_Bends/0.jpg", "One-Arm_High-Pulley_Cable_Side_Bends/1.jpg"]', 360.0, 'One-Arm High-Pulley Cable Side Bends', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7d78500d-ffc7-53a9-a04f-8bb4ec24660b', 'free-exercise-db', 'One-Arm_Incline_Lateral_Raise', 'Tek Kol Incline Lateral Raise (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Elinizde bir dambılla incline bench üzerine yan yatın. Omzun incline bench''e bastırıldığından ve kolun vücudunuzun üzerinden uzanarak avuç içinin göbeğinizin çevresinde olduğundan emin olun.", "Üstteki kolunuzda bir dambıl tutun ve kolunuzu önünüzde yere paralel şekilde uzatılmış halde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Dambılı her zaman yere paralel tutarak bir lateral raise yapın. Kolunuz tavanı gösterene kadar dümdüz yukarı gitmelidir. İpucu: Bu hareketi yaparken nefes verin. Dambılı bu pozisyonda tutun ve omuzlardaki kasılmayı bir saniye hissedin.", "Nefes alırken ağırlığı vücudunuzun üzerinden başlangıç pozisyonuna geri indirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["One-Arm_Incline_Lateral_Raise/0.jpg", "One-Arm_Incline_Lateral_Raise/1.jpg"]', 360.0, 'One-Arm Incline Lateral Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5c58b659-44f8-5bf8-882c-60372e41b6c1', 'free-exercise-db', 'One-Arm_Kettlebell_Clean', 'Tek Kol Clean (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["glutes", "lower back", "shoulders", "traps"]', '["Bir kettlebell''i ayaklarınızın arasına koyun. Kettlebell''i almak için eğilirken kalçanızı geriye itin ve gözlerinizi ileri bakar tutun.", "Kettlebell''i omzunuza doğru kaldırırken bacaklarınızı ve kalçanızı açarak omzunuza clean yapın. Bunu yaparken bilek dönmelidir.", "Ağırlığı başlangıç pozisyonuna geri getirin."]', 'strength', '["One-Arm_Kettlebell_Clean/0.jpg", "One-Arm_Kettlebell_Clean/1.jpg"]', 360.0, 'One-Arm Kettlebell Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4fb92da8-4213-552e-acdc-7cf986db5b9a', 'free-exercise-db', 'One-Arm_Kettlebell_Clean_and_Jerk', 'Tek Kol Clean and Jerk (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '[]', '["Bir kettlebell''i kulpundan tutun.", "Bacaklarınızı ve kalçanızı açarak kettlebell''i omzunuza doğru çekerek omzunuza getirin. Bunu yaparken bileğinizi döndürün, böylece avuç içi ileri baksın.", "Gövdenizi dik tutarak dizlerinizi bükerek vücudunuzu alçaltın.", "Hemen yönü tersine çevirin, topuklarınızdan iterek esasen ivme yaratmak için zıplayın. Bunu yaparken, vücudunuzun ivmesini kullanarak kettlebell''i kollarınızı açıp kilitlenene kadar baş üstüne itin.", "Ağırlığın altında tekrar çömelme pozisyonuna geçerek ağırlığı baş üstünde karşılayın.", "Ağırlığı baş üstünde tutarak ayakta duruş pozisyonuna dönün. Bir sonraki tekrarı yapmak için ağırlığı yere indirin."]', 'strength', '["One-Arm_Kettlebell_Clean_and_Jerk/0.jpg", "One-Arm_Kettlebell_Clean_and_Jerk/1.jpg"]', 360.0, 'One-Arm Kettlebell Clean and Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f4ee3bdb-b658-5c29-969c-ce39caa6ee99', 'free-exercise-db', 'One-Arm_Kettlebell_Floor_Press', 'Tek Kol Floor Press (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["chest"]', '["triceps"]', '["Bir elinizde kettlebell tutarak yere uzanın; üst kolunuz yer tarafından desteklensin. Avuç içi içe bakmalıdır.", "Bileğinizi döndürerek kettlebell''i tavana doğru düz yukarı itin.", "Kettlebell''i başlangıç pozisyonuna indirin ve tekrarlayın."]', 'strength', '["One-Arm_Kettlebell_Floor_Press/0.jpg", "One-Arm_Kettlebell_Floor_Press/1.jpg"]', 360.0, 'One-Arm Kettlebell Floor Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c823ffb2-0803-5e0d-b029-adfd8bb59453', 'free-exercise-db', 'One-Arm_Kettlebell_Jerk', 'Tek Kol Jerk (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["calves", "quadriceps", "triceps"]', '["Bir kettlebell''i sapından tutun. Kettlebell''i omzunuza doğru çekerken bacaklarınızı ve kalçanızı açarak omzunuza kaldırın (clean). Bunu yaparken avuç içi öne bakacak şekilde bileğinizi döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi dik tutarak dizlerinizi bükerek vücudunuzu aşağı indirin (dip).", "Hemen yön değiştirin, topuklarınızdan iterek aslında ivme yaratmak için zıplayın. Bunu yaparken, vücudunuzun ivmesini kullanarak kettlebell''i kollarınızı açıp kilitleyene kadar baş üstüne itin. Ağırlığı baş üstünde, altında squat pozisyonuna dönerek karşılayın. Ağırlığı baş üstünde tutarak ayakta duruş pozisyonuna dönün.", "Bir sonraki tekrarı yapmak için ağırlığı indirin."]', 'strength', '["One-Arm_Kettlebell_Jerk/0.jpg", "One-Arm_Kettlebell_Jerk/1.jpg"]', 360.0, 'One-Arm Kettlebell Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('457b0aec-ced4-5c4f-ad0b-ed745bd37ddd', 'free-exercise-db', 'One-Arm_Kettlebell_Military_Press_To_The_Side', 'Tek Kol Military Press (Kettlebell, Yana)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["triceps"]', '["Bir kettlebell''i omzunuza çekin (clean). Kettlebell''i omzunuza doğru çekerken bacaklarınızı ve kalçanızı açarak omzunuza kaldırın. Bunu yaparken avuç içi içeri bakacak şekilde bileğinizi döndürün. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kettlebell''e bakın ve başınızın üzerinde kilitlenene kadar yukarı ve dışarı doğru itin.", "Kettlebell''i kontrollü bir şekilde omzunuza geri indirin ve tekrarlayın. Ekstra denge ve güç için lat, kalça ve karın kaslarınızı güçlü bir şekilde kastığınızdan emin olun."]', 'strength', '["One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg", "One-Arm_Kettlebell_Military_Press_To_The_Side/1.jpg"]', 360.0, 'One-Arm Kettlebell Military Press To The Side', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('faa0bf22-00b3-5298-b7e6-6a69d517edd6', 'free-exercise-db', 'One-Arm_Kettlebell_Para_Press', 'Tek Kol Para Press (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["triceps"]', '["Bir kettlebell''i omzunuza clean yapın. Kettlebell''i omzunuza doğru çekerken bacaklarınızı ve kalçanızı açarak omzunuza clean yapın. Bunu yaparken avuç içi öne bakacak şekilde bileğinizi döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Kettlebell''i dirseğiniz yana açık şekilde tutun ve kilitlenene kadar başınızın üzerine yukarı ve dışa doğru itin.", "Kettlebell''i kontrollü bir şekilde omzunuza geri indirin ve tekrarlayın. Ek denge ve güç için lat, kalça ve karın kaslarınızı kuvvetle kasmayı unutmayın."]', 'strength', '["One-Arm_Kettlebell_Para_Press/0.jpg", "One-Arm_Kettlebell_Para_Press/1.jpg"]', 360.0, 'One-Arm Kettlebell Para Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2a034d4a-0fb8-58ef-8bdd-ecc1eada02dd', 'free-exercise-db', 'One-Arm_Kettlebell_Push_Press', 'Tek Kol Push Press (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["calves", "quadriceps", "triceps"]', '["Bir kettlebell''i kulpundan tutun. Bacaklarınızı ve kalçanızı açarak kettlebell''i omzunuza doğru çekerek omzunuza getirin. Bunu yaparken bileğinizi döndürün, böylece avuç içi ileri baksın. Bu sizin başlangıç pozisyonunuz olacak.", "Gövdenizi dik tutarak dizlerinizi bükerek vücudunuzu alçaltın.", "Hemen yönü tersine çevirin, topuklarınızdan iterek esasen ivme yaratmak için zıplayın. Bunu yaparken, vücudunuzun ivmesini kullanarak kettlebell''i kollarınızı açıp kilitlenene kadar baş üstüne itin. Bir sonraki tekrarı yapmak için ağırlığı indirin."]', 'strength', '["One-Arm_Kettlebell_Push_Press/0.jpg", "One-Arm_Kettlebell_Push_Press/1.jpg"]', 360.0, 'One-Arm Kettlebell Push Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('35a887f1-f7b2-571f-b3ac-ee4d81de9bc4', 'free-exercise-db', 'One-Arm_Kettlebell_Row', 'Tek Kol Row (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["middle back"]', '["biceps", "lats"]', '["Bir kettlebell''i ayaklarınızın önüne yerleştirin. Dizlerinizi hafifçe bükün ve ardından başlangıç pozisyonuna geçmek için eğilirken kalçanızı mümkün olduğunca geriye itin. Kettlebell''i kavrayın ve kürek kemiğinizi geriye çekerek ve dirseğinizi bükerek karnınıza doğru çekin. Sırtınızı düz tutun. İndirin ve tekrarlayın."]', 'strength', '["One-Arm_Kettlebell_Row/0.jpg", "One-Arm_Kettlebell_Row/1.jpg"]', 360.0, 'One-Arm Kettlebell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fd91b4da-509d-5fb0-bcee-2b6275a85f0d', 'free-exercise-db', 'One-Arm_Kettlebell_Snatch', 'Snatch (Kettlebell, Tek Kol)', 'pull', 'expert', 'compound', '["kettlebells"]', '["shoulders"]', '["calves", "glutes", "hamstrings", "lower back", "traps", "triceps"]', '["Ayaklarınızın arasına bir kettlebell yerleştirin. Doğru başlangıç pozisyonuna gelmek için dizlerinizi bükün ve kalçanızı geriye itin.", "Dümdüz ileri bakın ve kettlebell''i bacaklarınızın arasından geriye doğru sallayın.", "Hemen yön değiştirin ve kalçanızı ve dizlerinizi iterek kettlebell''i yukarı doğru hızlandırın. Kettlebell omzunuza yükselirken elinizi döndürün ve dümdüz yukarı itin; ağırlığı tepenizde kilitli şekilde karşılamak için ivmeyi kullanın."]', 'strength', '["One-Arm_Kettlebell_Snatch/0.jpg", "One-Arm_Kettlebell_Snatch/1.jpg"]', 360.0, 'One-Arm Kettlebell Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('55dd66a4-15cb-5e36-8c79-324f179d9b8c', 'free-exercise-db', 'One-Arm_Kettlebell_Split_Jerk', 'Tek Kol Split Jerk (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["glutes", "hamstrings", "quadriceps", "triceps"]', '["Bir kettlebell''i sapından tutun. Kettlebell''i omzunuza doğru çekerken bacaklarınızı ve kalçanızı açarak omzunuza kaldırın (clean). Bunu yaparken avuç içi öne bakacak şekilde bileğinizi döndürün. Bu sizin başlangıç pozisyonunuz olacaktır.", "Gövdenizi dik tutarak dizlerinizi bükerek vücudunuzu alçaltın (dip).", "Hemen yön değiştirin ve topuklarınızdan iterek, özünde ivme yaratmak için zıplayın. Bunu yaparken, ağırlığı hareket ettirmek için vücudunuzun ivmesini kullanarak kollarınızı açıp kettlebell''i başınızın üzerinde kilitlenene kadar itin.", "Bir bacağınız önde ve bir bacağınız arkada olacak şekilde ağırlığın altında bir squat pozisyonuna dönerek ağırlığı başınızın üzerinde karşılayın.", "Ağırlığı başınızın üzerinde tutarak ayakta duruş pozisyonuna dönün ve ayaklarınızı birleştirin. Bir sonraki tekrar için ağırlığı indirin."]', 'strength', '["One-Arm_Kettlebell_Split_Jerk/0.jpg", "One-Arm_Kettlebell_Split_Jerk/1.jpg"]', 360.0, 'One-Arm Kettlebell Split Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('dd09de9a-907f-5ae7-8d85-ded6f6d77728', 'free-exercise-db', 'One-Arm_Kettlebell_Split_Snatch', 'Tek Kol Split Snatch (Kettlebell)', 'pull', 'expert', 'compound', '["kettlebells"]', '["shoulders"]', '["hamstrings", "quadriceps"]', '["Bir kettlebell''i tek elinizle sapından tutun.", "Yere doğru çömelin, ardından hareketi tersine çevirerek kalçanızı, dizlerinizi ve son olarak ayak bileklerinizi açın ve kettlebell''i baş üstüne kaldırın.", "Vücudunuzu tamamen açtıktan sonra, ağırlıkları baş üstünde karşılamak için bir bacak önde ve bir bacak arkada olacak şekilde lunge pozisyonuna inin. Kalçanızla itmeyi ve kettlebell''i baş üstünde kesintisiz tek bir hareketle kilitlemeyi unutmayın.", "Ağırlığı baş üstünde tutarak ayakta duruş pozisyonuna dönün ve ayaklarınızı birleştirin. Başlangıç pozisyonuna dönmek için ağırlığı indirin."]', 'strength', '["One-Arm_Kettlebell_Split_Snatch/0.jpg", "One-Arm_Kettlebell_Split_Snatch/1.jpg"]', 360.0, 'One-Arm Kettlebell Split Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2617374d-bec2-5cdd-b0e4-8beb40b54fbc', 'free-exercise-db', 'One-Arm_Kettlebell_Swings', 'Tek Kol Kettlebell Swing', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["calves", "glutes", "lower back", "shoulders"]', '[]', 'strength', '["One-Arm_Kettlebell_Swings/0.jpg", "One-Arm_Kettlebell_Swings/1.jpg"]', 360.0, 'One-Arm Kettlebell Swings', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('79e5b505-5aa7-54eb-b5f9-522d61d287b1', 'free-exercise-db', 'One-Arm_Long_Bar_Row', 'Tek Kol Uzun Bar Row (Landmine)', 'pull', 'beginner', 'compound', '["barbell"]', '["middle back"]', '["biceps", "lats"]', '["Barı bir landmine aparatına ya da hareket etmemesi için bir köşeye yerleştirin. Kendi ucunuza uygun ağırlığı yükleyin.", "Barın yanında durun ve bir elinizle plaka tutucuya (collar) yakın bir yerden kavrayın. Kalçanızı ve bacaklarınızı kullanarak ayağa kalkın.", "Kalçanız geride ve göğsünüz yukarıda olacak şekilde dizleri bükülü bir duruş alın. Kolunuz uzanmış olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Omzunuzu geriye çekerek ve dirseğinizi bükerek ağırlığı yanınıza doğru çekin. Hareket sırasında ağırlığı savurmayın veya hile yapmayın.", "Kısa bir beklemeden sonra başlangıç pozisyonuna dönün."]', 'strength', '["One-Arm_Long_Bar_Row/0.jpg", "One-Arm_Long_Bar_Row/1.jpg"]', 360.0, 'One-Arm Long Bar Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2d5f85e8-e1dd-5dc0-b531-a9aad56fd1ab', 'free-exercise-db', 'One-Arm_Medicine_Ball_Slam', 'Tek Kol Medicine Ball Slam', 'pull', 'beginner', 'compound', '["medicine ball"]', '["abdominals"]', '["lats", "shoulders"]', '["Ayakta, ayaklar önlü arkalı atletik bir duruşta başlayın. Bir medicine ball''u arka bacağınızla aynı taraftaki elinizde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Kolu geriye savurarak ve medicine ball''u başınızın üzerine kaldırarak başlayın. Bunu yaparken slam için güç toplamak amacıyla kalça, diz ve bileklerinizi açın.", "Maksimum açılma noktasında omuzlarınızı, omurganızı ve kalçanızı bükerek topu hemen önünüzdeki yere sert şekilde fırlatın.", "Topu sekme sırasında yakalayın ve istenen tekrar sayısı kadar devam edin."]', 'strength', '["One-Arm_Medicine_Ball_Slam/0.jpg", "One-Arm_Medicine_Ball_Slam/1.jpg"]', 360.0, 'One-Arm Medicine Ball Slam', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6387f60f-c26c-572c-8fdb-a581b193f51c', 'free-exercise-db', 'One-Arm_Open_Palm_Kettlebell_Clean', 'Tek Kol Açık Avuç Clean (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["hamstrings"]', '["forearms", "glutes", "lower back", "quadriceps", "shoulders"]', '["Bir kettlebell''i ayaklarınızın arasına koyun.", "Kulpu bir elinizle kavrayın ve kettlebell''i hızla yukarı kaldırın, dönmesine izin verin; böylece kettlebell''in gövdesi avuç içinize otursun.", "Kettlebell''i önünüze doğru fırlatın ve kulpunu tek elle yakalayın.", "Kettlebell''i yere indirin ve tekrarlayın. Her iki kolu da çalıştırdığınızdan emin olun."]', 'strength', '["One-Arm_Open_Palm_Kettlebell_Clean/0.jpg", "One-Arm_Open_Palm_Kettlebell_Clean/1.jpg"]', 360.0, 'One-Arm Open Palm Kettlebell Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3bfd5906-bdcd-5826-b759-5cbc72090d91', 'free-exercise-db', 'One-Arm_Overhead_Kettlebell_Squats', 'Overhead Squat (Kettlebell, Tek Kol)', 'push', 'expert', 'compound', '["kettlebells"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "shoulders"]', '["Bir kolunuzla kettlebell''i clean ve press yapın. Bacaklarınızı ve kalçanızı açarak kettlebell''i omzunuza doğru çekerek omzunuza alın. Bunu yaparken bileğinizi döndürün. Dirseğinizi açarak ağırlığı tepenize itin. Bu sizin başlangıç pozisyonunuzdur.", "Dümdüz ileri bakarak ve kettlebell''i tepenizde kilitli tutarak dizlerinizi ve kalçanızı bükün ve başınız ile göğsünüz yukarıda gövdenizi bacaklarınızın arasına indirin.", "Alt pozisyonda bir saniye durun, ardından ayaklarınızın topuklarıyla iterek tekrar yukarı kalkın."]', 'strength', '["One-Arm_Overhead_Kettlebell_Squats/0.jpg", "One-Arm_Overhead_Kettlebell_Squats/1.jpg"]', 360.0, 'One-Arm Overhead Kettlebell Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a824c2ee-f015-5650-821a-a9f96d98353b', 'free-exercise-db', 'One-Arm_Side_Deadlift', 'Tek Kol Yan Deadlift (Halter)', 'pull', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["abdominals", "calves", "glutes", "hamstrings", "lower back", "traps"]', '["Halterin yanında, merkezine yakın bir yerde durun. Halteri tutabilene kadar dizlerinizi bükün ve vücudunuzu alçaltın.", "Halteri sanki bir evrak çantası tutuyormuşsunuz gibi kavrayın (halter yana dönük olduğundan avuç içleriniz size bakar). Kayda değer bir ağırlık kullanıyorsanız bilek bandına ihtiyaç duyabilirsiniz. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken halteri kaldırmaya yardımcı olması için bacaklarınızı kullanın. Ayakta duruş pozisyonuna gelene kadar halteri yukarı getirirken kollarınız tamamen uzanmalıdır.", "Nefes alırken halteri yavaşça geri indirin. İpucu: Herhangi bir sakatlanmayı önlemek için ağırlığı indirirken dizlerinizi bükmeyi unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["One-Arm_Side_Deadlift/0.jpg", "One-Arm_Side_Deadlift/1.jpg"]', 360.0, 'One-Arm Side Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('35ebccf3-e28f-5d61-881b-9aa63a48cd69', 'free-exercise-db', 'One-Arm_Side_Laterals', 'Tek Kol Lateral Raise (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Bir dambıl alın ve bir elinize yerleştirin. Kaldırmayan elinizle incline bench press gibi sabit bir şeyi tutun. Dengenizi korumanıza izin vereceği için, eğimli banki tutan elden uzağa, kaldıran kolunuza doğru yaslanın.", "Gövdeniz dik şekilde durun ve dambılı kolunuz boyunca, avuç içi size bakacak şekilde yanınızda tutun. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarak (sallanmadan), dirseğiniz hafif bükülü ve elinizi bardağa su döker gibi hafifçe öne eğik tutarak dambılı yanınıza doğru kaldırın. Kolunuz yere paralel olana kadar yukarı çıkmaya devam edin. Bu hareketi yaparken nefes verin ve üstte bir saniye bekleyin.", "Nefes alırken dambılı yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Kol değiştirin ve egzersizi tekrarlayın."]', 'strength', '["One-Arm_Side_Laterals/0.jpg", "One-Arm_Side_Laterals/1.jpg"]', 360.0, 'One-Arm Side Laterals', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('37192b18-1ef5-54c1-87b0-e10843b00697', 'free-exercise-db', 'One-Legged_Cable_Kickback', 'Tek Bacak Kickback (Kablo)', 'push', 'intermediate', 'isolation', '["cable"]', '["glutes"]', '["hamstrings"]', '["Deri bir ayak bileği kelepçesini alt kablo makarasına takın, ardından kelepçeyi ayak bileğinize bağlayın.", "Ağırlık yığınına yaklaşık 60 cm mesafeden dönük durun ve destek için çelik çerçeveyi kavrayın.", "Dizlerinizi ve kalçanızı hafifçe bükülü ve karın kaslarınızı sıkı tutarak, nefes verirken kalça kaslarınızı kasıp çalışan bacağı rahatça gidebildiği kadar yükseğe doğru yarım daire yayıyla yavaşça geriye \"tekmeleyin\". İpucu: Tam açılma noktasında, zirve kasılmayı elde etmek için kalça kaslarınızı bir saniye sıkın.", "Şimdi çalışan bacağınızı, başlangıç pozisyonuna ulaşana kadar kablonun çekişine direnerek yavaşça öne getirin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bacak değiştirin ve hareketi diğer taraf için tekrarlayın."]', 'strength', '["One-Legged_Cable_Kickback/0.jpg", "One-Legged_Cable_Kickback/1.jpg"]', 360.0, 'One-Legged Cable Kickback', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4978799a-99fc-586a-b9a6-912fbb4a80bd', 'free-exercise-db', 'One_Arm_Against_Wall', 'Duvara Karşı Tek Kol Esnetme', 'static', 'beginner', 'isolation', '[]', '["lats"]', '[]', '["Ayakta dururken bükülü bir kolunuzu duvara ya da kapı çerçevesine dayayın.", "Lat kaslarınızda bir gerilme hissedene kadar kolunuza doğru yavaşça eğilin."]', 'stretching', '["One_Arm_Against_Wall/0.jpg", "One_Arm_Against_Wall/1.jpg"]', 150.0, 'One Arm Against Wall', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('170be7b9-e5b3-5048-8623-f1fa22897513', 'free-exercise-db', 'One_Arm_Chin-Up', 'Tek Kol Chin-Up', 'pull', 'expert', 'compound', '["other"]', '["middle back"]', '["biceps", "forearms", "lats"]', '["Bu egzersiz için bir havluyu chin-up barının etrafına dolayarak başlayın.", "Chin-up barını avuç içiniz size bakacak şekilde kavrayın. Bir eliniz chin-up barını, diğeri havluyu tutacaktır.", "Belinizde bir kavis oluştururken ve göğsünüzü dışarı çıkarırken gövdenizi yaklaşık 30 derece geriye alın. Bu sizin başlangıç pozisyonunuzdur.", "Omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek, bar üst göğsünüze değene kadar gövdenizi yukarı çekin. Hareketin bu kısmında nefes verin. İpucu: Tam kasılmış pozisyona ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde uzayda hareket ederken sabit kalmalı ve yalnızca kollar hareket etmelidir. Ön kollar barı tutmaktan başka iş yapmamalıdır.", "Kasılmış pozisyonda bir saniye bekledikten sonra nefes almaya başlayın ve kollarınız tamamen uzanıp latlarınız tamamen gerilene kadar gövdenizi yavaşça başlangıç pozisyonuna indirin.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["One_Arm_Chin-Up/0.jpg", "One_Arm_Chin-Up/1.jpg"]', 360.0, 'One Arm Chin-Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4a3940a1-e716-58fe-ba1e-9cd4f80b6255', 'free-exercise-db', 'One_Arm_Dumbbell_Bench_Press', 'Tek Kol Bench Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["chest"]', '["shoulders", "triceps"]', '["Bir elinizde uyluğunuzun üzerinde bir dambılla düz bir bench''e uzanın.", "Dambılı kaldırmak için uyluğunuzdan destek alarak dambılı omuz genişliğinde önünüzde tutabilecek şekilde yukarı çekin (clean). Dambılı doğru konumlandırmak için kaldırmayan elinizi kullanın.", "Omuz genişliğine geldiğinizde, avuç içiniz sizden uzağa bakacak şekilde bileğinizi öne doğru çevirin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken ağırlığı yavaşça yanınıza doğru indirin. Dambıl üzerinde her zaman tam kontrolü koruyun. İpucu: Başlangıçta biraz zorlanabileceğiniz için dambılın dengesini korumaya yardımcı olması amacıyla kaldırmayan elinizi kullanın. Kaldırmayan elinizi yalnızca gerekirse kullanın. Aksi halde yanda dinlenmesine izin verin.", "Nefes verirken göğüs kaslarınızı kullanarak dambılı yukarı itin. Kasılmış pozisyonda kolunuzu kilitleyin, göğsünüzü sıkın, bir saniye bekleyin ve ardından yavaşça inmeye başlayın. İpucu: Aşağı inmek, yukarı çıkmaktan en az iki kat daha uzun sürmelidir.", "Hareketi antrenman programınızdaki belirlenen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["One_Arm_Dumbbell_Bench_Press/0.jpg", "One_Arm_Dumbbell_Bench_Press/1.jpg"]', 360.0, 'One Arm Dumbbell Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e715a078-8cf7-5925-bf27-94f6043159e7', 'free-exercise-db', 'One_Arm_Dumbbell_Preacher_Curl', 'Preacher Curl (Dambıl, Tek Kol)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Sağ kolunuzla bir dambıl alın ve üst kolunuzu preacher sehpasının veya incline sehpanın üzerine yerleştirin. Dambıl omuz hizasında tutulmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken üst kolunuz uzayana ve biceps tamamen gerilene kadar dambılı yavaşça indirin.", "Nefes verirken biceps''inizi kullanarak biceps tamamen kasılana ve dambıl omuz hizasına gelene kadar ağırlığı kıvırın. Tam kasılmayı sağlamak için serçe parmağınızı başparmağınızdan daha yukarı getirmeniz gerektiğini yine unutmayın.", "Kasılmış pozisyonda biceps''i bir saniye sert şekilde sıkın ve önerilen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["One_Arm_Dumbbell_Preacher_Curl/0.jpg", "One_Arm_Dumbbell_Preacher_Curl/1.jpg"]', 360.0, 'One Arm Dumbbell Preacher Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('be37b849-4b6d-583f-a318-a53a6148de31', 'free-exercise-db', 'One_Arm_Floor_Press', 'Tek Kol Floor Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "shoulders"]', '["Sırtınız yere veya egzersiz matına bastırılmış şekilde düz bir yüzeye uzanın. Dizlerinizin bükülü olduğundan emin olun.", "Bir partnerinizden halteri size tek elinize vermesini isteyin. Başlarken kolunuz hemen hemen tamamen uzanmış olmalıdır; tıpkı halter bench press''in başlangıç pozisyonu gibi. Ancak bu sefer tutuşunuz nötr olacak (avuç içleri gövdenize bakacak).", "Ağırlığı kaldırmak için kullanmadığınız elin yanınızda durduğundan emin olun.", "Egzersize, dirseğiniz yere değene kadar halteri indirerek başlayın. Bu eksantrik (egzersizin indirme kısmı) olduğundan nefes aldığınızdan emin olun.", "Ardından halteri tekrar ilk başlangıç pozisyonuna kaldırmaya başlayın. Konsantrik (egzersizin kaldırma kısmı) sırasında nefes vermeyi unutmayın.", "Önerilen tekrar sayısını tamamlayana kadar tekrarlayın.", "Kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["One_Arm_Floor_Press/0.jpg", "One_Arm_Floor_Press/1.jpg"]', 360.0, 'One Arm Floor Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b8f50726-58cd-528f-b476-b434335f41f5', 'free-exercise-db', 'One_Arm_Lat_Pulldown', 'Tek Kol Lat Pulldown', 'pull', 'beginner', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back"]', '["Uygun bir ağırlık seçin ve sizi aşağıda tutması için diz pedini ayarlayın. Tutamağı pronasyon tutuşla (avuç içi aşağı) kavrayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi bükerken dirseğinizi yanınıza sıkıştırarak tutamağı aşağı çekin.", "Hareketin alt noktasında bekleyin, ardından tutamağı yavaşça başlangıç pozisyonuna geri bırakın.", "Birden fazla tekrar için, çalışan kaslardaki gerginliği korumak amacıyla ağırlığı tamamen geri bırakmaktan kaçının."]', 'strength', '["One_Arm_Lat_Pulldown/0.jpg", "One_Arm_Lat_Pulldown/1.jpg"]', 360.0, 'One Arm Lat Pulldown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('37691a94-bbac-5cc5-9fce-327e72bb80ec', 'free-exercise-db', 'One_Arm_Pronated_Dumbbell_Triceps_Extension', 'Tek Kol Triceps Extension (Dambıl, Pronated)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Bir dambılı kol boyu uzaklıkta tutarken düz bir bankta uzanın. Kolunuz vücudunuza dik olmalıdır. Bu egzersiz için pronated tutuş gerektiğinden elinizin avuç içi ayaklarınıza bakmalıdır.", "Kaldırmayan elinizi destek için biceps''inizin üzerine koyun.", "Nefes alırken dambılı yavaşça aşağı indirmeye başlayın.", "Ardından triceps''i kasarak dambılı yukarı kaldırmaya başlayın. Konsantrik (egzersizin kaldırma) kısmında nefes vermeyi unutmayın.", "Set tekrar sayınızı tamamlayana kadar tekrarlayın.", "Kol değiştirin ve hareketi tekrarlayın."]', 'strength', '["One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg", "One_Arm_Pronated_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'One Arm Pronated Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('278a7a16-a3f6-54f8-ba50-061a4ec0ccba', 'free-exercise-db', 'One_Arm_Supinated_Dumbbell_Triceps_Extension', 'Triceps Extension (Dambıl, Tek Kol, Supinasyon)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Kol boyu bir dambılı tutarak sehpaya düz uzanın. Kolunuz vücudunuza dik olmalıdır. Bu egzersizi yapmak için supinasyon tutuş gerektiğinden elinizin avuç içi yüzünüze bakmalıdır.", "Kaldırmayan elinizi destek için biceps''inizin üzerine koyun.", "Nefes alırken dambılı yavaşça aşağı indirmeye başlayın.", "Ardından triceps''i kasarak dambılı yukarı kaldırmaya başlayın. Konsantrik (egzersizin kaldırma) kısmında nefes vermeyi unutmayın.", "Set tekrarlarını tamamlayana kadar tekrarlayın.", "Kolları değiştirin ve hareketi tekrarlayın.", "Tekrar kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg", "One_Arm_Supinated_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'One Arm Supinated Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('00af14cf-e62b-5297-8413-bb17078589b3', 'free-exercise-db', 'One_Half_Locust', 'Yarım Çekirge Pozu', 'static', 'beginner', NULL, '[]', '["quadriceps"]', '["abdominals", "biceps", "chest"]', '["Yere yüzüstü uzanın.", "Kalça kemiğinizi ve kasık kemiğinizi yastıklamak için sol elinizi sol kalça kemiğinizin altına koyun.", "Sağ dizinizi bükün ve ayağınızı sağ elinizle tutabilecek hale getirin.", "Ayağı havaya kaldırın ve aynı anda omuzlarınızı yerden kaldırın. Bu aynı zamanda sağ kalça fleksörünü, göğsü ve omuzları esnetir. Taraf değiştirin. Belinizi rahatsız etmiyorsa, bunu her iki kol ve bacakla aynı anda deneyebilirsiniz."]', 'stretching', '["One_Half_Locust/0.jpg", "One_Half_Locust/1.jpg"]', 150.0, 'One Half Locust', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3c3ca644-1df0-5cf6-aa59-bacbcf846117', 'free-exercise-db', 'One_Handed_Hang', 'Tek El ile Asılma', 'static', 'beginner', NULL, '["other"]', '["lats"]', '["biceps"]', '["Bir elinizle pronasyon tutuşla chin-up barına tutunun. Ayaklarınızı yerde veya bir basamakta tutun. Ayaklarınız yerdeyken ağırlığınızın büyük kısmının o elden asılı kalmasına izin verin. 10-20 saniye bekleyin ve taraf değiştirin."]', 'stretching', '["One_Handed_Hang/0.jpg", "One_Handed_Hang/1.jpg"]', 150.0, 'One Handed Hang', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('de392d30-176d-52d4-8e63-d878a8e1cba1', 'free-exercise-db', 'One_Knee_To_Chest', 'Tek Diz Göğse Çekme Esnetmesi', 'static', 'beginner', 'compound', '[]', '["glutes"]', '["hamstrings", "lower back"]', '["Yere uzanarak başlayın.", "Bir bacağınızı düz uzatın ve diğer dizinizi göğsünüze çekin. Diz kapağını korumak için diz ekleminin altından tutun.", "O dizi hafifçe burnunuza doğru çekin.", "Taraf değiştirin. Bu hareket, bükülü bacağın kalça ve alt sırt bölgesini ve düz bacağın kalça fleksörünü esnetir."]', 'stretching', '["One_Knee_To_Chest/0.jpg", "One_Knee_To_Chest/1.jpg"]', 150.0, 'One Knee To Chest', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1929fb1a-feb3-58a5-b344-19628aae1212', 'free-exercise-db', 'One_Leg_Barbell_Squat', 'Tek Bacak Squat (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Düz bir sehpanın yaklaşık 60-90 cm önünde, sırtınız sehpaya dönük şekilde durarak başlayın. Önünüzde yerde bir halter bulunsun. İpucu: Ayaklarınız birbirinden omuz genişliğinde açık olmalıdır.", "Dizlerinizi bükün ve ellerinizi omuz genişliğinden geniş tutarak pronasyon tutuşla halteri göğsünüze yaslayabileceğiniz noktaya kadar kaldırın.", "Ardından halteri başınızın üzerine kaldırın ve boynunuzun tabanına yerleştirin. Bir ayağınızı geriye alın ve ayak parmağınız düz sehpanın üzerinde dursun. Diğer ayağınız önünüzde sabit kalmalıdır. Aşağı bakmak dengenizi bozacağı için başınızı her zaman yukarıda tutun ve sırtınızı da düz tutun. İpucu: Bu egzersizi yaparken sırtınızın düz ve göğsünüzün dışarıda olduğundan emin olun.", "Nefes alırken bacağınızı uyluğunuz yere paralel olana kadar yavaşça indirin. Bu noktada diziniz ayak parmaklarınızın üzerinde olmalıdır. Göğsünüz uyluğunuzun ortasının tam üzerinde olmalıdır.", "Göğsünüzle ve kalçanızla öncülük ederek ve ön bacak kaslarınızı kasarak, nefes verirken bacağınızı başlangıç pozisyonuna yükseltin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bacak değiştirin ve hareketi tekrarlayın."]', 'strength', '["One_Leg_Barbell_Squat/0.jpg", "One_Leg_Barbell_Squat/1.jpg"]', 360.0, 'One Leg Barbell Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('21b199ce-e347-5289-b74a-d0d1f597b4fd', 'free-exercise-db', 'Open_Palm_Kettlebell_Clean', 'Açık Avuç Clean (Kettlebell)', 'pull', 'expert', 'compound', '["kettlebells"]', '["hamstrings"]', '["glutes", "lower back", "quadriceps", "shoulders"]', '["Bir kettlebell''i ayaklarınızın arasına koyun. Kettlebell''i omuzlarınıza doğru kaldırırken bacaklarınızı ve kalçanızı açarak clean yapın.", "Kettlebell yukarı gelirken bırakın ve kettlebell''in gövdesi avuç içlerinize inecek şekilde dönmesine izin verin.", "Kettlebell''i önünüze bırakın ve sapını iki elinizle yakalayın. Kettlebell''i başlangıç pozisyonuna indirin ve tekrarlayın."]', 'strength', '["Open_Palm_Kettlebell_Clean/0.jpg", "Open_Palm_Kettlebell_Clean/1.jpg"]', 360.0, 'Open Palm Kettlebell Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('aadb7279-8f16-590e-9111-6d810463d9ba', 'free-exercise-db', 'Otis-Up', 'Otis-Up', 'pull', 'beginner', 'compound', '["other"]', '["abdominals"]', '["chest", "shoulders", "triceps"]', '["Ayaklarınızı sabitleyin ve yere doğru yaslanın. Dizleriniz bükülü olmalı. Bir ağırlığı iki elinizle göğsünüzde tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Kalçanızı ve omurganızı bükerek gövdenizi yerden kaldırarak harekete başlayın.", "Yukarı çıkarken, hareketin üst noktasında ağırlık başınızın üzerinde olacak şekilde ağırlığı yukarı itin.", "Mekik hareketini tersine çevirirken ağırlığı göğsünüze geri getirin; tamamen yere inmemeye dikkat edin."]', 'strength', '["Otis-Up/0.jpg", "Otis-Up/1.jpg"]', 360.0, 'Otis-Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8251b021-866e-5565-8f6e-bf1f159a3695', 'free-exercise-db', 'Overhead_Cable_Curl', 'Overhead Biceps Curl (Kablo)', 'pull', 'intermediate', 'isolation', '["cable"]', '["biceps"]', '[]', '["Başlamak için makara makinesinin her iki yanına rahat bir ağırlık ayarlayın. Not: Seçilen ağırlık miktarının her iki tarafta da aynı olduğundan emin olun.", "Şimdi her iki taraftaki makaraların yüksekliğini ayarlayın ve omuzlarınızdan daha yüksekte konumlandırıldıklarından emin olun.", "İki tarafın ortasında durun ve her bir tutamağı ters tutuşla (avuç içleri tavana bakacak şekilde) kavrayın. Kollarınız tamamen uzatılmış ve yere paralel olmalı, ayaklarınız birbirinden omuz genişliğinde açık olmalıdır. Vücudunuz tutamaklarla eşit hizada olmalıdır. Bu başlangıç pozisyonudur.", "Nefes verirken, ön kollarınız ve biceps''iniz birbirine değene kadar her iki taraftaki biceps''i yavaşça sıkın.", "Nefes alırken ön kollarınızı başlangıç pozisyonuna geri getirin. Not: Bu egzersiz sırasında ön kollar dışında tüm vücudunuz sabittir.", "Programınızda belirtilen önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Overhead_Cable_Curl/0.jpg", "Overhead_Cable_Curl/1.jpg"]', 360.0, 'Overhead Cable Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('dc80be1f-7d41-59c0-8011-2a39265b4c42', 'free-exercise-db', 'Overhead_Lat', 'Baş Üstü Lat Esnetme (Partnerli)', 'static', 'expert', NULL, '["other"]', '["lats"]', '["triceps"]', '["Partneriniz arkanızdayken yerde dik oturun. Bir kolunuzu dümdüz yukarı kaldırın ve dirseği bükerek elinizle sırtınıza dokunmaya çalışın. Partneriniz triceps''inizi ve bileğinizi tutmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Partneriniz bunu gerçekten yapmanızı engellerken üst kolunuzu yanınıza çekmeye çalışın.", "10-20 saniye sonra kolunuzu gevşetin ve partnerinizin triceps''e hafif baskı uygulayarak lat kasını daha da esnetmesine izin verin. 10-20 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["Overhead_Lat/0.jpg", "Overhead_Lat/1.jpg"]', 150.0, 'Overhead Lat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('996698fe-9a3e-55d6-9adc-c8c9de21c32d', 'free-exercise-db', 'Overhead_Slam', 'Overhead Slam (Medicine Ball)', 'pull', 'beginner', 'compound', '["medicine ball"]', '["lats"]', '[]', '["Bir medicine ball''u iki elinizle tutun ve ayaklarınız omuz genişliğinde açık şekilde durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Topu başınızın üzerine kaldırarak ve vücudunuzu tamamen uzatarak karşı hareketi (countermovement) başlatın.", "Hareketi tersine çevirerek topu mümkün olduğunca sert bir şekilde doğrudan önünüzdeki yere çarpın.", "Topu zıplarken iki elinizle yakalayın ve hareketi tekrarlayın."]', 'plyometrics', '["Overhead_Slam/0.jpg", "Overhead_Slam/1.jpg"]', 480.0, 'Overhead Slam', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('336669a0-39d1-54c0-8e06-da46369da623', 'free-exercise-db', 'Overhead_Squat', 'Overhead Squat (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["abdominals", "calves", "glutes", "hamstrings", "lower back", "shoulders", "triceps"]', '["Önünüzde yerde bir halter olacak şekilde başlayın. Ayaklarınız omuz genişliğinden daha geniş açık olmalıdır.", "Dizlerinizi bükün ve halteri pronated tutuşla (avuç içleri size bakacak şekilde) kavrayın. Kaldırmadan önce elleriniz omuz genişliğinden daha geniş aralıklı olmalıdır. Konumlandıktan sonra halteri göğsünüze yaslayabileceğiniz noktaya kadar kaldırın.", "Halteri başınızın üzerine ve biraz arkasına taşıyın ve kollarınızın tamamen uzadığından emin olun. Başınızı her zaman yukarıda tutun ve sırtınızı da düz tutun. Kürek kemiklerinizi geriye çekin. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken dizlerinizi bükerek uyluklarınız yere paralel olana kadar ağırlığı yavaşça indirin. İpucu: Herhangi bir sakatlığı önlemek için bu egzersizi yaparken sırtınızı düz tutun ve kollarınız her zaman uzatılmış ve başınızın üzerinde kalmalıdır.", "Şimdi nefes verirken ağırlığı başlangıç pozisyonuna geri getirmek için ayaklarınızı ve bacaklarınızı kullanın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'olympic weightlifting', '["Overhead_Squat/0.jpg", "Overhead_Squat/1.jpg"]', 420.0, 'Overhead Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c9502c5b-24a8-5d63-b9b2-ad5b06e63109', 'free-exercise-db', 'Overhead_Stretch', 'Baş Üstü Esnetme', 'static', 'beginner', 'compound', '[]', '["abdominals"]', '["chest", "forearms", "lats", "triceps"]', '["Dik ayakta dururken parmaklarınızı birbirine kenetleyin ve avuç içlerinizi tavana doğru açın. Kollarınızı yukarı uzatırken omuzlarınızı aşağıda tutun.", "Tam bir gövde esnetmesi yapmak için kuyruk sokumunuzu aşağı çekin ve bunu yaparken gövdenizi stabilize edin. Gövdenin hem ön hem de arka kaslarını esnetin."]', 'stretching', '["Overhead_Stretch/0.jpg", "Overhead_Stretch/1.jpg"]', 150.0, 'Overhead Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9598e84f-a1c1-58b8-bb2c-bc34b61b7245', 'free-exercise-db', 'Overhead_Triceps', 'Triceps Esnetme (Partnerli, Baş Üstü)', 'static', 'expert', NULL, '["body only"]', '["triceps"]', '["lats"]', '["Partneriniz arkanızda olacak şekilde yerde dik oturun. Bir kolunuzu dümdüz yukarı kaldırın ve dirseğinizi bükerek elinizle sırtınıza dokunmaya çalışın. Partneriniz dirseğinizi ve bileğinizi tutmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Partneriniz buna engel olurken kolunuzu havaya doğru dümdüz uzatmaya çalışın.", "10-20 saniye sonra kolunuzu gevşetin ve partnerinizin bileğe hafif baskı uygulayarak triceps''i daha fazla esnetmesine izin verin. 10-20 saniye bekleyin ve ardından taraf değiştirin."]', 'stretching', '["Overhead_Triceps/0.jpg", "Overhead_Triceps/1.jpg"]', 150.0, 'Overhead Triceps', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('41075d08-6b97-5d4a-85e0-2e7e52c501f6', 'free-exercise-db', 'Pallof_Press', 'Pallof Press (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '["chest", "shoulders", "triceps"]', '["Standart bir tutamağı kuleye bağlayın ve mümkünse kabloyu omuz yüksekliğine getirin. Mümkün değilse alt makara da yeterlidir.", "Kabloya yan dönük, tutamağı iki elinizle kavrayın ve kuleden uzaklaşın. Makaradan yaklaşık kol boyu uzaklıkta olmalı ve kablodaki ağırlığın gerginliği hissedilmelidir.", "Ayaklarınız kalça genişliğinde ve dizleriniz hafif bükülü dururken kabloyu göğsünüzün ortasında tutun. Bu sizin başlangıç pozisyonunuzdur.", "Her iki kolunuzu tamamen açarak kabloyu göğsünüzden uzağa itin. Core bölgeniz sıkı ve devrede olmalıdır.", "Başlangıç pozisyonuna dönmeden önce tekrarı birkaç saniye tutun.", "Setin sonunda diğer yöne dönerek tekrarlayın."]', 'strength', '["Pallof_Press/0.jpg", "Pallof_Press/1.jpg"]', 360.0, 'Pallof Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f2ad1b4f-e870-5abc-8950-4e58972e603e', 'free-exercise-db', 'Pallof_Press_With_Rotation', 'Pallof Press (Rotasyonlu)', 'pull', 'beginner', 'compound', '["cable"]', '["abdominals"]', '["chest", "shoulders", "triceps"]', '["Standart bir sapı bir kuleye bağlayın ve kabloyu omuz yüksekliğine getirin.", "Yan tarafınız kabloya dönükken, sapı bir elinizle kavrayın ve kuleden uzaklaşın. Makaradan yaklaşık kol boyu mesafede olmalısınız ve kablo üzerindeki ağırlığın gerginliği hissedilmelidir. Uzattığınız kolu kabloyla hizalayın.", "Ayaklarınız kalça genişliğinde açık şekilde, kabloyu göğsünüze çekin ve sapı diğer elinizle de kavrayın. Bu noktada iki eliniz de sapta olmalıdır.", "İleri bakarak kabloyu göğsünüzden uzağa itin. Karın bölgeniz sıkı ve aktif olmalıdır.", "Kalçanızı düz tutarak, tam bir çeyrek tur dönüş elde edene kadar gövdenizi makaradan uzağa doğru çevirin.", "Sert duruşunuzu ve düz kollarınızı koruyun. Yavaş ve kontrollü bir şekilde nötr pozisyona dönün. Kollarınız önünüzde uzanmış olmalıdır.", "Yan gerginlik karın bölgenizi çalıştırmaya devam ederken, ellerinizi göğsünüze getirin ve hemen tamamen uzanmış pozisyona doğru dışa doğru itin. Bu bir tekrar sayılır.", "Tükenene kadar tekrarlayın.", "Ardından pozisyonunuzu değiştirin ve aynı hareket dizisini karşı tarafta tekrarlayın."]', 'strength', '["Pallof_Press_With_Rotation/0.jpg", "Pallof_Press_With_Rotation/1.jpg"]', 360.0, 'Pallof Press With Rotation', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('03343a41-d84e-54a2-867f-367e9bc5ae8e', 'free-exercise-db', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'Wrist Curl (Dambıl, Avuç İçi Aşağı)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["İki dambılı düz bir bench''in bir yanına yerleştirerek başlayın.", "Vücudunuz düz bench''e dönük olacak şekilde her iki dizinizin üzerinde diz çökün.", "Kollarınızla her iki dambılı pronasyon tutuşla (avuç içleri aşağı bakacak şekilde) kavrayın ve ön kollarınız düz bench''e dayanacak şekilde yukarı getirin. Bilekleriniz kenardan sarkıyor olmalıdır.", "Bileklerinizi yukarı doğru kıvırarak ve nefes vererek başlayın.", "Nefes alırken bileklerinizi yavaşça başlangıç pozisyonuna indirin.", "Ön kollarınız sabit olmalı; bu egzersizi yapmak için gereken tek hareket bileğinizdir.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg", "Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"]', 360.0, 'Palms-Down Dumbbell Wrist Curl Over A Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('87a64172-1819-5157-aaf5-c65fd098c7cc', 'free-exercise-db', 'Palms-Down_Wrist_Curl_Over_A_Bench', 'Wrist Curl (Halter, Avuç İçi Aşağı)', 'pull', 'beginner', 'isolation', '["barbell"]', '["forearms"]', '[]', '["Bir halteri düz bir bench''in bir tarafına yerleştirerek başlayın.", "Vücudunuz düz bench''e dönük olacak şekilde iki dizinizin üzerine çökün.", "Kollarınızla halteri pronasyon (avuç içleri aşağı) tutuşla kavrayın ve ön kollarınız düz bench''e dayanacak şekilde yukarı getirin. Bilekleriniz kenardan sarkmalıdır.", "Nefes verirken bileğinizi yukarı doğru kıvırarak başlayın.", "Nefes alırken bileklerinizi yavaşça başlangıç pozisyonuna indirin.", "Bu egzersizi yapmak için yalnızca bilek hareketi gerekir; ön kollarınız sabit kalmalıdır.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg", "Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg"]', 360.0, 'Palms-Down Wrist Curl Over A Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('69d19657-98b1-5599-817d-753aec2913eb', 'free-exercise-db', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'Sehpa Üzerinde Avuç İçi Yukarı Wrist Curl (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["forearms"]', '[]', '["Bir halteri düz bir sehpanın yanına koyarak başlayın.", "Vücudunuz düz sehpaya dönük olacak şekilde iki dizinizin üzerine çökün.", "Kollarınızla halteri supinasyon tutuşla (avuç içi yukarı) kavrayın ve ön kollarınız düz sehpaya dayanacak şekilde yukarı getirin. Bilekleriniz kenardan sarkmalıdır.", "Bileklerinizi yukarı doğru kıvırarak ve nefes vererek başlayın.", "Nefes alırken bileklerinizi yavaşça başlangıç pozisyonuna indirin.", "Bu egzersizi yapmak için gereken tek hareket bilek olduğundan ön kollarınız sabit kalmalıdır.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg", "Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg"]', 360.0, 'Palms-Up Barbell Wrist Curl Over A Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2c110b45-1971-55d2-b8b6-23ca66763b24', 'free-exercise-db', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'Wrist Curl (Dambıl, Avuç İçi Yukarı, Sehpada)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["Düz bir sehpanın bir yanına iki dambıl yerleştirerek başlayın.", "Vücudunuz düz sehpaya dönük olacak şekilde iki dizinizin üzerine çökün.", "Kollarınızı kullanarak her iki dambılı supinasyon tutuşla (avuç içi yukarı) kavrayın ve ön kollarınız düz sehpaya dayanacak şekilde yukarı getirin. Bilekleriniz kenardan sarkıyor olmalıdır.", "Bileğinizi yukarı doğru kıvırarak ve nefes vererek başlayın.", "Bileklerinizi yavaşça başlangıç pozisyonuna geri indirirken nefes alın. Egzersizin bu kısmında nefes aldığınızdan emin olun.", "Ön kollarınız sabit kalmalıdır; bu egzersizi yapmak için gereken tek hareket bileğinizdir.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg", "Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"]', 360.0, 'Palms-Up Dumbbell Wrist Curl Over A Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('44eda57a-2ad5-5b78-8900-a9aff3623416', 'free-exercise-db', 'Parallel_Bar_Dip', 'Paralel Bar Dips', 'push', 'beginner', 'compound', '["other"]', '["triceps"]', '["chest", "shoulders"]', '["Bir çift paralel barın arasında durun. Her bara bir el koyun, ardından kollarınız kilitli başlangıç pozisyonuna geçmenize yardımcı olması için küçük bir sıçrama yapın.", "Dirseklerinizi bükerek vücudunuzu kollarınız 90 dereceyi geçene kadar indirerek başlayın. Sallanmaktan kaçının ve iniş boyunca iyi bir duruşu koruyun.", "Dirseklerinizi açarak hareketi tersine çevirin ve kendinizi başlangıç pozisyonuna geri itin.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Parallel_Bar_Dip/0.jpg", "Parallel_Bar_Dip/1.jpg"]', 360.0, 'Parallel Bar Dip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4eeab83a-f469-5dc1-86fc-6cd0d704af56', 'free-exercise-db', 'Pelvic_Tilt_Into_Bridge', 'Pelvik Tilt ve Köprü', 'static', 'intermediate', 'compound', '[]', '["lower back"]', '[]', '["Ayaklarınız yerde, topuklarınız dizlerinizin tam altında olacak şekilde uzanın.", "Belinizi esnetmek için yalnızca kuyruk sokumunuzu tavana doğru kaldırın. (Henüz tüm omurgayı kaldırmayın.) Karnınızı içeri çekin.", "Köprü pozisyonuna geçmek için boyun hariç tüm omurgayı kaldırın."]', 'stretching', '["Pelvic_Tilt_Into_Bridge/0.jpg", "Pelvic_Tilt_Into_Bridge/1.jpg"]', 150.0, 'Pelvic Tilt Into Bridge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('55ec3336-5349-506f-a63b-781cc493385d', 'free-exercise-db', 'Peroneals-SMR', 'Dış Baldır (Peroneal) Foam Roll', 'static', 'intermediate', NULL, '["foam roll"]', '["calves"]', '[]', '["Yan yatın; ağırlığınızı ön kolunuz ve alt bacağınızın dış tarafına yerleştirilmiş bir foam roller üzerinde taşıyın. Üst bacağınız alt bacağınızın üzerinde olabilir veya önünüzde çapraz yapabilirsiniz. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kalçanızı yerden kaldırın ve bacağınızın yan tarafında dizin altından ayak bileğinin üstüne kadar yuvarlanmaya başlayın; gerginlik hissettiğiniz noktalarda 10-30 saniye duraklayın. Diğer bacakla tekrarlayın."]', 'stretching', '["Peroneals-SMR/0.jpg", "Peroneals-SMR/1.jpg"]', 150.0, 'Peroneals-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d630352b-09da-50bf-a3ab-f7615ba62216', 'free-exercise-db', 'Peroneals_Stretch', 'Peroneal Kas Esnetme', 'static', 'intermediate', NULL, '["other"]', '["calves"]', '[]', '["Oturur pozisyonda bir kemer, ip veya bandı ayaklarınızdan birine dolayın. Bu sizin başlangıç pozisyonunuzdur.", "Bacak uzatılmış ve topuk yerden kalkmış halde, ayağın iç kısmı size doğru çekilerek ayak içe dönecek şekilde kemeri çekin. 10-20 saniye bekleyin ve ardından taraf değiştirin."]', 'stretching', '["Peroneals_Stretch/0.jpg", "Peroneals_Stretch/1.jpg"]', 150.0, 'Peroneals Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d084590a-214a-5d83-a60b-87c485d66652', 'free-exercise-db', 'Physioball_Hip_Bridge', 'Hip Bridge (Pilates Topu)', 'push', 'beginner', 'compound', '["exercise ball"]', '["glutes"]', '["hamstrings"]', '["Üst sırtınız topun üzerinde ve kalçanız desteksiz olacak şekilde topun üzerine uzanın. Her iki ayak yere düz basmalı ve kalça genişliğinde ya da daha geniş açık olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Kalça ve arka bacak kaslarınızı kullanarak kalçanızı açarak ve köprü yaparken kalçanızı yukarı kaldırarak başlayın.", "Hareketin en üst noktasında bekleyin ve başlangıç pozisyonuna dönün."]', 'strength', '["Physioball_Hip_Bridge/0.jpg", "Physioball_Hip_Bridge/1.jpg"]', 360.0, 'Physioball Hip Bridge', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e54a8bb9-4af6-5bee-b09d-027286497bed', 'free-exercise-db', 'Pin_Presses', 'Pin Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "forearms", "lats", "middle back", "shoulders"]', '["Pin press''ler bench press''in eksantrik fazını ortadan kaldırarak başlangıç gücünü geliştirir. Ayrıca istediğiniz hareket açıklığını çalıştırmanıza da olanak tanır.", "Bench bir power rack içine kurulmalıdır. Pinleri hareket açıklığınızdaki istediğiniz noktaya ayarlayın; bu ister sadece kilitlenme noktası ister göğsünüzden 2,5 cm yukarısı olsun. Bar pinlere getirilmeli ve kaldırmaya hazırlanmalıdır.", "Bench''e uzanarak başlayın; bar, normal bench press''inizdeki temas noktasının tam üzerinde olsun. Ayaklarınızı altınıza çekin ve sırtınızı kavisli tutun. Ağırlığınızı desteklemek için barı kullanarak omuzlarınızı bench''ten kaldırın ve geriye çekin, kürek kemiklerinizi birbirine sıkıştırın. Ayaklarınızı kullanarak trapez kaslarınızı bench''e doğru bastırın. Hareket boyunca bu sıkı vücut pozisyonunu koruyun.", "Standart bir bench tutuşu veya triceps''e odaklanmak için omuz genişliğinde bir tutuş alabilirsiniz. Bar, bilek ve dirsek her zaman aynı hizada kalmalıdır. Barı sıkmaya ve ikiye ayırmaya çalışmaya odaklanın.", "Barı mümkün olan en büyük kuvvetle yukarı itin. Dirsekler kilitlenmeye kadar içeride kalmalıdır.", "Bir sonraki tekrara başlamadan önce duraklayarak barı pinlere geri bırakın."]', 'powerlifting', '["Pin_Presses/0.jpg", "Pin_Presses/1.jpg"]', 360.0, 'Pin Presses', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a9cf8a24-25b1-5561-9b91-b1a30c35860a', 'free-exercise-db', 'Piriformis-SMR', 'Piriformis Masajı (Foam Roller)', 'static', 'intermediate', 'isolation', '["foam roll"]', '["glutes"]', '[]', '["Kalçanız bir foam roller''ın üzerinde olacak şekilde oturun. Dizlerinizi bükün, ardından bir bacağınızı ayak bileği diğer dizin üzerinde olacak şekilde çaprazlayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Ağırlığınızı çaprazlanmış bacağın tarafına kaydırın ve üst kalça kasınızda gerginlik hissedene kadar kalçanızın üzerinde yuvarlanın. Bükülü dizi göğsünüze doğru çekmek için bir elinizi kullanarak esnemeye yardımcı olabilirsiniz. Bu pozisyonu 10-30 saniye koruyun, ardından taraf değiştirin."]', 'stretching', '["Piriformis-SMR/0.jpg", "Piriformis-SMR/1.jpg"]', 150.0, 'Piriformis-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3f494b65-ad16-5aeb-bf73-597f6a1fab03', 'free-exercise-db', 'Plank', 'Plank', 'static', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Yerde yüzüstü pozisyon alın ve ağırlığınızı ayak parmaklarınız ve ön kollarınız üzerinde taşıyın. Kollarınız bükülü ve tam omuzlarınızın altında olmalıdır.", "Vücudunuzu her zaman düz tutun ve bu pozisyonu olabildiğince uzun süre koruyun. Zorluğu artırmak için bir kol veya bacak kaldırılabilir."]', 'strength', '["Plank/0.jpg", "Plank/1.jpg"]', 360.0, 'Plank', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c0eca962-ba74-5855-9618-a0a54db14ced', 'free-exercise-db', 'Plate_Pinch', 'Plaka Tutma (Pinch Grip)', 'static', 'intermediate', 'isolation', '["other"]', '["forearms"]', '[]', '["Geniş kenarlı iki plakayı alın ve düz yüzleri dışarı bakacak şekilde birbirine yapıştırın.", "Parmaklarınızı plakanın dış kısmını kavramak için, başparmağınızı ise diğer taraf için kullanarak iki plakayı bir arada tutun. Bu başlangıç pozisyonudur.", "Plakayı parmaklarınız ve başparmağınızla sıkın. Bu pozisyonu elinizden geldiğince uzun süre tutun.", "Programınızda belirtilen set sayısı kadar tekrarlayın.", "Kolları değiştirin ve hareketleri tekrarlayın."]', 'strength', '["Plate_Pinch/0.jpg", "Plate_Pinch/1.jpg"]', 360.0, 'Plate Pinch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('62d310db-a659-5a78-a935-9faf872930f6', 'free-exercise-db', 'Plate_Twist', 'Plaka ile Gövde Çevirme', 'pull', 'intermediate', 'compound', '["other"]', '["abdominals"]', '[]', '["Bacaklarınız tamamen uzamış ve üst vücudunuz dik halde yere veya bir egzersiz matına oturun. Plakayı yanlarından iki elinizle, kolları hafifçe bükülü şekilde karın kaslarınızın önünde tutun.", "Bacaklarınızı ayak bileklerine yakın yerden yavaşça çaprazlayın ve yerden kaldırın. Dizleriniz de hafifçe bükülü olmalıdır. Not: Bu egzersizi yaparken dengenizi korumaya yardımcı olması için üst vücudunuzu hafifçe geriye alın. Bu başlangıç pozisyonudur.", "Plakayı sol tarafa götürün ve yere dokundurun. Bu hareketi yaparken nefes verin.", "Nefes alırken başlangıç pozisyonuna dönün ve ardından hareketi bu sefer vücudun sağ tarafına doğru tekrarlayın. İpucu: Her zaman yavaş ve kontrollü hareket kullanın. Sert hareketler sırtı sakatlayabilir.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Plate_Twist/0.jpg", "Plate_Twist/1.jpg"]', 360.0, 'Plate Twist', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1a34a33b-7a82-57e2-abc1-3bed98c5c044', 'free-exercise-db', 'Platform_Hamstring_Slides', 'Arka Bacak Kaydırma (Zeminde)', 'pull', 'beginner', 'isolation', '["other"]', '["hamstrings"]', '["glutes"]', '["Bu hareket için ahşap veya benzeri bir zemin gerekir. Bacaklarınız uzatılmış şekilde sırtüstü uzanın. Topuğunuzun altına bir spor havlusu veya hafif bir ağırlık koyun. Bu sizin başlangıç pozisyonunuzdur.", "Diğer bacağınızı düz tutarak dizinizi bükerek harekete başlayın.", "Topuğu zeminde kaydırarak size yaklaştırmaya devam edin.", "Dizin tam bükülme noktasında, başlangıç pozisyonuna dönmek için hareketi tersine çevirin."]', 'strength', '["Platform_Hamstring_Slides/0.jpg", "Platform_Hamstring_Slides/1.jpg"]', 360.0, 'Platform Hamstring Slides', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ba0b2fd7-ce4f-5e73-8709-78c5fb2a56b3', 'free-exercise-db', 'Plie_Dumbbell_Squat', 'Plie Squat (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["quadriceps"]', '["abdominals", "calves", "glutes", "hamstrings"]', '["Bir dambılı tabanından iki elinizle tutun ve dik durun. Bacaklarınızı omuz genişliğinden daha geniş açın ve dizlerinizi hafif bükün.", "Ayak uçlarınız dışa bakmalıdır. Not: Egzersizi yaparken kollarınız sabit olmalıdır. Bu başlangıç pozisyonudur.", "Dizlerinizi yavaşça bükün ve uyluklarınız yere paralel olana kadar bacaklarınızı indirin. Bu egzersizin eksantrik kısmı olduğundan nefes aldığınızdan emin olun.", "Nefes verirken vücudunuzu başlangıç pozisyonuna getirmek için ağırlıklı olarak ayağınızın topuğuyla itin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Plie_Dumbbell_Squat/0.jpg", "Plie_Dumbbell_Squat/1.jpg"]', 360.0, 'Plie Dumbbell Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8eb506b9-f9d0-5aa4-820f-e9e85f62528e', 'free-exercise-db', 'Plyo_Kettlebell_Pushups', 'Plyo Şınav (Kettlebell)', 'push', 'expert', 'compound', '["kettlebells"]', '["chest"]', '["shoulders", "triceps"]', '["Bir kettlebell''i yere yerleştirin. Şınav pozisyonuna geçin; ayak parmaklarınızın üzerinde, bir eliniz yerde ve bir eliniz kettlebell''i tutarken, dirsekleriniz uzatılmış olsun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sırtınızı düz tutarak gidebildiğiniz kadar aşağı inerek başlayın.", "Hızlı ve güçlü bir şekilde yön değiştirin, kendinizi kettlebell''in diğer tarafına doğru yukarı itin ve bunu yaparken ellerinizi değiştirin. Hareketi inerek ve ileri geri tekrarlayarak sürdürün."]', 'strength', '["Plyo_Kettlebell_Pushups/0.jpg", "Plyo_Kettlebell_Pushups/1.jpg"]', 360.0, 'Plyo Kettlebell Pushups', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('04fa69f2-6dd0-502d-a906-b05601f3722c', 'free-exercise-db', 'Plyo_Push-up', 'Plyo Şınav', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Zeminde yüzüstü pozisyona geçin ve ağırlığınızı ellerinizle ve ayak parmaklarınızla taşıyın.", "Kollarınız tamamen uzamış ve eller yaklaşık omuz genişliğinde olmalıdır. Hareket boyunca vücudunuzu düz tutun. Bu sizin başlangıç pozisyonunuzdur.", "Göğsünüzü yere doğru indirerek dirseklerinizden bükülüp inin.", "En altta hareketi tersine çevirin; dirseklerinizi açarak kendinizi olabildiğince hızlı yukarı itin. Ellerinizin yerden kesileceği kadar üst vücudunuzu yukarı itmeye çalışın.", "Başlangıç pozisyonuna dönün ve egzersizi tekrarlayın.", "Zorluğu artırmak için havadayken harekete alkış ekleyin."]', 'plyometrics', '["Plyo_Push-up/0.jpg", "Plyo_Push-up/1.jpg"]', 480.0, 'Plyo Push-up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d9bf30ba-b486-5201-9eba-f0450e88bd9c', 'free-exercise-db', 'Posterior_Tibialis_Stretch', 'Arka Tibialis Esnetme', 'static', 'intermediate', NULL, '["other"]', '["calves"]', '[]', '["Oturur pozisyonda bir kemer, ip veya bandı bir ayağınızın etrafından geçirin. Bu sizin başlangıç pozisyonunuzdur.", "Bacak uzatılmış ve topuk yerden kalkık halde, ayak dışa dönük (evert) olacak şekilde, ayağın dış kenarı size doğru çekilecek biçimde kemeri çekin. 10-20 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["Posterior_Tibialis_Stretch/0.jpg", "Posterior_Tibialis_Stretch/1.jpg"]', 150.0, 'Posterior Tibialis Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c70fa0db-3b76-5e5d-873d-a686134f5113', 'free-exercise-db', 'Power_Clean', 'Power Clean', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["calves", "forearms", "glutes", "lower back", "middle back", "quadriceps", "shoulders", "traps", "triceps"]', '["Ayaklarınız omuz genişliğinden biraz daha geniş ve parmak uçlarınız hafifçe dışa bakacak şekilde durun.", "Çömelin ve barı kapalı, pronasyon tutuşla kavrayın. Elleriniz omuz genişliğinden biraz daha geniş, dizlerin dışında ve dirsekler tamamen uzatılmış olmalıdır.", "Barı kaval kemiklerinizin yaklaşık 2,5 cm önüne ve ayak parmak diplerinizin üzerine yerleştirin.", "Sırtınız düz veya hafifçe kavisli, göğsünüz yukarıda ve dışarıda olmalı ve kürek kemikleriniz geriye çekilmiş olmalıdır.", "Başınızı nötr pozisyonda (omurga ile aynı hizada, eğik veya dönük olmadan) ve gözlerinizi düz ileriye odaklanmış halde tutun. Bu aşamada nefes alın.", "Nefes verirken kalçanızı ve dizlerinizi güçlü bir şekilde açarak barı yerden kaldırın. İpucu: Üst gövde aynı açıyı korumalıdır. Henüz belinizden bükülmeyin ve kalçanın omuzlardan önce yükselmesine izin vermeyin (bu, kalçayı havaya itme ve arka bacak kaslarını germe etkisi yaratır).", "Dirseklerinizi tamamen uzatılmış, başınızı nötr pozisyonda ve omuzlarınızı barın üzerinde tutun.", "Bar yükselirken onu mümkün olduğunca kaval kemiklerinize yakın tutun.", "Bar dizlerinizi geçerken, kilitlenmelerini önlemek için kalçanızı ileri itin ve dizlerinizi hafifçe bükün. İpucu: Bu noktada uyluklarınız bara dayanmış olmalıdır.", "Sırtınızı düz veya hafifçe kavisli, dirseklerinizi tamamen uzatılmış ve başınızı nötr tutun. İpucu: Bir sonraki aşamaya kadar nefesinizi tutacaksınız.", "Nefes alın ve ardından kalçanızı ve dizlerinizi güçlü ve hızlı bir şekilde açıp parmak uçlarınızda yükselin.", "Barı vücudunuza mümkün olduğunca yakın tutun. İpucu: Sırtınız düz, dirsekler yanlara dönük ve başınız nötr pozisyonda olmalıdır. Ayrıca omuzlarınızı barın üzerinde ve kollarınızı mümkün olduğunca uzun süre düz tutun.", "Alt vücut eklemleriniz tamamen açıldığında, dirseklerin henüz bükülmesine izin vermeden omuzlarınızı hızla yukarı doğru silkin. Hareketin bu kısmında nefes verin.", "Omuzlar en yüksek yüksekliğe ulaştığında, vücudunuzu barın altına çekmeye başlamak için dirseklerinizi bükün.", "Kollarınızı mümkün olduğunca yukarı ve uzun süre çekmeye devam edin. İpucu: Bu aşamanın patlayıcı doğası nedeniyle gövdeniz dik veya sırtınız kavisli olacak, başınız hafifçe geriye eğilecek ve ayaklarınız yerle temasını kaybedebilir.", "Alt vücut tamamen açıldıktan ve bar neredeyse maksimum yüksekliğe ulaştıktan sonra, vücudunuzu barın altına çekin ve kollarınızı barın etrafında ve altında döndürün.", "Aynı anda kalçanızı ve dizlerinizi çeyrek squat pozisyonuna bükün.", "Kollar barın altına geldiğinde nefes alın, ardından üst kollarınızı yere paralel konumlandırmak için dirseklerinizi kaldırın. Barı köprücük kemiklerinizin ve ön omuz kaslarınızın önüne yerleştirin (rack).", "Barı dik ve sıkı bir gövde, nötr baş pozisyonu ve düz ayaklarla yakalayın. Bu hareket sırasında nefes verin.", "Kalçanızı ve dizlerinizi tamamen dik bir pozisyona açarak ayağa kalkın.", "Barın uyluklarınıza kontrollü inmesine izin vermek için kollardaki kas gerginliğini kademeli olarak azaltarak barı indirin. Bu hareket sırasında nefes alın.", "Barın uyluklarınıza çarpma etkisini sönümlemek için aynı anda kalçanızı ve dizlerinizi bükün.", "Dirsekleriniz tamamen uzatılmış halde, bar yere değene kadar çömelin.", "1. Aşamadan yeniden başlayın ve önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Power_Clean/0.jpg", "Power_Clean/1.jpg"]', 360.0, 'Power Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e2ec4504-047b-5ed6-aadc-60723666dba1', 'free-exercise-db', 'Power_Clean_from_Blocks', 'Power Clean (Halter, Box Üzerinden)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["quadriceps"]', '["Halter istenen yükseklikteki box''ların üzerindeyken, bacaklarınızın hemen dışından bir tutuşla kavrayın. Ağırlığı topuklarınıza vererek kalçanızı alçaltın; sırtınız düz, başınız ileri bakıyor, göğsünüz yukarıda ve omuzlarınız barın hemen önünde olsun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Topuklarınızdan iterek ve dizlerinizi açarak ilk çekişe başlayın. Sırt açınız aynı kalmalı ve kollarınız düz durmalıdır. Bar uyluğun ortasına yaklaştığında kalçanızı açmaya başlayın.", "Zıplama hareketiyle kalça, diz ve ayak bileklerinizi açarak hızlanın ve barı yukarı hareket ettirmek için hızdan yararlanın. Ağırlığı hızlandırmak için kollarla aktif olarak çekmeye gerek yoktur. İkinci çekişin sonunda vücut tamamen açılmış, hafifçe geriye eğik ve kollar hâlâ uzamış olmalıdır.", "Tam açılmaya ulaşıldığında, omuzlarınızı sertçe silkerek (shrug) ve dirsekleriniz yukarı ve dışarı bakacak şekilde kollarınızı bükerek üçüncü çekişe geçin. En yüksek açılma noktasında, bar omuzlarınıza oturabilecek kadar kendinizi barın altına çekin ve bunu yaparken dirseklerinizi barın altına doğru döndürün. Bar, öne doğru yuvarlanmış omuzlarınızın üzerine oturmalı, ellerinizi gevşek tutarak boğazınıza hafifçe değmelidir.", "Topuklarınızdan iterek, gövdenizi dik ve dirseklerinizi yukarıda tutarak hemen toparlanın. Ayakta duruş pozisyonuna yükselene kadar devam edin ve ağırlığı box''ların üzerine geri indirerek tekrarı tamamlayın."]', 'olympic weightlifting', '["Power_Clean_from_Blocks/0.jpg", "Power_Clean_from_Blocks/1.jpg"]', 420.0, 'Power Clean from Blocks', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5ade5072-2066-53df-9426-ea79e2db2ca6', 'free-exercise-db', 'Power_Jerk', 'Power Jerk (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["abdominals", "calves", "glutes", "hamstrings", "shoulders", "triceps"]', '["Ağırlık omuzlarınızın önünde rafta dururken ayakta durarak dip ile başlayın. Ayaklarınız tam kalçanızın altındayken kalçanızı geriye hareket ettirmeden dizlerinizi bükün. Yalnızca hafifçe aşağı inin ve olabildiğince güçlü şekilde yön değiştirin.", "Olabildiğince fazla hız ve kuvvet yaratmak için topuklarınızla itin ve halter omuzlarınızdan ayrılırken başınızı yoldan çekmeyi unutmayın.", "Ayaklar yerden ayrıldığı bu anda, ayaklar olabildiğince hızlı şekilde karşılama pozisyonuna yerleştirilmelidir. Ayakların platforma aktif olarak basmadığı kısa anda, sporcunun halteri yukarı itme çabası onları aşağı sürecektir. Ayaklar, dizler kısmen bükülü şekilde biraz daha geniş bir duruşa taşınmalıdır.", "Halteri kollarınız tepenizde kilitli şekilde karşılayın.", "Ayakta durma pozisyonuna dönün."]', 'olympic weightlifting', '["Power_Jerk/0.jpg", "Power_Jerk/1.jpg"]', 420.0, 'Power Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('06201450-231c-51b8-8d0c-00dedaa40df2', 'free-exercise-db', 'Power_Partials', 'Power Partials (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Gövdeniz dik ve her elinizde bir dambıl kol boyu uzaklıkta tutulur şekilde ayakta durun. Dirsekler gövdeye yakın olmalıdır.", "Avuç içleri gövdenize bakmalıdır. Ayaklarınız yaklaşık omuz genişliğinde açık olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı düz ve gövdenizi sabit tutarak, nefes verirken ağırlıkları yanlara doğru yaklaşık omuz yüksekliğine kadar kaldırın.", "Kasılmayı bir saniye hissedin ve nefes alırken ağırlıkları başlangıç pozisyonuna indirmeye başlayın. İpucu: Ağırlıkları kaldırırken ve indirirken avuç içlerini aşağı bakacak ve küçük parmak biraz daha yukarıda olacak şekilde tutun; bu, yükü ağırlıklı olarak omuzlarınıza odaklayacaktır.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Power_Partials/0.jpg", "Power_Partials/1.jpg"]', 360.0, 'Power Partials', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0401e138-8cc9-59dc-a5cb-fb024f2ed453', 'free-exercise-db', 'Power_Snatch', 'Power Snatch (Halter)', 'pull', 'expert', 'compound', '["barbell"]', '["hamstrings"]', '["calves", "glutes", "lower back", "quadriceps", "shoulders", "traps", "triceps"]', '["Yerde yüklü bir halterle başlayın. Bar kaval kemiklerine yakın veya değiyor olmalı ve barı geniş bir tutuşla kavrayın. Ayaklar kalçanın tam altında olmalı, gerektiği kadar dışa çevrilmiş olabilir. Göğsünüz yukarıda ve başınız ileri bakacak şekilde kalçanızı alçaltın. Omuzlar barın hemen önünde olmalıdır. Bu başlangıç pozisyonu olacaktır.", "Topukların ön kısmından iterek barı yerden kaldırarak ilk çekişe başlayın. Bar dizlerin önünden geçene kadar sırt açısı aynı kalmalıdır.", "Kalça, diz ve ayak bileklerinizi açarak barı olabildiğince hızlı yukarı sürerek ikinci çekişe geçin. Bar vücuda yakın olmalıdır. En yüksek açılma noktasında omuzlarınızı silkin ve dirseklerin yana doğru bükülmesine izin verin.", "Ayaklarınızı biraz daha geniş olan karşılama pozisyonuna getirirken, barı baş üstüne yükseltirken kendinizi barın altına çekin. Bar kısmi bir squat içinde karşılanmalıdır. Barı baş üstü pozisyonuna kaldırmaya devam edin ve barı baş üstünde kilitli olarak karşılayın.", "Ağırlık baş üstündeyken ayakta duruş pozisyonuna dönün."]', 'olympic weightlifting', '["Power_Snatch/0.jpg", "Power_Snatch/1.jpg"]', 420.0, 'Power Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7377db4a-558e-55ac-aba9-e7ad54837463', 'free-exercise-db', 'Power_Snatch_from_Blocks', 'Blok Üzerinden Power Snatch (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "forearms", "glutes", "hamstrings", "lower back", "shoulders", "traps", "triceps"]', '["Yüklenmiş bir halteri istenen yükseklikteki kutular ya da standlar üzerinde başlayın. Barı geniş bir tutuşla kavrayın. Ayaklar kalçanın tam altında olmalı, gerekirse dışa dönük olmalıdır. Göğsünüz yukarıda ve başınız ileri bakar şekilde kalçanızı alçaltın. Omuzlar barın hemen önünde, dirsekler dışa dönük olmalıdır. Bu başlangıç pozisyonu olacaktır.", "Ayak topuklarınızın ön kısmıyla iterek barı kutulardan kaldırarak ilk çekişi başlatın.", "Kalçanızı, dizlerinizi ve ayak bileklerinizi açarak ikinci çekişe geçin ve barı olabildiğince hızlı yukarı sürün. Bar vücuda yakın olmalıdır. Maksimum açılma anında omuzlarınızı silkin ve dirseklerin yana doğru bükülmesine izin verin.", "Ayaklarınızı karşılama pozisyonuna taşırken, barı başınızın üzerine yükseltirken kendinizi barın altına kuvvetle çekin. Ayaklar kalçanın hemen dışına, gerektiği kadar dışa dönük şekilde hareket etmelidir. Barı tam squat''ın üzerinde ve kollar başın üzerinde tamamen uzanmış halde karşılayın.", "Barı ayak topuklarının önü hizasında tutarak, başınız ve göğsünüz yukarıda olacak şekilde, ayakta durma pozisyonuna geçmek için ayak topuklarınızdan itin. Ağırlığı dikkatlice kutulara geri bırakın."]', 'olympic weightlifting', '["Power_Snatch_from_Blocks/0.jpg", "Power_Snatch_from_Blocks/1.jpg"]', 420.0, 'Power Snatch from Blocks', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c1c19d4b-ff93-54ca-b43c-34eb9e16c63f', 'free-exercise-db', 'Power_Stairs', 'Power Stairs (Merdivene Ağırlık Taşıma)', 'pull', 'intermediate', 'compound', '["other"]', '["hamstrings"]', '["adductors", "calves", "glutes", "lower back", "quadriceps", "shoulders", "traps"]', '["Power stairs''te ekipmanlar bir merdivenden yukarı taşınır. Antrenman amacıyla bunlar bir lastik veya kutu ile yapılabilir.", "Ekipmanı iki elinizle alarak başlayın. Ayaklarınızı geniş açın, başınız ve göğsünüz yukarıda olsun. Ağırlığı yerden kaldırmak için dizlerinizi ve kalçanızı açarak topuklarınızla zemini itin.", "Geriye doğru yaslanırken ağırlığı genellikle 16-18 inç (40-45 cm) yüksekliğindeki merdivene savurmaya çalışın. Ağırlığı basamağa itmeye yardımcı olması için bacaklarınızı kullanabilirsiniz.", "3-5 tekrar yapın ve olabildiğince hızlı hareket ederek daha ağır bir ağırlıkla devam edin."]', 'strongman', '["Power_Stairs/0.jpg", "Power_Stairs/1.jpg"]', 480.0, 'Power Stairs', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e5be253e-dd55-5ae6-8f33-252867b7a9b7', 'free-exercise-db', 'Preacher_Curl', 'Preacher Curl (EZ Bar)', 'pull', 'beginner', 'isolation', '["barbell"]', '["biceps"]', '[]', '["Bu hareketi yapmak için bir preacher bankına ve bir EZ bar''a ihtiyacınız olacak. EZ curl barı dar iç sapından kavrayın (birinin size barı vermesi tercih edilir veya çoğu preacher bankında bulunan ön bar yatağından alın). Avuç içleriniz öne bakmalı ve barın şekli nedeniyle hafifçe içe doğru eğik olmalıdır.", "Üst kollar preacher bankının pedine yaslı ve göğsünüz ona dayalı şekilde, EZ Curl barı omuz uzunluğunda tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken, üst kolunuz uzayana ve biceps tamamen gerilene kadar barı yavaşça indirin.", "Nefes verirken, biceps tamamen kasılana ve bar omuz hizasına gelene kadar ağırlığı biceps ile yukarı kıvırın. Biceps''i sert şekilde sıkın ve bu pozisyonu bir saniye tutun.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Preacher_Curl/0.jpg", "Preacher_Curl/1.jpg"]', 360.0, 'Preacher Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f5e1db62-b8a1-5b40-8a0b-6c6bbb8ecb3d', 'free-exercise-db', 'Preacher_Hammer_Dumbbell_Curl', 'Preacher Hammer Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Her elinizde avuç içleri birbirine bakacak şekilde (nötr tutuş) bir dambıl tutarken her iki kolunuzun üst kısmını preacher bench''in üzerine yerleştirin.", "Nefes alırken, üst kolunuz uzanıp biceps''iniz tamamen gerilene kadar dambılları yavaşça indirin.", "Nefes verirken, biceps''inizi tamamen kasılana ve dambıllar omuz yüksekliğine gelene kadar kullanarak ağırlığı yukarı kıvırın.", "Kasılmış pozisyonda biceps''i bir saniye sertçe sıkın ve önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Preacher_Hammer_Dumbbell_Curl/0.jpg", "Preacher_Hammer_Dumbbell_Curl/1.jpg"]', 360.0, 'Preacher Hammer Dumbbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7fe8e6e3-f65e-5b01-8321-dc74ddf5d7ce', 'free-exercise-db', 'Press_Sit-Up', 'Press Sit-Up (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["abdominals"]', '["chest", "shoulders", "triceps"]', '["Başlamak için göğsünüzde bir halter olacak şekilde bir sehpaya uzanın. Bacaklarınızı karın sehpasının uzantısına sabit şekilde yerleştirin. Bu başlangıç pozisyonudur.", "Nefes alırken karın kaslarınızı ve kalça kaslarınızı sıkın. Aynı anda sit-up yaparken olduğu gibi gövdenizi kıvırın ve nefes verirken halteri başınızın üzerine itin. İpucu: Karın kaslarına odaklanmaya devam ederken halteri dışarı itmek için kollarınızı kullanın.", "Halteri gövdenize geri indirirken üst vücudunuzu da başlangıç pozisyonuna indirin. Vücudu indirirken nefes almayı unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Press_Sit-Up/0.jpg", "Press_Sit-Up/1.jpg"]', 360.0, 'Press Sit-Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4374a9e6-a868-5307-a8b0-8aa80fd0fc9e', 'free-exercise-db', 'Prone_Manual_Hamstring', 'Yüzüstü Arka Bacak Curl (Partnerli Dirençli)', 'static', 'beginner', 'isolation', '[]', '["hamstrings"]', '[]', '["Bu egzersiz için bir partnere ihtiyacınız olacak. Bacaklarınız düz şekilde yüzüstü uzanın. Yardımcınız elini topuğunuza koyacak.", "Başlamak için bacağınızı yukarı kıvırmak üzere dizinizi bükün. Partneriniz direnç sağlamalı, hafif başlayıp hareket tamamlanırken baskıyı artırmalıdır. Uygun direnç seviyelerini takip etmek için partnerinizle iletişim kurun.", "Üst noktada durun ve partneriniz diğer yönde direnç sağlarken bacağı başlangıç pozisyonuna geri getirin."]', 'strength', '["Prone_Manual_Hamstring/0.jpg", "Prone_Manual_Hamstring/1.jpg"]', 360.0, 'Prone Manual Hamstring', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b77c5885-88bc-58db-b2ff-e9b404cee0c0', 'free-exercise-db', 'Prowler_Sprint', 'Prowler Sprint (Kızak İtme)', 'push', 'beginner', 'compound', '["other"]', '["hamstrings"]', '["calves", "chest", "glutes", "quadriceps", "shoulders"]', '["Kızağınızı uygun bir zemine yerleştirin ve uygun bir ağırlıkla yükleyin. Kızak çaba gerektirecek kadar direnç sağlamalı, ancak sizi belirgin şekilde yavaşlatacak kadar ağır olmamalıdır.", "Bu egzersiz için dik veya alçak tutacakları kullanabilirsiniz. Ellerinizi kollarınız uzamış halde tutacaklara yerleştirin ve aletin üzerine yaslanın.", "İyi bir duruşla, dönüşümlü kısa adımlarla zemini iterek ilerleyin. Kısa bir mesafe boyunca olabildiğince hızlı hareket edin."]', 'cardio', '["Prowler_Sprint/0.jpg", "Prowler_Sprint/1.jpg"]', 600.0, 'Prowler Sprint', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5ee02def-39ee-580c-9723-028f6cadbf1a', 'free-exercise-db', 'Pull_Through', 'Pull Through (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["glutes"]', '["hamstrings", "lower back"]', '["Halat veya sap takılı alçak bir makaranın birkaç feet önünde ayakta durarak başlayın. Makineye sırtınız dönük, kabloyu bacaklarınızın arasına alarak ve ayaklarınız geniş açık olacak şekilde durun.", "Kalçanızdan eğilerek bacaklarınızın arasından olabildiğince uzağa uzanarak harekete başlayın. Dizlerinizi hafif bükülü tutun. Kollarınızı düz tutarak kalçanızı açıp dik şekilde ayağa kalkın. Omuzlardan yukarı çekmekten kaçının; tüm hareket kalçadan başlamalıdır."]', 'strength', '["Pull_Through/0.jpg", "Pull_Through/1.jpg"]', 360.0, 'Pull Through', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('14fd9129-e0d6-5c61-870e-91ea0b2307bc', 'free-exercise-db', 'Pullups', 'Barfiks', 'pull', 'beginner', 'compound', '["body only"]', '["lats"]', '["biceps", "middle back"]', '["Barfiks barını, belirlenen tutuşu kullanarak avuç içleri ileri bakacak şekilde kavrayın. Tutuşlar hakkında not: Geniş tutuş için ellerinizin omuz genişliğinizden daha geniş aralıklı olması gerekir. Orta tutuş için ellerin omuz genişliğine eşit aralıkta, dar tutuş için omuz genişliğinden daha dar aralıkta olması gerekir.", "İki kolunuz seçtiğiniz tutuş genişliğinde barı tutarak önünüzde uzanmışken, alt sırtınızda bir kavis oluştururken ve göğsünüzü dışarı çıkarırken gövdenizi yaklaşık 30 derece geriye getirin. Bu sizin başlangıç pozisyonunuzdur.", "Omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek bar üst göğsünüze değene kadar gövdenizi yukarı çekin. Hareketin bu kısmında nefes verin. İpucu: Tam kasılmış pozisyona ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde uzayda hareket ederken sabit kalmalı ve sadece kollar hareket etmelidir. Ön kollar barı tutmaktan başka bir iş yapmamalıdır.", "Kasılmış pozisyonda bir saniye bekledikten sonra nefes almaya başlayın ve kollarınız tamamen uzanıp latissimus kaslarınız tamamen gerilene kadar gövdenizi yavaşça başlangıç pozisyonuna indirin.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Pullups/0.jpg", "Pullups/1.jpg"]', 360.0, 'Pullups', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b66a3467-6059-5232-ab4e-ac6309458fd0', 'free-exercise-db', 'Push-Up_Wide', 'Geniş Şınav', NULL, 'beginner', 'compound', '["body only"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Ellerinizi geniş açarak, vücudunuzu ayak parmaklarınız ve ellerinizle plank pozisyonunda destekleyin. Dirsekleriniz uzamış ve vücudunuz düz olmalıdır. Kalçanızın çökmesine izin vermeyin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başlamak için nefes alırken dirseklerinizin bükülmesine izin vererek göğsünüzü yere doğru indirin.", "Göğüs kaslarınızı kullanarak dirseklerinizi açarak üst vücudunuzu başlangıç pozisyonuna geri itin. Bu adımı yaparken nefes verin.", "Kasılmış pozisyonda duraklamanın ardından hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Push-Up_Wide/0.jpg", "Push-Up_Wide/1.jpg"]', 360.0, 'Push-Up Wide', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8a5c40ca-6569-5f70-ad0f-7de80c91e124', 'free-exercise-db', 'Push-Ups_-_Close_Triceps_Position', 'Şınav (Dar Triceps Tutuşu)', 'push', 'intermediate', 'compound', '["body only"]', '["triceps"]', '["chest", "shoulders"]', '["Yüzüstü yere uzanın ve dar el pozisyonu için ellerinizi omuz genişliğinden daha yakın yerleştirin. Gövdenizi kol boyu kadar yukarıda tuttuğunuzdan emin olun.", "Nefes alırken göğsünüz neredeyse yere değene kadar kendinizi indirin.", "Triceps''inizi ve göğüs kaslarınızın bir kısmını kullanarak üst vücudunuzu başlangıç pozisyonuna geri itin ve göğsünüzü sıkın. Bu adımı yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra hareketi belirtilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Push-Ups_-_Close_Triceps_Position/0.jpg", "Push-Ups_-_Close_Triceps_Position/1.jpg"]', 360.0, 'Push-Ups - Close Triceps Position', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('64eb2e1a-7759-5582-bd35-9ffb712b13a3', 'free-exercise-db', 'Push-Ups_With_Feet_Elevated', 'Ayaklar Yükseltilmiş Şınav', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Yere yüzüstü uzanın ve ellerinizi birbirinden yaklaşık 90 cm aralıkla koyarak gövdenizi kollarınız uzanmış şekilde yukarıda tutun.", "Ayak parmaklarınızı düz bir sehpanın üzerine yerleştirin. Bu, vücudunuzun yükseltilmesini sağlayacaktır. Not: Düz sehpanın yüksekliği arttıkça egzersizin direnci de artar.", "Nefes alırken göğsünüz neredeyse yere değene kadar kendinizi indirin.", "Göğüs kaslarınızı kullanarak üst vücudunuzu başlangıç pozisyonuna geri itin ve göğsünüzü sıkın. Bu adımı yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Push-Ups_With_Feet_Elevated/0.jpg", "Push-Ups_With_Feet_Elevated/1.jpg"]', 360.0, 'Push-Ups With Feet Elevated', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8ce85b4d-7c76-57c7-bbc7-fbb84940316c', 'free-exercise-db', 'Push-Ups_With_Feet_On_An_Exercise_Ball', 'Ayaklar Topta Şınav', 'push', 'intermediate', 'compound', '["exercise ball"]', '["chest"]', '["shoulders", "triceps"]', '["Yüzüstü yere uzanın ve ellerinizi birbirinden yaklaşık 36 inç (90 cm) açıklıkta yere koyarak gövdenizi kol boyu uzaklıkta yukarıda tutun.", "Ayak parmaklarınızı bir egzersiz topunun üzerine koyun. Bu, vücudunuzun yükseltilmesini sağlayacaktır.", "Nefes alırken göğsünüz neredeyse yere değene kadar kendinizi indirin.", "Göğüs kaslarınızı kullanarak üst vücudunuzu başlangıç pozisyonuna geri itin ve göğsünüzü sıkın. Bu adımı yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg", "Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg"]', 360.0, 'Push-Ups With Feet On An Exercise Ball', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('70cd9f1f-5ef6-54a5-8991-50cc83a8326c', 'free-exercise-db', 'Push_Press', 'Push Press (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["shoulders"]', '["quadriceps", "triceps"]', '[]', 'olympic weightlifting', '["Push_Press/0.jpg", "Push_Press/1.jpg"]', 420.0, 'Push Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('57940f03-f616-525b-9c25-22b4865711db', 'free-exercise-db', 'Push_Press_-_Behind_the_Neck', 'Push Press (Halter, Ense Arkası)', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["calves", "quadriceps", "triceps"]', '["Ağırlık omuzların arkasında rafta dururken ayakta durarak dip (çömelme) ile başlayın. Ayaklarınız tam kalçalarınızın altındayken, kalçanızı geriye hareket ettirmeden dizlerinizi bükün. Yalnızca hafifçe aşağı inin ve mümkün olduğunca güçlü bir şekilde yön değiştirin. Mümkün olduğunca fazla hız ve kuvvet oluşturmak için topuklarınızdan itin ve barı dikey bir yolda hareket ettirin.", "Oluşan ivmeyi kullanarak kollarınızı açıp ağırlığı başınızın üzerine itmeyi tamamlayın.", "Darbeyi bacaklarınızla emerek başlangıç pozisyonuna dönün."]', 'olympic weightlifting', '["Push_Press_-_Behind_the_Neck/0.jpg", "Push_Press_-_Behind_the_Neck/1.jpg"]', 420.0, 'Push Press - Behind the Neck', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('90e17075-b5a1-5144-93ce-9bb3ef38f0be', 'free-exercise-db', 'Push_Up_to_Side_Plank', 'Şınav ve Yan Plank', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["abdominals", "shoulders", "triceps"]', '["Elleriniz omuz genişliğinin hemen dışında olacak şekilde ayak parmaklarınız üzerinde şınav pozisyonu alın.", "Dirseklerinizin bükülmesine izin vererek bir şınav yapın. İnerken vücudunuzu düz tutun.", "Bir şınav yapın ve yukarı çıkarken ağırlığınızı vücudunuzun sol tarafına kaydırın, sağ kolunuzu yan plank pozisyonunda tavana doğru kaldırırken yana doğru dönün.", "Başka bir şınav için kolu yere geri indirin, ardından diğer tarafa dönün.", "Seriyi her iki tarafı dönüşümlü yaparak 10 veya daha fazla tekrar boyunca tekrarlayın."]', 'strength', '["Push_Up_to_Side_Plank/0.jpg", "Push_Up_to_Side_Plank/1.jpg"]', 360.0, 'Push Up to Side Plank', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('174cffcc-ddc9-5012-9cac-f6ee4bac281e', 'free-exercise-db', 'Pushups', 'Şınav (Klasik)', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Yere yüzüstü uzanın ve gövdenizi kollarınız uzanmış şekilde yukarıda tutarken ellerinizi yaklaşık 90 cm aralıkla yerleştirin.", "Ardından nefes alırken göğsünüz neredeyse yere değene kadar kendinizi aşağı indirin.", "Şimdi nefes verin ve göğsünüzü sıkarak üst vücudunuzu başlangıç pozisyonuna geri itin.", "Üstteki kasılmış pozisyonda kısa bir beklemeden sonra, gereken tekrar sayısı kadar kendinizi tekrar aşağı indirmeye başlayabilirsiniz."]', 'strength', '["Pushups/0.jpg", "Pushups/1.jpg"]', 360.0, 'Pushups', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('cc93fbfa-ca1b-5884-af1e-37c0aeb96be7', 'free-exercise-db', 'Pushups_Close_and_Wide_Hand_Positions', 'Şınav (Dar ve Geniş El Pozisyonu)', 'push', 'beginner', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Yüzüstü yere uzanın, vücudunuz düz ve ayak parmaklarınız yerde olsun; geniş el pozisyonu için ellerinizi omuz genişliğinden daha geniş, dar el pozisyonu için omuz genişliğinden daha dar tutun. Gövdenizi kol boyu uzaklıkta yukarıda tuttuğunuzdan emin olun.", "Nefes alırken göğsünüz neredeyse yere değene kadar kendinizi indirin.", "Göğüs kaslarınızı kullanarak üst vücudunuzu başlangıç pozisyonuna geri itin ve göğsünüzü sıkın. Bu adımı yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Pushups_Close_and_Wide_Hand_Positions/0.jpg", "Pushups_Close_and_Wide_Hand_Positions/1.jpg"]', 360.0, 'Pushups (Close and Wide Hand Positions)', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2a1e1f49-3c1f-557f-b112-a7249bf7d768', 'free-exercise-db', 'Pyramid', 'Pyramid (Pilates Topu)', 'static', 'beginner', NULL, '["exercise ball"]', '["lower back"]', '["shoulders"]', '["Gövdenizi öne doğru topun üzerine yuvarlayarak başlayın; böylece kalçanız topun üzerinde dinlenir ve vücudunuzun en yüksek noktası olur.", "Ellerinizi ve ayaklarınızı yere koyun. Kollarınız ve bacaklarınız, topun boyutuna, esnekliğinize ve uzuvlarınızın uzunluğuna bağlı olarak hafif bükülü veya düz olabilir. Bu aynı zamanda gövdenizde ve omuzlarınızda stabilize edici kuvvetin gelişmesine yardımcı olur."]', 'stretching', '["Pyramid/0.jpg", "Pyramid/1.jpg"]', 150.0, 'Pyramid', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0d8075a7-6b29-5a3d-a109-59c9c6bdca00', 'free-exercise-db', 'Quad_Stretch', 'Ön Bacak (Quadriceps) Esnetme', 'static', 'intermediate', NULL, '["other"]', '["quadriceps"]', '[]', '["Yan yatın. Üstteki ayağınızın etrafına bir kemer, ip veya bant geçirin. Dizinizi bükün ve kalçanızı açarak ayağınızla kalçanıza dokunmaya çalışın ve kemeri elleriniz ile tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kemer omzunuzun üzerinden veya baş üstünden tutulurken, quadriceps''teki esnemeyi artırmak için hafifçe çekin. 10-20 saniye bekleyin ve ardından taraf değiştirin."]', 'stretching', '["Quad_Stretch/0.jpg", "Quad_Stretch/1.jpg"]', 150.0, 'Quad Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e5f44c3e-c492-567e-b616-f159b413c9ae', 'free-exercise-db', 'Quadriceps-SMR', 'Ön Bacak Foam Roller', 'static', 'intermediate', 'isolation', '["foam roll"]', '["quadriceps"]', '[]', '["Ağırlığınız ellerinizde veya ön kollarınızda desteklenerek yüzüstü yere uzanın. Bir foam roller''ı bir bacağın altına, ön bacak kasının üzerine yerleştirin ve ayağı yerden kaldırın. Bacağı olabildiğince gevşetmeyi unutmayın. Bu sizin başlangıç pozisyonunuz olacak.", "Esnetilecek bacağa tolere edebildiğiniz kadar ağırlık vererek, foam roller üzerinde dizin üstünden kalçanın altına kadar yuvarlanın ve gerginlik noktalarında 10-30 saniye bekleyin. Taraf değiştirin."]', 'stretching', '["Quadriceps-SMR/0.jpg", "Quadriceps-SMR/1.jpg"]', 150.0, 'Quadriceps-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2771a757-93c3-5f45-8d55-bd6384e8f209', 'free-exercise-db', 'Quick_Leap', 'Quick Leap', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["calves", "hamstrings"]', '["Bu egzersiz için bir kutuya ihtiyacınız olacak.", "Kutunun kenarından 30-60 cm uzakta, kutuya dönük durarak başlayın.", "Kalçanızı kullanarak kutunun üzerine sıçrayın ve iki bacağınızın üzerine inin. Bacaklarınız bükülü ve ayaklarınız düz basacak şekilde indiğinizden emin olun.", "İner inmez tüm vücudunuzu tamamen açın ve kutudan patlayıcı bir şekilde fırlamak için kollarınızı başınızın üzerine savurun. İniş darbesini sönümlemek için bacaklarınızı kullanın."]', 'plyometrics', '["Quick_Leap/0.jpg", "Quick_Leap/1.jpg"]', 480.0, 'Quick Leap', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('03e634f3-9683-5afa-bda7-5cbf9db86185', 'free-exercise-db', 'Rack_Delivery', 'Rack Delivery (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["forearms", "traps"]', '["Bu çalışma, barın omuzlardaki rack pozisyonuna teslim edilmesini öğretir. Üst kollar yere paralel ve ön kollar aşağı sarkacak şekilde barı korkuluk (scarecrow) pozisyonunda tutarak başlayın. Parmaklarınız başparmaklarınızın üzerine sarılacak şekilde hook tutuş kullanın.", "Dirseklerinizi barın etrafında döndürerek barı omuzlara teslim ederek başlayın. Dirsekleriniz öne gelirken tutuşunuzu gevşetin. Omuzlar öne itilmiş olmalı ve bara raf görevi görmeli; bar boğaza hafifçe temas etmelidir.", "Barın her zaman vücuda yakın kalması önemlidir, çünkü daha ağır yükte herhangi bir mesafe istenmeyen bir çarpışmayla sonuçlanır. Hareket daha akıcı hale geldikçe, ilerlemeden önce hız ve yük artırılabilir."]', 'olympic weightlifting', '["Rack_Delivery/0.jpg", "Rack_Delivery/1.jpg"]', 420.0, 'Rack Delivery', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('73b810ee-4928-559a-abee-27fda232ceaf', 'free-exercise-db', 'Rack_Pull_with_Bands', 'Rack Pull (Halter, Direnç Bandı)', 'pull', 'intermediate', 'compound', '["barbell"]', '["lower back"]', '["forearms", "glutes", "hamstrings", "quadriceps", "traps"]', '["Halter pimlerin üzerindeyken power rack''te hazırlanın. Pimler istenen noktaya ayarlanmalıdır; dizlerin hemen altı, hemen üstü veya uyluğun ortası. Bantları rafın tabanına bağlayın veya dambıllarla sabitleyin. Diğer ucunu halterin kendisine bağlayın. Gerginlik sağlamak için bantları kısaltmanız gerekebilir.", "Kendinizi halterin yanında doğru deadlift pozisyonuna getirin. Ayaklarınız kalçanızın altında, tutuşunuz omuz genişliğinde, sırtınız kavisli ve arka bacak kaslarını devreye sokmak için kalçanız geride olmalıdır. Ağırlık genellikle ağır olduğundan ağırlığı tutmaya yardımcı olması için karma tutuş, hook tutuş veya kayış kullanabilirsiniz.", "Başınızla ileri bakarken kalçanızı ve dizlerinizi açarak ağırlığı kilitlenmeye kadar yukarı ve geriye doğru çekin. Hareketi tamamlarken omuzlarınızı geriye çektiğinizden emin olun. Ağırlığı pimlere geri bırakın ve tekrarlayın."]', 'powerlifting', '["Rack_Pull_with_Bands/0.jpg", "Rack_Pull_with_Bands/1.jpg"]', 360.0, 'Rack Pull with Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1415b14c-d6c3-56ba-b176-022b3a2003e9', 'free-exercise-db', 'Rack_Pulls', 'Rack Pull (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["lower back"]', '["forearms", "glutes", "hamstrings", "traps"]', '["Barı pimlerin üzerinde olacak şekilde bir power rack içinde hazırlanın. Pimler istenen noktaya ayarlanmalıdır: dizlerin hemen altı, hemen üstü veya uyluk ortası. Uygun deadlift pozisyonunda bara yaslanın. Ayaklarınız kalçalarınızın altında, tutuşunuz omuz genişliğinde, sırtınız kavisli ve arka bacak kaslarını devreye sokmak için kalçanız geride olmalıdır. Ağırlık genellikle ağır olduğundan, ağırlığı tutmaya yardımcı olması için karışık tutuş, hook tutuş veya straps kullanabilirsiniz.", "Başınızla ileri bakarak, kalça ve dizlerinizi açın ve ağırlığı kilitlenene kadar yukarı ve geriye doğru çekin. Hareketi tamamlarken omuzlarınızı geriye çektiğinizden emin olun.", "Ağırlığı pimlerin üzerine geri bırakın ve tekrarlayın."]', 'powerlifting', '["Rack_Pulls/0.jpg", "Rack_Pulls/1.jpg"]', 360.0, 'Rack Pulls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('415a70f8-5a62-54d8-9914-14e42d986499', 'free-exercise-db', 'Rear_Leg_Raises', 'Geriye Bacak Kaldırma', 'push', 'beginner', NULL, '["body only"]', '["quadriceps"]', '[]', '["Bir egzersiz matı üzerinde eller ve dizler üzerinde konumlanın. Başınız öne bakmalı ve dizlerin bükülmesi arka bacaklar ile baldırlar arasında 90 derecelik açı oluşturmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Bir bacağınızı yukarı ve arkaya doğru uzatın. Diz ve kalça birlikte açılmalıdır. 5-10 tekrar yapın, ardından taraf değiştirin."]', 'stretching', '["Rear_Leg_Raises/0.jpg", "Rear_Leg_Raises/1.jpg"]', 150.0, 'Rear Leg Raises', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0dfca7d1-6762-5a30-adae-14a78a97ec68', 'free-exercise-db', 'Recumbent_Bike', 'Yatay Bisiklet', NULL, 'beginner', NULL, '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için bisiklete oturun ve koltuğu boyunuza göre ayarlayın.", "Menüden istediğiniz seçeneği seçin. Açmak için pedal çevirmeye başlamanız gerekebilir. Manuel ayarı kullanabilir veya bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kaloriyi tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz. Direnç seviyesi antrenman boyunca değiştirilebilir. Kalp atış hızınızı izlemek ve uygun yoğunlukta kalmak için saplar kullanılabilir.", "Yatay bisikletler kolaylık, kardiyovasküler faydalar sunar ve diğer aktivitelere göre daha az darbe yapar. 68 kg ağırlığındaki bir kişi, 30 dakika orta tempoda bisiklet sürerek yaklaşık 230 kalori yakarken, koşuda 450 kalori veya daha fazlası yakılır."]', 'cardio', '["Recumbent_Bike/0.jpg", "Recumbent_Bike/1.jpg"]', 600.0, 'Recumbent Bike', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('acecc170-3218-5f5b-ada2-ac05035ddeb3', 'free-exercise-db', 'Return_Push_from_Stance', 'Return Push (Duruştan, Medicine Ball)', 'push', 'beginner', 'compound', '["medicine ball"]', '["shoulders"]', '["chest", "triceps"]', '["Bu çalışma için bir partnere ihtiyacınız olacak.", "Atletik bir 2 veya 3 nokta duruşunda başlayın.", "Sinyalde, partnerinizden pası almak için bir pozisyona geçin.", "Medicine ball''u iki elinizle yakalayın ve hemen partnerinize geri fırlatın.", "Farklı rotalarda koşarak bu çalışmayı değiştirebilirsiniz."]', 'plyometrics', '["Return_Push_from_Stance/0.jpg", "Return_Push_from_Stance/1.jpg"]', 480.0, 'Return Push from Stance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f06e0113-dec8-5f61-8851-20f1cf7a9ce3', 'free-exercise-db', 'Reverse_Band_Bench_Press', 'Reverse Band Bench Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "forearms", "lats", "middle back", "shoulders"]', '["Bir bankı power rack içine yerleştirin ve barı doğru yüksekliğe ayarlayın. Bantları band peg''lerine veya rafın üst kısmına sabitleyerek başlayın. Bantların altında doğru şekilde konumlanacağınızdan emin olun. Diğer ucunu halterin barına bağlayın.", "Bankta uzanın, ayaklarınızı altınıza çekin ve sırtınızı kavisli yapın. Ağırlığınızı desteklemek için barı kullanarak omuzlarınızı bankın üzerinden kaldırın ve geriye çekin, kürek kemiklerinizi birbirine sıkın. Trapezlerinizi banka bastırmak için ayaklarınızı kullanın. Bu sıkı vücut pozisyonunu hareket boyunca koruyun. Tutuşunuz ne kadar geniş olursa olsun, barın üzerindeki halkayı kapsamalıdır.", "Omuzlarınızı öne yuvarlamadan barı raftan çıkarın. Barı sıkmaya ve ayırmaya çalışıyormuş gibi odaklanın. Barı alt göğsünüze veya üst karnınıza indirin. Bar, bilek ve dirsek her zaman aynı hizada kalmalıdır.", "Halter gövdenize değdiğinde bekleyin, ardından barı olabildiğince fazla güçle yukarı itin. Dirsekler kilitlenene kadar içeride kalmalıdır."]', 'powerlifting', '["Reverse_Band_Bench_Press/0.jpg", "Reverse_Band_Bench_Press/1.jpg"]', 360.0, 'Reverse Band Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('143b9206-f2d4-5c56-ad8c-6872ae1c870d', 'free-exercise-db', 'Reverse_Band_Box_Squat', 'Box Squat (Ters Bantlı)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["abductors", "adductors", "calves", "forearms", "glutes", "hamstrings", "lower back"]', '["Arkanızda uygun yükseklikte bir kutu bulunan power rack içinde başlayın. Bantları ya bant piminden ya da rack''in üstüne sabitleyerek ayarlayın ve squat sırasında barın tam üzerinde olacaklarından emin olun. Diğer ucu bara bağlayın.", "Barın altına girip omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine sıkıştırın ve barı omuzlarınızın üzerinde bükmeye çalışarak dirseklerinizi öne döndürün. Barı rack''ten çıkarın, belinizde sıkı bir kavis oluşturun ve geriye adım atarak pozisyona girin. Sırt, kalça, adduktör ve arka bacak kaslarına daha çok vurgu yapmak için ayaklarınızı daha geniş, quadriceps gelişimi için ise birbirine daha yakın yerleştirin. Başınızı ileriye dönük tutun.", "Sırtınız, omuzlarınız ve core bölgeniz sıkı haldeyken, dizlerinizi ve kalçanızı dışarı iterek inişe başlayın. Kutunun üzerine oturana kadar kalçanızla geriye oturun. İdeal olarak kaval kemikleriniz yere dik olmalıdır. Kutuya ulaştığınızda bekleyin ve kalça fleksörlerini gevşetin. Kutudan asla sekmeyin.", "Ağırlığı topuklarınızda tutarak ve ayaklarınızı ve dizlerinizi dışa iterek, hareketi başınızla yönlendirirken kutudan yukarı doğru itin. Baştan ayağa sıkılığı koruyarak yukarı çıkmaya devam edin. Halteri rack''e geri koyarken dikkatli olun."]', 'powerlifting', '["Reverse_Band_Box_Squat/0.jpg", "Reverse_Band_Box_Squat/1.jpg"]', 360.0, 'Reverse Band Box Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5fec6c5c-eba0-5b29-8e75-9597919e191d', 'free-exercise-db', 'Reverse_Band_Deadlift', 'Ters Bantlı Deadlift (Halter)', 'pull', 'expert', 'compound', '["barbell"]', '["lower back"]', '["abductors", "adductors", "calves", "glutes", "hamstrings", "quadriceps"]', '["Barı bir power rack içinde kurun. Bantları ya bant çubuklarını ya da çerçevenin kendisini kullanarak rafın üstüne bağlayın. Bantların diğer ucunu bara takın.", "Bar ayaklarınızın üzerinde ortalanacak şekilde bara yaklaşın. Ayaklarınız yaklaşık kalça genişliğinde olmalıdır. Kürek kemiklerinizin öne doğru açılmasına izin vererek barı omuz genişliğinde kavramak için kalçanızdan bükülün. Genellikle üsten tutuş ya da ağır setlerde karışık (over/under) tutuş kullanılır.", "Ayaklarınız ve tutuşunuz yerleştikten sonra derin bir nefes alın, ardından kaval kemikleriniz bara değene kadar kalçanızı alçaltın ve dizlerinizi bükün. Başınızla ileri bakın, göğsünüzü yukarıda ve sırtınızı kavisli tutun ve ağırlığı yukarı taşımak için topuklarınızdan itmeye başlayın.", "Bar dizleri geçtikten sonra, kalçanızı bara doğru ileri sürerken kürek kemiklerinizi birbirine çekerek barı agresif bir şekilde geriye çekin.", "Kalçanızdan bükülerek ve barı yere yönlendirerek barı indirin."]', 'powerlifting', '["Reverse_Band_Deadlift/0.jpg", "Reverse_Band_Deadlift/1.jpg"]', 360.0, 'Reverse Band Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('21a3c57b-8b28-5398-89ac-9d0178728530', 'free-exercise-db', 'Reverse_Band_Power_Squat', 'Power Squat (Halter, Ters Bant)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["adductors", "calves", "glutes", "hamstrings", "lower back"]', '["Pimler ve bar uygun yüksekliğe ayarlanmış bir power rack içinde başlayın. Barı yükledikten sonra, mandalları veya rack''in çerçevesini kullanarak bantları rack''in üst kısmına bağlayın. Bantların diğer ucunu bara bağlayın.", "Barın altına girerek ve omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine doğru sıkın ve barı omuzlarınızın üzerinde bükmeye çalışır gibi dirseklerinizi öne doğru döndürün. Barı raftan alırken belinizde sıkı bir kavis oluşturun ve geriye doğru adım atarak yerinizi alın. Sırt, kalça, iç bacak kasları (adductor) ve arka bacak üzerindeki vurguyu artırmak için ayaklarınızı geniş açın.", "Başınızı ileri bakacak şekilde tutun. Sırtınız, omuzlarınız ve karın bölgeniz sıkı haldeyken dizlerinizi ve kalçanızı dışarı doğru iterek inişe başlayın. Kalçanızı mümkün olduğunca geriye oturtun. İdeal olarak kaval kemikleriniz yere dik olmalıdır. Daha alçak bar pozisyonu, barı topukların üzerinde tutmak için gövdenin daha fazla öne eğilmesini gerektirir. Paralelin altına geçene kadar devam edin; paralel, kalça kıvrımının dizin üst kısmıyla aynı hizada olması olarak tanımlanır.", "Ağırlığı topuklarınızda tutarak ve ayaklarınızı ile dizlerinizi dışarı iterek, hareketi başınızla yönlendirerek yukarı doğru güç alın. Başlangıç pozisyonuna dönene kadar baştan ayağa sıkı kalmaya devam ederek yukarı çıkın."]', 'powerlifting', '["Reverse_Band_Power_Squat/0.jpg", "Reverse_Band_Power_Squat/1.jpg"]', 360.0, 'Reverse Band Power Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('27fbee70-b20c-5edf-9cd9-5d7b5f1617e3', 'free-exercise-db', 'Reverse_Band_Sumo_Deadlift', 'Sumo Deadlift (Halter, Ters Bant)', 'pull', 'expert', 'compound', '["barbell"]', '["hamstrings"]', '["abductors", "adductors", "calves", "forearms", "glutes", "lower back", "quadriceps", "traps"]', '["Bir power rack içinde yerde yüklü bir barla başlayın. Bantları, ya mandalları ya da rack''in kendisini kullanarak rack''in üstüne bağlayın. Diğer ucunu halterin üzerine bağlayın.", "Bar ayakların ortasını kesecek şekilde bara yaklaşın. Ayaklar çok geniş, manşonlara yakın olacak şekilde ayarlanmalıdır. Barı kavramak için kalçadan eğilin. Kollar omuzların tam altında, bacakların içinde olmalıdır ve pronasyon tutuş, karışık tutuş veya hook tutuş kullanabilirsiniz. Kolları uzatan omuzlarınızı gevşetin.", "Bir nefes alın, ardından kalçanızı alçaltın; başınızla ileri bakın ve göğsünüzü dik tutun. Ayaklarınızı birbirinden ayırarak yeri iterek, ağırlığınız ayaklarınızın arka yarısında olacak şekilde ilerleyin. Kalça ve dizlerinizi açın.", "Bar dizlerden geçerken geriye yaslanın ve kürek kemiklerinizi birbirine yaklaştırarak kalçanızı bara doğru sürün.", "Kalçadan bükülerek ve inerken ağırlığı kontrol ederek ağırlığı yere geri indirin."]', 'powerlifting', '["Reverse_Band_Sumo_Deadlift/0.jpg", "Reverse_Band_Sumo_Deadlift/1.jpg"]', 360.0, 'Reverse Band Sumo Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5ccb0ec4-64d0-5a0a-92a5-f1f1fa61dc8e', 'free-exercise-db', 'Reverse_Barbell_Curl', 'Reverse Curl (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["biceps"]', '["forearms"]', '["Gövdeniz dik şekilde ayakta durun ve halteri omuz genişliğinde tutun; dirsekleriniz gövdenize yakın olmalıdır. Avuç içleriniz aşağı bakmalıdır (pronasyon tutuş). Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı sabit tutarken nefes verirken biceps''i kasarak ağırlıkları kıvırın. Yalnızca ön kollar hareket etmelidir. Biceps''iniz tamamen kasılana ve halter omuz hizasına gelene kadar harekete devam edin. Kası sıkarak kasılmış pozisyonda bir saniye bekleyin.", "Nefes alırken halteri yavaşça başlangıç pozisyonuna geri getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Barbell_Curl/0.jpg", "Reverse_Barbell_Curl/1.jpg"]', 360.0, 'Reverse Barbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b079fa27-2a1c-5921-b4f7-96151ea75097', 'free-exercise-db', 'Reverse_Barbell_Preacher_Curls', 'Ters Tutuş Preacher Curl (EZ Bar)', 'pull', 'intermediate', 'isolation', '["e-z curl bar"]', '["biceps"]', '["forearms"]', '["Bir EZ-bar''ı omuz genişliğinde ve avuç içleri aşağı bakacak (pronated) tutuşla kavrayın.", "Şimdi her iki kolunuzun üst kısmını preacher bankının üzerine yerleştirin ve kollarınızı uzatın. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken, biceps tamamen kasılana ve halter omuz hizasına gelene kadar ağırlığı biceps ile yukarı kıvırın. Kasılmış pozisyonda biceps''i bir saniye sert şekilde sıkın.", "Nefes alırken, üst kollarınız uzayana ve biceps tamamen gerilene kadar halteri yavaşça indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Barbell_Preacher_Curls/0.jpg", "Reverse_Barbell_Preacher_Curls/1.jpg"]', 360.0, 'Reverse Barbell Preacher Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ad38b3e0-fc88-5ad5-8df5-9392f491a437', 'free-exercise-db', 'Reverse_Cable_Curl', 'Reverse Curl (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["biceps"]', '["forearms"]', '["Alt makaraya bağlı bir bar aparatını pronasyon (avuç içleri aşağı) ve omuz genişliğinde bir tutuşla tutarak gövdeniz dik şekilde ayakta durun. Ayrıca dirseklerinizi gövdenize yakın tuttuğunuzdan emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarak nefes verip biceps''inizi kasarak ağırlığı kıvırın. Yalnızca ön kollar hareket etmelidir. Biceps''leriniz tamamen kasılana ve bar omuz seviyesine gelene kadar hareketi sürdürün. Kası sıkarak kasılmış pozisyonu bir saniye tutun.", "Nefes alırken barı yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Cable_Curl/0.jpg", "Reverse_Cable_Curl/1.jpg"]', 360.0, 'Reverse Cable Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6aecf039-da6b-50e8-bc07-95e335972ecf', 'free-exercise-db', 'Reverse_Crunch', 'Reverse Crunch (Ters Mekik)', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Bacaklarınız tamamen uzamış ve kollarınız gövdenizin yanlarında, avuç içleri yerde olacak şekilde yere uzanın. Kollarınız tüm egzersiz boyunca sabit olmalıdır.", "Bacaklarınızı uyluklarınız yere dik, ayaklarınız bitişik ve yere paralel olacak şekilde yukarı kaldırın. Bu başlangıç pozisyonudur.", "Nefes alırken bacaklarınızı gövdenize doğru hareket ettirin, pelvisinizi geriye doğru yuvarlayın ve kalçanızı yerden kaldırın. Bu hareketin sonunda dizleriniz göğsünüze değiyor olacaktır.", "Kasılmayı bir saniye tutun ve nefes verirken bacaklarınızı başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Crunch/0.jpg", "Reverse_Crunch/1.jpg"]', 360.0, 'Reverse Crunch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2668f289-33d2-5dc3-b0df-67cda4a00d18', 'free-exercise-db', 'Reverse_Flyes', 'Reverse Fly (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Başlamak için göğsünüz ve karnınız eğime bastırılacak şekilde bir incline bench''e yüzüstü uzanın. Her elinizde avuç içleri birbirine bakacak şekilde (nötr tutuş) birer dambıl tutun.", "Kollarınızı, bench''in açısına dik olacak şekilde önünüze doğru uzatın. Bacaklar sabit kalırken ayak parmaklarınızın ön kısmıyla baskı uygulayın. Bu başlangıç pozisyonudur.", "Dirseklerdeki hafif bükülmeyi koruyarak, nefes verirken ağırlıkları yay çizerek birbirinden uzağa (yanlara) doğru hareket ettirin. İpucu: Bu egzersizden en iyi sonucu almak için kürek kemiklerinizi birbirine sıkıştırmaya çalışın.", "Kollar yere paralel olana kadar kaldırılmalıdır.", "Kasılmayı hissedin ve nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Flyes/0.jpg", "Reverse_Flyes/1.jpg"]', 360.0, 'Reverse Flyes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c7aaa39c-a140-5433-976d-bd42596b8951', 'free-exercise-db', 'Reverse_Flyes_With_External_Rotation', 'Reverse Fly (Dambıl, Dış Rotasyonlu)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Başlamak için, göğsünüz ve karnınız eğime bastırılmış şekilde 30 derecelik açıya ayarlanmış bir incline bench üzerine yüzüstü uzanın.", "Her elinizde bir dambıl olsun, avuç içleriniz yere bakmalı. Kollarınız önünüzde, bench''in eğimine dik olmalı. İpucu: Dirsekleriniz hafifçe bükülü olmalı. Ayak parmaklarınızın ön kısmıyla baskı uygularken bacaklar sabit kalmalı (topuklarınız yere değmemeli). Bu başlangıç pozisyonudur.", "Dirseklerdeki hafif bükülmeyi koruyarak, nefes verirken ağırlıkları yay çizerek dışa ve birbirinden uzağa hareket ettirin.", "Ağırlığı kaldırırken bileğiniz 90 derece dışa dönmelidir; böylece avuç içleri aşağı (pronasyon) tutuştan avuç içleri birbirine bakan (nötr) tutuşa geçersiniz. İpucu: Bu egzersizden en iyi sonucu almak için kürek kemiklerinizi birbirine sıkıştırmaya çalışın.", "Kollar başınızla aynı seviyeye gelene kadar yükseltilmelidir.", "Kasılmayı hissedin ve nefes alırken ağırlıkları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Flyes_With_External_Rotation/0.jpg", "Reverse_Flyes_With_External_Rotation/1.jpg"]', 360.0, 'Reverse Flyes With External Rotation', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eb5d10a0-f61b-5964-8830-c9a1cf1578f1', 'free-exercise-db', 'Reverse_Grip_Bent-Over_Rows', 'Öne Eğilerek Row (Halter, Ters Tutuş)', 'pull', 'intermediate', 'compound', '["barbell"]', '["middle back"]', '["biceps", "lats", "shoulders"]', '["Avuç içleri yukarı bakan supine tutuşla bir halteri tutarak dik durun.", "Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak belden eğilip gövdenizi, yere neredeyse paralel olana kadar öne getirin. İpucu: Başınızı yukarıda tuttuğunuzdan emin olun. Halter tam önünüzde sarkmalı, kollarınız yere ve gövdenize dik olarak sarkmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarak, nefes verirken halteri kaldırın; dirseklerinizi vücudunuza yakın tutun ve ön kolla ağırlığı tutmaktan başka kuvvet uygulamayın. Üst kasılma noktasında sırt kaslarınızı sıkın ve bir saniye bekleyin.", "Nefes alırken ağırlığı yavaşça tekrar başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Grip_Bent-Over_Rows/0.jpg", "Reverse_Grip_Bent-Over_Rows/1.jpg"]', 360.0, 'Reverse Grip Bent-Over Rows', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0c0acadf-1f0e-55d0-b047-1007276504a5', 'free-exercise-db', 'Reverse_Grip_Triceps_Pushdown', 'Ters Tutuş Triceps Pushdown (Kablo)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Yüksek makaralı bir makineye bir bar aparatı (düz veya EZ) takarak başlayın.", "Bar aparatına dönük durun ve avuç içleri yukarı bakacak (supinated tutuş) şekilde omuz genişliğinde kavrayın. Kollarınız yanlarınızda tamamen uzayana kadar barı kanat (lat) kaslarınızı kullanarak aşağı indirin. İpucu: Dirsekler yanlarınızda içeride olmalı ve ayaklarınız birbirinden omuz genişliğinde açık olmalıdır. Bu başlangıç pozisyonudur.", "Nefes alırken bar aparatını göğsünüzle aynı hizaya gelene kadar yavaşça yukarı kaldırın. Yalnızca ön kollar hareket etmeli, dirsekler/üst kollar her zaman yanınızda sabit kalmalıdır.", "Ardından nefes verirken ve triceps''i sert şekilde kasarak kablo barını orijinal başlangıç pozisyonuna indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Grip_Triceps_Pushdown/0.jpg", "Reverse_Grip_Triceps_Pushdown/1.jpg"]', 360.0, 'Reverse Grip Triceps Pushdown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6d27436f-6efd-51fa-89ff-b6fe811347e9', 'free-exercise-db', 'Reverse_Hyperextension', 'Reverse Hyperextension (Makine)', 'pull', 'intermediate', NULL, '["machine"]', '["hamstrings"]', '["calves", "glutes"]', '["Uygun bir ağırlık yükledikten sonra ayaklarınızı pedlerin arasına yerleştirin. Pozisyonunuzu korumak için tutamakları kavrarken üst pede uzanın ve kalçanızın arkadan sarkmasına izin verin.", "Harekete başlamak için kalçanızı bükerek bacaklarınızı öne çekin.", "Kalçanızı açarak ve bacağı geriye doğru savurarak hareketi tersine çevirin. Bu harekette kalçayı aşırı açmamak, tam hareket açıklığına varmadan durmak çok önemlidir.", "Kalçanızı tekrar bükerek ve arabayı olabildiğince öne çekerek geri dönün.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Hyperextension/0.jpg", "Reverse_Hyperextension/1.jpg"]', 360.0, 'Reverse Hyperextension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a82ab6a0-fba0-5227-9a9b-7d3380853d1c', 'free-exercise-db', 'Reverse_Machine_Flyes', 'Reverse Fly (Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["shoulders"]', '[]', '["Tutamakları tamamen arkaya gelecek şekilde ayarlayın. Uygun ağırlığı seçin ve tutamaklar omuz seviyesinde olacak şekilde koltuk yüksekliğini ayarlayın. Tutamakları avuç içleriniz içe bakacak şekilde kavrayın. Bu sizin başlangıç pozisyonunuzdur.", "Yarım daire hareketiyle ellerinizi yanlarınıza ve geriye doğru çekin ve arka omuzlarınızı kasın.", "Hareket boyunca kollarınızı hafif bükülü tutun; tüm hareket omuz ekleminde gerçekleşmelidir.", "Hareketin arka noktasında bekleyin ve ağırlığı yavaşça başlangıç pozisyonuna döndürün."]', 'strength', '["Reverse_Machine_Flyes/0.jpg", "Reverse_Machine_Flyes/1.jpg"]', 360.0, 'Reverse Machine Flyes', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d74701da-8247-5290-aa75-8566327f88c1', 'free-exercise-db', 'Reverse_Plate_Curls', 'Ters Tutuş Plaka Curl', 'pull', 'beginner', 'isolation', '["other"]', '["biceps"]', '["forearms"]', '["Ağırlık plakasını iki elinizle ve kollarınız tamamen uzatılmış halde tutarak dik durarak başlayın. Pronasyon tutuş (avuç içleri aşağı) kullanın ve parmaklarınızın plakanın pürüzlü tarafını, baş parmağınızın ise pürüzsüz tarafını kavradığından emin olun. Not: En iyi sonuçlar için ağırlık plakasını 11 ve 1 saat konumlarından kavrayın.", "Ayaklarınız birbirinden omuz genişliğinde açık olmalı ve ağırlık plakası kasık bölgesine yakın olmalıdır. Bu başlangıç pozisyonudur.", "Dirseklerinizi içeride ve üst kollarınızı sabit tutarak, nefes verirken biceps''iniz ve ön kollarınız birbirine değene kadar plakayı yavaşça kaldırın. Bu noktada plaka gövdenizle eşit hizada olmalıdır.", "Kasılmayı bir saniye hissedin ve nefes alırken ağırlığı yavaşça başlangıç pozisyonuna indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Reverse_Plate_Curls/0.jpg", "Reverse_Plate_Curls/1.jpg"]', 360.0, 'Reverse Plate Curls', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9926008a-8bf8-5f46-bc22-185cc46a3107', 'free-exercise-db', 'Reverse_Triceps_Bench_Press', 'Reverse Triceps Bench Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["triceps"]', '["chest", "shoulders"]', '["Düz sehpaya sırtüstü uzanın. Dar, supinasyon tutuşla (yaklaşık omuz genişliğinde) halteri raftan kaldırın ve kollarınız kilitli, önünüzde uzamış ve yere dik olacak şekilde tam tepenizde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken halteri orta göğsünüzde hissedene kadar yavaşça indirin. İpucu: Normal bench press''in aksine triceps katılımını en üst düzeye çıkarmak için dirseklerinizi her zaman gövdenize yakın tutun.", "Bir saniyelik duraklamanın ardından nefes verirken triceps kaslarınızı kullanarak halteri iterek başlangıç pozisyonuna geri getirin. Kollarınızı kasılmış pozisyonda kilitleyin, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İnmek, çıkmaktan en az iki kat uzun sürmelidir.", "Hareketi belirtilen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde halteri rafa geri yerleştirin."]', 'strength', '["Reverse_Triceps_Bench_Press/0.jpg", "Reverse_Triceps_Bench_Press/1.jpg"]', 360.0, 'Reverse Triceps Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b85ab572-2083-5595-9571-3fb33fcc3c5e', 'free-exercise-db', 'Rhomboids-SMR', 'Romboid Foam Roll (SMR)', 'static', 'intermediate', NULL, '["foam roll"]', '["middle back"]', '["traps"]', '["Sırtınız yerde olacak şekilde uzanın. Üst sırtınızın altına bir foam roll yerleştirin ve omuzlarınızı öne açarak kollarınızı önünüzde çaprazlayın. Bu sizin başlangıç pozisyonunuzdur.", "Kalçanızı yerden kaldırın ve ağırlığınızı foam roll''a verin. Ağırlığınızı sırayla bir yana kaydırarak orta ve üst sırtınız üzerinde yuvarlanın. Gerginlik noktalarında 10-30 saniye bekleyin."]', 'stretching', '["Rhomboids-SMR/0.jpg", "Rhomboids-SMR/1.jpg"]', 150.0, 'Rhomboids-SMR', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9d8fecc4-27f8-5195-b90a-350422ee5bd9', 'free-exercise-db', 'Rickshaw_Carry', 'Rickshaw Carry (Strongman)', NULL, 'intermediate', 'compound', '["other"]', '["forearms"]', '["abdominals", "calves", "glutes", "hamstrings", "lower back", "quadriceps", "traps"]', '["Çerçeveyi başlangıç noktasına yerleştirin ve uygun ağırlıkla yükleyin. Çerçevenin ortasında durarak sapları kavrayın ve çerçeveyi kaldırmak için topuklarınızdan itin. Göğsünüzün ve başınızın yukarıda, sırtınızın düz olduğundan emin olun.", "Hemen hızlı ve kontrollü adımlarla tempolu yürümeye başlayın. Göğsünüzü yukarıda, başınızı öne dönük tutun ve nefes almaya devam ettiğinizden emin olun. Bitiş noktasına ulaştıktan sonra çerçeveyi yere indirin."]', 'strongman', '["Rickshaw_Carry/0.jpg", "Rickshaw_Carry/1.jpg"]', 480.0, 'Rickshaw Carry', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('439bd233-66a3-58cc-954f-96a1d038e7ad', 'free-exercise-db', 'Rickshaw_Deadlift', 'Deadlift (Rickshaw)', 'pull', 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["forearms", "glutes", "hamstrings", "lower back", "traps"]', '["Çerçeveyi istenen ağırlıkla yükleyin. Tutacakların arasında ortalanın. Ayaklarınız yaklaşık kalça genişliğinde açık olmalıdır. Kürek kemiklerinizin öne doğru açılmasına izin vererek kalçadan bükülüp tutacakları kavrayın.", "Ayaklarınız ve tutuşunuz hazır olduğunda derin bir nefes alın, ardından kalçanızı alçaltın ve dizlerinizi bükün. Başınızla ileri bakın, göğsünüzü yukarıda ve sırtınızı kavisli tutun ve ağırlığı yukarı hareket ettirmek için topuklarınızdan itmeye başlayın. Ağırlık yukarı çıkarken kalçanızı ileri sürerken kürek kemiklerinizi birbirine doğru sıkın.", "Kalçanızdan bükülerek ve ağırlığı yere doğru yönlendirerek ağırlığı indirin."]', 'strongman', '["Rickshaw_Deadlift/0.jpg", "Rickshaw_Deadlift/1.jpg"]', 480.0, 'Rickshaw Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('406b4195-27b7-56a8-87d5-f11d321aefa8', 'free-exercise-db', 'Ring_Dips', 'Halka Dips', 'push', 'intermediate', 'compound', '["other"]', '["triceps"]', '["chest", "shoulders"]', '["Her elinizle bir halkayı kavrayın, ardından kollarınız kilitli şekilde başlangıç pozisyonuna geçmenize yardımcı olması için küçük bir sıçrama yapın.", "Dirseklerinizi bükerek, kollarınız 90 dereceyi geçene kadar vücudunuzu alçaltarak başlayın. Sallanmaktan kaçının ve iniş boyunca iyi bir duruşu koruyun.", "Dirseklerinizi açarak hareketi tersine çevirin, kendinizi başlangıç pozisyonuna geri itin.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Ring_Dips/0.jpg", "Ring_Dips/1.jpg"]', 360.0, 'Ring Dips', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f572f7ab-0db5-5041-9850-bccaf75e94b0', 'free-exercise-db', 'Rocket_Jump', 'Rocket Jump', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["calves", "hamstrings"]', '["Ayaklarınız omuz genişliğinde, rahat bir duruşla başlayın ve kollarınızı vücudunuza yakın tutun.", "Hareketi başlatmak için yarıya kadar çömelin ve olabildiğince yükseğe patlayıcı bir şekilde zıplayın.", "Tüm vücudunuzu tamamen uzatın ve olabildiğince yukarı uzanın. İnerken darbeyi bacaklarınızla sönümleyin."]', 'plyometrics', '["Rocket_Jump/0.jpg", "Rocket_Jump/1.jpg"]', 480.0, 'Rocket Jump', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('91120683-a60f-537d-a57e-da344ccaeaad', 'free-exercise-db', 'Rocking_Standing_Calf_Raise', 'Sallanarak Ayakta Calf Raise (Halter)', 'push', 'beginner', 'isolation', '["barbell"]', '["calves"]', '[]', '["Bu egzersizi güvenlik amacıyla bir squat rack içinde yapmak en iyisidir. Başlamak için önce barı boyunuza en uygun rafa yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve omuzlarınızın arkasına (boynun biraz altına) yerleştirin.", "Barı her iki kolunuzla yanlardan kavrayın ve önce bacaklarınızla iterek, aynı anda gövdenizi doğrultarak raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta duruşa getirin, ayak parmakları hafifçe dışa dönük olsun. Aşağıya bakmak dengenizi bozacağından başınızı her zaman yukarıda tutun. Ayrıca sırtınızı düz tutun ve dizlerinizi hafif bükülü tutun; asla kilitlemeyin. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken bileklerinizi olabildiğince yukarı uzatarak ve baldırınızı kasarak topuklarınızı kaldırın. Dizin her zaman sabit kaldığından emin olun. Herhangi bir anda bükülme olmamalıdır (pozisyon alırken oluşturduğumuz hafif ilk bükülme dışında). Aşağı inmeye başlamadan önce kasılmış pozisyonu bir saniye tutun.", "Nefes alırken bilekleri bükerek topuklarınızı indirip baldırlar gerilene kadar yavaşça başlangıç pozisyonuna dönün.", "Şimdi nefes verirken baldırların ön kısmındaki tibia kaslarını kasarak ayak parmaklarınızı kaldırın.", "Bir saniye bekleyin ve nefes alırken geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Rocking_Standing_Calf_Raise/0.jpg", "Rocking_Standing_Calf_Raise/1.jpg"]', 360.0, 'Rocking Standing Calf Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f53dc6fb-7db7-5d64-ab8f-d04c13dc6ec6', 'free-exercise-db', 'Rocky_Pull-Ups_Pulldowns', 'Rocky Barfiks', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Barfiks barını avuç içleri ileri bakacak şekilde geniş bir tutuşla kavrayın.", "İki kolunuz seçtiğiniz tutuş genişliğinde barı tutarak önünüzde uzanmışken, alt sırtınızda bir kavis oluştururken ve göğsünüzü dışarı çıkarırken gövdenizi yaklaşık 30 derece geriye getirin. Bu sizin başlangıç pozisyonunuzdur.", "Omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek bar üst göğsünüze değene kadar gövdenizi yukarı çekin. Hareketin bu kısmında nefes verin. İpucu: Tam kasılmış pozisyona ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde uzayda hareket ederken sabit kalmalı ve sadece kollar hareket etmelidir. Ön kollar barı tutmaktan başka bir iş yapmamalıdır.", "Kasılmış pozisyonda bir saniye bekledikten sonra nefes almaya başlayın ve kollarınız tamamen uzanıp latissimus kaslarınız tamamen gerilene kadar gövdenizi yavaşça başlangıç pozisyonuna indirin.", "Şimdi yukarıda anlatılan hareketleri tekrarlayın; ancak bu sefer yukarı çıkarken gövdeniz düz kalacak ve bar üst göğüs yerine boynunuzun arkasına değecektir. İpucu: Egzersizin bu kısmını doğru yapmanıza yardımcı olacağı için başınızı hafifçe öne doğru eğin.", "Kendinizi başlangıç pozisyonuna geri indirdikten sonra, programınızdaki belirlenen tekrar sayısı kadar egzersizi tekrarlayın."]', 'strength', '["Rocky_Pull-Ups_Pulldowns/0.jpg", "Rocky_Pull-Ups_Pulldowns/1.jpg"]', 360.0, 'Rocky Pull-Ups/Pulldowns', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f237d5d7-05c2-55e4-9bb5-085e5c1db3ed', 'free-exercise-db', 'Romanian_Deadlift', 'Romanian Deadlift (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["calves", "glutes", "lower back"]', '["Önünüzde yere bir halter koyun ve omuz genişliğinden biraz daha geniş pronasyon (avuç içleri aşağı bakan) tutuşla kavrayın. İpucu: Kullanılan ağırlığa bağlı olarak egzersizi yapmak için bilek sargılarına ve ayrıca daha iyi hareket açıklığı sağlamak için yükseltilmiş bir platforma ihtiyacınız olabilir.", "Dizlerinizi hafifçe bükün ve kaval kemiklerinizi dik, kalçanızı geride ve sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Sırtınızı ve kollarınızı her zaman tamamen düz tutarak, nefes verirken barı kaldırmak için kalçanızı kullanın. İpucu: Hareket hızlı değil, sabit ve kontrollü olmalıdır.", "Tamamen dik durduktan sonra, squat''tan farklı olarak dizlerinizi yalnızca hafifçe bükerek kalçanızı geriye iterek barı indirin. İpucu: Hareketin başında derin bir nefes alın ve göğsünüzü yukarıda tutun. İnerken nefesinizi tutun ve hareketi tamamlarken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Romanian_Deadlift/0.jpg", "Romanian_Deadlift/1.jpg"]', 360.0, 'Romanian Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('63b13c81-fd1e-57bc-a9a9-ad01825ad7df', 'free-exercise-db', 'Romanian_Deadlift_from_Deficit', 'Romanian Deadlift (Deficit)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["forearms", "glutes", "lower back", "traps"]', '["Önünüzde kol boyu kadar bir bar tutarak ayakta durarak başlayın. Hareket açıklığını artırmak için yükseltilmiş bir platformun üzerinde durabilirsiniz.", "Dizlerinizi hafifçe bükerek başlayın, ardından kalçanızdan bükülerek kalçanızı mümkün olduğunca geriye itin ve esnekliğinizin izin verdiği kadar gövdenizi alçaltın. Sırt her zaman tam bir ekstansiyonda kalmalı ve bar bacaklarla temas halinde kalmalıdır. Doğru yapılırsa arka bacak kaslarında ağır bir gerginlik hissedilmelidir.", "Başlangıç pozisyonuna dönmek için hareketi tersine çevirin."]', 'olympic weightlifting', '["Romanian_Deadlift_from_Deficit/0.jpg", "Romanian_Deadlift_from_Deficit/1.jpg"]', 420.0, 'Romanian Deadlift from Deficit', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d7db3957-defc-5cc7-8557-c026d2633a34', 'free-exercise-db', 'Rope_Climb', 'İp Tırmanma', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["biceps", "forearms", "middle back", "shoulders"]', '["İpi başınızın üzerinde iki elinizle kavrayın. Küçük bir sıçrama yaparken ipi aşağı çekin.", "İpi bir bacağınıza dolayın ve ipi sıkıştırmak için ayaklarınızı kullanın. İpi sıkıca kavrayarak kollarınızla olabildiğince yukarı uzanın.", "Dizlerinizi göğsünüze doğru getirerek kendinizi kollarınızla yukarı çekerken ayaklarınızla ipi bırakın.", "Ayaklarınızı tekrar ipe sabitleyin, ardından ipte bir kez daha yüksek bir tutuş almak için ayağa kalkın. İpin tepesine ulaşana kadar devam edin.", "Kendinizi indirmek için elden ele hareketiyle kayarken ayaklarınızın ip üzerindeki tutuşunu gevşetin."]', 'strength', '["Rope_Climb/0.jpg", "Rope_Climb/1.jpg"]', 360.0, 'Rope Climb', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('462b1d30-24a0-5532-b7c6-6f69adc39b40', 'free-exercise-db', 'Rope_Crunch', 'Crunch (Kablo, Halat)', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["Halat bağlı bir kablo sisteminin 30-60 cm önünde diz çökün.", "Uygun ağırlığı seçtikten sonra halatı baş üstüne uzanarak iki elinizle kavrayın. Başlangıç pozisyonunda gövdeniz dik olmalıdır.", "Başlamak için omurganızı bükün ve kabloyu aşağı çekerken kaburga kafesinizi bacaklarınıza doğru getirmeye çalışın.", "Hareketin alt noktasında durun, ardından yavaşça başlangıç pozisyonuna dönün.", "Yan karın kaslarını çalıştırmak için bunlar rotasyonla veya yana doğru yapılabilir."]', 'strength', '["Rope_Crunch/0.jpg", "Rope_Crunch/1.jpg"]', 360.0, 'Rope Crunch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('614526a8-ce4f-51e1-9236-22c7c19f7f1e', 'free-exercise-db', 'Rope_Jumping', 'İp Atlama', NULL, 'intermediate', NULL, '["other"]', '["quadriceps"]', '["calves", "hamstrings"]', '["İpin her ucunu bir elinizle tutun. İpi arkanızda yerde konumlandırın. Kollarınızı yukarı kaldırın ve ipi başınızın üzerinden çevirerek önünüze indirin. Yere ulaştığında üzerinden atlayın. Sürdürebileceğiniz iyi bir çevirme temposu bulun. Çeşitlilik katmak için farklı hızlar ve teknikler kullanılabilir.", "İp atlama heyecan vericidir, koordinasyonunuzu zorlar ve çok fazla enerji gerektirir. 68 kg''lık bir kişi 30 dakika ip atlayarak yaklaşık 350 kalori yakarken, koşarak 450 kaloriden fazla yakar."]', 'cardio', '["Rope_Jumping/0.jpg", "Rope_Jumping/1.jpg"]', 600.0, 'Rope Jumping', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8607c117-f05a-59f8-ac33-bff6d21dd4e3', 'free-exercise-db', 'Rope_Straight-Arm_Pulldown', 'Düz Kol Pulldown (Kablo, İp)', 'pull', 'beginner', 'isolation', '["cable"]', '["lats"]', '[]', '["Yüksek bir makaraya bir ip bağlayın ve ağırlığı seçin. Makaradan birkaç ayak geride, ayaklarınız kademeli şekilde (biri önde) durun ve ipi iki elinizle alın. Sırtınızı düz tutarak kalçadan öne eğilin; kollarınız önünüzde yukarı doğru uzanmış olsun. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı düz tutarak omzu açın ve ipi uyluklarınıza doğru aşağı çekin.", "Hareketin altında bekleyin ve latlarınızı sıkın.", "Ağırlığın tamamen stack üzerine oturmasına izin vermeden başlangıç pozisyonuna dönün."]', 'strength', '["Rope_Straight-Arm_Pulldown/0.jpg", "Rope_Straight-Arm_Pulldown/1.jpg"]', 360.0, 'Rope Straight-Arm Pulldown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('457669f9-496d-5936-9c9a-6cc2eacc4610', 'free-exercise-db', 'Round_The_World_Shoulder_Stretch', 'Omuz Esnetme (Çubukla Daire)', 'static', 'beginner', NULL, '["other"]', '["shoulders"]', '["biceps", "chest"]', '["Bacaklarınız bitişik, düz şekilde ayakta durun ve bir body bar veya süpürge sapı tutun.", "Çubuğu kalçanızın arkasında omuz genişliğinden daha geniş bir tutuşla tutun. Avuç içleriniz aşağı bakmalı ve başparmaklarınız dışa dönük olmalıdır.", "Kollarınızı başınızın arkasından yavaşça yukarı kaldırın. Daha fazla kaldırmak zorlaşırsa zorlamayın."]', 'stretching', '["Round_The_World_Shoulder_Stretch/0.jpg", "Round_The_World_Shoulder_Stretch/1.jpg"]', 150.0, 'Round The World Shoulder Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('62cc8809-52f9-53b9-a16a-c0756e4afd5e', 'free-exercise-db', 'Rowing_Stationary', 'Kürek Makinesi', NULL, 'intermediate', NULL, '["machine"]', '["quadriceps"]', '["biceps", "calves", "glutes", "hamstrings", "lower back", "middle back"]', '["Başlamak için kürek makinesine oturun. Topuklarınızın ayak pedallarının tabanına rahatça yaslandığından ve kayışların sabitlendiğinden emin olun. Varsa kullanmak istediğiniz programı seçin. Dik oturun ve kalçadan öne doğru eğilin.", "Kürek makinesi kullanırken üç hareket evresi vardır. İlk evre, makinede öne doğru geldiğiniz evredir. Dizleriniz bükülü ve göğsünüze yakındır. Üst vücudunuz iyi duruşu korurken hafifçe öne eğiktir. Ardından ayak pedallarına karşı iterek bacaklarınızı uzatın ve bunu yaparken ellerinizi üst karın bölgenize getirerek omuzlarınızı geriye doğru sıkın. Sırtınızı zorlamamak için esas olarak bacak ve kalça kaslarınızı kullanın.", "Toparlanma evresi basitçe kollarınızı düzeltmeyi, dizlerinizi bükmeyi ve ilk evreye geçerken vücudunuzu tekrar öne getirmeyi içerir."]', 'cardio', '["Rowing_Stationary/0.jpg", "Rowing_Stationary/1.jpg"]', 600.0, 'Rowing, Stationary', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('098a2038-bc27-522d-aa9d-213fd8e6ec39', 'free-exercise-db', 'Runners_Stretch', 'Koşucu Esnetmesi', 'static', 'beginner', NULL, '[]', '["hamstrings"]', '["calves"]', '["Bu esnemeye en kolay, ayakta başlayıp bir bacağınızı arkanıza uzatarak ve gövdenizi yavaşça yere doğru indirerek geçilir.", "Ön ayağınızın topuğunu yerde tutun (kalkarsa diğer bacağınızı daha geriye kaydırın).", "Ellerinizi ön bacağınızın iki yanına yerleştirin. Esnemeden daha fazla verim almak için kalçanızı tavana doğru itin, ardından kademeli olarak yere doğru indirin. Arka bacağın kalça fleksörünü, ön bacağın ise arka bacak ve kalça kaslarını esnetirsiniz."]', 'stretching', '["Runners_Stretch/0.jpg", "Runners_Stretch/1.jpg"]', 150.0, 'Runner''s Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('230f4e3a-12ce-52eb-8ece-e1f19d17e270', 'free-exercise-db', 'Running_Treadmill', 'Koşu Bandında Koşu', NULL, 'beginner', NULL, '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için koşu bandına çıkın ve menüden istediğiniz seçeneği belirleyin. Çoğu koşu bandında manuel bir ayar bulunur veya koşmak için bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kalori miktarını tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz. Antrenmanın yoğunluğunu değiştirmek için eğim ayarlanabilir.", "Koşu bantları kolaylık ve kardiyovasküler faydalar sunar ve genellikle dışarıda koşmaktan daha az darbe etkisi yaratır. 68 kg''lık bir kişi saatte yaklaşık 13 km hızla 30 dakika koşarak 450 kaloriden fazla yakar. Koşarken doğru duruşu koruyun ve tutamaklardan yalnızca gerektiğinde, örneğin banttan inerken veya kalp atış hızınızı kontrol ederken tutunun."]', 'cardio', '["Running_Treadmill/0.jpg", "Running_Treadmill/1.jpg"]', 600.0, 'Running, Treadmill', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0acaef99-3a1b-59d8-83d8-61a9301cc3ce', 'free-exercise-db', 'Russian_Twist', 'Russian Twist', 'pull', 'intermediate', 'compound', '["body only"]', '["abdominals"]', '["lower back"]', '["Yere uzanın ve ayaklarınızı hareket etmeyecek bir şeyin altına yerleştirin veya bir partnerin tutmasını sağlayın. Bacaklarınız dizlerden bükülü olmalıdır.", "Üst vücudunuzu uyluklarınızla hayali bir V şekli oluşturacak şekilde yükseltin. Kollarınız önünüzde gövdenize dik olacak şekilde tamamen uzanmış ve eller kenetlenmiş olmalıdır. Bu başlangıç pozisyonudur.", "Nefes verirken kollarınız yere paralel olana kadar gövdenizi sağ tarafa doğru döndürün.", "Kasılmayı bir saniye tutun ve nefes verirken başlangıç pozisyonuna geri dönün. Şimdi sağ tarafa uyguladığınız aynı teknikleri uygulayarak karşı tarafa geçin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Russian_Twist/0.jpg", "Russian_Twist/1.jpg"]', 360.0, 'Russian Twist', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9c9bb5da-9cb9-54e9-9384-b87e2a601dcc', 'free-exercise-db', 'Sandbag_Load', 'Kum Torbası Yükleme (Strongman)', 'pull', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abdominals", "biceps", "calves", "forearms", "glutes", "hamstrings", "lower back", "middle back", "shoulders", "traps"]', '["Kum torbalarını veya diğer nesneleri yüklemek için, aletleri yükleme platformundan belirli bir mesafeye, genellikle 50 feet (yaklaşık 15 m) uzağa yerleştirerek başlayın.", "Kum torbasını kaldırarak başlayın. Kum torbaları son derece kullanışsızdır ve kaldırma şekli kullanılan torbaya göre değişebilir. Torbanın etrafından olabildiğince uzağa uzanın, yukarı çekmek için kalça ve dizlerinizi açın. Omuza almaya genellikle izin verilmez.", "Olabildiğince hızlı platforma gidin ve yükleyin; olabildiğince yükseğe çıkarmak için kalça, diz ve bileklerinizi açın. Düşmediğinden emin olarak platforma yerleştirin.", "Bir sonraki kum torbasını almak için başlangıç pozisyonuna dönün ve etkinlik tamamlanana kadar tekrarlayın."]', 'strongman', '["Sandbag_Load/0.jpg", "Sandbag_Load/1.jpg"]', 480.0, 'Sandbag Load', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('53c0f26a-f3c4-508b-8a93-f787c1c25efe', 'free-exercise-db', 'Scapular_Pull-Up', 'Skapular Barfiks', 'pull', 'beginner', 'isolation', '[]', '["traps"]', '["lats", "middle back"]', '["Barfiks barını pronasyon tutuşla kavrayın.", "Asılı pozisyondan, kollarınızı kullanmadan kendinizi birkaç santim yukarı kaldırın. Bunu, ters şrag hareketiyle omuz kuşağınızı aşağı bastırarak yapın.", "Hareketin sonunda duraklayın, ardından daha fazla tekrar yapmadan önce yavaşça başlangıç pozisyonuna dönün."]', 'strength', '["Scapular_Pull-Up/0.jpg", "Scapular_Pull-Up/1.jpg"]', 360.0, 'Scapular Pull-Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e4d5228a-eafb-511a-b16b-903f86e1e226', 'free-exercise-db', 'Scissor_Kick', 'Makas Bacak Hareketi', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Başlamak için sırtınız yere veya bir egzersiz matına bastırılmış şekilde uzanın (mat isteğe bağlıdır). Kollarınız yanlara tamamen uzamış ve avuç içleri aşağı bakmalıdır. Not: Kollar tüm süre boyunca sabit olmalıdır.", "Dizlerinizi hafif bükerek bacaklarınızı topuklarınız yerden yaklaşık 6 inç (15 cm) yukarıda olacak şekilde kaldırın. Bu başlangıç pozisyonudur.", "Şimdi sol bacağınızı yaklaşık 45 derece açıya kadar kaldırırken sağ bacağınızı topuk yerden yaklaşık 2-3 inç (5-7 cm) uzakta olana kadar indirin.", "Sağ bacağınızı kaldırıp sol bacağınızı indirerek hareketi değiştirin. Bu egzersizi yaparken nefes almayı unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'stretching', '["Scissor_Kick/0.jpg", "Scissor_Kick/1.jpg"]', 150.0, 'Scissor Kick', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7d079842-3f7b-521c-b7f5-a0a000be5e5e', 'free-exercise-db', 'Scissors_Jump', 'Makas Sıçrama', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Bir ayak önde ve dizi bükülü, arka diz neredeyse yere değecek şekilde lunge duruşu alın.", "Ön dizin ayağın orta çizgisinin üzerinde olduğundan emin olun. Her iki bacağı da açarak, yükselmek için kollarınızı sallayarak olabildiğince yükseğe zıplayın.", "Olabildiğince yükseğe zıplarken bacaklarınızın pozisyonunu değiştirin; ön bacağı arkaya, arka bacağı öne getirin.", "İnerken, lunge pozisyonuna geçerek darbeyi bacaklarınızla emerek tekrarlayın."]', 'plyometrics', '["Scissors_Jump/0.jpg", "Scissors_Jump/1.jpg"]', 480.0, 'Scissors Jump', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('375e6d06-7b32-59ff-ab26-32554f485388', 'free-exercise-db', 'Seated_Band_Hamstring_Curl', 'Oturarak Leg Curl (Direnç Bandı)', 'pull', 'beginner', 'isolation', '["other"]', '["hamstrings"]', '[]', '["Bir bandı yere yakın bir noktaya sabitleyin ve bir bench''i ondan birkaç adım uzağa yerleştirin.", "Bench''e oturun ve bandı bacaklarınız düz halde, ayak bileklerinizin arkasına sabitleyin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dizlerinizi bükerek ayaklarınızı bench''e doğru getirin. Ayaklarınızın yere çarpmasını önlemek için biraz geriye yaslanmanız gerekebilir.", "Hareketin sonunda bekleyin, ardından yavaşça başlangıç pozisyonuna dönün."]', 'strength', '["Seated_Band_Hamstring_Curl/0.jpg", "Seated_Band_Hamstring_Curl/1.jpg"]', 360.0, 'Seated Band Hamstring Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ba4fcc5a-3138-5cc5-9aec-879870e7c25a', 'free-exercise-db', 'Seated_Barbell_Military_Press', 'Oturarak Military Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["triceps"]', '["Başınızın arkasında bir bar olacak şekilde bir Military Press Bench''ine oturun ve barı ya bir spotter''ın size vermesini sağlayın (bu şekilde rotator cuff için daha iyidir) ya da dikkatlice pronasyon (avuç içleri öne bakan) tutuşla kendiniz alın. İpucu: Tutuşunuz omuz genişliğinden geniş olmalı ve halter aşağı inerken ön kol ile üst kol arasında 90 derecelik bir açı oluşturmalıdır.", "Halteri doğru tutuş genişliğiyle aldıktan sonra kollarınızı kilitleyerek barı başınızın üzerine kaldırın. Yaklaşık omuz hizasında ve başınızın biraz önünde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken barı yavaşça köprücük kemiğine doğru indirin.", "Nefes verirken barı başlangıç pozisyonuna kaldırın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Barbell_Military_Press/0.jpg", "Seated_Barbell_Military_Press/1.jpg"]', 360.0, 'Seated Barbell Military Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6a77c006-3c94-5ee4-8291-b0d1008c2f88', 'free-exercise-db', 'Seated_Barbell_Twist', 'Oturarak Twist (Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["abdominals"]', '[]', '["Düz bir sehpanın ucuna oturarak ve halteri uyluklarınızın üzerine koyarak başlayın. Ayaklarınız birbirinden omuz genişliğinde açık olmalıdır.", "Barı avuç içleriniz aşağı bakacak şekilde kavrayın ve ellerinizin birbirinden omuz genişliğinden geniş olduğundan emin olun. Kolların tamamen uzanana kadar halteri başınızın üzerine kaldırmaya başlayın.", "Şimdi halteri başınızın arkasına, boynunuzun tabanı boyunca dayanacak şekilde indirin. Bu başlangıç pozisyonudur.", "Ayaklarınızı ve başınızı sabit tutarak, oblik kaslarınızın kasılmayı hissetmesi için belinizi sağa sola hareket ettirin. Yalnızca belinizin izin verdiği kadar yana hareket edin. Fazla esnemek veya fazla uzağa gitmek sakatlanmaya neden olabilir. İpucu: Yavaş ve kontrollü bir hareket kullanın.", "Vücudunuzu yana döndürürken nefes vermeyi, başlangıç pozisyonuna dönerken nefes almayı unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Barbell_Twist/0.jpg", "Seated_Barbell_Twist/1.jpg"]', 360.0, 'Seated Barbell Twist', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d73b0f34-e62c-5840-89ee-788bc81cfe53', 'free-exercise-db', 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'Oturarak Öne Eğik Tek Kol Triceps Extension (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Düz bir bankın ucuna, bir elinizde nötr tutuşla (avuç içi size bakacak şekilde) bir dambıl olacak şekilde oturun.", "Dizlerinizi hafif bükün ve sırtınızı düz tutarak belinizden eğilerek gövdenizi neredeyse yere paralel olana kadar öne getirin. Başınızı yukarıda tuttuğunuzdan emin olun.", "Dambılı tutan üst kol gövdeye yakın ve onunla aynı hizada olmalıdır (yere paralel olana kadar yukarı kaldırılmış, eller ağırlıkları tutarken ön kollar yere doğru bakıyor). İpucu: Ön kollar ile üst kol arasında 90 derecelik bir açı olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolu sabit tutarak, ön kol yere paralel olana ve tüm kol uzayana kadar nefes verirken ağırlığı triceps ile kaldırın. Diğer birçok kol egzersizinde olduğu gibi yalnızca ön kol hareket eder.", "Üstte bir saniyelik kasılmadan sonra, nefes alırken dambılı yavaşça başlangıç pozisyonuna indirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Kol değiştirin ve egzersizi tekrarlayın."]', 'strength', '["Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg", "Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1d70a8f9-e4c5-5b2e-bfed-466b582056a2', 'free-exercise-db', 'Seated_Bent-Over_Rear_Delt_Raise', 'Oturarak Arka Omuz Kaldırma (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Düz bir bench''in önüne, ileri bakacak şekilde bir çift dambıl yerleştirin.", "Bench''in ucuna bacaklarınız bitişik ve dambıllar baldırlarınızın arkasında olacak şekilde oturun.", "Dambılları almak için sırtınızı düz tutarak belinizden öne eğilin. Dambılları alırken avuç içleriniz birbirine bakmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Gövdenizi öne eğik ve sabit, kollarınızı dirseklerden hafifçe bükülü tutarak, her iki kol yere paralel olana kadar dambılları yanlara doğru düz bir şekilde kaldırın. Ağırlıkları kaldırırken nefes verin. (Not: Gövdeyi sallamaktan veya kolları yanlar yerine geriye getirmekten kaçının.)", "Üstte bir saniyelik kasılmadan sonra dambılları yavaşça başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Bent-Over_Rear_Delt_Raise/0.jpg", "Seated_Bent-Over_Rear_Delt_Raise/1.jpg"]', 360.0, 'Seated Bent-Over Rear Delt Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f9c0bd87-64fd-560e-a90e-9946080f17c5', 'free-exercise-db', 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'Oturarak Eğilmiş Triceps Kickback (Çift Kol, Dambıl)', 'push', 'intermediate', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Düz bir sehpanın ucuna oturun ve iki elinizde nötr tutuşla (avuç içleri size bakacak şekilde) dambıl tutun.", "Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak belden eğilip gövdenizi neredeyse yere paralel olana kadar öne getirin. Başınızı yukarıda tuttuğunuzdan emin olun.", "Dambıllı üst kollar gövdenize yakın ve onunla aynı hizada olmalıdır (eller ağırlıkları tutarken ön kollar yere bakarken üst kollar yere paralel olana kadar kaldırılmış). İpucu: Ön kollar ile üst kol arasında 90 derecelik açı olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarak, nefes verirken ön kollar yere paralel olana ve tüm kol uzayana kadar triceps''i kullanarak ağırlığı kaldırın. Diğer birçok kol egzersizinde olduğu gibi yalnızca ön kol hareket eder.", "Üst noktada bir saniyelik kasılmanın ardından nefes alırken dambılları yavaşça başlangıç pozisyonuna indirin.", "Hareketi belirtilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg", "Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d9b2c2cd-7c38-5e93-8621-c82f2e241acf', 'free-exercise-db', 'Seated_Biceps', 'Oturarak Biceps Esnetme (Partnerli)', 'static', 'expert', 'isolation', '["body only"]', '["biceps"]', '["chest", "shoulders"]', '["Dizleriniz bükülü şekilde yere oturun ve partneriniz arkanızda ayakta dursun. Kollarınızı avuç içleri birbirine bakacak şekilde arkanıza doğru düz uzatın. Partneriniz bileklerinizi sizin için tutacaktır. Bu başlangıç pozisyonu olacaktır.", "Partneriniz gerçek bir harekete izin vermezken dirseklerinizi bükmeye çalışın.", "10-20 saniye sonra, partneriniz biceps''inizi esnetmek için bileklerinizi nazikçe yukarı çekerken kollarınızı gevşetin. Yaralanmayı veya aşırı esnemeyi önlemek için esnemenin ne zaman uygun olduğunu partnerinize bildirdiğinizden emin olun."]', 'stretching', '["Seated_Biceps/0.jpg", "Seated_Biceps/1.jpg"]', 150.0, 'Seated Biceps', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6bda3628-03e4-5929-b2af-fc8c7e7baa62', 'free-exercise-db', 'Seated_Cable_Rows', 'Oturarak Kablo Row', 'pull', 'beginner', 'compound', '["cable"]', '["middle back"]', '["biceps", "lats", "shoulders"]', '["Bu egzersiz için V-bar''lı bir alçak makara row makinesine erişiminiz olmalı. Not: V-bar, avuç içlerinizin birbirine baktığı nötr bir tutuşa sahip olmanızı sağlar. Başlangıç pozisyonuna geçmek için önce makineye oturun ve ayaklarınızı öndeki platforma veya çapraz çubuğa yerleştirin; dizlerinizin hafifçe bükülü olduğundan ve kilitli olmadığından emin olun.", "Sırtınızın doğal hizasını koruyarak öne eğilin ve V-bar tutacaklarını kavrayın.", "Kollarınız uzamış halde, gövdeniz bacaklarınızla 90 derecelik açı yapana kadar geriye çekin. Sırtınız hafifçe kavisli ve göğsünüz dışarıda olmalıdır. Barı önünüzde tutarken lat kaslarınızda güzel bir gerilme hissetmelisiniz. Bu egzersizin başlangıç pozisyonudur.", "Gövdenizi sabit tutarak, kollarınızı gövdenize yakın tutup karın kaslarınıza dokunana kadar tutacakları gövdenize doğru geriye çekin. Bu hareketi yaparken nefes verin. Bu noktada sırt kaslarınızı sertçe sıkıyor olmalısınız. Bu kasılmayı bir saniye tutun ve nefes alırken yavaşça orijinal pozisyona dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Cable_Rows/0.jpg", "Seated_Cable_Rows/1.jpg"]', 360.0, 'Seated Cable Rows', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0db8c0a1-db96-510d-aed6-43993914b7da', 'free-exercise-db', 'Seated_Cable_Shoulder_Press', 'Oturarak Shoulder Press (Kablo)', 'push', 'beginner', 'compound', '["cable"]', '["shoulders"]', '["triceps"]', '["Ağırlığı uygun bir miktara ayarlayın ve oturarak tutamakları kavrayın. Üst kollarınız vücuda yaklaşık 90 derece açıda, başınız ve göğsünüz yukarıda olmalıdır. Dirsekler de yaklaşık 90 derece bükülü olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseklerinizi açarak ve tutamakları başınızın üzerinde birbirine doğru iterek başlayın.", "Üst noktada bekledikten sonra tutamakları başlangıç pozisyonuna geri getirin. Kablolardaki gerginliği koruduğunuzdan emin olun.", "Bu hareketi sırtınız pedden ayrılmış halde ve elleri dönüşümlü kullanarak da yapabilirsiniz."]', 'strength', '["Seated_Cable_Shoulder_Press/0.jpg", "Seated_Cable_Shoulder_Press/1.jpg"]', 360.0, 'Seated Cable Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2f681a9d-50e3-5dd3-82ff-013d8c842078', 'free-exercise-db', 'Seated_Calf_Raise', 'Oturarak Calf Raise (Makine)', 'push', 'beginner', 'isolation', '["machine"]', '["calves"]', '[]', '["Makineye oturun ve ayak parmaklarınızı sağlanan platformun alt kısmına, topuklarınız boşlukta kalacak şekilde yerleştirin. Bu bölümün başında anlatıldığı gibi istediğiniz ayak parmağı konumunu (öne, içe veya dışa) seçin.", "Alt uyluklarınızı, uyluk yüksekliğinize göre ayarlanması gereken kol pedinin altına yerleştirin. Şimdi pedin öne kaymasını önlemek için ellerinizi kol pedinin üzerine koyun.", "Topuklarınızı iterek kolu hafifçe kaldırın ve güvenlik çubuğunu serbest bırakın. Bu sizin başlangıç pozisyonunuzdur.", "Baldırlarınız tamamen gerilene kadar ayak bileklerinizi bükerek topuklarınızı yavaşça indirin. Bu hareketi yaparken nefes alın.", "Baldırlarınızı kasarak ve nefes vererek ayak bileklerinizi olabildiğince yukarı açıp topuklarınızı kaldırın. Üstteki kasılmayı bir saniye tutun.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Calf_Raise/0.jpg", "Seated_Calf_Raise/1.jpg"]', 360.0, 'Seated Calf Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4580c158-9547-5661-a7d7-967c034b80fc', 'free-exercise-db', 'Seated_Calf_Stretch', 'Oturarak Baldır Esnetme', 'static', 'beginner', NULL, '[]', '["calves"]', '["hamstrings", "lower back"]', '["Bir egzersiz matı üzerinde dik oturun.", "Bir dizinizi bükün ve gövdenizi dengelemek için o ayağınızı yere koyun.", "Diğer bacağınızı düzleştirin ve ayak bileğinizi bükün.", "Bir bant, havlu veya uzanabiliyorsanız elinizi kullanarak ayak parmaklarını size doğru çekin. 10 ila 20 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["Seated_Calf_Stretch/0.jpg", "Seated_Calf_Stretch/1.jpg"]', 150.0, 'Seated Calf Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4690e3e5-5a91-58da-a178-59ad148b7163', 'free-exercise-db', 'Seated_Close-Grip_Concentration_Barbell_Curl', 'Oturarak Concentration Curl (Halter, Dar Tutuş)', 'pull', 'intermediate', 'isolation', '["barbell"]', '["biceps"]', '[]', '["Düz bir bankta, bacaklarınızın arasında önünüzde bir halter ya da EZ Bar olacak şekilde oturun. Bacaklarınız açık, dizler bükülü ve ayaklar yerde olmalıdır.", "Kollarınızı kullanarak halteri alın ve üst kollarınızın arkasını iç uyluklarınızın üzerine yerleştirin (dizin ön kısmından yaklaşık üç buçuk inç (9 cm) uzakta). Bu egzersizi yapmak için omuz genişliğinden dar, supinated bir tutuş gerekir. İpucu: Kolunuz tam uzatılmış olmalı ve halter yerden yukarıda olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarak, nefes verirken biceps''i kasarak ağırlıkları öne doğru kıvırın. Yalnızca ön kollar hareket etmelidir. Biceps''iniz tamamen kasılana ve dambıllar omuz seviyesine gelene kadar harekete devam edin. Biceps''i sıkarken kasılmış pozisyonu bir saniye tutun.", "Nefes alırken halteri yavaşça başlangıç pozisyonuna getirmeye başlayın. İpucu: Hiçbir zaman sallanma hareketlerinden kaçının.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg", "Seated_Close-Grip_Concentration_Barbell_Curl/1.jpg"]', 360.0, 'Seated Close-Grip Concentration Barbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('85f54e2e-05bd-5acb-a13e-44c4d6ef2145', 'free-exercise-db', 'Seated_Dumbbell_Curl', 'Oturarak Biceps Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her elinizde kol boyu mesafede bir dambıl tutarak düz bir bench üzerine oturun. Dirsekleriniz gövdeye yakın olmalı.", "Avuç içlerinizi gövdenize bakacak şekilde çevirin. Bu sizin başlangıç pozisyonunuz olacak.", "Üst kolu sabit tutarak ağırlıkları kıvırın ve dambıllar uyluklarınızı geçtikten sonra bileklerinizi döndürmeye başlayın; böylece hareketin sonunda avuç içleriniz ileri baksın. Nefes verirken biceps''i kastığınızdan ve sadece ön kolların hareket ettiğinden emin olun. Biceps''iniz tamamen kasılana ve dambıllar omuz seviyesine gelene kadar harekete devam edin. Biceps''i sıkarken kasılmış pozisyonu bir saniye tutun.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna geri getirmeye başlayın ve bileklerinizi tekrar nötr tutuşa döndürün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Dumbbell_Curl/0.jpg", "Seated_Dumbbell_Curl/1.jpg"]', 360.0, 'Seated Dumbbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ba293848-c2fd-59c2-a485-bced02e0d956', 'free-exercise-db', 'Seated_Dumbbell_Inner_Biceps_Curl', 'Inner Biceps Curl (Dambıl, Oturarak)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her elinizde kol boyu bir dambıl tutarak düz bir sehpanın ucuna oturun. Dirsekleriniz gövdenize yakın olmalıdır.", "Avuç içlerini nötr pozisyonda içe bakacak şekilde döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarken dambılları dışa ve yukarı doğru kıvırın; kaldırırken avuç içlerini dışa çevirin ve ön kollarınızı dış deltoid kaslarınızla aynı hizada tutun. İpuçları:", "Yalnızca ön kollar hareket etmelidir. Biceps''iniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar harekete devam edin. Biceps''i sıkarak kasılmış pozisyonda bir saniye bekleyin.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna getirmeye başlayın. Dambılları indirirken nötr tutuşa geri dönebilmek için kollarınızı döndürmeyi unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Dumbbell_Inner_Biceps_Curl/0.jpg", "Seated_Dumbbell_Inner_Biceps_Curl/1.jpg"]', 360.0, 'Seated Dumbbell Inner Biceps Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('60969481-adb7-5947-b144-90f32c6f331f', 'free-exercise-db', 'Seated_Dumbbell_Palms-Down_Wrist_Curl', 'Oturarak Wrist Curl (Dambıl, Avuç İçi Aşağı)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["İki dambılı düz bir bench''in önünde yere yerleştirerek başlayın.", "Düz bench''in kenarına, bacaklarınız yaklaşık omuz genişliğinde açık olacak şekilde oturun. Ayaklarınızı yerde tuttuğunuzdan emin olun.", "Kollarınızla her iki dambılı kavrayın ve ön kollarınız uyluklarınıza dayanacak, avuç içleriniz aşağı bakacak şekilde yukarı getirin. Bilekleriniz uyluklarınızın kenarından sarkıyor olmalıdır.", "Bileklerinizi yukarı doğru kıvırarak ve nefes vererek başlayın.", "Nefes alırken bileklerinizi yavaşça başlangıç pozisyonuna indirin. Egzersizin bu kısmında nefes aldığınızdan emin olun. İpucu: Ön kollarınız sabit olmalı; bu egzersizi yapmak için gereken tek hareket bileğinizdir.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde dambılları yere bırakmanız yeterlidir."]', 'strength', '["Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg", "Seated_Dumbbell_Palms-Down_Wrist_Curl/1.jpg"]', 360.0, 'Seated Dumbbell Palms-Down Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7a0d3978-4592-54be-a098-4505420372ea', 'free-exercise-db', 'Seated_Dumbbell_Palms-Up_Wrist_Curl', 'Oturarak Avuç İçi Yukarı Wrist Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["İki dambılı düz bir sehpanın önünde yere koyarak başlayın.", "Bacaklarınız yaklaşık omuz genişliğinde açık olacak şekilde düz sehpanın kenarına oturun. Ayaklarınızı yerde tuttuğunuzdan emin olun.", "Kollarınızla iki dambılı da kavrayın ve avuç içleri yukarı bakacak şekilde ön kollarınız uyluklarınıza dayanacak biçimde yukarı getirin. Bilekleriniz uyluklarınızın kenarından sarkmalıdır.", "Bileklerinizi yukarı doğru kıvırarak ve nefes vererek başlayın.", "Nefes alırken bileklerinizi yavaşça başlangıç pozisyonuna indirin. Egzersizin bu kısmında nefes aldığınızdan emin olun. İpucu: Bu egzersizi yapmak için gereken tek hareket bilek olduğundan ön kollarınız sabit kalmalıdır.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde dambılları basitçe yere indirin."]', 'strength', '["Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg", "Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg"]', 360.0, 'Seated Dumbbell Palms-Up Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6ca82e9a-2beb-54dd-9f6e-2c2bfe704502', 'free-exercise-db', 'Seated_Dumbbell_Press', 'Oturarak Omuz Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Bir çift dambıl alın ve dambılları dik şekilde uyluklarınızın üzerine yerleştirerek bir military press bench''ine veya sırt desteği olan çok amaçlı bir bench''e oturun.", "Dambılları, uyluklarınızı kullanarak her iki yanda omuz hizasına getirecek şekilde tek tek yukarı kaldırın (clean).", "Bileklerinizi avuç içleriniz öne bakacak şekilde döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken dambılları üstte birbirine değene kadar yukarı itin.", "Bir saniyelik duraklamanın ardından nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Dumbbell_Press/0.jpg", "Seated_Dumbbell_Press/1.jpg"]', 360.0, 'Seated Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('76c4dff8-2656-58ac-98ee-25071969bb01', 'free-exercise-db', 'Seated_Flat_Bench_Leg_Pull-In', 'Oturarak Bacak Çekme (Düz Bench)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Bacaklarınız önünüzde yere paralelin biraz altında uzanmış ve kollarınız bench''in kenarlarını tutarak bir bench üzerine oturun. Gövdeniz bench''ten yaklaşık 45 derecelik bir açıyla geriye yaslanmış olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Gövdenizi aynı anda dizlerinize yaklaştırırken dizlerinizi size doğru çekin. Bu hareketi yaparken nefes verin.", "Bir saniyelik duraklamadan sonra nefes alırken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Flat_Bench_Leg_Pull-In/0.jpg", "Seated_Flat_Bench_Leg_Pull-In/1.jpg"]', 360.0, 'Seated Flat Bench Leg Pull-In', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fb0aaed9-ab25-57e5-95c1-35e88b2ffc7f', 'free-exercise-db', 'Seated_Floor_Hamstring_Stretch', 'Oturarak Yerde Arka Bacak Esnetme', 'static', 'beginner', NULL, '[]', '["hamstrings"]', '["calves"]', '["Bir matın üzerinde sağ bacağınız önünüzde uzatılmış ve sol bacağınız bükülü, ayağınız sağ iç uyluğunuza dayalı şekilde oturun.", "Kalçanızdan öne eğilin ve arka bacağınızda bir esneme hissedene kadar bileğinize uzanın. 15 saniye bekleyin, ardından diğer taraf için tekrarlayın."]', 'stretching', '["Seated_Floor_Hamstring_Stretch/0.jpg", "Seated_Floor_Hamstring_Stretch/1.jpg"]', 150.0, 'Seated Floor Hamstring Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7b554f39-c540-531d-8a69-aff611c2e8c8', 'free-exercise-db', 'Seated_Front_Deltoid', 'Oturarak Ön Omuz Esnetme (Partnerli)', 'static', 'expert', NULL, '["body only"]', '["shoulders"]', '["chest"]', '["Dizleriniz bükülü şekilde yerde dik oturun, partneriniz arkanızda dursun. Kollarınızı avuç içleri yere bakacak şekilde yanlara dümdüz uzatın. Yardımcınız bileklerinizi tutarken kollarınızı olabildiğince arkaya götürmeye çalışın. Bu sizin başlangıç pozisyonunuzdur.", "Dirseklerinizi düz tutarak kollarınızı öne getirmeye çalışın; partneriniz 10-20 saniye boyunca gerçek bir hareketi önlemek için sizi nazikçe tutsun.", "Şimdi kaslarınızı gevşetin ve partnerinizin omuzlardaki ve göğüsteki esnemeyi nazikçe artırmasına izin verin. 10-20 saniye bekleyin."]', 'stretching', '["Seated_Front_Deltoid/0.jpg", "Seated_Front_Deltoid/1.jpg"]', 150.0, 'Seated Front Deltoid', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('64a18adc-9d4e-57f7-8752-cda0d7888e3e', 'free-exercise-db', 'Seated_Glute', 'Oturarak Kalça Esnetme (Partnerli)', 'static', 'expert', NULL, '["body only"]', '["glutes"]', '["adductors"]', '["Dizleriniz bükülü şekilde otururken bir ayak bileğinizi karşı dizinizin üzerinden çaprazlayın. Partneriniz arkanızda duracaktır. Şimdi partneriniz elleriyle omuzlarınızı desteklerken öne doğru eğilin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Partneriniz gövdenizin gerçek bir hareketine izin vermezken 10-20 saniye boyunca gövdenizi geriye doğru itmeye çalışın.", "Şimdi kaslarınızı gevşetin; partneriniz 10-20 saniye boyunca gövdenizi nazikçe öne doğru iterek esnemeyi artırsın."]', 'stretching', '["Seated_Glute/0.jpg", "Seated_Glute/1.jpg"]', 150.0, 'Seated Glute', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7ee37644-1a01-5ebd-89d2-7d5ca8dc4f84', 'free-exercise-db', 'Seated_Good_Mornings', 'Oturarak Good Morning (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["lower back"]', '["glutes"]', '["Bir power rack içine bir box yerleştirin. Pimler uygun yüksekliğe ayarlanmalıdır. Barın altına girerek ve trapez kaslarınızın üzerine değil omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine doğru sıkın ve barı omuzlarınızın üzerinde bükmeye çalışır gibi dirseklerinizi öne doğru döndürün.", "Barı raftan alırken belinizde sıkı bir kavis oluşturun. Başınızı ileri bakacak şekilde tutun. Sırtınız, omuzlarınız ve karın bölgeniz sıkı haldeyken dizlerinizi ve kalçanızı dışarı doğru iterek inişe başlayın. Box''ın üzerine oturana kadar kalçanızı geriye atın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Barı sıkı tutarak kalçadan mümkün olduğunca öne doğru eğilin. Pimleri paralel olacak bir seviyeye ayarlarsanız, başarısız olursanız hem bir güvenliğiniz olur hem de ne zaman duracağınızı bilirsiniz.", "Pimlerin hemen üzerinde duraklayın ve gövdeniz dik olana kadar hareketi tersine çevirin."]', 'powerlifting', '["Seated_Good_Mornings/0.jpg", "Seated_Good_Mornings/1.jpg"]', 360.0, 'Seated Good Mornings', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f036d256-c702-5c3b-95b0-832e7c8a8f87', 'free-exercise-db', 'Seated_Hamstring', 'Oturarak Arka Bacak Esnetme (Partnerli)', 'static', 'expert', NULL, '[]', '["hamstrings"]', '["calves"]', '["Bacaklarınız uzatılmış şekilde oturur pozisyonda, partnerinizin arkanızda durmasını sağlayın. Şimdi partneriniz elleriyle omuzlarınızı desteklerken öne eğilin. Bu sizin başlangıç pozisyonunuzdur.", "Partneriniz gövdenizin gerçekten hareket etmesini engellerken, gövdenizi 10-20 saniye geriye itmeye çalışın.", "Şimdi kaslarınızı gevşetin; partneriniz gövdenizi 10-20 saniye nazikçe öne iterek esnemeyi artırsın."]', 'stretching', '["Seated_Hamstring/0.jpg", "Seated_Hamstring/1.jpg"]', 150.0, 'Seated Hamstring', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bb116cc3-4bc7-5653-b402-997114b60d9d', 'free-exercise-db', 'Seated_Hamstring_and_Calf_Stretch', 'Oturarak Arka Bacak ve Baldır Esnetme', 'static', 'intermediate', NULL, '["other"]', '["hamstrings"]', '["calves"]', '["Bir kemer, ip ya da bandı ayaklarınızdan birine dolayın. İki bacağınız uzanmış şekilde oturun. Bu sizin başlangıç pozisyonunuzdur.", "Hafifçe öne eğilerek ayağınızın parmaklarını geriye doğru çekmek için kemeri çekin. Bu pozisyonu 10-20 saniye tutun ve ardından diğer bacakla tekrarlayın."]', 'stretching', '["Seated_Hamstring_and_Calf_Stretch/0.jpg", "Seated_Hamstring_and_Calf_Stretch/1.jpg"]', 150.0, 'Seated Hamstring and Calf Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('34ed6194-542f-5ca9-a781-f2039f24ee43', 'free-exercise-db', 'Seated_Head_Harness_Neck_Resistance', 'Oturarak Boyun Direnci (Baş Kayışı)', 'pull', 'intermediate', 'isolation', '["other"]', '["neck"]', '[]', '["Bir boyun kayışını düz bir bench''in ucunda yere yerleştirin. Ağırlıkları seçtikten sonra, ayaklarınız omuz genişliğinden daha geniş açık ve ayak parmaklarınız dışa bakacak şekilde düz bench''in ucuna oturun.", "Gövdenizi yere neredeyse paralel olana kadar yavaşça öne doğru getirin. İki elinizi kullanarak boyun kayışını başınızın etrafına sağlam bir şekilde yerleştirin. İpucu: Boynunuzda herhangi bir zorlanmayı önlemek için ağırlıkların hâlâ yerde durduğundan emin olun. Şimdi gövdenizi yere neredeyse dik olana kadar tekrar yükseltirken ağırlığı iki elinizle kavrayın. Not: Bu egzersizi yapmak için başınız ve gövdeniz hafifçe öne eğik olmalıdır.", "Şimdi iki elinizi dizlerinizin üzerine koyun. Bu başlangıç pozisyonudur.", "Nefes alırken çeneniz üst göğsünüze değene kadar boynunuzu yavaşça aşağı indirin.", "Nefes verirken boynunuzu başlangıç pozisyonuna geri getirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Head_Harness_Neck_Resistance/0.jpg", "Seated_Head_Harness_Neck_Resistance/1.jpg"]', 360.0, 'Seated Head Harness Neck Resistance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('63cd6861-9445-5a53-905d-7d30f6c956ba', 'free-exercise-db', 'Seated_Leg_Curl', 'Oturarak Leg Curl (Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["hamstrings"]', '[]', '["Makinenin kolunu boyunuza göre ayarlayın ve sırtınız sırt desteği minderine yaslanacak şekilde makineye oturun.", "Alt bacağınızın arkasını minderli kolun üzerine (baldırlarınızın sadece birkaç santim altına) yerleştirin ve uyluk minderini dizlerinizin hemen üstünde, uyluklarınıza karşı sabitleyin. Ardından ayak uçlarınızı düz tutarak (veya diğer iki duruşun herhangi birini de kullanabilirsiniz) makinenin yan saplarını kavrayın ve bacaklarınızın önünüzde tamamen düz olduğundan emin olun. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken, dizlerinizden bükülerek makine kolunu uyluklarınızın arkasına doğru olabildiğince çekin. Gövdenizi her zaman sabit tutun. Kasılmış pozisyonu bir saniye tutun.", "Nefes alırken yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Leg_Curl/0.jpg", "Seated_Leg_Curl/1.jpg"]', 360.0, 'Seated Leg Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5ee9f1f2-7a7e-5778-92e7-06c7f877f2d6', 'free-exercise-db', 'Seated_Leg_Tucks', 'Oturarak Diz Çekme', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Bacaklarınız önünüzde paralelin biraz altında uzatılmış ve kollarınız sehpanın yanlarına tutunmuş şekilde bir sehpaya oturun. Gövdeniz sehpadan yaklaşık 45 derecelik açıyla geriye yaslanmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi kendinize doğru çekin ve aynı anda gövdenizi onlara yaklaştırın. Bu hareketi yaparken nefes verin.", "Bir saniyelik duraklamanın ardından nefes alırken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Leg_Tucks/0.jpg", "Seated_Leg_Tucks/1.jpg"]', 360.0, 'Seated Leg Tucks', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('234561fc-5162-5018-99a8-306472b83e90', 'free-exercise-db', 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'Oturarak Tek Kol Avuç İçi Aşağı Wrist Curl (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["Sağ elinizde bir dambıl ile düz bir sehpaya oturun.", "Ayaklarınızı yere düz basın; omuz genişliğinden biraz daha geniş aralıkta olsun.", "Öne eğilin ve avuç içi aşağı bakacak şekilde sağ ön kolunuzu sağ üst uyluğunuzun üzerine koyun. İpucu: Bileğin arkasının dizlerinizin üzerinde durduğundan emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Dambılı sıkı tutarak olabildiğince aşağı indirin. Bu hareketi yaparken nefes alın.", "Şimdi ön kolları kasarak ve nefes vererek dambılı olabildiğince yukarı kıvırın. Tekrar inmeden önce kasılmayı bir saniye koruyun. İpucu: Tek hareket bilekte gerçekleşmelidir.", "Önerilen tekrar sayısı kadar yapın, kolları değiştirin ve hareketi tekrarlayın."]', 'strength', '["Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg", "Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/1.jpg"]', 360.0, 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d1cd6512-ab7f-56ab-9201-f6f43ec930ea', 'free-exercise-db', 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'Oturarak Tek Kol Wrist Curl (Dambıl, Avuç İçi Yukarı)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["forearms"]', '[]', '["Sağ elinizde bir dambıl olacak şekilde düz bir bankta oturun.", "Ayaklarınızı yere düz basarak omuz genişliğinden biraz daha geniş açın.", "Öne eğilin ve sağ ön kolunuzu avuç içi yukarı bakacak şekilde sağ üst uyluğunuzun üzerine yerleştirin. İpucu: Bileğin ön kısmının dizlerinizin üzerinde durduğundan emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Dambılı sıkı tutarak olabildiğince aşağı indirin. Bu hareketi yaparken nefes alın.", "Şimdi ön kolları kasarak ve nefes vererek dambılı olabildiğince yukarı kıvırın. Tekrar indirmeden önce kasılmayı bir saniye tutun. İpucu: Hareket yalnızca bilekte gerçekleşmelidir.", "Önerilen tekrar sayısı kadar yapın, kol değiştirin ve hareketi tekrarlayın."]', 'strength', '["Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg", "Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/1.jpg"]', 360.0, 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d5de76b7-20b2-568b-a67a-88f6d49ed975', 'free-exercise-db', 'Seated_One-arm_Cable_Pulley_Rows', 'Oturarak Tek Kol Kablo Row', 'pull', 'intermediate', 'compound', '["cable"]', '["middle back"]', '["biceps", "lats", "traps"]', '["Başlangıç pozisyonuna geçmek için önce makineye oturun ve ayaklarınızı öndeki platforma veya çapraz çubuğa yerleştirin; dizlerinizin hafifçe bükülü olduğundan ve kilitli olmadığından emin olun.", "Sırtınızın doğal hizasını koruyarak öne eğilin ve tek tutacak aparatını sol kolunuzla avuç içi aşağı bakan tutuşla kavrayın.", "Kolunuz uzamış halde, gövdeniz bacaklarınızla 90 derecelik açı yapana kadar geriye çekin. Sırtınız hafifçe kavisli ve göğsünüz dışarıda olmalıdır. Barı önünüzde tutarken lat kasınızda güzel bir gerilme hissetmelisiniz. Sağ kolunuzu belinizin yanında tutabilirsiniz. Bu egzersizin başlangıç pozisyonudur.", "Gövdenizi sabit tutarak, kollarınızı gövdenize yakın tutup bileğinizi döndürerek tutacakları gövdenize doğru çekin; böylece eliniz karın kaslarınızın yanına geldiğinde nötr pozisyonda olsun (avuç içi gövdeye bakacak şekilde). Bu hareketi yaparken nefes verin. Bu noktada sırt kaslarınızı sertçe sıkıyor olmalısınız.", "Bu kasılmayı bir saniye tutun ve nefes alırken yavaşça orijinal pozisyona dönün. İpucu: Başlangıç pozisyonuna dönerken avuç içlerinin tekrar aşağı bakması için bileği döndürmeyi unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın ve ardından aynı hareketi sağ elle yapın."]', 'strength', '["Seated_One-arm_Cable_Pulley_Rows/0.jpg", "Seated_One-arm_Cable_Pulley_Rows/1.jpg"]', 360.0, 'Seated One-arm Cable Pulley Rows', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0da6c91f-e38c-5eb5-b850-60abffd90bb8', 'free-exercise-db', 'Seated_Overhead_Stretch', 'Oturarak Baş Üstü Yan Esnetme', 'static', 'beginner', 'isolation', '[]', '["abdominals"]', '[]', '["Bir egzersiz matı üzerinde dik oturun.", "Ayak tabanlarınızı, ayaklarınız kalçanızın altı ila sekiz inç (15-20 cm) önünde olacak şekilde birbirine değdirin.", "Bir elinizi yanınızda yere, diğer elinizi başınızın arkasına koyun.", "Gövdenizi diğer yana eğerken dirseğinizi tavana doğru kaldırın. 10-20 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["Seated_Overhead_Stretch/0.jpg", "Seated_Overhead_Stretch/1.jpg"]', 150.0, 'Seated Overhead Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('407a70b5-774c-5a0b-9b55-5fe3d267128d', 'free-exercise-db', 'Seated_Palm-Up_Barbell_Wrist_Curl', 'Oturarak Bilek Curl (Halter, Avuç İçi Yukarı)', 'pull', 'beginner', 'isolation', '["barbell"]', '["forearms"]', '[]', '["Halteri her iki elinizle avuç içleriniz yukarı bakacak şekilde tutun; eller yaklaşık omuz genişliğinde aralıklı olsun.", "Ayaklarınızı yere düz basın; omuz genişliğinden biraz daha geniş bir mesafede olsun.", "Öne eğilin ve ön kollarınızı avuç içleri yukarı bakacak şekilde üst uyluklarınızın üzerine koyun. İpucu: Bileklerin ön kısmının dizlerinizin üzerinde durduğundan emin olun. Bu sizin başlangıç pozisyonunuz olacak.", "Sıkı bir kavrayışı koruyarak nefes alırken barı olabildiğince aşağı indirin.", "Şimdi ön kol kaslarını kasarak ve nefes vererek barı olabildiğince yukarı kıvırın. Kasılmayı üstte bir saniye tutun. İpucu: Sadece bilek hareket etmelidir."]', 'strength', '["Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg", "Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg"]', 360.0, 'Seated Palm-Up Barbell Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a70665d5-8d2c-592e-959e-0c92e1424b13', 'free-exercise-db', 'Seated_Palms-Down_Barbell_Wrist_Curl', 'Oturarak Wrist Curl (Halter, Avuç İçi Aşağı)', 'pull', 'beginner', 'isolation', '["barbell"]', '["forearms"]', '[]', '["Bir halteri iki elinizle avuç içleriniz aşağı bakacak şekilde tutun; elleriniz yaklaşık omuz genişliğinde açık olsun.", "Ayaklarınızı yere düz basın ve omuz genişliğinden biraz daha geniş açın.", "Öne eğilin ve ön kollarınızı avuç içleriniz aşağı bakacak şekilde üst uyluklarınızın üzerine koyun. İpucu: Bileklerinizin arkasının dizlerinizin üzerinde durduğundan emin olun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken ve sıkı bir tutuşu korurken barı gidebildiğiniz kadar aşağı indirin.", "Şimdi ön kollarınızı kasarak ve nefes vererek barı olabildiğince yukarı curl yapın. Üst noktada kasılmayı bir saniye tutun. İpucu: Sadece bilek hareket etmelidir."]', 'strength', '["Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg", "Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg"]', 360.0, 'Seated Palms-Down Barbell Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0451a7ca-2317-53e7-a0c6-e5a1cb228633', 'free-exercise-db', 'Seated_Side_Lateral_Raise', 'Lateral Raise (Dambıl, Oturarak)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Birer dambıl alın ve ayaklarınız yerde sağlam şekilde düz bir sehpanın ucuna oturun. Dambılları avuç içleri içe bakacak ve kollarınız yanlarınızda kol boyu aşağı sarkacak şekilde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarken (sallanmadan), dirsek hafif bükülü ve eller bir bardağa su döker gibi hafifçe öne eğik olacak şekilde dambılları yanlara doğru kaldırın. Kollarınız yere paralel olana kadar yukarı çıkmaya devam edin. Bu hareketi yaparken nefes verin ve üstte bir saniye bekleyin.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Side_Lateral_Raise/0.jpg", "Seated_Side_Lateral_Raise/1.jpg"]', 360.0, 'Seated Side Lateral Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1e9aba09-b423-5a97-a073-8afe64b9ffcd', 'free-exercise-db', 'Seated_Triceps_Press', 'Oturarak Triceps Press (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Sırt desteği olan bir sehpaya oturun ve bir dambılı iki elinizle kavrayarak kollarınız uzanmış şekilde başınızın üzerinde tutun. İpucu: Özellikle çok ağırsa, birinin size vermesi daha iyi bir yöntemdir. Ağırlık avuç içlerinizde durmalı ve başparmaklarınız etrafına sarılmalıdır. Elin avuç içi içe bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı başınıza yakın (dirsekler içeride) ve yere dik tutarak, ön kollarınız biceps''inize değene kadar ağırlığı başınızın arkasına yarım daire hareketiyle indirin. İpucu: Üst kollar sabit kalmalı ve yalnızca ön kollar hareket etmelidir. Bu adımı yaparken nefes alın.", "Dambılı kaldırmak için triceps''i kullanarak başlangıç pozisyonuna dönün. Bu adımı yaparken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Triceps_Press/0.jpg", "Seated_Triceps_Press/1.jpg"]', 360.0, 'Seated Triceps Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('21fdbcf7-4a5f-5abc-9ed1-3d45304c6dd1', 'free-exercise-db', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'Oturarak İki Kol Wrist Curl (Alt Kablo, Avuç İçi Yukarı)', 'pull', 'beginner', 'isolation', '["cable"]', '["forearms"]', '[]', '["Bir halter veya EZ Curl aparatı takılı alçak makaralı makinenin önüne bir bank yerleştirin.", "Sapı uyluklarınızın üstüne getirdiğinizde ağırlık bloğu yukarı hareket ettiği için kablo üzerinde gerginlik oluşacak kadar bankı uzağa taşıyın.", "Şimdi sapı iki elinizle, avuç içleri yukarı bakacak şekilde omuz genişliğinde bir tutuşla tutun.", "Geri adım atın ve ayaklarınız yaklaşık omuz genişliğinde, yere sağlam basacak şekilde bankta oturun.", "Öne eğilin ve bileklerinizin arkası dizlerinizin üzerinde olacak şekilde ön kollarınızı uyluklarınıza yerleştirin. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken ve sıkı bir kavrayışı koruyarak barı olabildiğince aşağı indirin.", "Şimdi ön kolları kasarak barı olabildiğince yukarı kıvırın. İpucu: Yalnızca bilek hareket etmelidir; ön kollar değil.", "Üstte bir saniyelik kasılmadan sonra nefes alırken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg", "Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/1.jpg"]', 360.0, 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d365cf33-1610-53f1-bb91-6c1d3c1ea08d', 'free-exercise-db', 'See-Saw_Press_Alternating_Side_Press', 'Tahterevalli Press (Dambıl, Dönüşümlü Yan Press)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["abdominals", "triceps"]', '["Her elinize bir dambıl alın ve dik durun.", "Dambılları göğüs/omuz seviyesine clean ile (kaldırarak) alın ve ardından sanki Arnold Press yapmaya hazırlanıyormuş gibi avuç içleriniz size bakacak şekilde bileklerinizi döndürün. Bu sizin başlangıç pozisyonunuz olacak.", "Şimdi sol kolunuzu yukarı çıkarken avuç içiniz ileri bakacak şekilde bileğinizi döndürerek baş üstüne doğru uzatmaya başlayın. Ağırlığı kaldırırken dirsekleriniz de dışarı çıkmalı. Aynı anda kalçanızdan karşı tarafa doğru da eğileceksiniz. İpucu: Egzersizi doğru yaparsanız, sanki vücudunuzun sağ tarafında baş üstündeki bir şeye sol kolunuzla uzanmaya çalışıyormuşsunuz gibi görünmelidir. Bu hareketi yaparken nefes verin.", "Üst pozisyona ulaştığınızda nefes alın. Ardından ağırlık baş üstünde tamamen uzanmış ve sağ tarafınıza eğilmişken, sol tarafa doğru harekete başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["See-Saw_Press_Alternating_Side_Press/0.jpg", "See-Saw_Press_Alternating_Side_Press/1.jpg"]', 360.0, 'See-Saw Press (Alternating Side Press)', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6cd81b95-ab5e-5073-b80f-92ea504a026d', 'free-exercise-db', 'Shotgun_Row', 'Shotgun Row (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back"]', '["Tek bir tutamağı alt kabloya takın.", "Doğru ağırlığı seçtikten sonra, geniş bir split duruşla birkaç adım geride durun. Kolunuz uzatılmış ve omzunuz öne doğru olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Omzunuzu geriye çekerek ve dirseğinizi bükerek hareketi gerçekleştirin. Çekerken bileğinizi supine ederek, avuç içinizi yukarı doğru çevirin.", "Kısa bir beklemeden sonra başlangıç pozisyonuna dönün."]', 'strength', '["Shotgun_Row/0.jpg", "Shotgun_Row/1.jpg"]', 360.0, 'Shotgun Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9fffad78-03fb-5585-a751-64d998f0d419', 'free-exercise-db', 'Shoulder_Circles', 'Omuz Daireleri', 'pull', 'beginner', NULL, '[]', '["shoulders"]', '["traps"]', '["Omuzlarınız gevşek ve kollarınız yanlarınızda serbestçe dururken (veya oturuyorsanız kucağınızda) omuzlarınızı nazikçe öne, yukarı, geriye ve aşağı doğru döndürün.", "Yönü tersine çevirin. Bu egzersizi omuzları dönüşümlü olarak veya ikisini aynı anda yaparak uygulayabilirsiniz."]', 'stretching', '["Shoulder_Circles/0.jpg", "Shoulder_Circles/1.jpg"]', 150.0, 'Shoulder Circles', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('054549ef-b827-5082-882c-5ad23bdc481f', 'free-exercise-db', 'Shoulder_Press_-_With_Bands', 'Shoulder Press (Direnç Bandı)', 'push', 'beginner', 'compound', '["bands"]', '["shoulders"]', '["triceps"]', '["Başlamak için gerilim kol boyunda başlayacak şekilde bir egzersiz bandının üzerine basın. Tutamakları kavrayın ve eller her iki yanda omuz yüksekliğine gelecek şekilde kaldırın.", "Avuç içleriniz öne bakacak şekilde bileklerinizi döndürün. Dirsekleriniz bükülü, üst kollar ve ön kollar gövdeyle aynı hizada olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken kollarınız başınızın üzerinde tamamen uzanana kadar tutamakları yukarı kaldırın."]', 'strength', '["Shoulder_Press_-_With_Bands/0.jpg", "Shoulder_Press_-_With_Bands/1.jpg"]', 360.0, 'Shoulder Press - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('15b01f42-a1d3-59e9-97b4-8af45e6763e2', 'free-exercise-db', 'Shoulder_Raise', 'Omuz Kaldırma', 'pull', 'beginner', NULL, '[]', '["shoulders"]', '["lats"]', '["Kollarınızı yanlarınızda gevşetin ve omuzlarınızı kulaklarınıza doğru kaldırın, ardından tekrar aşağı indirin."]', 'stretching', '["Shoulder_Raise/0.jpg", "Shoulder_Raise/1.jpg"]', 150.0, 'Shoulder Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6d9a00fe-5ca2-5baa-a271-20b4635ee741', 'free-exercise-db', 'Shoulder_Stretch', 'Omuz Esnetme', 'pull', 'beginner', NULL, '[]', '["shoulders"]', '[]', '["Sol kolunuzu vücudunuzun önünden karşı tarafa uzatın ve düz tutun."]', 'stretching', '["Shoulder_Stretch/0.jpg", "Shoulder_Stretch/1.jpg"]', 150.0, 'Shoulder Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3f5bf0ff-7e06-5f9d-846c-9375eee955d7', 'free-exercise-db', 'Side-Lying_Floor_Stretch', 'Yan Yatarak Yerde Esnetme', 'static', 'beginner', NULL, '[]', '["lats"]', '[]', '["Önce sol yanınıza yatın, gövdenizi dengelemek için sol dizinizi önünüzde bükün (sizi dik tutmak için karın kaslarınızı da kullanın).", "Sağ bacağınızı düzleştirin ve sağ ayağınızı solun arkasında yere koyun. Sağ kolunuzu başınızın üzerine uzatın ve vücudun sağ tarafının tamamını esnetmek için sağ bileğinizi nazikçe çekin. Taraf değiştirin."]', 'stretching', '["Side-Lying_Floor_Stretch/0.jpg", "Side-Lying_Floor_Stretch/1.jpg"]', 150.0, 'Side-Lying Floor Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('dbcb80c2-980a-57d9-bfe6-a728ab07a54d', 'free-exercise-db', 'Side_Bridge', 'Yan Plank (Side Bridge)', 'static', 'beginner', NULL, '["body only"]', '["abdominals"]', '["shoulders"]', '[]', 'strength', '["Side_Bridge/0.jpg", "Side_Bridge/1.jpg"]', 360.0, 'Side Bridge', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6df158d5-afbe-578c-a9c6-0264f02de8b0', 'free-exercise-db', 'Side_Hop-Sprint', 'Yana Sıçrama ve Sprint', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "hamstrings"]', '["Bir koninin veya engelin yanında durun.", "Bu drille engelin üzerinden yana sıçrayarak ve inişten geri tepip başladığınız yere geri sıçrayarak başlayın.", "Belirlenen tekrar sayısı kadar mümkün olduğunca hızlı sıçrayın ve son sıçramada indikten sonra kısa bir mesafe sprint atarak drili bitirin."]', 'plyometrics', '["Side_Hop-Sprint/0.jpg", "Side_Hop-Sprint/1.jpg"]', 480.0, 'Side Hop-Sprint', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('74ab9508-78f1-5a1c-aa18-c5039c001e58', 'free-exercise-db', 'Side_Jackknife', 'Yan Jackknife', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '[]', 'strength', '["Side_Jackknife/0.jpg", "Side_Jackknife/1.jpg"]', 360.0, 'Side Jackknife', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('93513d5b-e224-58de-8ebb-abeecfe4b10c', 'free-exercise-db', 'Side_Lateral_Raise', 'Lateral Raise (Dambıl) – Side Lateral Raise', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Birer dambıl alın ve gövdeniz düz şekilde, dambıllar yanınızda kol boyu ve avuç içleriniz size bakacak şekilde ayakta durun. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarken (sallanmadan), dirsek hafif bükülü ve eller bir bardağa su döker gibi hafifçe öne eğik olacak şekilde dambılları yanlara doğru kaldırın. Kollarınız yere paralel olana kadar yukarı çıkmaya devam edin. Bu hareketi yaparken nefes verin ve üstte bir saniye bekleyin.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Side_Lateral_Raise/0.jpg", "Side_Lateral_Raise/1.jpg"]', 360.0, 'Side Lateral Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4ee1a871-c39d-583e-a70b-162a92193452', 'free-exercise-db', 'Side_Laterals_to_Front_Raise', 'Lateral Raise ve Front Raise (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '["traps"]', '["Ayakta dururken bir çift dambılı yanlarınızda tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseklerinizi hafifçe bükülü tutarak, sallanmadan veya hile yapmadan ağırlıkları doğrudan önünüzde omuz yüksekliğine kadar kaldırın.", "Hareketin üst noktasında, kollarınızı uzatılmış tutarak ağırlıkları önünüzde dışarı doğru hareket ettirin.", "Ağırlıkları kontrollü bir hareketle indirin.", "Bir sonraki tekrarda, ağırlıkları yanlarınıza doğru yana hareket ettirmeden önce önünüzde omuz yüksekliğine kaldırın.", "Ağırlıkları başlangıç pozisyonuna indirin."]', 'strength', '["Side_Laterals_to_Front_Raise/0.jpg", "Side_Laterals_to_Front_Raise/1.jpg"]', 360.0, 'Side Laterals to Front Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('82083add-ebcd-5d7a-9628-152d951ec3c9', 'free-exercise-db', 'Side_Leg_Raises', 'Yana Bacak Kaldırma (Ayakta)', 'pull', 'beginner', NULL, '["body only"]', '["adductors"]', '[]', '["Destek için tutunabileceğiniz bir sandalyenin yanında durun. Tek bacak üzerinde durun. Bu sizin başlangıç pozisyonunuzdur.", "Bacağınızı düz tutarak olabildiğince yana kaldırın ve karşı bacağı çaprazlamasına izin vererek aşağı savurun.", "Bu savurma hareketini, hareket açıklığını artırarak 5-10 kez tekrarlayın."]', 'stretching', '["Side_Leg_Raises/0.jpg", "Side_Leg_Raises/1.jpg"]', 150.0, 'Side Leg Raises', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fc51800a-912f-550c-b7f0-209a31b8a832', 'free-exercise-db', 'Side_Lying_Groin_Stretch', 'Yan Yatarak Kasık Esnetme', 'static', 'beginner', 'isolation', '[]', '["adductors"]', '["hamstrings"]', '["Sağ yanınıza uzanarak başlayın ve gövdeyi sabitlemek için sağ dizinizi önünüzde bükün.", "Başınızı sağ elinize veya omzunuza yaslayın. Sol bacağınızı yukarı kaldırın ve diz arkasından (daha kolay) veya ayaktan (daha zor) tutun.", "Sol dizinizi sol omzunuza doğru çekin ve aynı anda ayağınızı veya dizinizi yere doğru bastırın. Bu esnetmeyi yoğunlaştırmak için sol bacağınızı düzeltin. Taraf değiştirin."]', 'stretching', '["Side_Lying_Groin_Stretch/0.jpg", "Side_Lying_Groin_Stretch/1.jpg"]', 150.0, 'Side Lying Groin Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1111282e-2427-5847-aaea-991fc4239514', 'free-exercise-db', 'Side_Neck_Stretch', 'Yan Boyun Esnetme', 'static', 'beginner', 'isolation', '[]', '["neck"]', '[]', '["Omuzlarınız gevşek şekilde başlayın, başınızı nazikçe omzunuza doğru eğin.", "Esnemeye, başınızın yan tarafından nazikçe çekerek yardımcı olun."]', 'stretching', '["Side_Neck_Stretch/0.jpg", "Side_Neck_Stretch/1.jpg"]', 150.0, 'Side Neck Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('10e5cd65-1771-53c5-bcee-d57a18392461', 'free-exercise-db', 'Side_Standing_Long_Jump', 'Yana Durarak Uzun Atlama', 'push', 'beginner', 'compound', '[]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Ayaklarınız kalça genişliğinde, atletik bir duruşta durarak başlayın. Başınız ve göğsünüz yukarıda, dizleriniz ve kalçanız hafifçe bükülü olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Sağa doğru eğilerek, havaya zıplamak için kalça, diz ve ayak bileklerinizi açın. Hareketi yönlendirmek için kollarınızla destek vererek sağınıza doğru olabildiğince uzağa zıplayın.", "Aynı yöne bakacak şekilde, ayaklarınız kalça genişliğinde olarak inin ve darbeyi alt vücudunuzla emerek."]', 'plyometrics', '["Side_Standing_Long_Jump/0.jpg", "Side_Standing_Long_Jump/1.jpg"]', 480.0, 'Side Standing Long Jump', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('025f38a8-1b4d-55df-a71f-d64779ccb2ea', 'free-exercise-db', 'Side_To_Side_Chins', 'Yana Kayarak Barfiks (Chin)', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["biceps", "forearms", "middle back", "shoulders"]', '["Barfiks barını avuç içleriniz öne bakacak şekilde geniş tutuşla kavrayın.", "Her iki kolunuz önünüzde geniş tutuşla bar elinizde uzatılmışken, gövdenizi yaklaşık 30 derece geriye yatırın, bel bölgenizde hafif bir kavis oluşturun ve göğsünüzü öne çıkarın. Bu sizin başlangıç pozisyonunuzdur.", "Omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek, bar üst göğsünüze neredeyse değene kadar sol tarafa doğru eğilerek gövdenizi yukarı çekin. Bu hareketi yaparken nefes verin. İpucu: Tam kasılma pozisyonuna ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde hareket ederken sabit kalmalı (sallanma olmamalı), yalnızca kollar hareket etmelidir. Ön kollar barı tutmaktan başka bir iş yapmamalıdır.", "Bir saniyelik kasılmadan sonra, başlangıç pozisyonuna dönerken nefes alın.", "Şimdi omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek, bar üst göğsünüze neredeyse değene kadar sağ tarafa doğru eğilerek gövdenizi yukarı çekin. Bu hareketi yaparken nefes verin. İpucu: Tam kasılma pozisyonuna ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde hareket ederken sabit kalmalı, yalnızca kollar hareket etmelidir. Ön kollar barı tutmaktan başka bir iş yapmamalıdır.", "Bir saniyelik kasılmadan sonra, başlangıç pozisyonuna dönerken nefes alın.", "Her iki taraf için de belirlenen tekrar sayısını tamamlayana kadar 3-6. adımları tekrarlayın."]', 'strength', '["Side_To_Side_Chins/0.jpg", "Side_To_Side_Chins/1.jpg"]', 360.0, 'Side To Side Chins', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('65cb8b88-5e3e-56f4-ac5b-0115a1a4ac93', 'free-exercise-db', 'Side_Wrist_Pull', 'Yan Bilek Çekme Esnetmesi', 'static', 'beginner', 'isolation', '[]', '["shoulders"]', '["forearms", "lats"]', '["Bu esneme en iyi ayakta çalışır. Sol kolunuzu vücudunuzun orta çizgisinin üzerinden çaprazlayın ve sol bileğinizi kalça seviyesinde sağ elinizle tutun. Esnemeye bükülü bir sol kolla başlayın.", "Yavaşça düzeltin, çekin ve resimde gösterildiği gibi omuz yüksekliğine kadar kaldırın. Bu esnemenin omuzlarınızda değil sırtınızda başladığını hissedin ve omuz eklemini çok sert çekmeyin. Taraf değiştirin."]', 'stretching', '["Side_Wrist_Pull/0.jpg", "Side_Wrist_Pull/1.jpg"]', 150.0, 'Side Wrist Pull', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5040fecd-eb55-5d93-89bf-4855997f28cf', 'free-exercise-db', 'Side_to_Side_Box_Shuffle', 'Kutu Üzerinde Yana Shuffle', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "hamstrings"]', '["Sol ayağınız kutunun ortasına basacak şekilde kutunun bir yanında durun.", "Başlamak için kutunun diğer tarafına zıplayın ve sağ ayağınız kutunun üzerine, sol ayağınız yere inecek şekilde yere inin. Hareketinize yardımcı olmak için kollarınızı savurun.", "Kutunun iki yanında ileri geri shuffle yapmaya devam edin."]', 'plyometrics', '["Side_to_Side_Box_Shuffle/0.jpg", "Side_to_Side_Box_Shuffle/1.jpg"]', 480.0, 'Side to Side Box Shuffle', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4d0632ea-b194-513a-8298-5f843c794af5', 'free-exercise-db', 'Single-Arm_Cable_Crossover', 'Cable Crossover (Tek Kol)', 'push', 'beginner', 'isolation', '["cable"]', '["chest"]', '[]', '["Makaraları üst konuma getirerek başlayın, kullanılacak direnci seçin ve her elinize bir tutamak alın.", "Her iki makaranın önüne adım atın, kollarınız önünüzde uzanmış ve elleriniz birleşmiş olsun. Öne eğilirken başınız ve göğsünüz yukarıda olmalı, ayaklarınız çapraz basamaklı konumda olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Sol kolunuzu yerinde tutarken sağ kolunuzun dirsek hafif bükülü şekilde yana doğru açılmasına izin verin. Sağ kol vücuda dik ve yaklaşık omuz hizasında olmalıdır.", "Elinizi vücudun orta çizgisine geri çekerek kolunuzu başlangıç pozisyonuna getirin.", "Başlangıç pozisyonunda bir saniye bekleyin ve hareketi karşı tarafta tekrarlayın. Belirtilen tekrar sayısı boyunca dönüşümlü olarak devam edin."]', 'strength', '["Single-Arm_Cable_Crossover/0.jpg", "Single-Arm_Cable_Crossover/1.jpg"]', 360.0, 'Single-Arm Cable Crossover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f1c4447f-ded8-571d-a533-b86bbf3341db', 'free-exercise-db', 'Single-Arm_Linear_Jammer', 'Tek Kol Linear Jammer (Landmine)', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["chest", "triceps"]', '["Bir barı landmine''a yerleştirin veya bir köşeye sağlam bir şekilde sabitleyin. Barı uygun bir ağırlıkla yükleyin.", "Barı yerden kaldırın ve bir veya iki elinizle omuzlarınıza getirin. Geniş bir duruş alın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi açarak ağırlığı yukarı iterek hareketi gerçekleştirin. Maksimum kuvvet üretmek için kalça ve dizlerinizi tamamen açarak patlayıcı bir şekilde hareket edin.", "Başlangıç pozisyonuna dönün."]', 'strength', '["Single-Arm_Linear_Jammer/0.jpg", "Single-Arm_Linear_Jammer/1.jpg"]', 360.0, 'Single-Arm Linear Jammer', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7c697cac-5248-5be8-9362-e8c98e3d9325', 'free-exercise-db', 'Single-Arm_Push-Up', 'Tek Kol Şınav', 'push', 'intermediate', 'compound', '["body only"]', '["chest"]', '["shoulders", "triceps"]', '["Yere yüzüstü uzanarak başlayın. Kendinizi ağırlığınız ayak parmaklarınızda ve tek kolunuzda desteklenecek bir pozisyona getirin. Çalışan kolunuz doğrudan omzun altında, tamamen uzanmış olmalı. Bacaklarınız uzanmış olmalı ve bu hareket için daha geniş bir taban gerekebilir; ayaklarınızı normal şınavdakinden daha açık yerleştirin.", "İyi bir duruşu koruyun ve serbest elinizi sırtınızın arkasına koyun. Bu sizin başlangıç pozisyonunuz olacak.", "Yere değene kadar dirseğinizin bükülmesine izin vererek kendinizi alçaltın.", "Yavaşça inin ve kolunuzu açarak yönü tersine çevirip başlangıç pozisyonuna dönün."]', 'strength', '["Single-Arm_Push-Up/0.jpg", "Single-Arm_Push-Up/1.jpg"]', 360.0, 'Single-Arm Push-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('185e6ec0-5eee-50b6-bcd4-119f2638c755', 'free-exercise-db', 'Single-Cone_Sprint_Drill', 'Tek Koni Sprint Çalışması', 'push', 'beginner', NULL, '["other"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bu çalışma hızlı ayak hareketini öğretir. Tek bir koniye ihtiyacınız var. Bir kolunuz geride, diğeri ileride olacak şekilde koninin yanında durarak başlayın.", "Kollarınızla blok yaparak ayaklarınızı olabildiğince hızlı bir şekilde küçük adımlarla hareket ettirin. Dizlerinizi yukarıda tutarak ve sert ayak hareketiyle koninin etrafında daire çizin.", "Koninin etrafında üç tur attıktan sonra dinlenin."]', 'plyometrics', '["Single-Cone_Sprint_Drill/0.jpg", "Single-Cone_Sprint_Drill/1.jpg"]', 480.0, 'Single-Cone Sprint Drill', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c97b5593-5bb0-5598-9ff3-01e6662ad59f', 'free-exercise-db', 'Single-Leg_High_Box_Squat', 'Tek Bacak Yüksek Box Squat', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Bir kutuyu rack''in içine yerleştirin. Kutunun üzerinde bir bandı veya ipi yerine sabitleyin.", "Kutunun önünde durarak kutuya tam ayakta duruş pozisyonuna adım atın; diğer bacağınızın desteksiz kalmasına izin verin. Denge için banttan tutunun.", "Karşı tarafa geçmeden önce aynı bacakla kutuya çıkıp inmeye devam edin."]', 'strength', '["Single-Leg_High_Box_Squat/0.jpg", "Single-Leg_High_Box_Squat/1.jpg"]', 360.0, 'Single-Leg High Box Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('77149e9a-9819-5824-816a-d03bc88eb5c0', 'free-exercise-db', 'Single-Leg_Hop_Progression', 'Tek Bacak Sıçrama Progresyonu', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "hamstrings"]', '["Önünüze bir sıra koni dizin. Rahat bir ayakta duruş pozisyonu alın ve tek bacak üzerinde dengede durun. Karşı bacağınızın dizini kaldırın. Bu sizin başlangıç pozisyonunuz olacaktır.", "İleri doğru sıçrayın; koninin üzerinden aynı bacakla zıplayıp inin.", "Koniden koniye sıçramak için karşı hareketli (countermovement) bir sıçrama kullanın.", "Sonunda dönün ve diğer bacakla geri gidin."]', 'plyometrics', '["Single-Leg_Hop_Progression/0.jpg", "Single-Leg_Hop_Progression/1.jpg"]', 480.0, 'Single-Leg Hop Progression', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3eeac667-554a-5670-83b4-bec4f6d77b64', 'free-exercise-db', 'Single-Leg_Lateral_Hop', 'Tek Bacak Yana Sıçrama', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "hamstrings"]', '["Bir koninin ya da engelin yanında durun. Başlangıç pozisyonuna geçmek için dizinizi hafifçe bükerek tek bacak üzerinde durun.", "Başlamak için koninin üzerinden yana doğru sıçramak için bir karşı sıçrama (counterjump) yapın.", "Sıçradığınız bacağın üzerine inin ve hemen oradan geri sıçrayarak başlangıç pozisyonuna dönün.", "İleri geri sıçramaya devam edin."]', 'plyometrics', '["Single-Leg_Lateral_Hop/0.jpg", "Single-Leg_Lateral_Hop/1.jpg"]', 480.0, 'Single-Leg Lateral Hop', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ce5f6585-e6c0-5313-ba89-61fc87252508', 'free-exercise-db', 'Single-Leg_Leg_Extension', 'Tek Bacak Leg Extension (Makine)', 'push', 'beginner', 'isolation', '["machine"]', '["quadriceps"]', '[]', '["Makineye oturun ve düzgün konumlanacak şekilde ayarlayın. Ped, kaval kemiğinin alt kısmına karşı olmalı ancak ayak bileğine temas etmemelidir. Koltuğu, dönme noktası dizinizle aynı hizada olacak şekilde ayarlayın. Yeteneklerinize uygun bir ağırlık seçin.", "İyi bir duruşu koruyarak bir bacağınızı tamamen uzatın ve hareketin üst noktasında bekleyin.", "Ağırlığın durmasına izin vermeden, kastaki gerginliği koruyarak başlangıç pozisyonuna dönün.", "İstediğiniz tekrar sayısı kadar tekrarlayın."]', 'strength', '["Single-Leg_Leg_Extension/0.jpg", "Single-Leg_Leg_Extension/1.jpg"]', 360.0, 'Single-Leg Leg Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2776244e-595a-56cd-b601-b47ed98e2b81', 'free-exercise-db', 'Single-Leg_Stride_Jump', 'Tek Bacak Adım Sıçraması', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "hamstrings"]', '["Bir kutunun yanında, iç ayağınız kenara yakın şekilde üstünde olacak biçimde durun.", "Üstteki bacakla iterken kollarınızı yukarı sallayarak başlayın ve olabildiğince yükseğe zıplayın. Karşı dizi yukarı doğru sürmeye çalışın.", "Başladığınız pozisyona inin ve darbeyi yavaşlatmak için iç bacağınızı kullanın."]', 'plyometrics', '["Single-Leg_Stride_Jump/0.jpg", "Single-Leg_Stride_Jump/1.jpg"]', 480.0, 'Single-Leg Stride Jump', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4e2008a3-9339-54a4-a2fe-e173b65e91f2', 'free-exercise-db', 'Single_Dumbbell_Raise', 'Dambıl Kaldırma (Tek Dambıl, İki Elle)', NULL, 'beginner', 'isolation', '["dumbbell"]', '["shoulders"]', '["forearms", "traps"]', '["Geniş bir duruşla, sapı değil dambılın başını kavrayarak dambılı iki elinizle tutun. Kollarınız uzamış ve bel hizasında sarkıyor olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı uzamış tutarak ağırlığı omuz seviyesinin üstüne kadar kaldırın. Gövdeniz ve kalçanız hareket boyunca sabit kalmalıdır.", "Başlangıç pozisyonuna dönün ve önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Single_Dumbbell_Raise/0.jpg", "Single_Dumbbell_Raise/1.jpg"]', 360.0, 'Single Dumbbell Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f6696c09-db81-517a-a525-132ae76e1ad1', 'free-exercise-db', 'Single_Leg_Butt_Kick', 'Tek Bacak Topuk Vurma', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["calves", "hamstrings"]', '["Bükülü dizi kaldırılmış halde tek bacak üzerinde durarak başlayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Karşı hareketli (countermovement) bir sıçrayışla, yerdeki bacağın kalçasını, dizini ve ayak bileğini açarak yukarı doğru havalanın.", "Hemen dizinizi bükün ve sıçrayan bacağınızın topuğuyla kalçanıza dokunmaya çalışın.", "Bacağınızı kalçaların altında kısmen bükülü bir pozisyona getirin ve inin. Karşı bacağınız drill boyunca yaklaşık aynı pozisyonda kalmalıdır."]', 'plyometrics', '["Single_Leg_Butt_Kick/0.jpg", "Single_Leg_Butt_Kick/1.jpg"]', 480.0, 'Single Leg Butt Kick', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8e7d53c9-1f34-56b1-ade0-dd999ee929f4', 'free-exercise-db', 'Single_Leg_Glute_Bridge', 'Tek Bacak Glute Bridge', 'push', 'beginner', 'isolation', '["body only"]', '["glutes"]', '["hamstrings"]', '["Ayaklarınız yerde düz ve dizleriniz bükülü şekilde yere uzanın.", "Bir bacağınızı yerden kaldırın ve dizinizi göğsünüze çekin. Bu sizin başlangıç pozisyonunuzdur.", "Topuğunuzdan iterek, kalçanızı yukarı doğru açarak ve kalça kaslarınızı yerden kaldırarak hareketi gerçekleştirin.", "Olabildiğince yukarı uzanın, bekleyin ve ardından başlangıç pozisyonuna dönün."]', 'strength', '["Single_Leg_Glute_Bridge/0.jpg", "Single_Leg_Glute_Bridge/1.jpg"]', 360.0, 'Single Leg Glute Bridge', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a4ee5dfd-325a-506e-92e9-d86f613a68ec', 'free-exercise-db', 'Single_Leg_Push-off', 'Tek Bacak İtiş', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["calves", "hamstrings"]', '["Bir ayağınız kutunun üzerinde, topuğu kenara yakın olacak şekilde yerde durun.", "Kutunun üzerindeki ayağınızla iterek, kalça ve dizi açarak mümkün olduğunca fazla yükseklik kazanmaya çalışın.", "Aynı ayağınızla kutunun üzerine inin ve diğer ayağınızı başlangıç pozisyonuna geri getirin."]', 'plyometrics', '["Single_Leg_Push-off/0.jpg", "Single_Leg_Push-off/1.jpg"]', 480.0, 'Single Leg Push-off', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e4b353d7-afb8-5365-aa76-ab0bce90c006', 'free-exercise-db', 'Sit-Up', 'Sit-Up', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Ayaklarınızı hareket etmeyecek bir şeyin altına yerleştirerek veya bir partnerin tutmasını sağlayarak yere uzanın. Bacaklarınız dizlerden bükülü olmalıdır.", "Ellerinizi başınızın arkasına koyun ve parmaklarınızı kenetleyerek birbirine kilitleyin. Bu başlangıç pozisyonudur.", "Üst vücudunuzu uyluklarınızla hayali bir V şekli oluşturacak şekilde yükseltin. Egzersizin bu kısmını yaparken nefes verin.", "Bir saniye kasılmayı hissettikten sonra, nefes alırken üst vücudunuzu başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Sit-Up/0.jpg", "Sit-Up/1.jpg"]', 360.0, 'Sit-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('71c09f55-e3f4-5618-90e3-0bb3ed4793d9', 'free-exercise-db', 'Sit_Squats', 'Sit Squat (Yarım Squat)', 'push', 'beginner', NULL, '[]', '["quadriceps"]', '["abductors", "glutes", "hamstrings"]', '["Ayaklarınız omuz genişliğinde açık şekilde ayakta durun. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi ve kalçanızı bükerek, kalçanızla geriye oturarak harekete başlayın.", "Squat''ta bir miktar aşağı inene kadar, ancak paralelin üstünde kalarak devam edin ve hareketi hızla tersine çevirip başlangıç pozisyonuna dönün. 5-10 tekrar yapın."]', 'stretching', '["Sit_Squats/0.jpg", "Sit_Squats/1.jpg"]', 150.0, 'Sit Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c29a30ea-ec4c-5f66-bf87-3fbdce6682b2', 'free-exercise-db', 'Skating', 'Paten Kayma', NULL, 'intermediate', NULL, '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Paten kayma, kardiyorespiratuar kondisyonu ve kas dayanıklılığını geliştirmede etkili olabilen eğlenceli bir aktivitedir. Nispeten iyi bir denge ve koordinasyon gerektirir. Dönme ve durma dahil kaymanın temellerini öğrenmek ve olası sakatlıkları önlemek için koruyucu ekipman kullanmak gereklidir.", "30 dakika boyunca rahat bir tempoda kayabilirsiniz. Kardiyo açısından zorluk istiyorsanız aralıklı kayın: her beş dakikanın iki dakikasında hızlı kayın, kalan üç dakikayı toparlanmak için kullanın. 68 kg (150 lb) ağırlığındaki bir kişi rahat bir tempoda 30 dakika kayarak genellikle yaklaşık 175 kalori yakar; bu, tempolu yürüyüşe benzerdir."]', 'cardio', '["Skating/0.jpg", "Skating/1.jpg"]', 600.0, 'Skating', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('183dd3aa-d1a9-5a33-89b2-67d08dcbff31', 'free-exercise-db', 'Sled_Drag_-_Harness', 'Kızak Sürükleme (Koşum ile)', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için kızağı istenen ağırlıkla yükleyin ve çekme kayışını bağlayın. Saplarla çekebilir, bir koşum kullanabilir veya çekme kayışını bir ağırlık kemerine bağlayabilirsiniz.", "İleri ya da geri çekiyor olun, hareket yönüne doğru eğilin ve kalça ve dizlerinizi açarak ilerleyin."]', 'strongman', '["Sled_Drag_-_Harness/0.jpg", "Sled_Drag_-_Harness/1.jpg"]', 480.0, 'Sled Drag - Harness', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('79c03384-766b-5bde-8e2f-083b996d66cf', 'free-exercise-db', 'Sled_Overhead_Backward_Walk', 'Baş Üstü Geriye Yürüyüş (Kızak)', 'pull', 'beginner', 'compound', '["other"]', '["shoulders"]', '["calves", "middle back", "quadriceps"]', '["Halat veya zincirle bağlı bir kızağa çift tutacak takın. Kızağı hafif bir ağırlıkla yükleyin.", "Kızağa dönük durun ve hatta biraz gerginlik oluşana kadar geriye gidin. Ellerinizi dirsekleriniz uzamış halde tam başınızın üzerinde tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kollarınızı başınızın üzerinde kaldırılmış tutarak geriye doğru yürüyün. Sarsıntılı hareketlerden kaçının."]', 'strength', '["Sled_Overhead_Backward_Walk/0.jpg", "Sled_Overhead_Backward_Walk/1.jpg"]', 360.0, 'Sled Overhead Backward Walk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('65483564-dd77-51a8-977e-a7a6ab6cbdb1', 'free-exercise-db', 'Sled_Overhead_Triceps_Extension', 'Kızakla Baş Üstü Triceps Extension', 'push', 'beginner', 'isolation', '["other"]', '["triceps"]', '[]', '["Çift sapı bir zincir veya ip kullanarak kızağa bağlayın. Kızağı uygun bir yükle yükleyin.", "Kızağa sırtınız dönük, hatta gerginlik oluşana kadar uzaklaşın. Ellerinizi birbirine bitişik ve avuç içleri birbirine bakacak şekilde başınızın üzerine kaldırın. Dirsekleriniz bükülü ve yukarı bakıyor olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Kolu düzeltmek için dirseği açın. Triceps''i izole etmek için üst kolunuzun konumunda kaldığından emin olun.", "Tam açılmaya ulaştığınızda, hattaki gevşekliği almak için öne adım atın. Daha fazla denge için ayaklarınızı çapraz konumda tutabilirsiniz."]', 'strength', '["Sled_Overhead_Triceps_Extension/0.jpg", "Sled_Overhead_Triceps_Extension/1.jpg"]', 360.0, 'Sled Overhead Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a8cf7ff9-67e8-5991-ae92-03622892f253', 'free-exercise-db', 'Sled_Push', 'Kızak İtme (Sled Push)', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["calves", "chest", "glutes", "hamstrings", "triceps"]', '["İtme kızağınızı istenen ağırlıkla yükleyin.", "Atletik bir duruş alın, kollarınız tamamen uzatılmış ve sapları kavrayarak kızağa yaslanın. Kızağı olabildiğince hızlı itin, arka zincirinizi güçlendirmek için kalça ve dizlerinizi açmaya odaklanın."]', 'strongman', '["Sled_Push/0.jpg", "Sled_Push/1.jpg"]', 480.0, 'Sled Push', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('06b18eaf-3aff-5480-8689-48c644071590', 'free-exercise-db', 'Sled_Reverse_Flye', 'Reverse Fly (Kızak)', 'pull', 'beginner', 'isolation', '["other"]', '["shoulders"]', '[]', '["Çift tutamağı bir halat veya zincirle bağlı kızağa takın. Kızağı hafif bir ağırlıkla yükleyin.", "Kızağa dönük şekilde, hatta bir miktar gerginlik oluşana kadar geriye doğru gidin. Her iki tutamağı kol boyu, yaklaşık bel hizasında tutun. Dizlerinizi hafif bükün ve göğsünüz ile başınızı yukarıda tutun. Bu sizin başlangıç pozisyonunuzdur.", "Dirseği bükmeden tutamakları yukarı ve dışa doğru çekerek bir miktar dış rotasyonla reverse fly yapın. Bunu yaparken avuç içleriniz öne bakmalıdır.", "Hattaki gevşekliği almak için birkaç adım geriye giderek başlangıç pozisyonuna dönün."]', 'strength', '["Sled_Reverse_Flye/0.jpg", "Sled_Reverse_Flye/1.jpg"]', 360.0, 'Sled Reverse Flye', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('695a25a7-2b98-5b30-a1ff-dfb3dd2237d9', 'free-exercise-db', 'Sled_Row', 'Kızak Row', 'pull', 'beginner', 'compound', '["other"]', '["middle back"]', '["biceps", "lats"]', '["Halat veya zincirle bağlı bir kızağa çift tutacak takın. Kızağı uygun bir ağırlıkla yükleyin. Kızağa dönük durun ve hatta biraz gerginlik oluşana kadar geriye gidin.", "Her elinizde bir tutaçla dizlerinizi hafifçe bükün, başınızı ve göğsünüzü yukarıda tutun ve kollarınız uzamış halde başlayın.", "Harekete başlamak için kürek kemiklerinizi geriye çekerken dirseğinizi bükerek kızağı kendinize doğru çekin.", "Hatta gerginlik sağlamak için bir veya iki adım geriye gidin ve tekrarlayın."]', 'strength', '["Sled_Row/0.jpg", "Sled_Row/1.jpg"]', 360.0, 'Sled Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1e4b65b6-e4c9-5a0d-a047-f40a12a4f595', 'free-exercise-db', 'Sledgehammer_Swings', 'Sledgehammer Swing (Balyoz)', 'pull', 'beginner', 'compound', '["other"]', '["abdominals"]', '["calves", "forearms", "lats", "middle back", "shoulders"]', '["Bu egzersiz için bir lastiğe ve bir balyoza ihtiyacınız olacak. Lastiğin önünde, ondan yaklaşık 60 cm uzakta, kademeli bir duruşla durun. Balyozu kavrayın.", "Sağ elini kullanıyorsanız, sol eliniz sapın alt kısmında, sağ eliniz ise başa daha yakın şekilde tutmalıdır.", "Balyozu yukarı kaldırırken sağ eliniz başa doğru kayar; aşağı savururken sağ eliniz sol elinize katılmak üzere aşağı kayar. Balyozu lastiğe olabildiğince sert vurun. Balyozun lastikten sekmesini kontrol edin.", "Diğer tarafta tekrarlayın."]', 'plyometrics', '["Sledgehammer_Swings/0.jpg", "Sledgehammer_Swings/1.jpg"]', 480.0, 'Sledgehammer Swings', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b8ad9706-4432-5837-90d0-c60e77d10b07', 'free-exercise-db', 'Smith_Incline_Shoulder_Raise', 'Incline Omuz Raise (Smith Makinesi)', 'push', 'beginner', 'isolation', '["barbell"]', '["shoulders"]', '["chest"]', '["Smith makinesinin altına eğimli bir bank yerleştirin. Barı, uzandığınızda ve kollarınız neredeyse tamamen uzatılmışken ulaşabileceğiniz bir yüksekliğe ayarlayın. İhtiyacınız olan ağırlık seçildikten sonra eğimli bankta uzanın ve omuzlarınızın tam olarak barın altında hizalandığından emin olun.", "Omuz genişliğinde pronated (avuç içi öne) tutuşla barı raftan çıkarın ve dirsekleriniz hafif bükülü şekilde tam üzerinizde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken kollarınız tamamen uzayana kadar barı yukarı kaldırın. Not: Kasılma omuz çevresinde hissedilmelidir.", "Bir saniye bekledikten sonra nefes alırken barı başlangıç pozisyonuna indirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde barı rafa geri yerleştirin."]', 'strength', '["Smith_Incline_Shoulder_Raise/0.jpg", "Smith_Incline_Shoulder_Raise/1.jpg"]', 360.0, 'Smith Incline Shoulder Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('32e9b93c-3cfe-5bce-a334-6af33daa03b0', 'free-exercise-db', 'Smith_Machine_Behind_the_Back_Shrug', 'Arkadan Shrug (Smith Makinesi)', 'pull', 'beginner', 'isolation', '["machine"]', '["traps"]', '["shoulders"]', '["Bar uyluk seviyesindeyken uygun ağırlığı yükleyin.", "Bar arkanızda olacak şekilde durun, bara omuz genişliğinde pronasyon tutuşla tutunun ve ağırlığı kancadan çıkarın. Başınız ve göğsünüz yukarıda, kollarınız uzanmış şekilde dik durmalısınız. Bu sizin başlangıç pozisyonunuzdur.", "Omuzlarınızı düz yukarı silkerek harekete başlayın. Hareket sırasında kollarınızı veya bileklerinizi bükmeyin.", "Kısa bir beklemeden sonra ağırlığı başlangıç pozisyonuna geri getirin.", "Ağırlığı rafa koymak için kancaları devreye sokmadan önce istenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Behind_the_Back_Shrug/0.jpg", "Smith_Machine_Behind_the_Back_Shrug/1.jpg"]', 360.0, 'Smith Machine Behind the Back Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('de9c11dc-06d6-5070-9dc9-7213a83dfb7c', 'free-exercise-db', 'Smith_Machine_Bench_Press', 'Bench Press (Smith Makinesi)', 'push', 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Smith makinesinin altına düz bir bench yerleştirin. Şimdi halteri, uzandığınızda ve kollarınız neredeyse tamamen uzanmışken ulaşabileceğiniz bir yüksekliğe getirin. İhtiyacınız olan ağırlık seçildikten sonra düz bench''e uzanın. Omuz genişliğinden daha geniş bir pronasyon tutuşla barın kilidini raftan açın ve kollarınız kilitli şekilde tam üzerinizde tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes alırken barı orta göğsünüzde hissedene kadar yavaşça inin.", "Bir saniyelik duraklamadan sonra, nefes verirken göğüs kaslarınızı kullanarak barı iterek başlangıç pozisyonuna geri getirin. Kollarınızı kasılmış pozisyonda kilitleyin, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İniş, çıkıştan en az iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde barı rafa geri kilitleyin."]', 'strength', '["Smith_Machine_Bench_Press/0.jpg", "Smith_Machine_Bench_Press/1.jpg"]', 360.0, 'Smith Machine Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0098c65b-e473-5e61-996c-a4a8c477e4b4', 'free-exercise-db', 'Smith_Machine_Bent_Over_Row', 'Öne Eğilerek Row (Smith Makinesi)', 'pull', 'beginner', 'compound', '["machine"]', '["middle back"]', '["biceps", "lats", "shoulders"]', '["Smith makinesine bağlı barı dizlerinizin yaklaşık 5 cm altına gelecek bir yüksekliğe ayarlayın.", "Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak belden eğilip gövdenizi yere neredeyse paralel olana kadar öne getirin. İpucu: Başınızı yukarıda tuttuğunuzdan emin olun.", "Şimdi barı üsten (pronasyon) bir tutuşla kavrayın ve Smith makinesi rafından kilidini açın. Ardından kollarınız yere ve gövdenize dik olarak uzamış halde sarkarken barın tam önünüzde asılı kalmasına izin verin. Bu sizin başlangıç pozisyonunuzdur.", "Gövdenizi sabit tutarak, nefes verirken barı kaldırın; dirseklerinizi vücudunuza yakın tutun ve ön kolla ağırlığı tutmaktan başka kuvvet uygulamayın. Üst kasılma noktasında sırt kaslarınızı sıkın ve bir saniye bekleyin.", "Nefes alırken ağırlığı yavaşça tekrar başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Bent_Over_Row/0.jpg", "Smith_Machine_Bent_Over_Row/1.jpg"]', 360.0, 'Smith Machine Bent Over Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('07b30472-f02c-5f57-b31e-468a3cd63d6f', 'free-exercise-db', 'Smith_Machine_Calf_Raise', 'Calf Raise (Smith Makinesi)', 'push', 'beginner', 'isolation', '["machine"]', '["calves"]', '[]', '["Smith makinesinde barın altına bir blok veya ağırlık plakası yerleştirin. Barı boyunuza en uygun konuma ayarlayın. Doğru yükseklik seçilip bar yüklendikten sonra ayaklarınızın ön tabanlarıyla plakaların üzerine çıkın ve barı omuzlarınızın arkasına yerleştirin.", "Barı iki elinizle öne bakacak şekilde tutun. Barı rafından çıkarmak için döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Ayaklarınızın ön tabanından iterek topuklarınızı olabildiğince yukarı kaldırın ve kasılmanın üst noktasında baldırınızı sıkın. Dizleriniz uzamış kalmalıdır. Aşağı inmeye başlamadan önce kasılmış pozisyonu bir saniye tutun.", "Topuklarınızı indirirken nefes alarak yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Calf_Raise/0.jpg", "Smith_Machine_Calf_Raise/1.jpg"]', 360.0, 'Smith Machine Calf Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('726b72cf-f836-52f3-b95e-968da96ac301', 'free-exercise-db', 'Smith_Machine_Close-Grip_Bench_Press', 'Dar Tutuşlu Bench Press (Smith Makinesi)', 'push', 'beginner', 'compound', '["machine"]', '["triceps"]', '["chest", "shoulders"]', '["Düz bir bench''i Smith makinesinin altına yerleştirin. Barı, uzandığınızda ve kollarınız neredeyse tamamen uzatıldığında ulaşabileceğiniz bir yüksekliğe yerleştirin. İhtiyacınız olan ağırlık seçildikten sonra düz bench''e uzanın. Omuz genişliğinde dar ve pronasyon tutuşla (avuç içleri öne bakacak şekilde) barın kilidini açın ve kollarınız kilitli halde üzerinizde düz tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes alırken barı orta göğsünüzde hissedene kadar yavaşça indirin. İpucu: Normal bench press''ten farklı olarak, triceps''in devreye girmesini maksimuma çıkarmak için dirseklerinizi her zaman gövdenize yakın tuttuğunuzdan emin olun.", "Bir saniye bekledikten sonra, nefes vererek ve barı triceps kaslarınızla iterek başlangıç pozisyonuna getirin. Kasılmış pozisyonda kollarınızı kilitleyin, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: Aşağı inmek en az yukarı çıkmanın iki katı kadar sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Bitirdiğinizde barı tekrar rack''e kilitleyin."]', 'strength', '["Smith_Machine_Close-Grip_Bench_Press/0.jpg", "Smith_Machine_Close-Grip_Bench_Press/1.jpg"]', 360.0, 'Smith Machine Close-Grip Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('367e0606-da41-574e-a66a-8df6d5f4f097', 'free-exercise-db', 'Smith_Machine_Decline_Press', 'Decline Press (Smith Makinesi) – Smith Machine Decline Press', NULL, 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Bir decline sehpayı rafın içine, bar göğsünüzün üzerinde olacak şekilde yerleştirin. Uygun ağırlığı yükleyin ve sehpaya yerleşin.", "Barı kancadan çıkarmak için döndürün ve kollarınızı tamamen uzatın. Sırtınız hafif kavisli, kürek kemikleriniz geriye çekilmiş olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Kollarınızı bükerek ve barı göğsünüze indirerek harekete başlayın.", "Kısa bir süre bekleyin ve ardından ağırlığı başlangıç pozisyonuna geri itmek için kollarınızı açın.", "İstenen tekrar sayısını tamamladıktan sonra ağırlığı rafa koymak için barı döndürün."]', 'strength', '["Smith_Machine_Decline_Press/0.jpg", "Smith_Machine_Decline_Press/1.jpg"]', 360.0, 'Smith Machine Decline Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('caa03cfb-d425-5e91-8c10-6f9883b7b96e', 'free-exercise-db', 'Smith_Machine_Hang_Power_Clean', 'Hang Power Clean (Smith Makinesi)', 'pull', 'intermediate', 'compound', '["machine"]', '["hamstrings"]', '["glutes", "lower back", "quadriceps", "shoulders", "traps"]', '["Barı diz yüksekliğine yerleştirin ve uygun bir ağırlıkla yükleyin.", "Barı omuz genişliğinin dışında pronated tutuşla kavrayın ve barı makineden çıkarın. Kollarınız tamamen uzamış, başınız ve göğsünüz yukarıda olmalıdır. Dirsekleriniz dışa dönük, omuzlarınız geride ve aşağıda olmalıdır. Kalçanız geride olmalı ve gerginliği arka bacak kaslarına yüklemelidir. Bu sizin başlangıç pozisyonunuzdur.", "Kalça ve dizlerinizi güçlü şekilde açarak, bara doğru hızlanarak hareketi başlatın. Hareketin bu kısmında kollarınızı düz tuttuğunuzdan emin olun.", "Tam açılma sağlandığında, karşılama pozisyonunuzu alçaltmak için kalça ve dizlerinizi yeniden bükün.", "Bu noktada kolların bükülmesine izin verin, barı omuzlarınızda karşılamak için dirsekleri barın etrafında döndürün.", "Hareketi tamamlamak için kalça ve dizlerinizi açarak bar omuzlarınızda olacak şekilde ayakta duruş pozisyonuna gelin."]', 'strength', '["Smith_Machine_Hang_Power_Clean/0.jpg", "Smith_Machine_Hang_Power_Clean/1.jpg"]', 360.0, 'Smith Machine Hang Power Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('54096411-b92c-5a3d-b2e2-3d278a2f1d40', 'free-exercise-db', 'Smith_Machine_Hip_Raise', 'Kalça Kaldırma (Smith Makinesi)', 'pull', 'beginner', 'isolation', '["machine"]', '["abdominals"]', '[]', '["Bir bench''i rafın içine yerleştirin ve barı uygun bir ağırlıkla yükleyin. Bench''e uzanın, ayak tabanlarınızı bara dayayın. Barın kilidini açın ve bacaklarınızı uzatın. Size yardımcı olması için ellerinizi kullanmanız gerekebilir. Ek denge için Smith makinesinin yanlarını kavrayın. Bu sizin başlangıç pozisyonunuz olacak.", "Pelvisinizi döndürerek ve omurganızı bükerek kalçanızı bench''ten kaldırarak harekete başlayın. Hareket boyunca dizlerde hafif bir bükülme sürdürün.", "Kısa bir duraklamadan sonra kalçanızı bench''e geri indirin.", "İstenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Hip_Raise/0.jpg", "Smith_Machine_Hip_Raise/1.jpg"]', 360.0, 'Smith Machine Hip Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ea8de754-6be7-5d54-97c9-f4e60507b28a', 'free-exercise-db', 'Smith_Machine_Incline_Bench_Press', 'Incline Bench Press (Smith Makinesi)', 'push', 'beginner', 'compound', '["machine"]', '["chest"]', '["shoulders", "triceps"]', '["Smith makinesinin altına bir incline sehpa yerleştirin. Halteri, uzanırken ve kollarınız neredeyse tamamen açıkken ulaşabileceğiniz bir yüksekliğe yerleştirin. İhtiyacınız olan ağırlık seçildikten sonra incline sehpaya uzanın ve üst göğsünüzün halterle hizalı olduğundan emin olun. Omuz genişliğinden daha geniş üstten tutuşla (avuç içleri öne bakacak şekilde) barın kilidini açın ve kollarınız kilitli şekilde tam tepenizde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken barı üst göğsünüzde hissedene kadar yavaşça inin.", "Bir saniyelik duraklamanın ardından nefes verirken göğüs kaslarınızı kullanarak barı iterek başlangıç pozisyonuna geri getirin. Kollarınızı kasılmış pozisyonda kilitleyin, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İnmek, çıkmaktan en az iki kat uzun sürmelidir.", "Hareketi belirtilen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde barı rafa geri yerleştirin."]', 'strength', '["Smith_Machine_Incline_Bench_Press/0.jpg", "Smith_Machine_Incline_Bench_Press/1.jpg"]', 360.0, 'Smith Machine Incline Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('83d712e3-ead5-546f-bdd9-6f9ce0575594', 'free-exercise-db', 'Smith_Machine_Leg_Press', 'Leg Press (Smith Makinesi)', 'push', 'intermediate', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bir Smith makinesi barını yerden birkaç ayak yüksekliğe yerleştirin. Güvenlik duraklarının üzerinde durduğundan emin olun. Barı uygun ağırlıkla yükledikten sonra barın altına uzanın. Ayaklarınızın ortasını bara koyun ve dizlerinizi göğsünüze doğru çekin. Bu sizin başlangıç pozisyonunuzdur.", "Kalçanızı ve dizlerinizi açarak barı yukarı hareket ettirmek için ayaklarınızla iterek harekete başlayın. Dizlerinizi kilitlemeyin.", "Hareketin tepesinde başlangıç pozisyonuna dönmeden önce kısa bir süre bekleyin."]', 'strength', '["Smith_Machine_Leg_Press/0.jpg", "Smith_Machine_Leg_Press/1.jpg"]', 360.0, 'Smith Machine Leg Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('85e7b6ec-39cd-5d25-abb8-3bcd3de224a2', 'free-exercise-db', 'Smith_Machine_One-Arm_Upright_Row', 'Tek Kol Upright Row (Smith Makinesi)', 'pull', 'beginner', 'compound', '["machine"]', '["shoulders"]', '["biceps", "traps"]', '["Bar uyluk seviyesindeyken uygun bir ağırlık yükleyin.", "Barı geniş bir tutuşla kavrayın ve ağırlığı kancadan çıkarın, diğer elinizi bardan çekin. Kolunuz uzamış, başınız ve göğsünüz yukarıda dik durmalısınız. Bu sizin başlangıç pozisyonunuz olacaktır.", "Dirseğinizi bükerek, dirsek dışarı bakacak şekilde üst kolunuzu kaldırarak harekete başlayın. Üst kolunuz yere paralel olana kadar devam edin.", "Kısa bir duraklamanın ardından ağırlığı başlangıç pozisyonuna döndürün.", "Ağırlığı rafa asmak için kancaları devreye sokmadan önce istenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_One-Arm_Upright_Row/0.jpg", "Smith_Machine_One-Arm_Upright_Row/1.jpg"]', 360.0, 'Smith Machine One-Arm Upright Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9a806e41-af3e-550b-968a-539b68e1a496', 'free-exercise-db', 'Smith_Machine_Overhead_Shoulder_Press', 'Shoulder Press (Smith Makinesi)', 'push', 'beginner', 'compound', '["machine"]', '["shoulders"]', '["triceps"]', '["Başlamak için düz bir bench''i (veya tercihen sırt destekli olanı) Smith makinesinin altına yerleştirin. Barı, düz bench''e oturduğunuzda bara ulaşmak için kolların neredeyse tamamen uzatılması gereken bir yüksekliğe konumlandırın.", "Doğru yüksekliği ayarladıktan sonra, burun ucunuzdan bara hayali bir düz çizgi oluşacak şekilde barın biraz gerisine oturun. Ayaklarınız sabit olmalıdır. Barı avuç içleri öne bakacak şekilde kavrayın, kilidini açın ve kollarınız tamamen uzayana kadar yukarı kaldırın. Bu başlangıç pozisyonudur.", "Nefes alırken barı çenenizle aynı seviyeye gelene kadar yavaşça indirmeye başlayın.", "Ardından nefes vererek omuzlarınızı kullanarak barı başlangıç pozisyonuna geri kaldırın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Overhead_Shoulder_Press/0.jpg", "Smith_Machine_Overhead_Shoulder_Press/1.jpg"]', 360.0, 'Smith Machine Overhead Shoulder Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ff2a5bf5-0c6b-5ef7-8601-4dbb7eb0b7d9', 'free-exercise-db', 'Smith_Machine_Pistol_Squat', 'Pistol Squat (Smith Makinesi)', 'push', 'intermediate', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için önce barı boyunuza en uygun konuma ayarlayın. Altına girin ve barı omuzlarınızın arkasına yerleştirin.", "Barı avuç içleriniz ileri bakacak şekilde tutun, kilidini açın ve bacaklarınızı açarak raftan kaldırın.", "Bir ayağınızı barın yaklaşık 30 cm önüne doğru hareket ettirin. Diğer bacağınızı önünüze uzatın ve yerden havada tutun. Her zaman ileri bakın ve omurganızı nötr veya hafifçe kavisli tutun. Bu sizin başlangıç pozisyonunuz olacak.", "İyi bir duruşu koruyarak, diz ve kalçayı bükerek esneklik izin verdiği kadar aşağı inerek kendinizi alçaltın.", "Altta kısa bir süre duraklayın, ardından ayağınızın topuğundan iterek, diz ve kalçayı açarak başlangıç pozisyonuna dönün."]', 'strength', '["Smith_Machine_Pistol_Squat/0.jpg", "Smith_Machine_Pistol_Squat/1.jpg"]', 360.0, 'Smith Machine Pistol Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ff1fc2a9-ce70-5cb4-b390-acd1425032e0', 'free-exercise-db', 'Smith_Machine_Reverse_Calf_Raises', 'Ters Calf Raise (Smith Makinesi)', 'push', 'beginner', 'isolation', '["machine"]', '["calves"]', '[]', '["Smith makinesindeki barı boyunuza göre ayarlayın ve yükseltilmiş bir platformu tam barın altına hizalayın.", "Platformun üzerinde, topuklarınız üzerinde sabit ve ayak ön kısımlarınız platformdan dışarıda kalacak şekilde durun. Ayak parmaklarınızı öne dönük ve omuz genişliğinde bir duruşla konumlandırın.", "Şimdi tarif edilen ayak pozisyonunu koruyarak omuzlarınızı barın altına yerleştirin ve gövdeniz dik duruncaya kadar kalça ve dizlerinizi açarak barı yukarı itin. Dizler hafif bükülü tutulmalı, asla kilitlenmemelidir. Bu sizin başlangıç pozisyonunuzdur. İpucu: Sırtınızdaki halter yalnızca denge amaçlıdır.", "Nefes verirken ayak parmaklarınızı olabildiğince yukarı uzatarak ve baldırınızı kasarak ayağınızın ön kısmını kaldırın. Dizin her zaman sabit kaldığından emin olun. Herhangi bir anda bükülme olmamalıdır. Aşağı inmeye başlamadan önce kasılmış pozisyonu bir saniye tutun.", "Nefes alırken ayağınızın ön kısmını ve ayak parmaklarınızı indirerek yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Reverse_Calf_Raises/0.jpg", "Smith_Machine_Reverse_Calf_Raises/1.jpg"]', 360.0, 'Smith Machine Reverse Calf Raises', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('af611126-5ab6-5130-9730-d5af34171075', 'free-exercise-db', 'Smith_Machine_Squat', 'Squat (Smith Makinesi)', 'push', 'beginner', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Başlamak için önce barı boyunuza en uygun yüksekliğe ayarlayın. Doğru yüksekliği seçip barı yükledikten sonra barın altına girin ve omuzlarınızın arka kısmını (boynun biraz altında) barın üzerine yerleştirin.", "Barı her iki kolunuzla yanlardan (avuç içleri öne bakacak şekilde) kavrayın, kilidini açın ve önce bacaklarınızla iterek, aynı anda gövdenizi doğrultarak barı raftan kaldırın.", "Bacaklarınızı omuz genişliğinde orta bir duruşla, ayak parmakları hafifçe dışa bakacak şekilde konumlandırın. Başınızı her zaman yukarıda tutun ve sırtınızı da düz tutun. Bu sizin başlangıç pozisyonunuzdur. (Not: Bu anlatım için genel gelişimi hedefleyen orta duruşu kullanacağız; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik iken dizlerinizi bükerek barı yavaşça indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz küçük oluncaya kadar (üst bacakların yere paralelin altında olduğu nokta) inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız dizlerinizin ön kısmı, ayak parmaklarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizgiyi geçerse (ayak parmaklarınızı geçerse) dize gereksiz yük bindiriyorsunuz ve egzersizi yanlış yapıyorsunuz demektir.", "Topuğunuzla yeri iterek bacaklarınızı tekrar düzleştirirken nefes verip barı kaldırmaya başlayın ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Squat/0.jpg", "Smith_Machine_Squat/1.jpg"]', 360.0, 'Smith Machine Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('cc082d89-1b00-5fcf-848d-32922425740b', 'free-exercise-db', 'Smith_Machine_Stiff-Legged_Deadlift', 'Stiff-Leg Deadlift (Smith Makinesi)', 'pull', 'beginner', 'compound', '["machine"]', '["hamstrings"]', '["glutes", "lower back"]', '["Başlamak için Smith makinesindeki barı uyluklarınızın ortası civarında bir yüksekliğe ayarlayın. Doğru yükseklik seçilip bar yüklendikten sonra, barı omuz genişliğinde pronasyon (avuç içleri öne bakan) tutuşla kavrayın. Önemli miktarda ağırlık kullanıyorsanız bilek sargılarına ihtiyacınız olabilir.", "Sırtınızı düz tutarak kollarınızı tamamen uzatıp barı kaldırın. Gövdeniz dik, bacaklarınız omuz genişliğinde veya daha dar bir duruşta açık şekilde durun. Dizler hafifçe bükülü olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi sabit tutarak, sırtınızı düz tutup belden eğilerek halteri ayaklarınızın üzerine kadar indirin. Yerden bir şey alacakmışsınız gibi arka bacak kaslarınızda bir gerilme hissedene kadar öne doğru gitmeye devam edin. Bu hareketi yaparken nefes verin.", "Arka bacak kaslarınızda gerilme hissettiğiniz anda kalçanızı ve belinizi açarak gövdenizi tekrar dik şekilde yukarı getirmeye başlayın ve başlangıç pozisyonuna dönün. Bu hareketi yaparken nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Stiff-Legged_Deadlift/0.jpg", "Smith_Machine_Stiff-Legged_Deadlift/1.jpg"]', 360.0, 'Smith Machine Stiff-Legged Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c7815b80-0c9a-56e1-b2e4-11b7c679f705', 'free-exercise-db', 'Smith_Machine_Upright_Row', 'Upright Row (Smith Makinesi)', 'pull', 'beginner', 'compound', '["machine"]', '["traps"]', '["biceps", "middle back", "shoulders"]', '["Başlamak için Smith makinesindeki barı yaklaşık uyluklarınızın ortası hizasında bir yüksekliğe ayarlayın. Doğru yükseklik seçilip bar yüklendikten sonra barı omuz genişliğinde, pronasyon (avuç içleri öne) tutuşla kavrayın. Önemli miktarda ağırlık kullanıyorsanız bilek bandajına ihtiyacınız olabilir.", "Halteri kaldırın ve sırtınız düz şekilde kollarınızı tamamen uzatın. Dirseklerde hafif bir bükülme olmalıdır. Bu başlangıç pozisyonudur.", "Nefes verirken yan omuz kaslarınızı kullanarak barı kaldırın. Barı yukarı hareket ettirirken vücuda yakın olmalıdır. Neredeyse çenenize değene kadar kaldırmaya devam edin. İpucu: Hareketi dirsekleriniz yönlendirmelidir. Barı kaldırırken dirsekleriniz her zaman ön kollarınızdan daha yüksekte olmalıdır. Ayrıca gövdenizi sabit tutun ve hareketin üst noktasında bir saniye bekleyin.", "Barı yavaşça başlangıç pozisyonuna geri indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Smith_Machine_Upright_Row/0.jpg", "Smith_Machine_Upright_Row/1.jpg"]', 360.0, 'Smith Machine Upright Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('944fa1d6-1b19-5bc7-9a96-e6fef4d3991d', 'free-exercise-db', 'Smith_Single-Leg_Split_Squat', 'Tek Bacak Split Squat (Smith Makinesi)', 'push', 'beginner', 'compound', '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için düz bir bench''i Smith makinesinin 60-90 cm arkasına yerleştirin. Ardından barı boyunuza en uygun yüksekliğe ayarlayın. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve barı omuzlarınızın arkasına (boynun biraz altına) yerleştirin.", "Barı her iki kolunuzla iki yandan (avuç içleri öne bakacak şekilde) kavrayın, kilidini açın ve önce bacaklarınızla iterek, aynı anda gövdenizi dikleştirerek rack''ten kaldırın.", "Bacaklarınızı konumlandırın: bir ayağınızı barın altında biraz öne yerleştirin, diğer bacağınızı geriye uzatın ve ayağınızın üst kısmını bench''in üzerine koyun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başınız yukarıda ve duruşunuz dik kalacak şekilde dizinizi bükerek barı yavaşça indirmeye başlayın. Üst bacak ile baldır arasındaki açı 90 dereceden biraz az olana kadar (üst bacakların yere paralelin altına indiği nokta) inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız, dizinizin ön kısmı ayak parmaklarınızla öne doğru dik bir hayali düz çizgi oluşturmalıdır. Diziniz bu hayali çizgiyi geçerse (ayak parmaklarınızı geçerse), dizinize gereksiz stres bindirirsiniz ve egzersiz yanlış yapılmış demektir.", "Nefes vererek, esas olarak ayağınızın topuğu ile yere basarak bacağınızı tekrar düzeltirken ve başlangıç pozisyonuna dönerken barı kaldırmaya başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bacak değiştirin ve hareketi tekrarlayın."]', 'strength', '["Smith_Single-Leg_Split_Squat/0.jpg", "Smith_Single-Leg_Split_Squat/1.jpg"]', 360.0, 'Smith Single-Leg Split Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e1901f26-2259-51e1-adcc-fb358d84ead2', 'free-exercise-db', 'Snatch', 'Snatch (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["biceps", "glutes", "hamstrings", "lower back", "shoulders", "traps", "triceps"]', '["Ayaklarınızı omuz genişliğinde bir duruşa yerleştirin; halter, ayak parmaklarının ayağın geri kalanıyla birleştiği noktanın hemen üzerinde dursun.", "Avuç içleri aşağı bakan bir tutuşla, dizlerinizi bükün ve sırtınızı düz tutarak halteri omuz genişliğinden geniş bir tutuşla kavrayın. Kalçanızı aşağı indirin ve vücudunuzun sanki bir sandalyeye oturacakmış gibi alçaldığından emin olun. Bu sizin başlangıç pozisyonunuz olacak.", "Ayaklarınızla yeri sanki hareketli bir platformmuş gibi itmeye başlayın ve aynı anda halteri bacaklarınıza yakın tutarak kaldırmaya başlayın.", "Bar uyluklarınızın ortasına geldiğinde, bacaklarınızla yeri itin ve vücudunuzu patlayıcı bir hareketle tam açılmaya kadar kaldırın.", "Barı yukarı getirirken omuzlarınızı şrag hareketiyle geriye kaldırın; aynı anda dirseklerinizi yana doğru kaldırın ve mümkün olduğunca uzun süre barın üzerinde tutun.", "Şimdi çok hızlı ama güçlü bir hareketle, bar kontrol edilebilecek yeterince yüksek bir noktaya ulaştığında vücudunuzu halterin altına sokmanız, kollarınızı kilitlerken çömelme pozisyonuna geçerek ve halteri baş üstünde tutarak aşağı inmeniz gerekir.", "Kaldırışı tamamlamak için çömelme pozisyonundan kalkarak hareketi bitirin. Kaldırışın sonunda her iki ayak aynı hizada ve kollar halteri baş üstünde tutarak tamamen uzanmış olmalıdır."]', 'olympic weightlifting', '["Snatch/0.jpg", "Snatch/1.jpg"]', 420.0, 'Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8f899d00-be19-5f20-8372-2d11529c028a', 'free-exercise-db', 'Snatch_Balance', 'Snatch Balance (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "shoulders", "triceps"]', '["Ayaklar çekiş pozisyonunda, bar omuzların arkasında rafta ve eller geniş snatch tutuşunda olacak şekilde başlayın.", "Ani bir çökme ve dizlerle itişle barı fırlatın ve agresif şekilde barın altına girin; ayakları karşılama pozisyonuna geçirin.", "Barı baş üstünde kilitli halde squat''ın alt noktasına yakın bir yerde karşılayın. Gövde dik kalmalı, kalça bacakların arasına doğru alçalmalıdır.", "Tam derinliğe kadar inmeye devam edin ve ayakta duruş pozisyonuna dönün. Ağırlığı dikkatlice indirin."]', 'olympic weightlifting', '["Snatch_Balance/0.jpg", "Snatch_Balance/1.jpg"]', 420.0, 'Snatch Balance', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('24275f18-0d12-56f5-9949-4683ae10c8f9', 'free-exercise-db', 'Snatch_Deadlift', 'Snatch Deadlift (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["forearms", "glutes", "hamstrings", "lower back", "quadriceps", "traps"]', '["Snatch deadlift, snatch''in ilk çekişini güçlendirir. Halter platform üzerindeyken geniş bir snatch tutuşuyla başlayın. Ayaklar tam kalçaların altında ve dışa dönük olmalıdır. Sırtınız tamamen düz ve başınız ileri bakarken bara doğru çömelin.", "Topuklarınızdan iterek ve kalçanızı kaldırarak harekete başlayın. Bar dizleri geçene kadar sırt açısı aynı kalmalıdır.", "Bu noktada, geriye yaslanırken kalçanızı bara doğru sürün. Hareketi tersine çevirerek barı platforma geri bırakın."]', 'olympic weightlifting', '["Snatch_Deadlift/0.jpg", "Snatch_Deadlift/1.jpg"]', 420.0, 'Snatch Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9e93f8ee-fc8a-5bdb-893f-bafed6294acd', 'free-exercise-db', 'Snatch_Pull', 'Snatch Pull (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["calves", "glutes", "lower back", "quadriceps", "traps"]', '["Halter yerde, kaval kemiklerinize yakınken geniş snatch tutuşunu alın. Ağırlığı topuklarınıza vererek, sırtınız düz, başınız ileri bakacak, göğsünüz yukarıda ve omuzlarınız halterin hemen önünde olacak şekilde kalçanızı indirin. Bu sizin başlangıç pozisyonunuzdur.", "Topuklarınızla iterek ve dizlerinizi açarak ilk çekişe başlayın. Sırt açınız aynı kalmalı ve kollarınız düz kalmalıdır. Dizlerin üstüne kadar devam ederken ağırlığı kontrollü hareket ettirin.", "Sırada, çekişin ana ivmelenme kaynağı olan ikinci çekiş gelir. Halter uyluğun ortasına yaklaşırken kalçanızı açmaya başlayın. Sıçrama hareketiyle kalçanızı, dizlerinizi ve ayak bileklerinizi açarak hızlanın ve halteri yukarı taşımak için hızı kullanın.", "Ağırlığı hızlandırmak için kollarla aktif olarak çekmeye gerek olmamalıdır; ikinci çekişin sonunda vücut tamamen açılmış ve hafifçe geriye yaslanmış olmalıdır. Tam açılma sert ve ani olmalıdır ve açılmayı gerekenden daha uzun süre uzatmadığınızdan emin olun."]', 'strength', '["Snatch_Pull/0.jpg", "Snatch_Pull/1.jpg"]', 360.0, 'Snatch Pull', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4639b3a0-9880-5bb7-9c16-05272a7b2d2b', 'free-exercise-db', 'Snatch_Shrug', 'Snatch Shrug (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["traps"]', '["forearms", "shoulders"]', '["Geniş bir tutuşla, bar orta uyluk hizasında asılı olacak şekilde başlayın. Hook veya üstten (overhand) tutuş kullanabilirsiniz. Sırtınız düz ve hafifçe öne eğimli olmalıdır.", "Omuzlarınızı kulaklarınıza doğru silkin. Bu egzersiz genellikle snatch''ten daha ağır bir ağırlıkla yapılabilse de, uygulamanın yavaşlayacağı kadar aşırı yüklemekten kaçının."]', 'olympic weightlifting', '["Snatch_Shrug/0.jpg", "Snatch_Shrug/1.jpg"]', 420.0, 'Snatch Shrug', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('061987aa-4336-5c80-aae8-86001dc553b0', 'free-exercise-db', 'Snatch_from_Blocks', 'Blok Üzerinden Snatch (Halter)', 'pull', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "forearms", "glutes", "hamstrings", "lower back", "shoulders", "traps", "triceps"]', '["Yüklenmiş bir halteri istenen yükseklikteki kutular ya da standlar üzerinde başlayın. Barı geniş bir tutuşla kavrayın. Ayaklar kalçanın tam altında olmalı, gerekirse dışa dönük olmalıdır. Göğsünüz yukarıda ve başınız ileri bakar şekilde kalçanızı alçaltın. Omuzlar barın hemen önünde, dirsekler dışa dönük olmalıdır. Bu başlangıç pozisyonu olacaktır.", "Ayak topuklarınızın ön kısmıyla iterek barı kutulardan kaldırarak ilk çekişi başlatın.", "Kalçanızı, dizlerinizi ve ayak bileklerinizi açarak ikinci çekişe geçin ve barı olabildiğince hızlı yukarı sürün. Bar vücuda yakın olmalıdır. Maksimum açılma anında omuzlarınızı silkin ve dirseklerin yana doğru bükülmesine izin verin.", "Ayaklarınızı karşılama pozisyonuna taşırken, barı başınızın üzerine yükseltirken kendinizi barın altına kuvvetle çekin. Ayaklar kalçanın hemen dışına, gerektiği kadar dışa dönük şekilde hareket etmelidir. Barı vücudunuz olabildiğince alçakta ve kollar başın üzerinde tamamen uzanmış halde karşılayın.", "Barı ayak topuklarının önü hizasında tutarak, başınız ve göğsünüz yukarıda olacak şekilde, ayakta durma pozisyonuna geçmek için ayak topuklarınızdan itin. Ağırlığı dikkatlice kutulara geri bırakın."]', 'olympic weightlifting', '["Snatch_from_Blocks/0.jpg", "Snatch_from_Blocks/1.jpg"]', 420.0, 'Snatch from Blocks', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('bded679d-6f48-5101-96f0-6e710734edfc', 'free-exercise-db', 'Speed_Band_Overhead_Triceps', 'Baş Üstü Triceps Extension (Hız Bandı)', 'push', 'beginner', 'isolation', '["bands"]', '["triceps"]', '[]', '["Bu egzersiz için bir bandı yere sabitleyin. Biz bir incline bench kullandık ve bandı tabana sabitleyip bench''in üzerinde durduk. Alternatif olarak bandın üzerinde durarak da yapılabilir.", "Başlamak için bandı başınızın arkasına çekin; pronasyon tutuşla tutun ve dirseklerinizi yukarıda tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Hareketi gerçekleştirmek için üst kolunuzu yerinde tuttuğunuzdan emin olarak dirseğinizi açıp kollarınızı düzeltin.", "Duraklayın ve ardından başlangıç pozisyonuna dönün."]', 'strength', '["Speed_Band_Overhead_Triceps/0.jpg", "Speed_Band_Overhead_Triceps/1.jpg"]', 360.0, 'Speed Band Overhead Triceps', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8b1797e8-c3ec-547a-a13c-385bb79099c5', 'free-exercise-db', 'Speed_Box_Squat', 'Speed Box Squat (Bantlı, Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Yere yakın bir yere sağlam şekilde sabitlenmiş bantları bara bağlayın. Yeterli gerginlik sağlamak için bantları kısaltmanız gerekebilir.", "Bu egzersiz için uygun yükseklikte bir kutu kullanın. Barı hâlâ çaba gerektiren ancak hızı bozacak kadar ağır olmayan bir ağırlıkla yükleyin. Genellikle bu, tek tekrar maksimumunuzun (1RM) %50-70''i arasında olacaktır.", "Barı üst sırtınıza yerleştirin; kürek kemikleri geride, sırt kavisli ve baştan ayağa her şey sıkı olsun. Bu başlangıç pozisyonu olacaktır.", "Barı raftan çıkarın ve kutunun önünde konumlanın. Kutunun üzerine oturana kadar kalçanızı geriye oturtun; kontrollü indiğinizden ve yüzeye çarpmadığınızdan emin olun.", "Kısa süre bekleyin ve kalça ve dizlerinizi açarak kutudan patlayıcı şekilde kalkın."]', 'powerlifting', '["Speed_Box_Squat/0.jpg", "Speed_Box_Squat/1.jpg"]', 360.0, 'Speed Box Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fafad9d6-c365-5a48-9a44-926022a3f77d', 'free-exercise-db', 'Speed_Squats', 'Hızlı Squat (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Bu egzersiz güvenlik amacıyla en iyi squat rack içinde yapılır. Başlamak için önce barı boyunuza en uygun rafa yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve omuzlarınızın arkasını (boynun biraz altında) barın üzerine yerleştirin.", "Barı iki kolunuzla iki yandan tutun ve önce bacaklarınızla iterek ve aynı anda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşla, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Aşağı bakmak dengenizi bozacağı için başınızı her zaman yukarıda tutun ve ayrıca sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuz olacak. (Not: Bu anlatımda genel gelişimi hedefleyen orta duruş kullanılacaktır; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik şekilde dizlerinizi bükerek barı indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz az olana kadar inmeye devam edin (üst bacakların yere paralelin altında olduğu nokta). Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız, dizlerinizin ön kısmı ayak parmaklarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizginin ötesine geçiyorsa (ayak parmaklarınızı aşıyorsa) dizlere gereksiz yük bindiriyorsunuz demektir ve egzersiz yanlış yapılmıştır.", "Nefes verirken, ivme kullanmadan olabildiğince hızlı bir şekilde, esas olarak ayağınızın topuğuyla yeri iterek ve bacaklarınızı tekrar düzelterek barı kaldırmaya ve başlangıç pozisyonuna dönmeye başlayın. Not: Bu egzersizleri mükemmel formu bozmadan ve ivme kullanmadan olabildiğince hızlı yapmalısınız.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Speed_Squats/0.jpg", "Speed_Squats/1.jpg"]', 360.0, 'Speed Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3e693de4-4e59-53de-9196-e0ebcec86e3a', 'free-exercise-db', 'Spell_Caster', 'Spell Caster (Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["abdominals"]', '["glutes", "shoulders"]', '["Her elinizde pronasyon tutuşla bir dambıl tutun. Ayaklarınız geniş açık, kalçanız ve dizleriniz uzatılmış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Gövdenizi döndürerek her iki dambılı kalçanızın yanında bir tarafa doğru çekerek harekete başlayın.", "Kollarınızı düz ve dambılları yere paralel tutarak, ağırlıkları karşı tarafa savurmak için gövdenizi döndürün.", "Set tamamlanana kadar bir taraftan diğerine dönerek dönüşümlü olarak devam edin."]', 'strength', '["Spell_Caster/0.jpg", "Spell_Caster/1.jpg"]', 360.0, 'Spell Caster', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('78c27a7c-2bf5-5a6d-afa9-037ce5003eae', 'free-exercise-db', 'Spider_Crawl', 'Spider Crawl (Örümcek Yürüyüşü)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '["chest", "shoulders", "triceps"]', '["Yerde yüzüstü pozisyonda başlayın. Ağırlığınızı ellerinizle ve ayak parmaklarınızla destekleyin; ayaklarınız bitişik ve vücudunuz düz olsun. Kollarınız 90 derece bükülü olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Bir ayağınızı yerden kaldırarak harekete başlayın. Bacağı dışa doğru döndürün ve dizinizi dirseğinize doğru mümkün olduğunca ileri getirin.", "Bu bacağı başlangıç pozisyonuna döndürün ve karşı tarafta tekrarlayın."]', 'strength', '["Spider_Crawl/0.jpg", "Spider_Crawl/1.jpg"]', 360.0, 'Spider Crawl', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e40cb0d6-118e-59c6-b8bb-a7aca6ac3c11', 'free-exercise-db', 'Spider_Curl', 'Spider Curl (Halter)', 'pull', 'beginner', 'isolation', '["e-z curl bar"]', '["biceps"]', '[]', '["Halteri preacher sehpasının normalde oturduğunuz kısmına yerleştirerek başlayın. Halteri dengeli olacak ve düşmeyecek şekilde düzgün hizaladığınızdan emin olun.", "Preacher sehpasının ön tarafına (kolların genellikle yattığı kısma) geçin ve gövdeniz ile karnınız preacher sehpasının ön tarafına bastırılmış şekilde 45 derecelik bir eğimle uzanacak şekilde konumlanın.", "Ayaklarınızın (özellikle ayak parmaklarınızın) yerde iyi konumlandığından emin olun ve üst kollarınızı preacher sehpasının iç kısmında bulunan pedin üzerine yerleştirin.", "Kollarınızı kullanarak halteri supinasyon tutuşla (avuç içleri yukarı bakacak şekilde) yaklaşık omuz genişliğinde veya biraz daha dar kavrayın.", "Nefes verirken halteri yavaşça yukarı kaldırmaya başlayın. Biceps''i sıkarak kasılmış pozisyonda bir saniye bekleyin.", "Nefes alırken halteri yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Spider_Curl/0.jpg", "Spider_Curl/1.jpg"]', 360.0, 'Spider Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('725dc729-9463-592f-a089-81fb32bc4f81', 'free-exercise-db', 'Spinal_Stretch', 'Omurga Esnetme', 'static', 'beginner', 'isolation', '[]', '["middle back"]', '["lats", "lower back", "neck", "traps"]', '["Sırtınız düz ve ayaklarınız yere basacak şekilde bir sandalyeye oturun.", "Parmaklarınızı başınızın arkasında kenetleyin; dirsekleriniz dışarıda ve çeneniz aşağıda olsun.", "Üst vücudunuzu yaklaşık 3 kez gidebildiğiniz kadar bir yana döndürün. Ardından öne eğilin ve dirseğinizi dizinizin iç tarafında yere ulaştırmak için gövdenizi döndürün.", "Dik pozisyona dönün ve ardından diğer taraf için tekrarlayın."]', 'stretching', '["Spinal_Stretch/0.jpg", "Spinal_Stretch/1.jpg"]', 150.0, 'Spinal Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('306432e2-a9c4-59f1-8bc7-f9adc8943d3c', 'free-exercise-db', 'Split_Clean', 'Split Clean (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "forearms", "glutes", "hamstrings", "lower back", "shoulders", "traps"]', '["Halter yerde kaval kemiklerinize yakınken, bacakların hemen dışından üstten (overhand) tutuşla kavrayın. Ağırlık topuklarda yoğunlaşmış, sırt düz, baş öne dönük, göğüs yukarıda ve omuzlar barın hemen önünde olacak şekilde kalçanızı alçaltın. Bu sizin başlangıç pozisyonunuzdur.", "Topuklarınızdan iterek ve dizlerinizi açarak ilk çekişe başlayın. Sırt açınız aynı kalmalı ve kollarınız düz kalmalıdır. Dizlerin üzerine kadar devam ederken ağırlığı kontrollü hareket ettirin.", "Sonra clean için ana ivme kaynağı olan ikinci çekiş gelir. Bar orta uyluk pozisyonuna yaklaşırken kalçanızı açmaya başlayın. Zıplama hareketiyle kalça, diz ve bileklerinizi açarak hızlanın, barı yukarı hareket ettirmek için hızı kullanın. Ağırlığı hızlandırmak için kolları aktif olarak çekmeye gerek olmamalıdır; ikinci çekişin sonunda vücut tamamen açılmış, hafifçe geriye eğik ve kollar hâlâ uzatılmış olmalıdır.", "Tam açılma sağlandığında, dirsekler yukarı ve dışa doğru olacak şekilde güçlü bir shrug ve kol bükme ile üçüncü çekişe geçin. Maksimum açılma noktasında kendinizi güçlü şekilde aşağı çekin ve bunu yaparken dirseklerinizi barın altına doğru döndürün.", "Barı ayaklar ayrık şekilde karşılayın; bir ayağı güçlü şekilde öne, bir ayağı arkaya hareket ettirin. Bar, öne uzatılmış omuzların üzerine yerleşmeli, eller gevşek şekilde boğaza hafifçe değmelidir. Toparlanmaya yardımcı olacak alt pozisyona kadar inmeye devam edin.", "Topuklarınızdan iterek, gövdenizi dik ve dirseklerinizi yukarıda tutarak hemen toparlanın. Ayağa kalkarken ayaklarınızı birleştirin."]', 'olympic weightlifting', '["Split_Clean/0.jpg", "Split_Clean/1.jpg"]', 420.0, 'Split Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b4a0a732-3645-5567-a7f9-67c686b3cbb6', 'free-exercise-db', 'Split_Jerk', 'Split Jerk (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["glutes", "hamstrings", "shoulders", "triceps"]', '["Ağırlık omuzların önünde rafta dururken ayakta durarak dip (çömelme) ile başlayın. Ayaklarınız tam kalçalarınızın altındayken, kalçanızı geriye hareket ettirmeden dizlerinizi bükün.", "Yalnızca hafifçe aşağı inin ve mümkün olduğunca güçlü bir şekilde yön değiştirin. Mümkün olduğunca fazla hız ve kuvvet oluşturmak için topuklarınızdan itin ve bar omuzlardan ayrılırken başınızı yoldan çektiğinizden emin olun. Ayaklar yerden ayrıldığı bu anda, ayaklar mümkün olduğunca çabuk karşılama pozisyonuna yerleştirilmelidir.", "Ayakların platforma karşı aktif olarak itmediği kısa anda, sporcunun barı yukarı itme çabası onları aşağı sürecektir. Ayaklar, bir ayak önde bir ayak arkada ve dizler kısmen bükülü olacak şekilde split duruşa getirilmelidir. Barı kollar başın üzerinde kilitli halde karşılayın.", "Ayaklarınızı bir araya getirerek ayakta duruş pozisyonuna dönün."]', 'olympic weightlifting', '["Split_Jerk/0.jpg", "Split_Jerk/1.jpg"]', 420.0, 'Split Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1ddfc0e1-dabd-52f8-8cf5-0f471e365cc6', 'free-exercise-db', 'Split_Jump', 'Split Jump', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bir ayak önde ve dizi bükülü, arkadaki diz neredeyse yere değecek şekilde lunge duruşu alın.", "Ön dizin ayağın orta çizgisinin üzerinde olduğundan emin olun.", "Her iki bacağınızı da açarak, yükselmek için kollarınızı savurup olabildiğince yükseğe zıplayın.", "Zıplarken ayaklarınızı birleştirin ve inerken tekrar ilk pozisyonlarına getirin.", "Başlangıç pozisyonuna dönerek darbeyi sönümleyin."]', 'plyometrics', '["Split_Jump/0.jpg", "Split_Jump/1.jpg"]', 480.0, 'Split Jump', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('040b2c7f-dd30-584c-8cf6-7861dc524db4', 'free-exercise-db', 'Split_Snatch', 'Split Snatch (Halter)', 'pull', 'expert', 'compound', '["barbell"]', '["hamstrings"]', '["calves", "forearms", "glutes", "hamstrings", "lower back", "quadriceps", "shoulders", "traps", "triceps"]', '["Yerde yüklü bir halterle başlayın. Bar kaval kemiklerine yakın veya değiyor olmalı ve bara geniş bir tutuşla tutunulmalıdır. Ayaklar kalçanın tam altında olmalı ve gerekirse dışa dönük olmalıdır. Göğsünüz yukarıda ve başınız ileriye bakacak şekilde kalçanızı alçaltın. Omuzlarınız barın hemen önünde olmalıdır. Bu başlangıç pozisyonu olacaktır.", "Topuklarınızın ön kısmından iterek barı yerden kaldırarak ilk çekişe başlayın. Bar dizleri geçene kadar sırt açısı aynı kalmalıdır.", "Kalçanızı, dizlerinizi ve ayak bileklerinizi açarak ikinci çekişe geçin ve barı olabildiğince hızlı bir şekilde yukarı sürün. Bar vücuda yakın olmalıdır. Tam açılmanın zirvesinde omuzlarınızı silkin ve dirseklerinizin yana doğru bükülmesine izin verin.", "Ayaklarınızı karşılama pozisyonuna getirirken barı başınızın üzerine kaldırırken kendinizi kuvvetle barın altına çekin. Ayaklar güçlü bir şekilde split pozisyonuna, yani bir ayak önde bir ayak arkada olacak şekilde hareket etmelidir. Barı vücudunuz olabildiğince alçakta ve kollarınız başınızın üzerinde tamamen uzatılmış halde karşılayın.", "Barı ayakların ön topuklarının hizasında tutarak, başınız ve göğsünüz yukarıda, topuklarınızdan iterek ayakta duruş pozisyonuna geçin ve ayaklarınızı birleştirin.", "Ağırlığı dikkatlice yere geri indirin."]', 'olympic weightlifting', '["Split_Snatch/0.jpg", "Split_Snatch/1.jpg"]', 420.0, 'Split Snatch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f681999c-b823-5c87-8836-1295dc6ca419', 'free-exercise-db', 'Split_Squat_with_Dumbbells', 'Split Squat (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Arka ayak yükseltilmiş ve ön ayak ileride olacak şekilde kademeli bir duruş alın.", "Her elinizde bir dambıl tutun ve yanlarınızda sarkmasına izin verin. Bu sizin başlangıç pozisyonunuzdur.", "Dizinizi ve kalçanızı bükerek vücudunuzu aşağı indirerek inmeye başlayın. Hareket boyunca iyi bir duruşu koruyun. Egzersizi yaparken ön dizi ayakla aynı hizada tutun.", "Hareketin en altında başlangıç pozisyonuna dönmek için topuğunuzdan iterek diz ve kalçayı açın."]', 'strength', '["Split_Squat_with_Dumbbells/0.jpg", "Split_Squat_with_Dumbbells/1.jpg"]', 360.0, 'Split Squat with Dumbbells', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1fc4f462-9f18-5f5f-92a0-13405e2d8262', 'free-exercise-db', 'Split_Squats', 'Split Squat Sıçraması', 'push', 'intermediate', NULL, '[]', '["hamstrings"]', '["calves", "glutes", "quadriceps"]', '["Ayakta durma pozisyonunda başlayın. Bir bacak önde, bir bacak arkada split bacak pozisyonuna sıçrayın; bunu yaparken dizlerinizi bükün ve kalçanızı hafifçe indirin.", "İnerken hemen yön değiştirin, tekrar ayağa kalkın ve bacaklarınızın pozisyonunu değiştirerek sıçrayın. Her bacakta 5-10 kez tekrarlayın."]', 'stretching', '["Split_Squats/0.jpg", "Split_Squats/1.jpg"]', 150.0, 'Split Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f3b1dd5d-e93e-5609-9433-a1e39d5fa924', 'free-exercise-db', 'Squat_Jerk', 'Squat Jerk (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "shoulders", "triceps"]', '["Ağırlık omuzların önünde rafta dururken ayakta durarak dip (çömelme) ile başlayın. Ayaklarınız tam kalçalarınızın altındayken, kalçanızı geriye hareket ettirmeden dizlerinizi bükün. Yalnızca hafifçe aşağı inin ve mümkün olduğunca güçlü bir şekilde yön değiştirin. Mümkün olduğunca fazla hız ve kuvvet oluşturmak için topuklarınızdan itin ve bar omuzlardan ayrılırken başınızı yoldan çektiğinizden emin olun.", "Ayaklar yerden ayrıldığı bu anda, ayaklar mümkün olduğunca çabuk karşılama pozisyonuna yerleştirilmelidir. Ayakların platforma karşı aktif olarak itmediği kısa anda, sporcunun barı yukarı itme çabası onları aşağı sürecektir. Ayaklar, gerektiği kadar dışa dönük olarak kalçaların hemen dışına güçlü bir şekilde hareket etmelidir. Barı vücudunuz tam squat pozisyonunda ve kollarınız başınızın üzerinde tamamen uzamış halde karşılayın.", "Barı topukların ön kısmının üzerinde hizalı tutarak, başınız ve göğsünüz yukarıdayken, ayakta duruş pozisyonuna geçmek için ayaklarınızın topuklarından itin. Ağırlığı dikkatlice yere geri bırakın."]', 'strength', '["Squat_Jerk/0.jpg", "Squat_Jerk/1.jpg"]', 360.0, 'Squat Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('455b6ce5-3386-56fe-990e-cc61cbf0222e', 'free-exercise-db', 'Squat_with_Bands', 'Squat (Halter, Direnç Bandı)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["adductors", "calves", "glutes", "hamstrings", "lower back"]', '["Bantları halterin kollarına takın ve uygun gerginlik sağlanacak şekilde bant çivilerine, rafa veya dambıllara sabitleyin.", "Halterin altına girip halteri omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine doğru sıkın ve halteri omuzlarınızın üzerinde bükmeye çalışır gibi dirseklerinizi öne doğru döndürün. Halteri raftan çıkarırken belinizde sıkı bir kavis oluşturun ve geriye adım atarak pozisyon alın. Sırt, kalça, iç bacak ve arka bacağa daha fazla vurgu için ayaklarınızı geniş yerleştirin. Başınızı ileri bakacak şekilde tutun.", "Sırtınız, omuzlarınız ve karın bölgeniz sıkıyken dizlerinizi ve kalçanızı dışarı doğru iterek inişe başlayın. Kalçanızla olabildiğince geriye oturun. İdeal olarak kaval kemiklerinizin yere dik olması gerekir. Halter pozisyonu ne kadar alçaksa halteri topukların üzerinde tutmak için gövdeyi o kadar fazla öne eğmek gerekir. Kalça kıvrımının dizin üst kısmıyla aynı hizada olması olarak tanımlanan paralelin altına inene kadar devam edin.", "Ağırlığı topuklarınızda tutup ayaklarınızı ve dizlerinizi dışarı iterek hareketi başınızla yönlendirerek yukarı doğru çıkın. Baştan ayağa sıkılığı koruyarak başlangıç pozisyonuna dönene kadar yükselmeye devam edin."]', 'powerlifting', '["Squat_with_Bands/0.jpg", "Squat_with_Bands/1.jpg"]', 360.0, 'Squat with Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('70334845-646e-578d-8938-72862eb2eb67', 'free-exercise-db', 'Squat_with_Chains', 'Zincirli Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["adductors", "calves", "glutes", "hamstrings", "lower back"]', '["Zincirleri kurmak için ana zinciri barın kollarının üzerinden geçirerek başlayın. Ağır zincir bir çıtçıtlı kanca ile bağlanmalıdır. Ana zincirin uzunluğunu, hareketin tepesinde birkaç halka hâlâ yerde kalacak şekilde ayarlayın.", "Barın altına girip barı omuzlarınızın arkasına yerleştirerek başlayın. Kürek kemiklerinizi birbirine doğru sıkın ve dirseklerinizi öne doğru döndürerek barı omuzlarınızın üzerinde bükmeye çalışın. Barı raftan çıkarın, belinizde sıkı bir kavis oluşturun ve geriye adım atarak pozisyon alın. Sırt, kalça, addüktör ve arka bacak kaslarına daha fazla vurgu için ayaklarınızı geniş yerleştirin. Başınızı karşıya dönük tutun.", "Sırtınız, omuzlarınız ve karın bölgeniz sıkı iken dizlerinizi ve kalçanızı dışarı doğru iterek inişe başlayın. Kalçanızla mümkün olduğunca geriye oturun. İdeal olarak baldırlarınız yere dik olmalıdır. Daha alçak bar pozisyonu, barı topukların üzerinde tutmak için gövdenin daha fazla öne eğilmesini gerektirir. Kalça kıvrımı dizin üst kısmıyla aynı hizaya gelerek paralelin altına geçene kadar devam edin.", "Ağırlığı topuklarınızda tutup ayaklarınızı ve dizlerinizi dışarı iterek, hareketi başınızla yönlendirirken yukarı doğru itin. Başlangıç pozisyonuna dönene kadar baştan ayağa sıkılığı koruyarak yukarı çıkmaya devam edin."]', 'powerlifting', '["Squat_with_Chains/0.jpg", "Squat_with_Chains/1.jpg"]', 360.0, 'Squat with Chains', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ce51460d-14b3-5bd6-822d-6fde38e2ed24', 'free-exercise-db', 'Squat_with_Plate_Movers', 'Plate Mover Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Başlamak için önce barı rafa omuz seviyesinin hemen altına yerleştirin. Bir ağırlık plakasını yere, raftan birkaç adım geriye koyun. Bar yüklendikten sonra altına girin ve omuzlarınızın arkasını barın üzerine yerleştirin.", "Barı iki elinizle tutun ve önce bacaklarınızla iterek ve aynı anda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bir ayağınız ağırlık plakasının üzerinde, ayak uçları hafifçe dışa bakacak şekilde geniş bir duruş alın. Başınızı her zaman yukarıda tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Dizlerinizi ve kalçanızı bükerek barı yavaşça indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz az olana kadar inmeye devam edin.", "Nefes verirken kalça ve dizlerinizi açarken ayaklarınızın topuklarıyla yeri iterek barı kaldırın.", "Hareketin üst noktasında yana adım atın, ayaklarınızı plakanın karşı tarafında birleştirin.", "İç ayağınızı kullanarak ağırlık plakasını yerde, az önce durduğunuz yere doğru kaydırarak itin.", "Bir sonraki tekrar için iç ayağınızı ağırlık plakasının üzerine koyun ve geniş bir duruş alın."]', 'strength', '["Squat_with_Plate_Movers/0.jpg", "Squat_with_Plate_Movers/1.jpg"]', 360.0, 'Squat with Plate Movers', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3db50904-c47a-5271-b616-ae5eb7c6990f', 'free-exercise-db', 'Squats_-_With_Bands', 'Squat (Direnç Bandı)', 'push', 'beginner', 'compound', '["bands"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Başlamak için egzersiz bandının vücudun sol ve sağ tarafı arasında eşit bir şekilde bölündüğünden emin olun. Bunu yapmak için ellerinizle bandın iki yanını kavrayın ve ayaklarınızı bandın ortasına yerleştirin. Ayaklarınız birbirinden omuz genişliğinde açık olmalıdır.", "Bandları tutarken her iki tarafta da aynı yükseklikte olmalıdır. Bu egzersiz için pronasyon tutuş (avuç içleri öne bakacak şekilde) kullanmalı ve bantların tutamaklarını yüzünüzün yanında tutmalısınız. Bu başlangıç pozisyonudur.", "Nefes verirken dizlerinizi bükmeye ve bacaklarınızı uyluklarınız yere paralel olacak şekilde alçaltmaya yavaşça başlayın.", "Nefes verirken vücudunuzu başlangıç pozisyonuna itmek için ayaklarınızın topuklarını kullanın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Squats_-_With_Bands/0.jpg", "Squats_-_With_Bands/1.jpg"]', 360.0, 'Squats - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7e839562-6d9a-5014-8897-13b31f330543', 'free-exercise-db', 'Stairmaster', 'Stairmaster (Merdiven Makinesi)', NULL, 'intermediate', NULL, '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için stairmaster''a çıkın ve menüden istediğiniz seçeneği seçin. Manuel ayarı seçebilir veya çalıştırılacak bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kaloriyi tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz.", "Bacaklarınızı belirli bir ritimle aşağı yukarı hareket ettirin, pedalları aşağı doğru itin ancak tamamen yere kadar indirmeyin. Düşmemek için saplardan tutunmaya devam etmeniz önerilir. Saplar, uygun bir yoğunlukta kalmanıza yardımcı olmak için kalp atış hızınızı izlemekte kullanılabilir.", "Stairmaster''lar kolaylık, kardiyovasküler faydalar sunar ve genellikle dışarıda koşmaktan daha az darbe oluşturur. Genellikle diğer kardiyo aletlerinden çok daha zorlayıcıdır. 150 lb (yaklaşık 68 kg) ağırlığındaki bir kişi 30 dakikada genellikle 300 kaloriden fazla yakarken, yürüyüşte yaklaşık 175 kalori yakar."]', 'cardio', '["Stairmaster/0.jpg", "Stairmaster/1.jpg"]', 600.0, 'Stairmaster', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b1cdea91-e69e-542c-aa06-2e1c021d15dd', 'free-exercise-db', 'Standing_Alternating_Dumbbell_Press', 'Ayakta Alternatif Omuz Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Her elinizde bir dambıl olacak şekilde ayakta durun. Dambılları avuç içleriniz öne bakacak ve dirsekleriniz dışarı bakacak şekilde omuzlarınıza kaldırın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Diğer elinizi yerinde tutarak, dambılı dümdüz yukarı itmek için bir kolunuzu açın. Hareket sırasında eğilmeyin veya ağırlığı sallamayın.", "Kısa bir duraklamanın ardından ağırlığı başlangıç pozisyonuna döndürün.", "Karşı tarafta tekrarlayın ve kollar arasında dönüşümlü olarak devam edin."]', 'strength', '["Standing_Alternating_Dumbbell_Press/0.jpg", "Standing_Alternating_Dumbbell_Press/1.jpg"]', 360.0, 'Standing Alternating Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1cc472a8-43b0-57ef-adf9-579f34ac7655', 'free-exercise-db', 'Standing_Barbell_Calf_Raise', 'Ayakta Calf Raise (Halter)', 'push', 'beginner', 'isolation', '["barbell"]', '["calves"]', '[]', '["Bu egzersizi güvenlik açısından bir squat rafı içinde yapmak en iyisidir. Başlamak için önce halteri boyunuza en uygun rafa ayarlayın. Doğru yükseklik seçilip halter yüklendikten sonra halterin altına girin ve halteri omuzlarınızın arkasına (boynun biraz altına) yerleştirin.", "Halteri her iki kolunuzla yanlardan tutun ve önce bacaklarınızla iterek, aynı anda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşla, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Başınızı her zaman yukarıda tutun, çünkü aşağı bakmak dengenizi bozar; sırtınızı da düz tutun. Dizler hafif bükülü tutulmalı, asla kilitlenmemelidir. Bu sizin başlangıç pozisyonunuzdur. İpucu: Daha iyi hareket açıklığı için ayaklarınızın ön tabanlarını ahşap bir bloğa da yerleştirebilirsiniz, ancak bu seçenek daha fazla denge ve sağlam bir blok gerektirdiği için dikkatli olun.", "Nefes verirken ayak bileklerinizi olabildiğince yukarı açarak topuklarınızı kaldırın ve baldırınızı sıkın. Dizin her zaman sabit kaldığından emin olun. Hiçbir zaman bükülme olmamalıdır. Aşağı inmeye başlamadan önce kasılmış pozisyonu bir saniye tutun.", "Nefes alırken topuklarınızı indirerek ve ayak bileklerinizi bükerek baldırlar gerilene kadar yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Barbell_Calf_Raise/0.jpg", "Standing_Barbell_Calf_Raise/1.jpg"]', 360.0, 'Standing Barbell Calf Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('80870de4-ad49-5d76-ad9f-fd48b25726fc', 'free-exercise-db', 'Standing_Barbell_Press_Behind_Neck', 'Ayakta Ense Arkası Press (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["shoulders"]', '["triceps"]', '["Bu egzersiz, barı daha kolay almak için en iyi squat rafının içinde yapılır. Başlamak için önce barı boyunuza en uygun yükseklikteki rafa yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve omuzlarınızın arkasını (boynun biraz altında) barın üzerine yerleştirin.", "Barı her iki kolunuzla yanlardan tutun ve önce bacaklarınızla iterek, aynı zamanda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşta, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Bu egzersizi yaparken sırtınızı düz tutmalısınız. Bu sizin başlangıç pozisyonunuz olacaktır.", "Nefes verirken kollarınızı tamamen açarak halteri başınızın üzerine kaldırın.", "Kasılmayı bir saniye tutun ve nefes alarak halteri başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Barbell_Press_Behind_Neck/0.jpg", "Standing_Barbell_Press_Behind_Neck/1.jpg"]', 360.0, 'Standing Barbell Press Behind Neck', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('95e04eee-65d9-5440-a095-ebeb1c74cd45', 'free-exercise-db', 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'Ayakta Eğilerek Tek Kol Triceps Extension (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '["shoulders"]', '["Bir elinizde dambıl ve avuç içiniz gövdenize bakacak şekilde, dizlerinizi hafifçe bükün ve belinizden eğilerek sırtınızı düz tutarak gövdenizi yere neredeyse paralel olana kadar öne getirin. Başınızı yukarıda tuttuğunuzdan emin olun.", "Üst kol gövdeye yakın ve yere paralel olmalı, ön kol ise el ağırlığı tutarken yere doğru bakmalıdır. İpucu: Ön kol ile üst kol arasında 90 derecelik bir açı olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı sabit tutarak, nefes verirken ön kollar yere paralel olana ve tüm kol uzayana kadar triceps''i kullanarak ağırlıkları kaldırın. Diğer birçok kol egzersizinde olduğu gibi, sadece ön kol hareket eder.", "Üst noktada bir saniyelik kasılmadan sonra, nefes alırken dambılı yavaşça başlangıç pozisyonuna indirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın.", "Kolunuzu değiştirin ve egzersizi tekrarlayın."]', 'strength', '["Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg", "Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0271b532-4d6c-5f5f-bf86-79fd2b10e723', 'free-exercise-db', 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'Öne Eğilerek Triceps Kickback (Dambıl, İki Kol)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Her elinizde bir dambıl ve avuç içleriniz gövdenize bakacak şekilde, dizlerinizi hafifçe bükün ve sırtınızı düz tutarak belinizden eğilerek gövdenizi yere neredeyse paralel olana kadar öne getirin. Başınızı yukarıda tuttuğunuzdan emin olun. Üst kollar gövdeye yakın ve yere paralel olmalı, eller ağırlıkları tutarken ön kollar yere bakmalıdır. İpucu: Ön kollar ile üst kol arasında 90 derecelik bir açı olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarak, ön kollar yere paralel olana ve tüm kollar uzanana kadar nefes verirken triceps''i kullanarak ağırlıkları kaldırın. Diğer birçok kol egzersizinde olduğu gibi sadece ön kol hareket eder.", "Üstte bir saniyelik kasılmadan sonra nefes alırken dambılları yavaşça başlangıç pozisyonuna indirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg", "Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ee3d2901-353e-56d0-abe6-cd211a79357d', 'free-exercise-db', 'Standing_Biceps_Cable_Curl', 'Ayakta Biceps Curl (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["biceps"]', '[]', '["Alt makaraya bağlı bir kablo curl barını tutarak gövdeniz dik şekilde ayakta durun. Kablo barını omuz genişliğinde kavrayın ve dirseklerinizi gövdenize yakın tutun. Avuç içleriniz yukarı bakmalıdır (supinasyon tutuş). Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarak nefes verip biceps''inizi kasarak ağırlığı kıvırın. Yalnızca ön kollar hareket etmelidir. Biceps''leriniz tamamen kasılana ve bar omuz seviyesine gelene kadar hareketi sürdürün. Kası sıkarak kasılmış pozisyonu bir saniye tutun.", "Nefes alırken curl barını yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Biceps_Cable_Curl/0.jpg", "Standing_Biceps_Cable_Curl/1.jpg"]', 360.0, 'Standing Biceps Cable Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d1a3ef93-e934-5a83-ae3b-fb8fb92ea391', 'free-exercise-db', 'Standing_Biceps_Stretch', 'Ayakta Biceps Esnetme', 'static', 'beginner', 'isolation', '["other"]', '["biceps"]', '["chest", "shoulders"]', '["Ellerinizi arkanızda avuç içleri birbirine bakacak şekilde kenetleyin, kollarınızı düzleştirin ve ardından avuç içleriniz aşağı bakacak şekilde döndürün.", "Kollarınızı yukarı kaldırın ve biceps''inizde bir esneme hissedene kadar bekleyin."]', 'stretching', '["Standing_Biceps_Stretch/0.jpg", "Standing_Biceps_Stretch/1.jpg"]', 150.0, 'Standing Biceps Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('760f496a-54fc-54b1-93b9-14a836fd3ef3', 'free-exercise-db', 'Standing_Bradford_Press', 'Bradford Press (Halter, Ayakta)', 'push', 'beginner', 'compound', '["barbell"]', '["shoulders"]', '["triceps"]', '["Yüklü bir barı rafta omuz seviyesine yerleştirin. Omuz genişliğinde pronated tutuşla, bar omuzlarınızın önünde rafa yaslı şekilde başlayın. Bu sizin başlangıç pozisyonunuzdur.", "Barı baş üstüne itmek için dirseklerinizi açarak kaldırışı başlatın. Ağırlığı başınızın arkasına doğru hareket ettirirken dirseği kilitlemekten kaçının.", "Dirseğiniz dik açı oluşturana kadar barı başın arkasına doğru indirin.", "Dirseklerinizi açarak barı tekrar başınızın üzerine kaldırın.", "Barı başlangıç pozisyonuna indirin.", "Önerilen tekrar sayısını tamamlayana kadar bu şekilde dönüşümlü olarak devam edin."]', 'strength', '["Standing_Bradford_Press/0.jpg", "Standing_Bradford_Press/1.jpg"]', 360.0, 'Standing Bradford Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e01f8bad-a01a-570b-b94b-48c92f37d7a1', 'free-exercise-db', 'Standing_Cable_Chest_Press', 'Ayakta Chest Press (Kablo)', 'push', 'beginner', 'compound', '["cable"]', '["chest"]', '["shoulders", "triceps"]', '["Çift makaraları göğüs yüksekliğine getirin ve uygun ağırlığı seçin. Kabloların bir iki ayak önünde, her elinizde bir kablo tutarak durun. Daha iyi denge için duruşunuzu kademeli yapabilirsiniz (bir ayak önde).", "Üst kolu kürek kemikleriniz bir araya gelecek şekilde 90 derecelik açıya getirin. Bu sizin başlangıç pozisyonunuzdur.", "Vücudun geri kalanını sabit tutarak tutamakları öne doğru itmek için dirseklerinizi açın ve tutamakları önünüzde birleştirin.", "Hareketin tepesinde bekleyin ve başlangıç pozisyonuna dönün."]', 'strength', '["Standing_Cable_Chest_Press/0.jpg", "Standing_Cable_Chest_Press/1.jpg"]', 360.0, 'Standing Cable Chest Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('810b959a-7dbc-5afe-ac3f-d1c15edb0f43', 'free-exercise-db', 'Standing_Cable_Lift', 'Ayakta Cable Lift (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["abdominals"]', '["shoulders"]', '["Standart bir sapı bir kuleye bağlayın ve kabloyu en alçak makara pozisyonuna getirin.", "Yan tarafınız kabloya dönük şekilde sapı bir elinizle kavrayın ve kuleden uzaklaşın. Makaradan yaklaşık kol boyu uzaklıkta olmalı ve kabloda ağırlığın gerginliği bulunmalıdır. Uzattığınız kol kabloyla aynı hizada olmalıdır.", "Ayaklarınız omuz genişliğinde açıkken çömelin ve sapı iki elinizle kavrayın. Kollarınız hâlâ tamamen uzatılmış olmalıdır.", "Tek bir hareketle sapı yukarı ve vücudunuzun karşı tarafına doğru, kollarınız başınızın üzerinde tamamen uzatılmış pozisyona gelene kadar çekin.", "Tam hareket açıklığı elde etmek için sırtınızı düz ve kollarınızı vücudunuza yakın tutarken arka ayağınızı döndürün ve bacaklarınızı düzleştirin.", "Önce kollarınızı, sonra vücudunuzu geri getirin. Yavaş ve kontrollü bir şekilde nötr pozisyona dönün.", "Tükenene kadar tekrarlayın.", "Ardından pozisyonunuzu değiştirin ve aynı hareket dizisini karşı tarafta tekrarlayın."]', 'strength', '["Standing_Cable_Lift/0.jpg", "Standing_Cable_Lift/1.jpg"]', 360.0, 'Standing Cable Lift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('203e2caa-eb53-5fae-a438-2074bdf0c4ba', 'free-exercise-db', 'Standing_Cable_Wood_Chop', 'Wood Chop (Kablo)', 'pull', 'beginner', 'compound', '["cable"]', '["abdominals"]', '["shoulders"]', '["Standart bir tutacağı bir kuleye bağlayın ve kabloyu en yüksek makara pozisyonuna getirin.", "Yan tarafınız kabloya dönük olarak tutacağı bir elinizle kavrayın ve kuleden uzaklaşın. Makaradan yaklaşık kol boyu kadar uzakta olmalı ve kabloda ağırlığın gerginliği bulunmalıdır. Uzattığınız kol kabloyla aynı hizada olmalıdır.", "Ayaklarınız omuz genişliğinde açıkken diğer elinizle yukarı uzanın ve tutacağı iki elinizle kavrayın. Kollarınız hâlâ tamamen uzamış olmalıdır.", "Tek bir hareketle, gövdenizi döndürürken tutacağı aşağı ve vücudunuzun önünden çapraz olarak ön dizinize doğru çekin.", "Tam hareket açıklığı için arka ayağınızı çevirip dizlerinizi bükerken sırtınızı ve kollarınızı düz, karın bölgenizi sıkı tutun.", "Duruşunuzu ve düz kollarınızı koruyun. Yavaş ve kontrollü bir şekilde nötr pozisyona dönün.", "Tükenene kadar tekrarlayın.", "Ardından yerinizi değiştirin ve aynı hareket serisini karşı tarafta tekrarlayın."]', 'strength', '["Standing_Cable_Wood_Chop/0.jpg", "Standing_Cable_Wood_Chop/1.jpg"]', 360.0, 'Standing Cable Wood Chop', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4a00c180-de21-50c9-b5d2-cd3b533f4188', 'free-exercise-db', 'Standing_Calf_Raises', 'Ayakta Calf Raise (Makine)', 'push', 'beginner', 'isolation', '["machine"]', '["calves"]', '[]', '["Calf raise makinesinin minderli kolunu boyunuza göre ayarlayın.", "Omuzlarınızı sağlanan minderlerin altına yerleştirin ve ayak uçlarınızı ileri bakacak şekilde konumlandırın (veya bölümün başında anlatılan diğer iki konumdan birini kullanın). Ayaklarınızın ön kısmı calf bloğunun üzerinde sabitlenmeli ve topuklar bloğun dışına taşmalıdır. Kalçanızı ve dizlerinizi açarak, gövdeniz dik duruncaya kadar kolu yukarı itin. Dizler hafifçe bükülü tutulmalı; asla kilitlenmemelidir. Ayak uçları, bölümün başında anlatıldığı gibi ileri, dışa veya içe bakmalıdır. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken ayak bileklerinizi olabildiğince yukarı açarak topuklarınızı kaldırın ve baldır kasınızı kasın. Dizin her zaman sabit kaldığından emin olun. Hiçbir zaman bükülme olmamalıdır. Aşağı inmeye başlamadan önce kasılmış pozisyonu bir saniye tutun.", "Nefes alırken, baldırlar gerilene kadar ayak bileklerinizi bükerek topuklarınızı indirerek yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Calf_Raises/0.jpg", "Standing_Calf_Raises/1.jpg"]', 360.0, 'Standing Calf Raises', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a8a5fe16-1b67-5e3e-a774-a577952aa0d1', 'free-exercise-db', 'Standing_Concentration_Curl', 'Ayakta Concentration Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Çalışan elinize bir dambıl alın ve öne eğilin. Çalışan kolunuzun dirseği dışa bakacak şekilde yere dik sarkmasına izin verin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Üst kolunuzu sabit tutarak ağırlığı curl yapmak için dirseğinizi bükün. Tekrarın üst noktasında biceps''inizi kasın ve bekleyin.", "Dambılı başlangıç pozisyonuna geri indirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Concentration_Curl/0.jpg", "Standing_Concentration_Curl/1.jpg"]', 360.0, 'Standing Concentration Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4ffcd13a-939f-51f0-bc57-43b3f1480350', 'free-exercise-db', 'Standing_Dumbbell_Calf_Raise', 'Ayakta Calf Raise (Dambıl)', 'push', 'intermediate', 'isolation', '["dumbbell"]', '["calves"]', '[]', '["Gövdeniz dik şekilde, ellerinizde yanlarınızda iki dambıl tutarak ayakta durun. Ayağınızın ön tabanını sağlam ve dengeli bir ahşap tahtanın (yaklaşık 5-7 cm yüksekliğinde) üzerine yerleştirin; topuklarınız dışarıda kalıp yere değmelidir. Bu sizin başlangıç pozisyonunuzdur.", "Ayak uçları dümdüz (tüm bölgelere eşit çalışmak için), içe (dış başa vurgu için) veya dışa (iç başa vurgu için) bakarken nefes verirken baldırları kasarak topuklarınızı yerden kaldırın. Üst noktadaki kasılmayı bir saniye tutun.", "Nefes alırken topuklarınızı yavaşça indirerek başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Dumbbell_Calf_Raise/0.jpg", "Standing_Dumbbell_Calf_Raise/1.jpg"]', 360.0, 'Standing Dumbbell Calf Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0b80b352-4a5d-53d5-bfb4-0094a6cd20dc', 'free-exercise-db', 'Standing_Dumbbell_Press', 'Ayakta Shoulder Press (Dambıl)', 'push', 'beginner', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Ayaklarınız omuz genişliğinde açık olarak ayakta durun ve her elinize bir dambıl alın. Dambılları baş yüksekliğine kaldırın; dirsekler dışa dönük ve yaklaşık 90 derece olsun. Bu sizin başlangıç pozisyonunuzdur.", "Bacaklardan destek almadan veya geriye yaslanmadan, sıkı tekniği koruyarak ağırlıkları doğrudan başınızın üzerine birlikte kaldırmak için dirseklerinizi açın.", "Bekleyin ve ağırlığı yavaşça başlangıç pozisyonuna döndürün."]', 'strength', '["Standing_Dumbbell_Press/0.jpg", "Standing_Dumbbell_Press/1.jpg"]', 360.0, 'Standing Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9ebb63de-6c1f-51f9-b2f4-bf129d2661f7', 'free-exercise-db', 'Standing_Dumbbell_Reverse_Curl', 'Reverse Curl (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Başlamak için her elinizde pronasyon tutuşla (avuç içleri aşağı) bir dambıl tutarak dik durun. Kollarınız tamamen uzatılmış ve ayaklarınız birbirinden omuz genişliğinde açık olmalıdır. Bu başlangıç pozisyonudur.", "Üst kollarınızı sabit tutarak, nefes verirken biceps''inizi kasıp ağırlıkları curl yapın. Sadece ön kollar hareket etmelidir. Biceps''leriniz tamamen kasılana ve dambıllar omuz seviyesine gelene kadar hareketi sürdürün. Kası sıkarken kasılmış pozisyonda bir saniye bekleyin.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Dumbbell_Reverse_Curl/0.jpg", "Standing_Dumbbell_Reverse_Curl/1.jpg"]', 360.0, 'Standing Dumbbell Reverse Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('951bb4b3-687a-51dd-9546-80f3ff5e1c67', 'free-exercise-db', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'Ayakta Düz Kol Front Raise (Dambıl, Baş Üstü)', 'push', 'intermediate', 'isolation', '["dumbbell"]', '["shoulders"]', '[]', '["Dambılları uyluklarınızın önünde, avuç içleri uyluklarınıza bakacak şekilde tutun.", "Kollarınızı dirsekleriniz hafif bükülü şekilde düz tutun, ancak bu bükülmeyi kilitli tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken dambılları yarım daire hareketiyle başınızın üzerinde kol boyuna kadar kaldırın.", "Nefes alırken aynı yolu izleyerek yavaşça başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg", "Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/1.jpg"]', 360.0, 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('82e9cbd7-9188-5418-81d1-bc003058c7f9', 'free-exercise-db', 'Standing_Dumbbell_Triceps_Extension', 'Ayakta Triceps Extension (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Başlamak için bir dambılı iki elinizle tutarak ayakta durun. Ayaklarınız birbirinden yaklaşık omuz genişliğinde açık olmalıdır. Yavaşça iki elinizle dambılı kavrayın ve her iki kolunuz tamamen uzayana kadar başınızın üzerine kaldırın.", "Ağırlık avuç içlerinizde, başparmaklarınız çevresinde olacak şekilde durmalıdır. Avuç içleri tavana bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı başınıza yakın, dirsekleriniz içeride ve yere dik tutarak, ön kollarınız biceps''inize değene kadar ağırlığı başınızın arkasında yarım daire çizerek indirin. İpucu: Üst kollar sabit kalmalı ve yalnızca ön kollar hareket etmelidir. Bu adımı yaparken nefes alın.", "Dambılı kaldırmak için triceps''i kullanarak başlangıç pozisyonuna dönün. Bu adımı yaparken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Dumbbell_Triceps_Extension/0.jpg", "Standing_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'Standing Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('df8b5e43-cfa7-58dd-8fb1-755600e45d4e', 'free-exercise-db', 'Standing_Dumbbell_Upright_Row', 'Upright Row (Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["traps"]', '["biceps", "shoulders"]', '["Her elinizle, omuz genişliğinden biraz daha dar pronasyon (avuç içleri öne) tutuşla bir dambıl kavrayın. Dambıllar uyluklarınızın üzerinde durmalıdır. Kollarınız dirsekleri hafif bükülü şekilde uzamış ve sırtınız düz olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken yan omuz kaslarınızı kullanarak dambılları kaldırın. Dambıllar yukarı hareket ederken vücuda yakın olmalı ve hareketi dirsekler yönlendirmelidir. Neredeyse çenenize değene kadar kaldırmaya devam edin. İpucu: Hareketi dirsekleriniz yönlendirmelidir. Dambılları kaldırırken dirsekleriniz her zaman ön kollarınızdan daha yüksekte olmalıdır. Ayrıca gövdenizi sabit tutun ve hareketin üst noktasında bir saniye bekleyin.", "Dambılları yavaşça başlangıç pozisyonuna geri indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Dumbbell_Upright_Row/0.jpg", "Standing_Dumbbell_Upright_Row/1.jpg"]', 360.0, 'Standing Dumbbell Upright Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7afd2a69-2aba-5710-91a2-0553ea8db59a', 'free-exercise-db', 'Standing_Elevated_Quad_Stretch', 'Ayakta Yükseltilmiş Ön Bacak Esnetme', 'static', 'beginner', NULL, '["other"]', '["quadriceps"]', '[]', '["Sırtınız bir bench veya step''ten yaklaşık 60-90 cm uzakta olacak şekilde ayakta durarak başlayın.", "Bir bacağınızı arkanıza kaldırın ve ayağınızı step''e, ayak üstüne veya ayak ucuna (hangisi size daha rahat geliyorsa) yerleştirin.", "Destek aldığınız dizi hafifçe bükülü tutun ve o dizinin ayak parmaklarınızın ötesine geçmesine izin vermeyin. Taraf değiştirin."]', 'stretching', '["Standing_Elevated_Quad_Stretch/0.jpg", "Standing_Elevated_Quad_Stretch/1.jpg"]', 150.0, 'Standing Elevated Quad Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1e156d8e-d220-5945-9867-5343bf5af698', 'free-exercise-db', 'Standing_Front_Barbell_Raise_Over_Head', 'Ayakta Front Raise (Halter, Baş Üstü)', 'push', 'intermediate', 'isolation', '["barbell"]', '["shoulders"]', '[]', '["Başlamak için ellerinizde bir halterle dik durun. Barı avuç içleriniz aşağı bakacak ve ellerin birbirinden omuz genişliğinden daha dar aralıklı olduğu bir tutuşla kavramalısınız.", "Ayaklarınız omuz genişliğinde aralıklı olmalı. Dirsekleriniz hafifçe bükülü olmalı. Bu başlangıç pozisyonudur.", "Nefes verirken halteri doğrudan başınızın üzerine gelene kadar yukarı kaldırın. Her tekrarı yaparken dirseklerinizi hafifçe bükülü tuttuğunuzdan emin olun.", "Kasılmayı hissettiğinizde, nefes alırken halteri yavaşça başlangıç pozisyonuna indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Front_Barbell_Raise_Over_Head/0.jpg", "Standing_Front_Barbell_Raise_Over_Head/1.jpg"]', 360.0, 'Standing Front Barbell Raise Over Head', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('016f3d91-d5f6-59ac-9897-8bdf7f700daa', 'free-exercise-db', 'Standing_Gastrocnemius_Calf_Stretch', 'Ayakta Gastrocnemius Baldır Esnetme', 'static', 'beginner', NULL, '[]', '["calves"]', '["hamstrings"]', '["Sağ topuğunuzu dizinizi uzatarak bir basamağın üzerine yerleştirin ve sağ elinizle sağ ayak parmağınızı kavramak için öne eğilin. Sol dizinizin hafifçe bükülü ve sırtınızın düz olması gerekir.", "Ağırlığınızı sol bacağınızın üzerinde taşıyın ve sol elinizi sol uyluğunuza koyun.", "Baldırınızda bir esneme hissedene kadar sağ ayak parmaklarınızı dizinize doğru çekin."]', 'stretching', '["Standing_Gastrocnemius_Calf_Stretch/0.jpg", "Standing_Gastrocnemius_Calf_Stretch/1.jpg"]', 150.0, 'Standing Gastrocnemius Calf Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e99dbf83-b3be-51e9-912d-9af417849451', 'free-exercise-db', 'Standing_Hamstring_and_Calf_Stretch', 'Ayakta Arka Bacak ve Baldır Esnetme', 'static', 'beginner', NULL, '["other"]', '["hamstrings"]', '[]', '["Bir kemer, bant ya da ipi ayaklarınızdan birine dolayarak başlayın. Ayakta dururken o ayağınızı öne koyun.", "Öndeki bacağı düz tutarak arka bacağınızı bükün. Şimdi ön ayağınızın parmaklarını yerden kaldırın ve öne doğru eğilin.", "Kemeri kullanarak baldırdaki esnemeyi artırmak için ayağın üst kısmını çekin. 10-20 saniye bekleyin ve diğer ayakla tekrarlayın."]', 'stretching', '["Standing_Hamstring_and_Calf_Stretch/0.jpg", "Standing_Hamstring_and_Calf_Stretch/1.jpg"]', 150.0, 'Standing Hamstring and Calf Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b4fabac9-f627-5a9a-b4a4-943d812f06eb', 'free-exercise-db', 'Standing_Hip_Circles', 'Ayakta Kalça Daireleri', 'pull', 'beginner', 'isolation', '["body only"]', '["abductors"]', '["adductors"]', '["Dikey bir desteğe tutunarak tek bacak üzerinde durarak başlayın.", "Desteksiz dizinizi 90 dereceye kaldırın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kalçanızı mümkün olduğunca açarak dizinizle büyük bir daire çizmeye çalışın.", "Bu hareketi belirli sayıda tekrar boyunca yavaşça yapın ve diğer tarafta tekrarlayın."]', 'stretching', '["Standing_Hip_Circles/0.jpg", "Standing_Hip_Circles/1.jpg"]', 150.0, 'Standing Hip Circles', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f7527917-65d7-5fc9-b517-9acb345c33b4', 'free-exercise-db', 'Standing_Hip_Flexors', 'Ayakta Kalça Fleksörü Esnetme', 'static', 'beginner', 'isolation', '[]', '["quadriceps"]', '[]', '["Omurganız dikey olacak şekilde dik durun, sol ayağınız sağ ayağınızın biraz önünde olsun.", "Sağ kalçanızı öne doğru bastırırken her iki dizinizi bükün ve arka topuğunuzu yerden kaldırın. Ancak bu pozisyonda kapsamlı, derin bir esneme elde edemezsiniz, çünkü kalça fleksörünü gevşetmek ve aynı anda üzerinde durmak zordur. Taraf değiştirin."]', 'stretching', '["Standing_Hip_Flexors/0.jpg", "Standing_Hip_Flexors/1.jpg"]', 150.0, 'Standing Hip Flexors', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('2fe96c6a-4bc7-5391-9aea-9c81791b3f6e', 'free-exercise-db', 'Standing_Inner-Biceps_Curl', 'Ayakta İç Biceps Curl (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her elinizde kollarınız uzanmış şekilde birer dambıl tutarak ayakta durun. Dirsekler gövdeye yakın olmalıdır. Bacaklarınız birbirinden yaklaşık omuz genişliğinde açık olmalıdır.", "Avuç içlerinizi nötr pozisyonda içe bakacak şekilde döndürün. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarak nefes verip biceps''inizi kasarak ağırlıkları dışa doğru kıvırın. Bileğiniz, ağırlıklar tamamen yükseldiğinde supinasyon tutuşa (avuç içleri yukarı) gelecek şekilde dönmelidir.", "Yalnızca ön kollar hareket etmelidir. Biceps''leriniz tamamen kasılana ve dambıllar omuz seviyesine gelene kadar hareketi sürdürün. İpucu: Ön kolları dış deltoidlerinizle aynı hizada tutun.", "Biceps''inizi sıkarak kasılmış pozisyonu bir saniye tutun.", "Nefes alırken dambılları yavaşça başlangıç pozisyonuna getirmeye başlayın. Ağırlığı indirirken nötr tutuşa geri dönmek için bilekleri döndürmeyi unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Inner-Biceps_Curl/0.jpg", "Standing_Inner-Biceps_Curl/1.jpg"]', 360.0, 'Standing Inner-Biceps Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8ef3b9b6-67e8-5151-ae07-988bca6cc39b', 'free-exercise-db', 'Standing_Lateral_Stretch', 'Ayakta Yan Gövde Esnetme', 'static', 'beginner', NULL, '[]', '["abdominals"]', '[]', '["Kalça mesafesinden biraz daha geniş bir duruş alın ve dizlerinizi hafifçe bükün.", "Omurgayı desteklemek için sağ elinizi sağ kalçanıza yerleştirin.", "Sol kolunuzu dikey bir çizgide kaldırın ve sol elinizi başınızın arkasına yerleştirin. Gövdenizi sağa doğru eğerken orada tutun.", "Ağırlığınızı iki bacağınız arasında eşit dağıtın (sol kalçanıza yaslanmayın). Taraf değiştirin."]', 'stretching', '["Standing_Lateral_Stretch/0.jpg", "Standing_Lateral_Stretch/1.jpg"]', 150.0, 'Standing Lateral Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0e60954c-aa43-5dc1-9198-7cc0cb70a57a', 'free-exercise-db', 'Standing_Leg_Curl', 'Ayakta Leg Curl (Makine)', 'pull', 'beginner', 'isolation', '["machine"]', '["hamstrings"]', '[]', '["Makinenin kolunu boyunuza göre ayarlayın; kolun minderi sağ bacağınızın arkasında (baldırlarınızın sadece birkaç santim altında) ve sağ bacağınızın ön kısmı makine minderinin üzerinde olacak şekilde, gövdeniz belinizden yaklaşık 30-45 derece öne eğik şekilde uzanın (açılı pozisyon arka bacak kaslarını devreye sokmak için daha uygun olduğundan).", "Gövdenizi öne eğik tutarak bacağınızın tamamen gergin olduğundan emin olun ve makinenin yan saplarını kavrayın. Ayak uçlarınızı düz konumlandırın. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken, üst bacağı minderden kaldırmadan sağ bacağınızı olabildiğince yukarı kıvırın. Tamamen kasılmış pozisyona ulaştığınızda bir saniye tutun.", "Nefes alırken bacakları ilk pozisyona geri getirin. Önerilen tekrar sayısı kadar tekrarlayın.", "Aynı egzersizi şimdi sol bacak için yapın."]', 'strength', '["Standing_Leg_Curl/0.jpg", "Standing_Leg_Curl/1.jpg"]', 360.0, 'Standing Leg Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('dae3b026-f111-53bb-8e0b-dc06327f08fe', 'free-exercise-db', 'Standing_Long_Jump', 'Durarak Uzun Atlama', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bu çalışma en iyi kumda veya başka yumuşak bir iniş yüzeyinde yapılır. Mesafeyi ölçebildiğinizden emin olun. Ayaklar omuz genişliğinde açık ve kısmi squat duruşunda durun.", "Büyük bir kol savurma ve bacakların karşı hareketini kullanarak olabildiğince ileri zıplayın.", "Ayaklarınız önünüzde ve bacaklarınızla olabildiğince uzağa uzanarak inmeye çalışın.", "İniş noktanızdan başlangıç noktasına olan mesafeyi ölçün ve sonuçları takip edin."]', 'plyometrics', '["Standing_Long_Jump/0.jpg", "Standing_Long_Jump/1.jpg"]', 480.0, 'Standing Long Jump', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('535d1248-d19b-5f1d-b805-31343276fecf', 'free-exercise-db', 'Standing_Low-Pulley_Deltoid_Raise', 'Ayakta Deltoid Raise (Alt Makara)', 'push', 'beginner', 'isolation', '["cable"]', '["shoulders"]', '["forearms"]', '["Bir alt makaralı row''un sağ tarafında durarak başlayın. Sol elinizle vücudunuzun karşısına uzanın ve alt makaraya bağlı tek bir tutamağı pronasyon tutuşla (avuç içi aşağı) kavrayın. Kolunuzu önünüzde dinlendirin. Daha iyi destek ve denge için sağ elinizle makineyi tutun.", "Sırtınızın dik olduğundan ve ayaklarınızın omuz genişliğinde açık olduğundan emin olun. Bu başlangıç pozisyonudur.", "Sol elinizi kullanarak, nefes verirken omuz hizasına yükselene kadar vücudunuzun karşısından dışarı doğru getirmeye başlayın.", "Üst noktada kasılmayı bir saniye hissedin ve nefes alırken tutamağı yavaşça orijinal başlangıç pozisyonuna indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve egzersizi tekrarlayın."]', 'strength', '["Standing_Low-Pulley_Deltoid_Raise/0.jpg", "Standing_Low-Pulley_Deltoid_Raise/1.jpg"]', 360.0, 'Standing Low-Pulley Deltoid Raise', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4f5113ed-49cb-5ec7-b75d-264a7a1d6f1e', 'free-exercise-db', 'Standing_Low-Pulley_One-Arm_Triceps_Extension', 'Ayakta Tek Kol Triceps Extension (Kablo, Alt Makara)', 'push', 'intermediate', 'isolation', '["cable"]', '["triceps"]', '["chest", "shoulders"]', '["Alt makara makinesinin yanında sol kolunuzla tek bir tutamağı kavrayın. Kolunuz tamamen uzatılmış halde tutamağı vücudunuzun yanında tutarak makineye sırtınızı dönün. Şimdi iki elinizi de kullanarak tek tutamağı avuç içi öne bakacak şekilde doğrudan başınızın üzerine kaldırın. Üst kolunuzu tamamen dikey (yere dik) tutun ve sabit kalmasına yardımcı olmak için sağ elinizi sol dirseğinize koyun. Bu başlangıç pozisyonudur.", "Üst kollarınızı başınıza yakın (dirsekler içeride) ve yere dik tutarak, ön kollarınız biceps''inize değene kadar direnci başınızın arkasında yarım daire hareketiyle indirin. İpucu: Üst kollar sabit kalmalı ve sadece ön kollar hareket etmelidir. Bu adımı yaparken nefes alın.", "Tek tutamağı kaldırmak için triceps''i kullanarak başlangıç pozisyonuna geri dönün. Bu adımı yaparken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Kolunuzu değiştirin ve egzersizi tekrarlayın."]', 'strength', '["Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg", "Standing_Low-Pulley_One-Arm_Triceps_Extension/1.jpg"]', 360.0, 'Standing Low-Pulley One-Arm Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7a306bcb-d2c0-5d4c-a4a4-10a5fd8453bf', 'free-exercise-db', 'Standing_Military_Press', 'Ayakta Military Press (Halter)', 'push', 'beginner', 'compound', '["barbell"]', '["shoulders"]', '["triceps"]', '["Göğüs hizasında bir halteri squat rafına yerleştirerek başlayın. Ağırlıkları seçtikten sonra halteri pronasyon (avuç içleri öne bakan) tutuşla kavrayın. Barı omuz genişliğinden daha geniş bir aralıkla tuttuğunuzdan emin olun.", "Dizlerinizi hafifçe bükün ve halteri köprücük kemiğinize yerleştirin. Halteri göğsünüzün üzerinde duracak şekilde kaldırın. Bir adım geriye gidin ve ayaklarınızı omuz genişliğinde açın.", "Halteri doğru tutuş genişliğiyle aldıktan sonra kollarınızı kilitleyerek barı başınızın üzerine kaldırın. Yaklaşık omuz hizasında ve başınızın biraz önünde tutun. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken barı yavaşça köprücük kemiğine doğru indirin.", "Nefes verirken barı başlangıç pozisyonuna kaldırın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Military_Press/0.jpg", "Standing_Military_Press/1.jpg"]', 360.0, 'Standing Military Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ad7a458f-40da-5ee6-bdc0-0ead03640e4c', 'free-exercise-db', 'Standing_Olympic_Plate_Hand_Squeeze', 'Ayakta Plaka Sıkma (Olimpik Plaka)', 'static', 'beginner', 'isolation', '["other"]', '["forearms"]', '["biceps"]', '["Başlamak için her elinizde nötr tutuşla (avuç içleri içe bakacak şekilde) bir ağırlık plakasını kenarından kol boyu uzaklıkta tutarak dik durun. Ayaklarınız birbirinden omuz genişliğinde açık olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Plakaları, parmaklar neredeyse uzayana ancak ağırlığı hâlâ tutabilecek duruma gelene kadar indirin. Plakaları indirirken nefes alın.", "Şimdi nefes verirken ellerinizi kapatarak plakaları başlangıç pozisyonuna kaldırın.", "Programınızda belirtilen önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Olympic_Plate_Hand_Squeeze/0.jpg", "Standing_Olympic_Plate_Hand_Squeeze/1.jpg"]', 360.0, 'Standing Olympic Plate Hand Squeeze', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ed250977-a3ac-57ed-b06c-deb9c2b5e7c7', 'free-exercise-db', 'Standing_One-Arm_Cable_Curl', 'Ayakta Tek Kol Biceps Curl (Kablo)', 'pull', 'intermediate', 'isolation', '["cable"]', '["biceps"]', '[]', '["Alçak makara makinesinin yanındaki tek sapı kavrayarak başlayın. Kolunuzun ağırlığı taşıması için makineden yeterince uzakta olduğunuzdan emin olun.", "Üst kolunuzun sabit, yere dik, dirseklerin içeride ve avuç içlerinin ileri baktığından emin olun. Kaldırmayan kolunuz belinizi tutmalı. Bu, dengenizi korumanıza yardımcı olacaktır.", "Üst kolu sabit tutarak ön kolunuz biceps''inize değene kadar tek sapı yavaşça yukarı doğru kıvırmaya başlayın ve nefes verin. İpucu: Sadece ön kol hareket etmelidir.", "Biceps''i sıkarken kasılma pozisyonunu tutun, ardından nefes alırken tek sapı başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bu egzersizi yaparken kolları değiştirin."]', 'strength', '["Standing_One-Arm_Cable_Curl/0.jpg", "Standing_One-Arm_Cable_Curl/1.jpg"]', 360.0, 'Standing One-Arm Cable Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('08e2772b-bcd6-55bb-8015-7fe59557f059', 'free-exercise-db', 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'Biceps Curl (Dambıl, Tek Kol, Incline Sehpa Arkası)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Birine spotter olacakmış gibi incline sehpanın arka tarafında durun. Bir elinizde dambıl olsun ve supinasyon (avuç içi yukarı) tutuşla incline sehpanın üzerinden uzatın.", "Kaldırmayan elinizi incline sehpanın köşesine veya yanına yerleştirin. Göğsünüz incline''ın üst kısmına bastırılmış ve ayaklarınız geniş bir duruşla yere basıyor olmalıdır. Bu başlangıç pozisyonudur.", "Üst kolunuzu sabit tutarken nefes verip biceps''i kasarak dambılı yukarı doğru kıvırın. Yalnızca ön kollar hareket etmelidir. Biceps''iniz tamamen kasılana ve dambıl omuz hizasına gelene kadar harekete devam edin. Kasılmış pozisyonda bir saniye bekleyin.", "Nefes alırken dambılı yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Bu egzersizi yaparken kolları değiştirin."]', 'strength', '["Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg", "Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg"]', 360.0, 'Standing One-Arm Dumbbell Curl Over Incline Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('51659ceb-e573-5c39-ba8e-7fd336cfd4b6', 'free-exercise-db', 'Standing_One-Arm_Dumbbell_Triceps_Extension', 'Ayakta Tek Kol Triceps Extension (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '["chest", "shoulders"]', '["Başlamak için bir elinizde dambıl tutarak ayakta durun. Ayaklarınız birbirinden yaklaşık omuz genişliğinde açık olmalıdır. Şimdi dambıllı kolu başınızın üzerinde tamamen uzatın. İpucu: Elinizin serçe parmağı tavana, avuç içi ise öne bakmalıdır. Dambıl başınızın üzerinde olmalıdır.", "Bu sizin başlangıç pozisyonunuzdur.", "Üst kolunuzu başınıza yakın (dirsek içeride) ve yere dik tutarak, ön kolunuz biceps''inize değene kadar ağırlığı başınızın arkasına yarım daire hareketiyle indirin. İpucu: Üst kol sabit kalmalı ve yalnızca ön kol hareket etmelidir. Bu adımı yaparken nefes alın.", "Dambılı kaldırmak için triceps''i kullanarak başlangıç pozisyonuna dönün. Bu adımı yaparken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve egzersizi tekrarlayın."]', 'strength', '["Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg", "Standing_One-Arm_Dumbbell_Triceps_Extension/1.jpg"]', 360.0, 'Standing One-Arm Dumbbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4df0ff8c-47b3-5a2f-92c1-56232e9d8bf1', 'free-exercise-db', 'Standing_Overhead_Barbell_Triceps_Extension', 'Ayakta Baş Üstü Triceps Extension (Halter)', 'push', 'beginner', 'isolation', '["barbell"]', '["triceps"]', '["shoulders"]', '["Başlamak için bir halter ya da EZ bar''ı pronated tutuşla (avuç içleri öne bakacak şekilde), elleriniz birbirinden omuz genişliğinden daha yakın olacak şekilde tutarak ayakta durun. Ayaklarınız yaklaşık omuz genişliğinde açık olmalıdır.", "Şimdi kollarınız tamamen uzayana kadar halteri başınızın üzerine kaldırın. Dirseklerinizi içeride tutun. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı başınıza yakın ve dirseklerinizi içeride, yere dik tutarak, ön kollarınız biceps''inize değene kadar ağırlığı başınızın arkasında yarım daire çizerek indirin. İpucu: Üst kollar sabit kalmalı ve yalnızca ön kollar hareket etmelidir. Bu adımı yaparken nefes alın.", "Halteri kaldırmak için triceps''i kullanarak başlangıç pozisyonuna dönün. Bu adımı yaparken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Overhead_Barbell_Triceps_Extension/0.jpg", "Standing_Overhead_Barbell_Triceps_Extension/1.jpg"]', 360.0, 'Standing Overhead Barbell Triceps Extension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9fe3227a-c87d-56d4-9793-f0a7c3b87aab', 'free-exercise-db', 'Standing_Palm-In_One-Arm_Dumbbell_Press', 'Ayakta Tek Kol Omuz Press (Dambıl, Nötr Tutuş)', 'push', 'beginner', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Bir elinizde dambılla, nötr tutuşla kolunuz yana tamamen uzamış halde başlayın. Dengenizi korumak için diğer kolunuzla bir incline bench''e tutunun.", "Ayaklarınız omuz genişliğinde açık olmalıdır. Şimdi kolunuzla 90 derecelik bir açı oluşturana kadar dambılı yavaşça kaldırın. Not: Ön kolunuz yere dik olmalıdır. Egzersizin tamamı boyunca nötr tutuşu koruyun.", "Kolunuz tamamen uzayana kadar dambılı yavaşça yukarı kaldırın. Bu başlangıç pozisyonudur.", "Nefes alırken kolunuz tekrar 90 derecelik açıya gelene kadar ağırlığı aşağı indirin.", "Kasılmayı bir saniye hissedin ve ardından nefes verirken ağırlığı başlangıç pozisyonuna doğru yukarı kaldırın. Egzersiz sırasında dengeyi korumak için incline bench''e tutunmayı ve ayaklarınızı konumlandırmayı unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Kolları değiştirin ve egzersizi tekrarlayın."]', 'strength', '["Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg", "Standing_Palm-In_One-Arm_Dumbbell_Press/1.jpg"]', 360.0, 'Standing Palm-In One-Arm Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('889d3348-c511-5e52-85ab-004631f194c8', 'free-exercise-db', 'Standing_Palms-In_Dumbbell_Press', 'Ayakta Nötr Tutuş Shoulder Press (Dambıl)', 'push', 'intermediate', 'compound', '["dumbbell"]', '["shoulders"]', '["triceps"]', '["Her elinizde bir dambıl olacak şekilde, kollarınız nötr tutuşla yana tamamen uzatılmış halde başlayın. Ayaklarınız birbirinden omuz genişliğinde açık olmalıdır. Şimdi kollarınızla 90 derecelik bir açı oluşturana kadar dambılları yavaşça yukarı kaldırın. Not: Ön kollarınız yere dik olmalıdır. Bu başlangıç pozisyonudur.", "Tüm egzersiz boyunca nötr tutuşu koruyun. Kollarınız tamamen uzayana kadar dambılları yavaşça yukarı kaldırın.", "Nefes alırken ağırlıkları kolunuz tekrar 90 derecelik açıya gelene kadar indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Palms-In_Dumbbell_Press/0.jpg", "Standing_Palms-In_Dumbbell_Press/1.jpg"]', 360.0, 'Standing Palms-In Dumbbell Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ecc7f069-5410-5643-aebc-e690a8480a44', 'free-exercise-db', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'Arkadan Bilek Curl (Halter, Ayakta)', 'pull', 'beginner', 'isolation', '["barbell"]', '["forearms"]', '[]', '["Dik durarak ve halteri kalçalarınızın arkasında kol boyu mesafede, pronasyon tutuşla (avuç içleri kalçalardan uzağa, geriye bakacak şekilde) ve eller birbirinden omuz genişliğinde aralıklı olacak şekilde tutarak başlayın.", "Ayaklarınız omuz genişliğinde aralıklıyken düz ileri bakıyor olmalısınız. Bu başlangıç pozisyonudur.", "Nefes verirken, bileğinizi tavana doğru yarım daire hareketiyle kıvırarak halteri yavaşça yukarı kaldırın. Not: Bu egzersizde hareket eden tek vücut kısmı bileğiniz olmalıdır.", "Kasılmayı bir saniye tutun ve nefes alırken halteri başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "İşiniz bittiğinde dizlerinizi bükerek halteri squat rack''e veya yere bırakın. İpucu: En kolayı, onu squat rack''ten almak veya bir partnerinizin size vermesidir."]', 'strength', '["Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg", "Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg"]', 360.0, 'Standing Palms-Up Barbell Behind The Back Wrist Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1fa54b96-27df-5a24-8f59-8868f34ecf40', 'free-exercise-db', 'Standing_Pelvic_Tilt', 'Ayakta Pelvik Tilt', 'static', 'beginner', 'isolation', '[]', '["lower back"]', '["glutes"]', '["Ayaklarınızı kalça genişliğinde açarak başlayın.", "Dizlerinizi yumuşak ve yaylı tutmak için hafifçe bükün.", "Bu esnemede kuyruk sokumunu öne doğru tutmadan önce pelvisinizi birkaç kez ileri ve geri hareket ettirmek isteyebilirsiniz."]', 'stretching', '["Standing_Pelvic_Tilt/0.jpg", "Standing_Pelvic_Tilt/1.jpg"]', 150.0, 'Standing Pelvic Tilt', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('74685795-7ef4-5e56-bb29-55a8abda7238', 'free-exercise-db', 'Standing_Rope_Crunch', 'Ayakta Crunch (Kablo, İp)', 'pull', 'beginner', 'isolation', '["cable"]', '["abdominals"]', '[]', '["Yüksek bir makaraya bir ip bağlayın ve uygun ağırlığı seçin.", "Sırtınız kablo kulesine dönük şekilde durun. İpi iki elinizle omuzlarınızın üzerinden alın ve üst göğsünüze yakın tutun. Bu sizin başlangıç pozisyonunuzdur.", "Omurgayı bükerek, ağırlığı olabildiğince aşağı crunch yaparak hareketi gerçekleştirin.", "Başlangıç pozisyonuna dönmeden önce zirve kasılmayı bir an tutun."]', 'strength', '["Standing_Rope_Crunch/0.jpg", "Standing_Rope_Crunch/1.jpg"]', 360.0, 'Standing Rope Crunch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d0e86c37-829c-549c-870f-6b619c6926e0', 'free-exercise-db', 'Standing_Soleus_And_Achilles_Stretch', 'Ayakta Soleus ve Aşil Esnetme', 'static', 'beginner', 'isolation', '[]', '["calves"]', '[]', '["Ayaklarınız kalça genişliğinde açık, bir ayak diğerinin hafifçe önünde olacak şekilde ayakta durun.", "Arka topuğunuz yerde kalacak şekilde iki dizinizi de bükün. Taraf değiştirin."]', 'stretching', '["Standing_Soleus_And_Achilles_Stretch/0.jpg", "Standing_Soleus_And_Achilles_Stretch/1.jpg"]', 150.0, 'Standing Soleus And Achilles Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c4c2ee00-354d-52d6-9ad1-c9d4a43d16c2', 'free-exercise-db', 'Standing_Toe_Touches', 'Ayakta Parmak Ucuna Dokunma', 'static', 'beginner', NULL, '[]', '["hamstrings"]', '["calves"]', '["Önünüzde ve arkanızda biraz boşluk olacak şekilde durun.", "Bacaklarınızı düz tutarak belinizden eğilin ve gevşeyip üst vücudunuzun önünüzde sarkmasına izin verebileceğiniz noktaya gelin. Kollarınızın ve ellerinizin doğal şekilde sarkmasına izin verin. 10 ila 20 saniye bekleyin."]', 'stretching', '["Standing_Toe_Touches/0.jpg", "Standing_Toe_Touches/1.jpg"]', 150.0, 'Standing Toe Touches', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1d5b4005-c661-50d5-a8cf-1e3de6e95987', 'free-exercise-db', 'Standing_Towel_Triceps_Extension', 'Ayakta Triceps Extension (Havlu, Partnerli)', 'push', 'beginner', 'isolation', '["body only"]', '["triceps"]', '[]', '["Başlamak için ayakta durun ve havlunun bir ucunu iki elinizle tutarak her iki kolunuzu da başınızın üzerinde tamamen uzatın. Dirsekleriniz içeride, kollarınız yere dik ve avuç içleriniz birbirine bakıyor olmalı, ayaklarınız omuz genişliğinde açık olmalıdır. Bu başlangıç pozisyonudur.", "Şimdi partnerinizle, havlunun diğer ucunu tutarak direnç uygulayabilmesi için iletişim kurun. Üst kollarınızı başınıza yakın (dirsekler içeride) ve yere dik tutarak, ön kollarınız biceps''inize değene kadar direnci başınızın arkasından yarım daire hareketiyle indirin. İpucu: Üst kollar sabit kalmalı ve yalnızca ön kollar hareket etmelidir. Bu adımı yaparken nefes alın.", "Havluyu kaldırmak için triceps''i kullanarak başlangıç pozisyonuna dönün. Bu adımı yaparken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Standing_Towel_Triceps_Extension/0.jpg", "Standing_Towel_Triceps_Extension/1.jpg"]', 360.0, 'Standing Towel Triceps Extension', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ec5cc834-5da3-52ab-a52b-2a498bd6a0b9', 'free-exercise-db', 'Standing_Two-Arm_Overhead_Throw', 'Overhead Throw (Medicine Ball)', 'pull', 'beginner', 'compound', '["medicine ball"]', '["shoulders"]', '["chest", "lats"]', '["Ayaklarınız omuz genişliğinde açık, iki elinizde bir medicine ball tutarak durun. Başlamak için dizlerinizi hafifçe bükerek ve geriye yaslanarak medicine ball''u başınızın çok gerisine uzatın.", "Kalçanızdan bükülerek ve hareketi tamamlamak için tüm vücudunuzu kullanarak topu öne doğru şiddetle fırlatın.", "Medicine ball bir partnere veya bir duvara fırlatılabilir ve geri sektiğinde yakalanabilir."]', 'plyometrics', '["Standing_Two-Arm_Overhead_Throw/0.jpg", "Standing_Two-Arm_Overhead_Throw/1.jpg"]', 480.0, 'Standing Two-Arm Overhead Throw', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('45472541-e299-55d7-9d47-378fc81e0b30', 'free-exercise-db', 'Star_Jump', 'Yıldız Sıçraması', 'push', 'beginner', 'compound', '["body only"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "shoulders"]', '["Ayaklarınız omuz genişliğinde açık ve kollarınız vücuda yakın rahat bir duruşla başlayın.", "Harekete başlamak için yarıya kadar çömelin ve olabildiğince yükseğe patlayıcı bir şekilde yukarı sıçrayın. Bacaklarınızı ve kollarınızı vücudunuzdan uzağa açarak tüm vücudunuzu tamamen uzatın.", "İnerken uzuvlarınızı geri toplayın ve darbeyi bacaklarınızla karşılayın."]', 'plyometrics', '["Star_Jump/0.jpg", "Star_Jump/1.jpg"]', 480.0, 'Star Jump', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7d87f221-7b3a-5df7-b303-8b5c9f651208', 'free-exercise-db', 'Step-up_with_Knee_Raise', 'Step-Up ve Diz Kaldırma', 'push', 'beginner', 'compound', '["body only"]', '["glutes"]', '["hamstrings", "quadriceps"]', '["Ayaklarınız bitişik şekilde uygun yükseklikte bir kutuya veya banka dönük durun. Bu sizin başlangıç pozisyonunuzdur.", "Sol ayağınızı bankın üzerine koyarak yukarı adım atarak harekete başlayın. Kutunun üzerinde ayakta durmak için ön bacağınızın kalça ve dizini açın. Sol bacağınızla kutunun üzerinde dururken, sağ diz ve kalçanızı bükerek dizinizi olabildiğince yukarı getirin.", "Kutudan aşağı adım atmak için bu hareketi tersine çevirin, ardından diziyi diğer bacakla tekrarlayın."]', 'strength', '["Step-up_with_Knee_Raise/0.jpg", "Step-up_with_Knee_Raise/1.jpg"]', 360.0, 'Step-up with Knee Raise', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('adf0ebd3-d897-57af-bda8-12048ba16385', 'free-exercise-db', 'Step_Mill', 'Step Mill (Merdiven Makinesi)', NULL, 'intermediate', NULL, '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için step mill''e çıkın ve menüden istediğiniz seçeneği seçin. Manuel bir ayar seçebilir ya da çalıştırılacak bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kalori miktarını tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz. Merdivenleri tırmanırken tökezlememek için dikkatli olun. Düşmemek için tutamaklardan tutunmaya devam etmeniz önerilir.", "Step mill''ler kolaylık, kardiyovasküler faydalar sağlar ve genellikle dışarıda koşmaktan daha az darbe oluştururken benzer bir kalori yakma hızı sunar. Genellikle diğer kardiyo ekipmanlarından çok daha zordurlar. 68 kg (150 lb) ağırlığındaki bir kişi 30 dakikada genellikle 300 kaloriden fazla yakar; yürüyüşte bu yaklaşık 175 kaloridir."]', 'cardio', '["Step_Mill/0.jpg", "Step_Mill/1.jpg"]', 600.0, 'Step Mill', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('aa699871-9570-5eca-8b60-a97b2214ae8a', 'free-exercise-db', 'Stiff-Legged_Barbell_Deadlift', 'Stiff-Leg Deadlift (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["glutes", "lower back"]', '["Bir barı üsten tutuşla (avuç içleri aşağı bakan) kavrayın. Önemli miktarda ağırlık kullanıyorsanız bilek sargılarına ihtiyacınız olabilir.", "Gövdeniz dik, bacaklarınız omuz genişliğinde veya daha dar bir duruşta açık şekilde durun. Dizler hafifçe bükülü olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi sabit tutarak, sırtınızı düz tutup kalçadan eğilerek halteri ayaklarınızın üzerine kadar indirin. Yerden bir şey alacakmışsınız gibi arka bacak kaslarınızda bir gerilme hissedene kadar öne doğru gitmeye devam edin. Bu hareketi yaparken nefes alın.", "Başlangıç pozisyonuna dönene kadar kalçanızı açarak gövdenizi tekrar dik şekilde yukarı getirmeye başlayın. Bu hareketi yaparken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Stiff-Legged_Barbell_Deadlift/0.jpg", "Stiff-Legged_Barbell_Deadlift/1.jpg"]', 360.0, 'Stiff-Legged Barbell Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8f0aafb4-1908-5bd7-a114-4cf5c670c266', 'free-exercise-db', 'Stiff-Legged_Dumbbell_Deadlift', 'Stiff-Leg Deadlift (Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["hamstrings"]', '["glutes", "lower back"]', '["İki dambılı yanlarınızda kol boyu kadar sarkacak şekilde kavrayın.", "Gövdeniz düz ve bacaklarınız omuz genişliğinde veya daha dar bir duruşla açık olacak şekilde durun. Dizler hafifçe bükülü olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi sabit tutarak, sırtınızı düz tutup belinizden eğilerek dambılları ayaklarınızın üzerine kadar indirin. Arka bacaklarınızda bir esneme hissedene kadar sanki yerden bir şey alacakmış gibi öne doğru hareket etmeye devam edin. Bu hareketi yaparken nefes verin.", "Kalçanızı ve belinizi açarak başlangıç pozisyonuna dönene kadar gövdenizi tekrar dik hale getirmeye başlayın. Bu hareketi yaparken nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Stiff-Legged_Dumbbell_Deadlift/0.jpg", "Stiff-Legged_Dumbbell_Deadlift/1.jpg"]', 360.0, 'Stiff-Legged Dumbbell Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('962d1b2a-7d65-50b0-a959-9933481d8c1d', 'free-exercise-db', 'Stiff_Leg_Barbell_Good_Morning', 'Good Morning (Halter, Düz Bacak)', 'push', 'beginner', 'compound', '["barbell"]', '["lower back"]', '["glutes", "hamstrings"]', '["Bu egzersiz güvenlik amacıyla en iyi squat rack içinde yapılır. Başlamak için önce barı boyunuza en uygun rafa yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve omuzlarınızın arkasını (boynun biraz altında) barın üzerine yerleştirin.", "Barı iki kolunuzla iki yandan tutun ve önce bacaklarınızla iterek ve aynı anda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşla konumlandırın. Aşağı bakmak dengenizi bozacağı için başınızı her zaman yukarıda tutun ve ayrıca sırtınızı düz tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Bacaklarınızı sabit tutarak, nefes alırken kalçadan bükülerek gövdenizi öne doğru hareket ettirin. Gövdeniz yere paralel olana kadar indirin.", "Nefes verirken gövdenizi başlangıç pozisyonuna doğru kaldırarak barı yukarı kaldırmaya başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Stiff_Leg_Barbell_Good_Morning/0.jpg", "Stiff_Leg_Barbell_Good_Morning/1.jpg"]', 360.0, 'Stiff Leg Barbell Good Morning', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ed1228e6-877b-5ccf-aa4c-762e8f1750b6', 'free-exercise-db', 'Stomach_Vacuum', 'Karın Vakumu (Stomach Vacuum)', 'static', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Başlamak için ayaklarınız birbirinden omuz genişliğinde açık şekilde dik durun. Ellerinizi kalçanıza koyun. Bu başlangıç pozisyonudur.", "Şimdi yavaşça olabildiğince çok hava çekin, ardından karnınızı olabildiğince içeri çekerek mümkün olduğunca fazla nefes vermeye başlayın ve bu pozisyonu tutun. Göbeğinizin omurganıza değdiğini hayal etmeye çalışın.", "Bir izometrik kasılma yaklaşık 20 saniyedir. 20 saniyelik tutuş sırasında normal nefes almaya çalışın. Ardından nefes alın ve karnınızı başlangıç pozisyonuna getirin.", "Bu egzersizi alıştıktan sonra 20 saniyeden daha uzun süre yapmaya çalışın. İpucu: 40-60 saniyeye kadar çıkabilirsiniz.", "Önerilen set sayısı kadar tekrarlayın."]', 'stretching', '["Stomach_Vacuum/0.jpg", "Stomach_Vacuum/1.jpg"]', 150.0, 'Stomach Vacuum', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1bb55789-483b-5d2b-8a01-9f50b8a11ac8', 'free-exercise-db', 'Straight-Arm_Dumbbell_Pullover', 'Pullover (Dambıl, Düz Kol)', 'pull', 'intermediate', 'compound', '["dumbbell"]', '["chest"]', '["lats", "shoulders", "triceps"]', '["Düz bir sehpanın üzerine bir dambılı dik şekilde yerleştirin.", "Dambılın sehpanın üstünde sağlam durduğundan emin olarak sehpaya dik şekilde uzanın (gövdeniz bir haç oluşturacak şekilde sehpayı çaprazlasın); yüzeye yalnızca omuzlarınız değmelidir. Kalçanız sehpanın altında ve bacaklarınız bükülü, ayaklarınız yere sağlam basıyor olmalıdır. Baş da sehpanın dışında kalacaktır.", "Dambılı iki elinizle kavrayın ve göğsünüzün tam üzerinde kol boyu tutun. Her iki avuç içi de dambılın yan taraflarından birinin alt yüzüne bastırıyor olmalıdır. Bu sizin başlangıç pozisyonunuzdur.\nDikkat: Bu egzersiz için kullanılan dambılın sağlam olduğundan her zaman emin olun. Plakaları gevşek bir dambıl kullanmak, dambılın parçalanıp yüzünüze düşmesine neden olabilir.", "Kollarınızı düz tutarken nefes alırken göğsünüzde bir esneme hissedene kadar ağırlığı başınızın arkasında bir yay çizerek yavaşça indirin.", "Bu noktada dambılı ağırlığın indirildiği yayı kullanarak başlangıç pozisyonuna geri getirin ve bu hareketi yaparken nefes verin.", "Ağırlığı başlangıç pozisyonunda bir saniye tutun ve hareketi belirtilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Straight-Arm_Dumbbell_Pullover/0.jpg", "Straight-Arm_Dumbbell_Pullover/1.jpg"]', 360.0, 'Straight-Arm Dumbbell Pullover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('da4d69db-ef02-5642-b4a2-013f3821b578', 'free-exercise-db', 'Straight-Arm_Pulldown', 'Düz Kol Pulldown (Kablo)', 'pull', 'beginner', 'isolation', '["cable"]', '["lats"]', '[]', '["Pulldown makinesinin üst makarasındaki geniş barı, omuz genişliğinden geniş pronasyon (avuç içleri aşağı) tutuşla kavrayarak başlayın. Yaklaşık iki ayak geriye adım atın.", "Kollarınız önünüzde tamamen uzanmış ve dirsekler hafif bükülü şekilde gövdenizi belden yaklaşık 30 derece öne eğin. Kollarınız tamamen uzanmıyorsa, uzanana kadar biraz daha geriye adım atmanız gerekir. Kollarınız tamamen uzanıp gövdeniz belden hafifçe eğildikten sonra latlarınızı sıkın, artık başlamaya hazırsınız.", "Kolları düz tutarak, elleriniz uyluklarınızın yanına gelene kadar latlarınızı kasarak barı aşağı çekin. Bu adımı yaparken nefes verin.", "Kolları düz tutarak, nefes alırken başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Straight-Arm_Pulldown/0.jpg", "Straight-Arm_Pulldown/1.jpg"]', 360.0, 'Straight-Arm Pulldown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('04bcba98-31f0-5c6d-b236-8bfd9346d203', 'free-exercise-db', 'Straight_Bar_Bench_Mid_Rows', 'Bench Üzerinde Row (Halter)', 'pull', 'beginner', 'compound', '["barbell"]', '["middle back"]', '["biceps", "lats"]', '["Yüklü bir halteri bir bench''in ucuna yerleştirin. Barın arkasında bench''in üzerinde durarak orta genişlikte, pronasyon bir tutuş alın. Kalçanız geride ve göğsünüz yukarıda, nötr bir omurga ile durun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Kürek kemiklerinizi geriye çekerek ve dirseklerinizi bükerek barı gövdenize doğru çekin. Sarsıntı olmadan kontrollü bir hareket kullanın.", "Kısa bir beklemeden sonra, tamamen aşağı indiğinizden emin olarak barı yavaşça başlangıç pozisyonuna geri bırakın."]', 'strength', '["Straight_Bar_Bench_Mid_Rows/0.jpg", "Straight_Bar_Bench_Mid_Rows/1.jpg"]', 360.0, 'Straight Bar Bench Mid Rows', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ff99e21a-2a3d-5e49-bd92-cbcaa486266a', 'free-exercise-db', 'Straight_Raises_on_Incline_Bench', 'Düz Kol Raise (Incline Bench, Halter)', 'push', 'beginner', 'isolation', '["barbell"]', '["shoulders"]', '["traps"]', '["Bir barı incline bench''in baş tarafının arkasında yere yerleştirin.", "Bench''e yüzüstü uzanın. Pronasyon tutuşla, kollarınızı düz tutarak halteri yerden alın. Barın dümdüz aşağı sarkmasına izin verin. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başlamak için kollarınızı uzamış halde tutarak halteri başınızın önüne doğru kaldırın.", "Başlangıç pozisyonuna dönün."]', 'strength', '["Straight_Raises_on_Incline_Bench/0.jpg", "Straight_Raises_on_Incline_Bench/1.jpg"]', 360.0, 'Straight Raises on Incline Bench', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b5148943-e0a6-5e64-bcb9-74dca28df299', 'free-exercise-db', 'Stride_Jump_Crossover', 'Adım Sıçrama Çaprazlama (Kutuda)', 'push', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "hamstrings"]', '["Bir kutunun yanında, iç ayağınız kutunun üzerinde ve kenara yakın olacak şekilde durun.", "Üstteki bacağınızdan iterken kollarınızı yukarı savurarak ve olabildiğince yükseğe zıplayarak başlayın. Karşı dizi yukarı doğru sürmeye çalışın.", "Başladığınız pozisyonun tersine, kutunun diğer tarafına inin. Başlangıçta kutunun üzerinde olan ayak şimdi yerde, karşı ayak ise şimdi kutunun üzerinde olacaktır.", "Hareketi tekrarlayın ve diğer tarafa geri geçin."]', 'plyometrics', '["Stride_Jump_Crossover/0.jpg", "Stride_Jump_Crossover/1.jpg"]', 480.0, 'Stride Jump Crossover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('52f439ad-a581-59fb-8418-bf2cbed18113', 'free-exercise-db', 'Sumo_Deadlift', 'Sumo Deadlift (Halter)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["adductors", "forearms", "glutes", "lower back", "middle back", "quadriceps", "traps"]', '["Yerde yüklü bir barla başlayın. Bar ayakların ortasını kesecek şekilde bara yaklaşın. Ayaklar çok geniş, manşonlara yakın olacak şekilde ayarlanmalıdır. Barı kavramak için kalçadan eğilin. Kollar omuzların tam altında, bacakların içinde olmalıdır ve pronasyon tutuş, karışık tutuş veya hook tutuş kullanabilirsiniz. Kolları uzatan omuzlarınızı gevşetin.", "Bir nefes alın, ardından kalçanızı alçaltın; başınızla ileri bakın ve göğsünüzü dik tutun. Ayaklarınızı birbirinden ayırarak yeri iterek, ağırlığınız ayaklarınızın arka yarısında olacak şekilde ilerleyin. Kalça ve dizlerinizi açın.", "Bar dizlerden geçerken geriye yaslanın ve kürek kemiklerinizi birbirine yaklaştırarak kalçanızı bara doğru sürün.", "Kalçadan bükülerek ve inerken ağırlığı kontrol ederek ağırlığı yere geri indirin."]', 'powerlifting', '["Sumo_Deadlift/0.jpg", "Sumo_Deadlift/1.jpg"]', 360.0, 'Sumo Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b7f818d2-1947-5a92-a38d-a529af139fa7', 'free-exercise-db', 'Sumo_Deadlift_with_Bands', 'Sumo Deadlift (Halter, Direnç Bandı)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["adductors", "forearms", "glutes", "lower back", "middle back", "quadriceps", "traps"]', '["Kısa bantlarla deadlift yapmak için, başlamadan önce bantları barın üzerinden geçirin ve kurulum için bantların içine adım atın. Bantların ayağın arka yarısının altında, yani yeri ittiğiniz noktanın hemen altında olduğundan emin olun.", "Yerde yüklü bir barla başlayın. Bar ayakların ortasını kesecek şekilde bara yaklaşın. Ayaklar halter kilitlerine yakın, çok geniş açılmalıdır. Barı kavramak için kalçadan bükülün. Kollar omuzların tam altında, bacakların içinde olmalıdır ve pronasyon tutuş, karışık tutuş veya hook tutuş kullanabilirsiniz.", "Bir nefes alın, ardından kalçanızı alçaltın; başınızla ileri bakın ve göğsünüzü yukarıda tutun. Ağırlığınız ayakların arka yarısında olacak şekilde ayaklarınızı birbirinden ayırarak zemini itin. Kalça ve dizlerinizi açın.", "Bar dizlerden geçerken geriye yaslanın ve kalçanızı bara doğru sürerken kürek kemiklerinizi birbirine doğru sıkın.", "Kalçadan bükülerek ve inerken ağırlığı kontrol ederek ağırlığı yere geri bırakın."]', 'powerlifting', '["Sumo_Deadlift_with_Bands/0.jpg", "Sumo_Deadlift_with_Bands/1.jpg"]', 360.0, 'Sumo Deadlift with Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b6b8d9b0-6918-5512-b596-381bc35e856f', 'free-exercise-db', 'Sumo_Deadlift_with_Chains', 'Sumo Deadlift (Zincirli)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["abductors", "adductors", "forearms", "glutes", "lower back", "middle back", "quadriceps", "traps"]', '["Zincirleri barın uç kısımlarına (sleeve) bağlayabilir veya kaldırdıkça ağırlıkta daha büyük bir artış olması için ortalarını barın üzerine asabilirsiniz. Ağırlığı indirirken plakalara çarpmamak için zincirlerin uçlarını plakalardan uzak tutmaya çalışın.", "Yerde yüklü bir barla başlayın. Bar ayakların ortasını kesecek şekilde bara yaklaşın. Ayaklar, bar kilitlerine (collar) yakın olacak şekilde çok geniş konumlandırılmalıdır. Barı kavramak için kalçanızdan eğilin. Kollar doğrudan omuzların altında, bacakların içinde olmalıdır ve pronasyon tutuş, karışık tutuş veya hook tutuş kullanabilirsiniz. Omuzlarınızı gevşetin, bu da kollarınızı etkili bir şekilde uzatır.", "Bir nefes alın, ardından kalçanızı alçaltın; başınızla ileriye bakın ve göğsünüzü yukarıda tutun. Ağırlığınız ayaklarınızın arka yarısındayken ayaklarınızı birbirinden ayırarak yere doğru itin. Kalçanızı ve dizlerinizi açın.", "Bar dizlerden geçerken geriye yaslanın ve kalçanızı bara doğru sürün, kürek kemiklerinizi birbirine yaklaştırın.", "Kalçanızdan eğilerek ve inerken ağırlığı kontrol ederek ağırlığı yere geri indirin."]', 'powerlifting', '["Sumo_Deadlift_with_Chains/0.jpg", "Sumo_Deadlift_with_Chains/1.jpg"]', 360.0, 'Sumo Deadlift with Chains', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c10f05e2-bd36-5d58-b057-b68c271a8701', 'free-exercise-db', 'Superman', 'Superman', 'static', 'beginner', 'compound', '["body only"]', '["lower back"]', '["glutes", "hamstrings"]', '["Başlamak için yerde veya egzersiz matında düz ve yüzüstü uzanın. Kollarınız önünüzde tamamen uzanmış olmalıdır. Bu başlangıç pozisyonudur.", "Kollarınızı, bacaklarınızı ve göğsünüzü aynı anda yerden kaldırın ve bu kasılmayı 2 saniye tutun. İpucu: Bu egzersizden en iyi sonucu almak için belinizi sıkın. Bu hareket sırasında nefes vermeyi unutmayın. Not: Kasılmış pozisyonda beklerken uçan Superman gibi görünmelisiniz.", "Nefes alırken kollarınızı, bacaklarınızı ve göğsünüzü yavaşça başlangıç pozisyonuna indirmeye başlayın.", "Programınızda belirtilen önerilen tekrar sayısı kadar tekrarlayın."]', 'stretching', '["Superman/0.jpg", "Superman/1.jpg"]', 150.0, 'Superman', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0bf02c04-b5e5-54cd-8ca0-2026f0f9ad16', 'free-exercise-db', 'Supine_Chest_Throw', 'Sırtüstü Göğüs Fırlatma (Medicine Ball)', 'push', 'beginner', 'compound', '["medicine ball"]', '["triceps"]', '["chest", "shoulders"]', '["Bu çalışma, partneriniz veya yeterince sağlam bir duvarınız olmadığında göğüs pasları için harikadır. Dizleriniz bükülü şekilde yerde sırtüstü uzanın.", "Top göğsünüzde, iki elinizle alttan tutulacak şekilde başlayın.", "Patlayıcı şekilde yukarı fırlayın, dirseklerinizi açarak topu tam üzerinize olabildiğince yükseğe fırlatın.", "Top aşağı inerken iki elinizle yakalayın."]', 'plyometrics', '["Supine_Chest_Throw/0.jpg", "Supine_Chest_Throw/1.jpg"]', 480.0, 'Supine Chest Throw', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('cfbd3435-537c-5bb4-97e5-167af7081a08', 'free-exercise-db', 'Supine_One-Arm_Overhead_Throw', 'Sırtüstü Tek Kol Baş Üstü Atış (Top)', 'pull', 'beginner', 'compound', '["medicine ball"]', '["abdominals"]', '["chest", "lats", "shoulders"]', '["Dizleriniz bükülü şekilde yerde sırtüstü uzanın. Topu bir elinizle tutun ve kolunuzu başınızın arkasına tamamen uzatın. Bu sizin başlangıç pozisyonunuzdur.", "Hareketi omuzdan başlatın; oturarak topu tam önünüze doğru fırlatın ve maksimum mesafeyi hedefleyin.", "Top bir partnere atılabilir veya duvardan sektirilebilir."]', 'plyometrics', '["Supine_One-Arm_Overhead_Throw/0.jpg", "Supine_One-Arm_Overhead_Throw/1.jpg"]', 480.0, 'Supine One-Arm Overhead Throw', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9fd53cf2-c5ea-58ff-ba70-88c95c7a9455', 'free-exercise-db', 'Supine_Two-Arm_Overhead_Throw', 'Sırtüstü İki Kol Baş Üstü Fırlatma (Medicine Ball)', 'pull', 'beginner', 'compound', '["medicine ball"]', '["abdominals"]', '["chest", "lats", "shoulders"]', '["Dizleriniz bükülü şekilde yerde sırtüstü uzanın.", "Topu iki elinizle tutun ve kollarınızı başınızın arkasında tamamen uzatın. Bu sizin başlangıç pozisyonunuzdur.", "Hareketi omuzdan başlatın; otururken topu tam önünüze, maksimum mesafeyi hedefleyerek fırlatın.", "Top bir partnere atılabilir veya bir duvardan sektirilebilir."]', 'plyometrics', '["Supine_Two-Arm_Overhead_Throw/0.jpg", "Supine_Two-Arm_Overhead_Throw/1.jpg"]', 480.0, 'Supine Two-Arm Overhead Throw', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c7f97c1a-0c71-510b-a884-30d97eb4d79b', 'free-exercise-db', 'Suspended_Fallout', 'Askıda Fallout (TRX)', 'pull', 'intermediate', 'isolation', '["other"]', '["abdominals"]', '["chest", "lower back", "shoulders"]', '["Kayışları, sapların bel seviyesinin altında uygun bir yükseklikte olacak şekilde ayarlayın.", "Ayakta durarak ve sapları kavrayarak başlayın. Kayışlara doğru yaslanarak incline şınav pozisyonuna geçin. Bu sizin başlangıç pozisyonunuz olacak.", "Kollarınızı düz tutarak, askı kayışlarına daha fazla yaslanın; vücudunuzu yere yaklaştırın, omuzlarınızın açılmasına ve kollarınızın yukarı ve başınızın üzerine kalkmasına izin verin.", "Nötr bir omurgayı koruyun ve vücudunuzun geri kalanını düz tutun; hareket etmesine izin verilen tek eklem omuzlarınız olmalıdır.", "En yüksek kasılma noktasında duraklayın, ardından başlangıç pozisyonuna dönün."]', 'strength', '["Suspended_Fallout/0.jpg", "Suspended_Fallout/1.jpg"]', 360.0, 'Suspended Fallout', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4567492a-20e5-57aa-8fb4-fab0faca6b04', 'free-exercise-db', 'Suspended_Push-Up', 'Askılı Şınav (TRX)', 'push', 'beginner', 'compound', '["other"]', '["chest"]', '["shoulders", "triceps"]', '["Süspansiyon kayışlarınızı bir rafın üstüne ya da başka bir nesneye güvenli bir şekilde sabitleyin.", "Kayışlara doğru yaslanarak her elinize bir tutamak alın ve şınav plank pozisyonuna geçin. İyi bir duruşu koruyarak kollarınız tamamen uzanmışken başarabildiğiniz kadar yere paralel olmalısınız.", "Gövdenizi düz ve sert tutarak, dirseklerinizin bükülmesine izin vererek yavaşça inin.", "Dirsekleriniz 90 dereceyi geçene kadar devam edin; başlangıç pozisyonuna dönmek için açmadan önce bekleyin."]', 'strength', '["Suspended_Push-Up/0.jpg", "Suspended_Push-Up/1.jpg"]', 360.0, 'Suspended Push-Up', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ed094e6b-58f9-542b-bc3a-9e630dd8a6df', 'free-exercise-db', 'Suspended_Reverse_Crunch', 'Reverse Crunch (Askı İpi)', 'pull', 'beginner', 'isolation', '["other"]', '["abdominals"]', '[]', '["Bir çift askı ipini, tutamaklar yerden yaklaşık bir fit (30 cm) yukarıda sarkacak şekilde sabitleyin. Rafa arkanız dönük şekilde şınav plank pozisyonuna geçin.", "Ayaklarınızı tutamaklara yerleştirin. Düz bir duruşu korumalı ve kalçanızın sarkmasına izin vermemelisiniz. Bu sizin başlangıç pozisyonunuzdur.", "Dizlerinizi ve kalçanızı bükerek, dizlerinizi gövdenize doğru çekerek harekete başlayın. Bunu yaparken pelvisinizi öne doğru eğin ve omurganızın bükülmesine izin verin.", "Kontrollü hareketin üst noktasında başlangıç pozisyonuna dönün."]', 'strength', '["Suspended_Reverse_Crunch/0.jpg", "Suspended_Reverse_Crunch/1.jpg"]', 360.0, 'Suspended Reverse Crunch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ff682978-8953-5a0e-9154-b094acfbd62b', 'free-exercise-db', 'Suspended_Row', 'Askılı Row (TRX)', 'pull', 'beginner', 'compound', '["other"]', '["middle back"]', '["biceps", "lats"]', '["Kayışlarınızı yaklaşık göğüs hizasında asın. Her elinizle bir tutacak alın ve geriye yaslanın. Vücudunuzu dik, başınızı ve göğsünüzü yukarıda tutun. Kollarınız tamamen uzamış olmalıdır. Bu sizin başlangıç pozisyonunuz olacaktır.", "Harekete başlamak için dirseğinizi bükün. Bunu yaparken kürek kemiklerinizi geriye çekin.", "Hareketin sonunda duraklayın ve ardından başlangıç pozisyonuna dönün."]', 'strength', '["Suspended_Row/0.jpg", "Suspended_Row/1.jpg"]', 360.0, 'Suspended Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('453a55b6-0830-5764-be95-37dceaaa86cd', 'free-exercise-db', 'Suspended_Split_Squat', 'Askıda Split Squat (Askı ile)', 'push', 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["abductors", "adductors", "calves", "glutes", "hamstrings"]', '["Askılarınızı, saplar yerden 18-30 inç (yaklaşık 45-75 cm) yüksekte olacak şekilde asın.", "Düzenekten uzağa bakarak arka ayağınızı arkanızdaki sapa yerleştirin. Başınız öne bakacak, göğsünüz yukarıda ve diziniz hafif bükülü olacak şekilde durun. Bu sizin başlangıç pozisyonunuzdur.", "Diz ve kalçanızı bükerek kendinizi yere doğru indirin. Ağırlığınızı ayağınızın topuğunda tutun ve egzersiz boyunca duruşunuzu koruyun.", "Hareketin en alt noktasında, hareketi tersine çevirin; kalça ve dizinizi açarak başlangıç pozisyonuna dönün."]', 'strength', '["Suspended_Split_Squat/0.jpg", "Suspended_Split_Squat/1.jpg"]', 360.0, 'Suspended Split Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9b65fb8a-cac4-5ea4-bab2-17564cd61e7d', 'free-exercise-db', 'Svend_Press', 'Svend Press (Plaka)', 'push', 'beginner', 'compound', '["other"]', '["chest"]', '["forearms", "shoulders", "triceps"]', '["Ayakta duruş pozisyonunda başlayın.", "İki hafif plakayı ellerinizle birbirine bastırın. Göğüs kaslarınızda izometrik bir kasılma yaratmak için plakaları göğsünüze yakın tutun. Parmaklarınız öne bakmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Plakaları avuç içlerinizin arasında sıkın ve kollarınızı kontrollü bir hareketle doğrudan önünüze uzatın.", "Hareketin üst noktasında bekleyin, ardından yavaşça başlangıç pozisyonuna dönün."]', 'strength', '["Svend_Press/0.jpg", "Svend_Press/1.jpg"]', 360.0, 'Svend Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('e832626a-9a8e-5544-9dde-8856923acff8', 'free-exercise-db', 'T-Bar_Row_with_Handle', 'T-Bar Row (Tutamaklı)', 'pull', 'beginner', 'compound', '["barbell"]', '["middle back"]', '["biceps", "lats"]', '["Barı bir landmine aparatına ya da hareket etmemesi için bir köşeye yerleştirin. Kendi ucunuza uygun ağırlığı yükleyin.", "Barın üzerinde durun ve bir Double D row tutamağını plaka tutucunun (collar) yanında barın etrafına yerleştirin. Kalçanızı ve bacaklarınızı kullanarak ayağa kalkın.", "Kalçanız geride ve göğsünüz yukarıda olacak şekilde geniş bir duruş alın. Kollarınız uzanmış olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Kürek kemiklerinizi geriye çekerek ve dirseklerinizi bükerek ağırlığı üst karnınıza doğru çekin. Hareket sırasında ağırlığı savurmayın veya hile yapmayın.", "Kısa bir beklemeden sonra başlangıç pozisyonuna dönün."]', 'strength', '["T-Bar_Row_with_Handle/0.jpg", "T-Bar_Row_with_Handle/1.jpg"]', 360.0, 'T-Bar Row with Handle', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9031ad1f-30a0-5200-bb25-fb85edeb0e46', 'free-exercise-db', 'Tate_Press', 'Tate Press (Dambıl)', 'push', 'intermediate', 'isolation', '["dumbbell"]', '["triceps"]', '["chest", "shoulders"]', '["Her elinizde bir dambıl uyluklarınızın üzerinde olacak şekilde düz bir bench''e uzanın. Avuç içleriniz birbirine bakacaktır.", "Dambılları yukarı kaldırmak için uyluklarınızdan destek alarak, dambılları omuz genişliğinde önünüzde tutabilmeniz için bir seferde bir kolla kaldırın (clean). Not: Dambılları önünüzde tutarken, kollarınızın pronasyon (avuç içleri öne bakan) tutuşla omuz genişliğinden daha geniş olduğundan emin olun. Dirseklerinizin dışarı bakmasına izin verin. Bu sizin başlangıç pozisyonunuzdur.", "Üst kollarınızı sabit tutarak, nefes alırken dambılları yarım daire hareketiyle yavaşça içeri ve aşağı, üst göğsünüze değene kadar hareket ettirin. Dambıllar üzerinde her zaman tam kontrolü koruyun ve üst kolları hareket ettirmeyin veya dambılları göğüs üzerinde dinlendirmeyin.", "Nefes verirken triceps''inizi kullanarak aynı yarım daire hareketiyle ancak ters yönde dambılları yukarı hareket ettirin. Yukarı çıkarken dambılları birbirine yakın tutmaya çalışın. Kasılmış pozisyonda kollarınızı kilitleyin, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: Aşağı inmek, yukarı çıkmaktan en az iki kat daha uzun sürmelidir.", "Hareketi antrenman programınızdaki belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Tate_Press/0.jpg", "Tate_Press/1.jpg"]', 360.0, 'Tate Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('74ca6f74-99cf-532d-b5c1-fbdba341e40c', 'free-exercise-db', 'The_Straddle', 'Straddle Esnetme (Bacak Açma)', 'static', 'beginner', NULL, '[]', '["hamstrings"]', '["adductors", "calves"]', '["Oturarak, dik bir pozisyonda başlayın. Bacaklarınızı önünüzde V şeklinde uzatarak başlayın.", "Ellerinizi yere koyarak olabildiğince öne doğru eğilin. 10 ila 20 saniye bekleyin."]', 'stretching', '["The_Straddle/0.jpg", "The_Straddle/1.jpg"]', 150.0, 'The Straddle', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a32d845f-6502-58e9-abea-c876085c4f44', 'free-exercise-db', 'Thigh_Abductor', 'Hip Abduction (Makine)', 'push', 'beginner', 'isolation', '["machine"]', '["abductors"]', '["glutes"]', '["Başlamak için abduktör makinesine oturun ve rahat edeceğiniz bir ağırlık seçin. Bacaklarınız doğru konumlandırıldığında her iki yandaki tutamakları kavrayın. Tüm üst vücudunuz (belden yukarısı) sabit kalmalıdır. Bu başlangıç pozisyonudur.", "Nefes verirken bacaklarınızı birbirinden uzaklaştırmak için makineye karşı yavaşça bastırın.", "Kasılmayı bir saniye hissedin ve nefes alırken bacaklarınızı başlangıç pozisyonuna geri getirmeye başlayın. Not: Herhangi bir sakatlığı önlemek için üst vücudunuzu sabit tuttuğunuzdan emin olun.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Thigh_Abductor/0.jpg", "Thigh_Abductor/1.jpg"]', 360.0, 'Thigh Abductor', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0a3a93bb-f784-59ad-965f-76a50041866a', 'free-exercise-db', 'Thigh_Adductor', 'İç Bacak (Adduktör) Makinesi', 'pull', 'beginner', 'isolation', '["machine"]', '["adductors"]', '["glutes", "hamstrings"]', '["Başlamak için adduktör makinesine oturun ve rahat edeceğiniz bir ağırlık seçin. Bacaklarınız makinenin bacak minderlerine düzgün şekilde yerleştirildiğinde, her iki taraftaki sapları kavrayın. Tüm üst vücudunuz (belden yukarısı) sabit olmalıdır. Bu başlangıç pozisyonudur.", "Nefes verirken bacaklarınızı birbirine doğru hareket ettirmek için makineye karşı yavaşça bastırın.", "Kasılmayı bir saniye hissedin ve nefes alırken bacaklarınızı başlangıç pozisyonuna geri hareket ettirmeye başlayın. Not: Herhangi bir sakatlanmayı önlemek için üst vücudunuzu sabit tutmayı ve hızlı sarsıcı hareketlerden kaçınmayı unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Thigh_Adductor/0.jpg", "Thigh_Adductor/1.jpg"]', 360.0, 'Thigh Adductor', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8c49ced6-02df-5bea-843a-56a9aa2e4ef2', 'free-exercise-db', 'Tire_Flip', 'Lastik Çevirme (Tire Flip)', 'pull', 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["calves", "chest", "forearms", "glutes", "hamstrings", "lower back", "shoulders", "traps", "triceps"]', '["Lastiğin alt kısmını sırt (diş) kısmından kavrayarak başlayın ve ayaklarınızı biraz geriye konumlandırın. Göğsünüz lastiğe doğru itmeli.", "Lastiği kaldırmak için kalçanızı, dizlerinizi ve ayak bileklerinizi açın; lastiğe ve yukarı doğru itin.", "Lastik 45 derecelik bir açıya ulaştığında, öne adım atın ve bir dizinizi lastiğe sürün. Bunu yaparken tutuşunuzu lastiğin üst kısmına ayarlayın ve çevirmeyi tamamlamak için lastiği olabildiğince sert bir şekilde öne doğru itin. Gerektiği kadar tekrarlayın."]', 'strongman', '["Tire_Flip/0.jpg", "Tire_Flip/1.jpg"]', 480.0, 'Tire Flip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ae417e2a-77ab-5b4e-8e95-35b64ed3111c', 'free-exercise-db', 'Toe_Touchers', 'Parmak Ucuna Dokunma (Yerde)', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Başlamak için sırtınız yere bastırılmış şekilde yerde veya egzersiz matında uzanın. Kollarınız avuç içleri aşağı bakacak şekilde yanlarınızda uzanıyor olmalıdır.", "Bacaklarınız birbirine değiyor olmalıdır. Bacaklarınızı dizlerde hafif bükülü olacak şekilde yere neredeyse dik olana kadar yavaşça havaya kaldırın. Ayaklarınız yere paralel olmalıdır.", "Kollarınızı yerden 45 derecelik açıyla tamamen uzatılacak şekilde hareket ettirin. Bu başlangıç pozisyonudur.", "Belinizi yere bastırılı tutarak gövdenizi yavaşça kaldırın ve ellerinizle ayak parmaklarınıza dokunmaya çalışın. Egzersizin bu kısmını yaparken nefes vermeyi unutmayın.", "Nefes alırken gövdenizi ve kollarınızı yavaşça başlangıç pozisyonuna indirmeye başlayın. Kollarınızı ayak parmaklarınıza doğru düz tutmayı unutmayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'stretching', '["Toe_Touchers/0.jpg", "Toe_Touchers/1.jpg"]', 150.0, 'Toe Touchers', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('43619da3-455b-52fc-899b-03de3a35caf7', 'free-exercise-db', 'Torso_Rotation', 'Gövde Rotasyonu (Pilates Topu)', 'pull', 'beginner', NULL, '["exercise ball"]', '["abdominals"]', '[]', '["Bir egzersiz topunu iki elinizle tutarak dik durun. Top tam önünüzde olacak şekilde kollarınızı uzatın. Bu sizin başlangıç pozisyonunuzdur.", "Hareket ederken gözlerinizi topta tutarak gövdenizi bir yana doğru döndürün. Şimdi ters yöne geri dönün. 10-20 tekrar yapın."]', 'stretching', '["Torso_Rotation/0.jpg", "Torso_Rotation/1.jpg"]', 150.0, 'Torso Rotation', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('059571f7-1812-5dd6-99ee-8e54d0d82ec2', 'free-exercise-db', 'Trail_Running_Walking', 'Patika Koşusu / Yürüyüşü', NULL, 'beginner', NULL, '[]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Patikalarda koşmak veya yürümek, kanı neredeyse anında pompalar ve kalbi hızlandırır. İyi ayakkabılarınızın olduğundan emin olun. Bir yokuşu çıkmak için baldır ve kalça kaslarınızı kullanırken, aşağı inerken darbenin büyük kısmını dizler, eklemler ve ayak bilekleri emer. Yokuş aşağı yürürken daha küçük adımlar atın, darbeyi azaltmak için dizlerinizi bükülü tutun ve düşmemek için yavaşlayın.", "68 kg ağırlığındaki bir kişi yokuş yukarı yürüyerek 30 dakikada 200 kaloriden fazla yakabilir; düz zeminde bu 175 kaloridir. Patikada koşuluyorsa 68 kg''lık bir kişi 30 dakikada 500 kaloriden çok daha fazlasını yakabilir."]', 'cardio', '["Trail_Running_Walking/0.jpg", "Trail_Running_Walking/1.jpg"]', 600.0, 'Trail Running/Walking', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('70e106ac-0f3c-5aba-a4c9-80793ed176dd', 'free-exercise-db', 'Trap_Bar_Deadlift', 'Deadlift (Trap Bar)', 'pull', 'beginner', 'compound', '["other"]', '["quadriceps"]', '["glutes", "hamstrings"]', '["Bu egzersiz için hex bar olarak da bilinen bir trap bar''ı, yerde duracak şekilde uygun bir ağırlıkla yükleyin. Aparatın ortasında durun ve her iki tutamağı kavrayın.", "Kalçanızı alçaltın, başınızla ileriye bakın ve göğsünüzü yukarıda tutun.", "Topuklarınızdan iterek ve kalçanızı ve dizlerinizi açarak harekete başlayın. Her zaman sırtınızı yuvarlamaktan kaçının.", "Hareketin sonunda ağırlığı kontrollü bir şekilde yere geri indirin."]', 'strength', '["Trap_Bar_Deadlift/0.jpg", "Trap_Bar_Deadlift/1.jpg"]', 360.0, 'Trap Bar Deadlift', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5d878157-ce77-56a1-9eae-d4434aac203f', 'free-exercise-db', 'Tricep_Dumbbell_Kickback', 'Triceps Kickback (Dambıl)', 'push', 'beginner', 'isolation', '["dumbbell"]', '["triceps"]', '[]', '["Her elinizde birer dambıl ve avuç içleriniz gövdenize bakacak şekilde başlayın. Sırtınızı düz tutun, dizlerinizi hafif bükün ve belinizden öne eğilin. Gövdeniz neredeyse yere paralel olmalıdır. Başınızı yukarıda tuttuğunuzdan emin olun. Üst kollarınız gövdenize yakın ve yere paralel olmalıdır. Ağırlıkları tutarken ön kollarınız yere doğru bakmalıdır. Ön kol ile üst kol arasında 90 derecelik bir açı oluşmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi üst kollarınızı sabit tutarak nefes verin ve kol tamamen uzanana kadar ağırlıkları kaldırmak için triceps''inizi kullanın. Ön kolu hareket ettirmeye odaklanın.", "Üstteki kasılmada kısa bir beklemeden sonra nefes alın ve dambılları yavaşça başlangıç pozisyonuna indirin.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Tricep_Dumbbell_Kickback/0.jpg", "Tricep_Dumbbell_Kickback/1.jpg"]', 360.0, 'Tricep Dumbbell Kickback', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('96c54f0e-8e5f-561e-84ae-bc04bd5cce07', 'free-exercise-db', 'Tricep_Side_Stretch', 'Triceps Yan Esnetme', 'static', 'beginner', NULL, '[]', '["triceps"]', '["shoulders"]', '["Sağ kolunuzu vücudunuzun önünden sol omzunuzun üzerine getirin ve triceps''inizde bir gerilme hissedene kadar dirseğinizi sol elinizle tutun. Ardından diğer kolunuz için tekrarlayın."]', 'stretching', '["Tricep_Side_Stretch/0.jpg", "Tricep_Side_Stretch/1.jpg"]', 150.0, 'Tricep Side Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('316696bd-f42e-5391-9547-6f4fdadfe766', 'free-exercise-db', 'Triceps_Overhead_Extension_with_Rope', 'Baş Üstü Triceps Extension (Kablo, İp)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Bir ipi alçak makaraya bağlayın. Uygun bir ağırlık seçtikten sonra ipi iki elinizle kavrayın ve kabloya sırtınızı dönün.", "Ellerinizi başınızın arkasına, dirsekleriniz düz yukarı bakacak şekilde yerleştirin. Dirsekleriniz bükülü olarak başlamalı ve daha fazla denge için ayaklarınızı çapraz konumda tutabilir ve makineden hafifçe uzağa doğru yaslanabilirsiniz. Bu sizin başlangıç pozisyonunuz olacak.", "Hareketi gerçekleştirmek için üst kolu yerinde tutarak dirseği açın ve ellerinizi başınızın üzerine kaldırın.", "Hareketin üst noktasında triceps''inizi sıkın ve ağırlığı yavaşça başlangıç pozisyonuna indirin."]', 'strength', '["Triceps_Overhead_Extension_with_Rope/0.jpg", "Triceps_Overhead_Extension_with_Rope/1.jpg"]', 360.0, 'Triceps Overhead Extension with Rope', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d788b6b1-2d07-5d71-b815-a53551ab6c0d', 'free-exercise-db', 'Triceps_Pushdown', 'Triceps Pushdown (Kablo)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Yüksek bir makaraya düz veya açılı bir bar takın ve avuç içleri aşağı bakacak (overhand) tutuşla omuz genişliğinde kavrayın.", "Gövdeniz düz ve çok az öne eğik şekilde dik dururken, üst kollarınızı vücudunuza yakın ve yere dik hale getirin. Ön kollar barı tutarken makaraya doğru yukarıyı göstermelidir. Bu sizin başlangıç pozisyonunuzdur.", "Triceps''i kullanarak barı, uyluklarınızın önüne değene ve kollar yere dik şekilde tamamen uzanana kadar aşağı indirin. Üst kollar her zaman gövdenizin yanında sabit kalmalı ve yalnızca ön kollar hareket etmelidir. Bu hareketi yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra barı yavaşça başlangıç noktasına kaldırın. Bu adımı yaparken nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Triceps_Pushdown/0.jpg", "Triceps_Pushdown/1.jpg"]', 360.0, 'Triceps Pushdown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b501e6cb-44b5-5741-b025-ce9dedef46ce', 'free-exercise-db', 'Triceps_Pushdown_-_Rope_Attachment', 'Triceps Pushdown (Halat)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Bir halat aparatını yüksek makaraya takın ve nötr tutuşla (avuç içleri birbirine bakacak şekilde) kavrayın.", "Gövdeniz düz ve çok az öne eğik şekilde dik dururken üst kollarınızı vücudunuza yakın ve yere dik şekilde getirin. Ön kollar, halatı avuç içleri birbirine bakacak şekilde tutarken makaraya doğru yukarı bakıyor olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Triceps''i kullanarak halatı aşağı indirin ve halatın her iki ucunu uyluklarınızın yanlarına getirin. Hareketin sonunda kollar tamamen uzatılmış ve yere dik olmalıdır. Üst kollar her zaman gövdenizin yanında sabit kalmalı ve sadece ön kollar hareket etmelidir. Bu hareketi yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra halatı yavaşça başlangıç noktasına yukarı getirin. Bu adımı yaparken nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Triceps_Pushdown_-_Rope_Attachment/0.jpg", "Triceps_Pushdown_-_Rope_Attachment/1.jpg"]', 360.0, 'Triceps Pushdown - Rope Attachment', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('7baac1a0-be90-52db-aebf-bdd7092b320a', 'free-exercise-db', 'Triceps_Pushdown_-_V-Bar_Attachment', 'Triceps Pushdown (V-Bar)', 'push', 'beginner', 'isolation', '["cable"]', '["triceps"]', '[]', '["Bir V-Bar''ı üst makaraya takın ve omuz genişliğinde üsten tutuşla (avuç içleri aşağı bakan) kavrayın.", "Gövdeniz dik ve çok hafif öne eğik olacak şekilde ayakta dururken üst kollarınızı vücudunuza yakın ve yere dik hale getirin. Ön kollar barı tutarken makaraya doğru yukarı bakmalıdır. Başparmaklar küçük parmaktan daha yüksekte olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Triceps''i kullanarak, bar uyluklarınızın önüne değene ve kollar yere dik olarak tamamen uzayana kadar barı aşağı indirin. Üst kollar her zaman gövdenizin yanında sabit kalmalı ve yalnızca ön kollar hareket etmelidir. Bu hareketi yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra V-Bar''ı yavaşça başlangıç noktasına getirin. Bu adımı yaparken nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Triceps_Pushdown_-_V-Bar_Attachment/0.jpg", "Triceps_Pushdown_-_V-Bar_Attachment/1.jpg"]', 360.0, 'Triceps Pushdown - V-Bar Attachment', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d1cec9d1-1136-534b-84b8-e7c98d3566d7', 'free-exercise-db', 'Triceps_Stretch', 'Triceps Esnetme', 'static', 'beginner', 'isolation', '[]', '["triceps"]', '["lats"]', '["Elinizi başınızın arkasına uzatın, dirseğinizi kavrayın ve nazikçe çekin. 10-20 saniye bekleyin, ardından taraf değiştirin."]', 'stretching', '["Triceps_Stretch/0.jpg", "Triceps_Stretch/1.jpg"]', 150.0, 'Triceps Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fd6bddd3-c62a-52ba-ad7a-7c92b5fc1753', 'free-exercise-db', 'Tuck_Crunch', 'Tuck Crunch (Bacak Çaprazlamalı Mekik)', 'pull', 'beginner', 'isolation', '["body only"]', '["abdominals"]', '[]', '["Başlamak için sırtınız yere bastırılmış şekilde yerde veya bir egzersiz matında uzanın. Kollarınız yanlarınızda, avuç içleri aşağı bakacak şekilde durmalıdır.", "Bir ayak bileğini diğerine dolayarak bacaklarınızı çaprazlayın. Uyluklarınız yere dik ve dizleriniz hafif bükülü olana kadar bacaklarınızı yavaşça havaya kaldırın. Not: Uyluklarınız değil, dizleriniz ve ayak parmaklarınız yere paralel olmalıdır.", "Kollarınızı yerden kaldırın ve göğsünüzün üzerinde dinlenecek şekilde çaprazlayın. Bu başlangıç pozisyonudur.", "Alt belinizi yere bastırılmış tutarken gövdenizi yavaşça kaldırın. Egzersizin bu kısmını yaparken nefes vermeyi unutmayın.", "Nefes alırken gövdenizi yavaşça başlangıç pozisyonuna indirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Tuck_Crunch/0.jpg", "Tuck_Crunch/1.jpg"]', 360.0, 'Tuck Crunch', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('cac4b8cb-da84-5f34-956d-8ddd3878dccb', 'free-exercise-db', 'Two-Arm_Dumbbell_Preacher_Curl', 'Çift Kol Preacher Curl (Dambıl)', 'pull', 'beginner', 'isolation', '["dumbbell"]', '["biceps"]', '[]', '["Her kolunuzla bir dambıl kavrayın ve üst kollarınızı preacher sehpasının veya incline sehpanın üzerine koyun. Dambıl omuz uzaklığında tutulmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken üst kolunuz uzayana ve biceps''iniz tamamen gerilene kadar dambılları yavaşça indirin.", "Nefes verirken biceps''iniz tamamen kasılana ve dambıllar omuz yüksekliğine gelene kadar biceps''i kullanarak ağırlıkları kıvırın.", "Kasılmış pozisyonda biceps''inizi bir saniye sertçe sıkın ve önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Two-Arm_Dumbbell_Preacher_Curl/0.jpg", "Two-Arm_Dumbbell_Preacher_Curl/1.jpg"]', 360.0, 'Two-Arm Dumbbell Preacher Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0e524e50-10b3-5bd9-bcb1-4dc7f92dcade', 'free-exercise-db', 'Two-Arm_Kettlebell_Clean', 'Çift Kol Clean (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["calves", "glutes", "hamstrings", "lower back", "traps"]', '["İki kettlebell''i ayaklarınızın arasına koyun. Başlangıç pozisyonuna geçmek için kalçanızı geriye itin ve düz ileri bakın.", "Bacaklarınızı ve kalçanızı açarak kettlebell''leri omuzlarınıza doğru kaldırıp omuzlarınıza getirin. Bunu yaparken bileklerinizi döndürün.", "Kettlebell''leri başlangıç pozisyonuna geri indirin ve tekrarlayın."]', 'strength', '["Two-Arm_Kettlebell_Clean/0.jpg", "Two-Arm_Kettlebell_Clean/1.jpg"]', 360.0, 'Two-Arm Kettlebell Clean', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('be965bea-05ca-5684-a726-66f4be7d1f46', 'free-exercise-db', 'Two-Arm_Kettlebell_Jerk', 'İki Kol Jerk (Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["calves", "quadriceps", "triceps"]', '["İki kettlebell''i omuzlarınıza kaldırın (clean). Kettlebell''leri omuzlarınıza doğru savururken bacaklarınızı ve kalçanızı açarak omuzlarınıza kaldırın. Bunu yaparken avuç içleri öne bakacak şekilde bileklerinizi döndürün. Birkaç inç çömelin ve hareketi hızla tersine çevirerek her iki kettlebell''i baş üstüne itin. İlk itişten hemen sonra tekrar çömelin ve kettlebell''lerin altına girin. Kettlebell''ler kilitlendikten sonra, egzersizi tamamlamak için dik durun."]', 'strength', '["Two-Arm_Kettlebell_Jerk/0.jpg", "Two-Arm_Kettlebell_Jerk/1.jpg"]', 360.0, 'Two-Arm Kettlebell Jerk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('6a8f21b8-96bb-5464-94f4-925073748028', 'free-exercise-db', 'Two-Arm_Kettlebell_Military_Press', 'Askeri Press (Çift Kettlebell)', 'push', 'intermediate', 'compound', '["kettlebells"]', '["shoulders"]', '["triceps"]', '["İki kettlebell''i omuzlarınıza clean yapın. Kettlebell''leri omuzlarınıza doğru savurarak bacaklarınızı ve kalçanızı açıp omuzlarınıza clean yapın. Bunu yaparken bileklerinizi, avuç içleriniz öne bakacak şekilde döndürün.", "Kettlebell''leri yukarı ve dışarı doğru itin. Kettlebell''ler başınızı geçerken, kettlebell''lerin başınızın arkasında rack pozisyonunda durması için ağırlıklara doğru yaslanın. Ek stabilite için latissimus kaslarınızı, kalçanızı ve karnınızı kastığınızdan emin olun."]', 'strength', '["Two-Arm_Kettlebell_Military_Press/0.jpg", "Two-Arm_Kettlebell_Military_Press/1.jpg"]', 360.0, 'Two-Arm Kettlebell Military Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1cb65bc9-5ae6-508e-9a12-fd6cfb5aff6c', 'free-exercise-db', 'Two-Arm_Kettlebell_Row', 'Çift Kol Row (Kettlebell)', 'pull', 'intermediate', 'compound', '["kettlebells"]', '["middle back"]', '["biceps", "lats"]', '["İki kettlebell''i ayaklarınızın önüne koyun. Başlangıç pozisyonuna geçmek için dizlerinizi hafifçe bükün ve ardından öne eğilirken kalçanızı mümkün olduğunca geriye itin.", "Her iki kettlebell''i de kavrayın ve kürek kemiklerinizi geriye çekerek ve dirseklerinizi bükerek karnınıza doğru çekin. Sırtınızı düz tutun. İndirin ve tekrarlayın."]', 'strength', '["Two-Arm_Kettlebell_Row/0.jpg", "Two-Arm_Kettlebell_Row/1.jpg"]', 360.0, 'Two-Arm Kettlebell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('766c7568-9edf-5ab5-821d-495c93071677', 'free-exercise-db', 'Underhand_Cable_Pulldowns', 'Lat Pulldown (Kablo, Ters Tutuş)', 'pull', 'beginner', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Üst makaraya geniş bir bar bağlı pulldown makinesine oturun. Makinenin diz pedini boyunuza göre ayarlayın. Bu pedler, bara bağlı direncin vücudunuzu yukarı kaldırmasını önleyecektir.", "Pulldown barını avuç içleri gövdenize bakacak şekilde (supine tutuş) kavrayın. Ellerinizin omuz genişliğinden daha dar yerleştirildiğinden emin olun.", "Her iki kolunuz önünüzde uzamış ve bar seçtiğiniz tutuş genişliğinde tutulurken, gövdenizi yaklaşık 30 derece kadar geriye alın, bunu yaparken alt sırtınızda bir kavis oluşturun ve göğsünüzü dışarı çıkarın. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken omuzlarınızı ve üst kollarınızı aşağı ve geriye doğru çekerek bar üst göğsünüze değene kadar barı aşağı çekin. İpucu: Tam kasılma pozisyonuna ulaştığınızda sırt kaslarınızı sıkmaya odaklanın ve dirseklerinizi vücudunuza yakın tutun. Barı kendinize getirirken üst gövde sabit kalmalı ve yalnızca kollar hareket etmelidir. Ön kollar barı tutmaktan başka bir iş yapmamalıdır.", "Kasılmış pozisyonda bir saniye bekledikten sonra, nefes alırken barı yavaşça kollarınız tamamen uzayana ve lat kaslarınız tamamen gerilene kadar başlangıç pozisyonuna getirin.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Underhand_Cable_Pulldowns/0.jpg", "Underhand_Cable_Pulldowns/1.jpg"]', 360.0, 'Underhand Cable Pulldowns', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d5f95892-cbca-5aa8-be1e-91401c0a0c51', 'free-exercise-db', 'Upper_Back-Leg_Grab', 'Oturarak Üst Sırt Esnetme (Bacak Sarma)', 'static', 'beginner', NULL, '[]', '["hamstrings"]', '["lower back", "middle back"]', '["Otururken öne eğilin ve her iki kolunuzla uyluklarınızı alttan sarın.", "Dizlerinizi bitişik ve bacaklarınızı uzamış tutarak göğsünüzü dizlerinize doğru indirin. Dizlerinize sarılırken sırtınızı dizlerinizden uzağa çekerek orta sırtınızı da esnetebilirsiniz."]', 'stretching', '["Upper_Back-Leg_Grab/0.jpg", "Upper_Back-Leg_Grab/1.jpg"]', 150.0, 'Upper Back-Leg Grab', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('0d1daa0d-4fcb-5587-ab8d-3c1109c0765b', 'free-exercise-db', 'Upper_Back_Stretch', 'Üst Sırt Esnetme', 'static', 'beginner', NULL, '[]', '["middle back"]', '["middle back"]', '["Başparmaklarınız aşağı bakacak şekilde parmaklarınızı birbirine kenetleyin, ellerinizi öne doğru uzatırken omuzlarınızı yuvarlayın."]', 'stretching', '["Upper_Back_Stretch/0.jpg", "Upper_Back_Stretch/1.jpg"]', 150.0, 'Upper Back Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('76f318dc-4814-5ec9-80ef-0f4fd01d2112', 'free-exercise-db', 'Upright_Barbell_Row', 'Upright Row (Halter)', 'pull', 'beginner', 'compound', '["barbell"]', '["shoulders"]', '["traps"]', '["Halteri omuz genişliğinden biraz daha dar bir üsten tutuşla kavrayın. Bar uyluklarınızın üzerinde dururken kollarınız uzanmış ve dirsekleriniz hafif bükülü olmalıdır. Sırtınız da düz olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes verin ve dirseklerinizi yukarı ve yana kaldırarak barı kaldırmak için omuzlarınızın yan kısımlarını kullanın. Barı kaldırırken vücudunuza yakın tutun. Bar çenenize neredeyse değene kadar kaldırmaya devam edin. İpucu: Hareketi dirsekleriniz yönlendirmeli ve dirsekler her zaman ön kollardan daha yüksekte olmalıdır. Gövdenizi sabit tutmayı ve hareketin tepesinde bir saniye beklemeyi unutmayın.", "Barı yavaşça başlangıç pozisyonuna indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Upright_Barbell_Row/0.jpg", "Upright_Barbell_Row/1.jpg"]', 360.0, 'Upright Barbell Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c8bb6e0e-4256-5d5a-adeb-4fbe53625d9c', 'free-exercise-db', 'Upright_Cable_Row', 'Upright Row (Kablo)', 'pull', 'intermediate', 'compound', '["cable"]', '["traps"]', '["shoulders"]', '["Alçak bir makaraya bağlı düz bar kablo aparatını, omuz genişliğinden biraz daha dar, pronasyon (avuç içleri uyluklarınıza bakacak şekilde) tutuşla kavrayın. Bar uyluklarınızın üzerinde durmalı. Kollarınız dirseklerde hafif bir bükülmeyle uzanmış ve sırtınız düz olmalı. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes verirken kablo barını kaldırmak için yan omuz kaslarınızı kullanın. Bar yukarı hareket ederken vücuda yakın olmalı. Çenenize neredeyse değene kadar kaldırmaya devam edin. İpucu: Hareketi dirsekleriniz yönlendirmeli. Barı kaldırırken dirsekleriniz her zaman ön kollarınızdan daha yüksekte olmalı. Ayrıca gövdenizi sabit tutun ve hareketin üst noktasında bir saniye duraklayın.", "Barı yavaşça başlangıç pozisyonuna indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Upright_Cable_Row/0.jpg", "Upright_Cable_Row/1.jpg"]', 360.0, 'Upright Cable Row', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('fcba50d9-0a5e-5d48-89fa-58ed859f2f5a', 'free-exercise-db', 'Upright_Row_-_With_Bands', 'Upright Row (Direnç Bandı)', 'pull', 'beginner', 'compound', '["bands"]', '["traps"]', '["shoulders"]', '["Başlamak için, gerginlik kol boyunda başlayacak şekilde bir egzersiz bandının üzerinde durun. Sapları pronated (avuç içleri uyluklarınıza bakacak şekilde) omuz genişliğinden biraz daha dar bir tutuşla kavrayın. Saplar uyluklarınızın üzerinde dinleniyor olmalıdır. Kollarınız dirsekler hafif bükülü şekilde uzatılmış ve sırtınız düz olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken sapları kaldırmak için yan omuz kaslarınızı kullanın. Saplar yukarı hareket ederken vücuda yakın olmalıdır. Saplar neredeyse çenenize değene kadar kaldırmaya devam edin. İpucu: Hareketi dirsekleriniz yönlendirmelidir. Sapları kaldırırken dirsekleriniz her zaman ön kollarınızdan daha yukarıda olmalıdır. Ayrıca gövdenizi sabit tutun ve hareketin en üstünde bir saniye bekleyin.", "Sapları yavaşça başlangıç pozisyonuna indirin. Hareketin bu kısmında nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Upright_Row_-_With_Bands/0.jpg", "Upright_Row_-_With_Bands/1.jpg"]', 360.0, 'Upright Row - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('eb35e09c-c2e6-5f1e-b329-12b52c8511e4', 'free-exercise-db', 'Upward_Stretch', 'Yukarı Doğru Esnetme', 'static', 'beginner', NULL, '[]', '["shoulders"]', '["chest", "lats"]', '["Her iki elinizi avuç içleriniz birbirine değecek şekilde başınızın üzerine dümdüz uzatın.", "Sırtınızı düz tutarak ellerinizi yavaşça yukarı ve geriye doğru itin."]', 'stretching', '["Upward_Stretch/0.jpg", "Upward_Stretch/1.jpg"]', 150.0, 'Upward Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('9787d288-ac3c-565d-84da-4ca4286ca5c8', 'free-exercise-db', 'V-Bar_Pulldown', 'Pulldown (V-Bar)', 'pull', 'intermediate', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Üst makaraya bir V-Bar takılı bir pulldown makinesine oturun.", "Makinenin diz pedini boyunuza göre ayarlayın. Bu pedler, bara bağlı direncin vücudunuzu yukarı kaldırmasını önleyecektir.", "V-Bar''ı avuç içleri birbirine bakacak şekilde (nötr tutuş) kavrayın. Latissimus kaslarını daha iyi devreye sokmak için göğsünüzü dışarı çıkarın ve kendinizi hafifçe (yaklaşık 30 derece) geriye yaslayın. Bu sizin başlangıç pozisyonunuz olacaktır.", "Latissimus kaslarınızı kullanarak, kürek kemiklerinizi sıkarken barı aşağı çekin. Göğsünüz V-Bar''a neredeyse değene kadar devam edin. Bu hareketi yaparken nefes verin. İpucu: Hareket boyunca gövdenizi sabit tutun.", "Kasılmış pozisyonda bir saniye tuttuktan sonra, nefes alırken barı yavaşça başlangıç pozisyonuna geri getirin.", "Belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["V-Bar_Pulldown/0.jpg", "V-Bar_Pulldown/1.jpg"]', 360.0, 'V-Bar Pulldown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d296db3b-593c-5534-b9bf-f9bd60f8ef3b', 'free-exercise-db', 'V-Bar_Pullup', 'Barfiks (V-Bar)', 'pull', 'beginner', 'compound', '["body only"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["V-bar''ın ortasını barfiks barının ortasına yerleştirerek başlayın (kullandığınız barfiks istasyonunda nötr tutuş tutamaklarının olmadığını varsayarak). V-Bar tutamakları aşağı bakacaktır, böylece tutamaklar yardımıyla barfiks barından asılabilirsiniz.", "V-bar''ı sağlam şekilde yerleştirdikten sonra her iki yandan barı kavrayın ve asılın. Lat kaslarınızı daha iyi devreye sokmak için göğsünüzü öne çıkarın ve hafifçe geriye yaslanın. Bu sizin başlangıç pozisyonunuzdur.", "Lat kaslarınızı kullanarak gövdenizi yukarı çekin ve çene barına çarpmamak için başınızı hafifçe geriye atın. Göğsünüz V-bar''a neredeyse değene kadar devam edin. Bu hareketi yaparken nefes verin.", "Kasılmış pozisyonda bir saniye bekledikten sonra nefes alırken vücudunuzu yavaşça başlangıç pozisyonuna indirin.", "Belirtilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["V-Bar_Pullup/0.jpg", "V-Bar_Pullup/1.jpg"]', 360.0, 'V-Bar Pullup', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('70ceea87-2dd8-5b45-a672-d2dbe3067d87', 'free-exercise-db', 'Vertical_Swing', 'Dikey Swing (Dambıl)', 'pull', 'beginner', 'compound', '["dumbbell"]', '["hamstrings"]', '["glutes", "quadriceps", "shoulders"]', '["Dambılı iki elinizle tutarak bacaklarınızın arasında kol boyunda sarkmasına izin verin. Sırtınızı düz ve başınızı yukarıda tutun.", "Kalçanızdan bükülüp dizlerinizi hafifçe bükerek dambılı bacaklarınızın arasında savurun.", "Kendinizi yukarı fırlatmak için kalçanızı, dizlerinizi ve ayak bileklerinizi açarak hareketi güçlü bir şekilde tersine çevirin ve dambılı başınızın üzerine savurun.", "İnerken darbeyi bacaklarınızla sönümleyin ve bir sonraki tekrardan önce dambılı gövdenize çekin."]', 'plyometrics', '["Vertical_Swing/0.jpg", "Vertical_Swing/1.jpg"]', 480.0, 'Vertical Swing', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d51863ab-a97e-574b-9c28-1d292af781f1', 'free-exercise-db', 'Walking_Treadmill', 'Koşu Bandında Yürüyüş', NULL, 'beginner', NULL, '["machine"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Başlamak için koşu bandına çıkın ve menüden istediğiniz seçeneği seçin. Çoğu koşu bandında manuel bir ayar vardır veya koşmak için bir program seçebilirsiniz. Genellikle egzersiz sırasında yakılan kaloriyi tahmin etmek için yaşınızı ve kilonuzu girebilirsiniz. Antrenmanın yoğunluğunu değiştirmek için eğim ayarlanabilir.", "Koşu bantları kolaylık, kardiyovasküler faydalar sunar ve genellikle dışarıda yürümeye göre daha az darbe yapar. Yürürken rahat değil, orta ile hızlı arası bir tempoda hareket etmelisiniz. Düşük yoğunluklu bir aktivite olduğu için yürüyüş bazı diğer aktiviteler kadar kalori yakmaz, ancak yine de harika fayda sağlar. 68 kg ağırlığındaki bir kişi saatte 6,4 km hızla 30 dakika yürüyerek yaklaşık 175 kalori yakarken, iki kat hızlı koşuda 450 kalori yakar. Yürürken doğru duruşu koruyun ve saplara yalnızca inerken veya kalp atış hızınızı kontrol ederken gibi gerektiğinde tutunun."]', 'cardio', '["Walking_Treadmill/0.jpg", "Walking_Treadmill/1.jpg"]', 600.0, 'Walking, Treadmill', FALSE, NULL, TRUE, 'duration_distance', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('439db195-dfa9-57a5-93ce-6c610a2b409c', 'free-exercise-db', 'Weighted_Ball_Hyperextension', 'Hyperextension (Egzersiz Topu, Ağırlıklı)', 'pull', 'intermediate', 'compound', '["exercise ball"]', '["lower back"]', '["glutes", "hamstrings", "middle back"]', '["Başlamak için gövdeniz topa bastırılmış ve yere paralel olacak şekilde bir egzersiz topunun üzerine uzanın. Dengede kalmanıza yardımcı olması için ayaklarınızın ön kısmı yere bastırılmalıdır. Bir ağırlık plakasını çenenizin altına veya boynunuzun arkasına yerleştirin. Bu başlangıç pozisyonudur.", "Belinizden ve alt sırtınızdan bükülerek gövdenizi yavaşça yukarı kaldırın. Bu hareket sırasında nefes vermeyi unutmayın.", "Alt sırtınızdaki kasılmayı bir saniye tutun ve nefes alırken gövdenizi başlangıç pozisyonuna geri indirin.", "Programınızda belirtilen önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Weighted_Ball_Hyperextension/0.jpg", "Weighted_Ball_Hyperextension/1.jpg"]', 360.0, 'Weighted Ball Hyperextension', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('77449f8e-26d6-5f6b-8ea5-ef50a9ec338d', 'free-exercise-db', 'Weighted_Ball_Side_Bend', 'Yan Eğilme (Egzersiz Topu, Plaka)', 'pull', 'intermediate', 'isolation', '["exercise ball"]', '["abdominals"]', '[]', '["Başlamak için gövdenizin sol tarafı (bel, kalça ve omuz) topa bastırılmış şekilde bir egzersiz topunun üzerine uzanın.", "Ayaklarınız yerde, bacaklarınız çapraz ve toptan sarkıyor olmalıdır. Ağırlık plakasını sağ elinizle başınızın hemen sağ tarafında tutun. İpucu: Plakanın düz tarafının başınıza dayandığından emin olun.", "Sol kolunuzu gövdenizin üzerinden çaprazlayın, böylece avuç içiniz yan karın kaslarınızın (oblique) üzerinde olsun. Sol ön kolunuz ve üst kolunuz arasında dik açı olmalıdır. Bu başlangıç pozisyonudur.", "Nefes verirken belden yana bükülerek gövdenizin yan tarafını yukarı kaldırın.", "Kasılmayı bir saniye tutun ve nefes alırken yavaşça başlangıç pozisyonuna inin.", "Önerilen tekrar sayısı kadar tekrarlayın.", "Taraf değiştirin ve egzersizi tekrarlayın."]', 'strength', '["Weighted_Ball_Side_Bend/0.jpg", "Weighted_Ball_Side_Bend/1.jpg"]', 360.0, 'Weighted Ball Side Bend', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b79f3f9d-099a-5eb2-9e52-852b7be932db', 'free-exercise-db', 'Weighted_Bench_Dip', 'Bank Dips (Ağırlıklı, Dambıl)', 'push', 'intermediate', 'compound', '["other"]', '["triceps"]', '["chest", "shoulders"]', '["Bu egzersiz için sırtınızın arkasına bir bank ve önünüze başka bir bank yerleştirmeniz gerekir. Bankalar vücudunuza dik olacak şekilde, ellerinizi vücudunuza yakın ve omuz genişliğinde açık tutarak bir bankın kenarını tutun. Kolunuz tamamen uzatılmış olmalıdır.", "Bacaklar öne doğru diğer bankın üzerine uzatılacaktır. Bacaklarınız yere paralel, gövdeniz ise yere dik olmalıdır. Partnerinizin dambılı kucağınıza koymasını sağlayın. Not: Bu egzersiz en iyi partnerle yapılır; çünkü ağırlığı kucağınıza koymak yardım olmadan zor olabilir ve sakatlanmaya neden olabilir. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken dirseklerinizi bükerek, üst kol ile ön kol arasında 90 dereceden biraz küçük bir açı oluşana kadar vücudunuzu yavaşça indirin. İpucu: Hareket boyunca dirsekleri olabildiğince yakın tutun. Ön kollar her zaman aşağıyı göstermelidir.", "Gövdenizi tekrar yukarı getirmek için triceps''i kullanarak nefes verirken kendinizi başlangıç pozisyonuna kaldırın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Weighted_Bench_Dip/0.jpg", "Weighted_Bench_Dip/1.jpg"]', 360.0, 'Weighted Bench Dip', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('78d4ef24-4dc5-5b81-9742-e3a4040f9963', 'free-exercise-db', 'Weighted_Crunches', 'Ağırlıklı Mekik', 'pull', 'beginner', 'isolation', '["medicine ball"]', '["abdominals"]', '[]', '["Ayaklarınız yerde düz veya dizleriniz 90 derece bükülü şekilde bir sehpanın üzerinde dinlenirken sırtüstü düz uzanın.", "Bir ağırlığı göğsünüze doğru tutun veya gövdenizin üzerinde uzatarak tutabilirsiniz. Bu sizin başlangıç pozisyonunuzdur.", "Şimdi nefes verin ve omuzlarınızı yavaşça yerden kaldırmaya başlayın. Alt belinizin yerde kalması şartıyla omuzlarınız yerden yaklaşık 4 inç (10 cm) kalkmalıdır.", "Hareketin üst noktasında karın kaslarınızı kasın ve kısa bir süre bekleyin.", "Ardından nefes alın ve kendinizi yavaşça başlangıç pozisyonuna indirin."]', 'strength', '["Weighted_Crunches/0.jpg", "Weighted_Crunches/1.jpg"]', 360.0, 'Weighted Crunches', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('f59cfe2a-8ba0-5d25-9eef-c0d205bb436d', 'free-exercise-db', 'Weighted_Jump_Squat', 'Ağırlıklı Jump Squat', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Hafif yüklü bir halteri omuzlarınızın arkasına yerleştirin. Bu egzersiz için ağırlıklı yelek, kum torbası veya başka türde bir direnç de kullanabilirsiniz.", "Ağırlık, sizi belirgin şekilde yavaşlatmayacak kadar hafif olmalıdır. Ayaklarınız omuz genişliğinin hemen dışında, başınız ve göğsünüz yukarıda olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Karşı hareket (countermovement) kullanarak kısmen çömelin ve hemen yönü tersine çevirerek kalçanızı, dizlerinizi ve ayak bileklerinizi açıp yerden patlayıcı şekilde sıçrayın. Zıplama boyunca iyi bir duruşu koruyun.", "Yere dönerken darbeyi bacaklarınızla sönümleyin."]', 'strength', '["Weighted_Jump_Squat/0.jpg", "Weighted_Jump_Squat/1.jpg"]', 360.0, 'Weighted Jump Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c3d6d9f0-a4be-5fa5-b5ad-21f982eb316b', 'free-exercise-db', 'Weighted_Pull_Ups', 'Barfiks (Ağırlıklı)', 'pull', 'intermediate', 'compound', '["other"]', '["lats"]', '["biceps", "middle back"]', '["Bir ağırlığı dip kemerine takın ve belinize sabitleyin. Barfiks barını avuç içleriniz öne bakacak şekilde kavrayın. Orta tutuş için elleriniz omuz genişliğinde açık olmalıdır. Her iki kolunuz da önünüzde, barı seçilen tutuşta tutarak uzatılmış olmalıdır.", "Gövdenizi yaklaşık 30 derece geriye getirirken alt sırtınızda bir kavis oluşturmak ve göğsünüzü dışarı çıkarmak isteyeceksiniz. Bu sizin başlangıç pozisyonunuz olacaktır.", "Şimdi nefes verin ve başınız ellerinizin üzerine çıkana kadar gövdenizi yukarı çekin. Üst kasılmış pozisyona ulaşırken kürek kemiklerinizi geriye ve aşağıya doğru sıkmaya odaklanın.", "Üst kasılmış pozisyonda kısa bir an bekledikten sonra, nefes alın ve kollarınız uzatılmış ve latissimus kaslarınız tamamen esnemiş halde gövdenizi yavaşça başlangıç pozisyonuna geri indirin."]', 'strength', '["Weighted_Pull_Ups/0.jpg", "Weighted_Pull_Ups/1.jpg"]', 360.0, 'Weighted Pull Ups', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d685d0c3-5fcb-5965-96f4-aa7ed958a30d', 'free-exercise-db', 'Weighted_Sissy_Squat', 'Sissy Squat (Ağırlıklı)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Ayaklarınız omuz genişliğinde ve ayak parmaklarınız yukarıda olacak şekilde dik dururken, bir elinizle squat rafının kirişlerine tutunun ve karşı kolunuzla göğsünüzün üstünde bir plaka tutun. Bu sizin başlangıç pozisyonunuzdur.", "Bir kolunuzla kendinizi tutarken dizlerinizi bükün ve pelvisinizi ve dizlerinizi öne getirerek gövdenizi yavaşça yere doğru indirin. İnerken nefes alın ve üst ve alt bacaklarınız neredeyse 90 derecelik bir açı oluşturduğunda durun. Esneme pozisyonunu bir saniye tutun.", "Bir saniyelik beklemenin ardından gövdenizi başlangıç pozisyonuna geri getirmek için uyluk kaslarınızı kullanın. Yukarı çıkarken nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Weighted_Sissy_Squat/0.jpg", "Weighted_Sissy_Squat/1.jpg"]', 360.0, 'Weighted Sissy Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d82d1e32-9466-5913-a38e-6de2acae2a28', 'free-exercise-db', 'Weighted_Sit-Ups_-_With_Bands', 'Ağırlıklı Mekik (Direnç Bandı)', 'pull', 'intermediate', 'isolation', '["other"]', '["abdominals"]', '[]', '["Bantları decline bench''in tabanına bağlayarak başlayın. Sapları decline bench''in iç tarafına yerleştirin, böylece uzandığınızda ikisine de ulaşabilirsiniz.", "Bacaklarınızı sabitlenene kadar decline makinesinin içinden geçirin. Şimdi iki elinizle egzersiz bantlarına uzanın. Sapları kavramak için pronasyon (avuç içleri ileri) tutuş kullanın. Bunları köprücük kemiğinizin yakınına konumlandırın ve bileğinizi nötr tutuşa (avuç içleri gövdeye bakacak şekilde) döndürün. Not: Kollarınız egzersiz boyunca sabit kalmalıdır. Bu başlangıç pozisyonudur.", "Nefes verirken üst vücudunuz yere dik olana kadar gövdenizi yukarı hareket ettirin. Kasılmayı bir saniye tutun ve nefes alırken üst vücudunuzu başlangıç pozisyonuna geri indirin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Weighted_Sit-Ups_-_With_Bands/0.jpg", "Weighted_Sit-Ups_-_With_Bands/1.jpg"]', 360.0, 'Weighted Sit-Ups - With Bands', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('63309aa6-54b7-5c8b-91f2-15b2c7826b74', 'free-exercise-db', 'Weighted_Squat', 'Squat (Ağırlık Kemeri, Bench Üzerinde)', 'push', 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["İki düz bench''i omuz genişliğinde aralıklı olacak şekilde yerleştirerek başlayın. Üzerlerine çıkın ve ağırlık kemerini, kendinizi rahat hissettiğiniz miktarda ağırlıkla beline sarın. Ayak parmaklarınızın dışarı baktığından emin olun.", "Ağırlık bacaklarınızın arasında sarkarken dik durduğunuzda, kollarınızı vücudunuzun yanlarında tamamen uzamış olacak şekilde konumlandırın. Bu başlangıç pozisyonudur.", "Başınız yukarıda ve duruşunuz dik kalacak şekilde dizlerinizi bükerek başlayın. Üst bacak ile baldır arasındaki açı 90 dereceden biraz az olana kadar (üst bacakların yere paralelin altında olduğu nokta) inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız dizlerinizin önü, ayak uçlarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizginin ötesine (ayak uçlarınızı geçerek) giderse dizlere gereksiz yük bindirirsiniz ve egzersizi yanlış yapmış olursunuz.", "Bacaklarınızı tekrar düzeltirken esas olarak ayağınızın ön kısmıyla düz bench''in yüzeyini iterek vücudunuzu yukarı hareket ettirmeye başlayın ve başlangıç pozisyonuna dönün. Egzersizin bu kısmında nefes verin.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Weighted_Squat/0.jpg", "Weighted_Squat/1.jpg"]', 360.0, 'Weighted Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d9f5b435-b301-5751-920e-8379fe24990d', 'free-exercise-db', 'Wide-Grip_Barbell_Bench_Press', 'Bench Press (Halter, Geniş Tutuş)', 'push', 'intermediate', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Ayaklarınız yerde sağlam olacak şekilde düz bir sehpaya uzanın. Omuz genişliğinden (her el için) yaklaşık 7-8 cm daha geniş, pronasyon (avuç içleri öne) bir tutuşla barı raftan kaldırın ve kollarınız kilitli şekilde tam üzerinizde tutun. Bar gövdeye ve yere dik olacaktır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken barı orta göğsünüzde hissedene kadar yavaşça indirin.", "Bir saniye bekledikten sonra nefes verirken ve göğüs kaslarınızı kullanarak barı iterek başlangıç pozisyonuna geri getirin. Kollarınızı kilitleyin, kasılmış pozisyonda göğsünüzü sıkın, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İnmek, yukarı çıkmaktan en az iki kat daha uzun sürmelidir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wide-Grip_Barbell_Bench_Press/0.jpg", "Wide-Grip_Barbell_Bench_Press/1.jpg"]', 360.0, 'Wide-Grip Barbell Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a399c880-1b0f-5a5c-b4ba-24a724717495', 'free-exercise-db', 'Wide-Grip_Decline_Barbell_Bench_Press', 'Decline Bench Press (Halter, Geniş Tutuş)', 'push', 'intermediate', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Ayaklarınız bankın ön kısmında sağlam şekilde kilitlenmiş halde decline bankta uzanın. Omuz genişliğinden (her el için) yaklaşık 3 inç (7-8 cm) daha geniş, pronated (avuç içi öne) bir tutuşla barı raftan kaldırın ve kollarınız kilitli şekilde tam üzerinizde tutun. Bar gövdeye ve yere dik olacaktır. Bu sizin başlangıç pozisyonunuzdur.", "Nefes alırken barı alt göğsünüzde hissedene kadar yavaşça indirin.", "Bir saniye bekledikten sonra, nefes verirken göğüs kaslarınızı kullanarak barı itip başlangıç pozisyonuna getirin. Kollarınızı kilitleyin ve kasılmış pozisyonda göğsünüzü sıkın, bir saniye bekleyin ve ardından tekrar yavaşça inmeye başlayın. İpucu: İnişin yukarı çıkıştan en az iki kat uzun sürmesi gerekir.", "Hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wide-Grip_Decline_Barbell_Bench_Press/0.jpg", "Wide-Grip_Decline_Barbell_Bench_Press/1.jpg"]', 360.0, 'Wide-Grip Decline Barbell Bench Press', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a25ac845-be94-5211-ad92-a1c468460e8b', 'free-exercise-db', 'Wide-Grip_Decline_Barbell_Pullover', 'Decline Pullover (Halter, Geniş Tutuş)', 'pull', 'intermediate', 'compound', '["barbell"]', '["chest"]', '["shoulders", "triceps"]', '["Her iki bacağınız da sağlam şekilde sabitlenmiş halde decline sehpaya uzanın. Pronasyon tutuşla (avuç içleri dışa bakacak şekilde) başınızın arkasındaki halteri kavrayın. Bu egzersiz için halteri omuz genişliğinden daha geniş tuttuğunuzdan emin olun. Halteri kollarınızı kullanarak yerden yavaşça kaldırın.", "Doğru konumlandığınızda kollarınız tamamen uzamış ve yere dik olmalıdır. Bu başlangıç pozisyonudur.", "Halteri yere koyacakmış gibi yarım daire hareketiyle geriye doğru indirmeye başlayın, ancak kollar yere paralel olduğunda durun. İpucu: Kolları her zaman tamamen uzamış tutun. Hareket yalnızca omuz ekleminde gerçekleşmelidir. Hareketin bu kısmında nefes alın.", "Şimdi nefes verirken başlangıç pozisyonuna geri dönene kadar halteri yukarı getirin. Halterin kontrolünü her zaman tamamen elinizde tuttuğunuzu unutmayın.", "Hareketi antrenman programınızın belirttiği tekrar sayısı kadar tekrarlayın.", "Setiniz bittiğinde halteri başınızla aynı seviyeye gelene kadar yavaşça geri indirin ve bırakın."]', 'strength', '["Wide-Grip_Decline_Barbell_Pullover/0.jpg", "Wide-Grip_Decline_Barbell_Pullover/1.jpg"]', 360.0, 'Wide-Grip Decline Barbell Pullover', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b524c72a-c9b4-56d8-8ac5-2d68e98a25f3', 'free-exercise-db', 'Wide-Grip_Lat_Pulldown', 'Lat Pulldown (Geniş Tutuş)', 'pull', 'beginner', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Üst makaraya geniş bir bar takılı bir pulldown makinesine oturun. Makinenin diz pedini boyunuza göre ayarladığınızdan emin olun. Bu pedler, bara bağlı direncin vücudunuzu yukarı kaldırmasını önleyecektir.", "Barı avuç içleri öne bakacak şekilde belirtilen tutuşla kavrayın. Tutuşlar hakkında not: Geniş tutuş için elleriniz omuz genişliğinden daha geniş bir mesafede açılmalıdır. Orta tutuş için elleriniz omuz genişliğine eşit bir mesafede, dar tutuş için ise omuz genişliğinden daha dar bir mesafede olmalıdır.", "Her iki kolunuz da önünüzde, barı seçilen tutuş genişliğinde tutarak uzatılmışken, alt sırtınızda bir kavis oluşturarak ve göğsünüzü dışarı çıkararak gövdenizi yaklaşık 30 derece geriye getirin. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken, omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek barı üst göğsünüze değene kadar aşağı getirin. İpucu: Tam kasılmış pozisyona ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde sabit kalmalı ve sadece kollar hareket etmelidir. Ön kollar barı tutmak dışında başka bir iş yapmamalıdır; bu nedenle barı ön kollarınızla aşağı çekmeye çalışmayın.", "Kasılmış pozisyonda kürek kemiklerinizi birbirine sıkarak bir saniye bekledikten sonra, kollarınız tamamen uzayana ve latissimus kaslarınız tamamen esneyene kadar barı yavaşça başlangıç pozisyonuna geri kaldırın. Hareketin bu kısmında nefes alın.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wide-Grip_Lat_Pulldown/0.jpg", "Wide-Grip_Lat_Pulldown/1.jpg"]', 360.0, 'Wide-Grip Lat Pulldown', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('1e3fdd5f-338f-59ca-b89e-c92bbb59c138', 'free-exercise-db', 'Wide-Grip_Pulldown_Behind_The_Neck', 'Boyun Arkası Lat Pulldown (Geniş Tutuş)', 'pull', 'intermediate', 'compound', '["cable"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Üst makaraya geniş bir bar bağlı olan bir pulldown makinesine oturun. Makinenin diz minderini boyunuza göre ayarladığınızdan emin olun. Bu minderler, vücudunuzun bara bağlı direnç tarafından yukarı kaldırılmasını engeller.", "Barı belirlenen tutuşu kullanarak avuç içleri ileri bakacak şekilde kavrayın. Tutuşlar hakkında not: Geniş tutuş için ellerinizin omuz genişliğinizden daha geniş aralıklı olması gerekir. Orta tutuş için ellerin omuz genişliğine eşit aralıkta, dar tutuş için omuz genişliğinden daha dar aralıkta olması gerekir.", "İki kolunuz seçtiğiniz tutuş genişliğinde barı tutarak önünüzde uzanmışken, gövdenizi ve başınızı öne getirin. Barın merkezinden boynunuzun arkasına doğru inen hayali bir çizgi düşünün. Bu sizin başlangıç pozisyonunuzdur.", "Nefes verirken, omuzlarınızı ve üst kollarınızı aşağı ve geriye çekerek barı boynunuzun arkasına değene kadar aşağı indirin. İpucu: Tam kasılmış pozisyona ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde sabit kalmalı ve sadece kollar hareket etmelidir. Ön kollar barı tutmaktan başka bir iş yapmamalıdır; bu nedenle barı ön kollarınızı kullanarak aşağı çekmeye çalışmayın.", "Kasılmış pozisyonda kürek kemiklerinizi birbirine sıkıştırarak bir saniye bekledikten sonra, kollarınız tamamen uzanıp latissimus kaslarınız tamamen gerilene kadar barı yavaşça başlangıç pozisyonuna kaldırın. Hareketin bu kısmında nefes alın.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wide-Grip_Pulldown_Behind_The_Neck/0.jpg", "Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"]', 360.0, 'Wide-Grip Pulldown Behind The Neck', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ca6ff1aa-e3e9-5a99-bfdd-67da1b8f5c81', 'free-exercise-db', 'Wide-Grip_Rear_Pull-Up', 'Geniş Tutuş Arkadan Barfiks', 'pull', 'intermediate', 'compound', '["body only"]', '["lats"]', '["biceps", "middle back", "shoulders"]', '["Barfiks barını avuç içleri öne bakacak şekilde geniş tutuşla kavrayın.", "Barı tutan her iki kolunuz önünüzde uzanmışken, barfiks barından ensenizin arkasına hayali bir çizgi oluşacak şekilde gövdenizi ve başınızı öne getirin. Bu sizin başlangıç pozisyonunuzdur.", "Bar ensenizin arkasına yaklaşana kadar gövdenizi yukarı çekin. Bunu yapmak için başınızı hafifçe öne eğerken omuzlarınızı ve üst kollarınızı aşağı ve geriye çekin. Hareketin bu kısmında nefes verin. İpucu: Tam kasılmış pozisyona ulaştığınızda sırt kaslarınızı sıkmaya odaklanın. Üst gövde uzayda hareket ederken sabit kalmalı ve yalnızca kollar hareket etmelidir. Ön kollar barı tutmaktan başka iş yapmamalıdır.", "Kasılmış pozisyonda bir saniye bekledikten sonra nefes almaya başlayın ve kollarınız tamamen uzanıp latlarınız tamamen gerilene kadar gövdenizi yavaşça başlangıç pozisyonuna indirin.", "Bu hareketi belirlenen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wide-Grip_Rear_Pull-Up/0.jpg", "Wide-Grip_Rear_Pull-Up/1.jpg"]', 360.0, 'Wide-Grip Rear Pull-Up', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('8fa75f95-3bce-5d4f-8283-4ae26e5359d5', 'free-exercise-db', 'Wide-Grip_Standing_Barbell_Curl', 'Biceps Curl (Halter, Geniş Tutuş)', 'pull', 'beginner', 'isolation', '["barbell"]', '["biceps"]', '[]', '["Gövdeniz dik şekilde, halteri geniş dış sapından tutarak ayakta durun. Avuç içleriniz öne bakmalıdır. Dirsekler gövdeye yakın olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolları sabit tutarak, nefes verirken biceps''i kasarak ağırlıkları öne doğru kıvırın. İpucu: Yalnızca ön kollar hareket etmelidir.", "Biceps''iniz tamamen kasılana ve bar omuz seviyesine gelene kadar harekete devam edin. Kasılmış pozisyonu bir saniye tutun ve biceps''i sert şekilde sıkın.", "Nefes alırken barı yavaşça başlangıç pozisyonuna getirmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wide-Grip_Standing_Barbell_Curl/0.jpg", "Wide-Grip_Standing_Barbell_Curl/1.jpg"]', 360.0, 'Wide-Grip Standing Barbell Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('3db0c236-cde0-5c90-bbb7-2cc19c8ed03d', 'free-exercise-db', 'Wide_Stance_Barbell_Squat', 'Geniş Duruş Squat (Halter)', 'push', 'intermediate', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings", "lower back"]', '["Bu egzersiz güvenlik açısından en iyi squat rafının içinde yapılır. Başlamak için önce barı boyunuza en uygun yükseklikteki rafa yerleştirin. Doğru yükseklik seçilip bar yüklendikten sonra barın altına girin ve omuzlarınızın arkasını (boynun biraz altında) barın üzerine yerleştirin.", "Barı her iki kolunuzla yanlardan tutun ve önce bacaklarınızla iterek, aynı zamanda gövdenizi dikleştirerek raftan kaldırın.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinden geniş bir duruşta, ayak uçları hafifçe dışa bakacak şekilde konumlandırın. Aşağı bakmak dengenizi bozacağından başınızı her zaman yukarıda tutun ve sırtınızı dik tutun. Bu sizin başlangıç pozisyonunuz olacaktır.", "Başınız yukarıda ve duruşunuz dik kalacak şekilde dizlerinizi bükerek barı yavaşça indirmeye başlayın. Üst bacak ile baldır arasındaki açı 90 dereceden biraz az olana kadar (üst bacakların yere paralelin altında olduğu nokta) inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız dizlerinizin önü, ayak uçlarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizginin ötesine (ayak uçlarınızı geçerek) giderse dizlere gereksiz yük bindirirsiniz ve egzersizi yanlış yapmış olursunuz.", "Nefes verirken topuğunuzla yeri iterek, bacaklarınızı tekrar düzeltip başlangıç pozisyonuna dönerek barı kaldırmaya başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wide_Stance_Barbell_Squat/0.jpg", "Wide_Stance_Barbell_Squat/1.jpg"]', 360.0, 'Wide Stance Barbell Squat', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('4a7609fb-8506-5986-8fd9-c3c5d68f8095', 'free-exercise-db', 'Wide_Stance_Stiff_Legs', 'Stiff Leg Deadlift (Halter, Geniş Duruş)', 'pull', 'intermediate', 'compound', '["barbell"]', '["hamstrings"]', '["adductors", "glutes", "lower back"]', '["Yerde yüklenmiş bir halterle başlayın. Geniş bir duruş alın, ardından halteri tutmak için kalçanızdan eğilin. Kalçanız olabildiğince geride ve bacaklarınız neredeyse düz olmalıdır. Sırtınızı düz, başınızı ve göğsünüzü yukarıda tutun. Bu sizin başlangıç pozisyonunuzdur.", "Kalçanızı devreye sokarak ve kolların düz sarkmasına izin vererek kalçanızı öne sürmeye başlayın. Dümdüz ayakta durana kadar devam edin, ardından ağırlığı yavaşça başlangıç pozisyonuna geri indirin. Ardışık tekrarlarda ağırlığın yere değmesi gerekmez."]', 'olympic weightlifting', '["Wide_Stance_Stiff_Legs/0.jpg", "Wide_Stance_Stiff_Legs/1.jpg"]', 420.0, 'Wide Stance Stiff Legs', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b16195bf-65d2-50ad-9881-71d087efd5fc', 'free-exercise-db', 'Wind_Sprints', 'Asılı Diz Çekme (Wind Sprints)', 'pull', 'beginner', 'compound', '["body only"]', '["abdominals"]', '[]', '["Barfiks barından pronated tutuşla asılın. Kollarınız ve bacaklarınız uzatılmış olmalıdır. Bu sizin başlangıç pozisyonunuzdur.", "Bir dizinizi olabildiğince hızlı şekilde yukarı kaldırarak başlayın. Vücudunuzu veya bacaklarınızı sallamayın. 3", "Hareketi hemen tersine çevirin, o bacağı başlangıç pozisyonuna döndürün. Aynı anda karşı dizi olabildiğince yukarı kaldırın.", "Set tamamlanana kadar bacaklar arasında dönüşümlü olarak devam edin."]', 'strength', '["Wind_Sprints/0.jpg", "Wind_Sprints/1.jpg"]', 360.0, 'Wind Sprints', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('5561be13-8f0a-5b2a-8b49-b4eab119055f', 'free-exercise-db', 'Windmills', 'Windmill (Sırtüstü)', 'pull', 'intermediate', NULL, '[]', '["abductors"]', '["glutes", "hamstrings", "lower back"]', '["Kollarınız yanlara uzanmış ve bacaklarınız düz şekilde sırtüstü uzanın. Bu sizin başlangıç pozisyonunuzdur.", "Bir bacağınızı kaldırın ve hızla vücudunuzun üzerinden çaprazlayarak karşı elin yakınında yere dokunmaya çalışın.", "Başlangıç pozisyonuna dönün ve karşı bacakla tekrarlayın. 10-20 tekrar boyunca dönüşümlü devam edin."]', 'stretching', '["Windmills/0.jpg", "Windmills/1.jpg"]', 150.0, 'Windmills', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('41a6bc6e-7d3c-5a3b-ace7-466db6bd3920', 'free-exercise-db', 'Worlds_Greatest_Stretch', 'World''s Greatest Stretch', 'static', 'intermediate', NULL, '[]', '["hamstrings"]', '["calves", "glutes", "quadriceps"]', '["Bu üç bölümlü bir esnemedir. Ön ayağınız yerde düz ve arka ayağınızın parmak uçlarında olacak şekilde öne lunge yaparak başlayın. Dizleriniz bükülü halde, dizinizin neredeyse yere değeceği noktaya kadar çömelin. Gövdenizi dik tutun ve bu pozisyonu 10-20 saniye koruyun.", "Şimdi ön bacağınızla aynı taraftaki kolu dirseği ayağın yanında olacak şekilde yere yerleştirin. Diğer elinizi, esnemenin bu bölümünde sizi desteklemesi için öndeki bacağınıza paralel olacak şekilde yere koyun.", "10-20 saniye sonra ellerinizi ön ayağınızın iki yanına yerleştirin. Ön ayağınızın parmak uçlarını yerden kaldırın ve bacağınızı düzeltin. Bunu yapmak için arka bacağınızın yerini değiştirmeniz gerekebilir. 10-20 saniye bekleyin, ardından tüm diziyi diğer taraf için tekrarlayın."]', 'stretching', '["Worlds_Greatest_Stretch/0.jpg", "Worlds_Greatest_Stretch/1.jpg"]', 150.0, 'World''s Greatest Stretch', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('ee2ca439-1134-5a84-8feb-38b39d5d5a6f', 'free-exercise-db', 'Wrist_Circles', 'Bilek Daireleri', 'pull', 'beginner', 'isolation', '["body only"]', '["forearms"]', '[]', '["Ayaklarınız omuz genişliğinde açık şekilde dik durarak başlayın. Kollarınızı yanlarınıza, tamamen uzamış ve yere paralel, omuzlarınızla eşit hizada bir yüksekliğe kadar kaldırın. İpucu: Gövdeniz ve kollarınız \"T\" harfini oluşturmalıdır. Avuç içleriniz aşağı bakmalıdır. Bu başlangıç pozisyonudur.", "Bilekler dışında tüm vücudunuzu sabit tutarak her iki bileğinizi öne doğru dairesel hareketle döndürmeye başlayın. İpucu: Ellerinizi fırça gibi kullanarak daireler çizmeye çalıştığınızı hayal edin. Bu egzersizi yaparken normal nefes alın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'stretching', '["Wrist_Circles/0.jpg", "Wrist_Circles/1.jpg"]', 150.0, 'Wrist Circles', FALSE, NULL, TRUE, 'bodyweight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('a7a4aa90-438c-56cc-8eeb-29f6fa647537', 'free-exercise-db', 'Wrist_Roller', 'Wrist Roller', 'pull', 'beginner', 'isolation', '["other"]', '["forearms"]', '["shoulders"]', '["Başlamak için wrist roller''ı pronated tutuşla (avuç içleri aşağı bakacak şekilde) tutarak dik durun. Ayaklarınız omuz genişliğinde açık olmalıdır.", "Her iki kolunuzu önünüzde tamamen uzayıp yere paralel olana kadar yavaşça kaldırın. Not: İpin roller''a sarılı olmadığından emin olun. Ön kollar dışında tüm vücudunuz sabit olmalıdır. Bu başlangıç pozisyonudur.", "İpi roller''ın etrafına sararak ağırlığı bara kadar yukarı getirmek için bir seferde bir bileği yukarı doğru hareketle döndürün.", "Ağırlık bara ulaştığında, ağırlık başlangıç pozisyonuna gelene kadar bileği aşağı doğru döndürerek ağırlığı yavaşça aşağı indirmeye başlayın.", "Programınızda belirtilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Wrist_Roller/0.jpg", "Wrist_Roller/1.jpg"]', 360.0, 'Wrist Roller', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('d90166a6-3ab7-5cfa-9f02-5ebc7c0c326a', 'free-exercise-db', 'Wrist_Rotations_with_Straight_Bar', 'Wrist Rotation (Düz Halter)', 'pull', 'beginner', 'isolation', '["barbell"]', '["forearms"]', '[]', '["Halteri avuç içleriniz aşağı bakacak şekilde iki elinizle tutun; eller yaklaşık omuz genişliğinde aralıklı olsun. Bu sizin başlangıç pozisyonunuzdur.", "Her iki elinizi dönüşümlü kullanarak, gazete rulosu yapıyormuş gibi bileği açarak hareketi gerçekleştirin. Tükenene kadar ileri geri dönüşümlü devam edin.", "Bileği bükerek, ters yöne yuvarlayarak hareketi tersine çevirin. Dönüşümlü hareketi tükenene kadar sürdürün."]', 'strength', '["Wrist_Rotations_with_Straight_Bar/0.jpg", "Wrist_Rotations_with_Straight_Bar/1.jpg"]', 360.0, 'Wrist Rotations with Straight Bar', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('56c1cb30-f03e-5e26-a3a4-48689a8c6536', 'free-exercise-db', 'Yoke_Walk', 'Yoke Walk', NULL, 'intermediate', 'compound', '["other"]', '["quadriceps"]', '["abdominals", "abductors", "adductors", "calves", "glutes", "hamstrings", "lower back"]', '["Yoke genellikle bir yoke ekipmanıyla yapılır, ancak bazen buzdolabı veya başka ağır nesnelerle de görülür.", "Ekipmanı omuzlarınızın arkasına yerleştirerek başlayın. Başınız ileri bakar ve sırtınız kavisli şekilde, topuklarınızdan iterek yoke''u kaldırın.", "Kısa ve hızlı adımlar kullanarak olabildiğince hızlı yürümeye başlayın. Yoke''u dengelemek ve yerinde tutmak için yan direklerini tutabilirsiniz. Verilen mesafe boyunca, genellikle 23-30 metre, olabildiğince hızlı devam edin."]', 'strongman', '["Yoke_Walk/0.jpg", "Yoke_Walk/1.jpg"]', 480.0, 'Yoke Walk', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('44084d4e-4ef2-544e-9caf-c6ef7b3846c1', 'free-exercise-db', 'Zercher_Squats', 'Zercher Squat (Halter)', 'push', 'expert', 'compound', '["barbell"]', '["quadriceps"]', '["calves", "glutes", "hamstrings"]', '["Bu egzersizi güvenlik amacıyla squat rafının içinde yapmak en iyisidir. Başlamak için önce barı boyunuza en uygun rafa yerleştirin. Doğru yükseklik belin üstünde ama göğsün altında herhangi bir yer olmalıdır. Doğru yüksekliği seçip barı yükledikten sonra ellerinizi birbirine kilitleyin ve barı kollarınızın üzerine, ön kol ile üst kol arasına yerleştirin.", "Barı ön kollarınızın üzerinde duracak şekilde kaldırın. Barı doğru tutuyorsanız, kollarınız çaprazlanmış ve üzerlerinden bir bar geçiyormuş gibi görünmelidir.", "Raftan uzaklaşın ve bacaklarınızı omuz genişliğinde orta bir duruşla, ayak parmakları hafifçe dışa bakacak şekilde konumlandırın. Aşağı bakmak dengenizi bozacağı için başınızı her zaman yukarıda tutun ve sırtınızı da düz tutun. Bu sizin başlangıç pozisyonunuzdur. (Not: Bu anlatım için genel gelişimi hedefleyen yukarıda tarif edilen orta duruşu kullanacağız; ancak ayak duruşları bölümünde anlatılan üç duruştan herhangi birini seçebilirsiniz.)", "Başınız yukarıda ve duruşunuz dik iken dizlerinizi bükerek barı indirmeye başlayın. Üst bacak ile baldırlar arasındaki açı 90 dereceden biraz küçük oluncaya kadar (üst bacakların yere paralelin altında olduğu nokta) inmeye devam edin. Hareketin bu kısmında nefes alın. İpucu: Egzersizi doğru yaptıysanız dizlerinizin ön kısmı, ayak parmaklarınızla öne dik hayali bir düz çizgi oluşturmalıdır. Dizleriniz bu hayali çizgiyi geçerse (ayak parmaklarınızı geçerse) dize gereksiz yük bindiriyorsunuz ve egzersizi yanlış yapıyorsunuz demektir.", "Ağırlıklı olarak ayağınızın ön tabanıyla yeri iterek bacaklarınızı tekrar düzleştirirken nefes verip barı kaldırmaya başlayın ve başlangıç pozisyonuna dönün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Zercher_Squats/0.jpg", "Zercher_Squats/1.jpg"]', 360.0, 'Zercher Squats', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('b956997c-c1b5-56c3-9a02-34ff5b4a5421', 'free-exercise-db', 'Zottman_Curl', 'Zottman Curl (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Gövdeniz dik şekilde ayakta durun ve her elinizde kol boyu bir dambıl tutun. Dirsekleriniz gövdenize yakın olmalıdır.", "Avuç içlerinin birbirine baktığından emin olun. Bu sizin başlangıç pozisyonunuzdur.", "Üst kolu sabit tutarken nefes verip biceps''i kasarak ağırlıkları kıvırın. Yalnızca ön kollar hareket etmelidir. Bileğiniz supinasyon (avuç içi yukarı) tutuşa sahip olacak şekilde dönmelidir. Biceps''iniz tamamen kasılana ve dambıllar omuz hizasına gelene kadar harekete devam edin.", "Biceps''i sıkarak kasılmış pozisyonda bir saniye bekleyin.", "Şimdi kasılmış pozisyondayken, başparmağınız serçe parmağınızdan daha yukarıda olacak şekilde pronasyon (avuç içi aşağı) tutuşa gelene kadar bileğinizi döndürün.", "Pronasyon tutuşu kullanarak dambılları yavaşça aşağı indirmeye başlayın.", "Dambıllar uyluklarınıza yaklaşırken bileğinizi nötr (avuç içleri vücudunuza bakacak şekilde) tutuşa dönecek şekilde döndürmeye başlayın.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Zottman_Curl/0.jpg", "Zottman_Curl/1.jpg"]', 360.0, 'Zottman Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO exercises (id, source, source_id, name, force, level, mechanic, equipment, primary_muscles, secondary_muscles, instructions, category, images, calories_per_hour, description, is_custom, user_id, shared_with_public, modality, created_at, updated_at) VALUES ('c9939f7a-ed10-5dca-911a-0a1853ae84e2', 'free-exercise-db', 'Zottman_Preacher_Curl', 'Zottman Preacher Curl (Dambıl)', 'pull', 'intermediate', 'isolation', '["dumbbell"]', '["biceps"]', '["forearms"]', '["Her elinize bir dambıl alın ve üst kollarınızı preacher bench''in veya incline bench''in üzerine yerleştirin. Dambıllar omuz yüksekliğinde tutulmalı ve dirsekler bükülü olmalı. Dambılları avuç içleriniz aşağı bakacak şekilde tutun. Bu sizin başlangıç pozisyonunuz olacak.", "Nefes alırken, üst kolunuz uzanıp biceps''iniz tamamen gerilene kadar avuç içleri aşağıdayken dambılları yavaşça indirin.", "Şimdi hareketin en altındayken bileklerinizi, avuç içleri yukarı bakacak şekilde döndürün.", "Nefes verirken, biceps''inizi tamamen kasılana ve dambıllar omuz yüksekliğine gelene kadar kullanarak ağırlıkları yukarı kıvırın. Yine, tam kasılmayı sağlamak için küçük parmağı başparmaktan daha yukarı getirmeniz gerektiğini unutmayın.", "Kasılmış pozisyonda biceps''i bir saniye sertçe sıkın ve bileklerinizi avuç içleri tekrar aşağı bakacak şekilde döndürün.", "Önerilen tekrar sayısı kadar tekrarlayın."]', 'strength', '["Zottman_Preacher_Curl/0.jpg", "Zottman_Preacher_Curl/1.jpg"]', 360.0, 'Zottman Preacher Curl', FALSE, NULL, TRUE, 'weight_reps', now(), now()) ON CONFLICT (id) DO NOTHING;
